P.entries["item:99-year-old-port"] = {n="99-Річний Портвейн",s="99-річний портвейн — надзвичайно рідкісна пляшка витриманого трунку, яку відправили з Буті Бей як особистий подарунок Ґазлоу. Після аварії з вантажем у доках Раджета її вихопив божевільний на прізвисько Скажений Маґґліш і втік у звивисті тунелі біля Печер Стогонів.",h="99-річний портвейн — надзвичайно рідкісна пляшка витриманого трунку, яку відправили з Буті Бей як особистий...",kw={"99-річний портвейн","скажений маґґліш","кранівник бігглфаз","ґазлоу","раджет","печери стогонів"},ang={["class:Rogue"]="Скажений Маґґліш покладається на аматорську скритність, ховаючись у темряві біля Печер Стогонів, але вправний розбійник легко викурить його з тіні."},sec={{t="Розсипаний цінний вантаж",b="Перевозити цінні вантажі через Велике Море завжди ризиковано, але Кранівник Бігглфаз зробив усе значно гірше під час звичайного ранкового розвантаження в Раджеті. Намагаючись упоратися з величезною партією з Буті Бей, гоблін перевантажив свій кран і обвалив на причали цілу гору ящиків. У метушні місцевий дивак — непутящий тип, відомий як Скажений Маґґліш, — вихопив надзвичайно витриману пляшку 99-річного портвейну й чкурнув пагорбами до Печер Стогонів."},{t="Дипломатичний трунок",b="Викрадений портвейн був не простим трунком: його надіслав Барон Ревілґаз із Нападників Чорної Води як шанобливий дипломатичний дарунок Ґазлоу, головному інженерові й володареві Раджета. Втрата такого цінного вантажу загрожувала заробіткові Бігглфаза й неабияк загострила його стосунки з начальником доків. Злодія вистежили до темних зовнішніх гротів печер: він ховається в тіні з нерозкоркованим скарбом, тож докерам доводиться наймати сторонніх найманців, щоб повернути пляшку, перш ніж Ґазлоу дізнається про халепу."}},faq={{q="Кому спершу призначався 99-Річний Портвейн?",a="Пляшку надіслав Барон Ревілґаз, господар Буті Бей, як цінний особистий подарунок Ґазлоу, голові Раджета.",al={"кому призначався портвейн","кому дістанеться портвейн","подарунок ґазлоу"}},{q="Як портвейн опинився в Скаженого Маґґліша?",a="Кранівник Бігглфаз спробував розвантажити більше, ніж міг подужати його кран, і ящики розсипалися по всіх доках Раджета. Скажений Маґґліш скористався метушнею, схопив коштовну пляшку й накивав п'ятами.",al={"як його вкрали","хто вкрав портвейн","халепа в доках"}},{q="Куди Скажений Маґґліш забрав пляшку?",a="Маґґліш утік углиб суходолу через Пустки й засів у скелястих гротах і зовнішніх тунелях, що ведуть до Печер Стогонів.",al={"де скажений маґґліш","де сховано портвейн","місце портвейну"}},{q="Чому Бігглфаз сам не повернув портвейн?",a="Бігглфаз гнався за злодієм аж до порога Печер Стогонів, але так боявся звірів і осквернених друїдів, що кишать у печерах, що навідріз відмовився заходити всередину.",al={"чому бігглфаз не гнався","боягуз кранівник"}}},fp="16,288,24.521.0,18.522.1,50.122.0,42.205.0,39.130.0,48.164.0"}
P.entries["item:a-bloodstained-journal-page"] = {n="Закривавлена Сторінка Щоденника",s="Подертий закривавлений пергамент, який досліджують під час розслідування справи Сталвана Містмантла. Крізь густу кров ще можна розібрати кілька слів, і Командир Алтея Ебонлок просить звірити почерк.",h="Подертий закривавлений пергамент, який досліджують під час розслідування справи Сталвана Містмантла.",kw={"сталван містмантл","сторінка щоденника","даркшир","доказ","почерк","ебонлок"},ang={["faction:Alliance"]="Для захисників королівства цей похмурий документ — доказ, який Нічна Варта Даркшира досліджує під час розслідування."},sec={{t="Похмурий доказ",b="Командир Алтея Ебонлок пильно стереже Даркшир і просить дослідити почерк на цій подертій, забризканій кров'ю сторінці. Попри густу кров, кілька слів лишилися досить розбірливими, щоб Писар Долтрі міг звірити їх із міським реєстром."},{t="Почерк і провина",b="Щоб розвіяти всі сумніви, перш ніж вершити правосуддя, Командир Ебонлок покладається на Писаря Долтрі, що веде реєстр у Ратуші Даркшира. Роки, віддані архіву міських підписів, зробили Долтрі знавцем місцевих почерків. Звіривши закривавлену сторінку з міськими записами, Долтрі остаточно підтверджує, що писав Сталван, — і провину вчителя доведено."}},faq={{q="Що це за Закривавлена Сторінка Щоденника?",a="Це подертий закривавлений аркуш, пов'язаний із розслідуванням справи Сталвана Містмантла. Командир Алтея Ебонлок просить Писаря Долтрі дослідити його почерк.",al={"закривавлена сторінка щоденника","сторінка щоденника сталвана","кривава сторінка"}},{q="Хто може встановити, хто написав цю сторінку?",a="Писар Долтрі з Ратуші Даркшира. Він веде міський реєстр, тож звіряє почерк на сторінці зі старими підписами в архіві й підтверджує, що це рука Сталвана.",al={"хто читає сторінку","щоденник клерка далтрі","хто впізнає почерк"}},{q="Навіщо Алтеї Ебонлок перевіряти цю сторінку?",a="Командир Алтея вже якийсь час стежить за Сталваном і хоче, щоб Писар Долтрі звірив сторінку з міським реєстром. Їй треба встановити, чи писала обидва тексти одна рука.",al={"навіщо алтеї сторінка","навіщо перевіряти почерк"}},{q="Куди веде ця сторінка в розслідуванні?",a="Сторінку несуть до Писаря Долтрі в Даркширі, щоб він звірив почерк із реєстром. Після його перевірки розслідування триває вже з Командиром Ебонлок.",al={"що буде після сторінки","ланцюжок сталвана далі"}}},fp="27,210,24.255.0,21.376.1,39.163.0,36.173.0,50.184.0,47.175.1"}
P.entries["item:a-clue-to-sanders-treasure"] = {n="Підказка до Скарбу Сандерса",s="«Підказка до Скарбу Сандерса» — пошарпаний пергамент, який залишив сумнозвісний пірат капітан Сандерс. Це другий крок у пошуках скарбу, підказки до якого розкидані по кручах і узбережжю Вестфолу.",h="«Підказка до Скарбу Сандерса» — пошарпаний пергамент, який залишив сумнозвісний пірат капітан Сандерс.",kw={"скарб сандерса","капітан сандерс","підказка","вестфол","пірат","пергамент"},sec={{t="Піратська загадка",b="Цей пергамент знаходять, ідучи за першою картою скарбів капітана Сандерса, і він веде далі вглиб Вестфолу. Нашкрябана записка велить шукачеві йти просто на схід від узбережжя й піднятися кручами до головного шляху. Наступну позначку Сандерс сховав у старій бочці біля розсипаних кам'яних решток покинутого димаря — і ця підказка веде шукачів глибше в неспокійні фермерські землі."}},faq={{q="Що це за підказка?",a="Це записка, яку власноруч залишив капітан Сандерс. Вона веде кожного, кому вистачить кмітливості піти його слідом, до ще однієї схованки у Вестфолі.",al={"підказка сандерса","підказка до скарбу сандерса","що таке підказка до скарбу сандерса"}},{q="Куди веде ця підказка?",a="Підказка велить шукачам іти строго на схід, угору прибережними кручами до вестфолського тракту, де біля зруйнованого димаря стоїть старе барило.",al={"куди мені йти","куди веде підказка","місце димаря"}},{q="Хто такий капітан Сандерс?",a="Капітан Сандерс був піратом. Пам'ять про нього живе в схованках зі скарбами й загадках, які він порозкидав узбережжям і полями Вестфолу.",al={"хто такий капітан сандерс","історія сандерса","капітан сандерс"}}},fp="27,219,17.414.0,18.150.0,26.129.0,24.139.0"}
P.entries["item:a-dusty-unsent-letter"] = {n="Запорошений Невідправлений Лист",s="Запорошений Невідправлений Лист — забутий пергамент, знайдений у старій скрині у Вестфолі. Він дає важливий доказ того, що невловимий Сталван Містмантл жив у Мунбруку, перш ніж зник.",h="Запорошений Невідправлений Лист — забутий пергамент, знайдений у старій скрині у Вестфолі.",kw={"запорошений невідправлений лист","сталван містмантл","мунбрук","писар долтрі","даркшир","покинутий дух"},ang={["faction:Alliance"]="Відтворюючи шлях Сталвана, ви допомагаєте Даркширу вести точний облік мандрівників і вигнанців, що блукають людськими поселеннями від Вестфолу до Сутінколісся."},sec={{t="Підказка в пилюці",b="Шукаючи сліди минулого загадкового Сталвана Містмантла, слідчі знаходять цей невідправлений лист, захований у старій скрині в Мунбруку. У міських записах Мунбрука про Сталвана не було ні слова, тож урядники Даркшира сумнівалися, що він там узагалі бував. Цей лист — відсутня ланка, яка підтверджує, що Сталван якийсь час жив у цьому містечку Вестфолу. Та знахідка породжує й зловісні питання: той, хто забирає лист, тривожить мстивого покинутого духа, що з гіркою злобою стереже рештки Сталванового минулого."},{t="Оновлення реєстру",b="Лист, принесений Писареві Долтрі в Ратушу Даркшира, стає вагомим доказом, щоб оновити міський реєстр. Долтрі зауважує, як дивно, що лист так і не відправили, — це натяк на раптові від'їзди й потаємний слід, який Сталван лишив по південних королівствах Альянсу."}},faq={{q="Де знайти цей лист?",a="Лист дістають із покинутої скрині в Мунбруку у Вестфолі — вона схована серед напівзруйнованих будинків, які тепер захопило Братство Дефіас.",al={"де лист","де взяти запорошений невідправлений лист","лист мунбрука"}},{q="Чому лист так і не відправили?",a="Точні причини невідомі, хоча Писар Долтрі вважає це вкрай підозрілим. Схоже, Сталван Містмантл поспіхом утік із Мунбрука або покинув своє листування, перш ніж рушити далі.",al={"чому не відправлений","невідправлений лист сталвана","кому призначався лист"}},{q="Кому треба показати цей лист?",a="Лист слід доставити Писареві Долтрі, який веде міський реєстр у Ратуші Даркшира.",al={"кому віддати лист","лист клерка далтрі","здати лист"}},{q="Чому під час пошуків листа нападає дух?",a="Потривожена скриня викликає покинутого духа, пов'язаного з похмурою спадщиною Сталвана. Він накидається на кожного, хто нишпорить у його забутому житті, і насилає на непроханих гостей виснажливе Прокляття Сталвана.",al={"сумний дух","чому з'являється привид","прокляття сталвана"}}},fp="21,195,18.564.0,21.306.1,27.165.0,30.197.0,29.110.0,41.202.0"}
P.entries["item:a-faded-journal-page"] = {n="Збякла Сторінка Щоденника",s="Збякла Сторінка Щоденника — старий пергамент, знайдений у скрині на другому поверсі відлюдного дому Маршала Гаґґарда в Лісі Елвінн. Вона стає важливою підказкою в розплутуванні темної історії Сталвана Містмантла.",h="Збякла Сторінка Щоденника — старий пергамент, знайдений у скрині на другому поверсі відлюдного дому Маршала...",kw={"сторінка щоденника","маршал гаґґард","сталван містмантл","шинкар смітс","багряний крук","ліс елвінн"},ang={["faction:Alliance"]="Цей забутий запис допомагає розгадати давню, давно прохололу таємницю, яка тривожить мешканців по обидва береги річки між Елвінном і Сутінколіссям."},sec={{t="Пергамент у скрині",b="Цей вивітрений пергамент лишився в старій скрині ще тоді, коли Маршал Гаґґард, вийшовши у відставку, оселився біля східного кордону Лісу Елвінн, — і роками лежав там без руху. Через слабкий зір Гаґґард не міг його прочитати, тож сторінка припадала пилом, доки її не дістали шукачі пригод, що взялися розплутувати легенду про Сталвана Містмантла."},{t="Слід до Даркшира",b="Хоч Гаґґард і не зміг прочитати крихкий текст, він скерував слідчих за річку, до Таверни «Багряний Крук» у Сутінколіссі. Шинкар Смітс, глянувши на сторінку, одразу впізнав характерний почерк — і пов'язав запис у щоденнику з похмурою сагою, що досі не дає спокою цьому краю."}},faq={{q="Де знайти цю Сторінку Щоденника?",a="Сторінку знаходять у скрині на другому поверсі будинку поруч із Маршалом Гаґґардом — у східній частині Лісу Елвінн, біля річки, що відділяє його від Сутінколісся.",al={"де сторінка","де збякла сторінка щоденника","де скриня"}},{q="Чому Маршал Гаґґард не міг прочитати сторінку сам?",a="Маршал Гаґґард — старий ветеран, чий зір дуже підупав: він майже сліпий і не може розібрати вицвілі рядки на пергаменті.",al={"чому гаґґард не прочитав","сліпота маршала гаґґарда"}},{q="Хто впізнає почерк на сторінці щоденника?",a="Шинкар Смітс із Таверни «Багряний Крук» у Даркширі одразу впізнає почерк, щойно йому показують сторінку.",al={"хто знає почерк","хто читає сторінку"}},{q="Що охороняє скриню зі сторінкою?",a="Відчинена скриня на горішньому поверсі тривожить ворожого покинутого духа, який нападає на шукачів, перш ніж ті встигнуть спокійно оглянути сторінку.",al={"привид скрині","хто нападає біля скрині"}}},fp="20,215,22.343.0,22.315.1,38.153.0,51.165.0,51.141.0,44.127.0"}
P.entries["item:a-letter-to-grelin-whitebeard"] = {n="Лист до Греліна Вайтбірда",s="Це запечатане послання адресоване Ґреліну Вайтбірду, досвідченому дворфу, що несе службу серед засніжених пустищ Долини Холодного Хребта. Надіслане з гірської столиці, Айронфорджа, воно є рідкісною звісткою з новинами та вказівками, що дісталася далекого прикордоння.",h="Це запечатане послання адресоване Ґреліну Вайтбірду, досвідченому дворфу, що несе службу серед засніжених...",kw={"лист","ґрелін вайтбірд","долина холодного хребта","айронфордж","дун мороґ","депеша","анвілмар"},ang={["race:Dwarf"]="Носити депеші крижаними перевалами Дун Мороґу — основний обов'язок молодих дворфійських горян і новобранців, які лише починають здобувати собі ім'я."},sec={{t="Послання з гори",b="Життя в засніженій улоговині Долини Холодного Хребта може бути самотнім, особливо для тих, хто служить далеко від безпечних стін Анвілмара. Такі листи — життєво важлива ланка, що з'єднує розвідників і вчених у полі із залами Айронфорджа. Пронесене на південь гірськими стежками, послання приносить звістку зі столиці до табору Ґреліна Вайтбірда посеред дикої пустки."}},faq={{q="Хто такий Ґрелін Вайтбірд?",a="Ґрелін Вайтбірд — дворф-розвідник і дослідник, що отаборився на південному сході Долини Холодного Хребта. Новини й накази з Айронфорджа він отримує через гінців з Анвілмара.",al={"ґрелін вайтбірд","хто такий ґрелін","одержувач"}},{q="Звідки прийшов цей лист?",a="Лист вирушив зі столиці дворфів Айронфорджа, а місцевий поштар Долини Холодного Хребта переслав його далі, щоб доставити в поле.",al={"звідки лист","хто надіслав лист","звідки він"}},{q="Що в листі?",a="Це коротка записка від Короля Маґні Бронзбірда. Король не має часу на дрібниці й дає Ґреліну право діяти від його імені та розібратися з тролями, як той вважатиме за потрібне, — особливо якщо знайдеться швидке рішення. Ґрелін тішиться листом: звісток з Айронфорджа він не отримував уже давно.",al={"що в листі","зміст листа","текст листа"}}},fp="29,270,28.367.0,25.210.0,32.165.0,26.286.0"}
P.entries["item:a-mysterious-message"] = {n="Таємниче Послання",s="«Таємниче Послання» — лист, перехоплений у гінця, що мандрував Вестфолом. Адресований змовникам, він дає Народному ополченню незаперечний доказ, що Едвін Венкліф безпосередньо очолює Братство Дефіас.",h="«Таємниче Послання» — лист, перехоплений у гінця, що мандрував Вестфолом.",kw={"таємниче послання","едвін венкліф","братство дефіас","блекнейлз","ґраян стаутмантл","народне ополчення","вестфол"},ang={["class:Rogue"]="Перехоплене послання дає розбійникам змогу зазирнути в те, як підпілля Дефіасу дбає про таємність, якими шляхами ходять його гінці й як воно шифрує свої листи.",["faction:Alliance"]="Для героїв Альянсу, які допомагають Вестфолу, перехоплений документ доводить: заворушення у фермерських землях королівства — не випадковий розбій, а продуманий заколот на чолі з Едвіном Венкліфом."},sec={{t="Перехоплені накази",b="Цей лист ніс гонець, що курсував між осередками Братства Дефіас у Мунбруку, Кар'єрі Золотого Узбережжя й Шахті Джанґолод, і він став переломом у розслідуванні Ґраяна Стаутмантла. Тижнями Народне ополчення підозрювало, що за повстанням розбійників стоїть організоване керівництво, але не мало незаперечних доказів. Перехоплене послання остаточно підтверджує: Едвін Венкліф керує діями братства в усьому краї, спрямовуючи свою мережу через зашифровані ранги й посередників."},{t="Шепіт про Блекнейлза",b="Окрім того, що послання підтверджує верховну владу Венкліфа, воно натякає й на інших учасників змови, зокрема на темну постать на прізвисько «Блекнейлз». Хоч уся підпільна мережа ще прихована, розшифрований документ дає Народному ополченню важіль, щоб схилити на свій бік схоплених злодюжок і знайти справжню твердиню братства."}},faq={{q="Що це послання відкриває Народному ополченню?",a="Послання дає Ґраянові Стаутмантлу незаперечний доказ, що Едвін Венкліф особисто керує діями Братства Дефіас по всьому Вестфолу. Найгірші підозри ополчення щодо того, хто стоїть на чолі розбійників, підтвердилися.",al={"що написано в записці","про що таємниче послання","що в посланні"}},{q="Хто такий Блекнейлз?",a="Блекнейлз — спільник чи агент, якого згадано в перехопленому посланні. Про те, хто він і де переховується, відомо небагато: це одна з темних постатей, що діють глибоко в мережі Дефіас.",al={"хто такий блекнейлз","історія блекнейлза","блекнейлз дефіас"}},{q="Хто носить це послання?",a="Послання несе Посланець Дефіасу, що мандрує курними дорогами Вестфолу між Мунбруком, Кар'єром Золотого Узбережжя та Шахтою Джанґолод і узгоджує дії бандитів.",al={"хто має послання","хто дропає таємниче послання","гонець дефіас"}},{q="Що стається, коли Ґраян Стаутмантл його прочитає?",a="Коли причетність Венкліфа підтверджено, ополчення зосереджується на пошуках штабу Дефіас. Полонений злодій погоджується вивести розвідників просто до таємного сховку в обмін на своє життя.",al={"що буде далі","реакція стаутмантла","після таємничого послання"}}},fp="20,276,18.504.0,22.408.1,54.229.0,18.215.0,25.179.0,46.198.1"}
P.entries["item:a-simple-compass"] = {n="Простий Компас",s="Простий Компас — стара особиста пам'ятка Міського Архітектора Стормвінда, Бароса Алекстона. Схований у маленькій скрині на спаленій родинній садибі у Вестфолі, він нагадує про юність Бароса, ще до того, як той здобув шану в столиці.",h="Простий Компас — стара особиста пам'ятка Міського Архітектора Стормвінда, Бароса Алекстона.",kw={"простий компас","барос алекстон","міський архітектор","хутір алекстона","вестфол","братство дефіас"},ang={["faction:Alliance"]="Допомога Баросові Алекстону з поверненням загубленої пам'ятки показує людську ціну повстання Дефіас: навіть визначні особи Стормвінда втратили родинні домівки через смуту у Вестфолі.",["race:Human"]="Для людей королівства компас символізує різкий контраст між безпечними, позолоченими дворами Стормвінда й покинутим беззаконним прикордонням Вестфолу."},sec={{t="Пам'ятка з дитинства",b="Задовго до того, як Барос Алекстон став майстром-архітектором, що керує великими роботами на Соборній Площі, він ріс, працюючи на родинній фермі у Вестфолі. Простий компас був його першим навігаційним приладом і, мабуть, пробудив у ньому ранній інтерес до геометрії, креслення й відкриттів. Коли Хутір Алекстона став жертвою набігів Братства Дефіас і згорів, компас лишився в міцній скрині серед руїн і вцілів, хоч довколишні поля заполонили розбійники."},{t="Цінність спогадів",b="Батькові Бароса вдалося врятуватися, коли садибу знищили, але забрати з собою родинне майно він не зміг. Майстрові-будівничому, що працює за кам'яними мурами Стормвінда, від цього приладу мало практичної користі, та для його серця компас важить дуже багато. Повернувши компас Баросові, ви подаруєте йому рідкісний, неушкоджений зв'язок зі скромним початком і мирним сільським краєм його дитинства."}},faq={{q="Що таке Простий Компас?",a="Це скромний, зовсім не чарівний кишеньковий компас, що належав Баросу Алекстону, коли той хлопчиком жив на родинному хуторі у Вестфолі.",al={"простий компас","компас алекстона","компас барос"}},{q="Де знайти компас?",a="Він схований у Скрині Алекстона, що стоїть серед згарища Хутора Алекстона, трохи на захід від Сентінел Гілл у Вестфолі.",al={"де знайти компас","де компас","де скриня алекстона"}},{q="Хто хоче повернути цей компас?",a="Компас належить Баросу Алекстону, Міському Архітекторові Стормвінда. Його можна знайти біля ратуші на Соборній Площі.",al={"кому потрібен компас","здати компас","чий компас"}},{q="Чому компас лишився на хуторі?",a="Хутір Алекстона пограбували, спалили й захопили розбійники Дефіас. Батько Бароса мусив тікати, рятуючи життя, і не зміг забрати важкі речі, тож скриня лишилася схованою серед руїн.",al={"чому лишили компас","що сталося з хутором"}}},fp="16,281,18.508.0,17.420.0,25.133.0,29.153.0,32.128.0,44.216.0"}
P.entries["item:a-stack-of-letters"] = {n="Стос Листів",s="Стос Листів — невеликий згорток кореспонденції, що потрапив через гірський перевал до Долини Холодного Хребта. Хоча спершу вважали, що весь він належить Таліну Кінаю, у згортку лежать листи для кількох розвідників, які служать серед крижаної пустки.",h="Стос Листів — невеликий згорток кореспонденції, що потрапив через гірський перевал до Долини Холодного Хребта.",kw={"стос листів","пошта","талін кінай","ґрелін вайтбірд","долина холодного хребта","анвілмар","дун мороґ"},ang={["race:Dwarf"]="Для молодих горян, що починають свій шлях у Долині Холодного Хребта, розносити пошту між засніженими таборами — перше знайомство з суворими дорогами та розкиданими вартовими, які стережуть Дун Мороґ."},sec={{t="Через перевал",b="Діставатися віддалених таборів у суворих горах Дун Мороґу — виснажлива праця, тож поштарі часто покладаються на випадкових подорожніх, аби винести пошту з Анвілмара. Цей згорток листів прибув через перевал для розвідників, що стоять глибше в Долині Холодного Хребта. Хоча його вважали призначеним лише Таліну Кінаю в його таборі біля озера, розбираючи пакунок, знаходиш послання й для інших застав серед снігів, зокрема для горянина Ґреліна Вайтбірда."}},faq={{q="Що в Стосі Листів?",a="У пачці — особисті листи й донесення для дворфів, що несуть службу в Долині Холодного Хребта. Їх вважали адресованими лише Таліну Кінаю біля замерзлого озера, але, перебравши стос, він знаходить щонайменше один лист для Ґреліна Вайтбірда.",al={"що в листах","що у стосі листів","кому листи"}},{q="Хто надсилає ці листи до Долини Холодного Хребта?",a="Листи прийшли перевалом, що веде в Долину Холодного Хребта, дісталися Анвілмара, а там їх передали мандрівникові, готовому доправити їх далі дорогою.",al={"звідки листи","хто надіслав листи"}},{q="Хто отримує листи?",a="Спершу пакунок вручають просто в руки дворфові-розвідникові Таліну Кінаю в його таборі біля замерзлого озера. Переглянувши стос, він знаходить лист, що належить Ґреліну Вайтбірду.",al={"хто отримує листи","кому доставити листи"}}},fp="18,270,16.459.0,36.251.0,44.162.0,25.187.0"}
P.entries["item:a-torn-journal-page"] = {n="Подерта Сторінка Щоденника",s="Подерта Сторінка Щоденника — пошарпаний клапоть пергаменту, знайдений у старому вантажному ящику біля каналів Стормвінда. Це важлива речова підказка до особи й темного минулого Сталвана Містмантла: вона пов'язує похмурі події в Сутінколіссі із записами, що збереглися в Лісі Елвінн.",h="Подерта Сторінка Щоденника — пошарпаний клапоть пергаменту, знайдений у старому вантажному ящику біля каналів...",kw={"подерта сторінка щоденника","сталван містмантл","канали","стормвінд","маршал гаґґард","сутінколісся"},ang={["faction:Alliance"]="Ця сторінка показує, як нерозкриті злочини й забуті записи Стормвінда та Елвінна сягають далеко за їхні межі й не дають спокою знекровленому прикордонню Сутінколісся."},sec={{t="Підказка біля каналів",b="Цей клапоть знайшли на самому дні запечатаного ящика біля каналів Стормвінда — під старими книжками, родинними реліквіями й керамічною вазою, серед забутих особистих речей. Хоч сторінка пошкоджена й затерта, почерк на ній вельми характерний і прямо вказує на минуле Сталвана Містмантла, тож слідчі шукають тих, хто ще міг би впізнати руку, що її писала."},{t="Слідами Містмантла",b="Текст вицвів і погано читається, тож сторінку треба показати тому, хто знається на старих записах королівства. Знахідка веде слідчого зі Стормвінда до Маршала Гаґґарда — літнього офіцера, що живе в Лісі Елвінн. Зір у нього вже не той, але пам'ять досі зберігає цей характерний почерк із попередньої глави трагічної саги Містмантла."}},faq={{q="Де знайти подерту сторінку щоденника?",a="Сторінка лежить у запечатаному ящику біля каналів Стормвінда, під купою забутого хатнього начиння, мисливських трофеїв і старої керамічної вази.",al={"де подерта сторінка щоденника","де знайти подерту сторінку","запечатаний ящик стормвінд"}},{q="З чийого щоденника ця сторінка?",a="Сторінка — частина особистих записів Сталвана Містмантла, колишнього вчителя, чиє темне минуле й раптове зникнення стали предметом розслідування в Сутінколіссі та Лісі Елвінн.",al={"хто написав сторінку","автор подертої сторінки","хто такий сталван"}},{q="Хто може прочитати почерк на подертій сторінці?",a="Маршал Гаґґард — літній, майже сліпий відставний офіцер, що живе біля Лісозаготівельного Табору Східної Долини на сході Лісу Елвінн. Він упізнає манеру письма, яку бачив ще до того, як утратив зір.",al={"кому віднести подерту сторінку","хто читає подерту сторінку","щоденник маршала гаґґарда"}},{q="Чому знахідка сторінки важлива для Сутінколісся?",a="Міська Рада Даркшира складає докупи історію Сталвана Містмантла, щоб докопатися до правди про тривожні події й давно поховані злочини, пов'язані з його ім'ям.",al={"чому сутінколісся цікавить щоденник","зв'язок сталвана із сутінколіссям"}}},fp="19,302,20.446.0,28.370.1,37.176.0,38.191.0,46.204.0,45.175.0"}
P.entries["item:abercrombie-s-crate"] = {n="Ящик Аберкромбі",s="Ящик Аберкромбі — загублений ящик із тендітними інструментами й зібраними травами, що належить дивакуватому відлюдникові Аберкромбі. Він лежить покинутий біля входу до Огрського Кургану Вул'Ґол на півдні Сутінколісся: старого прогнали огри-мародери.",h="Ящик Аберкромбі — загублений ящик із тендітними інструментами й зібраними травами, що належить дивакуватому...",kw={"ящик аберкромбі","аберкромбі","огрський курган вул'ґол","огри","сутінколісся","травництво"},ang={["faction:Alliance"]="Похід у саме серце Огрського Кургану Вул'Ґол по загублені речі відкриває, наскільки зросла загроза чудовиськ на півдні Сутінколісся.",["profession:Herbalism"]="Аберкромбі нібито ходить у найтемніші закутки лісу по рідкісні рослини, тож повернути його ботанічний набір — звична справа для місцевих травників."},sec={{t="Здобич огрів",b="Аберкромбі далеко відійшов від своєї хижі в західному Сутінколіссі, збираючи рослини, і натрапив на ворожу ватагу огрів. Рятуючи життя, старий відлюдник упустив ящик із дорогоцінними інструментами й зібраними травами. Огри затягли його пожитки до своєї твердині — Огрського Кургану Вул'Ґол — і недбало кинули важку скриню біля входу до печери."},{t="Дивний уміст",b="Аберкромбі запевняє, що в ящику лише невинні інструменти й зібрані рослини, але його захоплена й підозріла радість, коли ящик повертають, натякає на щось значно темніше. Обмовившись, відлюдник ледь не дякує «Нек…» — і вчасно прикушує язика. А це породжує тривожні питання: якому ремеслу насправді мали служити ці вкрадені інструменти?"}},faq={{q="Де знайти ящик?",a="Ящик кинуто просто неба біля самого входу до печери в Огрському Кургані Вул'Ґол — таборі огрів на південних пагорбах Сутінколісся.",al={"де ящик","де ящик аберкромбі","ящик вул'ґола"}},{q="Як Аберкромбі його загубив?",a="Аберкромбі збирав трави далеко від дому, коли на нього напала ватага огрів. Без зброї, переляканий до смерті, він кинувся тікати й покинув свої речі, які огри потягли до свого лігва.",al={"як огри отримали ящик","чому ящик в огрів"}},{q="Що всередині ящика?",a="Аберкромбі каже, що там рідкісні трави й особливі інструменти для збору. Однак його дивне збудження та обмовка, коли він отримує ящик, натякають, що всередині можуть бути знаряддя куди зловісніші за звичайні садові ножиці.",al={"що в ящику","що загубив аберкромбі"}},{q="Чому Аберкромбі мало не дякує «Нек-»?",a="Отримавши ящик назад, Аберкромбі вигукує: «Хвала Нек-…» — і поспіхом виправляється, дякуючи шукачеві пригод. Це переконливо свідчить, що його вірність чи вдячність належить некромантії, а не Світлу.",al={"аберкромбі обмовився про нек","що означає дякую нек"}}},fp="19,261,17.387.0,17.355.1,27.151.0,28.200.0,25.239.1,45.223.1"}
P.entries["item:admiral-proudmoore-s-orders"] = {n="Накази Адмірала Праудмура",s="Накази Адмірала Праудмура — письмові бойові плани, здобуті у військ Кул Тірасу, що окопалися на узбережжі Дуротару. Написані ще до поразки Великого адмірала під Терамором, документи окреслюють далекосяжні військові задуми, які й досі загрожують молодій батьківщині орків.",h="Накази Адмірала Праудмура — письмові бойові плани, здобуті у військ Кул Тірасу, що окопалися на узбережжі...",kw={"накази","праудмур","кул тірас","дуротар","тіраґард","вол'джин","орда"},ang={["faction:Horde"]="Ці документи виправдовують тих в Орді, хто твердив, що перемир'я з людьми ніколи не триватиме довго: сили Кул Тірасу мали намір вести війну на винищення з миті висадки.",["race:Troll"]="Для тролів Темного Списа ці накази потрапляють просто до рук їхнього ватажка Вол'джина і підтверджують його давню пораду Траллу: присутність людей на узбережжі лишається безпосередньою небезпекою."},sec={{t="Спадщина ненависті",b="Навіть після загибелі Великого адмірала Дейліна Праудмура під Терамором його експедиційні сили відмовляються здаватися. Здобуті в гарнізоні Лейтенанта Бенедикта у Фортеці Тіраґард, ці тактичні вказівки описують довгострокові маневри та укріплення, покликані підірвати Орду. Накази доводять: наступ Великого адмірала у Дуроторі був не поспішним набігом, а організованою кампанією, розрахованою пережити самого полководця. Для Орди здобуті документи — важливе джерело відомостей про дії Кул Тірасу та можливі підкріплення, що загрожують її кордонам."},{t="Доставка до Фортеці Ґроммаш",b="Усвідомивши стратегічну небезпеку, окреслену в планах, розвідники Орди відправляють здобуті папери просто до Фортеці Ґроммаш в Оргріммарі. Передані ватажкові Вол'джину, який служить радником Вождя Тралла, накази підтверджують давню підозру провідника Темного Списа: людська агресія лишається живою небезпекою. Відомості спонукають провідників Орди готуватися до нових вторгнень уздовж узбережжя."}},faq={{q="Що таке Накази Адмірала Праудмура?",a="Це військові розпорядження, які склав великий адмірал Дейлін Праудмур перед своєю загибеллю в Тераморі. Вони велять воякам Кул Тірасу, що лишилися в Дуротарі, укріпитися на узбережжі й вести війну проти Орди.",al={"накази праудмура","що за накази","накази адмірала"}},{q="Де здобули ці накази?",a="Накази захоплюють у Дуротарі під час боротьби з рештками війська Кул Тірасу, що засіли у Фортеці Тіраґард біля південно-східного узбережжя.",al={"де знайти накази","де накази","хто дропає накази"}},{q="Кому треба показати ці накази?",a="Їх приносять ватажкові Темного Спису Вол'джину, який перебуває у Фортеці Ґроммаш, у Долині Мудрості Оргріммара, поруч із Вождем Траллом.",al={"кому віддати накази","кому потрібні накази","здати накази"}},{q="Чому вояки Кул Тірасу досі воюють у Дуротарі?",a="Хоча адмірал Праудмур поліг у бою, його підлеглі, як-от Лейтенант Бенедикт, і далі віддані його меті — винищити орків. Накази містили заздалегідь розроблені плани, тож гарнізон міг і надалі непокоїти Дуротар навіть без нагляду великого адмірала.",al={"чому люди в дуротарі","чому кул тірас ворожий","даелін мертвий чому воюють"}}},fp="27,299,18.577.0,25.419.1,37.219.0,34.150.0,30.144.0,53.286.0"}
P.entries["item:ados-fragment"] = {n="Уламок Адоса",s="Уламок Адоса — камінь із написом, знайдений на Місці Розкопок Велґара в Багнокраї. Разом із трьома іншими уламками він складає Камінь Ґоаза — прадавню реліквію із загадковими написами титанів.",h="Уламок Адоса — камінь із написом, знайдений на Місці Розкопок Велґара в Багнокраї.",kw={"уламок адоса","камінь ґоаза","шукач велґар","титани","древні боги","багнокрай"},ang={["race:Dwarf"]="Для Ліги Дослідників здобуття реліквій титанів, як-от Уламка Адоса, — ключ до розгадки справжнього походження дворфійського народу та його прадавніх творців."},sec={{t="Частина Каменя Ґоаза",b="Відкопаний у багнистих траншеях Місця Розкопок Велґара, Уламок Адоса — одна з чотирьох утрачених частин, без яких не відновити Камінь Ґоаза. Ще до того, як раптори заполонили розкоп, Шукач Велґар почав перекладати головну табличку — і з'ясував, що написи обриваються на найважливіших місцях. Розкидані уламки — Адос, Модр, Голм і Неру — загубилися серед руїн, сховані в прадавніх скринях і купах землі, довкола яких нишпорять звірі."},{t="Письмо титанів",b="Склавши Уламок Адоса з трьома іншими, Шукач Велґар може розшифрувати повний текст титанів, вирізьблений на Камені Ґоаза. Складений докупи напис згадує величний божественний задум і приречене пророцтво, а зрештою відкриває зловісне проголошення: «Древні Боги... Скуті під Землею». Це відкриття натякає, що в сиву давнину титани ув'язнили первісні сутності під Азеротом."}},faq={{q="Що таке Уламок Адоса?",a="Це відламана частина прадавньої таблиці, відомої як Камінь Ґоаза, яку знайшли на розкопках Велґара в Багнокраї. На ній вирізьблено письмена титанів, що творили світ.",al={"уламок адоса","що таке адос","камінь ґоаз уламок адоса"}},{q="Де знайти уламок?",a="Він закопаний на місці розкопок на схід від Гавані Менетіл у Багнокраї — зазвичай серед прадавніх реліквій чи в пухкій землі, а довкола снують раптори, що пильно стережуть свою територію.",al={"де уламок адоса","місце адоса","як знайти адос"}},{q="Що написано на уламку?",a="Сам по собі уламок неповний. Шукачеві Велґару потрібні ще уламки Модр, Голм і Неру, щоб продовжити переклад таблиці.",al={"текст уламка адоса","що написано на адосі","переклад каменя ґоаз"}},{q="Кому потрібен цей уламок?",a="Шукач Велґар, дворф із Ліги Дослідників, що наглядає за зруйнованими розкопками, шукає його, щоб завершити переклад Каменю Ґоаза.",al={"кому потрібен уламок адоса","здати уламок адоса","велґар адос"}}},fp="13,228,25.475.0,16.417.1,26.177.0,28.173.0,27.154.1,24.132.0"}
P.entries["item:agamand-family-axe"] = {n="Сокира Родини Аґаманд",s="Сокира Родини Аґаманд — родова реліквія, збережена у склепі родини Аґамандів на півночі Галявин Тірісфалю. Колись бойовий символ заможної династії власників млинів, тепер вона потрібна Коулменові Фартінґу, щоб позбавити родину-нежить решток гідності.",h="Сокира Родини Аґаманд — родова реліквія, збережена у склепі родини Аґамандів на півночі Галявин Тірісфалю.",kw={"сокира родини аґаманд","аґаманди","склеп","коулмен фартінґ","реліквія","галявини тірісфалю"},ang={["class:Warrior"]="Родова зброя, збережена у склепі, показує, що рід Аґамандів мав бойові традиції поряд із багатством і зерносховищами.",["race:Undead"]="Для Відступників пограбування реліквій Аґамандів — нутряне зведення рахунків із колишньою аристократією Лордерону, яка впала перед чумою так само легко."},sec={{t="Зброя Аґамандів",b="До Третьої війни династія Аґамандів панувала як заможні землевласники на північних пагорбах Галявин Тірісфалю, утримуючи великі млини й приватний родинний склеп. Сокира Родини Аґаманд спочивала серед родової зброї, похованої разом із покійними патріархами й воїнами, і лишалася цілою на підземних стійках навіть тоді, коли Погибель захопила маєток і вирізала його мешканців."},{t="Злостива відплата",b="Коли Погибель підняла полеглих Аґамандів як безтямних рабів, якими володіє Король-Ліч, їхній колишній слуга Коулмен Фартінґ вижив — у нежитті — з гіркою ненавистю до старих господарів. Фартінґ звинувачує родину у власній загибелі й доручає мандрівникам із Відступників увійти до склепу, зняти зі стійок сокиру, меч, булаву й кинджал і стерти останні сліди спадщини Аґамандів."}},faq={{q="Де знайти Сокиру Родини Аґаманд?",a="Сокира лежить на стійці для зброї в Родинному Склепі Аґамандів, на північній околиці Млинів Аґаманда в північній частині Галявин Тірісфалю.",al={"місце сокири","де сокира","де сокира аґаманд"}},{q="Кому потрібна Сокира Родини Аґаманд?",a="Коулмен Фартінґ, Відступник із Брілла, шукає цю зброю разом із родинними кинджалом, булавою й мечем, щоб позбавити своїх колишніх господарів честі.",al={"кому потрібна сокира","завдання коулмена фартінґа","хто хоче реліквії аґаманд"}},{q="Чому Коулмен Фартінґ ненавидить родину Аґаманд?",a="За життя Фартінґ служив Аґамандам і, за його словами, саме вони спричинили його смерть під час навали Погибелі. Тепер він мститься, грабуючи їхній склеп, поки самі Аґаманди блукають маєтком як безвольні слуги-нежить.",al={"чому фартінґ хоче реліквії","історія коулмена фартінґа","образа фартінґа"}},{q="Чи можна битися Сокирою Родини Аґаманд?",a="Ні. Це родова реліквія, яку забирають лише заради завдання — на доказ того, що родинний склеп сплюндровано.",al={"чи можна одягти сокиру","характеристики сокири"}}},fp="18,264,24.391.0,20.398.0,40.143.0,33.155.0,50.211.0,42.119.0"}
P.entries["item:agamand-family-dagger"] = {n="Кинджал Родини Аґаманд",s="Кинджал Родини Аґаманд — родова реліквія занепалої династії Аґамандів, що лежить на стійках для зброї в їхньому родовому склепі на півночі Галявин Тірісфалю. Коулмен Фартінґ хоче здобути цей клинок разом із рештою родинного арсеналу, щоб позбавити колишніх господарів останків спадщини й честі.",h="Кинджал Родини Аґаманд — родова реліквія занепалої династії Аґамандів, що лежить на стійках для зброї в...",kw={"кинджал родини аґаманд","аґаманди","склеп","коулмен фартінґ","брілл","млини аґаманда"},ang={["class:Rogue"]="Прослизнути повз піднятих мерців у склепі й поцупити зі стійок цінні родинні клинки — класична крадіжка зі світу злочинців, обернена на акт холодної помсти.",["race:Undead"]="Реліквії Аґамандів утілюють гірку прірву між уцілілими Відступниками Лордерону та їхніми колишніми господарями, що впали в безтямне рабство Погибелі."},sec={{t="Спадщина у склепі",b="До Третьої війни родина Аґамандів тримала великі маєтки й зернові млини на пагорбистих луках Галявин Тірісфалю. Як і решта зброї їхнього роду, Кинджал Родини Аґаманд пережив спустошення, яке принесла Погибель, замкнений у родинному склепі на північ від Млинів Аґаманда. Під охороною неспокійних решток-нежиті з домочадців і безтямних прислужників, якими командує Король-Ліч, кинджал уособлює престиж і бойову спадщину, що колись підносили родину над слугами й орендарями."},{t="Злостива вимога",b="Для Коулмена Фартінґа — одного з Відступників, що мешкає у Бріллі й загинув на службі в Аґамандів, — клинок означає гірку образу, а не шляхетний родовід. Вважаючи родину прямо винною у своїй смерті, Фартінґ посилає шукачів пригод до Родинного Склепу Аґамандів забрати кинджал разом із родинним мечем, сокирою й булавою. Виносячи цю родову зброю з гробниці, Фартінґ прагне відібрати в патріархів, що стали Погибеллю, останні крихти гідності й подбати, щоб пам'ять про Аґамандів згасла цілком."}},faq={{q="Що таке Кинджал Родини Аґаманд?",a="Це родова зброя заможної родини Аґаманд із Галявин Тірісфалю. Його поклали разом з іншою зброєю в родинний склеп, який згодом захопила Погибель.",al={"кинджал аґаманд","що таке кинджал аґаманд","родинний кинджал тирисфаль"}},{q="Де знайти Кинджал Родини Аґаманд?",a="Він лежить на стійці для зброї Аґамандів глибоко в Родинному Склепі Аґамандів, на північному краї Млинів Аґаманда в Галявинах Тірісфалю.",al={"де знайти кинджал аґаманд","місце кинджала аґаманд","стійка зі зброєю кинджал"}},{q="Навіщо Коулменові Фартінґу цей кинджал?",a="За життя Коулмен Фартінґ служив Аґамандам і звинувачує їх у своїй смерті. Він вимагає кинджал та інші реліквії, щоб позбавити колишніх господарів честі й довершити їхній занепад.",al={"навіщо фартінґу кинджал","завдання фартінґа аґаманд","чому грабувати склеп аґаманд"}},{q="Яка ще зброя входить до цього набору реліквій?",a="Окрім кинджала, до набору входять Меч Родини Аґаманд, Сокира Родини Аґаманд і Булава Родини Аґаманд — усі розкладені по стійках для зброї в родинному склепі.",al={"інші реліквії аґаманд","список зброї аґаманд","що ще в склепі"}}},fp="21,305,21.520.0,22.524.0,34.194.0,41.139.0,43.193.0,47.181.0"}
P.entries["item:agamand-family-mace"] = {n="Булава Родини Аґаманд",s="Булава Родини Аґаманд — родова реліквія, збережена в Родинному Склепі Аґамандів на півночі Галявин Тірісфалю. Колись символ гордості заможної династії північного Лордерону, вона стала предметом злостивої відплати, якої прагне їхній колишній слуга Коулмен Фартінґ.",h="Булава Родини Аґаманд — родова реліквія, збережена в Родинному Склепі Аґамандів на півночі Галявин Тірісфалю.",kw={"булава родини аґаманд","аґаманди","склеп","коулмен фартінґ","помста","галявини тірісфалю"},ang={["race:Undead"]="Осквернення склепів Аґамандів показує, як задавнені смертні образи й кривди часто штовхають Відступників зводити рахунки з часів життя."},sec={{t="Спадщина в руїнах",b="До Третьої війни родина Аґамандів володіла великими угіддями й вітряками на півночі Галявин Тірісфалю. Як і решта місцевої аристократії, вони впали перед чумою нежиті. Аґамандів підняли безтямними рабами, якими володіє Король-Ліч, і тепер вони блукають зруйнованим маєтком, тоді як їхні давні родинні скарби лишилися замкнені в глибинах родового склепу. Серед цієї зброї зберігається й Булава Родини Аґаманд — емблема забутого роду, що перетворився на безтямну Погибель."},{t="Помста слуги",b="Булава — одна з чотирьох бойових реліквій, на які націлився Коулмен Фартінґ, колишній найманий працівник, що звинувачує родину у своїй загибелі під час падіння Лордерону. Воскреслий у лавах Відступників, Фартінґ прагне позбавити безтямних Аґамандів кожної крихти гідності й честі. Здобувши булаву разом із родовими мечем, сокирою й кинджалом, Фартінґ хоче назавжди стерти пам'ять і гордість колишніх господарів із земель, якими вони колись правили."}},faq={{q="Де знайти Булаву Родини Аґаманд?",a="Булава зберігається на стійці для зброї в Родинному Склепі Аґамандів, на далекому північному краї Млинів Аґаманда в Галявинах Тірісфалю.",al={"де булава","місце булави аґаманд","знайти булаву аґаманд"}},{q="Кому потрібна Булава Родини Аґаманд?",a="Коулмен Фартінґ, Відступник, що живе в Бріллі, вимагає булаву разом з іншими родинними реліквіями, щоб звести давні рахунки з колишніми господарями.",al={"кому потрібна булава","хто бере булаву аґаманд","реліквія коулмена фартінґа"}},{q="Навіщо Коулменові Фартінґу викрадати реліквії?",a="Фартінґ служив Аґамандам за життя й прямо звинувачує їх у своїй смерті. Забрати з їхнього склепу найцінніше — так він стирає останні сліди честі цієї родини.",al={"чому красти реліквії","мотив коулмена фартінґа","чому ненавидіти аґаманд"}},{q="Що сталося з родиною Аґаманд?",a="Родина Аґаманд володіла заможними Млинами Аґаманда на півночі Лордерону, доки на неї не впала чума. Тепер їхні підняті трупи блукають маєтком і склепами як безвольні раби Погибелі.",al={"хто такі аґаманди","що сталося з аґамандами","історія аґаманд"}}},fp="19,284,16.528.0,21.482.1,41.137.0,34.153.0,52.186.0,36.205.0"}
P.entries["item:agamand-family-sword"] = {n="Меч Родини Аґаманд",s="Меч Родини Аґаманд — потьмянілий родовий клинок, що зберігається в Родинному Склепі Аґамандів на півночі Галявин Тірісфалю. Колись горда ознака заможної династії власників млинів, тепер він потрібен Коулменові Фартінґу з Відступників, щоб стерти останні сліди спадщини колишніх господарів.",h="Меч Родини Аґаманд — потьмянілий родовий клинок, що зберігається в Родинному Склепі Аґамандів на півночі...",kw={"меч родини аґаманд","аґаманди","склеп","коулмен фартінґ","помста","брілл","тірісфаль"},ang={["class:Warrior"]="Колись начищена емблема аристократії Лордерону, тепер клинок лежить занедбаний у неосвяченій гробниці — пам'ятка зруйнованої бойової гордості.",["race:Undead"]="Для Відступників повернення реліквій колишньої знаті Тірісфалю — зведення рахунків із живим минулим, що не зуміло їх захистити."},sec={{t="Спадщина в гробниці",b="До Третьої війни династія Аґамандів мала величезне багатство й вплив серед млинів на півночі Галявин Тірісфалю. Коли Погибель прокотилася Лордероном, родина загинула страшною смертю, а їхні тіла підняв безтямними рабами Король-Ліч. Їхню родову зброю, зокрема й церемоніальний родинний меч, замкнули в Родинному Склепі Аґамандів на північному краю млинів. Зняти ці клинки з поховальних стійок — не просто грабунок, а свідомий акт, що має зламати будь-яку пам'ять і шляхетне становище, які ще лишилися в полеглого дому."},{t="Помста з-за могили",b="Меча жадає Коулмен Фартінґ — один із Відступників, що мешкає у Бріллі, а за життя працював на Аґамандів. Фартінґ плекає гірку образу на колишніх господарів, звинувачуючи їхні рішення у своїй смерті під час падіння королівства. Посилаючи шукачів пригод по меч разом із родовими сокирою, кинджалом і булавою, Фартінґ прагне відібрати в шкутильгаючих Аґамандів останню крихту честі й подбати, щоб гідність їхнього роду згасла дощенту."}},faq={{q="Що таке Меч Родини Аґаманд?",a="Це родова зброя Аґамандів — знатної родини, що до падіння Лордерону володіла величезними млинами на півночі Галявин Тірісфалю.",al={"історія меча аґаманд","що таке меч родини аґаманд"}},{q="Де знайти меч?",a="Меч лежить на стійці для зброї в Родинному Склепі Аґамандів, на північному краї Млинів Аґаманда в Галявинах Тірісфалю. Його стережуть раби Погибелі та підняті з мертвих члени роду Аґаманд.",al={"де меч аґаманд","місце меча аґаманд"}},{q="Навіщо Коулменові Фартінґу цей меч?",a="За життя Коулмен Фартінґ служив родині Аґаманд і звинувачує її у своїй передчасній смерті. Він шукає родову зброю, щоб відібрати в Аґамандів рештки честі й стерти пам'ять про їхній рід.",al={"кому потрібен меч","чому фартінґ хоче реліквії"}},{q="Що сталося з родиною Аґаманд?",a="Аґамандів вирізали під час навали Погибелі на Лордерон. На відміну від вільних Відступників, загиблі члени родини лишаються безвольними слугами Короля-Ліча й блукають своїм родовим маєтком і склепом.",al={"хто такі аґаманди","історія млинів аґаманда"}}},fp="20,282,20.584.0,31.472.1,33.175.0,27.203.0,42.213.0,36.230.0"}
P.entries["item:ahanu-s-leather-goods"] = {n="Шкіряні Вироби Аану",s="«Шкіряні Вироби Аану» — зв'язаний пакунок готових шкіряних обладунків і припасів, виготовлених на столових горах Тандер Блафа. Його приготував шкірник Агану, а вирушає він на Перехрестя в Пустках, щоб забезпечити мандрівних мисливців і шукачів пригод.",h="«Шкіряні Вироби Аану» — зв'язаний пакунок готових шкіряних обладунків і припасів, виготовлених на столових...",kw={"шкіряні вироби аану","агану","тандер блаф","перехрестя","джахан гоквінг","вітрокрили","торгівля"},ang={["race:Tauren"]="Ця доставка показує, як розростається торгова мережа, що поєднує прабатьківщину тауренів Малгор із ширшими володіннями Орди в Пустках."},sec={{t="Торгівля між столовими горами",b="Шляхи постачання Орди тримаються на практичній торгівлі між укріпленими твердинями й прикордонними заставами. У Тандер Блафі майстер Агану обробляє сирі шкури, перетворюючи їх на готовий одяг і спорядження, і цей вантаж він підготував саме для торгівлі за межами Малгору. Пакунок призначено Джахану Гоквінгу — торговцеві, що працює в самому гамірному серці Пусток, на Перехресті. Подорож суходолом через рівнини повільна, тож доставка пакунка знайомить гінців із повітряною поштою, яку підтримують таурени: товари швидко переносять на великі відстані навчені вітрокрили Тала й Деврака."}},faq={{q="Що в пакунку Шкіряні Вироби Аану?",a="У пакунку — готові шкіряні вироби, які Агану в Тандер Блафі зробив із сирих шкур. Це практичні обладунки й спорядження, готові до продажу мандрівникам.",al={"що за шкіряні вироби","вміст пакунка аану","що в пакунку"}},{q="Хто отримує цей пакунок?",a="Пакунок доставляють Джахану Гоквінгу на Перехресті. Він продає готові товари мисливцям, воїнам і шукачам пригод, які юрбами проходять через центральні Пустки.",al={"хто отримує шкіряні вироби","куди це віднести","доставка шкіри джахану"}},{q="Чому цей пакунок відправляють на вітрокрилі?",a="Нести важкий крам пішки, спускатися підйомниками й перетинати Пустки — довга справа. Агану посилає кур'єрів до майстра вітрокрилів Тандер Блафа, Тала, щоб показати, як швидко крилаті перевізники доправляють вантажі до віддалених застав на кшталт Перехрестя.",al={"чому пакунок летить","доставка вітрокрилом громове урвище","майстер польотів пакунок"}}},fp="21,262,22.627.0,37.172.0,25.174.0,41.251.0"}
P.entries["item:alaric-s-remains"] = {n="Останки Аларіка",s="Останки Аларіка — викопані кістки людини, колись похованої в неглибокій могилі в Срібноліссі. Його неспокійний дух просить мандрівників пронести те, що від нього лишилося, повз гнилошкірих гнолів до веж Фортеці Фенріс.",h="Останки Аларіка — викопані кістки людини, колись похованої в неглибокій могилі в Срібноліссі.",kw={"останки аларіка","аларік","фортеця фенріс","острів фенріс","срібнолісся","гнилошкірі гноли","тул рейвенклов"},ang={["class:Mage"]="Схованка, яку відкриває Аларік, містить реліквії, пов'язані з Тулом Рейвенкловом і вишколеними в Даларані чародіями, що колись вивчали магію й плели змови у Фортеці Фенріс.",["race:Undead"]="Мандрівники-Відступники часто співчувають духам, чий смертний спочинок порушили, хоч Аларік шукає мирної самоти, а не служби Темній Леді."},sec={{t="Останнє прохання",b="Ці останки, викопані з непримітної неглибокої могили в Срібноліссі, належать Аларікові — колишньому мешканцеві Острова Фенріс. Його дух не хоче лишатися у відкритій ямі й прагне туди, де йому було любо за життя. Він просить того, хто викопає його кістки, лишити його незручні чоботи, а сам кістяк віднести просто до фортеці — у тихий притулок, подалі від падальників, що нишпорять на суходолі."},{t="Ніша у фортеці",b="Аларік веде свого носія до південно-західної вежі Фортеці Фенріс — повз заполонені нижні подвір'я в тиху кімнату. За запорошеною полицею схована ніша з артефактом, який колись цінували Тул Рейвенклов і його товариші-маги. Тим, хто приніс його кістки додому й дав йому спокійне місце спочинку, недоступне для ненажерливих гнилошкірих гнолів, Аларік віддає сховані дрібнички."}},faq={{q="Хто такий Аларік?",a="Аларік жив у Фортеці Фенріс ще до її занепаду й провів у її залах, як сам вважав, найкращі дні свого життя. Після смерті його поспіхом поховали в неглибокій могилі в Срібноліссі, аж поки його дух не попросив перехожого віднести кістки додому.",al={"хто такий аларік","історія аларіка","хто був цей чоловік"}},{q="Куди слід віднести останки Аларіка?",a="Їх треба покласти в приховану нішу за запорошеною полицею в південно-західній вежі Фортеці Фенріс, що на Острові Фенріс.",al={"куди нести аларіка","місце запорошеної полиці","де ніша"}},{q="Чому Аларік хоче, щоб його останки сховали за полицею?",a="За життя Фортеця Фенріс давала йому велику втіху, і він хоче спочивати в її кам'яних стінах, а не в земляній канаві. Щільно закрита ніша ще й убереже його скелет від гнилошкірих гнолів, що никають фортецею, — щоб ті його не зжерли й не осквернили.",al={"чому феніс зберігає","чому ніша","чому ховати тіло"}},{q="Чому він сказав залишити його чоботи?",a="Пояснюючи, як дістати його кістки з неглибокої могили, Аларік мимохідь зауважив, що чоботи й за життя йому не пасували, — тож їх можна лишити як непотріб.",al={"залишити чоботи","чоботи аларіка","чоботи ніколи не пасували"}},{q="Що, крім місця спочинку, є в прихованій ніші?",a="У таємній ніші зберігається річ, яку колись цінували Тул Рейвенклов і його колишні спільники, а також чарівні пожитки, які Аларік охоче заповідає тому, хто віднесе його останки на спочинок.",al={"скарб прихованої ніші","що за полицею","річ тула"}}},fp="16,237,15.426.0,22.424.1,15.280.0,42.146.0,55.256.0,41.171.0,57.194.0"}
P.entries["item:alien-egg"] = {n="Чужорідне Яйце",s="Чужорідне Яйце — незвичайна й загадкова кладка, яку стережуть місцеві вітряні змії в каньйонах Тисячі Голок. Попри незнайомий вигляд, змії люто оберігають яйце, наче власне. Воно збудило цікавість і тривогу розвідників-тауренів, що несуть варту на Заставі Вільного Вітру.",h="Чужорідне Яйце — незвичайна й загадкова кладка, яку стережуть місцеві вітряні змії в каньйонах Тисячі Голок.",kw={"чужорідне яйце","арікара","вітряні змії","застава вільного вітру","гаґар лайтнінггуф","тисяча голок"},ang={["class:Hunter"]="Вітряні змії — одні з найшанованіших звірів у пустищах Калімдору, і вистежити одну з їхніх найрідкісніших і найпильніше стережених кладок — випробування для кожного мисливського чуття.",["race:Tauren"]="Таурени Застави Вільного Вітру невсипно пильнують каньйон унизу й вважають появу невідомих істот прикметою — або прямою загрозою для свого хиткого поселення на скелях."},sec={{t="Зміїний виводок",b="Чужорідне Яйце знайшли біля підніжжя високих скельних шпилів на південь і північний схід від Застави Вільного Вітру, і воно разюче вирізняється з-поміж звичної живності на дні каньйону. Місцеві змії не кинули й не знищили дивну кладку — навпаки, люто стережуть її разом із власними гніздами. Гаґар Лайтнінггуф, сміливець-таурен, що чатує на висотах Застави Вільного Вітру, захотів роздобути цей зразок, щоб з'ясувати, чи загрожує він поселенням на столових горах, чи це лише незвичний різновид місцевих плазунів."},{t="Народження Арікари",b="Щойно яйце приносять на Заставу Вільного Вітру й починають уважно роздивлятися, загадкова шкаралупа тріскає. Усередині немає жодного прибульця з інших світів: з неї з'являється Арікара — червона вітряна зміїця з легенд тауренів, яку вважають духом помсти. Юна зміїця вмить злітає в небо, а приголомшений Гаґар оголошує, що до Тисячі Голок прийшла сама помста, — і це запускає низку подій, яка змусить місцевих захисників стати з нею до бою."}},faq={{q="Чому яйце називають «чужорідним»?",a="Слово «чужорідне» тут ужито в прямому значенні — цілком чуже й незнайоме для місцевих розвідників-тауренів, а зовсім не прилетіле із зоряних просторів. Його забарвлення й візерунок нітрохи не схожі на звичайні кладки вітряних зміїв у Тисячі Голок.",al={"назва чужорідного яйця","чому чужорідне","чи воно з космосу"}},{q="Де знайти Чужорідне Яйце?",a="Яйце лежить на дні каньйону біля підніжжя стрімких стін плато — і на південь, і на північний схід від Застави Вільного Вітру в Тисячі Голок. Його завжди оточують і стережуть ворожі вітряні змії.",al={"місце яйця","де чужорідне яйце","знайти чужорідне яйце"}},{q="Чому місцеві змії стережуть яйце?",a="Напевно ніхто не знає. Змії стережуть яйце, наче власне, і ті, хто його бачив, так і не змогли підійти досить близько, щоб роздивитися.",al={"чому змії стережуть яйце","змії стережуть яйце"}},{q="Що станеться, якщо принести яйце Гаґарові Лайтнінггуфу?",a="Щойно яйце потрапляє до Гаґара Лайтнінггуфа на Заставі Вільного Вітру, воно розколюється просто в нього на очах. Те, що з нього вилітає, так приголомшує Гаґара, що він негайно посилає по пораду до Мотеґи Фаєрмейна.",al={"віддати яйце гаґару","що вилупиться"}}},fp="9,333,17.548.0,20.462.1,30.274.0,33.201.0,40.167.1,59.188.1"}
P.entries["item:alterac-granite"] = {n="Альтеракський Граніт",s="Альтеракський Граніт — цінний міцний камінь, який видобувають у гористій місцевості північного Лордерону, а саме біля Пагорба Дарроу в Передгір'ї Гілсбреда. Майстри-каменярі шанують його за виняткову стійкість і зерно, тож саме його обрав королівський каменяр Короля Маґні Бронзбірда, щоб вирізьбити вічну пам'ятку полеглим воїнам.",h="Альтеракський Граніт — цінний міцний камінь, який видобувають у гористій місцевості північного Лордерону, а...",kw={"альтеракський граніт","пагорб дарроу","передгір'я гілсбреда","саллі баллу","маґні бронзбірд","пам'ятник","марблстен"},ang={["profession:Mining"]="Шахтарі й старателі цінують Альтеракський Граніт за рівний злам і надзвичайну щільність, що вирізняє його з-поміж звичайного скельного каміння.",["race:Dwarf"]="Дворфійські каменярі понад усе ставлять якість матеріалу, тож цей міцний гірський камінь конче потрібен, щоб ушанувати ще одного сина Айронфорджа."},sec={{t="Камінь для пам'ятників",b="Коли Король Маґні Бронзбірд наказав звести пам'ятник Саллі Баллу — хороброму дворфійському захиснику, що загинув у трагедії біля Мосту Тандол, — звичайний камінь із кар'єру не годився. Великий Каменяр Марблстен, якому доручили вирізьбити меморіал в Айронфорджі, наполіг, щоб дістали саме Альтеракський Граніт. Він славиться як один із найкращих каменів у всіх Східних Королівствах, і його легендарна міцність запорука того, що подоба й пам'ять полеглого героя переживуть покоління незаплямованими."},{t="Видобуток серед небезпек",b="Дістати Альтеракський Граніт — зовсім не просте доручення. Камінь залягає біля Пагорба Дарроу в північній частині Передгір'я Гілсбреда, неподалік зруйнованих земель Альтераку. Край кишить ворожими звірами, у засідках чигають розбійники Синдикату, а давні чвари досі не вщухли, тож, щоб принести бездоганні брили цього чистого каменю для ремісників Айронфорджа, потрібні сміливі шукачі пригод, готові заглибитися в спірні землі."}},faq={{q="Для чого потрібен Альтеракський Граніт?",a="Альтеракський Граніт замовив Великий Каменяр Марблстен в Айронфорджі, щоб витесати королівський пам'ятник на честь Саллі Баллу — дворфа-вояка, що поліг, обороняючи Міст Тандол.",al={"для чого альтеракський граніт","навіщо альтеракський граніт","камінь марблстена"}},{q="Де знайти Альтеракський Граніт?",a="Його видобувають із кам'яних покладів на Пагорбі Дарроу, на півночі Передгір'я Гілсбреда, біля кордону з Альтераком.",al={"де альтеракський граніт","де взяти альтеракський граніт","граніт дарроугілла"}},{q="Чому Великий Каменяр Марблстен хотів саме цей камінь?",a="Великий Каменяр Марблстен вважає Альтеракський Граніт одним із найкращих і найміцніших каменів для різьблення — єдиним матеріалом, гідним довговічного королівського пам'ятника, який замовив Король Маґні.",al={"чому марблстен хоче граніт","чому альтеракський камінь"}},{q="Хто такий Саллі Баллу?",a="Саллі Баллу — дворф-вояк, що загинув у боях за Міст Тандол. Король Маґні Бронзбірд замовив пам'ятник на його честь, щоб ушанувати його жертву заради Альянсу.",al={"саллі баллу","хто загинув на мості тандола"}}},fp="15,339,18.494.0,17.442.0,33.174.0,35.134.0,60.203.0,21.191.0"}
P.entries["item:altered-snapjaw-shell"] = {n="Змінений Панцир Хижощелепа",s="Змінений панцир хижощелепа — щит прісноводної черепахи, що живе в буйних оазах Пусток. Друїди, що вивчають цей край, досліджують ці мутовані панцирі, щоб зрозуміти, як дивні підземні розколини спотворюють місцеву звірину.",h="Змінений панцир хижощелепа — щит прісноводної черепахи, що живе в буйних оазах Пусток.",kw={"змінений панцир","хижощелепи","черепахи","тонга рунтотем","оази","пустки"},ang={["class:Druid"]="Для друїдів вивчення спотворених панцирів звірів з оаз — важливий крок, щоб виявити приховане порушення рівноваги, яке збурює води Пусток."},sec={{t="Ознаки порчі",b="Прісноводні черепахи, що живуть в Оазі Буйних Вод і Застояній Оазі, зазнали помітних протиприродних змін. Вважають, що вони п'ють із джерел, які живлять загадкові підземні розколини, тож хижощелепи оаз мають змінені панцирі, що зацікавили дослідників на Перехресті. Тонга Рунтотем, тауренський друїд, що прагне дізнатися про здоров'я землі, збирає ці панцирі, щоб з'ясувати, чи сили, які підіймаються з глибин, — протиприродна напасть, чи щось значно дивніше."}},faq={{q="Чим змінені ці черепашачі панцирі?",a="Хижощелепи живуть у джерелах Оази Буйних Вод і Застояни, які живляться з глибоких підземних розломів. Дивна енергія, що вибулькує у воду оаз, змінила саму природу істот, які її п'ють, — і їхні панцирі помітно викривилися.",al={"чому панцирі змінені","що таке змінений панцир хижощелепа","мутація панцира хижощелепа"}},{q="Кому потрібні ці панцирі й навіщо?",a="Тонга Рунтотем, друїд на Перехресті, просить мисливців їх добути. Він вважає, що тілесні зміни місцевих звірів допоможуть з'ясувати, яка сила чи скверна отруює води Пусток.",al={"кому потрібні змінені панцирі хижощелепів","панцирі для тонґи рунетотем","здати завдання змінених істот"}},{q="Де водяться ці хижощелепи?",a="Оазисні хижощелепи живуть у воді й на мулистих берегах Оази Буйних Вод і Застояни, на південь і південний схід від Перехрестя.",al={"де хижощелепи оазису","де взяти змінені панцирі","місця панцирів хижощелепів"}}},fp="21,241,19.495.0,39.279.0,31.238.0,31.150.0"}
P.entries["item:ambercorn"] = {n="Бурштинова шишка",s="Бурштинова шишка — священний плід, що падає з високих прадавніх дерев, розкиданих по Малгору. Насичена природною магією, вона слугує важливим реагентом у шаманських варивах тауренів — найчастіше для викликання духовних видінь під час випробувань молоді.",h="Бурштинова шишка — священний плід, що падає з високих прадавніх дерев, розкиданих по Малгору.",kw={"бурштинова шишка","малгор","таурени","обряд видіння","зарлман ту-мунс","вода провидців","шамани"},ang={["class:Shaman"]="Шаманська традиція шанує природні каталізатори на кшталт бурштинової шишки, визнаючи, що Мати-Земля вкладає духовну магію у плоди своїх дерев і ґрунту.",["race:Tauren"]="Кожен молодий таурен, що проходить традиційні Обряди Матері-Землі, вчиться розпізнавати бурштинову шишку як неодмінний складник пошуку видіння, що відкриває його духовний шлях."},sec={{t="Дари крони",b="Зібрані під міцними гілками великих дерев Малгору, бурштинові шишки для тауренів — більше, ніж звичайні горіхи. Багаті на духовну силу землі, вони мають приховані магічні властивості, які містики тауренів розуміють і використовують поколіннями. Молоді мисливці й мандрівники рано вчаться дивитися під ноги в траві під кроною, шануючи дари Матері-Землі, що вільно падають згори."},{t="Вариво провидця",b="У Селі Бладгуф провидець Зарлман Ту-Мунс покладається на бурштинову шишку, готуючи молодих тауренів до Обряду Видіння. Разом із камінням, зібраним у чистих водяних криницях рівнин, бурштинову шишку настоюють на могутню Воду Провидців. Випитий перед вогнями предків церемоніальний еліксир зміщує чуття посвяченого й відкриває духа-провідника у подобі звіра, що має вести його до наступної мети."}},faq={{q="Що таке Бурштинова шишка?",a="Бурштинова шишка — це насінна коробочка чи горіх, що падає з великих прадавніх дерев Малгору. Вона несе в собі природну магію, співзвучну з духами землі.",al={"бурштинова шишка","що таке бурштинові шишки"}},{q="Де знайти бурштинові шишки?",a="Вони лежать просто на землі під кронами могутніх дерев, розкиданих степами Малгору, — особливо довкола Села Бладгуф.",al={"де бурштинова шишка","де знайти бурштинову шишку","як дістати бурштинову шишку"}},{q="Для чого потрібні бурштинові шишки?",a="Провидці тауренів поєднують бурштинові шишки з каменями з колодязя, щоб зварити Воду Провидців — обрядовий напій, який п'ють під час Обряду Видіння, щоб побачити духів-провідників.",al={"для чого бурштинова шишка","що робить бурштинова шишка"}},{q="Хто в Селі Бладгуф просить принести бурштинові шишки?",a="Зарлман Ту-Мунс, шанований провидець із Села Бладгуф, доручає новачкам зібрати бурштинові шишки — це одне з випробувань, що мають довести їхній зв'язок із Земною Матір'ю.",al={"кому потрібні бурштинові шишки","хто дає завдання на шишки"}}},fp="9,241,19.422.0,15.425.0,21.150.0,29.181.0,27.162.0,44.185.0"}
P.entries["item:amethyst-phial"] = {n="Аметистова Фіала",s="Аметистова Фіала — тендітна обрядова посудина, яку Корітрас Мунрейдж у Доланаарі довіряє молодим нічним ельфам — шукачам пригод. Її зроблено саме для того, щоб набрати й зберегти священну воду з найпершого місячного колодязя під Деревом Оракула.",h="Аметистова Фіала — тендітна обрядова посудина, яку Корітрас Мунрейдж у Доланаарі довіряє молодим нічним...",kw={"аметистова фіала","місячний колодязь","дерево оракула","галявина оракула","корітрас мунрейдж","доланаар","тельдрассил","корона землі"},ang={["class:Druid"]="Друїди бачать у цій посудині важливе знаряддя для нагляду за життєвими силами й повзучою скверною, що загрожують живому світові Світового Дерева.",["race:NightElf"]="Для калдореїв наповнити цю фіалу — урочистий обов'язок, що прямо зіштовхує їх із тривожними вадами неблагословенного творення Тельдрассила."},sec={{t="Посудина священних вод",b="Довірена посвяченим на Тельдрассилі, Аметистова Фіала — остання посудина в паломництві Корони Землі. Корітрас Мунрейдж доручає мандрівникам віднести її на далекий північний захід віття, на Галявину Оракула. Там, під прадавнім шатром Дерева Оракула, лежить перший і наймогутніший місячний колодязь острова. Фіалу обережно занурюють у ці сяйливі води, щоб узяти сутність ласки Елуни і дати друїдам та жрицям змогу вивчати й доглядати непередбачуване зростання Світового Дерева."},{t="Тягар неблагословенного зростання",b="Збирання цього зразка — більше ніж звичний обряд відданості. Тельдрассил виростили під проводом Архідруїда Фандрала Стаґгелма без благословення Драконячих Аспектів, які відмовилися схвалити те, що мали за зухвальство. Через це віття потерпає від тривожної скверни, а калдореї лишаються смертними. Наповнення Аметистової Фіали — водночас духовний обряд і безперервне спостереження, що дає дослідникам у Доланаарі змогу прискіпливо перевіряти чистоту священних вод Тельдрассила."}},faq={{q="Для чого потрібна Аметистова Фіала?",a="Корітрас Мунрейдж дає фіалу шукачам пригод, щоб ті набрали води з першого й наймогутнішого місячного колодязя Тельдрассила — він у Галявині Оракула під великим Деревом Оракула.",al={"для чого аметистова фіала","що робити з аметистовою фіалою","використання аметистової фіали"}},{q="Де наповнити Аметистову Фіалу?",a="It must be dipped into the moonwell far to the northwest of Dolanaar, north of the entrance to Darnassus, within the secluded grove known as the Oracle Glade.",al={"де наповнити аметистову фіалу","місце аметистової фіали","місячний колодязь галявини оракула"}},{q="Чому вода з Галявини Оракула така важлива?",a="Місячний колодязь під Деревом Оракула вважають першим і наймогутнішим колодязем на Світовому Дереві. Його води глибоко просякнуті сутністю Елуни, тож без них не простежиш за духовним і тілесним здоров'ям Тельдрассила.",al={"чому вода галявини оракула","сила місячного колодязя дерева оракула","значення криниці оракула"}},{q="Хто посилає скористатися цією фіалою?",a="Корітрас Мунрейдж, друїд нічних ельфів із Доланаара, дає фіалу в межах обрядових доручень, що мають допомогти зрозуміти, чому Тельдрассил росте так тривожно.",al={"хто дає аметистову фіалу","корітрас мунрейдж фіала","кому потрібна аметистова фіала"}}},fp="14,241,23.550.0,28.517.1,36.187.0,35.158.0,52.258.0,32.174.0"}
P.entries["item:an-undelivered-letter"] = {n="Недоставлений Лист",s="Недоставлений Лист — давно забута пошта, що лишилася в Корчмі «Лев'яча Гордість» у Ґолдширі. Написаний багато років тому невловимим Сталваном Містмантлом, він стає вирішальною підказкою в розплутуванні темної історії його минулого.",h="Недоставлений Лист — давно забута пошта, що лишилася в Корчмі «Лев'яча Гордість» у Ґолдширі.",kw={"недоставлений лист","сталван містмантл","ґолдшир","лев'яча гордість","наглядач фолсом","стормвінд"},ang={["faction:Alliance"]="Відтворюючи забутий маршрут гінця, слідчі проходять шлях від мирного сільського Ґолдшира до заможних кварталів Стормвінда."},sec={{t="Опівнічна втеча",b="Багато років тому буря загнала мандрівного гінця до Корчми «Лев'яча Гордість» у пошуках сухого нічлігу. Близько півночі наляканий посланець збіг сходами в самій нічній сорочці й зник під зливою — і більше не повернувся. На другому поверсі він покинув скриню з речами, а серед них — лист, написаний Сталваном Містмантлом і адресований до маєтку в районі Каналів Стормвінда."},{t="Слідами вченого",b="Нерозпечатаний лист пролежав у верхніх кімнатах корчми недоторканим, доки нинішні слідчі не взялися простежити шлях Сталвана через Ліс Елвінн. Доставлений Наглядачеві Фолсому в столицю, давно загублений пергамент переносить таємницю з тихих залів корчми в саме серце Стормвінда."}},faq={{q="Де знайти недоставлений лист?",a="Він лежить у скрині на другому поверсі Корчми «Лев'яча Гордість» у Ґолдширі — біля самого ліжка в одній із гостьових кімнат.",al={"де лист","місце скрині","скриня левової гордості"}},{q="Чому лист так і не доставили?",a="Кур'єр, що віз його, сховався від зливи в Корчмі «Лев'яча Гордість». Близько опівночі його раптом охопила паніка: він збіг униз у нічній сорочці й вибіг у грозу, покинувши скриню з усім її вмістом.",al={"чому не доставлений","що сталося з гінцем","кур'єр утік"}},{q="Хто написав цей лист?",a="Лист надіслав Сталван Містмантл, який провів у корчмі кілька ночей приблизно тоді ж, коли там зупинявся переляканий кур'єр.",al={"хто надіслав лист","автор сталван","відправник"}},{q="Куди мав потрапити лист?",a="Його адресовано в Квартал Каналів Стормвінда, тож лист можна віднести Наглядачеві Фолсому біля Парку.",al={"хто отримує лист","пункт призначення стормвінд","лист каналового району"}}},fp="21,222,17.401.0,19.307.1,38.150.0,35.223.0,22.140.0,35.115.0"}
P.entries["item:anaya-s-pendant"] = {n="Підвіска Анаї",s="Підвіска Анаї — пам'ятка, яку носить неспокійний привид Анаї Донраннер серед руїн Амет'Арана. Це трагічний знак пам'яті про її коханого, Сереллеана Вайтклоу, який пережив Розкол лише для того, щоб через тисячоліття побачити її дух і досі змученим.",h="Підвіска Анаї — пам'ятка, яку носить неспокійний привид Анаї Донраннер серед руїн Амет'Арана.",kw={"підвіска анаї","аная донраннер","сереллеан вайтклоу","амет'аран","темне узбережжя","привид"},ang={["class:Druid"]="Як і багато друїдів, що пішли за шан'до Стормрейджем у Смарагдовий Сон, Сереллеан проспав тисячоліття, сподіваючись утекти від горя, — і прокинувся серед привидів, що досі блукають світом наяву.",["race:NightElf"]="Підвіска — щемке нагадування про незагоєні рани Війни Прадавніх, коли Великий Розкол обірвав незліченні життя й розлучив безліч закоханих."},sec={{t="Пам'ятка крізь тисячоліття",b="Десять тисяч років тому, коли катастрофа знищила Колодязь Вічності, давнє місто калдореїв Амет'Аран обернулося на руїни. Певний, що його кохана Аная загинула, Сереллеан Вайтклоу поніс своє глибоке горе в довгий сон разом із шан'до Малфуріоном Стормрейджем. Прокинувшись нарешті, він блукав Темним Узбережжям — і виявив, що змучений привид Анаї досі ширяє Амет'Араном із цією самою підвіскою. Не в змозі сам підняти на неї руку, Сереллеан просить мандрівників звільнити її дух і повернути родинну реліквію."},{t="Прощання і спокій",b="Коли підвіску повертають Сереллеанові в Обердайні, неупокоєний дух Анаї Донраннер востаннє ненадовго з'являється перед ним. Звільнений від муки, що прив'язувала її до примарних руїн Амет'Арана, привид тихо тане в нічній темряві, лишаючи Сереллеана наодинці з підвіскою та незгасною пам'яттю про їхнє давнє кохання."}},faq={{q="Звідки береться Підвіска Анаї?",a="Підвіску забирають у привида Анаї Донраннер, яка блукає прадавніми руїнами калдореїв Амет'Аран на півдні Темного Узбережжя.",al={"де взяти підвіску анаї","як отримати підвіску анаї","хто дропає підвіску анаї"}},{q="Кому потрібна Підвіска Анаї?",a="Вона належить Сереллеану Вайтклоу — нічному ельфу, що тужить за коханою в прибережному містечку Обердайн на Темному Узбережжі.",al={"кому віддати підвіску анаї","завдання сереллеана вайткло","здати підвіску анаї"}},{q="Чому Сереллеан не міг сам забрати підвіску?",a="Сереллеан знайшов дух своєї втраченої коханої серед руїн Амет'Аран, але навіть після десяти тисяч років скорботи не мав сил підняти на неї руку.",al={"чому сереллеан не вбив анаю","чому сереллеану потрібна допомога"}},{q="Що станеться, якщо повернути підвіску Сереллеану?",a="Коли підвіску приносять Сереллеану в Обердайн, дух Анаї на мить постає перед ним, щоб попрощатися, а тоді згасає й знаходить спокій. Нарешті Сереллеан може оплакати пам'ять про неї.",al={"що буде з анаєю","реакція сереллеана"}}},fp="15,273,27.579.0,17.343.1,37.136.0,26.111.0,52.191.0,54.193.1"}
P.entries["item:ancient-moonstone-seal"] = {n="Стародавня Печатка з Місячного Каменю",s="Стародавня Печатка з Місячного Каменю — могутня реліквія чаклунства Високородних, викувана задовго до Розколу. Сповнена потужної тайної магії скування, вона була якорем, що тримав дух Астеріона в полоні серед руїн Башал'Арана.",h="Стародавня Печатка з Місячного Каменю — могутня реліквія чаклунства Високородних, викувана задовго до Розколу.",kw={"стародавня печатка з місячного каменю","астеріон","атрікус нарассін","башал'аран","амет'аран","високородні"},ang={["class:Mage"]="Місячний камінь доводить, яка тривка давня ельфійська магія оберегів: його сковувальне поле не слабшало понад десять тисяч років.",["race:NightElf"]="Печатка — моторошна реліквія неприборканої тайної могутності Високородних і жорстокого поневолення, яке вони чинили до Великого Розколу."},sec={{t="В'язниця чаклунства Високородних",b="Стародавню Печатку з Місячного Каменю викував колишній господар Астеріона, могутній чаклун Високородних Атрікус Нарассін, як незламний метафізичний якір. Коли ще стояв Колодязь Вічності й правила королева Азшара, Атрікус за допомогою артефакту прикував душу Астеріона до колон Башал'Арана. І через понад десять тисячоліть Астеріон залишався безтілесним в'язнем цієї магії: жодна сила чи чари, якими він володів, не могли зламати печать."},{t="Знищення в Амет'Арані",b="Після спустошення Великого Розколу печатка зрештою потрапила в пазурі сатирів Дет'рілл, що кишать у навколишніх нетрях Темного Узбережжя. Звичайна сила не здатна навіть подряпати зачарований Високородними камінь, тож щоб знищити артефакт, його треба кинути в давнє синє полум'я, що досі палає в руїнах-близнюках Амет'Арана на півдні. Поглинута цим тайним вогнем, печатка назавжди руйнує сковувальні чари Атрікуса й нарешті відпускає дух Астеріона у світ смертних."}},faq={{q="Що таке Стародавня Печатка з Місячного Каменю?",a="Це прадавня чарівна реліквія, яку створив чародій із Високородних Атрікус Нарассін. Вона слугує магічним ключем, що прив'язує привида Астеріона до його святилища в руїнах Башал'Аран.",al={"що таке печатка з місячного каменю","печатка астеріона","печатка башал'аран"}},{q="У кого була печатка, перш ніж її повернули?",a="Печатка потрапила до рук сатирів Дет'рілл, що заполонили руїни довкола Башал'Аран на Темному Узбережжі. Вони користувалися її силою, щоб командувати нижчими греллами.",al={"у кого печатка","де печатка з місячного каменю","хто дропає печатку"}},{q="Як знищити печатку?",a="Звичайна зброя чи сучасна магія реліквії не зашкодять. Її треба кинути в прадавнє вічне полум'я, що досі горить у руїнах-близнюках Амет'Аран на півдні.",al={"як зламати печатку","знищити печатку з місячного каменю","де знищити печатку"}},{q="Що станеться, коли печатку знищено?",a="Спалена в полум'ї Амет'Аран печатка розриває прадавні чари, що тримали Астеріона, і його дух після тисячоліть неволі нарешті може вільно блукати світом.",al={"що буде, коли зламати печатку","астеріон вільний"}}},fp="22,238,29.469.0,25.498.1,35.190.0,46.165.0,30.180.0,40.186.1"}
P.entries["item:ancient-statuette"] = {n="Прадавня Статуетка",s="Прадавня Статуетка — затонула реліквія, знайдена на Зорамському Узмор'ї на північному заході Ашенвалю. Цю невеличку фігурку шукає нічний ельф Тален; вона походить із затоплених руїн прадавнього міста Зорам.",h="Прадавня Статуетка — затонула реліквія, знайдена на Зорамському Узмор'ї на північному заході Ашенвалю.",kw={"прадавня статуетка","зорам","тален","наги","реліквія","ашенваль"},ang={["faction:Alliance"]="Повернувши цей артефакт, ви допоможете Таленові описати й відвоювати спадщину нічних ельфів у наг, що наступають на узбережжя Ашенвалю.",["race:NightElf"]="Статуетка — рідкісний уцілілий уламок прадавньої цивілізації калдореїв, що існувала до Великого Розколу й тисячоліттями зберігалася під морем."},sec={{t="Реліквія на мілині",b="Води біля північно-західного Ашенвалю приховують затонулі рештки Зорама — міста нічних ельфів, що існувало ще до Великого Розколу й десять тисяч років тому пішло під хвилі. Нещодавно дослідник Тален оглядав затоплені руїни з невеликого човна, шукаючи загублені історичні реліквії. Коли люті наги напали й вигнали його на берег, Тален, рятуючись, покинув майже все своє добро — і впустив прадавню статуетку, яку виловив із глибини, на пісок біля лінії прибою, неподалік від свого затопленого човника."},{t="Таємниці Зорама",b="Тален вважає статуетку найдорожчим своїм скарбом і єдиним виправданням того, що він ризикнув вирушити на це узбережжя, де кишать чудовиська. Для нього фігурка — не просто оздоблення з каменю: він вірить, що вона — ключ до розгадки архітектури, історії та таємних знань, захованих під прибоєм Зорамського Узмор'я."}},faq={{q="Що таке Прадавня Статуетка?",a="Це артефакт, піднятий із затонулих руїн прадавнього міста нічних ельфів Зорам біля північно-західного узбережжя Ашенвалю.",al={"що таке статуетка","історія прадавньої статуетки","що це за річ"}},{q="Хто шукає статуетку?",a="Її шукає вчений із нічних ельфів Тален. Він пропливав човном над затопленими руїнами, коли на нього напали наги, і, рятуючись утечею, загубив реліквію на березі.",al={"кому потрібна статуетка","статуетка талена","хто загубив статуетку"}},{q="Чому статуетка важлива?",a="Тален вважає, що статуетка зберігає таємниці прадавнього міста Зорам і може стати ключем до історії, похованої в руїнах під хвилями.",al={"чому телен її хоче","навіщо статуетка"}},{q="Чому біля місця знахідки никають наги?",a="Наги заполонили прибережні води й руїни Узбережжя Зорам і люто нападають на кожного жителя суходолу, хто наблизиться до затонулих решток їхніх підводних володінь.",al={"чому наги на пляжі","нага на березі зорама"}}},fp="17,226,23.470.0,16.340.0,30.140.0,33.180.0,31.165.0,48.178.0"}
P.entries["item:andron-s-ledger"] = {n="Гросбух Андрона",s="Гросбух Андрона — розвідувальний документ, здобутий в Андрона Ґанта в Андерсіті. Скрадачі смерті шукають його під час перших доручень агента, що збирає відомості для Відступників.",h="Гросбух Андрона — розвідувальний документ, здобутий в Андрона Ґанта в Андерсіті.",kw={"гросбух андрона","андрон ґант","синдикат","скрадачі смерті","меннет каркад","варіматрас","андерсіті"},ang={["class:Rogue"]="Здобути й розшифрувати Гросбух Андрона — ваше випробування: після нього Меннет Каркад офіційно приймає вас до скрадачів смерті, а сам Варіматрас особисто визнає вашу роботу.",["race:Undead"]="Гросбух показує, як Відступники збирають відомості про загрози, що оточують їхні нові землі."},sec={{t="Викриття Синдикату",b="Цей гросбух, знятий із книжкової полиці Андрона Ґанта в Андерсіті, містить набагато більше відомостей, ніж спершу сподівалися скрадачі смерті. З нього випливає, що Синдикат — рештки занепалої людської знаті Альтераку — активно діє в краї. Переглянувши записи, скрадач смерті Меннет Каркад одразу розуміє стратегічну вагу документа: розорені лорди Альтераку знову плетуть інтриги. Гросбух дає проводу Відступників переконливий доказ діяльності Синдикату, і звичайне доручення обертається великим успіхом розвідки."},{t="Справа для жахолорда",b="Оскільки йдеться про загрози землям Відступників, Меннет Каркад посилає того, хто приніс гросбух, просто до Варіматраса в Королівський Квартал. Жахолорд Варіматрас, мажордом Сильвани Віндраннер, наглядає за внутрішньою безпекою та шпигунством через скрадачів смерті. Гросбух заслуговує похвалу Варіматраса й доводить і вправність мережі скрадачів смерті, і надійність агента, що виніс правду на світло."}},faq={{q="Що таке Гросбух Андрона?",a="Це облікова книга з полиці Андрона Ґанта в Андерсіті, у якій записано відомості, що їх шукають скрадачі смерті.",al={"гросбух андрона","що це за книга","гросбух андрон"}},{q="Хто такий Андрон Ґант?",a="Андрон Ґант — Відступник, що тримає крамницю біля Апотекаріуму в Андерсіті. Лорд Варіматрас запідозрив, що той таємно допомагає якійсь сторонній групі, тож скрадачі смерті підіслали до нього агента під виглядом очікуваного посланця, щоб заволодіти гросбухом.",al={"хто такий андрон","андрон ґант"}},{q="Навіщо скрадачам смерті гросбух?",a="Меннет Каркад хоче вивчити записи Андрона й знайти відомості, корисні для Відступників.",al={"чому гросбух важливий","навіщо скрадачам смерті гросбух"}},{q="Хто отримує гросбух?",a="Спершу його приносять Меннету Каркаду в Квартал Розбійників. Той оцінює вміст і велить доставити гросбух просто лордові Варіматрасу в Залу Темної Леді.",al={"хто отримує гросбух андрона","кому віднести гросбух"}},{q="Що дає розбійникові доставка гросбуха?",a="Доставка гросбуха завершує посвяту агента в скрадачі смерті: він офіційно стає членом таємної гільдії вбивць Відступників.",al={"посвята у скрадачі смерті","вступ до скрадачів смерті"}}},fp="15,190,24.613.1,26.462.1,24.129.0,19.240.0,41.92.0,24.186.0,52.153.0"}
P.entries["item:another-clue-to-sanders-treasure"] = {n="Ще Одна Підказка до Скарбу Сандерса",s="«Ще Одна Підказка до Скарбу Сандерса» — пошарпаний клаптик пергаменту, залишений сумнозвісним піратом капітаном Сандерсом. Знайдений у старій бочці, він містить віршовані вказівки, що ведуть шукачів скарбів до самотнього орієнтира на кручах Вестфолу.",h="«Ще Одна Підказка до Скарбу Сандерса» — пошарпаний клаптик пергаменту, залишений сумнозвісним піратом...",kw={"скарб сандерса","капітан сандерс","підказка","вітряк","вестфол","пірат"},ang={["class:Rogue"]="Розгадувати заплутані вказівки й нишпорити в забутих приморських схованках — звичне ремесло для кожного, хто має нюх на приховану здобич."},sec={{t="Слід на прибережних кручах",b="Капітан Сандерс ніколи не тримав награбоване на видноті. Замість однієї карти, яку могли б відібрати за раз, він розбив свої вказівки на низку загадок і схованих позначок. Цей клаптик пергаменту продовжує слід: він велить тому, хто його тримає, повернути від попередньої схованки на північ і пошукати покинутий глек біля самотнього вітряка, що здіймається над морськими скелями."}},faq={{q="Що написано в цій підказці?",a="Пергамент велить тому, хто його знайшов, стати від схованого барила обличчям на північ і йти прямо, доки не побачить порожній глек біля самотнього вітряка на морських кручах.",al={"що написано в підказці","текст підказки сандерса","вказівки в підказці"}},{q="Хто такий капітан Сандерс?",a="Капітан Сандерс був піратом, після пригод якого вздовж узбережжя й круч Вестфолу лишилися схованки з награбованим. Замість цілої мапи він залишив по всьому краю низку прихованих позначок — справжні пошуки скарбу.",al={"хто такий сандерс","минуле капітана сандерса","пірат сандерс з вестфолла"}},{q="Куди веде ця підказка далі?",a="За вказівками підказки треба йти на північ уздовж прибережних скель до самотнього вітряка на кручі, де в порожньому глеку чекає наступний крок слідом Сандерса.",al={"куди йти далі","підказка про вітряк сандерса","де глечик"}}},fp="33,253,29.422.0,29.172.0,24.222.0,31.168.0"}
P.entries["item:arikara-serpent-skin"] = {n="Зміїна Шкіра Арікари",s="Зміїна Шкіра Арікари — луската шкура, знята з міфічного вітряного змія Арікари на вершині Шпиля Темної Хмари. Принесена на Заставу Білого Рубежу, вона слугує відчутним доказом того, що спраглого помсти звіра прикликано й убито.",h="Зміїна Шкіра Арікари — луската шкура, знята з міфічного вітряного змія Арікари на вершині Шпиля Темної Хмари.",kw={"зміїна шкіра арікари","арікара","шпиль темної хмари","маґата ґрімтотем","кайрн бладгуф","мотеґа фаєрмейн","застава білого рубежу"},ang={["class:Shaman"]="Обряд, у якому зачарований порошок сиплють на священний вогонь, щоб змусити звіра-духа предків набути плоті, показує могутнє — хай і маніпулятивне — обрядове мистецтво, яке практикують у Тандер Блафі.",["race:Tauren"]="Ця шкура уособлює зіткнення давніх міфів із нинішньою владою: твердження Маґати Ґрімтотем про Кайрна Бладгуфа сіють неспокій серед племен."},sec={{t="Трофей прикликаного гніву",b="Арікара — грізний вітряний змій, пов'язаний із давньою легендою тауренів; кажуть, ніби він прагне помститися Кайрнові Бладгуфу за те, що звичаї народу змінюються. За допомогою зачарованого Інцендієвого Порошку, приготованого під наглядом Старійшини Маґати Ґрімтотем, чемпіони розпалюють священний вогонь на поховальних кручах Шпиля Темної Хмари, щоб змусити звіра-духа з'явитися у світі живих. Здерши шкуру змія, вони здобувають Зміїну Шкіру Арікари — безсумнівну реліквію загибелі звіра."},{t="Тривожне відкриття",b="Коли шкуру приносять на Заставу Білого Рубежу, до Мотеґи Фаєрмейна, вона доводить, що змій мертвий, але порушує незручні питання. Маґата Ґрімтотем наполягала, що Арікара полював саме на Кайрна Бладгуфа з прадавньої люті, проте, оглянувши вбиту істоту, Мотеґа не може збагнути, чому такий дух справді загрожував би їхньому Верховному Вождеві. Хоч шкура й усуває нагальну небезпеку, вона лишає стійку підозру щодо того, як насправді Маґата тлумачить знамення."}},faq={{q="Що таке Зміїна Шкіра Арікари?",a="Це луската шкура Арікари — легендарної вітряної змії, яку викликають і вбивають на вершині Шпиля Темної Хмари в Тисячі Голок.",al={"зміїна шкіра","шкіра арікари","що це за шкіра"}},{q="Кому потрібна Зміїна Шкіра Арікари?",a="Мотеґа Фаєрмейн на Заставі Білого Рубежу вимагає шкуру разом із залишками Інцендієвого Порошку як доказ, що змія більше не загрожує.",al={"хто бере шкіру","кому здати","хто хоче шкіру арікари"}},{q="Навіщо взагалі викликали Арікару?",a="Маґата Ґрімтотем стверджувала, що зміни в традиціях тауренів розгнівали прадавню змію Арікару і вона почала переслідувати Верховного Вождя Кайрна Бладгуфа. Маґата веліла виманити звіра й убити, перш ніж Кайрнові заподіють шкоди.",al={"чому викликали арікару","чому вбивати арікару"}},{q="Як здобути шкуру?",a="Її знімають з Арікари, яку викликають, кинувши зачарований Інцендієвий Порошок у священне вогнище життя на поховальній скелі-голці в Шпилі Темної Хмари.",al={"де взяти зміїну шкіру арікари","де арікара"}}},fp="20,231,26.474.0,22.458.1,33.136.0,35.152.0,44.245.0,31.176.0"}
P.entries["item:arnak-s-hoof"] = {n="Копито Арнака",s="Копито Арнака — моторошний доказ смерті злочинця Арнака Ґрімтотема. Захисники Застави Вільного Вітру засудили його на страту, коли він убив одноплемінника-таурена й викрав його сестру, і вистежили його на кручах Шпиля Темної Хмари.",h="Копито Арнака — моторошний доказ смерті злочинця Арнака Ґрімтотема.",kw={"копито арнака","арнак ґрімтотем","шпиль темної хмари","лакота віндсонг","застава вільного вітру","скельний вартовий лонггорн"},ang={["faction:Horde"]="Знищення Арнака зміцнює владу Застави Вільного Вітру в Тисячі Голок і послаблює підступний вплив Ґрімтотемів, що загрожує шляхам постачання Орди.",["race:Tauren"]="Для тауренів рівнин здобути копито Арнака — акт племінного правосуддя над ренегатом, чиї вбивства принесли Тисячі Голок безчестя й кровопролиття."},sec={{t="Нагорода за голову вигнанця",b="Арнак Ґрімтотем зажив по всій Тисячі Голок слави розбійника, чия жорстокість переступила навіть суперечливі межі міжкланової політики тауренів. Коли він убив іншого таурена й викрав сестру загиблого, Лакоту Віндсонг, за його смерть офіційно призначили нагороду. Арнак засів на висотах Шпиля Темної Хмари під охороною вартових-Ґрімтотемів. Його смерть і відтяте копито стануть для Скельного Вартового Лонггорна на Заставі Вільного Вітру незаперечним підтвердженням того, що вбивця нарешті відповів за свої злочини."}},faq={{q="Для чого потрібне Копито Арнака?",a="Копито Арнака — речовий доказ смерті розбійника Арнака Ґрімтотема. Його віддають Скельному Вартовому Лонггорну на Заставі Вільного Вітру, щоб отримати обіцяну за голову винагороду.",al={"здати копито арнака","що робити з копитом арнака","кому потрібне копито арнака"}},{q="Хто такий Арнак Ґрімтотем?",a="Арнак — ренегат із Ґрімтотемів, якого розшукували за вбивство й викрадення. Він убив одноплемінника-таурена й тримав у полоні його сестру, Лакоту Віндсонг, на кручах Шпиля Темної Хмари.",al={"хто такий арнак","історія арнака ґрімтотема","чому арнака розшукують"}},{q="Де знайти Арнака Ґрімтотема?",a="Арнак ховається на скелях Шпиля Темної Хмари на півночі Тисячі Голок, куди ведуть мотузяні мости біля урвищ на підступах до Рейзорфен Даунс. Свою бранку, Лакоту Віндсонг, він тримає на тій самій кручі.",al={"де арнак ґрімтотем","де арнак","як знайти арнака"}}},fp="12,256,20.533.0,30.200.0,24.183.0,31.211.0"}
P.entries["item:astor-s-letter-of-introduction"] = {n="Рекомендаційний Лист Астора",s="Рекомендаційний Лист Астора — документ, який носить Астор Гадрен, гонець, що курсує між Срібноліссям і Андерсіті. Майбутні скрадачі смерті забирають цей лист, щоб під його прикриттям проникнути в підозрювану змову, до якої причетний крамар Андрон Ґант.",h="Рекомендаційний Лист Астора — документ, який носить Астор Гадрен, гонець, що курсує між Срібноліссям і...",kw={"рекомендаційний лист астора","астор гадрен","андрон ґант","скрадачі смерті","меннет каркад","варіматрас","аптекаріум"},ang={["class:Rogue"]="Здобути й використати лист Астора — одне з перших польових завдань для розбійників-Відступників, які прагнуть до лав скрадачів смерті: воно перевіряє ваше вміння вбивати, красти й видавати себе за іншого.",["race:Undead"]="Інтриги довкола листа показують, яка підозріливість панує в Андерсіті: лорд Варіматрас руками скрадачів смерті викорінює крамолу серед Відступників."},sec={{t="Повноваження гінця",b="Астор Гадрен був обачним гінцем, що курсував між Срібноліссям і столицею. Його особистий рекомендаційний лист засвідчує надійність того, хто його пред'являє, перед таємними зв'язковими в місті. Коли Меннет Каркад, куратор скрадачів смерті, взявся розслідувати підозрілі витоки в Андерсіті, Астор із його подорожами одразу став мішенню. Убивши Гадрена або просто відібравши в нього папери, агент може видати себе за нього й перехоплювати таємні повідомлення, призначені лише для Астора."},{t="Пастка в Апотекаріумі",b="Меннет Каркад використовує здобутий лист, щоб ошукати Андрона Ґанта — крамаря, що тримає лавку неподалік Апотекаріуму. Лорд Варіматрас підозрює Ґанта в тому, що той зливає таємниці Відступників невідомій третій стороні. Маючи лист Астора, агент під прикриттям видає себе за очікуваного зв'язкового і, скориставшись наївною довірою Ґанта, з'ясовує, хто його спільники, та здобуває докази зради."}},faq={{q="Для чого потрібен Рекомендаційний Лист Астора?",a="Він слугує посвідченням особи, щоб ошукати торговця Андрона Ґанта. Показавши лист, агент видає себе за кур'єра Астора Гадрена й викриває таємні оборудки Ґанта.",al={"призначення листа","що робить лист","для чого лист астора"}},{q="Хто такий Астор Гадрен?",a="Астор Гадрен — посланець і гонець, що мандрував дорогами між Срібноліссям і Андерсіті з листами для приватних осіб, доки його не перехопили агенти скрадачів смерті.",al={"хто такий астор","історія астора гадрена","чий був лист"}},{q="Навіщо Меннетові Каркаду цей лист?",a="Меннет Каркад використовує лист, щоб випробувати новобранців, які хочуть вступити до скрадачів смерті, і влаштувати пастку для Андрона Ґанта, якого лорд Варіматрас підозрює в зраді.",al={"чому меннету потрібен лист","план каркада"}},{q="Чи підозрює Андрон Ґант, що лист викрадено?",a="Ні. Меннет зауважує, що Ґантові забракне кмітливості запідозрити підступ, і той охоче приймає подавця листа за звичайного гінця від своїх змовників.",al={"чи помічає ґант","чи обдурять андрона"}}},fp="30,269,23.494.0,29.418.1,48.178.0,21.203.0,40.174.0,46.158.1"}
P.entries["item:ataeric-s-staff"] = {n="Посох Атеріка",s="Посох Атеріка — могутній магічний провідник, яким орудує Архімаг Атаерік, поважний даларанський чарівник у Срібноліссі. Він водночас і фокус для керування місцевими лей-лініями, і речовий доказ поразки архімага для Відступників у Гробниці.",h="Посох Атеріка — могутній магічний провідник, яким орудує Архімаг Атаерік, поважний даларанський чарівник у...",kw={"посох атаеріка","архімаг атаерік","даларан","лей-лінії","жрець тіні аллістер","срібнолісся"},ang={["class:Mage"]="Посох — приклад зосереджених знарядь, якими архімаги Даларана користуються, щоб черпати силу з дрімотних лей-вузлів і знову їх пробуджувати.",["race:Undead"]="Повернувши посох, ви спиняєте Даларан, що загарбує магічні запаси Срібнолісся, і вбезпечуєте західні кордони Відступників."},sec={{t="Провідник лей-магії",b="Цим посохом Архімаг Атаерік спрямовував і приборкував лей-енергію в південному Срібноліссі. За дорученням Даларана Атаерік намагався знову пробудити давній вузол лей-енергії біля кордонів володінь магократії. Посох був незамінним знаряддям, щоб сплітати ці неосяжні навколишні потоки, і робив архімага грізною загрозою для сусідніх поселень Відступників."},{t="Трофей Гробниці",b="Стривожений магічним розширенням Даларана, Жрець Тіні Аллістер наказав убити Атаеріка й повернути посох. Коли Атаерік загинув, а посох здобули, зосереджена лей-енергія знову поринула в сон. Посох, принесений до Гробниці, став рішучою перемогою над задумами Даларана, хоча Відступники й далі пильно стежать за прихованою силою, що лишилася в землі."}},faq={{q="Кому належить Посох Атеріка?",a="Посох належить Архімагові Атаеріку — високопоставленому чарівникові Даларану, якого відрядили до Срібнолісся наглядати за пробудженням могутнього вузла лей-ліній.",al={"чий посох атеріка","власник атеріка","чий це посох"}},{q="Навіщо Жерцеві Тіні Аллістеру Посох Атеріка?",a="Жрець Тіні Аллістер у Гробниці хоче отримати посох як доказ смерті Архімага Атаеріка — і щоб переконатися, що спроби Даларану підкорити лей-лінії краю остаточно зірвано.",al={"чому аллістер хоче посох","призначення посоха склепу","хто забирає посох"}},{q="Що стається, коли в Архімага Атаеріка забирають посох?",a="Щойно Атаеріка вбито, а посох забрано, енергія лей-ліній, яку плели даларанці, розсіюється й засинає — і безпосередня магічна загроза Відступникам минає.",al={"що буде з лей-лінією","після перемоги над атеріком"}},{q="Де знайти Посох Атеріка?",a="Його забирають просто з тіла Архімага Атаеріка, який перебуває серед інших магів і вартових Даларану в їхньому таборі на півдні Срібнолісся.",al={"де взяти посох атеріка","місце атеріка"}}},fp="15,258,22.398.0,23.409.0,35.149.0,53.196.0,59.170.1,31.165.0"}
P.entries["item:athrikus-narassin-s-head"] = {n="Голова Атрікуса Нарассіна",s="Ця відрубана голова — доказ смерті Атрікуса Нарассіна, давнього чорнокнижника, що правив темні обряди на півночі Темного Узбережжя. Здобута на вершині зруйнованої вежі, вона підтверджує, що демонічну діяльність навколо Вежі Альталакса зірвано.",h="Ця відрубана голова — доказ смерті Атрікуса Нарассіна, давнього чорнокнижника, що правив темні обряди на...",kw={"атрікус нарассін","вежа альталакса","темне узбережжя","ковен","чорнокнижник","скверна"},ang={["class:Warlock"]="Майстерність Атрікуса в силах Скверни робила його грізним чаклуном, та його безрозсудна відкритість в Альталаксі й стала його погибеллю.",["race:NightElf"]="Знищивши Атрікуса Нарассіна, ви вичищаєте гнійну демонічну пошесть із давніх руїн калдореїв на північних берегах Калімдору."},sec={{t="Пошесть над Альталаксом",b="Засівши на самій верхівці Вежі Альталакса, Атрікус Нарассін очолював ковен темних чаклунів, що практикували магію Скверни на Темному Узбережжі. Давній і глибоко вкорінений, Нарассін керував викликанням демонів, яке загрожувало навколишнім нетрям. Із загибеллю Нарассіна ковен лишається без проводу й утрачає опору в краї, хоча порча, що лишилася, віщує: пильність знадобиться й надалі."}},faq={{q="Хто такий Атрікус Нарассін?",a="Атрікус Нарассін — прадавній і могутній чорнокнижник, що очолював культистів, які засіли у Вежі Альталакса на півночі Темного Узбережжя. З самої вершини шпиля він керував демонічними обрядами свого кола.",al={"хто такий атрікус","історія атрікуса","хто цей чорнокнижник"}},{q="Навіщо потрібна його голова?",a="Розвідникам Альянсу, що стежать за Вежею Альталакса, потрібен незаперечний доказ того, що верховного чорнокнижника вбито. Відтята голова підтверджує його загибель і засвідчує, що удар по демонічних силах удався.",al={"навіщо брати голову","призначення голови атрікуса","для чого голова"}},{q="Де знайти Атрікуса Нарассіна?",a="Він перебуває на самій вершині Вежі Альталакса на півночі Темного Узбережжя під пильною охороною відданих культистів і викликаних демонів.",al={"де знайти атрікуса","місце атрікуса","верх вежі олталакса"}},{q="Чи знищує його смерть демонічну загрозу остаточно?",a="Смерть Атрікуса завдає темним заклиначам тяжкого удару й розпорошує їхні нинішні задуми, але розвідники вважають, що демонічні сили зрештою знову зберуться, тож Темне Узбережжя доведеться боронити й надалі.",al={"чи зникли демони","чи очищена вежа","чи ми здолали культ"}}},fp="24,269,21.439.0,26.213.0,23.225.0,35.149.0,57.203.0"}
P.entries["item:bag-of-empty-ooze-containers"] = {n="Мішок Порожніх Посудин З-під Слизу",s="Мішок Порожніх Посудин З-під Слизу — набір стерильного скляного посуду, який видає гном-дослідник Ларіс Ґірдавдл в Айронфорджі. Підготовлений для делікатного збору зразків у полі, він містить порожні банки для чистих, незіпсованих зразків слизу з усього Азероту.",h="Мішок Порожніх Посудин З-під Слизу — набір стерильного скляного посуду, який видає гном-дослідник Ларіс...",kw={"мішок порожніх посудин з-під слизу","ларіс ґірдавдл","слиз","кратер ун'ґоро","сквернолісся","айронфордж","зразки"},ang={["faction:Alliance"]="Ларіс Ґірдавдл керує своїми природничими дослідженнями з Айронфорджа й посилає шукачів пригод Альянсу вглиб диких земель на кшталт Кратера Ун'Ґоро по важливі польові зразки.",["race:Gnome"]="Міцні, стійкі до хімікатів банки в мішку — приклад звичної гномської винахідливості: з ними польові дослідники можуть безпечно перевозити небезпечні їдкі зразки дикої природи."},sec={{t="Спорядження для польових досліджень",b="Вивчаючи химерну біологію слизунів Азероту, Ларіс Ґірдавдл збагнув, що слизові істоти швидко вбирають і віддзеркалюють зіпсованість свого довкілля. Дослідивши заражені рештки з місць на кшталт Сквернолісся, учений-гном замовив ці міцні банки, що витримують їдкі зразки й зберігають їх у природному стані. У торбі досить банок, щоб дослідник набрав чистого, незабрудненого слизу в диких, незайманих краях — передусім у первісній глушині Кратера Ун'Ґоро, де давні клейкі слизуни живуть, не знаючи демонічної скверни."}},faq={{q="Що в Мішку Порожніх Посудин З-під Слизу?",a="У мішку — десять порожніх банок для чистих зразків: особливих скляних посудин, у яких можна безпечно зберігати їдкий слиз, не псуючи й не забруднюючи зразок.",al={"що в мішку","вміст мішка","вміст посудин для слизу"}},{q="Хто дав ці посудини?",a="Їх дає Ларіс Ґірдавдл — ексцентричний гном-дослідник із Зали Дослідників в Айронфорджі, який вивчає, як слизи пристосовуються до довкілля.",al={"хто дає мішок зі слизом","мішок ларіса гірдодла","хто дає мішок порожніх посудин"}},{q="Які слизи мають збирати в ці банки?",a="Банки призначені для чистих, незіпсованих зразків слизу. На відміну від отруєних зразків зі Сквернолісся, чистий слиз можна зібрати з клейких слизів, що живуть у Кратері Ун'Ґоро.",al={"який слиз у банки","ціль для чистих зразків","де наповнювати банки"}},{q="Навіщо Ларісові чисті зразки слизу?",a="Ларіс з'ясував, що слизи вбирають властивості довкілля, наче жива губка. Щоб зрозуміти, як працює це пристосування, йому потрібен незіпсований зразок для порівняння з отруєними слизами з уражених земель.",al={"навіщо збирати чистий слиз","мета досліджень гірдодла","навіщо чисті слизи"}}},fp="28,267,24.585.0,48.171.0,30.176.0,51.186.0,38.235.0"}
P.entries["item:balnir-snapdragons"] = {n="Ротики Балніра",s="Ротики Балніра — яскраві квіти, що ростуть на Хуторі Балнірів у східній частині Галявин Тірісфалю. Вони від природи чутливі до магічних потоків, тож Відступникам слугують тонкими індикаторами: показують, як скверна Погибелі підповзає із сусідніх Чумних Земель.",h="Ротики Балніра — яскраві квіти, що ростуть на Хуторі Балнірів у східній частині Галявин Тірісфалю.",kw={"ротики балніра","хутір балнірів","галявини тірісфалю","анастасія гартвелл","артас","непереможний","чума"},ang={["class:Mage"]="Маги-Відступники вивчають Ротики Балніра як природні магічні провідники: їхня чутливість допомагає виміряти, як магічна зараза викривлює лей-лінії довкола.",["race:Undead"]="Для Відступників ці квіти — справжній дозор на східному кордоні: вони попереджають дослідників Андерсіті, якщо скверна Короля-Ліча почне захоплювати ґрунти Тірісфалю."},sec={{t="Цвіт серед руїни",b="Ці барвисті квіти колись доглядала Вара Балнір, ще до падіння Лордерона, і вони дивом пережили і загибель родини Балнірів, і піднесення Погибелі. Навіть коли принц Артас повернувся до оскверненої садиби, щоб підняти свого коня Інвінсібла, ротики й далі буйно цвіли, не торкнуті гниллю, що поглинала королівство довкола. Ця живучість перед темною магією робить їх помітною прикметою серед занепаду Галявин Тірісфалю."},{t="Магічні барометри",b="Ротики надзвичайно чутливі до магії в повітрі, тож стають живими барометрами магічної зарази. Анастасія Гартвелл і маги-Відступники в Андерсіті шукають свіжі зразки з квіткових ящиків на вікнах хутора. Передаючи рослини Королівському Аптекарському Товариству, Андерсіті сподівається дослідити їх і виміряти, як глибоко чума Короля-Ліча просочилася через кордон у ґрунти Тірісфалю."}},faq={{q="Де ростуть Ротики Балніра?",a="Вони ростуть у квітниках і на грядках довкола зруйнованого Хутора Балнірів на сході Галявин Тірісфалю, біля кордону із Західними Чумними Землями.",al={"де ротики балніра","де квіти","де квіти балніра"}},{q="Навіщо Анастасії Гартвелл ці ротики?",a="Ротики легко вбирають приховану магічну енергію. Анастасія Гартвелл хоче, щоб свіжі квіти доставили аптекарям Андерсіті, — так можна з'ясувати, чи магічна скверна Чумних Земель справді поширюється на Галявини Тірісфалю.",al={"навіщо збирати ротики","мета завдання хутора балнірів","ротики анастасії гартвелл"}},{q="Хто колись вирощував ці квіти?",a="Вони були гордістю й утіхою Вари Балнір, яка плекала їх на родинному хуторі, доки Третя війна не змела сільські поселення Лордерону.",al={"хто посадив ротики балніра","квіти балнірів вара","ротики родини балнірів"}},{q="Чи знищила Погибель квіти Балнірів?",a="Ні. Хоч як дивно, ротики й далі буйно цвіли навіть після загибелі Балнірів. Артас помітив, що вони вціліли, коли повернувся на хутір, щоб підняти свого коня Інвінсібла, але не торкнувся їх, аби його мертвотна присутність не зів'ялила пелюстки.",al={"чи чума вбила ротики","артас квіти балнірів"}}},fp="18,267,15.462.0,18.429.0,38.171.0,51.228.0,34.146.0,43.257.0"}
P.entries["item:baron-longshore-s-head"] = {n="Голова Барона Лонгшора",s="Ця відтята голова — доказ смерті Барона Лонгшора, капітана корабля флібустьєрів Південних морів «Безрозсудний». Ґазлоу оголосив публічну винагороду за рештки пірата, які можна впізнати, щоб захистити торгове судноплавство Раджета вздовж Узбережжя Крамарів.",h="Ця відтята голова — доказ смерті Барона Лонгшора, капітана корабля флібустьєрів Південних морів...",kw={"голова барона лонгшора","барон лонгшор","флібустьєри південних морів","ґазлоу","раджет","пірати"},ang={["race:Human"]="В оголошенні Ґазлоу зазначено, що Лонгшор походив із відлюдного королівства Ґілнеас, перш ніж узятися за морський розбій із Флібустьєрами Південних морів."},sec={{t="Ціна за голову пірата",b="Діючи з таборів на Узбережжі Крамарів на південь від Раджета, Барон Лонгшор керував нападами Флібустьєрів Південних морів на місцеві торгові судна. Його флагман, «Безрозсудний», прямо загрожував гоблінським торговим шляхам, що з'єднують Калімдор зі Східними Королівствами. Ґазлоу, Головний Інженер Раджета, оголосив винагороду за Лонгшора, вимагаючи доказу смерті, за яким пірата можна впізнати. Принесена голова пірата виконує умови угоди й приносить грошову винагороду від портової влади."}},faq={{q="Хто такий Барон Лонгшор?",a="Це капітан піратів родом із людського королівства Ґілнеас. Він очолював Флібустьєрів Південних морів із таборів на Торговому Узбережжі на південь від Раджета й тероризував морські шляхи на своєму кораблі «Безоглядний».",al={"барон лонгшор","хто такий лонгшор","капітан лонгшор"}},{q="Кому потрібна голова Барона Лонгшора?",a="Оголошення про розшук вивісив Ґазлоу, гоблінський ватажок Раджета. Флібустьєри Південних морів грабували торгові кораблі Раджета, тож Ґазлоу вимагає впізнавані останки Лонгшора, щоб торгівля в його гавані йшла без перешкод.",al={"кому потрібна голова","кому здати","нагорода ґазлоу"}},{q="Де знайти Барона Лонгшора?",a="Лонгшор обходить три піратські табори Південних морів на узбережжі на південь від Раджета, трохи на північ від Твердині Північної Варти на Торговому Узбережжі.",al={"де лонгшор","місце лонгшора","де з'являється барон лонгшор"}},{q="Яким кораблем командував Барон Лонгшор?",a="Він був капітаном «Безоглядного» — грізного судна, що грабувало торгові кораблі у Великому морі біля берегів Пусток.",al={"корабель лонгшора","безтурботний","корабель безтурботний"}}},fp="22,247,22.499.0,24.211.0,33.242.0,31.151.0,38.128.0"}
P.entries["item:barrel-of-barleybrew-scalder"] = {n="Барило Окропу Барліброю",s="Барило Окропу Барліброю — діжка міцного елю, звареного родиною Барліброю, щоб довести свою броварську майстерність перед головними суперниками. Його довіряють таємним кур'єрам, які мають пробратися до Ґуральні Тандербрю в Хараносі та влаштувати хитру дегустаційну диверсію.",h="Барило Окропу Барліброю — діжка міцного елю, звареного родиною Барліброю, щоб довести свою броварську...",kw={"барило","окріп барліброю","ель","тандербрю","харанос","ґуральня","марлет барліб'ю","суперництво"},ang={["class:Rogue"]="Відволікти вартового в льоху й пронести важку контрабанду до охоронюваного сховку — кумедна й безпечна вправа в класичному дворфійському підступі.",["race:Dwarf"]="Для дворфів варіння елю — і мистецтво, і кривавий спорт; узяти участь у льохових інтригах про те, чий рецепт кращий, — чи не улюблена розвага Дун Мороґу."},sec={{t="Запекла ворожнеча в Дун Мороґу",b="Броварство для дворфів Дун Мороґу — справа серйозна, і мало яке суперництво палає гарячіше за ворожнечу між Тандербрю та Барліброю. Поки Тандербрю тішаться широкою славою та почесним місцем у своїй людній ґуральні в Хараносі, Марлет Барліб'ю відмовляється сидіти в їхній тіні. Замість покладатися лише на відкриті шинки, Марлет варить вогняний «Окріп», щоб довести: її рецепти нічим не поступаються. Вона сподівається, що нічого не підозрюючи, відвідувачі скуштують напій і збагнуть: Тандербрю не мають монополії на добрий дворфійський трунок."},{t="Підступ у льоху",b="Барило мають непомітно пронести просто до льохів під Ґуральнею Тандербрю й підмінити ним діжку місцевого улюбленця — Громового Елю. Задум не отруйний і не руйнівний — це зухвалий дворфійський жарт, спрямований на вражену гордість: щоб наступна партія, яку подадуть нагорі, потай виявилася міцним окропом Барліброю."}},faq={{q="Що в Барилі Окропу Барліброю?",a="У ньому фірмовий «окріп» Марлета Барліб'ю — міцний дворфський напій, зварений, щоб позмагатися зі славетними рецептами родини Тандербрю.",al={"вміст окропу барліброю","який це ель","що таке окріп"}},{q="Навіщо Марлету підмінити це барило?",a="Марлет визнає, що Тандербрю варять добрі напої, але хоче збити з них пиху: нехай відвідувачі погребу ненароком скуштують його напій і переконаються, що Барліброю варять не гірше, а то й краще.",al={"чому підмінювати барила","причина ворожнечі","чому марлет підкидає напій"}},{q="Куди слід віднести це барило?",a="Його зносять у погріб під Ґуральнею Тандербрю в Хараносі й ставлять на стелаж замість бочки Громового Елю, яку саме мають відкоркувати.",al={"куди поставити барило","місце барила окропу","погріб винокурні"}},{q="Чи має цей напій комусь зашкодити?",a="Ні. Це просто міцний ель від суперників. Ворожнеча між родинами запекла, але це питання професійної гордості, а не злоби.",al={"чи отруєний окріп","чи це отрута","чи комусь зашкодить"}}},fp="28,287,27.543.0,24.337.1,48.135.0,42.215.0,26.155.0,33.171.0"}
P.entries["item:barrel-of-shimmer-stout"] = {n="Барило Мерехтливого Стауту",s="Свіжозварена діжка експериментального дворфійського елю Реджолда Барліброю, створеного в холодних просторах Дун Мороґу. Напій відомий тим, що дає міцного стусана й нібито прояснює зір, і призначений у подарунок вартовим, які чатують на високих гірських перевалах.",h="Свіжозварена діжка експериментального дворфійського елю Реджолда Барліброю, створеного в холодних просторах...",kw={"мерехтливий стаут","барило","реджолд барліброю","ель","лох модан","горянин","дун мороґ"},ang={["profession:Cooking"]="Дворфійські елі раз у раз розсувають межі кулінарних експериментів, поєднуючи міцне бродіння з витривалими гірськими інгредієнтами, щоб витримати лютий холод.",["race:Dwarf"]="Броварство — наріжний камінь культури Айронфорджа, а доправити щойно вдосконалений стаут родичеві на варті — почесна гірська традиція."},sec={{t="Гордість бровара",b="Мерехтливий Стаут, який Реджолд Барліброю зварив, зібравши рідкісні інгредієнти по всьому Дун Мороґу, — найновіший тріумф уславленої родини Барліброю. Дворфійські бровари ставляться до свого ремесла смертельно серйозно й невпинно змагаються, хто зварить ситніше вариво, здатне відігнати крижаний гірський холод. Останній рецепт Реджолда покликаний не лише зігріти нутро, а й загострити чуття тих, хто служить на крижаному вітрі."},{t="Припаси для варти",b="Це барило призначене горянину Велларту Барліброю, який стоїть на варті біля південної вежі на перевалі, що веде до Лох Модану. На самотньому прикордонні горяни терплять пронизливий холод і довгі чергування між сутичками з трогами та звіриною. Свіжа діжка родинного елю — це водночас і жаданий смак дому, і підбадьорливий тонік, достатньо міцний, щоб втомлений вартовий заприсягся, ніби бачить крізь темряву."}},faq={{q="Що в Барилі Мерехтливого Стауту?",a="У ньому Мерехтливий Стаут — новий дворфський рецепт Реджолда Барліброю. Напій славиться неймовірно міцним ударом: кожен, хто його скуштує, відчуває приплив сил, а очі в нього буквально сяють.",al={"що таке мерехтливий стаут","який це ель","мерехтливий стаут напій"}},{q="Хто зварив цей стаут?",a="Цей ель зварив Реджолд Барліброю з шанованого клану Барліброю з Дун Мороґа, який довго вдосконалював рецепт, щоб вразити родичів.",al={"хто зварив мерехтливий стаут","пивовар мерехтливого стауту","реджолд барліброй"}},{q="Для кого це барило?",a="Воно призначене братові Реджолда, горянинові Велларту Барліброю, що несе варту на південній вежі при дорозі до Лох Модану.",al={"кому барило","куди стаут","велларт барліброй"}},{q="Як Мерехтливий Стаут діє на того, хто його п'є?",a="Окрім міцного хмелю, стаут дає такий потужний поштовх, що очі блищать, а тому, хто п'є, здається, ніби він бачить у непроглядній темряві. Тож пильні горяни його неабияк полюбили.",al={"дія мерехтливого стауту","чи бачиш у темряві","що робить мерехтливий стаут"}}},fp="23,272,16.452.0,22.454.0,39.221.0,30.150.0,29.145.0,61.208.0"}
P.entries["item:barrel-of-thunder-ale"] = {n="Барило Грозового Елю",s="Барило Грозового Елю — цінна діжка фірмового трунку Хараноса, винесена просто з льоху Ґуральні Тандербрю. Підмінене на діжку Окропу Барліброю від Марлет, воно слугує незаперечним доказом підступу в броварському суперництві, що дедалі розпалюється.",h="Барило Грозового Елю — цінна діжка фірмового трунку Хараноса, винесена просто з льоху Ґуральні Тандербрю.",kw={"барило","громовий ель","тандербрю","харанос","марлет барліб'ю","село брюнолл","підміна"},ang={["class:Rogue"]="Прослизнути до охоронюваного льоху та підмінити важкі барила елю, не здійнявши тривоги, — класичний і практичний вияв скрадливості та спритності.",["race:Dwarf"]="Для дворфів броварство — серйозна справа й висока політика; підмінити цінну діжку суперницького клану в їхньому ж льоху — зухвала образа."},sec={{t="Гіркий обмін",b="У Дун Мороґу змагання між майстрами-броварами сягає глибоко, і мало яка суперечка запекліша за ворожнечу між Тандербрю з Хараноса та Барліброю із Села Брюнолл. Марлет Барліб'ю задумала підкинути барило власного Окропу Барліброю до льоху суперників, щоб відвідувачі Тандербрю скуштували її вариво замість їхнього. Це важке барило Громового Елю захопили під час обміну й витягли під самим носом у місцевої варти як речовий доказ того, що підміна вдалася."}},faq={{q="Що в цьому барилі?",a="У ньому Громовий Ель — славетний напій, який варить родина Тандербрю в Хараносі. По всьому Дун Мороґу його знають як міцний дворфський ель.",al={"вміст грозового елю","що таке грозовий ель"}},{q="Звідки це барило?",a="Його забирають просто з погреба Ґуральні Тандербрю в Хараносі під час таємної доставки суперницького напою Марлета.",al={"де його взяти","місце грозового елю"}},{q="Кому потрібне це барило?",a="Марлетові Барліб'ю із Села Брюнолл на заході. Він чекає, що йому принесуть барило на доказ того, що його «окріп» успішно підкинуто між бочки Тандербрю.",al={"кому нести грозовий ель","завдання марлета барліброя"}},{q="Навіщо забрали барило?",a="Марлет хотів мати відчутний доказ, що хтось таки прокрався в погріб Тандербрю, прошмигнув повз вартового ґуральні й зіпсував запаси суперників.",al={"чому красти грозовий ель","історія гіркого суперництва"}}},fp="21,266,14.510.0,27.154.0,32.140.0,22.181.0,25.158.0"}
P.entries["item:barrow-key"] = {n="Ключ від Притулку",s="Ключ від Притулку — один із трьох друїдських ключів, захованих у Лігві Кігтя на Піку Кам'яного Кігтя. Його тримають замкненим у схованці притулку, щоб уберегти давні скарби, запечатані в сховищі лігва.",h="Ключ від Притулку — один із трьох друїдських ключів, захованих у Лігві Кігтя на Піку Кам'яного Кігтя.",kw={"ключ від притулку","лігво кігтя","пік кам'яного кігтя","друїди","ключ воротаря","кігтистий ключ","ключ сплячих"},ang={["class:Druid"]="Ключ — частина давнього охоронного обряду, який друїди Лігва Кігтя створили, щоб уберегти священні речі у своєму підземному святилищі.",["faction:Horde"]="Агенти Орди в Горах Кам'яного Кігтя вибивають відомості з полонених нічних ельфів, щоб знайти цей ключ і пограбувати особисте сховище друїдів."},sec={{t="Запобіжник хранителів",b="У підземних притулках Лігва Кігтя друїди нічних ельфів наклали складні захисні чари, щоб уберегти свої реліквії від непроханих гостей. Ключ від Притулку — одна частинка цього багатошарового замка, захована в особливій схованці серед підземних ходів. Щоб дістатися до нього, потрібен Ключ Воротаря, — тож здобути його може лише той, хто знає оборонну систему друїдів."},{t="Відімкнути сховище",b="Разом із Кігтистим Ключем і Ключем Сплячих Ключ від Притулку підходить до одного з трьох вигадливо вирізьблених замків у кам'яному вівтарі глибоко в Лігві Кігтя. Коли всі три ключі повертають водночас, захисні чари розвіюються й відкривають приховане сховище друїдських реліквій тому, хто зумів зламати захист."}},faq={{q="Для чого потрібен Ключ від Притулку?",a="Ключ від Притулку разом із Кігтистим Ключем і Ключем Сплячих відмикає Скарб Лігва Кігтя — кам'яну скриню з друїдськими реліквіями глибоко в Піку Кам'яного Кігтя.",al={"для чого ключ від притулку","що відчиняє ключ від притулку","використання ключа від притулку"}},{q="Де схований Ключ від Притулку?",a="Він замкнений у схованці притулку, схожій на замаскований настінний смолоскип, глибоко в звивистих тунелях Лігва Кігтя на Піку Кам'яного Кігтя.",al={"де ключ від притулку","місце ключа від притулку","знайти ключ від притулку"}},{q="Як відчинити схованку з Ключем від Притулку?",a="Спершу вам треба знайти Ключ Воротаря, який друїди сховали в маленькому ліхтарі біля головного входу до Лігва Кігтя.",al={"відчинити схованку притулку","відімкнути ключ від притулку","ключ воротаря притулку"}},{q="Хто сховав Ключ від Притулку в Лігві Кігтя?",a="Друїди нічних ельфів, що жили на Піку Кам'яного Кігтя, придумали хитромудру систему захисту, щоб їхні могутні артефакти не потрапили до ворожих рук, і заховали окремі ключі в різних куточках лігва.",al={"хто зробив ключ від притулку","хто сховав ключі в лігві кігтя"}}},fp="10,195,22.413.0,19.315.1,32.174.0,31.149.0,52.136.0,43.205.0"}
P.entries["item:bartleby-s-mug"] = {n="Кухоль Бартлбі",s="Кухоль Бартлбі — особистий кухоль упертого забіяки Бартлбі зі Стормвінда. Віддаючи його лише після бійки в таверні й допивши до останньої краплі, Бартлбі тим самим засвідчує, що воїн уміє силою переконати непоступливого суперника.",h="Кухоль Бартлбі — особистий кухоль упертого забіяки Бартлбі зі Стормвінда.",kw={"кухоль бартлбі","бартлбі","воїн","бійка","таверна","стормвінд"},ang={["class:Warrior"]="Відібрати цей кухоль у Бартлбі — один із перших обрядів посвяти для юних воїнів Альянсу: він учить покладатися на витримку й силу, коли слова не допомагають."},sec={{t="Трофей забіяки",b="Для звичайного завсідника таверни Кухоль Бартлбі — не більше ніж простий посуд, який міцно стискає в руці відомий упертий пияк. Та для воїна-новачка, що навчається в Стормвінді, відібрати в Бартлбі цей кухоль — перевірка чистої фізичної переваги. Бартлбі не віддасть улюбленого кухля, доки його не повалять, — і навіть тоді наполягає, щоб допити все до останньої краплі, перш ніж вручити його як трофей."}},faq={{q="Для чого потрібен Кухоль Бартлбі?",a="Кухоль Бартлбі — доказ перемоги у випробуванні воїна. Принісши його наставникові, воїн показує, що впорався з упертим корчемним забіякою й змусив його віддати найдорожчу річ.",al={"призначення кухля бартлбі","навіщо кухоль бартлбі","що робить кухоль"}},{q="Кому спершу належав кухоль?",a="Кухоль належить Бартлбі — задиристому п'яниці, що тільки й знає пити та битися. Він не віддасть кухля, доки молодий воїн не здолає його в кулачному бою, та й тоді — лише допивши свій напій.",al={"хто такий бартлбі","власник бартлбі","у кого кухоль"}},{q="Хто просить принести Кухоль Бартлбі?",a="Кухоль приносять Берлґарду, наставникові воїнів у Стормвінді, який спостерігає за бійкою й вимагає кухоль як доказ, перш ніж продовжити бойову науку воїна.",al={"хто хоче кухоль","кому віддати кухоль бартлбі","здати кухоль бартлбі"}}},fp="14,258,17.433.0,32.228.0,28.222.0,28.167.0"}
P.entries["item:bathran-s-hair"] = {n="Волосся Батрана",s="Волосся Батрана — рідкісна ніжна трава, що росте серед руїн Притулку Батрана на північному заході Ашенвалю. Нічноельфійські перекази славлять її могутню цілющу силу: кажуть, ця рослина лікує недуги не лише тіла, а й духу.",h="Волосся Батрана — рідкісна ніжна трава, що росте серед руїн Притулку Батрана на північному заході Ашенвалю.",kw={"волосся батрана","притулок батрана","травництво","ліки","відступники","ашенваль"},ang={["profession:Herbalism"]="Досвідчені травники мають неабияку перевагу в пошуках Волосся Батрана: гостре око на дикі рослини допомагає їм помітити заховані в'язки серед уламків.",["race:NightElf"]="Для калдореїв уберегти священні рослини на кшталт Волосся Батрана від осквернення Відступниками — питання і виживання, і збереження їхньої прадавньої батьківщини."},sec={{t="Ліки для духу",b="Волосся Батрана, що росте в тіні прадавніх руїн на північ від Посту Маестри, здавна цінують цілителі нічних ельфів. На відміну від звичайних лікарських рослин, що загоюють прості тілесні рани, ця трава, кажуть, має силу зцілювати глибокі недуги духу. Коли юна нічна ельфійка в Астранаарі занедужує підступною, невідступною хворобою, травник Орендил Броудліф шукає пасма цієї рідкісної рослини, щоб зварити рятівні ліки."},{t="Збирання серед руїн",b="Знайти Волосся Батрана стало небезпечно. Траву можна знайти в покинутих в'язках рослин і під купами листя, розкиданими по Притулку Батрана, неподалік від межі з Темним Узбережжям. А ще серед руїн закріпилися аптекарі Відступників та їхні неживі посіпаки, які збирають місцеві рослини для власних темних, нечистих зілль."}},faq={{q="Для чого потрібне Волосся Батрана?",a="Цією травою цілителі нічних ельфів лікують тяжкі недуги, що виходять за межі звичайної хвороби. Зокрема, Орендил Броудліф додає її до цілющого відвару, щоб урятувати вмирущу дитину, чий дух поволі згасає.",al={"що робить волосся батрана","призначення волосся батрана","використання волосся батрана"}},{q="Де росте Волосся Батрана?",a="Його можна знайти лише в Притулку Батрана — прадавньому зруйнованому поселенні на півночі Ашенвалю, на схід від головного шляху, що веде на північ до Темного Узбережжя.",al={"де знайти волосся батрана","місце волосся батрана","де волосся батрана"}},{q="Чому Відступники цікавляться Притулком Батрана?",a="Відступники, що вдерлися в Ашенваль, отаборилися серед руїн, щоб збирати місцеві рослини й магічні реагенти. Їхня присутність тривожить нічних ельфів: ті бояться того, що алхіміки-нежить зварять із рослин цього краю.",al={"чому нежить у притулку батрана","відступники в притулку батрана","нежить батран"}},{q="Хто такий Орендил Броудліф?",a="Орендил Броудліф — травник із Посту Маестри на заході Ашенвалю. Він сумлінно вивчає місцеві рослини й готує ліки для мандрівників і поранених захисників лісу.",al={"орендил броудліф","хто хоче волосся батрана"}}},fp="14,252,23.451.0,24.381.1,32.224.0,31.151.0,51.238.0,25.201.0"}
P.entries["item:battleboar-flank"] = {n="Бік Бойового Вепра",s="Бік Бойового Вепра — ситний шмат м'яса, здобутий із лютих бойових вепрів, яких вишколюють шипогриви Щетиноспинні в Малгорі. Молоді мисливці збирають його довкола Табору Нарачі: це і доказ знищеної загрози, і поживна їжа для племені тауренів.",h="Бік Бойового Вепра — ситний шмат м'яса, здобутий із лютих бойових вепрів, яких вишколюють шипогриви...",kw={"бойовий вепр","бік","м'ясо","щетиноспинні","табір нарачі","ґрулл гоквінд","малгор"},ang={["profession:Cooking"]="Хоч м'ясо звірів, вирощених для бою, грубе й має присмак дичини, бік дає вдосталь багатого, ситного м'яса, якщо повільно виварити його в спільній табірній юшці.",["race:Tauren"]="Полювання на бойових вепрів, що вдираються в їхні землі, вчить молодих тауренів: захист батьківщини нерозривний зі священним обов'язком шанувати й використовувати щедроти Матері-Землі."},sec={{t="Пожива з загрози Щетиноспинних",b="Шипогриви Щетиноспинні, що причаїлися в Яру Тернистого Клинка, вишколили лютих бойових вепрів, аби ті вдиралися на мисливські угіддя тауренів. Ці агресивні звірі — пряма небезпека для молодих тауренів, що входять у зрілість у Таборі Нарачі, та ніщо, взяте в природи, не марнується. Ґрулл Гоквінд наказує мисливцям-новачкам зрізати з повалених звірів боки разом із рилами. Шматки боків дають багате, поживне м'ясо, яке виварюють на ситну юшку для молоді племені, — так зброя шипогривів стає живленням для племені."}},faq={{q="Для чого потрібен Бік Бойового Вепра?",a="Боки бойових вепрів збирають молоді мисливці з Табору Нарачі за дорученням Ґрулла Гоквінда. З м'яса варять юшку для тауренської молоді, тож навіть переможені вороги допомагають прогодувати плем'я.",al={"для чого бік бойового вепра","що таке бік бойового вепра","навіщо збирати м'ясо бойових вепрів"}},{q="Де добути Боки Бойового Вепра?",a="Їх зрізають з агресивних бойових вепрів і бойових вепрів Щетиноспинних, що никають біля Яру Тернистого Клинка на схід від Табору Нарачі на Плато Червоної Хмари.",al={"джерело боку бойового вепра","звідки боки бойових вепрів","хто дропає боки бойових вепрів"}},{q="Чому бойові вепри вдираються на землі тауренів?",a="Цих вепрів розводять і муштрують шипогриви Щетиноспинних, щоб ті були злі й люті. Що більше наростає ворожнеча між Щетиноспинними й тауренами, то частіше шипогриви женуть вимуштруваних звірів на споконвічні мисливські угіддя племені, аби дошкулити прибульцям.",al={"чому бойові вепри нападають","квілборги вепри мулґор","бойові вепри брамблейду"}}},fp="16,266,38.545.0,36.226.0,34.149.0,51.256.0"}
P.entries["item:battleboar-snout"] = {n="Рило Бойового Вепра",s="Рило Бойового Вепра здобувають з агресивних вепрів, яких вишколюють шипогриви Щетиноспинні в Малгорі. Молоді мисливці-таурени збирають їх і як доказ проріджування загарбницької загрози, і як ситний складник племінної кухні Табору Нарачі.",h="Рило Бойового Вепра здобувають з агресивних вепрів, яких вишколюють шипогриви Щетиноспинні в Малгорі.",kw={"бойовий вепр","рило","щетиноспинні","табір нарачі","ґрулл гоквінд","юшка","малгор"},ang={["profession:Cooking"]="Жорсткі частини на кшталт рил треба довго виварювати на вогні, тож вони стали основними складниками племінних юшок біля багаття.",["race:Tauren"]="Узяти рило разом із м'ясом — означає шанувати рівновагу Матері-Землі: хижака, що вдирається в землі, стримано, а молодь Табору Нарачі нагодовано."},sec={{t="Трофеї та припаси",b="У тіні Плато Червоної Хмари шипогриви Щетиноспинні вишколюють у Яру Тернистого Клинка злісних бойових вепрів, аби ті промацували мисливські угіддя тауренів. Коли Ґрулл Гоквінд посилає молодих сміливців дати відсіч цьому вторгненню, рило стає незаперечним доказом поваленого звіра. Табір Нарачі не марнує жодної частини здобичі: таурени використовують ці рила разом зі шматками боків, щоб готувати багаті, поживні юшки для своєї молоді."}},faq={{q="Для чого потрібні Рила Бойового Вепра?",a="Ґрулл Гоквінд просить молодих мисливців Табору Нарачі збирати їх разом із боками. Вони доводять, що небезпечних вепрів убито, а потім ідуть у казани — на юшку для молоді племені.",al={"для чого рило бойового вепра","навіщо зберігати рила","що ґрулл робить із рилами"}},{q="Звідки ці рила?",a="Їх зрізають з бойових вепрів і бойових вепрів Щетиноспинних, що водяться на околицях Плато Червоної Хмари та в Яру Тернистого Клинка на сході.",al={"де знайти бойових вепрів","хто дропає рила","місце бойових вепрів"}},{q="Чому бойові вепри вдираються на землі тауренів?",a="Ворожі шипогриви Щетиноспинних вимуштрували цих вепрів бути надзвичайно лютими, і ті просуваються з Яру Тернистого Клинка на споконвічні мисливські угіддя племені.",al={"чому вепри нападають","квілборги вепри","бойові вепри брамблейду"}}},fp="16,258,23.445.0,36.227.0,32.149.0,51.180.0"}
P.entries["item:battleworn-axe"] = {n="Зужита в Боях Сокира",s="Зужиті в боях сокири — грубі, поцятковані зазубринами сокири орків Блекрок, що вторглися в Гори Редріджу. Маршал Марріс у Лейкширі приймає ці трофейні клинки як речовий доказ загибелі загарбників, які загрожують місцевим жителям.",h="Зужиті в боях сокири — грубі, поцятковані зазубринами сокири орків Блекрок, що вторглися в Гори Редріджу.",kw={"зужита в боях сокира","блекрок","орки","маршал марріс","лейкшир","редрідж","трофей"},ang={["faction:Alliance"]="Кожна сокира, принесена до Лейкширу, — це на одного загарбника менше, хто загрожує беззахисним жителям Редріджу, поки головні сили Стормвінда деінде.",["profession:Blacksmithing"]="Попри зазубрені краї й пощерблені леза, ці грубі залізні сокири свідчать про міцні традиції важкого кування, притаманні зброярству Блекрок."},sec={{t="Трофей загарбника",b="Ці важкі щербаті сокири — звичайне спорядження грабіжників Блекрок, які просуваються на південь від Палаючих Степів до Редріджу. Для Маршала Марріса й знесиленої міської варти Лейкширу вони важливі з двох причин: кожна така сокира означає, що ще один орк-мародер поліг, а заразом показує, наскільки добре озброєний загін, що підступає до міста."},{t="Загроза на пагорбах",b="Загарбники Блекрок укріпилися у Фортеці Кам'яної Варти й закріпилися в південно-східних закутках Редріджу, фактично замкнувши містян у Лейкширі. Кожна сокира, відібрана в нападників, зменшує арсенал загону й розчищає дороги для мандрівників Альянсу."}},faq={{q="Що таке Зужита в Боях Сокира?",a="Це груба, добре пошарпана в боях зброя ближнього бою, яку носять орки Блекрок у Горах Редріджу. Шукачі пригод збирають ці сокири як доказ того, що загарбників убито.",al={"що за зужита в боях сокира","що це за сокири","сокира чорної скелі"}},{q="Кому в Лейкширі потрібні ці сокири?",a="Маршал Марріс, командир варти Лейкширу, просить їх, щоб пересвідчитися, що загрозу Блекрок справді відкидають від міських земель.",al={"хто бере зужиті сокири","хто дає завдання на сокири","маршал маррис сокири"}},{q="Звідки ці сокири?",a="Їх забирають в орків Блекрок по всьому Редріджу — особливо довкола Фортеці Кам'яної Варти на півночі та в розкиданих таборах орків на південному сході.",al={"звідки падають зужиті сокири","фарм зужитих сокир","які орки їх мають"}},{q="Як орки взагалі опинилися в Редріджі?",a="Клан Блекрок рушив на південь гірськими перевалами з Палаючих Степів, захопив Фортецю Кам'яної Варти й плюндрує північ і схід Редріджу, щоб узяти Лейкшир у лещата.",al={"чому орки чорної скелі в редріджі","вторгнення в стонвотч","причина загрози чорної скелі"}}},fp="14,237,20.358.0,23.317.0,25.171.0,34.151.0,30.164.0,48.186.0"}
P.entries["item:berard-s-journal"] = {n="Щоденник Берарда",s="Щоденник Берарда — дослідницькі нотатки Аптекаря Берарда, написані до того, як він став жертвою прокляття Архімага Аруґала. Книга, що лишилася в Селі Пайрвуд, описує, як Берард вивчав давню чуму, яка колись знищила все живе у водах Озера Лордамер, тож для Королівського Аптекарського Товариства вона дуже цінна.",h="Щоденник Берарда — дослідницькі нотатки Аптекаря Берарда, написані до того, як він став жертвою прокляття...",kw={"щоденник берарда","аптекар берард","аруґал","село пайрвуд","озеро лордамер","нова чума","аптекар ренферрел"},ang={["faction:Horde"]="Вирушаючи в Село Пайрвуд по втрачені дослідження, ви допомагаєте Відступникам міцно закріпитися в Срібноліссі.",["race:Undead"]="Кожна крихта знань про отрути допомагає Королівському Аптекарському Товариству здобути зброю, здатну захистити Відступників і від Погибелі, і від живих ворогів."},sec={{t="Втрачені дослідження Озера Лордамер",b="Доки Архімаг Аруґал не напустив свою тіньову магію на Срібнолісся, Аптекар Берард вважався одним із найперспективніших умів Королівського Аптекарського Товариства. Він працював у Селі Пайрвуд і зосередився на давній, лютій заразі, яка століття тому винищила все живе в Озері Лордамер. Коли прокляття Аруґала охопило село, розум Берарда зламався, і він став ще одним бездумним рабом. Докладні польові нотатки лишилися на книжковій полиці в його кімнаті в корчмі Села Пайрвуд."},{t="Паливо для Нової Чуми",b="Хоч сам Берард для Товариства втрачений, його дослідження вціліли. Аптекар Ренферрел у Склепі розуміє стратегічну цінність щоденника й посилає агентів-Відступників у вороже село, щоб його забрати. Нотатки про давню отруту озера закладають важливе підґрунтя для Головного Аптекаря Фаранелла й Товариства в Апотекаріумі — основу, на якій Відступники варитимуть власну Нову Чуму."}},faq={{q="Хто такий Аптекар Берард?",a="Аптекар Берард — обдарований член Королівського Аптекарського Товариства, що жив у Селі Пайрвуд. Він вів важливе дослідження давніх отрут, коли Архімаг Аруґал наклав на край своє прокляття, зламавши розум Берарда й поневоливши його.",al={"хто такий берард","історія берарда","аптекар берард"}},{q="Де знайти Щоденник Берарда?",a="Щоденник стоїть на книжковій полиці в колишньому кабінеті Берарда на горішньому поверсі корчми в Селі Пайрвуд, на далекому півдні Срібнолісся.",al={"де знайти щоденник берарда","місце щоденника","де книга"}},{q="Які дослідження записано в щоденнику?",a="У щоденнику описано, що Берард дізнався про первісну заразу, яка в давнину вигубила всіх водяних істот в Озері Лордамер. Королівське Аптекарське Товариство сподівається використати ці отруйні властивості для власної хімічної зброї.",al={"що в щоденнику","дослідження берарда","зміст щоденника"}},{q="Навіщо Аптекареві Ренферрелу щоденник?",a="Ренферрел прагне вберегти всі корисні наукові надбання, доки їх не знищено чи не втрачено назавжди. Унікальні спостереження Берарда щодо зарази з Озера Лордамер дають важливі складники, без яких Головний Аптекар Фаранелл в Андерсіті не створить нову чуму Відступників.",al={"навіщо ренферрелу щоденник","завдання щоденника ренферрела"}}},fp="16,331,31.542.0,23.440.1,26.248.0,32.154.0,41.247.0,47.272.0"}
P.entries["item:bernice-s-necklace"] = {n="Намисто Берніс",s="Намисто Берніс — пам'ятна родинна реліквія «Тітоньки» Берніс Стоунфілд із Ферми Стоунфілдів у Лісі Елвінн. Колись її покійний чоловік носив цю прикрасу як талісман на удачу під час військової служби; дрібничку загубили біля Копальні Фарґодіп, і її поцупив спритний кобольд.",h="Намисто Берніс — пам'ятна родинна реліквія «Тітоньки» Берніс Стоунфілд із Ферми Стоунфілдів у Лісі Елвінн.",kw={"намисто","берніс стоунфілд","золотозуб","кобольд","копальня фарґодіп","реліквія"},ang={["faction:Alliance"]="Намисто — тихе нагадування про важку ціну, яку тривалі військові кампанії Стормвінда стягують із простих фермерських родин по всьому Лісі Елвінн."},sec={{t="Загублений талісман солдата",b="Хоч тутешні знають його як намисто Берніс, спершу воно належало покійному чоловікові Тітоньки Берніс Стоунфілд. Ветеран військових кампаній Стормвінда, він брав талісман із собою в бій як запоруку удачі. За словами Берніс, біда сталася лише раз — під час його останнього походу, єдиної виправи, у яку він забув узяти щасливе намисто. Після його смерті ця пам'ятка лишилася одним із найдорожчих скарбів Берніс на Фермі Стоунфілдів."},{t="Украдене падложерами",b="Реліквія зникла після того, як малого Біллі Маклура застали за грою біля Копальні Фарґодіп, де він упустив блискучу дрібничку, досліджуючи околиці. Блиск привернув око Золотозуба — сумнозвісного кобольда, що чаївся в копальні. Як і всі його родичі, ласий до яскравих і цінних дрібничок, Золотозуб ховав намисто серед своєї підземної здобичі, доки його не повернули згорьованій удові."}},faq={{q="Кому спершу належало це намисто?",a="Намисто належало покійному чоловікові Тітоньки Берніс Стоунфілд — він носив його як оберіг у військових походах за Стормвінд.",al={"чиє було намисто","власник намиста берніс","намисто чоловіка"}},{q="Як намисто опинилося в кобольдів?",a="Біллі Маклур розповідає, що бачив, як великий кобольд із золотим зубом підібрав намисто біля Копальні Фарґодіп і поніс геть. Тітонька Берніс сподівається, що його вдасться повернути.",al={"як воно загубилося","чому золотозуб його має","хто забрав намисто"}},{q="Чому намисто таке важливе для Тітоньки Берніс?",a="Це дорога пам'ять про її покійного чоловіка. Берніс сумно згадує, що він завжди вірив, ніби намисто береже його в бою, — і загинув на війні саме того дня, коли ненароком залишив його вдома.",al={"чому берніс його хоче","історія чоловіка берніс","чи намисто магічне"}},{q="Хто такий Золотозуб?",a="Золотозуб — відомий кобольд-збирач, що влаштував собі лігво в Копальні Фарґодіп у Лісі Елвінн. Він любить збирати блискучі дрібнички, тож і загублене неподалік намисто привласнив собі.",al={"що таке золотозуб","історія золотозуба","у кого намисто"}}},fp="18,294,22.488.0,20.407.1,35.155.0,45.163.0,51.211.0,17.198.0"}
P.entries["item:besseleth-s-fang"] = {n="Ікло Бесселет",s="Ікло Бесселет — величезний отруйний зуб, вирваний у велетенської павучихи Бесселет у Каньйоні Сішир. Принесене як доказ її загибелі, воно означає, що смертельна загроза, яка чатувала на стежках Гір Кам'яного Кігтя, усунута.",h="Ікло Бесселет — величезний отруйний зуб, вирваний у велетенської павучихи Бесселет у Каньйоні Сішир.",kw={"ікло бесселет","бесселет","каньйон сішир","павуки","гори кам'яного кігтя","стежка павутинника"},ang={["class:Hunter"]="Отруйний зуб завдовжки два фути, здобутий у павучої матріархині — найлютішої хижачки, — незаперечне свідчення мисливської вправності в читанні слідів і в бою.",["faction:Horde"]="Знищення павучихи з каньйону допомагає вберегти хиткі гірські стежки, що з'єднують порубіжжя Пусток із Притулком Сонячної Скелі."},sec={{t="Трофей каньйонної мисливиці",b="Каньйон Сішир здавна кишить агресивними павуками, але жоден із них не наводить на мандрівників такого жаху, як Бесселет. Вона виросла до жахливих розмірів і разом зі своїм виводком перетворила ущелину на смертельну пастку для тих, хто вночі йде Стежкою Павутинника. Саме ікло завдовжки майже два фути й сочиться сильною отрутою, тож воно безпомилково свідчить про загибель павучої матері. Цей моторошний трофей приносить полегшення місцевим оборонцям, які потерпали від її отруйних ударів."}},faq={{q="Для чого потрібне Ікло Бесселет?",a="Ікло — речовий доказ того, що павучиху-матріархиню Бесселет убито. Маґґран Ертбайндер із Притулку Сонячної Скелі призначив за неї нагороду після того, як ледве пережив напад її іклів, і винагороджує кожного, хто принесе йому цей трофей.",al={"призначення ікла бесселет","кому потрібне ікло бесселет","здати ікло"}},{q="Звідки це ікло?",a="Ікло виривають просто з пащі Бесселет — велетенської хижої павучихи, що живе в Каньйоні Сішир на захід від головного шляху, на південь від Кручі Вітрорізу в Горах Кам'яного Кігтя.",al={"як отримати ікло бесселет","де бесселет","місце бесселет"}},{q="Чому Маґґран Ертбайндер хотів смерті Бесселет?",a="Бесселет і її виводок раз у раз полюють на мандрівників дорогою до Притулку Сонячної Скелі, особливо під покровом ночі. На самого Маґґрана Ертбайндера вона напала із засідки й поранила іклами, тож він оголосив нагороду, щоб убезпечити стежки.",al={"чому вбити бесселет","нагорода маґґрана за павучиху","чому нагорода за бесселет"}},{q="Хто оголосив нагороду за ікло?",a="Нагороду затвердив Маґґран Ертбайндер, а оголошення про розшук висить при головному шляху на південь від розвилки біля Кручі Вітрорізу й застерігає мандрівників від небезпек Каньйону Сішир.",al={"оголошення в камені-вартовому павук","видавець завдання арахнофобії"}}},fp="16,228,28.512.0,34.256.0,31.185.0,48.259.0,35.196.0"}
P.entries["item:bethor-s-scroll"] = {n="Сувій Бетора",s="Сувій Бетора містить магічні заклинання, які записав Бетор Айсшард, щоб протидіяти темному чаклунству свого колишнього колеги Тула Рейвенклова. Створений на допомогу Аптекареві Ренферрелу, що варить захисне зілля, сувій вкрай потрібен, щоб уціліти перед некромантією Погибелі, яка стереже Острів Фенріс.",h="Сувій Бетора містить магічні заклинання, які записав Бетор Айсшард, щоб протидіяти темному чаклунству свого...",kw={"сувій бетора","бетор айсшард","тул рейвенклов","аптекар ренферрел","острів фенріс","некромантія","кірін-тор"},ang={["class:Mage"]="Сувій показує розколоте минуле Кірін-Тору: близьке знання особливої магії товариша-чарівника можна обернути на сильний протизасіб.",["race:Undead"]="Цей пергамент поєднує різні таланти чаклунів і аптекарів-Відступників: давній чарівний вишкіл Даларана й нове алхімічне ремесло Гробниці."},sec={{t="Зрада колеги",b="Дослідивши отруєний іхор, знайдений у гнилошкірих гнолів, Бетор Айсшард упізнав руку Тула Рейвенклова. Колись Тул був здібним молодим магом Кірін-Тору, але, коли Погибель увійшла в силу, зрадив братів, щоб служити Королю-Лічу. Дізнавшись, що Тул уцілів і з Острова Фенріс керує нападами гнилошкірих гнолів по всьому Срібноліссю, Бетор скористався своїм близьким знанням чарів колишнього колеги й написав цей сувій."},{t="Протидія некромантові",b="Сувій просякнутий могутніми чарівними формулами, але це не зброя для нападу, а настанова з варіння для Королівського Аптекарського Товариства. Переданий Аптекареві Ренферрелу в Гробниці, сувій дає точні контрзаклинання, потрібні, щоб виготовити відновлювальне зілля, здатне розвіяти виснажливі прокляття, якими Тул обплітає свою фортецю."}},faq={{q="Що написано в Сувої Бетора?",a="У сувої записано особливі чародійські заклинання, які склав Бетор Айсшард. Колись він навчався разом із Тулом Рейвенкловом, тож знав улюблені чари некроманта й вписав точні формули, потрібні, щоб зварити алхімічне протизілля.",al={"що написано в сувої","зміст сувою бетора","що на сувої"}},{q="Хто отримує цей сувій?",a="Сувій слід доставити Аптекареві Ренферрелу в Гробниці у Срібноліссі. Ренферрел використовує закладену в ньому магію, щоб приготувати захисне зілля.",al={"кому віддати сувій","здати сувій бетора","хто отримує сувій"}},{q="Навіщо Аптекареві Ренферрелу магічні заклинання для зілля?",a="Аптекар Ренферрел — знавець алхімії, а не звичного чаклунства, і сам визнає, що рідко вплітає таку відверту магію у свої суміші. Проте звичайні протиотрути не здолають прокльонів Погибелі, що захищають Тула, тож без чародійських формул Бетора зілля не подіє.",al={"навіщо аптекареві заклинання","магічне зілля ренферрела"}},{q="Ким був Тул Рейвенклов, перш ніж перейти на бік Погибелі?",a="До Третьої війни Тул був багатообіцяльним молодим магом-людиною й соратником Бетора Айсшарда. Коли Король-Ліч зібрав свої армії нежиті, Тул покинув товаришів-чародіїв і присягнув на вірність Погибелі.",al={"хто такий тул рейвенклов","історія тула","тул і бетор"}}},fp="15,290,22.461.0,26.368.1,35.255.0,25.175.0,69.286.0,54.225.0"}
P.entries["item:bingles-blastencapper"] = {n="Вибухокапсулятор Бінґлза",s="Вибухокапсулятор Бінґлза — особливий вибуховий пристрій, сконструйований гномом-пілотом Бінґлзом Бластенгаймером. Він загубився, коли гірокоптер Бінґлза шубовснув у води Лох Модану, і його поцупили місцеві троги, а це загрожує планам Бінґлза допомогти визволенню Гномреґана.",h="Вибухокапсулятор Бінґлза — особливий вибуховий пристрій, сконструйований гномом-пілотом Бінґлзом...",kw={"вибухокапсулятор","бінґлз бластенгаймер","гномреґан","лох модан","троги","гірокоптер","вибухівка"},ang={["profession:Engineering"]="Вибухокапсулятор — класичний зразок гномського інженерного шику: складний, страшенно вибуховий і нищівний, коли його скидають з великої висоти.",["race:Gnome"]="У боротьбі за Гномреґан важить кожен інструмент і кожен снаряд, і повернена вибухівка Бінґлза дасть гномській повітряній кмітливості змогу відповісти загарбникам-трогам."},sec={{t="Вибуховий винахід",b="Вибухокапсулятор Бінґлза — вершина власного арсеналу пілота Бінґлза Бластенгаймера. Його збудували, щоб завдавати рішучих ударів з повітря по трогах і прокажених гномах, які захопили Гномреґан, і вибухівка була на борту гірокоптера, коли механічна поломка скинула Бінґлза у води озера. Бінґлз уцілів, але троги, що кишать на північних острівцях озера, розграбували уламки й потягли небезпечну зброю до своїх таборів."},{t="Підтримка з повітря для Гномреґана",b="Для Бінґлза Вибухокапсулятор — куди більше, ніж просто врятований мотлох. Гноми-вигнанці щосили готуються відвоювати свою радіоактивну домівку, і Бінґлз вважає свій гірокоптер і фірмові боєприпаси важливою частиною майбутнього повітряного штурму. Повернувши цю вибухівку, ви не дасте тутешнім трогам Лох Модану ненароком накликати катастрофу й збережете цінну зброю для гномського опору."}},faq={{q="Що таке Вибухокапсулятор Бінґлза?",a="Це особлива потужна вибухівка, яку винайшов Бінґлз Бластенгаймер для повітряних ударів на підтримку походу гномів проти трогів і прокажених гномів, що захопили Гномреґан.",al={"що таке вибухокапсулятор","вибухокапсулятор","вибухівка бінґлза"}},{q="Як вибухокапсулятор опинився в озері?",a="Бінґлз упав зі своїм гірокоптером в озеро. Перш ніж він устиг зібрати спорядження, троги з довколишніх островів обнишпорили збитий апарат і потягли інструменти разом із вибуховим пристроєм.",al={"чому він у озері","як бінґлз його втратив","аварія"}},{q="У кого зараз вибухокапсулятор?",a="Троги, що живуть на північних островах озера, поцупили пристрій з місця аварії й стережуть його у своєму примітивному таборі.",al={"хто вкрав вибухокапсулятор","у кого він","троґи"}},{q="Навіщо Бінґлзу повернути вибухокапсулятор?",a="Без інструментів і фірмових боєприпасів Бінґлз не полагодить гірокоптер і не завдасть удару з повітря на підтримку визволення Гномреґана.",al={"навіщо він потрібен назад","чому вибухокапсулятор важливий","для гномереґану"}}},fp="22,254,20.451.0,26.421.0,31.197.0,45.217.0,36.140.0,49.157.0"}
P.entries["item:bingles-hammer"] = {n="Молот Бінґлза",s="Молот Бінґлза — інженерний інструмент Бінґлза Бластенгаймера, дивакуватого гнома-авіатора, що застряг у Лох Модані. Коли його літальна машина впала в озеро, ворожі троги розтягли молот разом з іншим особливим спорядженням. Бінґлзові треба його повернути, щоб полагодити свій літак і допомогти війні за визволення Гномреґана.",h="Молот Бінґлза — інженерний інструмент Бінґлза Бластенгаймера, дивакуватого гнома-авіатора, що застряг у Лох...",kw={"молот бінґлза","бінґлз бластенгаймер","лох модан","троги","гірокоптер","гномреґан"},ang={["profession:Engineering"]="Кожен майстер знає, що добрий гномський молот незамінний — надто коли треба відбудувати експериментальний гірокоптер посеред дикої місцини.",["race:Gnome"]="Кожен повернений інструмент на крок наближає повітряний наступ Гномреґана на загарбників, що відібрали у вас прадідівську домівку."},sec={{t="Інструменти авіатора-невдахи",b="Коли пілот Бінґлз Бластенгаймер шубовснув у води озера, те, що він вижив, стало лише початком його бід. Троги, що живуть на прісноводних острівцях, швидко пограбували місце аварії й розтягли його особливі інструменти та потужну вибухівку. Серед награбованого був і його молот — незамінна річ, щоб вирівняти пом'ятий корпус і заново налаштувати механізми гірокоптера. Без цього головного інструмента й решти спорядження Бінґлз міцно прикутий до землі й не може літати на підтримку гномських визвольних загонів, які прагнуть відвоювати Гномреґан."}},faq={{q="Де знайти Молот Бінґлза?",a="Молот лежить в одному з відер з інструментами Бінґлза, розкиданих по островах на півночі озера, де аж кишить трогами.",al={"місце молота","де молот бінґлза","як знайти молот"}},{q="Кому належить цей молот?",a="Він належить Бінґлзу Бластенгаймеру — гному-інженерові й пілотові, охочому до пригод, який розбив свою літальну машину на березі озера в Лох Модані.",al={"чий молот","власник молота бінґлза"}},{q="Чому цей інструмент такий важливий для Бінґлза?",a="Бінґлзу потрібен увесь набір інструментів, щоб відбудувати збитий гірокоптер, на якому він хоче вилетіти в бій і підтримати удар з повітря по трогах і прокажених гномах, що захопили Гномреґан.",al={"навіщо бінґлзу молот","використання молота бінґлза"}},{q="Хто вкрав Молот Бінґлза?",a="Місцеві троги з острівців на озері напали на місце аварії й потягли відра з інструментами пілота та його саморобну вибухівку — вибухокапсулятори.",al={"хто забрав молот","троґи злодії"}}},fp="15,353,28.599.0,35.147.0,31.139.0,41.198.0,26.145.0"}
P.entries["item:bingles-screwdriver"] = {n="Викрутка Бінґлза",s="Викрутка Бінґлза — необхідний інженерний інструмент Бінґлза Бластенгаймера, гнома-пілота, що впав на своєму гірокоптері у води Лох Модану. Після аварії тутешні троги розграбували уламки й розтягли відра з інструментами та особливим спорядженням Бінґлза по північних острівцях озера.",h="Викрутка Бінґлза — необхідний інженерний інструмент Бінґлза Бластенгаймера, гнома-пілота, що впав на своєму...",kw={"викрутка бінґлза","бінґлз бластенгаймер","лох модан","троги","гірокоптер","гномреґан"},ang={["profession:Engineering"]="Кожен винахідник знає, що точно відкалібрована викрутка незамінна для мудрованих гвинтів гірокоптера й делікатних спускових механізмів.",["race:Gnome"]="Кожен повернений інструмент на крок наближає Бінґлза до відновлення його машини й повітряної війни з трогами та прокаженими гномами, що вигнали ваш народ із Гномреґана."},sec={{t="Незамінний набір пілота",b="Коли Бінґлз Бластенгаймер шубовснув в озеро, він утратив не лише літальну машину, а й особливе спорядження, потрібне, щоб її полагодити. Серед розкиданого добра була й його вірна викрутка, складена в одне з кількох відер з інструментами, які вхопили спритні троги з сусідніх острівців. Для інженера, що застряг серед дикої місцини, такі інструменти для тонкого налаштування незамінні — особливо коли треба складати делікатні механізми гірокоптера чи мати справу з вибуховою зброєю."},{t="Підготовка до відвоювання",b="Бінґлз — не просто авіатор-аматор: він служить великій справі визволення занепалого міста Гномреґан від трогів і прокажених гномів. Його задум — поєднати політ із вибуховими снарядами з Вибухокапсулятора й ударити з повітря по підземній загрозі. Повернути цю викрутку разом із гайковим ключем і молотом — вкрай важливо, щоб знову скласти гірокоптер і не дати згаснути гномському повітряному контрнаступу."}},faq={{q="Де знайти Викрутку Бінґлза?",a="Її дістають з одного з відер з інструментами Бінґлза, розкиданих по островах на півночі Лох Модану, куди місцеві троги затягли рештки після аварії.",al={"місце викрутки","знайти викрутку бінґлза","де викрутка"}},{q="Чому викрутка така важлива для Бінґлза?",a="Бінґлзу потрібні основні інженерні інструменти, щоб відбудувати збитий гірокоптер і підготувати особливу вибухівку для походу на визволення Гномреґана.",al={"навіщо бінґлзу викрутка","для чого вона"}},{q="Хто взагалі вкрав викрутку?",a="Троги з островів на озері напали на Бінґлза після вимушеної посадки й потягли відра з інструментами та вибухокапсулятори.",al={"хто забрав інструменти","хто вкрав інструменти бінґлза"}},{q="Які ще інструменти Бінґлз утратив під час аварії?",a="Окрім викрутки, Бінґлз утратив гайковий ключ, молот і запас нестабільної вибухівки — Вибухокапсуляторів Бластенгаймера.",al={"інші інструменти бінґлза","чого ще бракує"}}},fp="20,310,19.507.0,29.476.0,36.162.0,47.151.0,45.148.0,47.130.0"}
P.entries["item:bingles-wrench"] = {n="Гайковий Ключ Бінґлза",s="Гайковий Ключ Бінґлза — важлива частина гномського інженерного спорядження пілота Бінґлза Бластенгаймера. Він загубився, коли Бінґлз аварійно посадив свою літальну машину в озеро Лох Модану, і місцеві троги потягли його разом з рештою інструментів.",h="Гайковий Ключ Бінґлза — важлива частина гномського інженерного спорядження пілота Бінґлза Бластенгаймера.",kw={"гайковий ключ бінґлза","бінґлз бластенгаймер","троги","гірокоптер","гномреґан","інструменти"},ang={["profession:Engineering"]="Майстер знає: інженер без свого улюбленого ключа намертво прикутий до землі — особливо коли поруч троги, ласі до чужого добра.",["race:Gnome"]="Кожен повернений інструмент на крок наближає гномський опір до того, щоб перенести бій у опромінені зали Гномреґана."},sec={{t="Здобич на острівцях",b="Після того як Бінґлз Бластенгаймер упав на своєму гірокоптері в спокійні води озера, його порятунок швидко обернувся випробуванням. Троги з маленьких північних острівців пограбували місце аварії, розтягли його особливі припаси й порозкидали інструменти по відрах у своїх таборах. Гайковий ключ Бінґлза — один із трьох незамінних ручних інструментів, потрібних разом із потужною вибухівкою з Вибухокапсулятора. Без нього Бінґлзові годі й думати про ремонт збитого гірокоптера, і задуманий повітряний наступ на допомогу гномам-вигнанцям, що борються за Гномреґан, зависає в повітрі."}},faq={{q="Кому належить цей гайковий ключ?",a="Ключ належить Бінґлзу Бластенгаймеру — ексцентричному гномові-пілотові, що впав зі своїм гірокоптером в озеро в Лох Модані.",al={"хто такий бінґлз","власник бінґлза","чий ключ"}},{q="Чому гайковий ключ такий важливий для Бінґлза?",a="Бінґлзу потрібні його особливі інструменти, щоб полагодити пошкоджену літальну машину й зарядити вибухівку, а тоді завдати удару з повітря по трогах і прокажених гномах, що захопили Гномреґан.",al={"навіщо бінґлзу ключ","призначення ключа","для чого ключ"}},{q="Де опинився ключ після аварії?",a="Ключ підібрали місцеві троги й сховали в одне з украдених відер з інструментами Бінґлза, розкиданих по північних островах озера.",al={"де гайковий ключ бінґлза","місце ключа","знайти ключ бінґлза"}},{q="Що ще вкрали разом із ключем?",a="Разом із ключем троги потягли Викрутку Бінґлза, Молот Бінґлза та його експериментальну вибухівку — Вибухокапсулятори Бластенгаймера.",al={"інші припаси","зниклі інструменти","що ще взяли троґи"}}},fp="15,244,22.570.0,31.125.0,42.195.0,44.145.0,43.147.0"}
P.entries["item:black-claw-stout"] = {n="Темне Пиво Чорного Пазура",s="Темне Пиво Чорного Пазура — особливий напій, який готує Зардет із Чорного Кігтя під вулицями Стормвінда. Зварене для одного надокучливого вельможі, воно потрапляє до нього під виглядом звичайного трунку з таверни.",h="Темне Пиво Чорного Пазура — особливий напій, який готує Зардет із Чорного Кігтя під вулицями Стормвінда.",kw={"темне пиво чорного пазура","зардет із чорного кігтя","лорд вішок","зарізане ягня","отрута","фортеця стормвінда"},ang={["class:Warlock"]="Цей трунок уособлює тонкі й безжальні методи стормвіндського ковену чорнокнижників, які позбуваються політичних загроз просто під носом у міської варти.",["faction:Alliance"]="Пронести цей трунок крізь Фортецю Стормвінда — означає побачити, наскільки вразливі вельможі столиці для таємних убивств, задуманих у їхньому ж місті."},sec={{t="Отруйний ковток",b="За темними шинками таверни «Зарізане Ягня» чорнокнижники й змовники ховаються просто під носом у міської варти Стормвінда. Коли вельможа на ім'я Лорд Вішок раз у раз погрожує закрити їхню підпільну справу, а сам лицемірно набирає неоплачених рахунків у шинку нагорі, Зардет із Чорного Кігтя вирішує звести з ним рахунки. Темне Пиво Чорного Пазура створене саме для того, щоб скористатися слабкістю Вішока до міцних напоїв: під виглядом звичайного трунку з таверни воно несе смертельну дозу."},{t="Тихе вбивство",b="Принесене просто до Палати Прохача у Фортеці Стормвінда, пиво розраховане на пихатість і спрагу Вішока. Прийнявши доставку за послугу уважного слуги, вельможа охоче випиває трунок на місці. Отрута діє майже миттєво, і один із найупертіших і найдокучливіших політичних критиків культу замовкає просто під носом у королівського двору."}},faq={{q="Що таке Темне Пиво Чорного Пазура?",a="Це особливий напій, який зварив Зардет із Чорного Кігтя в катакомбах під корчмою «Зарізане Ягня» в Кварталі магів Стормвінда. Призначено його для лорда Вішока.",al={"що це за напій","історія темного пива чорного пазура","отруйне пиво"}},{q="Для кого призначене це пиво?",a="Для лорда Вішока — пихатого вельможі, що вештається в Залі Прохачів. Він домагався закриття притулку чорнокнижників, а сам тим часом пив там у борг.",al={"хто це п'є","хто помирає від темного пива","ціль вішока"}},{q="Хто зварив цей напій?",a="Його зварив Зардет із Чорного Кігтя — зловісна постать, що орудує зі склепів під корчмою «Зарізане Ягня».",al={"творець темного пива чорного пазура","хто це зробив","пиво зардета"}},{q="Чому лордові Вішоку пропонують це пиво?",a="Зардет посилає пиво лордові Вішоку в Залу Прохачів і просить кур'єра подивитися, як вельможі сподобається його особливий напій.",al={"чи помре вішок","дія темного пива чорного пазура"}}},fp="16,208,15.501.1,19.384.1,25.161.0,31.178.0,21.119.0,38.131.1"}
P.entries["item:black-feather-quill"] = {n="Чорне Перо",s="Чорне Перо — священна реліквія нічних ельфів, якою Друїди Кігтя послуговуються в обрядах сплячки й пробудження. Воно зберігається в окремій скрині в Курганному Лігві Бан'етіл і є одним із кількох конче потрібних осередків, щоб безпечно прикликати сплячих друїдів назад зі Смарагдового Сну.",h="Чорне Перо — священна реліквія нічних ельфів, якою Друїди Кігтя послуговуються в обрядах сплячки й...",kw={"чорне перо","реліквія","друїди кігтя","курганне лігво бан'етіл","смарагдовий сон","пробудження","атрідас бермантл"},ang={["class:Druid"]="Для друїдів перо уособлює священні знаряддя, що прив'язують послідовників Кігтя до яви, поки їхні духи єднаються зі Смарагдовим Сном.",["race:NightElf"]="Нічні ельфи бачать у споганенні скринь із реліквіями Бан'етіла фурболгами Вузлошкірів ще одне болісне нагадування про скверну, що насувається на Тельдрассил."},sec={{t="Посудина пробудження",b="Друїдизм нічних ельфів спирається на глибоко настроєні священні предмети, щоб долати поріг між явою і Смарагдовим Сном. Чорне Перо разом із Талісманом Воронячого Пазура, Сапфіром Небес і Руною Гніздування становить основний набір обрядових предметів, потрібних, щоб перервати крихку сплячку Друїдів Кігтя. Без цих осередків сплячий друїд ризикує навіки лишитися в пастці Сну, нездатний повернутися у своє тіло наяву."},{t="Загроза в Бан'етілі",b="Коли споганені фурболги Вузлошкірів заполонили Курганне Лігво Бан'етіл, священні скрині з цими скарбами опинилися в небезпеці. Залишені без охорони в покручених глибинах, реліквії треба було швидко повернути за наказом Атрідаса Бермантла з Доланаара, доки полонених друїдів не втрачено для Сну назавжди."}},faq={{q="Для чого потрібне Чорне Перо?",a="Перо — одна з чотирьох Реліквій Пробудження, без яких не можна безпечно пробудити Друїдів Кігтя з обрядової сплячки в Смарагдовому Сні.",al={"призначення чорного пера","навіщо чорне перо","що робить перо"}},{q="Де зберігається Чорне Перо?",a="Воно лежить у Скрині Чорного Пера глибоко в Курганному Лігві Бан'етіл у центрі Тельдрассила.",al={"місце чорного пера","де скриня чорного пера","де перо"}},{q="Чому друїди не можуть прокинутися без пера й інших реліквій?",a="Друїдська сплячка — це занурення в Смарагдовий Сон під тонкими чарами. Щоб вийти з цього трансу, потрібні особливі священні предмети: без них дух сплячого не знайде шляху назад до свого тіла.",al={"чому друїди потребують реліквій щоб прокинутися","чи можуть друїди прокинутися самі"}},{q="Хто просить знайти Чорне Перо?",a="Атрідас Бермантл у Доланаарі посилає шукачів пригод по перо та інші Реліквії Пробудження, щоб урятувати друїдів, яким загрожує небезпека.",al={"хто потребує пера","хто дає завдання на чорне перо"}}},fp="19,297,20.476.0,23.306.0,41.144.0,38.117.0,64.227.0,37.144.0"}
P.entries["item:blackened-skull"] = {n="Почорнілий Череп",kw={"почорнілий череп","даркай бонкастер","млини аґаманда","погибель","брілл","тірісфаль"},ang={["class:Mage"]="Ці черепи — тілесні рештки Даркай Бонкастерів, скелетів-чаклунів, на яких полюють на Млинах Аґаманда.",["race:Undead"]="Для Відступників знищення Даркай Бонкастерів — питання чистого виживання: їхній колишній володар не повинен закріпитися просто на їхньому порозі."},sec={{t="Трофей кістеметників",b="These blackened skulls are salvaged from the Darkeye Bonecasters haunting the Agamand Mills. These skeletal spellcasters direct necromantic malice against the living and the Forsaken alike, attempting to entrench a forward base for the Lich King's armies in northern Tirisfal. Presenting their ruined skulls to Deathguard Dillinger serves as tangible evidence that the Scourge's mystical vanguard is being crushed."}},faq={{q="Звідки беруться почорнілі черепи?",a="Їх збирають з решток Темнооких заклиначів кісток — скелетів-чаклунів, що никають полями й будівлями довкола Млинів Аґаманда на півночі Галявин Тірісфалю.",al={"джерело почорнілих черепів","хто дропає почорнілі черепи","де взяти почорнілі черепи"}},{q="Навіщо Вартовому Смерті Діллінджеру почорнілі черепи?",a="Вартовий Смерті Діллінджер доручає захисникам-Відступникам збирати почорнілі черепи й зазубрені ребра як доказ того, що бої з Погибеллю тривають. Відступники не можуть дозволити безвольним слугам Короля-Ліча закріпитися так близько до Брілла й Андерсіті.",al={"черепи діллінджера","навіщо збирати черепи","млини переповнені черепами"}},{q="Чому черепи почорніли?",a="Черепи описано як почорнілі, але джерело не пояснює, що спричинило таку барву. Їх збирають із Даркай Бонкастерів на Млинах Аґаманда.",al={"чому він почорнілий","історія почорнілого черепа"}},{q="Що Погибель робить у Млинах Аґаманда?",a="Погибель намагається укріпити покинуті Млини Аґаманда як передовий плацдарм, звідки можна завдавати глибших ударів і робити набіги по всіх Галявинах Тірісфалю.",al={"погибель у млинах аґаманда","чому погибель у млинах"}}},fp="15,243,25.414.0,36.174.0,52.262.0,29.163.0,43.162.0"}
P.entries["item:bloodfeather-belt"] = {n="Пояс Кривавого Пера",s="Пояс Кривавого Пера — грубий шкіряний ремінь, який носять гарпії Кривавого Пера, що заполонили північний Тельдрассил. Вартова Аринія Клаудзбрейк збирає ці пояси як доказ, що тутешні гнізда, які зазіхають на Галявину Оракула, розорено.",h="Пояс Кривавого Пера — грубий шкіряний ремінь, який носять гарпії Кривавого Пера, що заполонили північний...",kw={"пояс кривавого пера","гарпії","галявина оракула","аринія клаудзбрейк","вартова","тельдрассил","дарнасус"},ang={["faction:Alliance"]="Допомога Вартовій Аринії Клаудзбрейк гарантує, що важливі звіти від прадавніх дерев Тельдрассила безперешкодно дійдуть до проводу в Дарнасусі.",["race:NightElf"]="Зграя Кривавого Пера споганює природне шатро Тельдрассила, тож відвоювати Галявину Оракула в їхніх верескливих гнізд — неодмінний обов'язок кожного захисника батьківщини калдореїв."},sec={{t="Трофеї з гнізд",b="Гарпії Кривавого Пера напосідливо загніздилися у вітті довкола Галявини Оракула, загрожуючи прадавньому Дереву Оракула й перекриваючи шлях через північний Тельдрассил. Коли зграя підстерегла й убила гінця зі звітами до Дарнасуса, Вартова Аринія Клаудзбрейк закликала мандрівників ударити просто по їхніх гніздах. Пояси, зняті з полеглих гарпій, — відчутний доказ того, що їхню кількість зменшують, а стежки вбезпечують, щоб зв'язок зі столицею відновився."}},faq={{q="Навіщо Вартовій Аринії Клаудзбрейк ці пояси?",a="Аринія Клаудзбрейк та її невеликий загін Вартових стережуть священне Дерево Оракула від навколишніх гнізд гарпій Кривавого Пера. Нещодавно гарпії вбили гінця, що прямував до Дарнасуса, тож Аринія вимагає пояси як речовий доказ того, що шукачі пригод розоряють гнізда й проріджують зграю.",al={"навіщо аринії пояси","призначення пояса кривавого пера","навіщо збирати пояси"}},{q="Звідки беруться Пояси Кривавого Пера?",a="Їх забирають у гарпій Кривавого Пера, що живуть на деревах і скелях довкола Галявини Оракула на півночі Тельдрассила. Пояси носять усі гарпії зграї — вітряні відьми, чаклунки, розбійниці й фурії.",al={"хто дропає пояс кривавого пера","де взяти пояси","місце пояса кривавого пера"}},{q="Чому гарпії — це біда для Галявини Оракула?",a="Гарпії звили гнізда зовсім поруч із Деревом Оракула — прадавнім шанованим деревом, що стежить за здоров'ям Світового Дерева. Їхня зухвала присутність відрізає Вартових, які охороняють галявину, і жорстоко перериває зв'язок із Дарнасусом.",al={"гарпії галявини оракула","чому гарпії в тельдрассілі","загроза гарпій дереву оракула"}}},fp="17,234,23.505.0,54.329.0,38.237.0,46.263.0"}
P.entries["item:bloodfury-ripper-s-remains"] = {n="Рештки Кривавоярісної Шматувальниці",s="Рештки Кривавоярісної Шматувальниці — речовий доказ, здобутий у матріархині гарпій Бладф'юрі в Обвугленій Долині. Їх шукає Маґґран Ертбайндер у Притулку Сонячної Скелі: цей трофей підтверджує смерть лютої проводирки виводку й завдає рішучого удару гарпіям, що загрожують місцевому тауренському поселенню.",h="Рештки Кривавоярісної Шматувальниці — речовий доказ, здобутий у матріархині гарпій Бладф'юрі в Обвугленій...",kw={"рештки кривавоярісної шматувальниці","потрошителька бладф'юрі","гарпії","маґґран ертбайндер","притулок сонячної скелі","обвуглена долина"},ang={["faction:Horde"]="Знищення диких загроз на кшталт матріархині Бладф'юрі забезпечує безпечний прохід валкам і розвідникам Орди між Пустками й Горами Кам'яного Кігтя.",["race:Tauren"]="Гарпії Бладф'юрі прямо загрожують безпеці Притулку Сонячної Скелі, тож здобути рештки їхньої проводирки — справа відданості захистові мирних тауренських поселень у Горах Кам'яного Кігтя."},sec={{t="Перервати рід",b="Гарпії Бладф'юрі, що гніздяться в обпалених руїнах Обвугленої Долини, здавна люто загрожують мандрівникам і шаманам Гір Кам'яного Кігтя. Проріджуючи їх, можна послабити безпосередню небезпеку, але Маґґран Ертбайндер із Притулку Сонячної Скелі розуміє: справжнього перепочинку не буде без знищення їхньої верхівки. Потрошителька Бладф'юрі править своєю зграєю майже як королева й спрямовує її ворожість до чужинців. Її рештки — важливий доказ її загибелі: вони кидають решту гарпій у сум'яття й дають спокій тауренам, що прагнуть зцілити й убезпечити свої суворі землі."}},faq={{q="Для чого потрібні Рештки Кривавоярісної Шматувальниці?",a="Вони — незаперечний речовий доказ смерті Потрошительки Бладф'юрі. Маґґран Ертбайндер із Притулку Сонячної Скелі просить їх, щоб пересвідчитися, що ватажку місцевих гарпій, схожу на королеву, усунуто назавжди.",al={"що роблять рештки","призначення решток","кому потрібні рештки"}},{q="Де знайти Потрошительку Бладф'юрі?",a="Потрошителька Бладф'юрі никає західними й північно-західними пагорбами Обвугленої Долини на півдні Гір Кам'яного Кігтя. Від своєї червоно-білої зграї вона відрізняється помітним синім пір'ям.",al={"місце потрошительки бладф'юрі","де шматувальниця","знайти шматувальницю"}},{q="Чому Маґґран Ертбайндер хоче її смерті?",a="Маґґран вважає, що, просто вибиваючи звичайних гарпій, їхніх набігів на довколишні землі не зупинити. Смерть матріархині руйнує їхню ієрархію й послаблює здатність гуртуватися проти Притулку Сонячної Скелі.",al={"чому вбити шматувальницю","мотив маґґрана","чому вона мусить померти"}}},fp="26,326,22.609.0,45.216.0,36.194.0,43.218.0"}
P.entries["item:bloodstone-choker"] = {n="Намисто Кровавика",s="Намисто Кровавика — темний магічний талісман із кровавика, яким спершу володів наставник чорнокнижників Ґакін Зв'язувач Темряви. Викрадене зрадливою ученицею, що втекла до Братства Дефіас, воно слугує могутнім осередком ритуалу, здатним пронизати порожнечу, щоб викликати й прив'язати блукача порожнечі.",h="Намисто Кровавика — темний магічний талісман із кровавика, яким спершу володів наставник чорнокнижників Ґакін...",kw={"намисто кровавика","ґакін","сурена каледон","блукач порожнечі","чорнокнижник","зарізане ягня"},ang={["class:Warlock"]="Для чорнокнижників Альянсу повернення Намиста Кровавика — життєво важливий обряд посвяти, що з'єднує основи чаклунства з владою над грізними демонічними слугами.",["faction:Alliance"]="Втеча Сурени Каледон до Братства Дефіас показує, як звичайні розбійники Елвінну завзято шукають небезпечні окультні реліквії, щоб підживити свій бунт проти Стормвінда."},sec={{t="Викрадений провідник",b="Намисто Кровавика, що зберігалося в потаємних покоях під стормвіндським «Зарізаним Ягням», було одним із найцінніших ритуальних знарядь Ґакіна Зв'язувача Темряви. Його спокій розбила Сурена Каледон, чорнокнижниця-початківиця під опікою Ґакіна: вона зрадила наставника й викрала амулет. Сурена втекла в ліси Елвінну, щоб пристати до розбійницького Братства Дефіас, прихопивши зачароване намисто як знак сили й козир для торгу. Щоб повернути його, доведеться вистежити її на Гарбузовій Ділянці Брекуеллів, перш ніж бандити обернуть його небезпечні сили на власні цілі."},{t="Приборкання порожнечі",b="Вирізьблене з кровавика, намисто має приховану містичну владу, потрібну, щоб з'єднати світ смертних із покрученими тінями Викривленого Нижнього Світу. Щойно його повертають Ґакінові, його одразу випробовують у криптах під таверною. Чорнокнижник має спрямувати магію намиста в підземному колі прикликання, щоб вирвати з порожнечі ворожого блукача порожнечі. Лише впокоривши розлючену сутність у прямому бою з талісманом у руках, практик доводить силу волі, потрібну, щоб командувати таким охоронцем."}},faq={{q="Що таке Намисто Кровавика?",a="Це зачароване намисто з кровавика, яке чорнокнижники використовують як обрядовий провідник. У ньому досить магічної сили, щоб прорвати тканину світу й викликати норовливого блукача Порожнечі з Нижнього Світу.",al={"намисто кровавика","що це за намисто","що робить намисто"}},{q="Кому спершу належало намисто?",a="Воно належить Ґакіну Зв'язувачу Темряви — майстрові-чорнокнижникові, що навчає учнів у потаємних підвалах під корчмою «Зарізане Ягня» в Кварталі магів Стормвінда.",al={"чиє намисто","намисто ґакіна","звідки намисто"}},{q="Чому намисто вкрали?",a="Сурена Каледон, учениця Ґакіна, покинула навчання, викрала намисто й утекла до Братства Дефіас. Вона прагнула влади й пристала до бандитів, що ховаються в Лісі Елвінн.",al={"хто його вкрав","чому сурена його вкрала","сурена каледон намисто"}},{q="Як намисто використовують у навчанні чорнокнижників?",a="Повернене намисто активують над колом виклику в склепах під корчмою «Зарізане Ягня». Воно витягає блукача Порожнечі, якого чорнокнижник-початківець мусить здолати й підкорити, щоб дістати владу над демоном.",al={"як використати намисто","ритуал пустоходця намисто","зв'язувальне намисто"}}},fp="17,307,16.598.1,15.530.0,30.192.0,32.165.0,26.211.0,43.226.0"}
P.entries["item:blueleaf-tuber"] = {n="Синьолиста Бульба",s="Синьолисті бульби — надзвичайно рідкісні коренеплоди, що ростуть приховано під колючою землею Рейзорфен Краулу. Їх цінують по всьому світу як екзотичний делікатес, і знайти їх неозброєним оком майже неможливо.",h="Синьолисті бульби — надзвичайно рідкісні коренеплоди, що ростуть приховано під колючою землею Рейзорфен...",kw={"синьолиста бульба","рейзорфен краул","мебок міззірікс","ховрахи","делікатес","шипогриви"},ang={["profession:Cooking"]="Ці коренеплоди — цінований по всьому світу делікатес, і найбагатші гурмани полюють на них, хоч ростуть вони в непривітній землі шипогривих лігв."},sec={{t="Рідкісний підземний делікатес",b="Хоч Синьолисті бульби й походять із Пусток, ростуть вони лише в підземних глибинах Рейзорфен Краулу. Сховані під густим переплетінням коріння й колючими чагарями шипогривів, вони недоступні для випадкових збирачів. Попри суворі умови, у яких вони ростуть, багаті гурмани й торговці по всьому світу платять за них захмарні гроші, смакуючи їхній неповторний смак."},{t="Збирання з допомогою ховрахів",b="Мешканці поверхні не можуть легко помітити ці коренеплоди, тож заповзятливий гоблін Мебок Міззірікс у Раджеті вигадав незвичний спосіб збирання. Він навчає місцевих ховрахів-нюхоносів чути бульби за запахом за п'ятдесят кроків, і шукачі пригод, що керують ними спеціальними паличками-командирками, можуть викопати коренеплоди, перш ніж патрулі шипогривів почують чужинців."}},faq={{q="Для чого потрібні Синьолисті Бульби?",a="Синьолисті Бульби продають як рідкісні делікатеси. Заможні покупці й торговці екзотикою платять за них чималі гроші — за особливий смак і рідкість.",al={"для чого бульби","навіщо синьолисті бульби","для чого потрібні бульби"}},{q="Де знайти Синьолисті Бульби?",a="Вони ростуть лише глибоко під землею на півдні Пусток, серед колючих хащ і підземних нір Рейзорфен Краул.",al={"де ростуть синьолисті бульби","місце бульб","де бульби"}},{q="Навіщо для викопування бульб потрібен ховрах?",a="Бульби ховаються під верхнім шаром ґрунту, і ні людське, ні гоблінське око їх не помітить. Ховрахів-нюхачів привчили чути їх за п'ятдесят кроків і викопувати за командою.",al={"чому ховрах снафлноуз","навіщо ховрах","чому ховрахи"}},{q="Хто купує ці бульби?",a="Мебок Міззірікс, гоблін-ділок із Раджета, скуповує їх, щоб із чималим зиском перепродати заможним клієнтам і закордонним партнерам.",al={"хто хоче синьолисті бульби","хто купує бульби","бульби мебока"}}},fp="14,233,27.356.0,26.382.0,34.143.0,35.122.0,40.188.0,22.146.0"}
P.entries["item:book-from-sven-s-farm"] = {n="Книга з Ферми Свена",s="Книга з Ферми Свена — заляпаний землею щоденник без назви, викопаний на руїнах сплюндрованого хутора Свена Йорґена в Сутінколіссі. Уривчасті записи свідчать, що якийсь невідомий спостерігач бачив різанину родини Свена, — і це дає початок невпинному полюванню в похмурому лісі.",h="Книга з Ферми Свена — заляпаний землею щоденник без назви, викопаний на руїнах сплюндрованого хутора Свена...",kw={"книга з ферми свена","свен йорґен","тремтій","сутінколісся","воргени","даркшир"},ang={["faction:Alliance"]="Для слідчих Альянсу ця потріпана книга — ключ до розгадки моторошних жахіть, що паралізували південь Сутінколісся, і до того, як зграя диких воргенів закріпилася в цих краях."},sec={{t="Підказка в землі",b="Ця непоказна, попсована негодою книжка лежала закопана в пухкій купі землі серед обгорілих решток ферми Свена на півдні Сутінколісся. У ній — гарячкові нотатки невідомого мандрівника. Записи уривками показують трагедію, що спіткала хутір, і підтверджують найчорнішу підозру Свена Йорґена: поки вбивали його родину, хтось ховався в тіні. Оповідь раптово уривається, тож книга породжує більше питань, ніж відповідей, і слідчі несуть її до Даркшира, шукаючи когось, хто впізнає почерк чи загадкового автора."},{t="Хто ховався в тіні",b="Віщуни й мешканці Даркшира з'ясовують, що справжній власник книги не був тутешнім, але тікав лісом, не тямлячи себе від жаху. Ледь помітні сліди на сторінках зрештою приводять до Тремтія — боягузливого волоцюги, що переховується в лісі. Відсутні уривки цієї книги розповідають, як Братство Дефіас бавилося із забороненими артефактами й ненароком випустило в Сутінколісся ненажерливих воргенів. Знайшовши Тремтія, слідчі по шматочку складають оповідь докупи — аж до його завершеного щоденника."}},faq={{q="Де знайти Книгу з Ферми Свена?",a="Книга закопана в занедбаному земляному горбку на зруйнованому хуторі Свена Йорґена на півдні Сутінколісся.",al={"де книга свена","земляний горбок ферма свена","місце книги свена"}},{q="Хто написав книгу, знайдену на фермі Свена?",a="На книзі немає ні назви, ні імені. Її автор — переляканий чоловік, що втік від якогось жаху деінде в Сутінколіссі й сховався у Свеновій стодолі. Там він став свідком різанини Свенової родини, а згодом загубив свій щоденник.",al={"автор книги свена","хто написав забруднену книгу","хто написав щоденник"}},{q="Навіщо Свенові Йорґену ця книга?",a="Після нападу на свою родину Свен бачив біля стодоли незнайомця, що крадькома тинявся довкола. Книга доводить, що той свідок справді існував, — і це єдина відчутна ниточка, яка може допомогти Свенові дізнатися, що насправді сталося тієї ночі.",al={"чому свена цікавить","реакція свена йорґена на книгу"}},{q="Що стається з книгою після розслідування?",a="Коли уривок книги показують різним мешканцям Даркшира й розшукують її власника, неповну книгу зрештою заступає Завершений Щоденник Джиттерса, де розказано всю історію.",al={"що замінює книгу свена","чи лишається книга свена"}},{q="Яка більша таємниця пов'язана зі змістом книги?",a="Повний щоденник пояснює, що змусило автора переховуватися й чому напали на родину Свена. А його історія сягає далеко за межі одного хутора — до темряви, що впала на все Сутінколісся.",al={"який лор у книзі свена","зв'язок із воргенами","зв'язок із дефіас"}}},fp="21,286,18.583.0,29.547.1,41.117.0,40.195.1,36.215.0,50.197.1,55.184.1"}
P.entries["item:book-stresses-of-iron"] = {n="Книга: Напруги Заліза",s="Напруги Заліза — учений трактат із металургії, написаний Марґульфом Блеґґоном. Спершу він зберігався в Королівській Бібліотеці Фортеці Стормвінда, а потім, позичений Абатству Нортшира для переписування, став приводом для доручення між ченцями.",h="Напруги Заліза — учений трактат із металургії, написаний Марґульфом Блеґґоном.",kw={"напруги заліза","марґульф блеґґон","королівська бібліотека","мілтон шіф","брат пакстон","брат крістофф"},ang={["profession:Blacksmithing"]="Цей фоліант Марґульфа Блеґґона заглиблюється в міцність конструкцій і практичні межі роботи із залізом."},sec={{t="Позичений том",b="Праця Марґульфа Блеґґона «Напруги Заліза» розповідає про практичні й теоретичні властивості металургії. Книгу, яку в Королівській Бібліотеці у Фортеці Стормвінда доглядає Мілтон Шіф, позичили Абатству Нортшира, щоб Брат Пакстон міг власноруч переписати її для свого зібрання. Переписування затяглося значно довше, ніж очікували, і Брат Крістофф на Соборній Площі з тривогою чекає, коли текст повернеться до міста."}},faq={{q="Про що ця книга?",a="«Напруги Заліза» — науковий посібник із металургії та обробки металу, який написав учений Марґульф Блеґґон.",al={"що таке напруги заліза","тема напруг заліза","зміст книги"}},{q="Чому книга опинилася в Абатстві Нортшира?",a="Брат Пакстон позичив її в Королівській Бібліотеці Стормвінда, щоб ретельно переписати від руки для власного зібрання, а тоді повернути оригінал.",al={"чому пакстон її мав","чому в нортширі"}},{q="Хто хотів, щоб книгу повернули?",a="Брат Крістофф із Соборної Площі терміново потребував цього тексту, тож шукач пригод вирушив з'ясувати, де ж книга — у Королівській Бібліотеці чи в Нортширі.",al={"кому потрібна книга","хто на неї чекає"}}},fp="22,247,17.466.0,23.121.0,37.159.0,29.173.0"}
P.entries["item:bottle-of-disease"] = {n="Пляшка Хвороби",s="Пляшка Хвороби — флакон із моторошним зіллям, яке варять Відступники, що діють в Ашенвалі. Знайдені в таборі біля Підземної Обителі Дор'Даніл, ці флакони свідчать про зловісну спробу нежиті занести моровиці в незайману природу нічних ельфів.",h="Пляшка Хвороби — флакон із моторошним зіллям, яке варять Відступники, що діють в Ашенвалі.",kw={"пляшка хвороби","відступники","зараза","ашенваль","лісова пісня","кейнет стіллвінд"},ang={["class:Druid"]="Отруйні суміші й штучні моровиці — повна протилежність природній рівновазі, тож кожен друїд, що присягнув берегти ліс, мусить негайно втрутитися.",["race:NightElf"]="Осквернення ґрунту Ашенвалю заразою нежиті — непрощенна образа для калдореїв, тим паче коли її варять на самому порозі Підземної Обителі Дор'Даніл."},sec={{t="Пошесть у священних лісах",b="Глибоко під прадавнім пологом лісу на сході Ашенвалю Відступники прокралися далеко за лінію фронту, яку тримають Дозорці Пісні Війни. Облаштувавши заставу біля Підземної Обителі Дор'Даніл, неживі алхіміки варять мерзенну заразу й запечатують її в скляні пляшки. Для нічних ельфів, що стережуть Лісову Пісню, ці флакони — явний доказ тихого, підступного наступу: нежить хоче не битися у відкритому бою, а заразити лісовий ґрунт і звірину."},{t="Розслідування Кейнета Стіллвінда",b="Кейнет Стіллвінд, вартовий нічних ельфів із Лісової Пісні, шукає доказів зловісних задумів Відступників. Здобута Пляшка Хвороби дає Стіллвіндові змогу просто дослідити її вміст. Нічні ельфи бояться, що ці зілля — не лише зброя проти озброєних вартових, а й ретельно продумані реагенти, що мають осквернити священні підземні обителі й зламати розум і тіло захисників лісу."}},faq={{q="Що в Пляшці Хвороби?",a="У пляшці — штучні отрути й магічна зараза, зварені аптекарями-Відступниками. Ці мерзенні суміші мають уражати живу плоть і ґрунт — це частина ширших дослідів Королівського Аптекарського Товариства з лютими моровицями.",al={"що в пляшці","вміст пляшки хвороби","зілля відступників"}},{q="Де знайти ці пляшки?",a="Вони стоять у відлюдному таборі Відступників на південь від Лісової Пісні, біля самого входу до Курганного Лігва Дор'Даніл на сході Ашенвалю.",al={"де знайти пляшку хвороби","місце пляшки хвороби","табір відступників ашенвейл"}},{q="Кому потрібна Пляшка Хвороби?",a="Кейнет Стіллвінд, захисник із нічних ельфів на заставі Лісова Пісня, доручає шукачам пригод з Альянсу принести пляшку, щоб перевірити її вміст і розгадати справжні наміри Орди.",al={"кому віддати пляшку хвороби","здати пляшку хвороби","завдання кейнета стилвінда"}},{q="Чому Відступники варять хвороби в Ашенвалі?",a="Нічні ельфи підозрюють, що Відступники хочуть потай заразити священний ліс і осквернити довколишні курганні лігва — отруїти живу природу й підточити опір нічних ельфів зсередини.",al={"чому відступники в ашенвалі","мета нежиті в ашенвалі","лігва відступників"}}},fp="17,281,26.448.0,33.411.1,37.245.0,30.155.0,32.201.0,51.201.0"}
P.entries["item:bottle-of-moonshine"] = {n="Пляшка Самогону",s="Пляшка Самогону — міцний трунок, який продають у похмурому Даркширі. Шинкар Деніелс із Лейкширу терміново шукає таку пляшку, щоб поповнити запаси міської таверни, бо набіги орків Блекрок перерізали звичне постачання.",h="Пляшка Самогону — міцний трунок, який продають у похмурому Даркширі.",kw={"пляшка самогону","самогон","шинкар деніелс","даркшир","лейкшир","таверна"},ang={["faction:Alliance"]="Доставка трунку з Даркширу до Лейкширу показує, які крихкі шляхи постачання пов'язують розкидані поселення королівства Стормвінд у часи кризи."},sec={{t="Міцна розрада",b="Лейкшир в облозі клану Блекрок, і місцевий корчмар, Шинкар Деніелс, опинився в скрутному становищі: звичні валки з припасами більше не доходять. Щоб підтримати дух міської варти й змучених містян, Деніелс розсилає гінців південними королівствами по трунки, якими славиться кожен край. Серед них — міцний самогон, який виганяють і продають у Таверні «Багряний Крук» у сусідньому Сутінколіссі, де люди полюбляють чарку чогось міцного, щоб відігнати страх, що підступає з лісу."}},faq={{q="Де знайти Пляшку Самогону?",a="Пляшку Самогону можна купити в шинкаря Таверни «Багряний Крук» у Даркширі, що в похмурих межах Сутінколісся.",al={"де купити самогон","місце самогону даркшир","продавець пляшки самогону"}},{q="Кому потрібна ця пляшка?",a="Шинкар Деніелс, корчмар Лейкширу в Горах Редріджу, просить її разом із кількома іншими місцевими напоями, щоб поповнити погріб, поки триває облога орків.",al={"кому потрібен самогон","здати самогон","шинкар деніелс самогон"}},{q="Чому в Лейкширі закінчується випивка?",a="Ворожі орки Блекрок заполонили Гори Редріджу, грабують на дорогах і перерізали торгові шляхи. Звичні поставки не доходять, тож полиці таверни в Лейкширі майже порожні.",al={"чому сухі часи","нестача припасів лейкшира","нестача випивки в редріджі"}}},fp="19,241,17.497.0,39.146.0,22.186.0,39.200.0"}
P.entries["item:bottle-of-zombie-juice"] = {n="Пляшка Зомбі-Соку",s="Пляшка Зомбі-Соку — міцний і бридкий трунок, зварений із їдкого гнилоцвіту, що росте в Сутінколіссі. Його купують у таверні Даркшира — нібито на прохання відлюдника Аберкромбі, щоб зігрітися в похмурому лісі.",h="Пляшка Зомбі-Соку — міцний і бридкий трунок, зварений із їдкого гнилоцвіту, що росте в Сутінколіссі.",kw={"пляшка зомбі-соку","гнилоцвіт","аберкромбі","даркшир","сутінколісся","трунок"},ang={["faction:Alliance"]="Виконуючи доручення між Даркширом і похмурою глушиною, ви допомагаєте змученим мешканцям Сутінколісся не втрачати зв'язку одне з одним — навіть коли самі доручення видаються сумнівними.",["profession:Herbalism"]="Травники, обізнані із Сутінколіссям, знають, що гнилоцвіт не годиться для звичайних цілющих настоїв, — і від того, що з нього гонять питво, стає ще моторошніше."},sec={{t="Їдке вариво",b="Зомбі-Сік варять із гнилоцвіту, зібраного на темних ґрунтах Сутінколісся, і трунок цей надзвичайно різкий. Шинкар, що його продає, попереджає: питво таке міцне, що й мертвого підніме. Звичайні люди тримаються від такої гидоти подалі, але дивакуватий відлюдник Аберкромбі запевняє, що лише вона й зігріває його сирими холодними ночами в самотній хижі."},{t="Сумнівна спрага",b="Аберкромбі наполягає, що трунок — лише палюча чарка на ніч, але, отримавши пляшку, він обмовляється й мало не хвалить гінця за «дурість» замість доброти. Це натякає, що вариво може слугувати чомусь темнішому й зловіснішому, ніж просто зігрівати, як чарка в таверні."}},faq={{q="З чого роблять Зомбі-Сік?",a="Зомбі-Сік — це міцна настоянка, яку переганяють із гнилоцвіту, смердючої рослини, що росте на зіпсованих ґрунтах Сутінколісся.",al={"з чого зомбі-сік","що в зомбі-соку"}},{q="Кому треба доставити цю пляшку?",a="Пляшку просить Аберкромбі — ексцентричний відлюдник, що живе в самотній халупі на західному краю Сутінколісся.",al={"кому потрібен зомбі-сік","для кого зомбі-сік","доставка зомбі-соку"}},{q="Навіщо Аберкромбі Зомбі-Сік?",a="Аберкромбі запевняє, що пекучий напій потрібен йому, аби зігріти старі кістки в люті темні ночі Сутінколісся, хоча його дивна поведінка натякає, що така міцна суміш може знадобитися йому й для чогось іншого.",al={"навіщо аберкромбі п'є його","причина зомбі-соку аберкромбі"}},{q="Чи можна випити Пляшку Зомбі-Соку?",a="Ні, саме ця пляшка — предмет завдання, призначений лише для доставки Аберкромбі. Ваше головне завдання — неушкодженою донести її до його халупи.",al={"чи можна випити зомбі-сік","чи зомбі-сік їстівний"}}},fp="22,249,20.398.0,19.287.1,31.130.0,32.136.0,39.204.0,45.142.0"}
P.entries["item:bottom-of-gelkak-s-key"] = {n="Нижня Частина Ключа Ґелкака",s="Нижня Частина Ключа Ґелкака — один із трьох уламків розбитого механічного заводного ключа, що належав гномові-піратові Ґелкаку Джайромасту, який зазнав корабельної аварії. Коли його судно пішло на дно біля Темного Узбережжя, цей уламок підібрали місцеві рифові повзуни.",h="Нижня Частина Ключа Ґелкака — один із трьох уламків розбитого механічного заводного ключа, що належав...",kw={"ключ ґелкака","ґелкак джайромаст","темне узбережжя","повзуни","гном-пірат","заводний ключ"},ang={["profession:Engineering"]="Інженери впізнають у цьому уламку частину спеціального заводного пристрою, створеного, щоб живити складні годинникові автомати.",["race:Gnome"]="Гноми оцінять, що навіть після корабельної аварії, застрягши на ворожому березі, Джайромаст покладався на годинникову винахідливість, а не на команду з плоті й крові."},sec={{t="Здобич повзунів",b="Коли трешадони потопили корабель Ґелкака Джайромаста біля берегів Темного Узбережжя, гнома викинуло на берег разом із його пожитками. Серед найцінніших скарбів був заводний ключ, яким він запускав свого механічного першого помічника. Ключ розбився об прибережне каміння на три частини, і місцеві падальники одразу накинулися на уламки. Нижню частину вхопили агресивні ракоподібні, що бродять у прибої, — рифові й припливні повзуни, які нишпорять у мотлоху вздовж лінії припливу."},{t="Знову разом",b="Ґелкак не зможе запустити свого механічного матроса, доки не з'єднає нижній уламок із середнім і верхнім, які потягли прибережні мурлоки та лісові довгоступи вглибині суходолу. Лише видерши цей важкий уламок із панцирів прибережних крабів, гном-пірат може сподіватися відновити свій механізм і помститися за зірвану експедицію."}},faq={{q="Для чого потрібна Нижня Частина Ключа Ґелкака?",a="Це одна з трьох частин, потрібних, щоб полагодити заводний ключ Ґелкака Джайромаста — пірата, що застряг на березі. Без цього ключа не оживити його механічного першого помічника.",al={"що відчиняє ключ ґелкака","призначення нижньої частини ключа ґелкака","навіщо мені нижня частина ключа"}},{q="Звідки береться ця частина ключа?",a="Її знаходять на березі Темного Узбережжя: місцеві краби — обліплені черепашками припливні повзуни й люті рифові повзуни — затягли її до себе біля самої води.",al={"де нижня частина ключа ґелкака","хто дропає нижню частину ключа","місце нижньої частини ключа"}},{q="Чому ключ розбився на три частини?",a="Коли трешадони розтрощили корабель Ґелкака, його викинуло на берег, а ключ ударився об прибережні скелі й розлетівся на уламки, які розтягли місцеві тварини.",al={"чому ключ ґелкака зламався","як розбився ключ"}},{q="Хто такий Ґелкак Джайромаст?",a="Ґелкак Джайромаст — гном-пірат, що застряг на березі Темного Узбережжя після того, як трешадон знищив його судно й розкидав спорядження.",al={"хто такий ґелкак","історія ґелкака джайромаста"}}},fp="22,256,19.545.0,10.356.1,44.167.0,36.144.0,40.173.0,23.147.0"}
P.entries["item:branch-of-cenarius"] = {n="Гілка Кенарія",s="Гілка Кенарія — священна реліквія дріад, яку викрав мерзенний сатир Ґелтарис на сході Ашенвалю. Повернути цей родинний скарб було передсмертним бажанням дріади Анілії, яка загинула, захищаючи його від осквернителів лісу.",h="Гілка Кенарія — священна реліквія дріад, яку викрав мерзенний сатир Ґелтарис на сході Ашенвалю.",kw={"гілка кенарія","дріади","сатири","ґелтарис","анілія","ашенваль"},ang={["class:Druid"]="Як учні Кенарія, друїди відчувають особистий обов'язок вирвати будь-який артефакт, що носить ім'я Володаря Лісу, з лап демонічних сатирів, які його осквернюють.",["race:NightElf"]="Для нічних ельфів Ашенвалю допомагати дріадам і повертати їхні втрачені родові скарби — священний обов'язок перед природою."},sec={{t="Священна гілка під владою Тіні",b="Гілка Кенарія, яку шанують доньки Кенарія, уособлює і благословення Володаря Лісу, і глибокий зв'язок його дріад з Ашенвалем. Сестри-дріади Анілія та Ілліяна дуже дорожили гілкою, доки на них не напала зграя зіпсованих сатирів. Ватажок сатирів, Ґелтарис, захопив реліквію й смертельно поранив Анілію біля осквернених руїн на сході Ашенвалю. З останнім подихом Анілія вказала на північ, до арки, де ховається Ґелтарис, і благала знайти звитяжця, який вирве священну гілку з його пазурів і поверне її дріадам у Лісовій Пісні."}},faq={{q="Що таке Гілка Кенарія?",a="Гілка Кенарія — дорогоцінна реліквія природи, яку шанують дріади Ашенвалю. Вона носить ім'я й благословення напівбога Кенарія і слугує священним символом їхньої опіки над прадавнім лісом.",al={"історія гілки кенарія","що це за гілка","гілка дріад"}},{q="Хто вкрав Гілку Кенарія?",a="Реліквію викрав мерзенний сатир Ґелтарис, що влаштував засідку на дріад на сході Ашенвалю. Ґелтарис убив дріаду Анілію і втік із гілкою в пазурах на північ, за кам'яну арку.",al={"хто взяв гілку","хто її вкрав","хто дропає гілку кенарія"}},{q="Кому належить гілка?",a="Гілка належить дріадам Лісової Пісні. Анілія загинула, захищаючи її, тож реліквію повертають її сестрі Ілліяні, що тужить за нею, — так виконується передсмертне прохання Анілії.",al={"кому віддати гілку","кому потрібна гілка","кому її нести"}},{q="Де знайти гілку?",a="Гілка при Ґелтарисі, який чатує трохи на північ від руїн, де падає Анілія, на сході Ашенвалю, біля кордону з Азшарою.",al={"місце гілки","де гелтаріс","де знайти гілку"}}},fp="18,222,31.608.0,31.220.0,33.224.0,30.178.1,30.140.0"}
P.entries["item:brass-collar"] = {n="Латунний Нашийник",s="Латунний Нашийник — міцна прикраса на шиї Принцеси, призової свині родини Брекуеллів. Він слугує відчутним доказом для Ма Стоунфілд, що ненажерливу тварюку приборкано, перш ніж вона зіпсувала врожай на її фермі.",h="Латунний Нашийник — міцна прикраса на шиї Принцеси, призової свині родини Брекуеллів.",kw={"латунний нашийник","принцеса","свиня","ма стоунфілд","ферма стоунфілдів","брекуелли"},ang={["faction:Alliance"]="Для молодих шукачів пригод, що допомагають сільському люду Елвінну, зняти нашийник із Принцеси — класичний обряд посвяти в залагодженні сварок між фермерами маленьких містечок."},sec={{t="Трофей фермерського суперництва",b="Принцеса — не звичайна свиня: це величезна, гідна призової стрічки льоха родини Брекуеллів, що блукає довкола їхньої гарбузової ділянки на схід від садиби Маклурів. На лихо сусідам, її призові розміри живляться ненаситним апетитом до посівів Ферми Стоунфілдів. Утомлена втрачати цінну городину через мандрівну ненажеру, Ма Стоунфілд шукає когось, хто зважиться зарізати велетенську льоху. Оскільки Принцеса носить на шиї помітний латунний обруч, її нашийник слугує незаперечним доказом, що свиня-мародерка більше ніколи не плюндруватиме поля Стоунфілдів."}},faq={{q="Звідки береться Латунний Нашийник?",a="Нашийник знімають із Принцеси — велетенської свині-призерки, що риється на Гарбузовій Ділянці Брекуеллів на сході Лісу Елвінн, за хутором Маклурів.",al={"джерело латунного нашийника","хто дропає латунний нашийник","де взяти латунний нашийник"}},{q="Навіщо Ма Стоунфілд нашийник?",a="Принцеса раз у раз прокрадається на хутір Стоунфілдів і пожирає найкращі овочі Ма Стоунфілд. Нашийник доводить Ма Стоунфілд, що тварину нарешті вбито, перш ніж вона знищила решту врожаю.",al={"навіщо стоунфілд нашийник","призначення нашийника ма стоунфілд"}},{q="Кому належить Принцеса?",a="Принцеса належить Брекуеллам, хоча вона вільно бродить їхньою гарбузовою ділянкою разом із меншими кабанами-супутниками.",al={"чия принцеса","чия це свиня"}},{q="Чи може цей предмет випасти з когось, крім Принцеси?",a="Ні. Латунний нашийник є лише в Принцеси — його зробили спеціально під величезний обхват призової свині Брекуеллів.",al={"інші дропи нашийника","де ще знайти латунний нашийник"}}},fp="12,230,28.593.0,38.158.0,39.223.0,18.132.0,46.123.0"}
P.entries["item:bristleback-attack-plans"] = {n="Креслення Атаки Щетиноспинних",s="Креслення Атаки Щетиноспинних — грубі мапи й тактичні нотатки, накреслені шипогривами з Яру Тернистого Клинка. Вони описують узгоджену облогу, спрямовану просто на захоплення поселення тауренів — Табору Нарачі.",h="Креслення Атаки Щетиноспинних — грубі мапи й тактичні нотатки, накреслені шипогривами з Яру Тернистого Клинка.",kw={"креслення атаки","щетиноспинні","шипогриви","табір нарачі","вождь гоквінд","яр тернистого клинка","облога"},ang={["faction:Horde"]="Зірваний наступ Щетиноспинних гарантує, що Орда збереже надійну, нічим не загрожену опору на священних рівнинах Малгору.",["race:Tauren"]="Розкрита змова захищає самі тренувальні землі, де молоді таурени проходять перші обряди, і береже ваших старійшин і новачків від жорстокої облоги шипогривів."},sec={{t="Змова проти плато",b="Сховані глибоко в земляній печері Яру Тернистого Клинка, ці накидані тактичні замальовки показують: шипогриви Щетиноспинні вже не просто зчиняють сутички на околицях Плато Червоної Хмари. Їхні ватажки спланували організований, тривалий штурм, щоб увірватися в Табір Нарачі й винищити молодих тауренів, які там навчаються. Доставлена Вождю Гоквінду мапа дає племені змогу послати по підкріплення до Села Бладгуф і притупити навалу, перш ніж вона почнеться."}},faq={{q="Що містять Креслення Атаки Щетиноспинних?",a="Це тактична мапа й грубі вказівки щодо повномасштабної облоги Табору Нарачі. Вони свідчать, що шипогриви готуються до тривалого наступу, а не до поодиноких набігів.",al={"що в кресленнях атаки","що на мапі","плани бою щетиноспинних"}},{q="Де знайти ці креслення?",a="Вони лежать покинуті на земляній долівці в печері на узвишші в Яру Тернистого Клинка — трохи вище бічною стежкою від хатини ватажка Щетиноспинних.",al={"де креслення","де мапа","місце креслень атаки щетиноспинних"}},{q="Що робить Вождь Гоквінд, отримавши креслення?",a="Вождь Гоквінд усвідомлює, що плато загрожує неминуча небезпека, і, скориставшись цими відомостями, кличе на допомогу воїнів із Села Бладгуф, щоб посилити оборону Табору Нарачі.",al={"що робить гоквінд","реакція табору нарачі","реакція вождя гоквінда"}},{q="Чому Щетиноспинні нападають на Табір Нарачі?",a="Плем'я Щетиноспинних вважає колючі яри своїми володіннями, а присутність тауренів на плато — вторгненням, тож прагне вигнати поселення геть.",al={"чому квілборги нападають","мотив щетиноспинних"}}},fp="24,212,23.494.0,45.200.0,28.143.0,55.171.1,47.208.0"}
P.entries["item:bristleback-belt"] = {n="Пояс Щетиноспинних",s="Пояс Щетиноспинних — грубо зроблена частина спорядження, яку носять шипогриви, що заполонили Яр Тернистого Клинка. Для молодих тауренів, які входять у зрілість у Таборі Нарачі, зібрані пояси — речовий доказ відваги під час Обряду Сили.",h="Пояс Щетиноспинних — грубо зроблена частина спорядження, яку носять шипогриви, що заполонили Яр Тернистого...",kw={"пояс щетиноспинних","шипогриви","обряд сили","табір нарачі","вождь гоквінд","таурени"},ang={["faction:Horde"]="Приборкання агресивних шипогривів Малгору убезпечує південні кордони серця Орди в центральному Калімдорі.",["race:Tauren"]="Зняти пояс із поваленого Щетиноспинного — обряд посвяти для кожного юнака на Плато Червоної Хмари, перший крок до визнання старійшинами Тандер Блафу."},sec={{t="Доказ обряду",b="Плем'я Червоної Хмари випробовує кожного юнака, що прагне здобути повагу в Тандер Блафі, стародавніми Обрядами Земної Матері. Перше випробування, Обряд Сили, вимагає від посвяченого захистити плем'я від нагальних загроз. Оскільки ворожі шипогриви Щетиноспинні раз у раз грабують племінні запаси харчів і влаштовують засідки на мисливські загони біля Табору Нарачі, Вождь Гоквінд вимагає пояси цих зайд. Дванадцять поясів, принесених вождю, доводять, що посвячений здатен дивитися небезпеці в очі й завдати удару на захист племені."},{t="Ремесло шипогривів",b="Зняті з воїнів і шаманів Щетиноспинних по всьому Яру Тернистого Клинка, ці пояси зроблені з грубої шкури, мотузки й мотлоху. Як одяг вони нічого не варті для воїна-таурена, та це безпомилково робота шипогривів — незаперечний доказ убитого ворога. Принесені до табірного кола, вони й стають тим доказом, якого вимагає обряд."}},faq={{q="Для чого потрібні Пояси Щетиноспинних?",a="Вождь Гоквінд у Таборі Нарачі вимагає дванадцять Поясів Щетиноспинних як речовий доказ того, що новачок пройшов Обряд Сили — перший зі споконвічних Обрядів Земної Матері.",al={"навіщо мені пояс щетиноспинних","призначення поясів щетиноспинних","для чого пояс"}},{q="Звідки беруться Пояси Щетиноспинних?",a="Їх забирають у шипогривів Щетиноспинних та їхніх шаманів, що живуть у Яру Тернистого Клинка, трохи на схід від Табору Нарачі на Плато Червоної Хмари.",al={"де взяти пояс щетиноспинних","хто дропає пояси щетиноспинних","місце поясів щетиноспинних"}},{q="Чому Вождь Гоквінд хоче пояси, а не голови чи зброю?",a="Пояси — зручний доказ того, що посвячений убив ворогів племені. Обряд вимагає саме поясів, але не пояснює, чому обрано їх, а не інші трофеї.",al={"чому пояси","доказ для гоквінда"}},{q="Чому полюють саме на Щетиноспинних?",a="Щетиноспинні вдерлися на землі племені з Яру Тернистого Клинка: під покровом ночі нападають на Табір Нарачі й влаштовують засідки на мисливців-тауренів по всьому плато.",al={"чому вбивати щетиноспинних","загроза квілборгів мулґор"}}},fp="16,239,17.547.0,14.362.0,36.190.0,37.150.0,63.182.0,40.168.0"}
P.entries["item:bristleback-quilboar-tusk"] = {n="Ікло Шипогрива Щетиноспинів",s="Ікла шипогривів Щетиноспинів добувають з убитих шипогривів-Щетиноспинів на півночі та в центрі Пусток. Зібрані як доказ убивства, вони стають моторошними знаками помсти для скорботного орка-воїна Манкріка.",h="Ікла шипогривів Щетиноспинів добувають з убитих шипогривів-Щетиноспинів на півночі та в центрі Пусток.",kw={"ікло шипогрива","щетиноспини","манкрік","помста","шипогриви","перехрестя"},ang={["faction:Horde"]="Шипогриви загрожують Перехрестю й шляхам постачання по всіх Пустках; збираючи ікла, ви допомагаєте і особистій помсті Манкріка, і ширшим зусиллям Орди втихомирити край.",["race:Orc"]="Орки розуміють кровні борги й воїнське горе, тож жорстока гонитва Манкріка за шістдесятьма трофеями шипогривів — справа спільної честі."},sec={{t="Трофеї помсти",b="Шипогриви-Щетиноспини живуть у хащах і колючих лігвах по всіх Пустках, люто обороняючи свою територію від поширення Орди. Їхні ікла — великі зазубрені бивні, природна зброя в ближньому бою. Для Манкріка, досвідченого воїна з Перехрестя, чия дружина загинула в лютій засідці шипогривів, ці ікла — більше, ніж звичайні мисливські трофеї. Зібрати їх десятками — це чиста відплата, кривавий рахунок, що має змусити Щетиноспинів страждати так само глибоко, як страждає він."}},faq={{q="Кому потрібні ці ікла?",a="Їх вимагає Манкрік, орк-воїн із Перехрестя в Пустках. Він прагне помститися шипогривам Щетиноспинних після трагічної засідки, що розлучила його з дружиною.",al={"кому потрібні ікла щетиноспинних","хто бере ікла шипогривів","здати ікла"}},{q="Навіщо Манкрікові стільки іклів?",a="Манкріка поглинули горе й лють після того, як шипогриви-нападники здолали його й кинули помирати. Шістдесят іклів — для нього відчутний доказ того, що плем'я Щетиноспинних нещадно винищують у відповідь.",al={"чому 60 іклів","навіщо манкріку ікла","помста манкріка"}},{q="Які шипогриви носять ці ікла?",a="Їх забирають у членів племені Щетиноспинних, що блукають чагарниками й колючими таборами на півночі та в центрі Пусток.",al={"де падають ікла щетиноспинних","хто дропає ікла шипогривів"}},{q="Чи потрібні ці ікла для чогось, крім помсти Манкріка?",a="Ні. Хоча ікла шипогривів іноді йдуть на племінні прикраси чи товари, ці трофеї збирають лише для того, щоб утамувати Манкрікову жагу помсти.",al={"для чого ще ікла щетиноспинних","чи можна крафтити з іклів квілборгів"}}},fp="25,231,21.526.0,22.195.0,36.217.0,33.138.0,63.171.0"}
P.entries["item:brock-s-list"] = {n="Список Брока",s="Список Брока — донесення, складене наставником гірничої справи Броком Стоунсікером у Телсамарі. У ньому записані імена найкращих учнів-рудокопів, які заслужили почесні кайла від гільдійних палат Айронфорджа.",h="Список Брока — донесення, складене наставником гірничої справи Броком Стоунсікером у Телсамарі.",kw={"список брока","брок стоунсікер","телсамар","айронфордж","гірнича справа","кайла","ґолнір болдерто"},ang={["profession:Mining"]="Для рудокопів Список Брока — офіційне визнання учнів, які переросли грубий щебінь і долучаються до гордих традицій Гірничої гільдії Глибинної Гори.",["race:Dwarf"]="Пергамент відбиває дворфійські ремісничі традиції: він вшановує молодь, віддану кайлу й лопаті в надрах Каз Модану."},sec={{t="Відзнака рудокопа",b="Гірнича справа — живильна кров дворфійської цивілізації, і учні-копачі мусять довести свою вправність, перш ніж їм довірять серйозну роботу в жилах Каз Модану. У Телсамарі місцевий наставник гірничої справи складає цей пергамент, щоб нагородити учнів, які відзначилися в навчанні. У документі записано тих, хто заслужив почесні кайла — жадані знаки майстерності, викувані в столиці."},{t="Шлях до Великої Кузні",b="Почесні інструменти мають гравіювати й видавати в столиці, тож пергамент довіряють мандрівникам, що прямують до Айронфорджа. Грифоном із телсамарського сідала Список Брока потрапляє просто до Ґолніра Болдерто в Гірничій гільдії Глибинної Гори у Великій Кузні, де імена відзначених учнів викарбовують у камені й сталі."}},faq={{q="Що таке Список Брока?",a="Це перелік, який склав наставник гірничої справи Брок Стоунсікер у Телсамарі. У ньому названо учнів, що найкраще засвоїли гірничу справу й заслужили церемоніальні кайла.",al={"список брока","що це за річ","призначення списку брока"}},{q="Кому доставити Список Брока?",a="Спершу ви показуєте список Торґруму Боррелсону, майстрові грифонів у Телсамарі, щоб отримати переліт. Потім несете його просто до Ґолніра Болдерто з Гірничої Гільдії Глибокої Гори у Великій Кузні Айронфорджа.",al={"куди нести список","кому віддати список брока","здати список брока"}},{q="Навіщо Ґолнірові Болдерто цей документ?",a="Ґолнір відає інструментами Гірничої Гільдії Глибокої Гори в Айронфорджі. У нього вже готовий ящик почесних кайл, і йому потрібен список Брока, щоб вирізьбити на кожній нагороді ім'я учня.",al={"чому ґолнір","навіщо айронфорджу список"}},{q="Чому список відправляють грифоном, а не пішки?",a="Хоча гірські перевали через Лох Модан і ведуть назад до Дун Мороґа, переліт на грифоні в майстра Торґрума Боррелсона — найшвидший і найбезпечніший спосіб доставити справи гільдії просто у Велику Кузню.",al={"чому летіти в айронфордж","чому грифоном"}}},fp="12,201,21.384.0,27.365.0,21.191.0,33.217.0,46.199.0,49.221.0"}
P.entries["item:broken-and-battered-samophlange"] = {n="Зламаний і Понівечений Самофланж",s="Зламаний і Понівечений Самофланж — загадковий механізм, здобутий на об'єктах Венчурної Компанії в Пустках. Після невдалої спроби його перемайструвати міцність конструкції впала до критичної межі, і тепер його треба віднести до гоблінів-знавців в Оргріммарі, які, можливо, справді розуміють, як він працює.",h="Зламаний і Понівечений Самофланж — загадковий механізм, здобутий на об'єктах Венчурної Компанії в Пустках.",kw={"самофланж","венчурна компанія","венікі болтбакет","ріллі ґрісіґоб","оргріммар","пустки"},ang={["faction:Horde"]="Промислові трофеї з об'єктів Венчурної Компанії в Пустках приносять цінні технічні таємниці просто до гоблінських майстерень Оргріммара.",["profession:Engineering"]="Абияк приліплені шкали й важелі на й без того нестійкому механізмі Венчурної Компанії — хрестоматійне застереження проти бездумних переробок без креслення."},sec={{t="Перемайстрований до невпізнання",b="Самофланж — маловідомий фірмовий механізм, створений Венчурною Компанією для видобутку ресурсів у північних Пустках. Коли Венікі Болтбакет спробувала оглянути й переробити один такий, вона приладнала до нього зайві датчики, важелі й шкали, щоб виміряти його стійкість. Та замість стабілізувати механізм, її аматорське втручання вщент підірвало його міцність, і тепер він понівечений і ледь тримається купи. Збагнувши, що нові пристосування тільки доконають його, вона відіслала крихку конструкцію тому, хто має справжній заводський досвід."},{t="Дорога до Оргріммара",b="Щоб урятувати зламаний пристрій, потрібен хтось, хто сам працював на конвеєрах Венчурної Компанії. Так мандрівники потрапляють до Ріллі Ґрісіґоба, колишнього працівника Компанії, що тепер працює в Майстерні Ноґґа в Долині Честі Оргріммара. Такий понівечений апарат одразу привертає увагу інженера, і кожен, хто наважився поживитися на гоблінських об'єктах, видається йому або напрочуд сміливим, або нерозважливим."}},faq={{q="Що таке самофланж?",a="Самофланж — особливий механізм, який виготовляє Венчурна Компанія для своїх промислових робіт у Пустках. Як він влаштований усередині — таємниця гоблінської інженерії, яку мало хто з чужинців до кінця розуміє.",al={"що це за річ","що робить самофланж","призначення самофланжа"}},{q="Чому самофланж зламаний і понівечений?",a="Венікі Болтбакет спробувала доповнити його додатковими вимірювальними приладами, щоб перевірити міцність конструкції. Її вдосконалення цілком обернулися проти неї: пристрій утратив стійкість, а його чутливі внутрішні деталі пошкодилися.",al={"хто зламав самофланж","чому він пошкоджений","венікі його зламала"}},{q="Хто може полагодити цей пошкоджений апарат?",a="Тут потрібен хтось, хто знається на машинах Венчурної Компанії. Пристрій несуть до Ріллі Ґрісіґоб — інженера з Механічної Майстерні Ноґґа в Долині Честі в Оргріммарі.",al={"кому віднести цей апарат","куди нести самофланж","хто його ремонтує"}},{q="Звідки цей механізм узявся спершу?",a="Він потрапив сюди з бурових і видобувних робіт Венчурної Компанії на півночі Пусток, де гобліни-інженери використовують такі пристрої, щоб живити важкі видобувні машини.",al={"походження самофланжа","де його знайшли","походження компанії венчур"}}},fp="31,309,27.565.0,21.445.0,22.229.0,43.222.0,35.182.0,46.169.0"}
P.entries["item:broken-samophlange"] = {n="Зламаний Самофланж",s="Зламаний самофланж — загадковий механічний пристрій, знайдений на півночі Пусток. Попри пошкодження, його внутрішні шестерні й рухомі частини захоплюють інженерів, яким досить цікавості, щоб з'ясувати його справжнє призначення.",h="Зламаний самофланж — загадковий механічний пристрій, знайдений на півночі Пусток.",kw={"зламаний самофланж","спаттервалв","венікі болтбакет","механізм","інженерна справа","пустки"},ang={["faction:Horde"]="Пристрій з'являється на землях Орди в Пустках і спонукає до співпраці місцеві застави, майстрів і нейтральних торгових посередників.",["profession:Engineering"]="Самофланж — класична головоломка, від якої інженерові не втриматися: хитромудра машина з тендітними внутрішніми шестернями, чиє призначення можна з'ясувати, лише розібравши її й запустивши."},sec={{t="Загадковий механізм",b="Самофланж — одна з найдивніших штуковин, які трапляються на півночі Пусток. Навіть зламаний, механізм вражає майстерністю внутрішньої будови: він повен рухомих вузлів і дрібних шестерень. Гоблін із Раджета Спаттервалв ненароком пошкодив тендітний апарат, перш ніж його роботу встигли як слід описати. Прагнучи показати цікавим колегам в Андермайні робочі результати, знахідник шукав когось досить вправного, щоб полагодити пристрій, — і звернувся до Венікі Болтбакет, кмітливої майстрині біля прикордонної застави Вал Мор'шан."},{t="У пошуках умілих рук",b="Оглянувши зламаний апарат, навіть така допитлива голова, як Венікі, не може одразу збагнути, для чого насправді призначений самофланж. Проте дражливі звуки внутрішнього годинникового механізму та його жвавий рух одразу її захоплюють. Вона не викидає поламаний мотлох: загадка його будови надихає її спробувати полагодити пристрій і побачити, як механізми працюють на повну."}},faq={{q="Що таке самофланж?",a="Його призначення — загадка навіть для майстрів, що намагаються його полагодити. Назва спантеличує, але, якщо роздивитися пристрій, видно складні шестерні й рухомі деталі, створені для якоїсь невідомої промислової мети.",al={"призначення самофланжа","що робить самофланж","що таке самофланж"}},{q="Чому самофланж зламаний?",a="Гоблін Спаттервалв із Раджета, якому цей пристрій принесли, зламав тонкий механізм, длубаючись у ньому. Зрозумівши, що пристрій заклинило, перш ніж його таємниці вдалося передати колегам в Андермайні, гобліни шукають знавця, який знову запустить його.",al={"як він зламався","історія зламаного самофланжа"}},{q="Хто така Венікі Болтбакет?",a="Венікі Болтбакет — допитлива майстриня, що працює на півночі Пусток, трохи на південь від Валу Мор'шан на кордоні з Ашенвалем. Їй вистачає інженерної цікавості, щоб оглядати й відбудовувати дивні механізми.",al={"де венікі","місце болтбакет"}},{q="Чому самофланжем цікавляться гобліни в Андермайні?",a="Гоблінські інженери й ділки завжди радо розбирають унікальні механізми, щоб відтворити їх. Чутка про дивний пристрій дійшла до знайомих в Андермайні, і там одразу зацікавилися, які переваги він може дати.",al={"інтерес андермайну","чому гоблінам цікаво"}}},fp="18,223,20.570.0,24.409.0,22.209.0,30.263.0,26.230.0,46.234.0"}
P.entries["item:broken-tools"] = {n="Зламані Інструменти",s="Зламані Інструменти — потрощені рештки кайл дворфійських старателів, навмисно знищених на ковадлі. Вони слугують речовим доказом для Бейна Бладгуфа, що загарбницькі дворфійські розкопки, які загрожують землі й звірині Малгору, зірвано.",h="Зламані Інструменти — потрощені рештки кайл дворфійських старателів, навмисно знищених на ковадлі.",kw={"зламані інструменти","бейн бладгуф","дворфи","розкопки","кайла","малгор","кодо"},ang={["profession:Blacksmithing"]="Методично нищити на ковадлі тонку дворфійську ковальську роботу — означає перетворити горно майстра на знаряддя захисту рідної землі.",["race:Tauren"]="Для тауренів принести Бейну зіпсовані інструменти означає захистити Матір-Землю від загарбницького копання, що мучить тутешніх звірів."},sec={{t="Саботаж розкопок",b="На північний захід від Села Бладгуф дворфійські землекопи влаштували розкопки в пагорбах Малгору. Дворфи шукають поховану стародавню історію, а таурени вбачають у їхньому зухвалому копанні пряме осквернення Матері-Землі. Гуркіт і руйнування тривожать місцеву звірину, особливо мандрівні стада кодо. Замість просто прогнати землекопів, молодий Бейн Бладгуф наказує захисникам відібрати в старателів залізні кайла й потрощити їх на горні, щоб експедиція більше не могла шматувати землю."}},faq={{q="Що це за Зламані Інструменти?",a="Це розбиті обухи й розщеплені держаки Кирок Шукача, відібраних у дворфів-копачів у Малгорі й навмисно розтрощених у кузні.",al={"зламані інструменти","що за зламані інструменти","розбиті кирки"}},{q="Чому Бейн Бладгуф хоче їх знищити?",a="Бейн вважає, що розкопувати землю — значить її осквернювати й лютити звірів Малгору, особливо кодо. Розтрощені інструменти зупиняють розкопки й ясно дають зрозуміти: земля не віддасть своєї мудрості нерозважливим копачам.",al={"чому знищити кирки","чому бейн хоче зламані інструменти","бейн дворфи копають"}},{q="Де можна розбити ці кирки?",a="Підійде будь-яке справне ковальське горно. Ви можете скористатися горном просто на дворфських розкопках або знайти його в Селі Бладгуф чи нагорі в Тандер Блафі.",al={"як розбити кирки","де кузня","розбити кирку рудознавця"}},{q="Чому дворфи копають у Малгорі?",a="Дворфи вірять, що під землею Малгору поховано глибокі таємниці й реліквії давнини. Одержимі пошуками свого походження, вони часто перекопують чужі землі, не зважаючи на корінних мешканців.",al={"чому дворфи в малгорі","розкопки дворфів у малгорі"}}},fp="12,250,18.570.0,28.152.0,45.239.0,32.165.0,35.218.0"}
P.entries["item:bundle-of-crocolisk-skins"] = {n="Згорток Шкур Кроколіска",s="Згорток шкур кроколіска — підготовлений пакунок вичинених шкур плазунів, здобутих у небезпечних болотах Багнокраю. Він призначений для шкірників Гавані Менетіл і є цінним товаром для пошиття міцних чобіт і цупкого портового спорядження.",h="Згорток шкур кроколіска — підготовлений пакунок вичинених шкур плазунів, здобутих у небезпечних болотах...",kw={"згорток шкур кроколіска","кроколіски","гавань менетіл","джеймс галлоран","ейнар","багнокрай"},ang={["faction:Alliance"]="Мисливці з околиць постачають матеріали, завдяки яким гарнізон і мешканці Гавані Менетіл мають належне спорядження проти суворої болотяної негоди."},sec={{t="Торгівля в Багнокраї й родинні чвари",b="Розлогі водойми Багнокраю кишать кроколісками, чиї цупкі, водостійкі шкури — важливий товар для прибережного поселення Гавань Менетіл. Мисливці, що наважуються лізти в болота, збирають і вичиняють ці шкури, а тоді відправляють на захід місцевим майстрам на кшталт Джеймса Галлорана. Та цей згорток потрапив до рук шукача пригод незвичним шляхом: мисливець Ейнар шукав посланця лише для того, щоб не вертатися до міста й не потрапити під гарячу руку своєї розгніваної дружини, Сіди."}},faq={{q="Для чого потрібен Згорток Шкур Кроколіска?",a="У згортку — сирі й вичинені болотяні шкури для Джеймса Галлорана, чинбаря з Гавані Менетіл. Галлоран робить із цих грубих шкур міцні чоботи, пояси й шкіряні обладунки, які добре служать у вогкій, затопленій місцевості Багнокраю.",al={"використання шкур кроколіска","для чого ці шкури","призначення згортка шкур"}},{q="Хто зібрав ці шкури кроколісків?",a="Шкури добув і зв'язав у згорток мисливець Ейнар на болотах. Зазвичай він сам возить свій крам до містечка, але цього разу просить перехожих мандрівників віднести його — щоб не сваритися з дружиною Сідою.",al={"хто зробив згорток","хто зібрав шкури","ейнар кроколіск"}},{q="Хто такий Джеймс Галлоран?",a="Джеймс Галлоран — шкірник і чинбар із портового містечка Гавань Менетіл. Він скуповує сирі й вичинені шкури в місцевих болотяних мисливців і шиє з них чоботи, вичинену шкіру й практичне спорядження для моряків, вояків і містян.",al={"роль джеймса галлорана","хто такий галлоран","шкіряр мененіл"}}},fp="25,265,37.497.0,47.262.0,35.234.0,22.239.0"}
P.entries["item:bundle-of-hides"] = {n="Оберемок Шкур",s="Оберемок шкур — вичинені шкури звірів Пусток, зв'язані докупи для перевезення через центральний Калімдор. Призначений для шкірників Тандер Блафа, це звичайний вантаж для гінця, що знайомить мандрівників із мережею польотів Орди на вітрокрилах.",h="Оберемок шкур — вичинені шкури звірів Пусток, зв'язані докупи для перевезення через центральний Калімдор.",kw={"оберемок шкур","шкірництво","тандер блаф","деврак","вітрокрили","перехрестя"},ang={["faction:Horde"]="Перевезення простих вантажів, як-от шкур, небом показує, як Орда використовує повітряні шляхи на вівернах, щоб прив'язати віддалені пустельні застави просто до столиць.",["race:Tauren"]="Таурени покладаються на природні матеріали й шанобливе полювання, перетворюючи шкури із сусідньої савани на обладунки й вироби, що продаються на ятках Малгору."},sec={{t="Прикордонна торгівля",b="Неприборкані рівнини Пусток — дім для величезних стад кодо, левів, що чатують на здобич, і зграй рапторів. Мисливці на торгових шляхах знімають шкури з цих звірів не лише заради м'яса й виживання, а й щоб постачати міських ремісників. Без сирих шкур із глушини такі поселення, як Тандер Блаф, ледве втримали б своїх шкірників, які перетворюють висушені шкури на необхідне спорядження, торбинки, обладунки й ремені для Орди."},{t="Вантаж у небо",b="Везти важкі вантажі суходолом через Пустки й угору до Малгору — небезпечно й повільно: повсякчас загрожують шипогриви й кентаври-грабіжники, що никають довкола. Щоб пришвидшити доставку між Перехрестям і столицею тауренів, гінці покладаються на навчених віверн Деврака. Передати оберемок шкур гінцеві-вітрокрилу — означає побачити, як ефективно повітряні подорожі долають розірвану місцевість Калімдору."}},faq={{q="Для чого потрібен Оберемок Шкур?",a="Ці шкури зняли з тварин по всіх Пустках, і призначені вони для Агану — шкірника в Тандер Блафі. Він робить із них шкіряні вироби й обладунки для тауренів та їхніх союзників з Орди.",al={"призначення оберемка шкур","навіщо возити шкури","для чого шкури"}},{q="Хто отримує вантаж у Тандер Блафі?",a="Пакунок отримує Агану. Він працює в Зброярні Геви, що стоїть біля самого підніжжя сідала вітрокрилів у Тандер Блафі.",al={"хто отримує шкури","одержувач оберемка шкур","де ану"}},{q="Навіщо відправляти цей оберемок на вітрокрилі?",a="Пішки перетинати Пустки й підніматися на плато Малгору — справа кількох днів, та й легко потрапити в засідку кентаврів чи шипогривів. Переліт на вітрокрилі в майстра польотів Перехрестя, Деврака, гарантує, що товар прибуде швидко й неушкодженим.",al={"чому шкури летять","переліт перехрестя шкури","вітрокрил дерака"}},{q="Хто зібрав оберемок у Пустках?",a="Шкури тварин із Пусток зібрав в оберемок Джахан Гоквінг — торговець шкіряними й кольчужними обладунками на Перехресті та колега Агану.",al={"хто дав шкури","шкури джахана","хто зібрав шкури"}}},fp="15,302,14.424.0,15.402.0,37.204.0,43.131.0,38.239.0,39.148.0"}
P.entries["item:bundle-of-wood"] = {n="Оберемок Дров",s="Оберемки Дров — зв'язані стоси деревини, заготовлені робітниками біля Лісозаготівельного Табору Східної Долини на сході Лісу Елвінн. Нещодавно покинуті через хижу звірину, вони становлять важливі поставки, потрібні, щоб виконати місцеві угоди на деревину.",h="Оберемки Дров — зв'язані стоси деревини, заготовлені робітниками біля Лісозаготівельного Табору Східної...",kw={"оберемок дров","деревина","лісозаготівельний табір","східна долина","лісоруби","ведмеді"},ang={["faction:Alliance"]="Кожен повернутий оберемок напряму підтримує відбудову Стормвінда, дбаючи, щоб важливі поставки деревини вчасно доходили до поселень Елвінну й Вестфолу."},sec={{t="Покинута деревина",b="Лісозаготівельний Табір Східної Долини — головне джерело деревини для Королівства Стормвінд: свіжозрубаний ліс іде на захід, щоб живити міське господарство й будівництво. Нещодавно агресивна тутешня звірина — лісові ведмеді й хижі вовки — вдерлася в гаї на північний захід від табору. Нажахані лісоруби втекли, рятуючи життя, й покинули щойно зібрані Оберемки Дров там, де вони лежали серед дерев. Терміни постачання тиснуть, тож наглядачі табору покладаються на відважних подорожніх, які прослизнуть повз хижаків і повернуть зрубану деревину, перш ніж угоди буде порушено."}},faq={{q="Чому ці оберемки дров покинули в лісі?",a="На лісорубів, що заготовляли деревину на північний захід від Лісозаготівельного Табору Східної Долини, напали люті вовки й ведмеді, що никають лісом, і прогнали їх. Нарубані оберемки так і лишилися розкиданими по лісі.",al={"чому дрова на землі","чому покинули дрова","покинуті дрова ельвін"}},{q="Кому треба зібрати ці дрова?",a="Раелен, наглядач Лісозаготівельного Табору Східної Долини, конче потребує цих дров, щоб вчасно відправити замовлену партію деревини.",al={"хто хоче дрова","дрова рейлена","здати дрова"}},{q="Де знайти ці оберемки?",a="Вони розкидані просто на землі на північний захід від Лісозаготівельного Табору Східної Долини, у густих заростях, де живуть ведмеді й вовки Лісу Елвінн.",al={"місце оберемків дров","де дрова","місця дров іствейлу"}},{q="Чому міська варта не прогнала звірів?",a="Раелен звертався до Помічника Рейнера через навалу звірів, але місцевих маршалів і вартових ледве вистачає на весь Елвінн, тож лісорубам доводиться шукати допомоги на боці, щоб швидко повернути колоди.",al={"чому немає варти","помічник рейнер дрова","варта іствейлу"}}},fp="14,238,16.594.0,54.205.0,30.132.0,30.148.0,48.207.0"}
P.entries["item:burning-blade-medallion"] = {n="Медальйон Палаючого Клинка",s="Медальйон Палаючого Клинка — темний талісман, який носять культисти, що причаїлися в Долині Випробувань. Захищений темною магією в глибинах Ковену Палаючого Клинка, він слугує прямим доказом демонічної скверни, що намагається підкорити молодих воїнів Дуротару.",h="Медальйон Палаючого Клинка — темний талісман, який носять культисти, що причаїлися в Долині Випробувань.",kw={"медальйон","палаючий клинок","культ","долина випробувань","скверна","бейншедов"},ang={["class:Warlock"]="Хоч чорнокнижники Орди практикують темну магію під суворою дисципліною, медальйон втілює свавільне, нестримне ремесло Скверни Палаючого Клинка, що загрожує стабільності Дуротару.",["race:Orc"]="Медальйон уособлює тінь демонічної скверни, яка колись поневолила орчий рід, а тепер загрожує молодим посвячуваним ще до того, як вони покинуть Долину Випробувань."},sec={{t="Знак скверни",b="Знайдений глибоко у звивистих печерах Ковену Палаючого Клинка медальйон тримає Ярроґ Бейншедов — агент зловісного культу Палаючого Клинка. Виявлена ворожінням Зуріти Фарґейз, ця дрібничка спрямовує темну силу серед бісівських фамільярів і переслідувачів Скверни культу. Здолати її носія і забрати медальйон — означає урвати підступну спробу підточити тренувальні землі Орди зсередини самого Дуротару."}},faq={{q="Що таке Медальйон Палаючого Клинка?",a="Це магічний талісман, який носить Ярроґ Бейншедов — агент культу Палаючого Клинка, що ховається в Дуротарі. Медальйон зосереджує темну магію й слугує знаком вірності серед культистів.",al={"таліман палаючого клинка","медальйон ковену","медальйон ярроґа"}},{q="Хто хоче повернути медальйон?",a="Зуріта Фарґейз, орчиха-провидиця біля Лігва в Долині Випробувань, шукає медальйон, щоб викорінити вплив демонів і вивчити місцеві підступи культу.",al={"хто бере медальйон","кому здати медальйон","завдання зурити фаргейз"}},{q="Де знайти медальйон?",a="Він захований глибоко в Ковені Палаючого Клинка — прихованій печері на північний захід від Лігва в Долині Випробувань. Його стереже Ярроґ Бейншедов, що чатує на верхніх уступах печери.",al={"де ярроґ бейншедоу","місце медальйона палаючого клинка","як знайти медальйон"}},{q="Що означає поява медальйона для Дуротару?",a="Знахідка підтверджує, що культ Палаючого Клинка заслав своїх агентів просто на випробувальні землі Орди, — а отже, задуми культистів по всій батьківщині орків значно ширші й небезпечніші.",al={"чому культисти в долині випробувань","чи палаючий клинок у дуротарі"}}},fp="23,268,20.452.0,36.208.0,34.171.0,29.192.0,52.215.0"}
P.entries["item:burning-blood-quest-item"] = {n="Палаюча Кров (предмет завдання)",s="Палаюча Кров — неприродна рідина, яку добувають із лютих воргенів Найтбейн, що нишпорять Сутінколіссям. Стормвіндському бронярові Ґріманду Елмору потрібно двадцять фіалів цієї вогненної есенції для дослідів із новими ковальськими прийомами.",h="Палаюча Кров — неприродна рідина, яку добувають із лютих воргенів Найтбейн, що нишпорять Сутінколіссям.",kw={"палаюча кров","ґріманд елмор","воргени","кишкодер","погибель роланда","ковальство"},ang={["class:Warrior"]="Ґріманд Елмор випробовує на цьому непередбачуваному реагенті найновіші ковальські методи й винагороджує воїнів-початківців, які його здобудуть, міцними латами, викуваними на замовлення.",["profession:Blacksmithing"]="Майстри-ковалі часом виходять за межі звичного вугілля й води й використовують екзотичні реагенти, як-от палаючу кров воргенів, щоб гартувати важкі метали за надвисоких температур."},sec={{t="Непередбачуваний реагент",b="Прокляті воргени Найтбейн, що заполонили Сутінколісся, кипять дивною неприродною люттю, а їхня кров буквально пече. Цю пекучу рідину можна взяти у звірів, що блукають моторошними лісами й покинутими розкопками Погибелі Роланда. Добувати її бридко, проте вогненна речовина має рідкісні металургійні властивості, яких прагнуть майстри-бронярі, щоб гартувати міцні латні обладунки."},{t="Дослід Елмора",b="Ґріманд Елмор, досвідчений майстер, що працює в Дворфійському Кварталі Стормвінда, хоче випробувати нові ковальські методи, започатковані його колишнім учнем Фуреном Лонґбірдом. Щоб перевірити, чи варті чогось ці сміливі прийоми кування, Елморові потрібна палаюча кров, а ще важкий палаючий камінь, що зберігається у ватажка воргенів Кишкодера. Тим, хто наважиться вийти проти хижої зграї й принести киплячу рідину, обіцяно міцні обладунки воїна, викувані в жарі його горна."}},faq={{q="Що таке Палаюча Кров?",a="Палаюча Кров — пекуча, нестійка рідина з тіл воргенів Найтбейн у Сутінколіссі. Через свій неприродний жар вона стала цінним реагентом для особливих дослідів у зброярстві.",al={"історія палаючої крові","що таке палаюча кров","кров воргенів"}},{q="Звідки береться Палаюча Кров?",a="Її збирають із різних воргенів Найтбейн, що никають лісами Сутінколісся, — особливо з тих, що збираються біля покинутої копальні Погибель Роланда.",al={"де взяти палаючу кров","хто дропає палаючу кров","місце палаючої крові"}},{q="Навіщо вона Ґріманду Елмору?",a="Ґріманд Елмор хоче випробувати новаторські способи кування обладунків, які розробив Фурен Лонґбірд. Поєднавши киплячу кров із палаючим каменем, він має намір викувати виняткову кольчугу для воїна-мандрівника.",al={"чому ґріманд хоче кров","ґріманд елмор завдання на кров"}},{q="Чому кров воргенів Найтбейн палає?",a="Воргени Сутінколісся — неприродні потвори, викликані темною й хаотичною магією. Прокляття, що тече в жилах зграї Найтбейн, спотворює їхні тіла й наповнює кров вогненною, неприродною лютістю.",al={"чому в воргенів палає кров","чи кров воргенів вогонь"}}},fp="26,230,18.410.0,19.465.0,22.184.0,35.156.0,32.239.0,42.210.0"}
P.entries["item:burning-rock"] = {n="Палаючий Камінь",s="Палаючий Камінь — незвичайний тліючий мінерал, який забирають у ватажка воргенів Найтбейн Кишкодера глибоко в Погибелі Роланда в Сутінколіссі. Майстрові-ковалеві Ґріманду Елмору в Стормвінді потрібна ця рідкісна дивовижа разом із вогненною кров'ю воргенів, щоб викувати особливі зачаровані обладунки для перспективних воїнів.",h="Палаючий Камінь — незвичайний тліючий мінерал, який забирають у ватажка воргенів Найтбейн Кишкодера глибоко в...",kw={"палаючий камінь","кишкодер","ґріманд елмор","погибель роланда","фурен лонґбірд","ковальство"},ang={["class:Warrior"]="Ґріманд Елмор залучає досвідчених воїнів, щоб ті здобули цей камінь у Погибелі Роланда, і винагороджує їхню відвагу обладунками, викуваними на його жарі.",["profession:Blacksmithing"]="Палаючий Камінь — екзотичне джерело жару, що показує незвичні методи плавлення й гартування, які досліджують бронярі Стормвінда й Айронфорджу."},sec={{t="Тліючий трофей",b="Палаючий Камінь, який носить Кишкодер — лютий ворген Найтбейн, що зачаївся в занедбаних штольнях Погибелі Роланда, — дивовижа навіть серед підземних жахіть Сутінколісся. Він випромінює невгасимий надприродний жар, і саме це привернуло увагу Ґріманда Елмора в Стормвінді. Прагнучи випробувати експериментальні ковальські прийоми, започатковані його колегою Фуреном Лонґбірдом, Ґріманд використовує природний жар каменю й киплячу кров місцевих воргенів, щоб гартувати міцні латні пластини для досвідчених бійців."}},faq={{q="Де знайти Палаючий Камінь?",a="Він у Кишкодера — лютого ватажка воргенів, що живе в копальні Погибель Роланда на сході Сутінколісся.",al={"місце палаючого каменю","хто дропає палаючий камінь","де взяти палаючий камінь"}},{q="Кому потрібен Палаючий Камінь?",a="Ґріманду Елмору — вправному дворфові-ковалеві з Дворфійського Кварталу Стормвінда. Камінь потрібен йому, щоб випробувати експериментальні способи обробки металу.",al={"кому потрібен палаючий камінь","хто здає палаючий камінь","ґріманд елмор палаючий камінь"}},{q="Навіщо камінь Ґріманду Елмору?",a="Ґріманд хоче випробувати способи кування, які розробив Фурен Лонґбірд. Разом із киплячою кров'ю воргенів Найтбейн тліючий камінь дає сильний жар, потрібний, щоб викувати незвичайні обладунки.",al={"використання палаючого каменю","навіщо палаючий камінь","що робить палаючий камінь"}},{q="Як цей камінь пов'язаний із воргенами?",a="Воргени Найтбейн із Погибелі Роланда мають дивні вогняні риси — як-от палаючу кров. Кишкодер, ватажок їхньої зграї, тримає Палаючий Камінь глибоко в копальні, але чи викопали вони його, чи принесли з собою, — лишається загадкою.",al={"чому в воргенів палаючий камінь","історія палаючого каменю ґатспіл"}}},fp="12,308,18.488.0,32.114.0,27.157.0,32.216.0,50.255.0"}
P.entries["item:cache-of-zanzil-s-altered-mixture"] = {n="Схованка Зміненої Мікстури Занзіла",s="Схованка Зміненої Мікстури Занзіла — запас сильної отрути, замкнений у скрині у вежі Венчурної Компанії біля Багнистого Болота. Названа на честь знахаря тролів джунглів Занзіла, вона стала важливою ціллю для Розтрощеної Руки в Оргріммарі.",h="Схованка Зміненої Мікстури Занзіла — запас сильної отрути, замкнений у скрині у вежі Венчурної Компанії біля...",kw={"занзіл","мікстура","отрута","венчурна компанія","розтрощена рука","ґаллівікс","багнисте болото"},ang={["class:Rogue"]="Здобути мікстуру — важливий обряд посвяти для розбійників Орди: так вони доводять Розтрощеній Руці, що вміють зламувати замки, обчищати кишені й поводитися з отрутами.",["faction:Horde"]="Отруєна вежа Венчурної Компанії на північ від Багнистого Болота — пряма загроза і довкіллю, і безпеці Дуротару та Пусток."},sec={{t="Отруйна справа",b="На північ від Багнистого Болота в Пустках Венчурна Компанія тримає вежу-заставу. Схованка зміненої мікстури, названої на честь сумнозвісного знахаря-троля Занзіла, лежить замкнена в особистій скриньці Великого Наглядача Пузіка Ґаллівікса на самій верхівці вежі. Отрута послабила все живе у вежі, і тамтешні гобліни беззахисні перед будь-яким сміливцем, що наважиться вдарити."},{t="Здобич для Розтрощеної Руки",b="Такі небезпечні алхімічні речовини так близько від Дуротару одразу привернули увагу Розтрощеної Руки — таємної гільдії розбійників, що діє під Оргріммаром. Щоб і знешкодити загрозу, і здобути мікстуру для власних розвідувальних досліджень, наставник Шентул відрядив агентів штурмувати вежу, стратити Ґаллівікса й зламати скриньку наглядача. Щоб забрати нестійкий вміст схованки, треба неабиякого вміння проникати потай, адже, торкнувшись зараженого вмістилища, злодій ризикує й сам отруїтися його згубною, виснажливою отрутою."}},faq={{q="Що таке Змінена Мікстура Занзіла?",a="Це сильна отрута, що носить ім'я троля-знахаря Занзіла. Її запас замкнено у вежі Венчурної Компанії біля Багнистого Болота, де отрута ослабила все живе всередині.",al={"що таке мікстура занзіла","що за схованка","зілля занзіла"}},{q="Де знайти схованку?",a="Мікстура зберігається в Скриньці Ґаллівікса на самій верхівці вежі Венчурної Компанії, трохи на північ від Багнистого Болота на північному сході Пусток.",al={"де мікстура","де схованка занзіла","місце мікстури"}},{q="Навіщо мікстура Розтрощеній Руці?",a="Шентул і Розтрощена Рука хочуть знищити небезпечне гніздо Венчурної Компанії просто на порозі Орди, а заразом здобути рідкісну речовину, щоб глибше пізнати отрути й бойові яди.",al={"кому потрібна мікстура","чому шентул її хоче","місія розтрощеної руки"}},{q="Як відчинити скриню зі схованкою?",a="Щоб обійти механізм скрині, потрібна неабияка вправність у зламуванні замків, тож відчинити її може лише навчений агент, який уміє впоратися з тонкими замками навіть у небезпечних умовах.",al={"як відчинити скриню ґаллівікса","відчинити скриню занзіла","зламати замок схованки занзіла"}}},fp="33,265,18.395.0,31.565.1,33.198.0,25.155.0,45.218.0,47.204.0"}
P.entries["item:cactus-apple"] = {n="Кактусове Яблуко",s="Кактусові яблука — тверді, соковиті плоди, зібрані з суворої рослинності Долини Випробувань у Дуроторі. Вони розкошують у сухій пустельній спеці, і місцеві орки цінують їх як рідкісне, освіжне джерело харчу.",h="Кактусові яблука — тверді, соковиті плоди, зібрані з суворої рослинності Долини Випробувань у Дуроторі.",kw={"кактусове яблуко","кактус","дуротар","долина випробувань","ґалґар","їжа"},ang={["profession:Cooking"]="Для кухарів, що виживають у нетрях Дуротару, збирання пустельних кактусів — головний урок, як перетворити колючу, негостинну пустельну рослинність на поживну й зволожувальну страву.",["race:Orc"]="Молоді орки, що проходять випробування в Дуроторі, швидко засвоюють: пережити червоний каньйон — означає користатися кожною дрібкою вологи, яку дає природа."},sec={{t="Пустельний урожай",b="Випалена сонцем земля Дуротару не розпещує мешканців, змушуючи їх використовувати будь-які витривалі рослини, що переживають стихію. Кактусові яблука ростуть гронами на товстих кактусах, розкиданих по Долині Випробувань. Їх важко зібрати, не зачепивши кілька колючок, зате плоди дають життєво важливу вологу в задушливому каньйоні. Місцевий орк на ім'я Ґалґар збирає ці плоди для свого фірмового Сюрпризу із Кактусових Яблук — прохолодних ласощів, що приносять жадане полегшення новобранцям на суворому початковому вишколі."}},faq={{q="Де ростуть кактусові яблука?",a="Вони ростуть дико на червоній куряві Долини Випробувань на півдні Дуротару — зазвичай біля підніжжя кремезних кактусів, розкиданих улоговиною.",al={"місця кактусових яблук","де знайти кактусове яблуко","місце кактусового яблука"}},{q="Що таке Сюрприз із Кактусових Яблук?",a="Це холодна освіжна страва, яку готує Ґалґар із Долини Випробувань. Зі свіжозібраних кактусових яблук він робить солодкі ласощі, що миттю рятують від нещадної спеки дуротарської пустелі.",al={"що таке сюрприз ґалґара","рецепт кактусових яблук","частування ґалґара"}},{q="Хто просить принести ці яблука?",a="Ґалґар, орк із Долини Випробувань, віддає порції свого прохолодного десерту кожному молодому новобранцеві, який вирушить у пустелю й принесе шість свіжих яблук.",al={"хто дає завдання на кактусові яблука","хто хоче кактусові яблука","яблука ґалґара"}}},fp="12,219,14.536.0,28.166.0,30.207.0,26.165.0"}
P.entries["item:calor-s-note"] = {n="Записка Калора",s="Записка Калора — клаптик вицвілого пергаменту, яким лісник Калор рекомендує перевіреного шукача пригод Майстрові Джонатанові Каревіну. Вона відчиняє двері до потаємного гурту, що діє поряд із міським ополченням Даркшира, але не є його частиною.",h="Записка Калора — клаптик вицвілого пергаменту, яким лісник Калор рекомендує перевіреного шукача пригод...",kw={"записка калора","калор","джонатан каревін","даркшир","сутінколісся","воргени"},ang={["class:Paladin"]="Джонатан Каревін вітає посланця словами «Слава у Світлі» — ознака ідейної спорідненості зі святими воїнами, що присягли очистити Сутінколісся від демонів і нежиті.",["faction:Alliance"]="Армії Стормвінда в Сутінколіссі немає зовсім, тож неофіційні гурти, як-от коло Каревіна, і Нічна Варта — єдиний заслін південного кордону від темряви."},sec={{t="Рідкісна рекомендація",b="Сутінколісся неприязне до чужинців, а Калора, як відомо, вразити нелегко. Лише той, хто вцілів у сутичках із кровожерними воргенами, що нишпорять лісом, заслуговує на його повагу — і тоді він пише цю коротку записку. Принесений до Даркшира вицвілий клаптик стає своєрідною перепусткою й відрекомендовує чужинця просто Джонатанові Каревіну."},{t="Власний хрестовий похід",b="Даркшир покладається на Нічну Варту в обороні міста, а Калор і Каревін ведуть похмурішу, потаємнішу боротьбу. Калор відверто нарікає, що міська варта переважає їх числом, і сподівається знайти досить вправних бійців для своєї приватної війни. Доставлена записка відкриває шлях до походу Каревіна проти демонів, нежиті й прихованих поплічників, що сприяють занепаду Сутінколісся."}},faq={{q="Що таке Записка Калора?",a="Це послання, яке Калор власноруч написав на клапті вицвілого пергаменту. Це особиста рекомендація, що ручається за бойову вправність і надійність шукача пригод у боротьбі з жахами Сутінколісся.",al={"записка калора","що це за записка","що написано в записці"}},{q="Хто отримує записку?",a="Записку адресовано Джонатанові Каревіну — суворому чоловікові з Даркшира, що очолює віддану боротьбу з темними силами, які загрожують краю.",al={"кому віддати записку","хто отримує записку калора","записка джонатана каревіна"}},{q="Що Калор думає про Нічну Варту?",a="Калор вважає, що Нічній Варті не до снаги справжні загрози, які чигають у Сутінколіссі. Передаючи записку, він каже, що хотів би зібрати стільки здібних союзників, щоб їх стало більше, ніж ополченців, — і нарешті завершити нагальну справу, яку його невеликий гурт веде сам-один.",al={"калор і нічна варта","чому калор хоче переважити нічну варту"}},{q="З ким бореться Джонатан Каревін?",a="Майстер Каревін веде непохитну боротьбу з демонами, нежиттю та смертними посібниками, що допомагають їм у Сутінколіссі. Він цінує пильність і відданість Святому Світлу й довіряє лише перевіреним людям.",al={"справа каревіна","що робить каревін","з ким воює каревін"}}},fp="12,256,21.344.0,17.383.0,21.218.0,22.163.0,38.272.0,48.227.0"}
P.entries["item:candle-of-beckoning"] = {n="Свічка Прикликання",s="Свічка Прикликання — зачарована ритуальна свічка, яку тримає відлюдний некромант Ґунтер Арканус на Озері Світлої Води. Якщо поставити й запалити її на вівтарі на сусідньому острівці, вона прикликає неспокійного духа, відомого як Лілліт Нефара.",h="Свічка Прикликання — зачарована ритуальна свічка, яку тримає відлюдний некромант Ґунтер Арканус на Озері...",kw={"свічка прикликання","ґунтер арканус","лілліт нефара","озеро світлої води","ритуал","некромант"},ang={["class:Mage"]="Уміння Ґунтера прив'язувати духів до ритуальних знарядь, як-от ця свічка, показує його майстерність у некромантії й мистецтві прикликання поза дозволеним ученням Кірін-Тору.",["race:Undead"]="Для посланців Відступників з Андерсіті робота з ритуальною свічкою Ґунтера — необхідний крок, щоб переконати затято незалежного некроманта, що ви не раби Короля-Ліча."},sec={{t="Випробування вірності",b="Свічка Прикликання, що зберігається в ящику біля самотнього мага Ґунтера Аркануса на його острові посеред Озера Світлої Води, — знаряддя темного обряду прикликання. Ґунтер — затято незалежний чаклун-нежить; Король-Ліч утратив над ним владу, бо Ґунтер сам розірвав пута, і тепер він однаково насторожено ставиться і до Погибелі, і до Відступників. Щоб довести, що ваша вірність належить не Королю-Лічу, Ґунтер велить віднести одну з цих свічок на південний захід, до меншого острівця. Там, на старому закривавленому столі, полум'я свічки проймає завісу між світами, щоб розбудити й прикликати сплячу тінь Лілліт Нефари — і дати їй нарешті спочити."}},faq={{q="Для чого потрібна Свічка Прикликання?",a="Свічкою викликають тінь Лілліт Нефари. Якщо поставити й запалити її на старому закривавленому обрядовому столі на меншому острівці на південний захід від табору Ґунтера Аркануса, дух, що дрімає, переходить у тілесний світ.",al={"що робить свічка прикликання","використання свічки прикликання","як використати свічку прикликання"}},{q="Де взяти Свічку Прикликання?",a="Свічку ви берете з ящика поруч із Ґунтером Арканусом на його острові в Озері Світлої Води на сході Галявин Тірісфалю, коли проходите його випробування на вірність.",al={"де знайти свічку прикликання","як отримати свічку прикликання","місце ящика зі свічками"}},{q="Кого викликає свічка?",a="Запалена свічка викликає Лілліт Нефару — мстиву примарну тінь, прив'язану до острівців озера. Здолати її потрібно, щоб довести, що ви не служите Погибелі.",al={"кого вона викликає","ціль виклику свічки","хто така ліліт нефара"}},{q="Звідки в Ґунтера Аркануса ці свічки?",a="Ґунтер використовує свічки й пов'язаний із ними обряд як випробування. Він не довіряє чужинцям і завзято обстоює свою незалежність від Погибелі, тож вимагає від кожного, хто шукає з ним союзу, зустрітися з неспокійними мерцями, яких він викликає, і знищити їх.",al={"чому в ґунтера свічки","ритуальні свічки ґунтера"}}},fp="19,244,20.642.0,41.240.0,41.179.0,30.169.0,44.236.0"}
P.entries["item:cantation-of-manifestation"] = {n="Заклинання Прояву",s="Заклинання Прояву — особливі магічні чари, записані на пергаментному сувої: маги використовують їх, щоб виявляти незримі магічні аномалії. В Андерсіті Анастасія Гартвелл дає цей сувій учням, які розслідують появу невидимих магічних істот у крамниці Алджернона в Апотекаріумі.",h="Заклинання Прояву — особливі магічні чари, записані на пергаментному сувої: маги використовують їх, щоб...",kw={"заклинання прояву","анастасія гартвелл","алджернон","магічний квартал","аномалії","маг","андерсіті"},ang={["class:Mage"]="Заклинання Прояву — важливе знаряддя вашого раннього навчання: воно вчить відчувати приховані магічні потоки й стримувати нестійких істот із розломів.",["race:Undead"]="Заклиначі-Відступники в Магічному Кварталі пильно стежать за магічними коливаннями, щоб розломи не підточили стабільності Андерсіті."},sec={{t="Явити невидиме",b="Заклинання Прояву містить зосереджені чари, що пронизують магічні завіси й змушують безтілесних, невидимих істот проявитися. Сувій зберігають у Магічному Кварталі Андерсіті, поряд з Анастасією Гартвелл, і довіряють його здібним магам, яким доручено приборкувати некеровані магічні аномалії. Якщо прочитати його вголос там, де магія нестійка, — як-от в алхімічній майстерні Алджернона в Апотекаріумі, — слова змушують приблудні породження розлому набути тіла. Тоді заклинач може їх здолати й замкнути у скриньки зберігання для подальшого вивчення."}},faq={{q="Що робить Заклинання Прояву?",a="Це магічний сувій із чарами, що виявляють невидимі магічні аномалії. Якщо прочитати його там, де стаються магічні розриви чи збурення, він змушує незримих істот — як-от породження розлому — показатися, щоб їх можна було здолати й упіймати.",al={"що таке заклинання прояву","призначення заклинання","як працює заклинання"}},{q="Де знайти Заклинання в Андерсіті?",a="Воно лежить на підлозі просто за наставницею магів Анастасією Гартвелл у Магічному Кварталі Андерсіті.",al={"місце заклинання в андерсіті","де заклинання прояву","знайти заклинання в андерсіті"}},{q="Навіщо Анастасії Гартвелл, щоб цей сувій прочитали?",a="В алхімічній крамниці Алджернона внизу, в Апотекаріумі, сталося дивне магічне збурення. Приміщеннями почали блукати незримі сутності, створені з чистої магії, і Гартвелл потрібно, щоб сувій прочитали на місці — виявили й упіймали цих істот, перш ніж розлом поглибиться.",al={"навіщо використовувати заклинання","мотив гартвелл","анастасія збурення"}},{q="Чи можна залишити собі сувій після використання?",a="Ні. Щойно ви змусите породження розлому проявитися й замкнете їх у скриньках зберігання, вам слід повернути Заклинання Прояву разом зі скриньками Анастасії Гартвелл.",al={"залишити заклинання","чи втрачу заклинання","повернути заклинання"}}},fp="26,298,23.573.0,44.249.0,44.121.0,50.268.0,43.184.0"}
P.entries["item:canvas-scraps"] = {n="Клапті Парусини",s="Клапті Парусини — рештки міцної тканої тканини, яку носять людські загарбники та племена кентаврів, що вдираються в Дуротар. У Гострому Пагорбі старий ветеран Фурл Скорнброу збирає ці врятовані клапті, щоб пошити корисні дорожні мішки для нових новобранців Орди.",h="Клапті Парусини — рештки міцної тканої тканини, яку носять людські загарбники та племена кентаврів, що...",kw={"парусина","клапті","скорнброу","гострий пагорб","кул тірас","кентаври","торба"},ang={["faction:Horde"]="Кожен клапоть, відібраний у загарбників Кул Тірасу чи нальотчиків Колкар, допомагає спорядити нових захисників, що відгукнулися на заклик Тралла по всьому Дуротару.",["profession:Tailoring"]="Хоч просту ткану парусину здебільшого збирають воїни як сиру здобич, вона слугує міцною основою для пошиття практичних торб у суворій пустелі."},sec={{t="Трофеї з ворогів Дуротару",b="Парусина — тканина не з грубих шкіряних традицій орків, зате її вдосталь у ворогів Дуротару. Морські піхотинці та моряки Кул Тірасу, що окопалися на східному узбережжі, носять важке парусинове спорядження та рештки вітрил зі своїх морських походів. Далі вглиб суходолу кочові кентаври Колкар пристосовують клапті грубої тканини, награбованої з караванів і в минулих сутичках. Перемога над цими ворогами дає міцні рештки, які можна зібрати з їхніх таборів і спорядження."},{t="Ремесло ветерана",b="Умостившись на сторожовій вежі Гострого Пагорба, ветеран Фурл Скорнброу виглядає загарбників і водночас береться за корисну роботу. Хоч бойові роки старого воїна позаду, він перешиває врятовану ворожу тканину на міцні торби для молодших солдатів. Повертаючи матеріали Кул Тірасу й Колкарів проти них самих, Фурл споряджає нове покоління захисників, що б'ються за кордони Орди."}},faq={{q="Звідки беруться Клапті Парусини?",a="Їх забирають у ворогів — людей і кентаврів — по всьому Дуротару. Ви можете здобути їх у вояків Кул Тірасу, що засіли у Фортеці Тіраґард і на східному березі, або в кентаврів Колкар — наймитів і гінців, що никають біля своїх таборів углибині краю.",al={"хто дропає клапті парусини","де взяти клапті парусини","фарм клаптів парусини"}},{q="Навіщо Фурлу Скорнброу ці клапті?",a="Фурл Скорнброу — старий ветеран-орк зі сторожової вежі на Гострому Пагорбі, що вже не може битися на передовій. Щоб і далі приносити користь Орді, він шиє з цієї тканини практичні дорожні торби для молодих шукачів пригод.",al={"кому потрібні клапті парусини","для чого клапті парусини","парусина фурла скорнброу"}},{q="Чому вояки Кул Тірасу й кентаври носять парусину?",a="Експедиція Кул Тірасу прибула в Дуротар на бойових кораблях і тримає табори на узбережжі, тож вітрильне полотно й парусина для них — звичайна щоденна річ. Кентаври Колкар здобувають схожі грубі тканини, грабуючи каравани, обшукуючи узбережжя й обдираючи мандрівників, що перетинають посушливі рівнини.",al={"чому кентаври мають парусину","історія клаптів парусини людей"}}},fp="13,252,29.493.0,17.413.0,33.234.0,42.235.0,53.294.0"}
P.entries["item:cask-of-merlot"] = {n="Барило Мерло",s="Барило Мерло — бочка доброго червоного вина, яке виготовляють і продають у Стормвінді. Це один із кількох особливих трунків, що знадобилися корчмареві Лейкширу, коли через вторгнення орків Блекрок почалися перебої з постачанням.",h="Барило Мерло — бочка доброго червоного вина, яке виготовляють і продають у Стормвінді.",kw={"барило мерло","вино","стормвінд","шинкар деніелс","лейкшир","роберто пупеллівербос"},ang={["faction:Alliance"]="Доставка барила підкреслює різкий контраст між безпечною розкішшю стормвіндського кварталу каналів і прикордонними містечками Редріджу, що потерпають від облоги."},sec={{t="Смак столиці",b="Вироблене в самому серці королівства, це Барило Мерло прибуває просто з погребів виноробні «Галліна», що тулиться вздовж каналів біля Торгового Кварталу Стормвінда. Винороб Роберто Пупеллівербос доглядає там за винами, догоджаючи вишуканішим смакам столиці. На відміну від різкого самогону із Сутінколісся чи простих трунків, які варять в Елвінні, мерло — витвір майстерності людських виноробів, що працюють у відносній безпеці за міськими мурами."},{t="Поповнення запасів Лейкширу",b="Коли клан Блекрок вторгся в Гори Редріджу, шляхи постачання розвалилися, і Лейкшир лишився без звичних купецьких поставок. Бачачи спраглих і наляканих земляків, Шинкар Деніелс доручає охочим гінцям обійти все королівство, щоб наповнити погреби його таверни. Завдяки цьому барилу захисники й біженці, що тримаються біля Озера Незрушного, матимуть чим м'яко запити свої пайки."}},faq={{q="Де знайти Барило Мерло?",a="Його продає Роберто Пупеллівербос у виноробні «Ґаліна». Крамниця стоїть над каналами на околиці Торгового Кварталу Стормвінда.",al={"місце барила мерло","де купити мерло","хто продає барило мерло","винний торговець стормвінда"}},{q="Навіщо Шинкареві Деніелсу це вино?",a="Навала орків Блекрок на Редрідж перерізала звичні торгові поставки до Лейкширу. Шинкар Деніелс майже без випивки, тож посилає шукачів пригод по всьому півдню Азероту по місцеві напої, щоб відвідувачі лишалися вдоволені.",al={"завдання сухі часи мерло","чому деніелс хоче вино","навіщо мерло лейкширу"}},{q="Які ще напої збирають разом із Мерло?",a="Деніелс просить також бурдюк Солодкого Рому з Ґолдшира, пляшку Самогону з Даркшира й барильце Лагеру Тандербрю від Ґрімбуза Тандербрю з пагорбів Вестфолу.",al={"інші напої сухих часів","список випивки деніелса","інший алкоголь сухих часів"}},{q="Чи загрожує щось виноробні «Ґаліна»?",a="Виноробня в безпеці за кам'яними мурами Стормвінда. Поки околиці на кшталт Вестфолу й Редріджу потерпають від бандитів і набігів орків, у столичному Кварталі Каналів торгівля й виноробство тривають без перешкод.",al={"виноробня ґаліна","виноробня в стормвінді"}}},fp="14,237,22.489.0,20.421.0,34.150.0,40.245.0,53.179.0,31.241.0"}
P.entries["item:cask-of-scalder"] = {n="Барило Скалдеру",s="Важке барило вогняного елю Скалдер Барліброу, яке дають відважним шукачам пригод, що вирушають до Стормвінда. Це водночас і подарунок, що втамує спрагу, і неофіційна валюта між давніми знайомими.",h="Важке барило вогняного елю Скалдер Барліброу, яке дають відважним шукачам пригод, що вирушають до Стормвінда.",kw={"барило скалдеру","скалдер барліброу","фурен лонґбірд","дворфійський квартал","ель","ретбанське випробування"},ang={["class:Warrior"]="Для воїна, що шукає надійного захисту, здобути легендарну майстерність Фурена Лонґбірда ціною барила доброго елю — важливий обряд посвяти.",["race:Dwarf"]="Ніщо так не скріплює угоду й не сплачує старий борг між дворфами, як свіже барило найкращого трунку Барліброу."},sec={{t="Дворфійська угода",b="Скалдер Барліброу — славетний ель, здатний зігріти навіть найзмерзлішого дворфа. Це барило довіряють мандрівникам, що довели свою відвагу в Ретбанському випробуванні, і посилають просто Фуренові Лонґбірду в Дворфійський Квартал Стормвінда. Лонґбірд, майстер щитів, вважає «сухі часи» нестерпними, тож цей міцний трунок — ідеальний спосіб нагадати йому про давню послугу й отримати першокласну дворфійську роботу."}},faq={{q="Що в Барилі Скалдеру?",a="Барило повне Скалдеру Барліброю — міцного, вогненного напою, який варить родина Барліброю. Дворфи цінують його за насичений смак і зігрівальний удар.",al={"який це напій","ель скалдер","скалдер барліброй"}},{q="Для кого це барило?",a="Барило призначене Фурену Лонґбірду — вправному дворфові-щитникові, що працює в Дворфійському Кварталі Стормвінда.",al={"кому барило","куди це нести","одержувач скалдера"}},{q="Чому це барило везуть Фурену Лонґбірду?",a="Фурен завинив послугу Йорусу Барліброу. Цінне барило втамує Фуренову спрагу в те, що він називає «сухими часами», і переконає його викувати для кур'єра міцний, винятковий щит.",al={"чому фурен хоче скалдер","послуга щитовика","призначення барила"}}},fp="15,190,17.434.0,35.166.0,30.130.0,52.200.0"}
P.entries["item:cask-of-shimmer-stout"] = {n="Барило Мерехтливого Стауту",s="Барило Мерехтливого Стауту — запечатана діжка міцного нового елю Реджолда Барліброю, звареного на холодних висотах Дун Мороґу. Відомий своїм неабияким ударом і запаморочливою силою, він вирушає на схід через гори як бадьорий гостинець для дворфійських горян.",h="Барило Мерехтливого Стауту — запечатана діжка міцного нового елю Реджолда Барліброю, звареного на холодних...",kw={"мерехтливий стаут","барило","реджолд барліброю","горянин кадрелл","телсамар","лох модан","харанос"},ang={["race:Dwarf"]="Для дворфів поділитися добрим елем між обходами — шанована традиція, що єднає розкиданих горян по суворих вершинах Каз Модану."},sec={{t="Бадьора доставка",b="Зварений у Хараносі Реджолдом Барліброю Мерехтливий Стаут швидко здобув високу оцінку в місцевих відвідувачів і горян, що зносили пронизливі морози Дун Мороґу. Вражений варивом брата, Горянин Барліброу замовив діжку, щоб переправити її східним перевалом до Лох Модану. Дворфи високо цінують міцний трунок і як основу товариства, і як практичний захист від пронизливого гірського холоду, а поділитися свіжим урожаєм із далекими побратимами — давня військова традиція."},{t="Дворфійський підбадьорювач",b="Коли Горянин Кадрелл на своїй варті в Телсамарі відкриває діжку й куштує напій, той цілком виправдовує свою славу. Це не звичайне корчемне пиво: кажуть, один ковток Мерехтливого Стауту робить ноги легкими й лишає воїна з відчуттям, ніби він от-от злетить, — саме таке підбадьорливе зілля потрібне дворфійському розвіднику на довгих самотніх обходах високих доріг."}},faq={{q="Що таке Мерехтливий Стаут?",a="Мерехтливий Стаут — міцний дворфський ель, який зварив Реджолд Барліброю в Дун Мороґу. Його високо цінують за потужний удар: він бадьорить тіло й не підпускає холоду.",al={"що таке мерехтливий стаут","історія мерехтливого стауту","хто зварив мерехтливий стаут"}},{q="Кому відправляють барило?",a="Барило відправляють Горянинові Кадреллу — вартовому при дорозі, що проходить через поселення Телсамар у Лох Модані.",al={"кому барило","куди барило","одержувач барила"}},{q="Навіщо відправляти ель через гори?",a="Дворфи-горяни часто діляться добрими напоями з товаришами на далеких дозорах. Скуштувавши вдалий витвір Реджолда, його брат захотів пригостити Кадрелла новим найкращим рецептом Дун Мороґа.",al={"навіщо доставка","навіщо возити пиво","навіщо слати кадреллу"}},{q="Як Мерехтливий Стаут діє на того, хто його п'є?",a="Ель напрочуд міцний. Скуштувавши його, Горянин Кадрелл вигукує, що в нього паморочиться голова, тіло стає легким, а сам він почувається так, ніби може літати.",al={"наскільки міцний мерехтливий стаут","дія мерехтливого стауту"}}},fp="21,274,19.512.0,20.395.0,22.190.0,30.138.0,34.223.0,51.169.0"}
P.entries["item:cats-eye-emerald"] = {n="Смарагд Котяче Око",s="Смарагд Котяче Око — надзвичайно великий, завбільшки з кулак самоцвіт, знайдений у Шахті Кам'яної Жили на півночі Пусток. Його величезна ринкова вартість швидко зробила його предметом інтриг поза лавами Венчурної Компанії.",h="Смарагд Котяче Око — надзвичайно великий, завбільшки з кулак самоцвіт, знайдений у Шахті Кам'яної Жили на...",kw={"смарагд котяче око","шахта кам'яної жили","венчурна компанія","діззівіг","бос копперплаґ","самоцвіт"},ang={["class:Rogue"]="Викрасти величезний, погано охоронюваний самоцвіт просто з-під носа продажних наглядачів Венчурної Компанії — хрестоматійний приклад пройдисвітства.",["profession:Mining"]="Знахідка бездоганного самоцвіту завбільшки з кулак у звичайних брудних промислових розкопках на кшталт Шахти Кам'яної Жили — найщасливіша удача, про яку мріє кожен гірник."},sec={{t="Статок завбільшки з кулак",b="Коли робітники, що розробляли Шахту Кам'яної Жили Венчурної Компанії на північний схід від Багнистого Болота, натрапили на величезний смарагд, чутка швидко рознеслася саваною. Такі рідкісні, високоякісні самоцвіти недовго лишаються таємницею на землях, де верховодять гобліни. Начальник Пристані Діззівіг у Раджеті почув про знахідку з невпинних торгових пліток, що ходять між його пристанями й Буті Бей, і одразу задумав здобути скарб для відкритого ринку в Андермайні."},{t="Власність компанії",b="Замість потрапити до звичайних торгових каналів законним шляхом, самоцвіт тримали під посиленою охороною керівники Венчурної Компанії в самій шахті. Наглядачі, вибивайли й головні управителі на кшталт Боса Копперплаґа пильно стерегли свій цінний скарб і від картелів-суперників, і від заповзятливих шукачів скарбів, що прагнули отримати обіцяну Діззівігом половину прибутку."}},faq={{q="Що таке Смарагд Котяче Око?",a="Це надзвичайно великий смарагд, завбільшки з кулак, знайдений під час розкопок на півночі Пусток. Через свою чистоту й розмір він коштує цілий статок на світовому ринку.",al={"що таке смарагд котяче око","самоцвіт котяче око","що це за самоцвіт"}},{q="Де знайшли цей самоцвіт?",a="Його викопали шахтарі Венчурної Компанії в Шахті Кам'яної Жили, що трохи на північний схід від Багнистого Болота на півночі Пусток.",al={"де його знайшли","місце самоцвіту","смарагд шахти валунів"}},{q="Кому в Раджеті потрібен смарагд?",a="Начальник Пристані Діззівіг, гоблін, що відає перевезеннями й вантажами в доках Раджета, шукає камінь, щоб продати його заможним покупцям через торгові зв'язки в Андермайні.",al={"хто купує смарагд","смарагд діззівіґа","хто дає завдання на смарагд"}},{q="У кого камінь у шахті?",a="Смарагд тримають старші наглядачі Венчурної Компанії в Шахті Кам'яної Жили — його можуть мати доглядачі, вишибали або сам Бос Копперплаґ.",al={"хто дропає смарагд","у кого смарагд котяче око","де знайти смарагд котяче око"}}},fp="16,248,20.470.0,18.366.0,29.187.0,29.141.0,33.161.0,41.140.0"}
P.entries["item:cenarion-lunardust"] = {n="Кенарійський Місячний Пил",s="Кенарійський Місячний Пил — священний порошок, який Турак Рунтотем на висотах Тандер Блафа вручає юним друїдам-тауренам. Ним пробуджують звіра-охоронця Лунакло біля давнього Каменя Місячника на межі Малгору й Пусток.",h="Кенарійський Місячний Пил — священний порошок, який Турак Рунтотем на висотах Тандер Блафа вручає юним...",kw={"кенарійський місячний пил","турак рунтотем","лунакло","камінь місячника","друїд","форма ведмедя","коло кенарія"},ang={["class:Druid"]="Для друїдів-тауренів цей пил — головний каталізатор священного обряду посвяти, що відкриває прадавнє мистецтво перевтілення на ведмедя.",["race:Tauren"]="Цей пил безпосередньо поєднує юних шу'гало з ученням Кола Кенарія й засвідчує їхнє дедалі глибше єднання з природою та дикими духами Калімдору."},sec={{t="Обряд тіла й серця",b="Кенарійський Місячний Пил, який довіряють учням, готовим посісти своє місце серед Друїдів Пазура, несе благословення Кола Кенарія. Коли сяйливий пил розсипають на Камені Місячника на захід від Табору Тауражо, він прикликає Лунакло — священного звіра, покликаного випробувати учня. Перемога над цим вартовим перевіряє і тілесну міць, і духовну стійкість, дозволяючи юному друїдові ввібрати силу тіла й серця, без якої не прийняти форми ведмедя."}},faq={{q="Для чого потрібен Кенарійський Місячний Пил?",a="Ним посипають Камінь Місячників на пагорбах між Малгором і Пустками, трохи на захід від Табору Тауражо. Пил викликає Лунакло — могутнього звіра, якого новачки мусять здолати, щоб довести свою силу.",al={"що робить місячний пил","як використати кенарійський місячний пил","призначення місячного пилу"}},{q="Хто дає Кенарійський Місячний Пил?",a="Турак Рунтотем, наставник друїдів на Узвишші Старійшин у Тандер Блафі, дає пил друїдам-тауренам, які проходять випробування ведмежої подоби.",al={"хто дає місячний пил","де взяти кенарійський місячний пил","пил турака рунетотема"}},{q="Що буде, якщо загубити Кенарійський Місячний Пил?",a="Якщо ви загубите пил або програєте бій із Лунакло, доведеться повернутися до Турака Рунтотема на Узвишші Старійшин у Тандер Блафі по новий мішечок.",al={"загублений місячний пил","потрібно більше місячного пилу","де взяти ще місячного пилу"}},{q="Чому друїд мусить зійтися з Лунакло?",a="Лунакло — охоронець каменя, що втілює рівновагу тілесної сили й внутрішньої стійкості. Кинувши виклик цій істоті й здолавши її, майбутній Друїд Пазура засвоює науку тіла й серця, потрібну, щоб опанувати силу Великого Духу Ведмедя.",al={"чому битися з лунакло","хто такий лунакло","призначення лунакло"}}},fp="18,242,24.474.0,36.224.0,36.145.0,49.152.0,31.267.0"}
P.entries["item:cenarion-moondust"] = {n="Кенарійський Місячний Пил",s="Кенарійський Місячний Пил — священний порошок, який довіряють друїдам нічних ельфів, що проходять випробування, аби стати друїдами Пазура. Якщо розсипати його на прадавньому Камені Місячника на пагорбах на схід від Обердайна, він викликає Лунакло — лютого звіра-охоронця печери.",h="Кенарійський Місячний Пил — священний порошок, який довіряють друїдам нічних ельфів, що проходять...",kw={"кенарійський місячний пил","лунакло","камінь місячника","друїд пазура","форма ведмедя","темне узбережжя","матренґіл берволкер"},ang={["class:Druid"]="Для друїдів нічних ельфів Кенарійський Місячний Пил — завершальний крок на шляху до звання друїда Пазура, і веде він просто до опанування форми ведмедя.",["race:NightElf"]="Пил утілює давні традиції Кола Кенарія, що поєднують шанування природи з місячними обрядами на честь звірів Темного Узбережжя."},sec={{t="Обряд Пазура",b="Кенарійський Місячний Пил вручає Матренґіл Берволкер у Дарнасусі, і для молодого друїда він стає ключем до останнього випробування серця й тіла. Щоб зустрітися з охоронцем Лунакло й довести йому свою силу, посвячуваний має вирушити до лігв місячників на схід від Обердайна, на Темному Узбережжі. Пил, нанесений на прадавній Камінь Місячника, кличе звіра, і той випробовує новачка в бою — так друїд опановує незламну силу, без якої не прийняти форму ведмедя."}},faq={{q="Для чого потрібен Кенарійський Місячний Пил?",a="Ним користуються новачки-друїди з нічних ельфів біля Каменю Місячників на Темному Узбережжі, щоб пробудити Лунакло. Це випробування їхньої сили й рішучості, після якого вони здобувають ведмежу подобу.",al={"використання місячного пилу","що робить кенарійський місячний пил","призначення кенарійського місячного пилу"}},{q="Де використати Кенарійський Місячний Пил?",a="Його треба розсипати над Каменем Місячників у печері місячників серед пагорбів просто на схід від Обердайна на Темному Узбережжі.",al={"де використати місячний пил","місце каменю лунакло","де камінь лунакло"}},{q="Хто дає Кенарійський Місячний Пил?",a="Матренґіл Берволкер, наставник друїдів у Ценаріонському Анклаві в Дарнасусі, дає його новачкам, які довели, що готові до випробування тіла й серця.",al={"хто дає місячний пил","де взяти кенарійський місячний пил","місячний пил матренгіла"}},{q="Що буде, якщо загубити місячний пил?",a="Якщо пил загублено чи витрачено на невдалу спробу здолати Лунакло, новачкам доведеться повернутися до Дарнасуса й знову просити Матренґіла Берволкера про випробування.",al={"загублений кенарійський місячний пил","загублений місячний пил","повернути місячний пил"}}},fp="17,255,18.479.0,35.170.0,37.127.0,31.174.0,36.178.0"}
P.entries["item:centaur-bracers"] = {n="Наручі Кентавра",s="Наручі кентавра — прості шкіряно-залізні наручі, які знімають з убитих кентаврів-колкарів по всіх Пустках. Реґтар Дезґейт збирає їх на захід від Перехрестя як доказ знищених кентаврів-нападників.",h="Наручі кентавра — прості шкіряно-залізні наручі, які знімають з убитих кентаврів-колкарів по всіх Пустках.",kw={"наручі кентавра","колкари","кентаври","реґтар дезґейт","перехрестя","пустки"},ang={["faction:Horde"]="Знищення нападників-колкарів безпосередньо допомагає поширенню Орди, оберігаючи тендітні караванні шляхи постачання між Дуротаром, Малгором і Перехрестям.",["race:Tauren"]="Поколіннями кочові таурени терпіли жорстокі напади кланів кентаврів; вигнання колкарів із Пусток — довгоочікувана відплата й безпека."},sec={{t="Сувора винагорода",b="Плем'я колкарів становить невпинну загрозу для опори Орди на посушливих рівнинах Пусток. Наручі, зняті з полеглих воїнів-кентаврів, — незаперечний доказ того, що з торгових шляхів прибрано ще одного ворожого грабіжника. Реґтар Дезґейт, орк-розвідник, що стоїть на кручах на захід від Перехрестя, оголосив постійну винагороду за ці трофеї, щоб приборкати агресію племені."}},faq={{q="Кому потрібні ці наручі?",a="Реґтар Дезґейт, розвідник Орди, що отаборився на узвишші на захід від Перехрестя в Пустках, приймає їх як доказ вашої боротьби з місцевими кентаврами Колкар.",al={"хто бере наручі кентавра","здати реґтару деткейту","хто купує наручі кентавра"}},{q="Які кентаври носять ці наручі?",a="Наручі носять воїни Колкар, що кочують оазами й таборами на півночі Пусток, — як-от біля Забутих ставків і Оази Буйних Вод.",al={"де фармити наручі","наручі колкарів","джерело наручів кентавра"}},{q="Навіщо Реґтарові ці наручі?",a="Реґтар прагне рішуче скоротити кількість Колкар, щоб захистити землі Орди. Трофеї на кшталт наручів доводять, що воїни справді знищують розбійників, а не просто проганяють їх.",al={"навіщо збирати наручі","мотив реґтара деткейта","призначення наручів кентавра"}}},fp="15,199,15.413.0,24.160.0,34.151.0,37.207.0"}
P.entries["item:charred-horn"] = {n="Обвуглений Ріг",s="Обвуглені Роги — грубі, випалені жаром роги молодих химер, що живуть серед скель Гір Кам'яного Кігтя. Вони такі міцні, що витримують люті стихійні сили, тож слугують незамінним складником для гартування в особливому бронярстві.",h="Обвуглені Роги — грубі, випалені жаром роги молодих химер, що живуть серед скель Гір Кам'яного Кігтя.",kw={"обвуглений ріг","химери","гори кам'яного кігтя","фурен лонґбірд","кольчуга","калімдор"},ang={["class:Warrior"]="Фурен Лонґбірд залучає саме воїнів-початківців, щоб ті здобули ці роги в Калімдорі, і винагороджує їхню небезпечну мандрівку кольчугою, загартованою вогнем і викуваною на замовлення.",["profession:Blacksmithing"]="Ці роги показують екзотичну ковальську техніку: природно загартований вогнем матеріал хижаків Калімдору використовують, щоб гартувати кільця кольчуги."},sec={{t="Рідкісний ковальський складник",b="Обвуглені Роги, які здобувають у пташенят і молодих химер, що гніздяться на скелястих висотах Гір Кам'яного Кігтя, цінують за неприродну стійкість до вогню й ударів. Дворфійський броняр Фурен Лонґбірд, що працює біля своєї кузні в Стормвінді, потребує цих рогів, щоб викувати загартовану вогнем кольчугу. Разом з отруйними павучими іклами з Багнокраю, флогістоном із Рейзорфен Краулу й гальванованим рогом матріарха химер ці скам'янілі роги дають основне підсилення, потрібне для надзвичайно міцного захисного обладунку."}},faq={{q="З яких істот падають Обвуглені Роги?",a="Їх збирають із химеренят і молодих химер, що водяться на суворих кручах Гір Кам'яного Кігтя в Калімдорі.",al={"де взяти обвуглений ріг","хто дропає обвуглений ріг","джерело обвугленого рогу"}},{q="Кому в Стормвінді потрібні ці роги?",a="Їх просить майстер-зброяр Фурен Лонґбірд. Загартовані вогнем роги слугують йому сировиною, щоб викувати надзвичайно міцний кольчужний нагрудник для перспективних воїнів.",al={"кому потрібен обвуглений ріг","здати обвуглений ріг","роги для фурена лонґбірда"}},{q="Навіщо Фурену стільки рогів?",a="Фуренові потрібно дванадцять Обвуглених Рогів, щоб мати досить загартованого жаром матеріалу й як слід укріпити кільця та пластини своєї загартованої вогнем кольчуги.",al={"чому 12 обвуглених рогів","призначення обвугленого рогу"}},{q="Чи відрізняються вони від Гальванованого Рогу?",a="Так. Обвуглені Роги добувають у великій кількості з менших, молодших химер Кам'яного Кігтя, тоді як Гальванований Ріг — єдиний і куди рідкісніший трофей, який знімають просто з Матріарха Химер.",al={"гальванований ріг чи обвуглений","різниця між рогами"}}},fp="12,258,25.607.0,34.132.0,35.177.0,39.149.0,45.185.0"}
P.entries["item:chest-of-containment-coffers"] = {n="Скриня зі Скриньками Зберігання",s="Скриня зі Скриньками Зберігання містить зачаровані вмістилища, якими маги ловлять нестійкі магічні явища. Це необхідне спорядження для тих, кого посилають розслідувати й безпечно впіймати незримі аномалії мани.",h="Скриня зі Скриньками Зберігання містить зачаровані вмістилища, якими маги ловлять нестійкі магічні явища.",kw={"скриня зі скриньками зберігання","скриньки зберігання","аномалії","анастасія гартвелл","дженнея кеннон","алджернон","маг"},ang={["class:Mage"]="У скрині — польове спорядження для магів, які вчаться приборкувати нестійкі магічні прояви й зберігати живі зразки для вивчення.",["race:Undead"]="Маги-Відступники ловлять у ці скриньки магічні аномалії біля Апотекаріуму, щоб неперевірені магічні сили не зіпсували їхньої роботи."},sec={{t="Посудини для незримого",b="Магічні досліди й раптові розломи між світами часто породжують нестійкі, невидимі аномалії, що складаються з чистої магічної сили. Звичайні клітки не втримають істот, створених лише з магії. Скриня зі Скриньками Зберігання дає магам особливі зачаровані скриньки, зроблені, щоб упіймати й скувати цих приборканих істот живими. Скриню тримають біля старших наставників — Анастасії Гартвелл в Андерсіті та Дженнеї Кеннон у Стормвінді, — і вона дає необхідне спорядження новачкам, яким доручено обстежити аномалії, перш ніж ті розхитають усе довкола."},{t="Правила магічного утримання",b="Коли в крамниці Алджернона в Апотекаріумі з'явилися невидимі збурення, наставники-Відступники послали магів із цими скриньками, щоб приборкати лихо. Щоб упіймати істоту з розлому, її треба виявити особливим сувоєм, послабити чарами й замкнути в одній зі скриньок із цієї скрині. Наповнені вмістилища дають дослідникам-Відступникам змогу безпечно розібрати й вивчити бранців і визначити, чи ці збурення — випадкові розриви в лей-лініях, чи навмисні магічні напади."}},faq={{q="Що в Скрині зі Скриньками Зберігання?",a="У скрині — особливі порожні скриньки зберігання. Маги беруть ці посудини, щоб надійно замкнути впокорених магічних істот, як-от породження розлому, під час небезпечних польових досліджень.",al={"що дає скриня","вміст скриньок зберігання","вміст скрині"}},{q="Де знайти цю скриню?",a="В Андерсіті вона стоїть просто за Наставницею Магів Анастасією Гартвелл у Магічному Кварталі. Таку саму скриню можна знайти й у Стормвінді — за Дженнеєю Кеннон у Святилищі Чародія.",al={"місце скрині зі скриньками зберігання","де скриня зі скриньками","місце скриньки"}},{q="Чому магам потрібні ці скриньки, а не звичайні клітки?",a="Досліджувані істоти — породження розлому, створені з чистої безтілесної магічної енергії. Звичайні матеріали їх не втримають: лише зачаровані скриньки зберігання можуть замкнути й угамувати магічну аномалію.",al={"навіщо скриньки","для чого скриньки","як працюють скриньки"}},{q="Що стається зі скриньками, коли їх наповнено?",a="Повні скриньки передають старшим наставникам для вивчення. Упійманих істот досліджують, щоб з'ясувати, чи було магічне збурення випадковим природним розломом, чи навмисним нападом сторонніх сил.",al={"що буде із захопленими розривними істотами","використання наповненої скриньки","навіщо ловити істот"}}},fp="28,226,22.578.0,28.527.1,48.185.0,30.194.0,56.222.0,49.216.0"}
P.entries["item:chief-sharptusk-thornmantle-s-head"] = {n="Голова Вождя Гостроікла Терномантія",s="Голову Вождя Гостроікла Терномантія беруть як похмурий доказ перемоги над ватажком шипогривів Щетиноспинних, що загрожують Плато Червоної Хмари. Здобуту з глибин Яру Тернистого Клинка, її подають Сміливцю Віндфезеру на знак того, що невідчепній загрозі для молодих сміливців-тауренів покладено край.",h="Голову Вождя Гостроікла Терномантія беруть як похмурий доказ перемоги над ватажком шипогривів Щетиноспинних...",kw={"гостроікл терномантій","голова","вождь","щетиноспинні","шипогриви","сміливець віндфезер","яр тернистого клинка"},ang={["class:Hunter"]="Для мисливців Гостроікл — найвища здобич: розумний ворог, здатний полювати у відповідь, що перетворює сутичку за виживання на справжнє випробування вистежування й влучності.",["race:Tauren"]="Здобута голова грізного ворога — важлива віха для молодих тауренів: вона доводить, що вони мають рішучість і вміння захистити новий дім свого народу."},sec={{t="Трофей полювання",b="Таурени виборюють свою мирну батьківщину в Малгорі пильністю й силою. Шипогриви Щетиноспинні, що закріпилися в Яру Тернистого Клинка, ведуть агресивний похід проти племен, яким дає прихисток Табір Нарачі, підбурювані своїм лютим вождем Гостроіклом Терномантієм. Відтяти йому голову — не безглузда жорстокість, а остаточний доказ його загибелі й суворе попередження вцілілим кланам шипогривів, що зазіхають на межі плато."},{t="Урок полювання",b="Сміливець Віндфезер вимагає голову вождя як обряд посвяти для мисливців-початківців і захисників племені. Для тауренів зіткнення з ворогом, досить хитрим, щоб відповідати ударом на удар і зібрати цілу бойову ватагу, — важлива перевірка бойової вправності. Подана голова Гостроікла виконує це випробування й здобуває молодому бійцеві міцну репутацію серед сміливців Плато Червоної Хмари."}},faq={{q="Навіщо Сміливцеві Віндфезеру голова Шарптаска Торнмантла?",a="Сміливцеві Віндфезеру потрібен незаперечний доказ, що ватажок шипогривів Щетиноспинних загинув. Принесена голова свідчить, що Шарптаск більше не водитиме набігів на Табір Нарачі, і показує решті шипогривів, що на їхню зухвалість відповідатимуть рішучою силою.",al={"навіщо брати його голову","причина голови гостроікла","прохання віндфезера про голову"}},{q="Хто такий Вождь Шарптаск Торнмантл?",a="Вождь Шарптаск Торнмантл очолював шипогривів Щетиноспинних, що живуть у Яру Тернистого Клинка на східному краю Плато Червоної Хмари. Під його проводом Щетиноспинні раз у раз нападали на молодих сміливців-тауренів.",al={"хто такий гостроікл","історія гостроікла терномантія","вождь квілборгів малгор"}},{q="Де здобути цей трофей?",a="Голову здобувають, убивши Вождя Шарптаска Торнмантла в його нашвидкуруч зведеному селищі глибоко в Яру Тернистого Клинка, на схід від Табору Нарачі.",al={"де знайти голову","місце голови гостроікла"}}},fp="34,295,18.458.0,20.398.0,66.288.0,36.232.0,30.161.0"}
P.entries["item:chok-sul-s-head"] = {n="Голова Чоксула",s="Голова Чок'сула — моторошний речовий доказ смерті ватажка огрів Мо'ґрош. Принесена Магістратові Блантноузу в Телсамар, вона дає право на винагороду, яку оголосила місцева дворфійська влада.",h="Голова Чок'сула — моторошний речовий доказ смерті ватажка огрів Мо'ґрош.",kw={"голова чок'сула","огри","мо'ґрош","телсамар","блантноуз","винагорода","лох модан"},ang={["race:Dwarf"]="Загибель Чок'сула прямо послаблює тиск на сільські поселення Айронфорджа й захищає від огрячого нищення такі важливі для громади споруди, як Каменетесна Гребля."},sec={{t="Доказ загибелі ватажка",b="Огри з Твердині Мо'ґрошів — постійна загроза для поселень Лох Модану: вони нападають на Телсамар, на розкопки й на життєво важливу Каменетесну Греблю. Магістрат Блантноуз оголосив винагороду за голову звірюки, яку вважають організатором цих нападів, — Чок'сула. Зважаючи на хаос у північно-східних пагорбах, магістрат вимагає незаперечного доказу, перш ніж видати кошти з міської скарбниці. Відтята голова огрячого ватажка дає дворфійській раді ту моторошну певність, якої вона потребує, щоб визнати угоду виконаною."}},faq={{q="Хто такий Чок'сул?",a="Чок'сул — ватажок огрів, що засів у Твердині Мо'ґрошів на північному сході Лох Модану. Дворфські урядовці вважають, що саме він стояв за злагодженими набігами на Телсамар, Каменетесну Греблю та довколишні розкопки.",al={"хто такий чок'сул","історія чок'сула","особа чок'сула"}},{q="Навіщо Магістратові Блантноузу ця голова?",a="Магістрат Блантноуз оголосив нагороду за смерть Чок'сула — у будь-який спосіб. Набіги огрів тяжко виснажили край, тож магістрат вимагає незаперечного доказу смерті ватажка, перш ніж виплатити гроші зі скарбниці Телсамару.",al={"навіщо блантноузу голова","призначення голови чок'сула","хто хоче голову чок'сула"}},{q="Де орудував Чок'сул?",a="Чок'сул керував своєю ватагою з Твердині Мо'ґрошів — добре укріпленого лігва огрів серед скелястих пагорбів на північному сході Лох Модану.",al={"де чок'сул","місце твердині мо'грош","місце чок'сула"}},{q="Чим Чок'сул загрожував краю?",a="Вважали, що він спрямовує зухвалі напади на Телсамар і довколишні дворфські споруди — зокрема на Каменетесну Греблю й місцеві археологічні розкопки.",al={"чому чок'сула розшукують","що накоїв чок'сул"}}},fp="15,204,29.539.0,17.240.0,44.284.0,27.149.0,45.174.0"}
P.entries["item:clarice-s-pendant"] = {n="Амулет Кларіс",kw={"амулет кларіс","кларіс фостер","юрів","гробниця","відступники","світло"},ang={["class:Paladin"]="Зневага Кларіс до хрестового походу Юріва — незручне нагадування про особисту ціну й зруйновані домівки, які лишає по собі священний запал.",["race:Undead"]="Амулет показує трагедію й гіркоту, спільні для багатьох Відступників: їхні живі рідні часто кидали їх заради походів, які зрештою нікого не вберегли."},sec={{t="Гіркий подарунок",b="Амулет Кларіс уособлює розбите людське минуле, спільне для багатьох Відступників. Ще до того як Третя війна поглинула Лордерон, чоловік Кларіс, Юрів, покинув її з дітьми, щоб піти воювати з нежиттю, проголосивши, що відданість Святому Світлу понад усе. Та замість урятувати домівку, Юрів загинув, а його родина зрештою стала жертвою тієї самої Погибелі, з якою він пішов боротися. Для Кларіс амулет — не дорога серцю пам'ятка, а образлива дрібничка, символ цілого життя на другому місці після фанатизму й обов'язку."},{t="На гробниці Юріва",b="Прагнучи розірвати останні почуттєві зв'язки з колишнім життям і невірним чоловіком, Кларіс посилає шукача пригод повернути прикрасу просто на могилу Юріва в Гробниці. Гробниця занедбана й осквернена, похована під бур'яном і сміттям. Коли амулет нарешті кладуть на вирізьблені руки на віку труни, його самоцвіт помітно тьмяніє, гасячи останнє тепло колишнього життя Кларіс."}},faq={{q="Кому належить Амулет Кларіс?",a="The pendant belongs to Clarice Foster, a Forsaken woman residing in the Pools of Vision in Thunder Bluff. It was given to her in life by her husband, Yuriv, before he marched off to war.",al={"чий амулет","чия це підвіска","кларіс фостер"}},{q="Хто такий Юрів?",a="Юрів був чоловіком Кларіс за життя. Він покинув її з дітьми, щоб боротися з дедалі більшою загрозою нежиті в ім'я Святого Світла, — і загинув, а поховали його в занедбаній могилі біля Гробниці.",al={"чоловік кларіс","хто такий юрів","могила юріва"}},{q="Чому Кларіс хоче позбутися амулета?",a="Кларіс не може пробачити Юрівові, що свій хрестовий похід і відданість Світлу він поставив вище за неї та дітей. Його жертва нічого не дала: він однаково загинув, а вона, покинута, зрештою сама стала нежиттю — саме тим, що він прагнув викорінити.",al={"чому викинути амулет","чому кларіс ненавидить юріва","завдання амулета кларіс"}},{q="Що стається, коли амулет кладуть на могилу Юріва?",a="Returning the pendant to Yuriv's grave fulfills Clarice's wish to part with the keepsake and the painful attachment it represents.",al={"що буде на могилі юріва","амулет на могилі"}}},fp="17,277,14.572.0,25.437.1,27.186.0,14.213.0,48.259.0,57.130.1"}
P.entries["item:claw-key"] = {n="Кігтистий Ключ",s="Кігтистий Ключ — один із трьох друїдських ключів, захованих у Лігві Кігтя на Піку Кам'яного Кігтя. Разом із Ключем від Притулку й Ключем Сплячих він потрібен, щоб відімкнути зачароване Сховище Лігва Кігтя.",h="Кігтистий Ключ — один із трьох друїдських ключів, захованих у Лігві Кігтя на Піку Кам'яного Кігтя.",kw={"кігтистий ключ","лігво кігтя","пік кам'яного кігтя","друїди","ключ від притулку","ключ сплячих"},ang={["class:Druid"]="Названий на честь славетних Друїдів Кігтя, цей ключ відбиває священні традиції й захисні чари, створені нічними ельфами, що жили в притулках.",["faction:Horde"]="Допитуючи полонених нічних ельфів, Орда може обійти давній захист друїдів і пограбувати священні артефакти, що зберігаються на Піку Кам'яного Кігтя."},sec={{t="Захисні чари Лігва Кігтя",b="Друїди нічних ельфів заснували Лігво Кігтя високо на Піку Кам'яного Кігтя як святилище й сховище могутніх реліквій. Щоб ці скарби були в безпеці від чужинців, вони сховали їх за багатошаровою охоронною системою. Саме сховище запечатане трьома окремими зачарованими замками: Ключем від Притулку, Ключем Сплячих і Кігтистим Ключем. Кожен ключ захований в особливій друїдській схованці, схожій на смолоскип, серед звивистих тунелів притулку."},{t="Зламати схованки",b="Друїди не лишили ключі без охорони чи у вільному доступі. Щоб відкрити схованку з Кігтистим Ключем, спершу треба здобути Ключ Воротаря, захований біля входу до притулку. Здобутий Кігтистий Ключ стає важливою частиною того, щоб зламати друїдську печатку й заволодіти багатствами, схованими глибоко в горі."}},faq={{q="Для чого потрібен Кігтистий Ключ?",a="Кігтистий Ключ — один із трьох ключів, потрібних, щоб відімкнути Скарб Лігва Кігтя, захищену чарами кам'яну скриню в серці Лігва Кігтя на Піку Кам'яного Кігтя.",al={"призначення кігтистого ключа","що відчиняє кігтистий ключ","ключ до скарбниці лігва кігтя"}},{q="Де знайти Кігтистий Ключ?",a="Він схований у друїдській схованці, замаскованій під смолоскип, у тунелях Лігва Кігтя на Піку Кам'яного Кігтя. Щоб відчинити схованку, потрібен Ключ Воротаря з входу до лігва.",al={"місце кігтистого ключа","де кігтистий ключ","знайти кігтистий ключ"}},{q="Які ще ключі потрібні, крім Кігтистого Ключа?",a="Щоб відімкнути Скарб Лігва Кігтя, вам треба зібрати Кігтистий Ключ, Ключ від Притулку й Ключ Сплячих — усі вони лежать в окремих схованках по всьому лігву.",al={"інші ключі","ключі лігва кігтя","ключі до лігва"}},{q="Чому друїди сховали ці ключі?",a="Друїди нічних ельфів збудували Лігво Кігтя, щоб зберігати могутні реліквії подалі від цікавих очей, і вигадали складну систему ключів і прихованих схованок, щоб відлякувати непроханих гостей.",al={"чому ключі сховані","історія лігва кігтя"}}},fp="8,191,22.466.0,20.344.0,30.150.0,32.175.0,50.149.0,35.166.0"}
P.entries["item:cliffspring-river-sample"] = {n="Проба з Річки Кліффспрінг",s="Скляна пробірка з каламутною, смердючою водою, набраною біля підніжжя водоспаду на Річці Скельного Джерела на Темному Узбережжі. Зібрана на прохання Тундріса Віндвівера з Обердайна, проба — відчутний доказ порчі, що підступає до прибережного поселення.",h="Скляна пробірка з каламутною, смердючою водою, набраною біля підніжжя водоспаду на Річці Скельного Джерела на...",kw={"річка скельного джерела","тундріс віндвівер","обердайн","сквернолісся","темне узбережжя","порча"},ang={["class:Druid"]="Друїди тонко відчувають рівновагу природних водойм, тож протиприродна отруйність проби з Річки Скельного Джерела вимагає негайно її вивчити й очистити.",["race:NightElf"]="Для нічних ельфів Обердайна будь-яка порча вод північного Калімдору — грізна прикмета пошесті, що й далі шириться зі Сквернолісся."},sec={{t="Отруєна течія",b="Річка Скельного Джерела збігає зі скелястих східних висот Темного Узбережжя, перекочується повз давні кам'яні мости й вливається в море біля Краю Імли. Останнім часом кришталеві води річки стали смердючими й помітно зіпсованими. Боячись, що отруйний потік незабаром забруднить берег Обердайна та його запаси води, нічний ельф Тундріс Віндвівер доручив мандрівникам набрати проби просто з озерця під нижнім водоспадом. Проба підтверджує найгірше: протиприродна гниль невпинно пливе вниз за течією до узбережжя."},{t="Відлуння Сквернолісся",b="Хоча вище за течією живуть фурболги Чорнолісся, які й самі потерпають від цього темного впливу, проба свідчить про недугу куди глибшу, ніж звичайні племінні капості. Тундріс розпізнає, що мерзенна порча походить з-понад скель на сході — з отруєних просторів Сквернолісся. Зіпсована проба остаточно доводить, що демонічна хвороба, яка уразила гірські вершини, просочується вниз у водозбори Темного Узбережжя, і захисники Обердайна мусять готуватися до рішучих дій."}},faq={{q="Де взяти Пробу з Річки Кліффспрінг?",a="Її набирають у заводі під першим водоспадом на Річці Скельного Джерела, на північ від Обердайна. Треба йти річкою вглиб суходолу, доки не дійдете до водоспаду під мостом.",al={"де взяти пробу","місце річки кліффспрінг","проба з водоспаду"}},{q="Навіщо Тундрісу Віндвіверу ця вода?",a="Тундріс боїться, що каламуть із річки отруїть прибережні води біля Обердайна. Зібравши й дослідивши пробу, він зможе з'ясувати природу скверни й скласти план, як їй протидіяти.",al={"навіщо збирати воду","завдання тундріса","призначення проби з річки"}},{q="Що каламутить Річку Скельного Джерела?",a="Уздовж річки живуть зіпсовані фурболги Блеквуд, але Тундріс підозрює, що справжнє джерело лиха далі на схід, у Скверноліссі: його демонічна гниль просочується у верхів'я гірських потоків.",al={"що отруїло річку","чому вода зіпсована","джерело псування річки"}},{q="Чи винні фурболги Блеквуд в отруєнні?",a="Вони погіршують становище на берегах річки, але корінь лиха не в них. Фурболги й самі стали жертвами ширшої скверни, що сходить із уражених земель на сході.",al={"чи фурболги це зробили","скверна фурболгів блеквуда","чи фурболги труять воду"}}},fp="24,275,17.572.0,17.522.1,48.206.0,45.211.0,51.197.0,54.199.0"}
P.entries["item:cloth-request"] = {n="Запит на Тканину",s="Запит на Тканину — замовлення, яке написав стормвіндський купець Гарлан Беґлі. Адресоване Ремі Шнайдер у кравецькій майстерні біля каналів, воно просить нових сувоїв тканини й в'язаних речей, щоб поповнити полиці Беґлі, які швидко порожніють.",h="Запит на Тканину — замовлення, яке написав стормвіндський купець Гарлан Беґлі.",kw={"запит на тканину","гарлан беґлі","рема шнайдер","кравецтво","тканина","стормвінд"},ang={["faction:Alliance"]="Ажіотаж довкола міцного одягу відображає відчутну тривогу стормвіндців, які готуються до смути, хоч регентство нічого офіційно не оголошувало.",["profession:Tailoring"]="Замовлення показує жваву внутрішню торгівлю тканинами в Стормвінді, де кравці з околиць, як-от Шнайдери, постачають тканий крам до крамниць і торговців спорядженням."},sec={{t="Попит на міцні речі",b="У цьому торговому замовленні Гарлан Беґлі просить кравців із кварталу каналів знову постачити йому в'язаний одяг і тканину. Беґлі зауважує раптовий тривожний сплеск торгівлі: звичайні містяни й мандрівники масово закуповують обладунки й міцний одяг, ніби готуються до лихої пори. Коли замовлення доставляють Ремі Шнайдер, кравчиня спантеличена й насторожена. Рема дивується, навіщо міщани потай одягаються в броню, коли Дім Вельмож не оголошував жодної відкритої війни, і в ній зростає тиха підозра, що провід корони приховує заворушення."}},faq={{q="Що таке Запит на Тканину?",a="Це письмове замовлення від крамаря Гарлана Беґлі до кравчині Реми Шнайдер: він просить свіжих партій тканини й плетеного одягу, щоб поповнити крамницю.",al={"що таке запит на тканину","предмет запит на тканину","бланк замовлення гарлана"}},{q="Чому Гарланові Беґлі потрібно більше тканини?",a="Торгівля в Беґлі йде напрочуд жваво. Містяни й мандрівники скуповують обладунки й міцний одяг цілими оберемками, і його запаси вичерпалися.",al={"чому гарлану потрібно більше тканини","чому в беґлі немає товару","причина поповнення беґлі"}},{q="Куди треба віднести цей запит?",a="Замовлення несуть Ремі Шнайдер у Кравецьку Майстерню на Каналі, що на водних шляхах Стормвінда.",al={"куди віднести запит на тканину","кому віддати запит","доставка запиту на тканину"}},{q="Чому стормвіндці скуповують стільки обладунків і одягу?",a="Напевно не знають ні торговці, ні прості люди. Раптовий ажіотаж тривожить Рему Шнайдер: вона гадає, чи не приховує королівський двір від народу війну, що назріває, чи якусь іншу небезпеку.",al={"чому люди купують обладунки","чи стормвінд на війні","підозри реми шнайдер"}}},fp="13,237,21.579.0,26.157.0,39.155.0,35.114.0,62.195.0"}
P.entries["item:cloven-hoof"] = {n="Роздвоєне Копито",s="Роздвоєне Копито — загадкова реліквія, яку кентаври племені Ґалак стережуть у глибинах Тисячі Голок. Вона зберігається в прадавньому священному полум'ї в Твердині Розщепленого Копита й випромінює незвичну надприродну енергію, яку прагнуть збагнути вчені-таурени.",h="Роздвоєне Копито — загадкова реліквія, яку кентаври племені Ґалак стережуть у глибинах Тисячі Голок.",kw={"роздвоєне копито","кентаври","ґалак","твердиня розщепленого копита","тисяча голок","рау кліффраннер","реліквія"},ang={["class:Shaman"]="Обрядові стихії, якими безпечно гасять магічне полум'я й дістають насичені силою реліквії, показують, наскільки тонкою справою є духовні пошуки в Калімдорі.",["race:Tauren"]="Поколіннями кочові таурени потерпали від безжальних нападів кентаврів. Розгадка походження й магічних таємниць таких реліквій, як Роздвоєне Копито, дає цінне знання проти давніх ворогів."},sec={{t="Священна реліквія кентаврів",b="Роздвоєне Копито, що лежить у прадавній жаровні в найглибшому закутку Твердині Розщепленого Копита, — одна з найцінніших реліквій кентаврів Ґалак. Артефакт постійно оповитий магічним полум'ям, і щоб узяти його в руки, треба на мить загасити вогонь освяченою водою. Суспільство кентаврів славиться жорстокістю й розколоте на ворожі клани, проте їхнє благоговіння перед жаровнею свідчить про обрядове значення, безпосередньо пов'язане з їхнім походженням. Таурени-дослідники, як-от Рау Кліффраннер із Застави Вільного Вітру, вважають, що дивна аура копита може відкрити важливі таємниці народу, який поколіннями тероризує рівнини Калімдору."}},faq={{q="Де зберігається Роздвоєне Копито?",a="Роздвоєне Копито лежить у прадавній жаровні в самій глибині Твердині Розщепленого Копита — печери в Кручі Розколотого Копита на північ від Застави Вільного Вітру. Його пильно стережуть добірні воїни кентаврів Ґалак.",al={"місце роздвоєного копита","де знайти роздвоєне копито","реліквія тримання сплітгуфів"}},{q="Навіщо Рау Кліффраннеру Роздвоєне Копито?",a="Рау Кліффраннер хоче дослідити артефакт, щоб більше дізнатися про походження й магію кентаврів. Він відчуває, що від реліквії йде дивна енергія, і сподівається, що вона відкриє давно приховані таємниці ворожих кланів.",al={"навіщо отримати роздвоєне копито","завдання рау кліффраннера","хто хоче роздвоєне копито"}},{q="Як дістати Роздвоєне Копито з жаровні?",a="Реліквію огортає магічний вогонь, тож просто взяти її не вийде. У прадавню жаровню треба вилити фіал особливої води, щоб ненадовго загасити священне полум'я, — і вихопити копито, доки вогонь не спалахнув знову.",al={"як дістати роздвоєне копито","загасити священне полум'я","використання фіали з гравіюванням"}},{q="Хто такі кентаври Ґалак, що його стережуть?",a="Плем'я Ґалак — найвпливовіше угруповання кентаврів на півночі Тисячі Голок. Їхня твердиня — Круча Розколотого Копита, і вони люто боронять свій священний вогонь від чужинців.",al={"кентаври ґалак","кентаври скелі сплітгуф","хто стереже полум'я"}}},fp="11,259,22.647.0,30.200.0,46.215.0,50.240.0,38.203.0"}
P.entries["item:comar-s-heart"] = {n="Серце Комара",s="Серце Комара — моторошний обрядовий складник, вирізаний із грудей Комара Вілларда, вірного чоловіка, що блукає болотами Багнокраю в пошуках зниклої дружини. Чорнокнижники-Відступники в Андерсіті шукають цю реліквію чистої відданості, щоб живити нею обряди виклику сукуба.",h="Серце Комара — моторошний обрядовий складник, вирізаний із грудей Комара Вілларда, вірного чоловіка, що...",kw={"серце комара","комар віллард","сукуб","чорнокнижник","багнокрай","карендін галґар","храм проклятих"},ang={["class:Warlock"]="Серце Комара показує холодну, прагматичну жорстокість демонології: незаплямована людська чеснота — лише приманка, щоб заманити сукуба вам на службу.",["race:Undead"]="Для Відступників вирвати серце вірного закоханого — свідчення того, наскільки остаточно розірвалися почуттєві зв'язки між живими й нежиттю Лордерона."},sec={{t="Маяк чистоти",b="Щоб скорити таку примхливу й хижу істоту, як сукуб, чорнокнижники мусять приманити демона справжньою чистотою й відданістю. Учні Карендіна Галґара в Андерсіті вирізняють Комара Вілларда як одного з небагатьох чоловіків, наділених такою незаплямованою вірністю. Його дружина зникла в розбурханому вирі, що охопив Східні Королівства, а Комар уперто блукає розмоклими дорогами Багнокраю й не полишає пошуків. Саме ця непохитна любов і прирікає його на смерть: його серце, що ще б'ється, стає ідеальною приманкою для демонічного слуги."},{t="Ціна спокуси",b="Щоб здобути серце, учням-Відступникам доводиться вирушати далеко на південь спірними землями, повз Міст Тандол, углиб боліт, де панує Альянс. Принесене до Храму Проклятих разом із Серцем Даліна, воно на вигляд зовсім звичайне, хоч колись його вела глибока доброта. Та для чуттів Нижнього Світу залишки чесноти, що променіють від плоті Комара, — п'янка приманка, досить сильна, щоб витягти сукуба крізь завісу між світами й віддати його в рабство чорнокнижникові."}},faq={{q="Хто такий Комар Віллард?",a="Комар Віллард — відданий чоловік, що шукав у небезпечному Багнокраї бодай якийсь слід своєї зниклої дружини. Безмежна любов і непохитна надія, якої він не втрачав, зробили його відомим як людину воістину чистого серця.",al={"хто такий комар","історія комара","чому вбити комара"}},{q="Навіщо чорнокнижникам Серце Комара?",a="Чорнокнижникам Андерсіті потрібне серце цілком чистого й шляхетного смертного, щоб приманити й прив'язати сукуба. Цього демона природно вабить можливість зіпсувати й пожерти справжню чесноту, тож незламна відданість Комара — неперевершена принада.",al={"навіщо серце комара","для чого серце комара","серце сукуби"}},{q="Де знайти Комара Вілларда?",a="Він блукає головним шляхом на півночі Багнокраю, трохи на південь від Мосту Тандол, що з'єднує Аратійське нагір'я з Каз Моданом.",al={"місце комара вілларда","де комар","як знайти комара"}},{q="Хто посилає чорнокнижників по серце?",a="Це доручення дають наставники чорнокнижників в Андерсіті на чолі з Карендіном Галґаром у Храмі Проклятих — як частину обрядового навчання учня, що має викликати сукуба.",al={"хто хоче серце комара","хто дає серця чистих","серце карендіна гелґара"}}},fp="13,268,18.556.0,22.505.1,22.204.0,35.239.0,29.133.0,40.188.0"}
P.entries["item:consecrated-rune"] = {n="Освячена Руна",s="Освячена Руна — священний предмет із написом, який вручають новоспеченим дворфійським паладинам, що навчаються в Долині Холодного Хребта. Це вступний виклик від Бромоса Ґруммнера, який велить послушникам з'явитися до Анвілмара й узятися до своїх обов'язків як Лицарі Срібної Длані.",h="Освячена Руна — священний предмет із написом, який вручають новоспеченим дворфійським паладинам, що...",kw={"освячена руна","паладин","бромос ґруммнер","срібна длань","анвілмар","долина холодного хребта","святе світло"},ang={["class:Paladin"]="Для дворфійських паладинів отримати цю руну означає зробити офіційний крок до лав Лицарів Срібної Длані під проводом Бромоса Ґруммнера.",["race:Dwarf"]="Руна відображає, як людські священні традиції вросли в дворфійську бойову культуру — на ґрунті спільного союзу та взаємної поваги між Айронфорджем і людством."},sec={{t="Поклик Срібної Длані",b="Дворфи-паладини, які доводять себе в Долині Холодного Хребта, отримують Освячену Руну, щойно покажуть базову бойову вправність. Руна, вкрита священними словами й благословенна Святим Світлом, походить від Бромоса Ґруммнера — наставника паладинів, що мешкає в Анвілмарі. Дворфи глибоко шанують традиції Святого Світла, які їм передали союзники-люди. Прочитання руни — водночас офіційний виклик і символічний обряд посвяти, що підтверджує місце новачка серед Лицарів Срібної Длані."}},faq={{q="Для чого потрібна Освячена Руна?",a="Руна — це письмовий виклик для дворфів-новачків, що обрали шлях паладина. Вона велить їм знайти Бромоса Ґруммнера в Анвілмарі, щоб продовжити навчання.",al={"призначення освяченої руни","що робить руна","освячена руна предмет завдання"}},{q="Хто надсилає Освячену Руну?",a="Її надсилає Бромос Ґруммнер, дворф-наставник паладинів в Анвілмарі в Долині Холодного Хребта.",al={"хто дав освячену руну","походження руни","руна бромоса ґраммнера"}},{q="Чому дворфи-паладини шанують традиції Срібної Длані?",a="Багато чого про Святе Світло й шлях Срібної Длані дворфи навчилися в наставників-людей. Вони глибоко шанують історію ордену, його традиції й віру в те, що одна-єдина жертва може змінити долю Азероту.",al={"дворфи-паладини срібна длань","чому дворфи паладини","дворфи та світло"}}},fp="16,275,28.546.0,38.169.0,31.105.0,65.222.0"}
P.entries["item:console-key"] = {n="Ключ від Консолі",s="Ключ від консолі — механічний ключ обходу, який тримає Винахідник Сніґґлз на розкопках Венчурної Компанії в Пустках. Він відмикає головний пульт керування, у якому стоїть самофланж, і дає змогу дістати пристрій, коли апарат вимкнено.",h="Ключ від консолі — механічний ключ обходу, який тримає Винахідник Сніґґлз на розкопках Венчурної Компанії в...",kw={"ключ від консолі","винахідник сніґґлз","самофланж","венчурна компанія","пульт","пустки"},ang={["faction:Horde"]="Забравши Ключ від Консолі у Винахідника Сніґґлза, ви допомагаєте зірвати хижацьку промислову діяльність Венчурної Компанії в самому серці Пусток.",["profession:Engineering"]="Венчурна Компанія використовує особливі замки на ключ, щоб уберегти тендітні інженерні дослідні зразки на кшталт самофланжа від конкурентів."},sec={{t="Як уберегти апарат",b="Венчурна Компанія має на півночі Пусток велику промислову заставу, що залежить від особливих парових машин, якими керує загадковий пристрій, відомий як самофланж. Щоб ніхто сторонній не втрутився, консоль апарата міцно замкнена. Лише головний технік на місці, Винахідник Сніґґлз, має Ключ від Консолі, потрібний, щоб відчинити корпус пульта й повністю знеструмити установку."},{t="Як вимкнути установку",b="Щоб вивести з ладу пульт керування, однієї грубої сили замало. Коли допоміжні вентилі повернуто, а внутрішній апарат охолоджено до холостого ходу, вставлений Ключ від Консолі розмикає останні кола. Поворот ключа вичерпує решту енергії з пульта й відмикає корпус, щоб самофланж можна було безпечно витягти з машинерії."}},faq={{q="Що відмикає Ключ від Консолі?",a="Він відмикає головну консоль керування на установці Венчурної Компанії на півночі Пусток. Коли машина працює вхолосту, ключ відкриває доступ до самофланжа й відрізає живлення термінала.",al={"для чого ключ від консолі","що відчиняє ключ від консолі","використання ключа від консолі"}},{q="У кого Ключ від Консолі?",a="Ключ тримає Винахідник Сніґґлз — інженер Венчурної Компанії, що сидить у хатині трохи на північний схід від головної консолі.",al={"хто дропає ключ від консолі","де взяти ключ від консолі","ключ майстра сніґлза"}},{q="Чому консоль узагалі замкнена?",a="Венчурна Компанія працює з власною небезпечною промисловою технікою. Замкнений термінал не дає суперникам чи неслухняним робітникам зіпсувати машину або витягти цінні деталі — як-от самофланж.",al={"навіщо ключ","чому самофланж замкнений"}},{q="Чи можна скористатися ключем, не перекривши клапанів?",a="Ключ відмикає консоль лише тоді, коли апарат вимкнено, а стрілки приладів показують нуль. Якщо длубатися в увімкненій консолі, механізм може вибухнути.",al={"спершу ключ","чи просто відімкнути консоль"}}},fp="11,253,22.419.0,21.360.1,33.179.0,28.132.0,45.222.0,52.186.0"}
P.entries["item:control-console-operating-manual"] = {n="Посібник з Керування Пультом",s="Посібник з керування пультом — технічний документ, що описує, як працювати з машинами на дослідницькій ділянці Венчурної Компанії на південний захід від Багнистого Болота. У ньому є настанови, потрібні, щоб безпечно перекрити вентилі й від'єднати загадкову штуковину, відому як самофланж.",h="Посібник з керування пультом — технічний документ, що описує, як працювати з машинами на дослідницькій...",kw={"посібник з керування","пульт","самофланж","венчурна компанія","вентилі","інженерна справа"},ang={["faction:Horde"]="Посібник дає слідчим Орди змогу зазирнути всередину загарбницької промислової діяльності, яку Венчурна Компанія розгорнула на півночі Пусток.",["profession:Engineering"]="Посібник показує типову гоблінську інженерну філософію: системи під високим тиском, ледь безпечні, якими керує безладна мішанина важелів і вентилів замість виважених запобіжників."},sec={{t="Як розібратися в гоблінських машинах",b="Венчурна Компанія має відлюдну бурову й дослідницьку ділянку на півночі Пусток, на південний захід від Багнистого Болота. Як і годиться гоблінам, їхні складні машини працюють на непередбачуваній мішанині манометрів, вентилів під тиском і пов'язаних між собою механізмів, що мають приборкати пристрій під назвою самофланж. Без належного порядку дій поводження з такими нестабільними штуковинами загрожує катастрофічною віддачею або повним блокуванням системи. Цей посібник описує точну послідовність дій із вентилями, потрібну, щоб безпечно від'єднати головний апарат і не спричинити вибуху."}},faq={{q="Для чого потрібен Посібник з Керування Пультом?",a="У ньому записано, як керувати пультом Венчурної Компанії на південний захід від Багнистого Болота: посібник пояснює, які клапани перекрити, щоб від'єднати самофланж.",al={"що дає посібник","використання посібника","навіщо мені посібник"}},{q="Що таке самофланж?",a="Навіть дослідники поза Венчурною Компанією не до кінця розуміють, що робить самофланж. Схоже, це хитромудрий центральний механізм гоблінської роботи, пов'язаний із їхнім бурінням і промисловими роботами в Пустках.",al={"що робить самофланж","історія самофланжа","що це за машина"}},{q="Хто написав цей посібник?",a="Посібник склали техніки Венчурної Компанії, що наглядають за дослідницькою заставою, — щоб робітники могли керувати пультом і підтримувати потрібний тиск у його клапанах.",al={"хто зробив посібник","автор посібника"}},{q="Що буде, якщо загубити посібник?",a="На самому пульті є зрозумілі прилади й шкали, що показують тиск у клапанах, тож вправний шукач пригод може зчитати все просто з панелі й перемкнути важелі без посібника в руках.",al={"загублений посібник","видалений посібник"}}},fp="32,289,28.603.0,54.215.0,22.230.0,22.209.0,34.214.0"}
P.entries["item:corroded-shrapnel"] = {n="Роз'їдена Шрапнель",s="Роз'їдена Шрапнель — зазубрені уламки металу, що глибоко застрягли в зіпсованих деревлянах Гір Кам'яного Кігтя. Здобуті з полеглих захисників, як-от Обвуглених і Почорнілих Древніх, ці уламки — речовий доказ мерзенної зброї, яку застосувала Венчурна Компанія, відступаючи.",h="Роз'їдена Шрапнель — зазубрені уламки металу, що глибоко застрягли в зіпсованих деревлянах Гір Кам'яного...",kw={"роз'їдена шрапнель","венчурна компанія","каела шедовспір","ґаксим растфіззл","древні","гори кам'яного кігтя"},ang={["class:Druid"]="Велично-давні Древні Калімдору, спотворені гоблінськими боєприпасами й гнійними уламками металу, — гостре нагадування про ціну, яку дика природа платить за неконтрольоване визискування.",["race:Gnome"]="Те, як Ґаксим шукає отруєну шрапнель, показує практичний, науковий підхід гномів до розв'язання природних аномалій, перед якими безсилі звичні лісові вартові."},sec={{t="Рештки промислової руїни",b="Коли Венчурну Компанію відкинули з гаїв Гір Кам'яного Кігтя, гобліни, прикриваючи втечу, пустили в хід жорстокі, безрозсудні боєприпаси. Шрапнель цієї вибухової зброї впилася в деревлян, що захищали долину, і глибоко засіла в їхній корі й осерді зазубреним металом. Замість загоїтися, давні охоронці поволі піддалися зіпсуттю: їхня деревина чорніла, а лють оберталася на кожного, хто ступав у долину. Іржаві, отруєні уламки, вийняті з цих поранених захисників, потрібні Каелі Шедовспір, щоб гном Ґаксим Растфіззл міг дослідити, як саме діє це зіпсуття."}},faq={{q="Звідки ця шрапнель?",a="Роз'їдену Шрапнель виколупують із тіл зіпсованих деревників у Горах Кам'яного Кігтя — Обвуглених Прадавніх, Почорнілих Прадавніх і Мстивих Прадавніх.",al={"де взяти шрапнель","дроп роз'їденої шрапнелі","хто дропає шрапнель"}},{q="Чому шрапнель застрягла в деревниках?",a="Венчурна Компанія стріляла по деревниках вибуховими зазубленими снарядами, коли лісові охоронці повстали, щоб вигнати гоблінів-лісорубів із долини. Металеві уламки встрягли в їхню кору під час бою й так і лишилися там.",al={"як шрапнель потрапила в деревників","чому деревники повні металу"}},{q="Чи шрапнель зіпсувала прадавніх лісу?",a="За словами Каели Шедовспір, гном Ґаксим вважає, що скверна, яка вражає деревників, прямо пов'язана з мерзенним хімічним чи металевим складом зброї гоблінів, що відступали.",al={"чи шрапнель зіпсувала деревників","чому деревники шалені"}},{q="Хто хоче оглянути шрапнель?",a="Нічна ельфійка Каела Шедовспір просить зразок, щоб передати його гномові-винахідникові Ґаксиму, який хоче вивчити його властивості й з'ясувати природу недуги деревників.",al={"кому потрібна шрапнель","здати шрапнель"}}},fp="17,302,27.617.0,35.162.0,44.225.0,63.202.0,34.189.0"}
P.entries["item:corrupt-manifestation-s-bracers"] = {n="Наручі Зіпсутого Втілення",s="Наручі зіпсутого втілення — тілесні рештки отруєного водяного елементаля з узбережжя Срібнолісся. Їх здобувають послушники-шамани під час випробування «Поклик Води», і вони стають важливою складовою обряду очищення стихії на Жаровні Вічного Джерела.",h="Наручі зіпсутого втілення — тілесні рештки отруєного водяного елементаля з узбережжя Срібнолісся.",kw={"наручі зіпсутого втілення","поклик води","шаман","водяний елементаль","срібнолісся","очищення"},ang={["class:Shaman"]="Здобути й очистити ці наручі — останнє випробування Поклику Води, що доводить силу шамана вгамовувати й відновлювати спотворені стихії."},sec={{t="Очисна жертва",b="Коли моровиця Погибелі пронеслася Лордероном, вона не пощадила й природних духів землі. На туманних берегах Срібнолісся, на захід від Гробниці, колись священне водне святилище зазнало порчі, і його водне втілення перетворилося на агресивну, зіпсовану тінь. Послушників-шаманів посилають угамувати цю істоту й забрати її наручі. Поєднані з найчистішою водою на Жаровні Вічного Джерела, ці пута кидають у полум'я, щоб зняти осквернення й викликати чистого духа стихії."}},faq={{q="Для чого потрібні ці наручі?",a="Їх кладуть на Жаровню Вічного Джерела разом із краплями чистої води під час обряду очищення. Обряд розвіює скверну, що лишилася у святилищі в Срібноліссі, і викликає чистого духа води.",al={"що роблять наручі","наручі поклику води","використання зіпсутих наручів"}},{q="Звідки беруться наручі?",a="Їх забирають з решток Зіпсованого Малого Прояву Води — біля оскверненого святилища стихій на узбережжі Срібнолісся, на захід від Гробниці.",al={"де взяти наручі","місце зіпсутого втілення"}},{q="Чому елементаль води зіпсувався?",a="Елементаля спотворили чума й темні сили, що отруїли землі Лордерону й відрізали місцевих духів від спілкування з шаманами.",al={"чому вода осквернена","псування води сільверпайну"}}},fp="31,283,20.539.0,32.208.0,31.175.0,43.152.0"}
P.entries["item:corrupted-brain-stem"] = {n="Зіпсутий Стовбур Мозку",s="Зіпсуті стовбури мозку — біологічні зразки, здобуті зі спотворених наг і сатирів, що населяють Чорноглибинні Печери й узбережжя Ашенвалю. Їх шукає Ґершала Найтвіспер з Обердайна, щоб вивчити тілесні каліцтва, спричинені безоглядною магічною скверною. Досліджуючи ці мізки, вчені нічних ельфів сподіваються зрозуміти — а може, й відвернути — подібну долю для ельфів крові.",h="Зіпсуті стовбури мозку — біологічні зразки, здобуті зі спотворених наг і сатирів, що населяють Чорноглибинні...",kw={"зіпсутий стовбур мозку","ґершала найтвіспер","обердайн","наги","сатири","чорноглибинні печери"},ang={["faction:Alliance"]="Розвідники Альянсу, яких посилають в Ашенваль, ризикують у глибинах Блекфатому, щоб допомогти вченим Обердайна зрозуміти загрози, що зростають по всьому Азероту.",["race:NightElf"]="Для нічних ельфів збирання цих решток — похмуре нагадування про трагічну історію свого народу й потворні наслідки неприборканих магічних і демонічних утручань."},sec={{t="Анатомія перетворення",b="Сатири й наги Калімдору — живі свідчення спотворювальної сили забороненої магії й демонічних угод. Колись безоглядні Високородні калдореї безповоротно перетворилися на зміїподібних морських звірів і рогатих демонічних потвор. Стовбури мозку, здобуті з цих істот, мають важкі тілесні мутації — пряме анатомічне свідчення того, як глибоко згубні енергії вгризаються в нервову систему колишніх ельфів."},{t="Застереження Ґершали",b="У прибережному поселенні Обердайн Ґершала Найтвіспер із тривогою стежить за чутками про ельфів крові зі Східних Королівств. Побоюючись, що їхні загравання з демонічним чаклунством породять іще одне покоління чудовиськ в Азероті, Ґершала доручає шукачам пригод вирушити в Чорноглибинні Печери. Розтинаючи тканини і наг, і сатирів, Ґершала сподівається простежити шлях магічного виродження, перш ніж загине ще одна ельфійська культура."}},faq={{q="З яких істот добувають Зіпсутий Стовбур Мозку?",a="Його збирають із наг і сатирів, що живуть у Чорноглибинних Печерах і на навколишніх берегах Ашенвалю, — зокрема з оракулів і морських відьом Блекфатом та сатирів Фолленрут.",al={"хто дропає стовбури мозку","дроп зіпсутого стовбура мозку","де взяти стовбури мозку"}},{q="Кому потрібні ці стовбури мозку й навіщо?",a="Ґершала Найтвіспер із портового Обердайна на Темному Узбережжі просить їх для анатомічних досліджень магічної скверни.",al={"кому потрібен зіпсутий стовбур мозку","завдання ґершали","здати стовбури мозку"}},{q="Що нічні ельфи сподіваються дізнатися із цих зразків?",a="Ґершала боїться, що демонічна магія, якою користуються ельфи крові, перетворить їх на потвор — так само, як колись прадавні Високородні стали нагами й сатирами. Вивчення цих зразків допомагає зрозуміти, як демонічна енергія змінює тіла ельфів.",al={"чому вивчати наґ і сатирів","дослідження псування","зв'язок із кривавими ельфами"}},{q="Чи можна знайти їх поза Чорноглибинними Печерами?",a="Так. Їх мають і деякі сатири Фолленрут та жриці припливів Блекфатом, що вештаються біля входу до печер на узбережжі Ашенвалю.",al={"за межами чорноглибинних печер","стовбури мозку ашенвейл","чи падають вони з наземних створінь"}}},fp="20,403,25.444.0,18.475.0,44.186.0,36.136.0,58.226.0,60.144.0"}
P.entries["item:corrupted-kor-gem"] = {n="Зіпсутий Самоцвіт Кор",s="Зіпсутий Самоцвіт Кор — могутній магічний провідник, спотворений темними обрядами наг, що живуть біля Чорноглибинних Печер. Чаклуни прагнуть таких каменів, бо вони здатні вбирати чисту тайну силу, але зіпсутий самоцвіт треба очистити, перш ніж він послужить праведному ремеслу.",h="Зіпсутий Самоцвіт Кор — могутній магічний провідник, спотворений темними обрядами наг, що живуть біля...",kw={"зіпсутий самоцвіт кор","тундріс віндвівер","джордан стілвелл","наги","паладин","обердайн"},ang={["class:Paladin"]="Паладини, що прагнуть викувати священну зброю, мусять здобути й очистити Самоцвіт Кор — як свідчення того, що вони здатні протистати злу й обертати темряву на праведну силу.",["race:NightElf"]="Учені нічних ельфів, як-от Тундріс Віндвівер, розуміють, яку небезпеку несуть реліквії наг, що підступають до Темного Узбережжя, і бережуть знання, потрібні, щоб очищати давні камені."},sec={{t="Вмістища зіпсутої сили",b="Самоцвіти Кор від природи мають рідкісну здатність уловлювати й утримувати чималі магічні енергії, тож для чаклунів і зачарованого ковальства вони — безцінні фокуси. Та на узбережжі біля руїн Чорноглибинних Печер місцеві оракули й жриці припливів із наг забирають ці камені для власних темних обрядів. Мерзенними чарами зміїсті істоти викривлюють камінь, наповнюючи його злісною морською порчею. Хоча це псує природу самоцвіту, прихована в ньому сила лишається потужною, і ті, кому потрібні виняткові магічні фокуси, відбирають такі камені в наг."},{t="Очищення й ковальство",b="Зіпсутий Самоцвіт Кор треба очистити — лише тоді Тундріс Віндвівер дозволить віднести його Джорданові Стілвеллу. Нічний ельф з Обердайна змиває з каменя злу магію наг і запевняє паладина, що сила самоцвіту лишилася неушкодженою й готовою до ковальського обряду."}},faq={{q="Для чого потрібен самоцвіт Кор?",a="Самоцвіти Кор — потужні провідники й сховища магічної енергії. Чародії тримають у них величезні запаси сили для заклинань, а вправні ковалі вставляють їх у зачаровану зброю, щоб спрямовувати магію.",al={"що таке самоцвіти кор","призначення самоцвіту кор","історія самоцвіту кор"}},{q="Де знайти Зіпсуті Самоцвіти Кор?",a="Їх носять наги-чаклунки — жриці припливів і оракули Блекфатом, — що живуть біля прадавніх руїн і в самих руїнах, які ведуть до Чорноглибинних Печер на межі Ашенвалю й Темного Узбережжя.",al={"де знайти зіпсутий самоцвіт кор","місце самоцвіту кор","хто дропає самоцвіт кор"}},{q="Чому самоцвіт треба очистити?",a="Під час своїх обрядів наги насичують самоцвіти мерзенною магією. Зіпсутий самоцвіт у священному ремеслі може осквернити горно чи того, хто носитиме зброю, тож потрібен знавець природи чи Світла, як-от Тундріс Віндвівер, щоб вигнати зло, перш ніж самоцвіт вправлять у зброю.",al={"очистити самоцвіт кор","чому очищувати самоцвіт кор","чи самоцвіт злий"}},{q="Чи зберігає очищений самоцвіт свою силу?",a="Так. Очистивши самоцвіт, Тундріс Віндвівер запевняє паладина, що сила каменя не постраждала й він чудово підійде для обряду Джордана Стілвелла.",al={"чи очищення псує самоцвіт","слабший після очищення"}}},fp="17,288,24.601.0,25.263.1,27.238.0,35.236.0,29.280.0,42.153.0"}
P.entries["item:cougar-claws"] = {n="Кігті Пуми",s="Кігті Пуми здобувають із рівнинних пум, що блукають центральними рівнинами Малгору. Вони слугують важливим матеріалом у ритуальному ремеслі тауренів, уособлюючи неприборкану рівновагу й природну лють диких хижаків.",h="Кігті Пуми здобувають із рівнинних пум, що блукають центральними рівнинами Малгору.",kw={"кігті пуми","пума","малл тандергорн","водяна криниця","тотем","гобліни","малгор"},ang={["class:Shaman"]="Шамани знають, що сутність місцевих хижаків нерозривно пов'язана з духами рівнин, тож вона — неодмінний провідник для очисних оберегів і тотемів.",["race:Tauren"]="Збирання цих кігтів учить молодих тауренів, що полювання вкорінене в рівновазі й духовній потребі — на разючу відміну від безоглядного забруднення, яке несуть підприємства гоблінів."},sec={{t="Посудина природної рівноваги",b="Рівнинна пума — один із найвищих хижаків розлогих лугів Малгору, що переслідує здобич з інстинктивною грацією. У традиції тауренів узяти кігті такого хижака — не легковажне вбивство й не полювання за трофеями, а спосіб приборкати природний дух звіра. Коли підприємства гоблінів починають оскверняти прабатьківські води рівнин, Малл Тандергорн закликає молодих мисливців зібрати ці кігті разом із кігтями степових переслідувачів. Таурени вірять, що чисті, неспотворені хижацькі інстинкти тутешніх звірів можна вплести в ритуальний тотем, здатний вичистити неприродні отрути й лихе чаклунство з отруєної Водяної Криниці Тандергорнів."}},faq={{q="Для чого потрібні Кігті Пуми?",a="Малл Тандергорн разом із кігтями скрадачів використовує їх, щоб виготовити Очисний Тотем Громорога. Таурени вплітають чистий дух місцевих хижаків в обрядові предмети, щоб очищати криниці, отруєні промисловими затіями гоблінів.",al={"використання кігтів пуми","навіщо кігті пуми","призначення кігтів пуми"}},{q="Звідки беруться Кігті Пуми?",a="Їх знімають із рівнинних пум, що никають хвилястими степами Малгору, переважно на схід і на захід від Села Бладгуф.",al={"де взяти кігті пуми","джерело кігтів пуми","хто дропає кігті пуми"}},{q="Навіщо Маллу Тандергорну кігті хижаків, щоб очистити криницю?",a="Шаманські й друїдські традиції тауренів шанують чистоту, з якою полюють дикі звірі. На відміну від гоблінів, що виснажують і плюндрують землю, місцеві хижаки живуть у цілковитій рівновазі з нею, тож їхня сутність ідеально протидіє штучній скверні.",al={"навіщо кігті хижаків","чому маллу кігті","тотем хижаків кігті"}},{q="Чи придатні Кігті Пуми ще для чогось?",a="Окрім виготовлення обрядового тотема для Водяної Криниці Тандергорнів, особливого вжитку вони не мають, і їх зазвичай продають місцевим торговцям.",al={"інше використання кігтів пуми","продати кігті пуми"}}},fp="12,218,27.670.0,31.228.0,32.128.0,64.259.0,42.138.0"}
P.entries["item:courser-eye"] = {n="Око Скакуна",s="Очі Скакунів — біологічні реагенти, які добувають у рогатих скакунів, що бродять нагір'ям Гір Кам'яного Кігтя. Знахар Джин'Зіл у Малака'джині шукає їх цілу купу, щоб приготувати суміш, яку він глузливо називає лісовою магією.",h="Очі Скакунів — біологічні реагенти, які добувають у рогатих скакунів, що бродять нагір'ям Гір Кам'яного Кігтя.",kw={"око скакуна","знахар джин'зіл","малака'джин","скакуни","гори кам'яного кігтя","вуду"},ang={["race:Troll"]="Грубе використання тваринних складників Знахарем Джин'Зілом відбиває темнішу, практичну сторону тролівської алхімії й моджо, що їх обертають проти ворогів Орди."},sec={{t="Тролівська суміш",b="На віддаленій заставі Малака'джин Знахар Джин'Зіл варить різні племінні суміші, щоб дати раду нічним ельфам, які оспорюють цей край. Оленячі очі — не рідкісний складник у вуду й народній алхімії, але Джин'Зіл вимагає одразу тридцять очей скакунів — куди більше, ніж потрібно для звичайних чарів. Змішані з лускою чарівних драконів, живицею й котячими вусами, очі стають основою смертельного зілля, призначеного для нічних ельфів-бранців, замкнених у клітках у глибині його лігва."}},faq={{q="Де знайти очі скакунів?",a="Їх добувають із різних скакунів — рогатих і великих, — що водяться високо в Горах Кам'яного Кігтя, особливо довкола Озера Міркфаллон і Піку Кам'яного Кігтя.",al={"місця очей скакунів","де взяти око скакуна","як отримати око скакуна"}},{q="Навіщо Знахареві Джин'Зілу стільки очей?",a="Jin'Zil claims that one can never have enough eyes when preparing a proper brew. He combines them with native fauna parts for the concoction he mockingly calls forest magic.",al={"чому 30 очей","навіщо джин'зілу очі","що джин'зіл робить з очима скакунів"}},{q="Що стається, коли Джин'Зіл доварює своє лісове зілля?",a="Jin'Zil plans to use his forest magic concoction on the night elf prisoners caged in his cave. Their fate is revealed when his experiment is carried out.",al={"результат лісової магії джин'зіла","що буде з в'язнями в малакаджині"}}},fp="11,250,20.483.1,29.207.0,48.173.1,60.153.1"}
P.entries["item:covert-ops-pack"] = {n="Ранець Таємних Операцій",s="Ранець Таємних Операцій — набір особливого підривного спорядження й оперативних креслень, зібраний для шпигунських дій Альянсу в Горах Кам'яного Кігтя. Створений, щоб зламати хижацьку присутність Венчурної Компанії на Кручі Вітрорізу, він споряджає агентів для злагодженої диверсії та здобуття цінних технічних відомостей.",h="Ранець Таємних Операцій — набір особливого підривного спорядження й оперативних креслень, зібраний для...",kw={"ранець таємних операцій","венчурна компанія","круча вітрорізу","диверсія","вибухівка","гори кам'яного кігтя"},ang={["faction:Alliance"]="Таємна операція з цим ранцем прямо підтримує боротьбу вартових проти комерційного плюндрування Гір Кам'яного Кігтя.",["profession:Engineering"]="Ранець — зразок вишуканої гномської кмітливості, оберненої проти гоблінської промисловості: саморобні заряди НҐ-5 допомагають розкрити таємниці машин Венчурної Компанії."},sec={{t="Диверсія за планом",b="Видаваний для таємних ударів глибоко на землях Венчурної Компанії, Ранець Таємних Операцій поєднує грубу руйнівну силу з тактичною точністю. Усередині — позначена кольорами вибухівка НҐ-5 із дистанційними детонаторами й докладні настанови під назвами «План Альфа» і «План Бета». Задум полягає в тому, щоб улаштувати потужні відволікальні вибухи на ключових об'єктах — лісопильні біля Озера Скельної Заводі та східній шахті. Поки гобліни метушаться, гасячи пожежі й оцінюючи поломки, лазутчик прослизає крізь хаос і викрадає важливі документи та креслення."},{t="Збіг інтересів",b="Уміст ранця служить Альянсові в Горах Кам'яного Кігтя подвійній меті. Для вартових нічних ельфів вибухи й крадіжка зривають безжальну суцільну вирубку й плюндрування священних гірських схилів. Для винахідників Альянсу головна нагорода — самі документи. Здобуті інженерні креслення Венчурної Компанії дають рідкісне уявлення про важкі гоблінські машини, відкривають механічні слабкі місця, якими можна скористатися, і дають інженерам Альянсу змогу перейняти промислові нововведення для власних задумів."}},faq={{q="Що в Ранці Таємних Операцій?",a="У ранці — дві пари кольорових підривних зарядів: червона й синя вибухівка НҐ-5 із відповідними дистанційними детонаторами. Там також є письмові вказівки до завдання з описом Плану Альфа й Плану Бета.",al={"вміст ранця таємних операцій","що в ранці","предмети в ранці таємних операцій"}},{q="Яке тактичне призначення вибухівки?",a="Вибухівку НҐ-5 закладають на робочих ділянках Венчурної Компанії, щоб гучно й люто відвернути увагу. Вибухи — не сама мета: вони мають відтягти охорону, щоб агент непомітно проник на лісопилку й у шахту.",al={"навіщо вибухівка","для чого вибухівка нґ-5","підрив альфа бета"}},{q="Які відомості має здобути ця операція?",a="Мета — інженерні креслення Венчурної Компанії з лісопилки на південь від Озера Скельної Заводі, а потім листи керівництва, що зберігаються в Шахті Зрізаного Вітру на східному краю кручі.",al={"що ми крадемо","мета місії з ранцем","цілі таємних операцій"}},{q="Кому користь від того, що здобуто з цим ранцем?",a="І Вартовим нічних ельфів, що стережуть Кам'яний Кіготь, і інженерам Альянсу. Вартові бачать, що вирубку лісу підірвано, а майстри Альянсу вивчають захоплені креслення, щоб знайти вади в шредерах Венчурної Компанії й запозичити ідеї для власної техніки.",al={"кому потрібні плани венчур","для кого ранець","таємні операції вартових"}}},fp="15,339,18.584.0,25.515.0,35.202.0,47.250.0,45.191.0,58.280.0"}
P.entries["item:crate-of-crash-helmets"] = {n="Ящик із Захисними Шоломами",s="Важка партія шоломів для екіпажів дворфійських облогових машин, що прямує до Мерехтливих Низин у Тисячі Голок. Міцні шоломи терміново потрібні братам Брассболтс, щоб уберегти випробувачів від струсу мозку, якого ті зазнають у їхніх експериментальних ракетних автомобілях.",h="Важка партія шоломів для екіпажів дворфійських облогових машин, що прямує до Мерехтливих Низин у Тисячі Голок.",kw={"ящик із захисними шоломами","шоломи","брати брассболтс","мерехтливі низини","перегони міражу","ракетні автомобілі"},ang={["profession:Engineering"]="Кожен інженер розуміє, як тонко балансує максимальна тяга на межі катастрофічної відмови — і як конче потрібна важка броня, коли про безпеку думають в останню чергу.",["race:Gnome"]="Для гномів на Перегонах Міражу струс мозку в пілота — просто ціна, яку платиш, коли хочеш перевершити суперників-гоблінів на солончаках."},sec={{t="Безпека на шаленій швидкості",b="На сліпучо-білих просторах Мерехтливих Низин гноми-інженери випробовують межі механічної тяги. На біду пілотів-випробувачів, експериментальні ракетні автомобілі братів Брассболтс мчать куди швидше, ніж здатне надійно впоратися їхнє кермування. Водії раз у раз потрапляють у страшні аварії й травмують голови, тож звичайні шкіряні шапки вже не рятують. Щоб охочі ризикувати сміливці не перевелися зовсім, надміцні шоломи від дворфійських облогових машин пакують і відправляють за море — аби водії лишалися при тямі й живими."}},faq={{q="Що в Ящику із Захисними Шоломами?",a="У ящику — важкі шоломи для облогових машин із дворфських військових запасів. Вони створені, щоб витримувати вибухові хвилі й жорсткі удари машин, і дають найтовщий захист голови, який тільки можна знайти для швидкісних випробувань.",al={"вміст ящика","які це шоломи","тип захисних шоломів"}},{q="Кому потрібні ці шоломи?",a="Їх надсилають Віззлу Брассболтсу та його братові на Перегони Міражу в Мерехтливих Низинах. Їхні безрозсудні машини раз у раз вибивають дух із пілотів-випробувачів, тож серйозний захист голови їм конче потрібен.",al={"кому дістануться шоломи","для кого ящик","куди шоломи"}},{q="Чому брати Брассболтс так часто розбиваються?",a="Гномські конструктори машин ставлять швидкість і технічні рекорди вище за керованість. Брати збудували надзвичайно швидку ракетну машину, але на такій швидкості зіткнення на соляних рівнинах майже неминучі.",al={"чому вони розбиваються","проблеми ракетних авто","аварії гномів-гонщиків"}},{q="Куди доставляють шоломи?",a="Вантаж треба доправити в Мерехтливі Низини — велику соляну рівнину на південному сході Тисячі Голок у Калімдорі.",al={"місце доставки","де візл","куди це нести"}}},fp="22,262,21.584.0,42.227.0,24.218.0,49.232.0,38.147.0"}
P.entries["item:crate-of-horseshoes"] = {n="Ящик Підків",s="Ящик Підків — важкий пакунок із п'ятдесятьма залізними підковами, викуваними в Лісі Елвінн. Призначений для Лейкширу, він утілює життєво важливий торговий зв'язок між кузнею Ґолдширу й обложеними поселенцями Редріджу.",h="Ящик Підків — важкий пакунок із п'ятдесятьма залізними підковами, викуваними в Лісі Елвінн.",kw={"ящик підків","коваль арґус","вернер осґуд","лейкшир","ґолдшир","ковальство"},ang={["faction:Alliance"]="Гінці, що возять товари між Елвінном і Редріджем, підтримують крихкий торговий хребет королівства, тримаючи віддалені гарнізони спорядженими навіть тоді, коли Стормвінд не шле військового підкріплення.",["profession:Blacksmithing"]="Ця доставка показує сталий попит на ковальські основи оптом уздовж прикордонних доріг королівства, де такі містечка, як Лейкшир, цілком залежать від ковадла Ґолдширу, щоб підтримувати своїх тяглових тварин."},sec={{t="Доставка в Лейкшир",b="Спакований і забитий цвяхами ковалем Арґусом у Ґолдширі, цей важкий ящик містить п'ятдесят щойно викуваних підків на замовлення Вернера Осґуда. Місцеве ремесло Лейкширу знемагає під постійним тиском гнолів і орків з околиць, тож майстри на кшталт Вернера залежать від Лісу Елвінн у постачанні важливих металевих виробів. Ящик задовольняє нагальну потребу Вернера в спорядженні, та Арґус не забуває вкласти суворий рахунок, щоб редріджський майстер пам'ятав: навіть виживання на рубежі має свою високу ціну."}},faq={{q="Що в Ящику Підків?",a="У ящику — п'ятдесят залізних підків, викуваних Ковалем Арґусом у Ґолдширі, а до них прикріплено рахунок, який має оплатити покупець.",al={"вміст ящика","що в ящику","вміст ящика підків"}},{q="Хто замовив цей ящик?",a="Вернер Осґуд, ремісник із Лейкширу в Горах Редріджу, замовив підкови, щоб його справа йшла, а місцеві тяглові тварини не простоювали.",al={"хто хоче підкови","підкови вернера","одержувач ящика"}},{q="Хто викував ці підкови?",a="Коваль Арґус, місцевий коваль Ґолдшира в Лісі Елвінн, викував підкови й спакував ящик для доставки.",al={"хто викував підкови","коваль у ґолдширі","коваль арґус"}},{q="Чому Вернерові потрібні підкови з Лісу Елвінн?",a="Лейкшир обложили ворожі орки Блекрок і гноли, тож прикордонне поселення відрізане від світу й потерпає від нестачі сировини й товарів. Місцевим ремісникам доводиться завозити найпростіше з безпечніших поселень, як-от Ґолдшир.",al={"чому редрідж потребує підков","навіщо возити підкови","проблема з припасами лейкшира"}}},fp="19,232,23.543.0,39.138.0,23.172.0,29.125.0,44.228.0"}
P.entries["item:crate-of-inn-supplies"] = {n="Ящик із Припасами для Корчми",s="Ящик із Припасами для Корчми — пакунок, зібраний у Долині Холодного Хребта для Ґуральні Тандербрю в Хараносі. Гірський перевал захопили троги, звичні шляхи постачання перерізано, і корчма залежить від випадкових подорожніх, які зголосяться пронести крам.",h="Ящик із Припасами для Корчми — пакунок, зібраний у Долині Холодного Хребта для Ґуральні Тандербрю в Хараносі.",kw={"ящик","припаси","корчма","гендс спрінґспрокет","таннок фростгаммер","харанос","троги","перевал холодного кряжа"},ang={["race:Dwarf"]="Пронести ці припаси — перша служба молодого дворфа за межами Долини Холодного Хребта: кинути виклик забитому трогами перевалу, щоб допомогти родичам у Хараносі.",["race:Gnome"]="Для новоприбулих гномів доправити пакунок Гендса Спрінґспрокета — практичний спосіб здобути прихильність місцевих дворфів, що тримають корчми Дун Мороґу."},sec={{t="Крізь перевал трогів",b="Зазвичай крам вільно плине між тихими навчальними угіддями Анвілмара та людними містечками Дун Мороґу. Та недавні набіги трогів перерізали Перевал Холодного Кряжа, і цивільним кур'єрам шлях закрито, доки озброєні горяни не розчистять дороги. Цей важкий ящик, спакований Гендсом Спрінґспрокетом, містить необхідні корчемні припаси, яких Таннок Фростгаммер у Хараносі тривожно чекає посеред цього безладу."}},faq={{q="Що в ящику?",a="У ящику — звичайні припаси для таверни, відправлені з Долини Холодного Хребта, щоб корчма в Хараносі мала все потрібне для мандрівників і місцевих, які шукають тепла.",al={"вміст ящика","вміст припасів для корчми","що в коробці"}},{q="Хто надсилає ящик до Хараноса?",a="Гендс Спрінґспрокет біля Анвілмара пакує ящик і просить шукачів пригод, що вирушають із Долини Холодного Хребта, перенести його через гірський перевал.",al={"хто дає ящик","хендс спрінґспрокет","відправник"}},{q="Чому звичайний кур'єр не зміг його доставити?",a="Троги заполонили Перевал Холодного Кряжа, і без повного ескорту горян звичайним кур'єрам туди зась. Лише шукачі пригод, здатні пробитися з боєм, — єдина надія корчми швидко отримати товар.",al={"чому хендс не може доставити","прохід перекритий","чому шукають шукача пригод"}},{q="Хто отримує припаси?",a="Пакунок приймає Таннок Фростгаммер, помічник корчмаря в Ґуральні Тандербрю в Хараносі.",al={"хто отримує ящик","таннок фростгаммер","корчмар хараноса"}}},fp="21,261,22.431.0,25.157.0,32.156.0,43.232.0,26.118.0"}
P.entries["item:crate-of-lightforge-ingots"] = {n="Ящик зі Зливками Лайтфорджу",s="Ящик зі Зливками Лайтфорджу містить рідкісний освячений метал, з якого мають викувати зброю, здатну здолати некроманта Морбента Фела. Надійно запакований для перевезення, він прямує до ковадел Дворфійського Кварталу в Стормвінді.",h="Ящик зі Зливками Лайтфорджу містить рідкісний освячений метал, з якого мають викувати зброю, здатну здолати...",kw={"ящик зі зливками лайтфорджу","залізо лайтфорджу","ґріманд елмор","морбент фел","дворфійський квартал","сутінколісся"},ang={["class:Paladin"]="Ці зливки надзвичайно сприйнятливі до Святого Світла, тож викувана з них зброя — природна згуба для некромантів і їхніх прислужників-нежиті.",["profession:Blacksmithing"]="Робота із загартованим Світлом залізом — рідкісне мистецтво: навіть досвідчені зброярі на кшталт Ґріманда Елмора роками не тримають у руках такого дзвінкого святого металу."},sec={{t="Священна доставка",b="Загартоване Світлом залізо — надзвичайно рідкісний матеріал, від природи здатний спрямовувати святу силу проти темних створінь. Надійно запаковані в цьому ящику, зливки — надія Сутінколісся в запеклій боротьбі з некромантом Морбентом Фелом, чий тіньовий захист відштовхує звичайну сталь. Звичайні ковалі не можуть просто так узятися за цей метал: тут потрібен майстер, який розуміє його гарт і шанує його священну природу."},{t="Зброяр Стормвінда",b="Ящик призначений для Ґріманда Елмора — вправного дворфійського зброяра, що працює в Дворфійському Кварталі Стормвінда. Хоч Ґріманд уже багато років не працював із загартованим Світлом залізом, він погоджується викувати з нього освячену зброю — таку, що матиме силу зламати захист Морбента Фела й повалити його."}},faq={{q="Що в цьому ящику?",a="У ящику — зливки лайтфорджського заліза, особливого освяченого металу, зібраного, щоб викувати зброю, яка проб'є магічний захист некроманта Морбента Фела.",al={"вміст ящика","що таке лайтфорджське залізо","що в коробці"}},{q="Хто має отримати цей ящик?",a="Ящик треба віднести Ґріманду Елмору — досвідченому дворфові-ковалеві біля ковадел у Дворфійському Кварталі Стормвінда.",al={"кому віднести ящик","одержувач ящика","куди ящик"}},{q="Навіщо потрібне лайтфорджське залізо?",a="Некромант Морбент Фел захищається мерзенною нечестивою магією, від якої відскакують звичайні клинки. Лайтфорджське залізо має священні властивості, що пробивають темне чаклунство.",al={"чому лайтфорджське залізо","чому не звичайне залізо","слабкість морбента до скверни"}},{q="Хто спакував ящик?",a="Ґлорін Стілброу склав у ящик лайтфорджське залізо, яке ви здобули, щоб ви могли доставити його майстрові-зброяреві Ґріманду Елмору в Стормвінді.",al={"хто спакував зливки","хто дав ящик"}}},fp="26,244,17.434.0,28.328.1,26.182.0,38.129.0,30.177.0,22.151.0"}
P.entries["item:crate-with-holes"] = {n="Ящик з Дірками",s="Переносний ящик для перевезення, який дає гоблін-підприємець Мебок Міззірікс у Раджеті. Пробитий отворами для повітря, він безпечно вміщує навченого Ховраха-нюхоноса, з чиєю допомогою шукають підземні делікатеси у твердині шипогривів — Рейзорфен Краулі.",h="Переносний ящик для перевезення, який дає гоблін-підприємець Мебок Міззірікс у Раджеті.",kw={"ящик з дірками","мебок міззірікс","ховрах-нюхоніс","рейзорфен краул","раджет","синьолиста бульба"},sec={{t="Нюхач у ящику",b="Щоб здобути рідкісні Синьолисті бульби з колючих глибин Рейзорфен Краулу, гоблінський торговець Мебок Міззірікс покладається на навчених Ховрахів-нюхоносів, а не на сліпе копання. Ховрахи не можуть просто дріботіти за шукачем пригод курними стежками Пусток, тож Мебок пакує кожну тваринку в добре провітрюваний дерев'яний ящик. Коли ящик приносять у вологі, зарослі корінням переходи лігва шипогривів, його відкривають, і звірятко, довіряючись гострому нюхові, веде до закопаних бульб."}},faq={{q="Що в Ящику з Дірками?",a="У ящику — живий Ховрах-нюхоніс, якого видресирував Мебок Міззірікс. Дірки, просвердлені в дошках, дають тваринці дихати під час подорожі через Пустки.",al={"що в коробці","вміст ящика","що всередині"}},{q="Де взяти Ящик з Дірками?",a="Ящик можна взяти просто з купи біля Мебока Міззірікса в портовому містечку Раджет на східному узбережжі Пусток.",al={"місце ящика","де знайти ящик з дірками","ящик мебока"}},{q="Як ящик працює в Рейзорфен Краул?",a="Якщо відкрити ящик у Рейзорфен Краул, з нього вибіжить Ховрах-нюхоніс. Коли ним керують за допомогою Командного Жезла Нюхоноса, ховрах гострим нюхом знаходить Синьолисті Бульби, заховані під землею.",al={"як використати ящик з дірками","використання ящика","викликати ховраха"}},{q="Чому без ховраха так важко знайти Синьолисті Бульби?",a="Синьолисті Бульби ростуть глибоко під землею серед коріння Рейзорфен Краул. Звичайним оком їх не побачити, а Ховрахи-нюхоноси чують їх за п'ятдесят кроків.",al={"чому потрібен ховрах","пошук бульб","місце бульб"}}},fp="16,265,18.509.0,36.170.0,36.153.0,46.216.0,59.181.0"}
P.entries["item:crawler-leg"] = {n="Нога Повзуна",s="Нога Повзуна — кінцівка, відірвана в одного з крабів, що нишпорять оповитими туманом берегами Темного Узбережжя. Для більшості мандрівників вона нічого не варта, але ці міцні хітинові кінцівки напрочуд добре годяться для механічних імпровізацій.",h="Нога Повзуна — кінцівка, відірвана в одного з крабів, що нишпорять оповитими туманом берегами Темного...",kw={"нога повзуна","візбанґ кранктоґґл","дзижчалка","краби","обердайн","темне узбережжя"},ang={["profession:Engineering"]="Рішення Візбанґа Кранктоґґла взяти крабові кінцівки за саморобні механічні важелі — класична гномська польова імпровізація: замість звичних металевих тяг — те, що є під рукою.",["race:Gnome"]="Лише гном міг подивитися на пляж, що кишить агресивними ракоподібними, і вирішити, що їхні відірвані ноги — ідеальні запчастини для делікатної мережі далекого зв'язку."},sec={{t="Гномська винахідливість на березі",b="Краби Темного Узбережжя — від карликових припливних повзунів до більших рифових — славляться міцними, тривкими панцирами. Вартові нічних ельфів не звертають уваги на відкинуті кінцівки прибережної наволочі, але ексцентричний гном-інженер Візбанґ Кранктоґґл знайшов їм несподіване застосування. Працюючи в Обердайні, Візбанґ сконструював свої дослідні пристрої для зв'язку на великі відстані — дзижчалки — так, щоб вони працювали на саморобних місцевих деталях. Членисті суглоби й тривкий хітин ніг повзунів дають саме те механічне тертя й ті важелі, які потрібні, щоб полагодити Дзижчалку 827, що стоїть на березі трохи на південь від міста."}},faq={{q="Для чого потрібні ноги повзунів?",a="Ноги повзунів збирають, щоб полагодити Дзижчальну Скриньку 827 — експериментальну станцію зв'язку, яку гном-винахідник Візбанґ Кранктоґґл поставив на березі Темного Узбережжя, трохи на південь від Обердайна.",al={"призначення ноги повзуна","навіщо зберігати ноги повзунів","нога повзуна для скриньки"}},{q="Звідки беруться ноги повзунів?",a="Їх можна зібрати з різних крабів на пляжах Темного Узбережжя — карликових припливних повзунів, молодих рифових повзунів, обліплених припливних повзунів і рифових повзунів.",al={"джерело ніг повзунів","які краби дропають ноги","де знайти ногу повзуна"}},{q="Навіщо механічній скриньці крабові ноги?",a="Візбанґ Кранктоґґл навмисно сконструював свої машини так, щоб їх можна було лагодити в полі деталями з місцевих тварин. Тверді суглоби й хітинові членики ніг повзунів просто вставляються між шестерні скриньки й відновлюють її внутрішні механізми.",al={"чому краби для машини","ноги крабів у скриньці","як нога повзуна лагодить скриньку"}}},fp="11,231,30.641.0,31.191.0,32.179.0,45.270.0"}
P.entries["item:creeper-ichor"] = {n="Іхор Повзуна",s="Іхор Повзуна — рідкісна заразна рідина, яку добувають із мохових повзунів, що чатують у лісах Передгір'я Гілсбреда. Його шукає Королівське Аптекарське Товариство в Таррен Міллі як потужний біологічний засіб для нових чум проти живих.",h="Іхор Повзуна — рідкісна заразна рідина, яку добувають із мохових повзунів, що чатують у лісах Передгір'я...",kw={"іхор повзуна","мохові повзуни","таррен мілл","аптекар лайдон","еліксир страждання","передгір'я гілсбреда"},ang={["race:Undead"]="Для вірних Відступників кожна здобута смертоносна складова на кшталт Іхору Повзуна безпосередньо просуває похід Королівського Аптекарського Товариства, що прагне вичистити живих із Лордерону."},sec={{t="Аптекарські дослідження в Гілсбреді",b="У Таррен Міллі Аптекар Лайдон ставить досліди, щоб створити нові смертоносні отрути й винищити навколишніх людей. Зневажаючи чисте повітря й буйне життя передгір'я, Лайдон шукає природні отрути й біологічні каталізатори серед місцевої живності. Отруйні рідини велетенських лісових павуків, а надто невловимий іхор дорослих мохових повзунів, — ідеальна основа для його Еліксиру Страждання. Змішана з іншими складниками, як-от язиками сірих ведмедів, ця рідина допомагає Відступникам удосконалювати своє мистецтво смертоносної алхімії."}},faq={{q="З яких істот добувають Іхор Повзуна?",a="Цю рідину збирають із мохових повзунів Передгір'я Гілсбреда — велетенських, лісових і старших мохових повзунів, а також із відомого павука на ім'я Крипотес.",al={"де взяти іхор повзуна","хто дропає іхор повзуна","істоти з іхором повзуна"}},{q="Навіщо Аптекареві Лайдону ця рідина?",a="Аптекар Лайдон використовує Іхор Повзуна як важливий смертоносний складник у своїх алхімічних дослідах — він варить Еліксир Страждання, що має вразити й винищити живих людей у Гілсбреді.",al={"чому лайдон хоче іхор","призначення еліксиру страждання","для чого іхор повзуна"}},{q="Чому Іхор Повзуна так важко знайти?",a="Мохові повзуни трапляються в лісах довкола Таррен Мілла на кожному кроці, але придатні запаси саме цього отруйного іхору в них рідкісні, тож мисливцям доводиться вбити чимало павуків, перш ніж знайдеться годящий зразок.",al={"чому рідкісний","шанс дропу іхору повзуна"}}},fp="13,270,32.579.0,35.188.0,42.195.0,42.220.0"}
P.entries["item:crocolisk-skin-classic"] = {n="Шкура Кроколіска (класична)",s="Шкури кроколісків знімають із цупких тіл кроколісків, що живуть на острівцях і у водах великого озера Лох Модану. Купці й шкірники цінують їх за міцність, тож вони мають непогану ціну, попри небезпеку, з якою їх добувають.",h="Шкури кроколісків знімають із цупких тіл кроколісків, що живуть на острівцях і у водах великого озера Лох...",kw={"шкура кроколіска","кроколіск","лох модан","хутір далекоходів","шкірництво","полювання"},ang={["class:Hunter"]="На Хуторі Далекоходів поважають кожного слідопита, що наважиться перебрести до острівців і здолати кроколіска, який шалено борсається, — заради його шкури.",["race:Dwarf"]="Славетні кроколіски Лох Модану — відоме місцеве випробування витримки для горян і лісовиків із хутора."},sec={{t="Небезпечне ремесло",b="Холодні води озера кишать агресивними кроколісками, що влаштовують лігва на острівцях і берегах. Полювати на них непросто: ці люті звірі мають гострі як бритва зуби й товсту, міцну луску, від якої відскакують необачні клинки. Попри небезпеку, мисливці з Хутора Далекоходів часто вполювують цих тварин. Кравці, шкірники й купці з далеких країв постійно шукають ці шкури, щоб шити міцний одяг і захисні обладунки, тож в'язка цілих шкур — цінний товар у цьому краї."}},faq={{q="Звідки беруться шкури кроколісків?",a="Їх збирають з озерних кроколісків і великих озерних кроколісків, що живуть у водах і на островах озера в Лох Модані.",al={"де взяти шкури кроколісків","джерело шкур з озера","хто дропає шкуру кроколіска"}},{q="Хто купує ці шкури в Лох Модані?",a="Марек Айронгарт, досвідчений дворф-мисливець із Хутора Далекоходів, збирає їх разом із м'ясом кроколісків, щоб продавати заїжджим торговцям і ремісникам.",al={"хто купує шкури кроколісків","шкури кроколісків у мисливській ложі","шкури мареку айронгарта"}},{q="Чому ці шкури в попиті?",a="Торговці цінують цупкі лускаті шкури для міцного одягу й обладунків. А що звірі люті й убити їх нелегко, за добрі шкури завжди добре платять.",al={"для чого шкури кроколісків","використання шкіри кроколіска","чому полювати на кроколісків"}},{q="Чи небезпечно полювати на кроколісків в озері?",a="Так. Кроколіски славляться своєю агресивністю, а їхні потужні щелепи й зазублені зуби можуть відірвати кінцівку. Місцеві мисливці, як-от Марек Айронгарт, часто обмінюються історіями про те, як ледве не загинули, вистежуючи здобич.",al={"чи небезпечні кроколіски озера","небезпека полювання на кроколісків"}}},fp="24,267,17.570.0,35.131.0,45.165.0,30.172.0,55.235.0"}
P.entries["item:crocolisk-tear-classic"] = {n="Сльоза Кроколіска (класика)",s="Сльоза Кроколіска — цікавий алхімічний реагент, який здобувають у кроколісків із вод Лох Модану. Її шукає Головний Інженер Гіндервір, щоб виготовити знешкоджувальну суміш, здатну обеззброїти вибухівку Темного Заліза.",h="Сльоза Кроколіска — цікавий алхімічний реагент, який здобувають у кроколісків із вод Лох Модану.",kw={"сльоза кроколіска","кроколіски","лох модан","гіндервір","каменетесна гребля","темне залізо"},ang={["profession:Engineering"]="Дворфійські інженери на кшталт Головного Інженера Гіндервіра нерідко вдаються до незвичних алхімічних сумішей, щоб знешкодити складну вибухівку там, де звичайні інструменти безсилі."},sec={{t="Цікавий складник",b="Озерні кроколіски — витривалі плазуни, що живуть у помірних водах Лох Модану. Мисливці здавна цінують їхні шкури й м'ясо, а Головний Інженер Гіндервір відкрив у їхніх виділеннях несподівану користь. У поєднанні з сильною павучою отрутою й резонансними огрячими мінералами сльоза кроколіска має саме ті хімічні властивості, що потрібні, аби нейтралізувати небезпечні підривні заряди Темного Заліза, які загрожують Каменетесній Греблі."}},faq={{q="Для чого потрібна Сльоза Кроколіска?",a="Головному Інженерові Гіндервіру з Каменетесної Греблі потрібна Сльоза Кроколіска, щоб скласти хімічну суміш для знешкодження вибухівки, закладеної диверсантами Темного Заліза.",al={"призначення сльози кроколіска","навіщо мені сльоза кроколіска","кому потрібні сльози кроколіска"}},{q="Де збирати Сльози Кроколіска?",a="Їх добувають з озерних кроколісків і великих озерних кроколісків, що живуть у водах і на мілинах озера в Лох Модані.",al={"де падають сльози кроколіска","місце сльози кроколіска","як здобути сльози кроколіска"}},{q="Які ще матеріали додають до сльози?",a="Гіндервір поєднує сльозу з Отрутою Причаєної, добутою з місцевих лісових павуків, і з Кристалом Мо'ґрош, забраним в огрів із північно-східних пагорбів, — так виходить засіб для знешкодження.",al={"інгредієнти гіндервейра","матеріали для знешкодження","що ще потрібно до сльози кроколіска"}}},fp="24,236,19.429.0,34.166.0,38.129.0,48.181.0"}
P.entries["item:crossroads-supply-crate"] = {n="Скриня з Припасами для Перехрестя",s="Скрині з припасами для Перехрестя містять важливу провізію для поселення Перехрестя в Пустках. Після того як на караван напали на посушливих дорогах, ці викрадені товари опинилися розкиданими по таборах місцевих шипогривів-Гостроманів.",h="Скрині з припасами для Перехрестя містять важливу провізію для поселення Перехрестя в Пустках.",kw={"скриня з припасами","перехрестя","гостромани","шипогриви","торк","пустки"},ang={["faction:Horde"]="Перехрестя — головний вузол, що поєднує Дуротар, Малгор і північні дикі землі; убезпечуючи його припаси, ви безпосередньо захищаєте подорожі й постачання Орди по всьому Калімдору."},sec={{t="Пограбована провізія",b="Поселення Перехрестя — живе серце мандрівок Орди центральним Калімдором, але забезпечувати його припасами через посушливі пустища — постійне випробування. На караванних шляхах Пусток безупинно чатують місцеві шипогриви-Гостромани. Під час однієї такої засідки важливий вантаж для поселення пограбували. Скрині затягли в колючі чагарники та земляні лігва довколишніх таборів шипогривів, і комендант поселення, Торк, наймає мандрівників, щоб повернути їх, поки на заставі не забракло харчів, знарядь і всього потрібного."}},faq={{q="Що це за скрині з припасами?",a="Це вантажі їжі, інструментів і найпотрібніших припасів для поселення Орди на Перехресті. Їх пограбували з каравану, на який напали на дорогах Пусток.",al={"припаси перехрестя","що в скринях","про скрині з припасами"}},{q="Хто вкрав скрині з припасами?",a="На караван напали шипогриви Гостроманів і потягли скрині до своїх колючих таборів неподалік, щоб бенкетувати й ховати здобич.",al={"хто взяв скрині","хто пограбував караван","злодії квілборги"}},{q="Хто шукає ці скрині?",a="Торк, орк-офіцер із Перехрестя, хоче повернути вкрадені скрині, щоб гарнізон і місцеві мешканці мали все потрібне.",al={"хто хоче скрині","здати скрині з припасами","припаси торка"}},{q="Де знайти скрині?",a="Вони розкидані на землі в різних таборах шипогривів Гостроманів по всіх навколишніх землях Пусток.",al={"місця скринь","де знайти скрині з припасами","місця скринь перехрестя"}}},fp="23,236,20.603.0,29.196.0,28.137.0,32.159.0,29.141.0"}
P.entries["item:crude-flint"] = {n="Грубий Кремінь",s="Грубий кремінь — шорсткі камені для розпалювання вогню, які носять гноли-Мохошкірі по всьому Багнокраю. Гноли розпалюють ними багаття зі свіжозрубаного болотяного дерева, і це до глибини душі обурює місцевого захисника — Ретіеля Зеленовартового.",h="Грубий кремінь — шорсткі камені для розпалювання вогню, які носять гноли-Мохошкірі по всьому Багнокраю.",kw={"грубий кремінь","ретіель зеленовартовий","мохошкірі","гноли","багнокрай","кресала"},ang={["class:Druid"]="Нищення живих рослин лише заради зручності гнолів прямо ображає закони природи, тож відбирати й трощити ці кресала — природний обов'язок для кожного охоронця дикої природи."},sec={{t="Розпалка серед трясовини",b="Хоч ці прості кресала грубі й необроблені, саме ними гноли-Мохошкірі добувають тепло й смажать м'ясо серед вогких боліт Багнокраю. На біду для болотяної природи, Мохошкірі рубають живі дерева, щоб годувати свої вогнища й ватри. Таке безрозсудне вирубування й спалювання живого гілля накликало гнів Ретіеля Зеленовартового, для якого кожна висічена іскра — напад на природну рівновагу."},{t="Відплата Зеленовартового",b="Сповнений рішучості спинити нищення болотяних дерев, Ретіель доручає мандрівним шукачам пригод одне за одним відбирати в зграї Мохошкірих їхні кремені. Охоронець не збирається використовувати здобуте каміння — він розтовче кожен уламок на порох і викине рештки в море, щоб гноли більше не могли палити живе дерево Багнокраю."}},faq={{q="Для чого потрібен Грубий Кремінь?",a="Мохошкірі гноли користуються грубими кременями як примітивними кресалами, щоб розпалювати вогонь для тепла й готування. Мандрівники ж збирають їх для Ретіеля Зеленовартового, щоб гноли перестали підпалювати живі дерева.",al={"використання грубого кременя","що робить грубий кремінь","призначення грубого кременя"}},{q="Які істоти носять Грубий Кремінь?",a="Їх носить більшість дорослих і вправних членів племені мохошкірих гнолів — громили, ловці, болотяні бігуни, ткачі туману, містики, ватажки-альфи й Кістогриз. Менші мохошкірі гноли й дворняги їх не мають.",al={"хто дропає грубий кремінь","де взяти грубий кремінь","які гноли мають кремінь"}},{q="Чому Ретіель хоче знищити кремені?",a="Ретіеля жахає, що гноли рубають живі дерева в болотах і палять їхню деревину, щоб грітися. Знищивши кремені й викинувши уламки в океан, він сподівається назавжди позбавити гнолів змоги розпалювати руйнівні вогнища.",al={"чому знищити кремінь","причина ретіель","табу на вогонь"}},{q="Чи цінні ці кремені для ремесла?",a="Ні. Хоч це й мінерал, але звичайне грубе каміння, придатне лише висікати іскру: ні чистоти, ні форми, яких потребують ковалі чи інженери, у ньому немає.",al={"чи можна кремінь у ковальстві","чи кремінь матеріал для ремесла"}}},fp="11,247,20.466.0,29.363.0,29.223.0,34.227.0,43.258.0,39.155.0"}
P.entries["item:crystal-kelp-frond"] = {n="Лист Кристалевої Ламінарії",s="Листи Кристалевої Ламінарії — зрізки водяної рослини, здобуті в мурлоків, що живуть на Кришталевому Озері в Лісі Елвінн. Хоч ламінарія родом з океану, мурлоки носять її листя вглиб суходолу, і так воно стає незвичним алхімічним реагентом, за яким полює Вільям Пестл у Ґолдширі.",h="Листи Кристалевої Ламінарії — зрізки водяної рослини, здобуті в мурлоків, що живуть на Кришталевому Озері в...",kw={"кристалева ламінарія","мурлоки","кришталеве озеро","вільям пестл","алхімія","реагент"},ang={["profession:Herbalism"]="На відміну від звичайних трав, що ростуть у землі, кристалева ламінарія — водяна рослина, якої не знайти у звичних місцях збору трав по Елвінну; травникам і збирачам доводиться відбирати її просто в тутешніх мурлоків, які її нагромаджують."},sec={{t="Рідкісний водяний реагент",b="Кристалева ламінарія зазвичай росте в глибинах солоних океанів, тож її поява в прісних водоймах Лісу Елвінн несподівана. Племена мурлоків, що оселилися на берегах Кришталевого Озера, збирають і зберігають це листя з власних міркувань. Алхіміки цінують листя за дивну здатність спотворювати зір, а Вільям Пестл у Ґолдширі використовує його як головний інгредієнт лікеру невидимості, створеного, щоб допомогти таємним закоханим прослизнути повз пильні очі родини."}},faq={{q="Де природно росте кристалева ламінарія?",a="Кристалева ламінарія — морська рослина, що зазвичай росте в солоних морях. У прісних озерах углибині суходолу вона не водиться, але племена мурлоків збирають її паростки й приносять у прісні води, як-от у Кришталеве Озеро.",al={"де росте кристалева ламінарія","походження кристалевої ламінарії","середовище ламінарії"}},{q="Звідки в мурлоків Кришталевого Озера морська ламінарія?",a="Мурлоки тісно пов'язані з узбережжям і кочують між водоймами. Вони збирають ламінарію в прибережних водах і несуть її з собою до таборів біля озер і струмків углибині суходолу.",al={"чому мурлоки мають ламінарію","причина ламінарії у мурлоків"}},{q="Кому в Ґолдширі потрібні Листи Кристалевої Ламінарії?",a="Ламінарія потрібна Вільямові Пестлу — аптекареві, що працює в Корчмі «Лев'яча Гордість» у Ґолдширі. Він варить із неї особливий Лікер Невидимості для Мейбелл Маклур, щоб вона могла непомітно вислизнути з родинного виноградника на побачення з Томмі Джо Стоунфілдом.",al={"хто потребує кристалеву ламінарію","ламінарія вільяма пестла"}},{q="Які властивості має кристалева ламінарія?",a="Якщо алхімік як слід її обробить, незвичайні якості кристалевої ламінарії дають сильні суміші для маскування — зокрема Лікер Невидимості, що на якийсь час ховає того, хто його випив, від чужих очей.",al={"ефекти ламінарії","що робить кристалева ламінарія"}}},fp="18,258,22.511.0,39.209.0,51.183.0,43.241.1,42.204.0"}
P.entries["item:crystal-phial"] = {n="Кристалева Фіала",s="Бездоганна Кристалева Фіала, яку друїд Тенарон Стормґріп у Тінедолі довіряє молодим нічним ельфам — шукачам пригод. Нею набирають священну воду з поблизького місячного колодязя, розпочинаючи низку обрядів на честь і для живлення зростаючого Світового Дерева — Тельдрассила.",h="Бездоганна Кристалева Фіала, яку друїд Тенарон Стормґріп у Тінедолі довіряє молодим нічним ельфам — шукачам...",kw={"кристалева фіала","місячний колодязь","тенарон стормґріп","тінедол","алдрассил","тельдрассил","корона землі"},ang={["class:Druid"]="Друїди глибоко шанують місячні колодязі й черпають їхні безтурботні властивості, щоб спрямовувати природні сили й плекати нове зростання, не піддаючись спокусам таємного чаклунства.",["race:NightElf"]="Для молодих калдореїв, що роблять перші кроки за межами Алдрассила, наповнити цю фіалу — основоположний обряд посвяти, що прямо єднає їх із водами Елуни та відродженням народу після Третьої війни."},sec={{t="Посудина для священних вод",b="Ця тендітна скляна фіала, яку дають молодим нічним ельфам на верхівці Алдрассила, має важливе обрядове призначення. Тенарон Стормґріп доручає молодим захисникам віднести її до місячного колодязя одразу на північ від гілки й набрати його сяйливої води. Проста на вигляд, фіала містить воду, наснажену священним спадком Колодязя Вічності. Принесена назад Наповнена Кришталева Фіала — перший крок паломництва Корони Землі, що вчить молодих калдореїв хисткої рівноваги магії, історії та природи на їхньому новому острівному домі."}},faq={{q="Для чого потрібна Кристалева Фіала?",a="Фіалою набирають благословенну воду з місячного колодязя трохи на північ від Алдрассила в Тінедолі. Наповнену фіалу повертають Тенаронові Стормґріпу в межах завдання «Корона Землі».",al={"призначення кристалевої фіали","використання кристалевої фіали","що робити з фіалою"}},{q="Хто дає Кристалеву Фіалу?",a="Порожню Кристалеву Фіалу дає друїд Тенарон Стормґріп, коли доручає молодим шукачам пригод їхні перші справи на великій гілці Алдрассила.",al={"хто дає кристалеву фіалу","де взяти кристалеву фіалу"}},{q="Чому так важливо набрати води з місячного колодязя?",a="Місячні колодязі містять освячену воду, пов'язану із сутністю Колодязя Вічності й ласкою Елуни. Вода у фіалі допомагає збагнути наслідки Третьої війни й узяти участь в обрядах, що живлять Тельдрассил.",al={"чому вода з місячного колодязя","значення води місячного колодязя","призначення місячного колодязя"}},{q="Що стається, коли фіалу наповнено?",a="Вона стає Наповненою Кришталевою Фіалою. Повернувши її Тенаронові Стормґріпу, ви завершуєте перше випробування й відкриваєте шлях до нових уроків про створення Світового Дерева й турботу про нього по всьому Тельдрассилу.",al={"після наповнення фіали","використання наповненої кристалевої фіали"}}},fp="13,258,26.540.0,35.200.0,32.147.0,44.252.0,39.194.0"}
P.entries["item:crystalized-scales"] = {n="Кристалізована Луска",s="Кристалізована Луска — затверділі, мінералізовані шкури василісків, що живуть у суворих краях Калімдору, як-от в Обвугленій Долині й Тисячі Голок. Розтерта на дрібний порошок, ця незвична луска стає екзотичним магічним реагентом, якого жадають чаклуни Стормвінда.",h="Кристалізована Луска — затверділі, мінералізовані шкури василісків, що живуть у суворих краях Калімдору...",kw={"кристалізована луска","василіски","коллін маурен","стормвінд","реагент","обвуглена долина","тисяча голок"},ang={["class:Mage"]="Для знавців чарівної магії ця луска показує, як вплив довкілля змінює магічну будову звірів і дає особливі реагенти для незвичних формул чарів.",["faction:Alliance"]="Здобуваючи цю луску, ви перекидаєте місток через величезну відстань між столицею Альянсу Стормвіндом і дикими нетрями Калімдору."},sec={{t="Рідкісний реагент Калімдору",b="Василіски, що витримують страшну спеку й попіл, — надто ті, що живуть в Обвугленій Долині в Горах Кам'яного Кігтя чи на мерехтливих солончаках Тисячі Голок, — обростають твердими шкурами, вкритими кристалами. Ця кристалізована луска має приховану чарівну співзвучність, тож украй цінна для вчених чарівників за Великим морем, які експериментують із рідкісними чарами."},{t="Чарівна робота Маурена",b="У людському королівстві Стормвінд маг Коллін Маурен шукає шукачів пригод, що вирушають на калімдорське порубіжжя, аби роздобути цю луску. Розтираючи кристалічні мінеральні шари на пил, Маурен використовує його як важливий реагент для щойно задуманих чарів і власних чарівних досліджень."}},faq={{q="З яких істот добувають кристалізовану луску?",a="Її знімають переважно з василісків, що пристосувалися до суворих країв: з обпалених, підсмалених і почорнілих василісків Обвугленої Долини в Кам'яному Кігті, а також із солекам'яних василісків у Тисячі Голок.",al={"звідки падає луска","хто дропає кристалізовану луску","джерело луски василісків"}},{q="Хто шукає цю луску в Стормвінді?",a="Коллін Маурен, чарівник зі Стормвінда, доручає мандрівникам, що вирушають до Кам'яного Кігтя, зібрати її для його магічних дослідів.",al={"хто хоче кристалізовану луску","луска колліна маурена","кому потрібна ця луска"}},{q="Як луску використовують у чарах?",a="За словами Колліна Маурена, кристалічна луска, розтерта на дрібний порошок, стає сильним реагентом, потрібним для особливих заклинань його власного винаходу.",al={"чому кристалізована луска магічна","луска як компонент заклять"}},{q="Чи кристалізовану луску можна знайти лише в Кам'яному Кігті?",a="Маурен просить саме тих, хто прямує до Обвугленої Долини в Кам'яному Кігті, але схожу кристалічну шкуру можна зняти й із солекам'яних василісків у Тисячі Голок.",al={"тисяча голок луска","інші місця для луски"}}},fp="18,292,23.382.0,20.324.0,40.215.0,41.142.0,40.161.0,51.185.0"}
P.entries["item:curative-animal-salve"] = {n="Цілюща Мазь для Тварин",s="Цілюща Мазь для Тварин — трав'яні ліки, які варять друїди-травники, щоб заспокоїти й вилікувати звірину, уражену пошестю, що шириться природою. Її готують і на Темному Узбережжі, і в Пустках, і вона стала першою допомогою для хворих тварин, що страждають від незримої порчі землі.",h="Цілюща Мазь для Тварин — трав'яні ліки, які варять друїди-травники, щоб заспокоїти й вилікувати звірину...",kw={"цілюща мазь для тварин","аланндаріан найтсонг","тонга рунтотем","коло кенарія","дендрит старблейз","друїди"},ang={["class:Druid"]="Лікування цими ліками — одне з перших випробувань на шляху до вміння вгамовувати отрути й хвороби: так ви доводите свою відданість місії Кола Кенарія по всьому Калімдору.",["race:Tauren"]="Застосовуючи мазь у Пустках, друїди-таурени показують, як втілюють науку Кенарія, діючи в злагоді з прадавніми обрядами кола, щоб зцілювати землю."},sec={{t="Лікування дикої природи",b="Цілющу Мазь для Тварин готують із місцевих трав'яних реагентів партіями по десять доз, щоб лікувати звірів, яких охопила порча. В імлистих лісах Темного Узбережжя Аланндаріан Найтсонг посилає молодих друїдів намащувати хворих оленів, що бродять між Річкою Скельного Джерела й межами Ашенвалю. Далеко на півдні, в посушливих просторах Пусток, Тонга Рунтотем варить такі самі ліки для хворих газелей, що пасуться на північ від Перехрестя. Обоє травників співпрацюють із місцевою владою, щоб виготовити більші запаси, а польові цілителі наносять мазь просто на звірів, яким дошкуляє недуга довкілля."},{t="Симптоми глибшої недуги",b="Мазь полегшує страждання тварини, але Коло Кенарія вважає ці хвороби лише симптомами значно більшого збурення. У Місячному Гаї Дендрит Старблейз зауважує, що ні хворі олені узбережжя, ні знесилені газелі савани не випадкові жертви. Вони — мимовільні жертви пошесті, що підступає до Калімдору з різних боків. Лікування маззю — основоположний обряд для новачків: він перевіряє їхню відданість охороні природи й навчає мистецтва очищення від отрути."}},faq={{q="Для чого потрібна Цілюща Мазь для Тварин?",a="Мазь наносять просто на хворих тварин, щоб вилікувати їхні недуги. Друїди лікують нею хворих оленів, що блукають Темним Узбережжям, або хворих газелей, що пасуться на північ від Перехрестя в Пустках.",al={"призначення цілющої мазі для тварин","як використати цілющу мазь","що робить мазь"}},{q="Хто готує мазь?",a="На Темному Узбережжі мазь готує Аланндаріан Найтсонг в Обердайні із зібраних реагентів. У Пустках це зілля для друїдів Орди варить Тонга Рунтотем на Перехресті.",al={"хто робить мазь","звідки мазь"}},{q="Чому олені й газелі взагалі хворіють?",a="За словами Дендрита Старблейза з Кола Кенарія, тварини стали жертвами дедалі більшої скверни, що шириться Калімдором. Вони — перші жертви моровиці, яка руйнує рівновагу природи.",al={"чому тварини хворіють","що труїть оленів темного узбережжя","хвороба газелей пустищ"}},{q="На скільки разів вистачає однієї порції?",a="Звичайної польової порції мазі вистачає на десять застосувань, а тоді трав'яна суміш закінчується.",al={"скільки зарядів","скільки разів можна використати мазь"}}},fp="21,285,17.678.0,28.582.0,39.205.0,23.181.0,54.210.0,36.128.0"}
P.entries["item:daffodil-bouquet"] = {n="Букет Нарцисів",s="Букет Нарцисів — свіжа в'язанка яскравих квітів, яку зібрала травниця Марті Джейнроуз у Лейкширі. Задуманий як романтичний знак вдячності від Вартового Паркера для Дарсі, цей подарунок мимоволі розпалює плітки й дріб'язкове суперництво.",h="Букет Нарцисів — свіжа в'язанка яскравих квітів, яку зібрала травниця Марті Джейнроуз у Лейкширі.",kw={"букет нарцисів","нарциси","марті джейнроуз","вартовий паркер","дарсі","лейкшир"},ang={["profession:Herbalism"]="Травники, що завітають до Лейкширу, упізнають у букеті руку колеги, травниці Марті Джейнроуз: навіть збирання польових квітів тут — частина буденної торгівлі."},sec={{t="Заплутаний знак уваги",b="Вартовий Паркер хоче віддячити Дарсі з корчми Лейкширу за те, що вона щодня збирає йому обід, і просить допомоги в міської травниці, Марті Джейнроуз. Марті складає букет нарцисів, зауваживши, що це її улюблені квіти. Та щойно букет потрапляє до Дарсі, яскраві квіти одразу викликають підозру: Дарсі впізнає улюблені квіти Марті, запідозрює суперницю в дріб'язкових ревнощах і напівжартома припускає, що Марті з досади могла отруїти стебла."}},faq={{q="Для чого потрібен Букет Нарцисів?",a="Букет призначено для Дарсі з корчми в Лейкширі. Вартовий Паркер просить доставити його їй як щиру подяку за обід, який вона готує й надсилає йому на пост.",al={"призначення букета нарцисів","що робити з букетом нарцисів","кому нарциси"}},{q="Хто склав цей букет?",a="Марті Джейнроуз, місцева травниця й квіткарка в Лейкширі, на прохання збирає й перев'язує букет. Нарциси вона обирає навмисно — бо це її улюблені квіти.",al={"хто склав букет","джерело букета нарцисів","звідки квіти"}},{q="Чому Дарсі з підозрою сприймає квіти?",a="Дарсі одразу впізнає в нарцисах улюблені квіти Марті, а не вибір, зроблений саме для неї. Називаючи Марті заздрісною суперницею, Дарсі жартома гадає, чи не отруєно букет зі злоби, — але подарунок таки приймає.",al={"чому дарсі сердиться","отруєні квіти дарсі","суперництво дарсі й марті"}},{q="Чи справді нарциси отруєні?",a="Ні. Підозри Дарсі — лише місцеві плітки й показні ревнощі між двома жінками з Лейкширу. Квіти цілком нешкідливі.",al={"чи букет отруєний","чи марті отруїла нарциси"}}},fp="16,247,15.516.0,38.182.0,26.184.0,49.268.1,36.135.1"}
P.entries["item:daggerspine-scale"] = {n="Луска Кинджалоспинного",s="Луска Кинджалоспинного — міцна плазуняча луска, яку здирають із наг племені Кинджалоспинних, що нишпорять південними берегами Передгір'я Гілсбреда. Королівське Аптекарське Товариство дуже цінує цю луску: вона — важливий каталізатор, що пробуджує отруйні суміші в чумних дослідах Відступників.",h="Луска Кинджалоспинного — міцна плазуняча луска, яку здирають із наг племені Кинджалоспинних, що нишпорять...",kw={"луска кинджалоспинного","наги","передгір'я гілсбреда","саутшор","еліксир агонії","королівське аптекарське товариство"},ang={["faction:Horde"]="Збирати луску на південному узбережжі треба обережно: табори Кинджалоспинних стоять небезпечно близько до порту Альянсу в Саутшорі.",["race:Undead"]="Здобуваючи цю луску, ви безпосередньо просуваєте дослідження Королівського Аптекарського Товариства, що створює нові нищівні чуми проти ворогів Відступників."},sec={{t="Дослідження аптекарів",b="Королівське Аптекарське Товариство постійно шукає біологічні реагенти, щоб посилити свої отрути, чуми й настоянки. Удосконалюючи дослідне вариво під назвою Еліксир Агонії, аптекарі виявили, що луска місцевих наг Кинджалоспинних має особливі реактивні властивості. Разом із тролячими еліксирами регенерації та органами мурлоків вона допомагає хімічно пробудити приспані заразні речовини в сирій суміші. Щоб її здобути, доводиться полювати на скелястому узбережжі на схід від Саутшора, ризикуючи наразитися і на лютих наг, і на загони Альянсу поблизу."}},faq={{q="Для чого потрібна Луска Кинджалоспинного?",a="Її збирають для Аптекаря Лайдона в Таррен Міллі — для досліджень Еліксиру Агонії. У поєднанні з іншими реагентами луска пробуджує заразні властивості алхімічної суміші із Суцвіть Багнорила.",al={"використання луски кинджалоспинного","навіщо луска кинджалоспинного","що робить луска кинджалоспинного"}},{q="Звідки ця луска?",a="Її здирають із наг Кинджалоспинних — берегових скрадачів, берегових мисливців, крикунок, сирен і їхньої ватажки Леді Зефріс, — що живуть на узбережжі Передгір'я Гілсбреда просто на схід від людського поселення Саутшор.",al={"де знайти луску кинджалоспинного","хто дропає луску кинджалоспинного","місце луски кинджалоспинного"}},{q="Навіщо Королівському Аптекарському Товариству луска наг?",a="Аптекарі Товариства з'ясували, що міцна луска племені Кинджалоспинних має саме ті хімічні властивості, які потрібні, щоб пробудити певні заразні складники в їхніх експериментальних моровицях і хворобах.",al={"навіщо луска наг","аптекарям луска наг"}}},fp="17,299,19.597.0,37.222.0,32.233.0,55.227.0"}
P.entries["item:dal-bloodclaw-s-skull"] = {n="Череп Дала Бладкло",s="Череп Дала Бладкло забирають у ватажка фурболгів Будякохутрих на півночі Ашенвалю. Коли його приносять Рейн Вульфраннер в Астранаар, він стає відчутним доказом того, що неминучий напад на поселення нічних ельфів відвернуто.",h="Череп Дала Бладкло забирають у ватажка фурболгів Будякохутрих на півночі Ашенвалю.",kw={"дал бладкло","фурболги","будякохутрі","астранаар","рейн вульфраннер","ашенваль"},ang={["faction:Alliance"]="Убивство Дала Бладкло захищає північний фланг Астранаару, і головний притулок Альянсу в центральному Ашенвалі залишається під надійною охороною.",["race:NightElf"]="Для нічних ельфів убивати занепалих ватажків фурболгів — сумна необхідність: давніх союзників спотворила порча, і тепер вони прямо загрожують поселенням на кшталт Астранаару."},sec={{t="Падіння ватажка",b="Фурболги Будякохутрі, що живуть на північ від Астранаару, стрімко множаться й лютішають — їх зіпсувала та сама порча, що й більшу частину прадавніх лісів Ашенвалю. Побоюючись, що плем'я, яке дедалі міцнішає, незабаром наважиться рушити просто на Астранаар, вартова нічних ельфів Рейн Вульфраннер наказала проредити їхні лави й убити їхнього ватажка, Дала Бладкло. Череп Дала Бладкло — не трофей дріб'язкової помсти, а похмурий і незаперечний доказ того, що проводу племені завдано смертельного удару, а захисники Астранаару виграли дорогоцінний час."}},faq={{q="Хто такий Дал Бладкло?",a="Дал Бладкло — вождь фурболгів Будякохутрих, що живуть у Твердині Будякохутрих трохи на північ від Астранаару. Під його проводом вороже плем'я швидко розплодилося й нависло загрозою над сусідньою заставою нічних ельфів.",al={"дал бладкло","хто такий бладкло","вождь будякохутрів"}},{q="Навіщо Рейн Вульфраннер череп?",a="Рейн Вульфраннер потрібен доказ, що вождя Будякохутрих убито. Зі смертю Дала Бладкло нічні ельфи сподіваються, що розлад серед уцілілих фурболгів перешкодить будь-яким злагодженим задумам напасти на Астранаар.",al={"навіщо череп","череп рейн вульфраннер","доказ смерті"}},{q="Чому фурболги Будякохутрі такі ворожі?",a="Як і багато племен фурболгів в Ашенвалі, Будякохутрі піддалися буйній скверні, що засіла в лісі, і з мирних лісових сусідів перетворилися на жорстоку загрозу, що люто боронить свою територію.",al={"чому фурболги агресивні","скверна фурболгів","будякохутрі шалені"}}},fp="21,238,22.573.0,22.231.0,41.221.0,43.221.0"}
P.entries["item:dalaran-mana-gem"] = {n="Самоцвіт Мани з Даларана",s="Самоцвіти Мани з Даларана — кристалізовані запаси магії, які носять при собі служителі Кірін-Тору, що діють у Срібноліссі. Заклиначі-Відступники жадають цих самоцвітів як потужної сировини для зачарованого вбрання на кшталт Мантії Чарівного Вогню.",h="Самоцвіти Мани з Даларана — кристалізовані запаси магії, які носять при собі служителі Кірін-Тору, що діють у...",kw={"самоцвіт мани з даларана","кірін-тор","амбермілл","срібнолісся","йозеф ґреґоріан","кравецтво","маг"},ang={["class:Mage"]="Молодих магів-Відступників посилають по ці самоцвіти, наче на обряд посвяти: так вони доводять і бойову вправність, і вміння опановувати здобуті джерела магії.",["race:Undead"]="Цей промисел показує холодний прагматизм Відступників: вони відкидають сентименти щодо колишніх колег-людей із Даларана, аби забезпечити виживання власного народу."},sec={{t="Викрадена магія",b="Маги, заклиначі й вартові Кірін-Тору, що стоять довкола Амбермілла в Срібноліссі, носять особливі самоцвіти мани, щоб зосереджувати й поповнювати свою магічну снагу. Для магів-Відступників із Магічного Кварталу Андерсіті ці кристалічні провідники — доступне джерело зосередженої магічної сутності. Хоча дехто з немертвих магів визнає спільне наукове коріння з Даларана, сувора необхідність і закон виживання підказують: непоступливі суперники — законна здобич, і їхні магічні запаси можна забрати."},{t="Тчучи чарівний вогонь",b="Самоцвіти, зняті з полеглих служителів Кірін-Тору, несуть до кравців на кшталт Йозефа Ґреґоріана в Андерсіті разом із сувоями простого лляного полотна. Звичайні ремісники не можуть самі спрямовувати магічну силу, але вмілі кравці здатні вплести самоцвіти мани в тканину. Таке насичення перетворює звичайну нитку на зачаровану одіж, що зміцнює зв'язок молодого заклинача з магією."}},faq={{q="Звідки беруться Самоцвіти Мани з Даларана?",a="Їх носять загони Кірін-Тору в Срібноліссі — особливо довкола таборів і застав Даларана біля Амбермілла, на південний схід від Гробниці.",al={"де фармити самоцвіти мани","дроп самоцвіту даларана","хто дропає самоцвіти мани"}},{q="Для чого потрібні ці самоцвіти?",a="Маги-Відступники використовують їх як необхідні складники для зачарування. Принесені разом із полотном Йозефові Ґреґоріану в Андерсіті, вони дають магічний заряд, потрібний, щоб виткати мантії чарівного полум'я.",al={"призначення самоцвіту мани","навіщо мені самоцвіти мани з даларана"}},{q="Навіщо Кірін-Тору в Срібноліссі ці самоцвіти?",a="Члени Кірін-Тору користуються самоцвітами мани як особистими сховищами магічної сили, що підживлюють їхні чари, захисні обереги й закляття у ворожих краях на кшталт Срібнолісся.",al={"чому маги даларана мають самоцвіти","самоцвіти мани кірін-тор"}},{q="Чому Відступники полюють на магів Даларана заради цих самоцвітів?",a="Хоч Відступники й мають спільне з Далараном коріння магічної науки, своїх живих колег вони вважають суперниками. Наставники Андерсіті переконані: маг, що не може вберегти свої магічні скарби, надто слабкий, щоб вижити, — тож забрати в нього складники цілком справедливо.",al={"відступники проти магів даларана","чому вбивати даларан заради шат"}}},fp="16,232,13.549.0,21.423.0,37.169.0,29.187.0,56.187.0,56.259.0"}
P.entries["item:dalaran-pendant"] = {n="Амулет Даларана",s="Амулети Даларана — магічні талісмани, які носять чарівники Кірін-Тору, розміщені в селі Амбермілл у Срібноліссі. Відступники збирають ці амулети, щоб зірвати чарівні задуми магів і вистежити джерело їхньої сили.",h="Амулети Даларана — магічні талісмани, які носять чарівники Кірін-Тору, розміщені в селі Амбермілл у...",kw={"амулет даларана","кірін-тор","амбермілл","срібнолісся","жрець тіні аллістер","маги"},ang={["class:Mage"]="Амулети правлять за фокуси для чарівного плетива Кірін-Тору й показують, як даларанські чаклуни злагоджено творять складну спільну магію.",["race:Undead"]="Відібрати ці амулети в Кірін-Тору — важливий крок, щоб убезпечити Срібнолісся від людських чаклунів, які намагаються знову закріпитися в краї."},sec={{t="Амулети Амбермілла",b="У селі Амбермілл чаклуни, заклиначі й охоронці Кірін-Тору наполегливо плетуть грізні чари, що загрожують владі Відступників у південному Срібноліссі. Кожен із них має при собі налаштований Амулет Даларана. У Гробниці Жрець Тіні Аллістер доручає Відступникам здобути ці амулети, щоб загальмувати зусилля магів і з'ясувати, хто спрямовує їхнє чарівне плетиво."}},faq={{q="Що таке Амулет Даларана?",a="Це магічний амулет, який носять заклиначі, маги й захисники Кірін-Тору, що засіли в Амберміллі. Відступники забирають їх, щоб зірвати обряди чарівників і вивчити їхнє магічне ремесло.",al={"що таке амулет даларана","намисто кірін-тор срібнолісся"}},{q="Хто носить ці амулети?",a="Їх носять маги-люди, заклиначі й захисники Даларана, що зайняли Амбермілл у Срібноліссі.",al={"хто дропає амулет даларана","де взяти амулет даларана"}},{q="Навіщо вони Жерцеві Тіні Аллістеру?",a="Жерцеві Тіні Аллістеру та його союзникові Далару потрібні амулети, щоб уповільнити чари чарівників і визначити, який могутній маг спрямовує потік магічної енергії в Амберміллі.",al={"чому аллістер хоче амулети","розслідування амбермілла амулети"}},{q="Де розташований Амбермілл?",a="Амбермілл — на півдні Срібнолісся. Мандрівникам, що йдуть на південь від Гробниці, треба звернути з головного шляху на східне відгалуження, щоб дійти до села.",al={"місце амбермілла","як дістатися амбермілла"}}},fp="15,250,20.406.0,28.198.0,27.115.0,42.176.0,27.149.0"}
P.entries["item:dalaran-status-report"] = {n="Звіт про Стан Даларана",s="Звіт про Стан Даларана — збірка цінних розвідданих, які уклали чарівники Кірін-Тору, що стоять в Амберміллі в Срібноліссі. У ньому описано теперішній стан Даларана, який відбудовують, тож для Відступників і скрадачів смерті Андерсіті цей документ — цінна здобич.",h="Звіт про Стан Даларана — збірка цінних розвідданих, які уклали чарівники Кірін-Тору, що стоять в Амберміллі в...",kw={"звіт про стан даларана","даларан","кірін-тор","амбермілл","скрадачі смерті","злам замків","меннет каркад"},ang={["class:Rogue"]="Меннет Каркад перетворює пошуки цього звіту на польове випробування: так він навчає скрадачів смерті тонкого мистецтва зламу замків і проникнення під носом у пильних магів.",["race:Undead"]="Рештки Кірін-Тору в Амберміллі — скалка в боці Відступників у Срібноліссі, тож будь-які відомості про їхні дії життєво важливі для безпеки Андерсіті."},sec={{t="Очі на відбудову міста",b="Під час Третьої війни Погибель розграбувала Даларан, а Архімонд звалив його високі шпилі. Уцілілі маги відбудовують місто, і у Forever вони прибрали його захисний купол, поки відбудова ще тривала. Кірін-Тор також тримає осередки на кшталт Амбермілла на південному сході Срібнолісся. Звіт про Стан Даларана містить саме ті відомості про місто, яких прагнуть скрадачі смерті."},{t="Випробування скрадача смерті",b="Утримати Лордерон можна лише за постійної пильності, і лорд Варіматрас уважно стежить за будь-якими рештками Альянсу й Кірін-Тору. Коли допитувачі-Відступники вичавили зізнання з полоненого мага Кірін-Тору, жахолорд наказав скрадачам смерті здобути звіт. Захований у замкненій скриньці глибоко в Амберміллі, документ став і оперативною потребою, і обрядом посвяти для новоприйнятих розбійників, що опановують мистецтво зламу замків під наглядом Меннета Каркада в Кварталі Розбійників."}},faq={{q="Що таке Звіт про Стан Даларана?",a="Це таємні документи Кірін-Тору про нинішнє становище Даларана, відновлювальні роботи та стан міста, складені магами, що тримають заставу в Амберміллі.",al={"що таке цей звіт","звіт даларана","документи амбермілла"}},{q="Де зберігається звіт?",a="Маги Амбермілла замкнули звіт у скрині у своєму поселенні на південному сході Срібнолісся, щоб уберегти його від непроханих гостей і цікавих очей.",al={"де звіт","місце скриньки амбермілла","як знайти звіт про стан"}},{q="Навіщо Андерсіті цей звіт?",a="Лорд Варіматрас і Відступники вважають уцілілий Кірін-Тор прямою загрозою під самим порогом. Здобувши звіт, скрадачі смерті зможуть оцінити військову силу Даларана й таємні проєкти його відбудови.",al={"навіщо андерсіту цей звіт","звіт даларана варіматраса","мета скрадачів смерті"}},{q="Як скрадачі смерті дізналися про документ?",a="Скрадачі смерті вибили відомості про документ і місце, де він лежить, просто з полоненого мага Кірін-Тору, якого тримали й допитували в Андерсіті.",al={"як андерсіт дізнався","зізнання в'язня"}}},fp="21,286,27.426.0,21.518.1,34.185.0,25.172.0,40.223.0,51.147.0"}
P.entries["item:dalin-s-heart"] = {n="Серце Даліна",s="Серце Даліна — моторошний обрядовий складник, вирізаний із грудей Даліна Форджрайта, шляхетного чоловіка, що вартує біля Стіни Ґреймейна в Срібноліссі. Чорнокнижники Андерсіті шукають його як дар незаплямованої чистоти, щоб приманити сукуба й прив'язати його до себе на службу.",h="Серце Даліна — моторошний обрядовий складник, вирізаний із грудей Даліна Форджрайта, шляхетного чоловіка, що...",kw={"серце даліна","далін форджрайт","стіна ґреймейна","сукуб","чорнокнижник","срібнолісся","храм проклятих"},ang={["class:Warlock"]="Здобути це серце — важливий обряд посвяти для чорнокнижників-Відступників, які вчаться ловити сукуба: так ви доводите, що готові забирати незаплямовану чесноту заради влади над демонами.",["race:Undead"]="Полювання на серце Даліна показує гірку правду Лордерона після навали Погибелі: останні живі люди, що допомагають іншим за Стіною Ґреймейна, стають здобиччю Відступників."},sec={{t="Чисте серце для темних мистецтв",b="Щоб викликати й підкорити сукуба, чорнокнижникам Андерсіті потрібна рідкісна приманка — справжні серця доброчесних смертних. Далін Форджрайт заслужив свою темну долю безкорисливою відданістю: він днями боронив зневірених біженців із Лордерона, яких не пустили за замкнену Стіну Ґреймейна. Ця невтомна доброта робить його втіленням добра в занепалому краї, а його серце — непереборною здобиччю для обрядів демонічної спокуси, що їх правлять у Храмі Проклятих."}},faq={{q="Хто такий Далін Форджрайт?",a="Далін Форджрайт — шляхетна людина, що присвятила життя захистові біженців із Лордерону, які застрягли перед зачиненою брамою Стіни Ґреймейна на півдні Срібнолісся.",al={"далін форджрайт","хто такий далін","історія даліна"}},{q="Навіщо чорнокнижникам Серце Даліна?",a="Чорнокнижникам-викликачам Андерсіті потрібне серце справді чистої й шляхетної людини як обрядова принада, щоб приманити й підкорити сукуба.",al={"чому серце даліна","призначення серця даліна","навіщо чорнокнижникам серце даліна"}},{q="Хто приймає Серце Даліна?",a="Серце приносять Карендіну Галґару, наставникові чорнокнижників у Храмі Проклятих в Андерсіті.",al={"хто бере серце","здати серце даліна","куди нести серце даліна"}},{q="Що ще потрібно, крім цього серця?",a="Карендіну Галґару потрібні і Серце Даліна, і Серце Комара — Комара Вілларда, вірного чоловіка, що блукає Багнокраєм у пошуках зниклої дружини.",al={"серця чистих інше серце","яке ще серце потрібне","друге серце"}}},fp="13,271,26.478.0,26.182.0,35.143.0,26.116.0,52.160.0"}
P.entries["item:darkhound-blood"] = {n="Кров Темного Гончака",s="Кров Темного Гончака — мерзенна тілесна рідина, добута із заражених псоподібних звірів, що блукають полями й лісами Галявин Тірісфалю. Зібрана на замовлення Королівського Аптекарського Товариства, вона слугує одним із перших реагентів у їхніх темних дослідах зі створення нової смертоносної чуми.",h="Кров Темного Гончака — мерзенна тілесна рідина, добута із заражених псоподібних звірів, що блукають полями й...",kw={"кров темного гончака","темні гончаки","королівське аптекарське товариство","аптекар йогаан","чума","брілл"},ang={["faction:Horde"]="Поки у Бріллі тривають темні досліди, мало хто поза внутрішнім колом Відступників цілком усвідомлює, який отруйний потенціал відкриває Королівське Аптекарське Товариство.",["race:Undead"]="Збирання реагентів на кшталт Крові Темного Гончака — важлива праця для Відступників: вона допомагає Леді Сильвані й Королівському Аптекарському Товариству кувати найвищу зброю проти Погибелі."},sec={{t="Пальне для Нової Чуми",b="За наказом Леді Сильвани Віндраннер Королівське Аптекарське Товариство прагне створити заразу, здатну стерти Артаса і його Погибель. Аптекар Йогаан, що працює у Бріллі, припускає: місцеві звірі, зіпсуті темними силами й стійкі до довколишнього розкладу, мають незвичайні біологічні властивості. Переганяючи кров диких темних гончаків, Йогаан сподівається виявити біологічні сполуки, здатні протистояти лютим некротичним штамам або розносити їх."}},faq={{q="Для чого потрібна Кров Темного Гончака?",a="Аптекар Йогаан у Бріллі використовує її як основний реагент у дослідах Королівського Аптекарського Товариства, що мають створити нову чуму — смертоноснішу за все, що досі бачив Азерот.",al={"використання крові темного гончака","навіщо кров темного гончака","призначення крові темного гончака"}},{q="З яких істот добувають цю кров?",a="Її беруть із різних темних гончаків, що блукають Галявинами Тірісфалю, — проклятих, ненажерливих і старезних.",al={"де взяти кров темного гончака","хто дропає кров темного гончака","джерело крові темного гончака"}},{q="Чому для досліджень чуми полюють саме на темних гончаків?",a="Аптекар Йогаан припускає, що кров звірів, які призвичаїлися до зіпсованих земель Тірісфалю, може приховувати тілесні таємниці, потрібні, щоб створити нестримну заразу.",al={"чому темні гончаки","теорія аптекаря йохана","властивості темного гончака"}}},fp="15,275,23.478.0,33.185.0,33.119.0,48.179.0"}
P.entries["item:darkshore-grouper"] = {n="Окунь Темного Узбережжя",s="Окунь Темного Узбережжя — міцна морська риба, що живе в імлистих прибережних водах Темного Узбережжя. Її цінують і як смачний щоденний улов, і як спортивну здобич, але виловити її з пристаней дедалі важче: мурлоки вигнали місцевих рибалок із човнів.",h="Окунь Темного Узбережжя — міцна морська риба, що живе в імлистих прибережних водах Темного Узбережжя.",kw={"окунь темного узбережжя","ґуббер бламп","рибальство","мурлоки","обердайн","кулінарія"},ang={["profession:Cooking"]="Окунь Темного Узбережжя — універсальний інгредієнт для простих прибережних рецептів, тож мандрівним кухарям, що вдосконалюють ремесло на березі, він стане в пригоді.",["race:Dwarf"]="Дворф-рибалка Ґуббер Бламп продовжує горду рибальську традицію своєї родини на берегах Калімдору й винагороджує кожного, хто зрівняється в улові з його ріднею."},sec={{t="Головний улов імлистого берега",b="Окунь Темного Узбережжя, що водиться в холодних морських водах краю, — бажаний улов для прибережних рибалок. Рибу цінують за те, що з нею можна приготувати що завгодно: вона потрапляє в цілу низку простих прибережних страв, які люблять мандрівники й мешканці Обердайна. Витягти її з прибою можна й найпростішою снастю, і рибалки кажуть, що ловити окуня не менш приємно, ніж його їсти."},{t="Мурлоцька загроза",b="Колись рибалки на кшталт Ґуббера Блампа виходили на невеликих човнах у глибші води й витягали окунів десятками. Але через дедалі агресивніших прибережних мурлоків більшість човнів біля Обердайна тепер стоїть на березі. Рибалкам лишилися тільки береги й пристані, а місцеві підозрюють, що мурлоки-зайди пожирають окунів, тож добрий улов тепер вимагає терпіння."}},faq={{q="Де ловиться Окунь Темного Узбережжя?",a="Окуня Темного Узбережжя ловлять, закидаючи вудку в солону воду вздовж берегів Темного Узбережжя, зокрема у водах довкола Обердайна.",al={"де ловити окуня","місце окуня темного узбережжя","як зловити окуня темного узбережжя"}},{q="Кому в Обердайні потрібен Окунь Темного Узбережжя?",a="Ґуббер Бламп, дворф-рибалка, що зупинився в Обердайні, просить мандрівників наловити для нього окунів Темного Узбережжя, а натомість дає цінну Вудку Родини Блампів.",al={"кому потрібен окунь","риба ґаббера бламп","хто дає завдання на окуня"}},{q="Чому рибалки не виходять на окуня човнами?",a="Уздовж берегів Темного Узбережжя з'явилися агресивні мурлоки, тож виходити на воду човнами стало для місцевих рибалок надто небезпечно.",al={"чому човни зупинені","рибальські човни обердайна","мурлоки окунь"}},{q="Чи треба мати завдання, щоб зловити Окуня Темного Узбережжя?",a="Ні. Хоча його й просять місцеві, як-от Ґуббер Бламп, Окунь Темного Узбережжя — звичайна морська риба, яку може зловити будь-який рибалка, що закине вудку у води Темного Узбережжя.",al={"чи окунь предмет завдання","чи можна ловити окуня будь-коли"}}},fp="17,267,30.384.0,17.397.0,37.148.0,41.157.0,50.139.0,58.198.0"}
P.entries["item:darksoul-shackle"] = {n="Кайдани Темної Душі",s="Кайдани Темної Душі — зачаровані пута, які носять воргени Темна Душа Мунрейджів, що полюють у Срібноліссі. Виготовлені за вказівками Архімага Аруґала, ці знаряддя потрібні магам-Відступникам у Гробниці, щоб розплутати дику магію, яка тримає край у своїх лабетах.",h="Кайдани Темної Душі — зачаровані пута, які носять воргени Темна Душа Мунрейджів, що полюють у Срібноліссі.",kw={"кайдани темної душі","темна душа мунрейджів","воргени","архімаг аруґал","далар донвівер","срібнолісся"},ang={["class:Mage"]="Ці кайдани показують, як відчайдушний чарівник підпирав грубими зачарованими артефактами нестійкі чари виклику, яких не міг як слід контролювати.",["race:Undead"]="Для Відступників зламати владу Аруґала над Срібноліссям — вкрай важливо, щоб захистити свої південні кордони й довести, що чарівна наука Андерсіті перевершує даларанську, яка зазнала краху."},sec={{t="Милиця для кволої магії",b="Коли Архімаг Аруґал випустив воргенів на Срібнолісся, його власної чарівної майстерності забракло, щоб цілком керувати потойбічними звірами й підтримувати їх. Щоб надолужити свої вади, він прикував до своїх створінь зачаровані знаряддя — як-от Кайдани Темної Душі. Ці пута спрямовують у Темні Душі Мунрейджів сторонні чари, зміцнюючи їхню надприродну силу й закріплюючи прокляття, що тримає їх у покорі Фортеці Шадовфенг."},{t="Під пильним оком Кірін-Тору",b="У Гробниці маг-Відступник Далар Донвівер вважає Аруґала небезпечним невігласом, чиє втручання зруйнувало оборону Кірін-Тору від Погибелі. Збираючи Кайдани Темної Душі разом із тими, що зірвані з Ненажер Мунрейджів, дослідники-Відступники видобувають рештки чарів, вплетених у метал. Вивчення цих милиць оголює вади в Аруґаловому чаклунстві й дає Відступникам чарівне розуміння, потрібне, щоб знайти протидію його вовчій напасті."}},faq={{q="Що таке Кайдани Темної Душі?",a="Це зачаровані металеві пута, які носять Темні Душі Мунрейджів — воргени Срібнолісся. Їх виготовив Архімаг Аруґал, щоб підсилити свої недосконалі чари й тримати звірів під контролем.",al={"що таке кайдани темної душі","історія кайданів темної душі","що це за кайдани"}},{q="Кому потрібні Кайдани Темної Душі?",a="Вони потрібні Далару Донвіверу — магові-Відступникові з Гробниці в Срібноліссі. Він вивчає чари в кайданах, щоб знайти раду на спалах воргенів, який спричинив Аруґал.",al={"кому потрібні кайдани темної душі","хто бере кайдани","завдання далара давнвівера"}},{q="Звідки беруться ці кайдани?",a="Їх знімають із тіл Темних Душ Мунрейджів — лютих воргенів, що никають північчю й сходом Срібнолісся.",al={"хто дропає кайдани темної душі","моб з кайданами темної душі","де взяти кайдани темної душі"}},{q="Чому Аруґал надів на воргенів кайдани?",a="За словами Далара Донвівера, Аруґалові бракувало таланту, щоб керувати звірами самою лише силою. Він покладався на зачаровані предмети, як-от ці кайдани, що спрямовували й підтримували нестійку магію, яка тримала зграю вкупі.",al={"чому воргени носять кайдани","призначення кайданів аруґала"}}},fp="16,273,28.448.0,18.505.1,27.191.0,28.193.0,34.140.0,42.237.0"}
P.entries["item:darnassus-marzipan"] = {n="Марципан із Дарнасуса",s="Марципан із Дарнасуса — святкові ласощі, які в столиці нічних ельфів готують на осіннє свято Переддень Усіх Святих. Корчмарі Дарнасуса роздають його тим, хто ходить по солодощі й готовий станцювати заради смачної винагороди.",h="Марципан із Дарнасуса — святкові ласощі, які в столиці нічних ельфів готують на осіннє свято Переддень Усіх...",kw={"марципан","дарнасус","переддень усіх святих","солодощі","джеспер","корчмар"},ang={["faction:Alliance"]="Збираючи ласощі з Дарнасуса, Айронфорджу й Стормвінда, ви об'єднуєте далекі народи Альянсу спільним святкуванням Передодня Усіх Святих.",["race:NightElf"]="Навіть стримані калдореї приймають веселіші осінні звичаї й пригощають солодким марципаном мандрівників, які шанують їхню гостинність жвавим танцем."},sec={{t="Смак Світового Древа",b="На Переддень Усіх Святих столиці Альянсу долучаються до веселої традиції «солодощі або капость». Дворфи частують гострими м'ятними цукерками, Стормвінд — тягучою нугою, а корчмарі Дарнасуса готують для гостей ніжний марципан. Щоб отримати шматочок, гостеві треба показати трохи святкового настрою — а саме станцювати на прохання корчмаря. Ці ласощі — одні з чотирьох місцевих смаколиків, яких шукає маленький Джеспер, хворий сирота із Соборної Площі Стормвінда, що сам не може піти по солодощі."}},faq={{q="Для чого потрібен Марципан із Дарнасуса?",a="Марципан із Дарнасуса — одна з чотирьох різних солодощів, яких потребує Джеспер, хворий сирота зі стормвіндського сиротинця на Соборній Площі, у Переддень Усіх Святих. Принісши його разом із цукерками з Айронфорджа, Гномреґана й Стормвінда, ви отримаєте натомість оберемок святкових гарбузових ласощів.",al={"використання марципану з дарнасуса","що робити з марципаном"}},{q="Як здобути Марципан із Дарнасуса?",a="Його дають корчмарі Дарнасуса в Переддень Усіх Святих. Корчмар попросить вас швиденько станцювати, перш ніж розлучитися з солодким частуванням.",al={"як отримати марципан з дарнасуса","де взяти марципан"}},{q="Чому Джеспер не може сам принести марципан?",a="Джеспер хворий і не може сам ходити по солодощі. Він живе в стормвіндському сиротинці на Соборній Площі, тож покладається на шукачів пригод, які зберуть для нього далекі ласощі.",al={"навіщо джесперові солодощі","чому джеспер не може піти"}}},fp="18,222,25.534.0,36.279.0,37.158.0,42.170.0"}
P.entries["item:darthalia-s-sealed-commendation"] = {n="Запечатана Грамота Дарталії",s="Запечатана Грамота Дарталії — офіційне донесення, написане командувачкою Відступників у Таррен Міллі. Воно звеличує невтомну кампанію одного воїна проти людей Гілсбреда й несе вісті про ці перемоги просто до верховного командування Андерсіті.",h="Запечатана Грамота Дарталії — офіційне донесення, написане командувачкою Відступників у Таррен Міллі.",kw={"запечатана грамота дарталії","верховний екзекутор дарталія","таррен мілл","передгір'я гілсбреда","саутшор","варіматрас","сильвана віндраннер"},ang={["faction:Horde"]="Грамота знаменує важливу стратегічну перемогу в Лордероні: вона доводить проводу Андерсіті, що укріплені плацдарми Альянсу в південних передгір'ях можна планомірно розбити.",["race:Undead"]="Заслужити щедру похвалу Дарталії й особисто доставити її до тронної зали — так ви підвищуєте своє становище у військовій ієрархії Темної Леді, що невпинно розростається."},sec={{t="Донесення верховному командуванню",b="Following the brutal clashes across the Hillsbrad Foothills, High Executor Darthalia drafted this sealed dispatch to officially record victories against Hillsbrad's human defenders and the devastation wrought upon human positions. Sealed to preserve the commander's appraisal from prying eyes, the document is addressed to Varimathras, dreadlord advisor to Lady Sylvanas Windrunner. For the Forsaken leadership in the Royal Quarter, such missives offer tangible proof that Alliance enclaves south of Lordaeron can be broken, freeing northern garrisons to focus on the relentless threat of the Scourge."}},faq={{q="Що таке Запечатана Грамота Дарталії?",a="Це офіційна військова грамота, яку написала Верховний Екзекутор Дарталія з Таррен Мілла. Документ відзначає бойові заслуги воїна проти Альянсу в Битві за Гілсбред і призначений для верховного командування в Андерсіті.",al={"запечатана грамота","лист дарталії","звіт гілсбреда"}},{q="Хто отримує цю грамоту?",a="Грамоту треба принести просто жахолордові Варіматрасу, який керує військовими справами поруч із Леді Сильваною Віндраннер у Королівському Кварталі Андерсіті.",al={"кому віднести це","здати грамоту","хто отримує грамоту дарталії"}},{q="Чому Варіматраса хвилюють бої в Гілсбреді?",a="Хоча найбільшою загрозою своєму існуванню Відступники вважають Короля-Ліча та його Погибель на півночі, присутність людей у Гілсбреді раз у раз перериває їхні шляхи постачання й загрожує південному кордону. Варіматрас цінує перемоги, що усувають людську перешкоду, — тоді сили Андерсіті можуть зосередитися на більшій війні.",al={"чому варіматрасу цікаво","володар жаху гілсбреду","стратегія відступників у гілсбреді"}}},fp="31,261,22.601.0,40.251.0,31.175.0,58.345.0"}
P.entries["item:deadmire-s-tooth"] = {n="Зуб Мертвої Багнюки",s="Зуб Мертвої Багнюки — трофей, здобутий у прадавнього кроколіска на ім'я Мертвобагно, що чатує в каламутних водах Багна Пилоброду. Принісши його мисливцеві Мелору Стоунгуфу на Тандер Блаф, ви доводите, що старий хижак дістав милосердну й почесну смерть.",h="Зуб Мертвої Багнюки — трофей, здобутий у прадавнього кроколіска на ім'я Мертвобагно, що чатує в каламутних...",kw={"зуб мертвої багнюки","мертвобагно","кроколіск","багно пилоброду","мелор стоунгуф","узвишшя мисливців","мисливець"},ang={["class:Hunter"]="Для мисливців, що навчаються в наставників Узвишшя Мисливців, цей зуб — урок того, що в полюванні мають бути повага й милосердя, а не сама лише гонитва за трофеями.",["race:Tauren"]="Полювання на Мертвобагно втілює коло рівноваги Земної Матері, у якому старих хижаків ведуть до спокою, а не лишають страждати."},sec={{t="Трофей милосердя",b="За традиціями мисливців-тауренів з Узвишшя Мисливців вистежування диких звірів — не просто перевірка бойової вправності й не бездумна кривава забава. Це духовна угода рівноваги, шани, а часом і милосердя. Колись Мертвобагно був одним із найвеличніших кроколісків Багна Пилоброду, але глибока старість обернула його останні роки на нестерпні муки. Хоч він і зберіг незламний дух і моторошну лють своїх найкращих років, його масивні кістки й немічне тіло стали в'язницею нескінченного болю. Зуб Мертвої Багнюки — відчутний доказ для Мелора Стоунгуфа, що тривалі страждання звіра нарешті скінчилися завдяки почесному полюванню."}},faq={{q="Для чого потрібен Зуб Мертвої Багнюки?",a="Зуб приносять Мелорові Стоунгуфу на Узвишші Мисливців у Тандер Блафі. Він завершує полювання на Мертвобагно, яке доручає Мелор, і засвідчує, що прадавній хижак дістав милосердне звільнення.",al={"здати зуб мертвобагна","хто хоче зуб мертвої багнюки","що робити із зубом мертвобагна"}},{q="Звідки береться Зуб Мертвої Багнюки?",a="Зуб виривають просто з пащі Мертвобагна — величезного блідого кроколіска, що никає водами Багна Пилоброду. Його часто бачать біля річки й островів на північ від Руїн Кам'яного Молота.",al={"де взяти зуб мертвої багнюки","хто дропає зуб мертвобагна","місце мертвобагна"}},{q="Чому Мелор Стоунгуф хоче смерті Мертвобагна?",a="Мелор не вважає Мертвобагно чудовиськом — для нього це благородна істота, яка на старість терпить нестерпний біль, що доводить до божевілля. Полювання — це милосердя: нехай вогонь життя кроколіска згасне спокійно, а не тліє в повільних муках.",al={"чому вбити мертвобагна","причина мелора стоунгуфа","чи мертвобагно злий"}}},fp="16,270,17.677.0,34.204.0,38.195.0,46.238.0"}
P.entries["item:death-cap"] = {n="Бліда Поганка",s="Бліда Поганка — рідкісний і сильний гриб, що ховається в затіненій печері за Водоспадом Скельного Джерела на Темному Узбережжі. Алхіміки нічних ельфів шукають його заради особливих властивостей, але, щоб його зібрати, доведеться зайти в підземне кубло, від якого застерігають у Гаю Прадавніх.",h="Бліда Поганка — рідкісний і сильний гриб, що ховається в затіненій печері за Водоспадом Скельного Джерела на...",kw={"бліда поганка","водоспад скельного джерела","барітрас муншейд","гай прадавніх","темне узбережжя","алхімія"},ang={["profession:Herbalism"]="Хоча для Барітраса Бліду Поганку можна зібрати й без фахових навичок, кожен травник оцінить, як ризиковано рвати рідкісні гриби в сирих, зіпсованих підземних закутках.",["race:NightElf"]="Здобуваючи Бліду Поганку, ви служите двом справам: допомагаєте Барітрасові варити зілля в Обердайні й перевіряєте грізні передчуття, які висловили в Гаю Прадавніх."},sec={{t="Отруйний цвіт у темряві",b="Бліда Поганка росте лише в підземній вогкості печери, захованої за Водоспадом Скельного Джерела, серед північно-східних гірських хребтів Темного Узбережжя. На відміну від численних Стебел Стрункавки, що вкривають долівку печери, Бліда Поганка трапляється рідко й помітно вирізняється. Травники нічних ельфів, як-от Барітрас Муншейд, цінують гриб для дослідних варив, хоча навіть заради одного екземпляра доведеться ризикнути й увійти до печери, де, як шепочуть, зароджується порча."},{t="Прикмета Скельного Джерела",b="Збирання Блідої Поганки — така ж розвідка, як і алхімічне доручення. Охоронці з Гаю Прадавніх застерегли місцевих калдореїв не наближатися до водоспаду: вони відчули, як у темряві вкорінюється щось мерзенне. Хто зайде до печери, щоб зірвати гриб, муситиме зіткнутися з тими силами, що обрали цю вогку западину за своє лігво."}},faq={{q="Де знайти Бліду Поганку?",a="Бліді Поганки ростуть у прихованій печері за Водоспадом Скельного Джерела, на північному сході Темного Узбережжя, під самою гірською стіною.",al={"місце блідої поганки","де бліда поганка","гриб у печері кліффспрінг"}},{q="Кому потрібен цей гриб?",a="Барітрас Муншейд, алхімік із прибережного поселення Обердайн, шукає Бліду Поганку, щоб зварити особливе зілля.",al={"кому потрібен гриб","завдання барітраса про гриб"}},{q="Чому Барітрас Муншейд не зібрав її сам?",a="Деревні охоронці з Гаю Прадавніх застерегли Барітраса від печери за Водоспадом Скельного Джерела: вони відчули, що там сховалося зло, яке підступає до краю.",al={"чому не зібрав сам","застереження барітраса"}},{q="Чим Бліда Поганка відрізняється від Стебла Стрункавки?",a="Стебел стрункавки на дні печери Скельного Джерела досить багато, а Бліда Поганка — рідкісніший і сильніший гриб, який доводиться ретельно вишукувати.",al={"поганка проти стебла стрункавки","різниця грибів"}}},fp="9,273,25.485.0,19.361.1,29.125.0,24.132.0,50.177.0,50.166.0"}
P.entries["item:deathstalker-report"] = {n="Звіт Смертоловця",s="Звіт Смертоловця — письмове донесення Скрадача Смерті Рейна Йоріка про військову розвідку в Срібноліссі. Воно містить важливі тактичні відомості для Верховного Екзекутора Гадрека в Гробниці — про пересування Погибелі в краї й стан передових розвідників Відступників.",h="Звіт Смертоловця — письмове донесення Скрадача Смерті Рейна Йоріка про військову розвідку в Срібноліссі.",kw={"звіт смертоловця","рейн йорік","квінн йорік","верховний екзекутор гадрек","скрадачі смерті","срібнолісся","розвідка"},ang={["class:Rogue"]="Доставляючи відомості, зібрані досвідченими скрадачами смерті, ви зазираєте просто в таємну розвідувальну роботу, на якій тримається військо Відступників.",["race:Undead"]="Звіт показує безжальну дієвість і постійну небезпеку, з якою стикаються скрадачі смерті — розвідка, що стереже рубежі Лордерона для Сильвани."},sec={{t="Відомості з передової",b="Розвідка в північному Срібноліссі — смертельно небезпечна справа навіть для нежиті. Потрапивши в засідку й опинившись затиснутими Погибеллю, що нишпорить сосновими лісами, скрадачі смерті Рейн Йорік і Квінн Йорік мусили звести свої знахідки в це поспішне донесення. Звіт описує несподівано запеклий опір Погибелі, що загрожує задумам Відступників утвердитися в краї. Квінн тяжко поранений під час місії, тож документ довіряють союзникам, що проходять повз, аби Верховний Екзекутор Гадрек у Гробниці отримав звістку без зволікань."}},faq={{q="Що таке Звіт Смертоловця?",a="Це польовий звіт, який склала скрадачка смерті Рейн Йорік. У ньому описано небезпеки, дії Погибелі й перешкоди, з якими стикаються розвідники-Відступники в Срібноліссі.",al={"що таке звіт смертоловця","про що звіт смертоловця","що це за звіт"}},{q="Хто написав звіт?",a="Звіт написала скрадачка смерті Рейн Йорік, доглянувши свого пораненого брата, скрадача смерті Квінна, після сутички з місцевою Погибеллю.",al={"хто написав звіт смертоловця","автор звіту","хто його написав"}},{q="Кому доставляють звіт?",a="Його адресовано й доставляють Верховному Екзекуторові Гадреку — командирові Відступників у Гробниці, що керує військовими справами по всьому Срібноліссю.",al={"куди звіт","кому віддати звіт","звіт гадрека"}},{q="Чому звіт такий нагальний?",a="Верховний Екзекутор Гадрек недооцінив, як багато Погибелі в Срібноліссі. Звіт описує ці ворожі сили й дає вкрай потрібні відомості, щоб Відступники втримали свої позиції в краї.",al={"чому звіт важливий","навіщо гадреку звіт","що в звіті"}}},fp="19,312,22.578.0,32.178.0,21.157.0,31.167.0,37.209.0"}
P.entries["item:deepfury-s-orders"] = {n="Накази Діпф'юрі",s="Накази Діпф'юрі — зім'ятий пергамент, знайдений на тілі Старого Растлока під Мостом Тандол. Він містить похмурі вказівки дворфів Темного Заліза, які влаштували засідку на дворфа-захисника, що вирушив на розвідку.",h="Накази Діпф'юрі — зім'ятий пергамент, знайдений на тілі Старого Растлока під Мостом Тандол.",kw={"накази діпф'юрі","міст тандол","темне залізо","старий растлок","раґ ґармасон","багнокрай"},ang={["faction:Alliance"]="Перехоплені накази викривають спробу диверсії на головному суходільному шляху між Дун Мороґом, Багнокраєм і північними заставами Альянсу.",["race:Dwarf"]="Змови Темного Заліза під Мостом Тандол болюче ранять дворфів Айронфорджа, адже міст — одне з найбільших інженерних досягнень їхнього королівства й життєво важлива торгова ланка з північчю."},sec={{t="Знахідка під мостом",b="Розвідуючи підвалини Мосту Тандол, дворф-захисник мосту Старий Растлок потрапив у раптову засідку Темного Заліза й загинув. Біля стиснутого кулака розвідника лежали ці накази, складені ворожим ватажком — Діпф'юрі. Документ — прямий доказ злагодженої змови проти мосту, що з'єднує Багнокрай з Аратійським нагір'ям."},{t="Викриття загрози",b="Принісши Накази Діпф'юрі Раґові Ґармасону, ви підтверджуєте найгірші підозри гарнізону мосту. Це не випадкова сутичка: дворфи Темного Заліза навмисно готують операції просто під величною кам'яною кладкою Мосту Тандол, і тепер до Айронфорджа й Стормвінда летять нагальні прохання про підкріплення."}},faq={{q="Що таке Накази Діпф'юрі?",a="Це письмові військові накази командира Темного Заліза Діпф'юрі, знайдені біля тіла Старого Растлока під Мостом Тандол.",al={"накази діпф'юрі","що за накази","пергамент діпф'юрі"}},{q="Де знайти накази?",a="Пергамент лежить біля стиснутого кулака Старого Растлока в печерних опорах під Мостом Тандол на півночі Багнокраю.",al={"де накази","місце растлока","знайти накази діпф'юрі"}},{q="Хто такий Старий Растлок?",a="Старий Растлок — дворф-розвідник із Мосту Тандол, що спустився з'ясувати, що за дивна метушня біля опор мосту, і потрапив у засідку дворфів Темного Заліза.",al={"хто такий старий растлок","історія старого растлока"}},{q="Хто отримує Накази Діпф'юрі?",a="Накази приносять Раґу Ґармасону — дворфові-захисникові нагорі, на Мосту Тандол, який читає їх, щоб оцінити загрозу Темного Заліза.",al={"кому віднести накази","раґ ґармасон"}}},fp="17,217,24.375.0,21.315.1,27.153.0,27.151.0,22.175.0,31.145.0"}
P.entries["item:deepmoss-egg"] = {n="Яйце Глибокомохового",s="Яйця глибокомохових павуків — скупчені кладки, які ці павуки відкладають серед скель і каньйонів Гір Кам'яного Кігтя. Їх прагнуть спритні гоблінські купці з Раджета: яйцям судилося стати екзотичним ласощем у піратському порту Буті Бей.",h="Яйця глибокомохових павуків — скупчені кладки, які ці павуки відкладають серед скель і каньйонів Гір...",kw={"яйце глибокомохового","павучі яйця","буті бей","мебок міззірікс","кулінарія","гори кам'яного кігтя"},ang={["profession:Cooking"]="Кухарі-люди, орки й дворфи, може, й завагаються, але мешканці Буті Бей вважають збиті павучі яйця сміливим делікатесом, вартим недешевих гоблінських цін."},sec={{t="Ласощі серед скель",b="Глибокомохові павуки гніздяться по всіх скелястих височинах Гір Кам'яного Кігтя, особливо в Каньйоні Сішир і під рештками дерев Кручі Вітрорізу. Їхні кладки містять живі павучі яйця, сховані під товстими павутинними мішками й вологим гірським мохом. Більшості мандрівників вони гидкі, але ці яєчні мішки привернули увагу гоблінської торгівлі."},{t="Кулінарна мода Буті Бей",b="У південному порту Буті Бей омлет із павучих яєць раптом став химерною гастрономічною модою. Місцеві запаси не можуть угамувати апетит багатих піратів і сміливих гурманів, тож купець із Раджета Мебок Міззірікс налагоджує постачання через Начальника Пристані Діззівіга. Шукачі пригод наважуються зійтися з отруйними виводками Кам'яного Кігтя, щоб зібрати свіжі кладки, і небезпечні павучі гнізда обертаються на вигідні угоди на перевезення."}},faq={{q="Де знайти Яйця Глибокомохового?",a="Вони в Горах Кам'яного Кігтя на північний захід від Пусток. Кладки можна знайти під уцілілими деревами на Кручі Вітрорізу, а також глибше — в отруйних лігвах Каньйону Сішир.",al={"місця яєць","де взяти яйця глибокомохового","місце яєць глибокомохового"}},{q="Хто хоче зібрати ці яйця?",a="Гоблін-ділок Мебок Міззірікс із Раджета наймає шукачів пригод, щоб їх зібрати, і домовляється з Начальником Пристані Діззівігом про торговий шлях, щоб вивозити кладки за море.",al={"кому потрібні яйця","хто купує яйця глибокомохового","завдання мебока міззіркса"}},{q="Для чого насправді ці яйця?",a="Їх везуть до Буті Бей, де омлет із павучих яєць став популярною, хоч і дивною, модою серед місцевих піратів і гостей.",al={"для чого яйця павука","чому збирати яйця павуків","омлети з павучих яєць"}},{q="Чому застерігають від Каньйону Сішир?",a="Каньйон Сішир — розплідник, де аж кишить дорослими павуками, павутинням і об'їдками здобичі. Мебок радить тим, хто має слабкий шлунок, краще збирати яйця під рідкими деревами Кручі Вітрорізу.",al={"застереження каньйону сішир","слабкий шлунок сішир"}}},fp="12,262,23.380.0,24.427.0,30.207.0,32.171.0,36.148.0,54.217.0"}
P.entries["item:defias-docket"] = {n="Реєстр Дефіас",s="Реєстр Дефіас — збірка таємних оперативних наказів Братства Дефіас, знайдена в схованці на Хуторі Аддла на заході Сутінколісся. У ньому докладні відомості про зухвалу змову Дефіас, і він стає важливою зачіпкою в пошуках зниклого посланця Стормвінда.",h="Реєстр Дефіас — збірка таємних оперативних наказів Братства Дефіас, знайдена в схованці на Хуторі Аддла на...",kw={"реєстр дефіас","братство дефіас","хутір аддла","вартовий бакус","еллінг тріас","змова"},ang={["class:Rogue"]="Реєстр — промовисте нагадування про витончене шифрування й таємну логістику, які Братство Дефіас приховує за личиною звичайного розбою.",["faction:Alliance"]="Документи з реєстру викривають злагоджену зрадницьку змову, що б'є по самій верхівці влади Стормвінда."},sec={{t="Слід у темряву",b="Розплутуючи справу про зниклого дипломата королівства, слідчі за порадою Майстра Еллінга Тріаса вирушають до Сутінколісся. Вартовий Бакус помітив, що останнім часом Дефіас незвично часто сходяться до Хутора Аддла — занедбаної садиби одразу на південь від дороги з Вестфолу. У залізній скрині на садибі схований Реєстр Дефіас із заплутаними записами про пересування братства, які далеко виходять за межі звичайного розбою на дорогах чи місцевого бандитизму."},{t="Павутина змови",b="Під час огляду папери виявилися такими заплутаними й політично небезпечними, що Вартовий Бакус відмовився тримати їх у себе, боячись суворої кари від начальства, якщо його спіймають із ними. Повернутий до сирної крамниці Тріаса в Стормвінді, реєстр показує, що Дефіас уклали чималі кошти в складну змову з викраденням і пов'язують її з відомими ділками підпілля, зокрема з агентом на прізвисько «Кулак»."}},faq={{q="Що таке Реєстр Дефіас?",a="Це офіційна в'язка письмових документів і наказів Братства Дефіас із подробицями їхніх планів і таємних операцій у Сутінколіссі та Вестфолі.",al={"що таке реєстр","папери дефіас","реєстр зниклого дипломата"}},{q="Де знайти Реєстр Дефіас?",a="Він замкнений у скрині Дефіас у напівзруйнованій хаті на Хуторі Аддла, трохи на південь від дороги, що веде з Вестфолу на захід Сутінколісся.",al={"місце реєстру","де знайти реєстр дефіас","реєстр аддлс-стед"}},{q="Чому реєстр тримали в Сутінколіссі?",a="Агенти Дефіас використовували Хутір Аддла як віддалену перевалочну базу між Вестфолом і Сутінколіссям, щоб готувати важливу операцію подалі від пильних очей головних патрулів Стормвінда.",al={"чому реєстр в сутінколіссі","дефіас в аддлс-стеді"}},{q="Хто вивчає реєстр?",a="Вартовий Бакус коротко переглядає його й надсилає просто Еллінгові Тріасу в Стормвінд — його таємна мережа розвідників знається на розшифровуванні потаємних послань злочинного світу.",al={"кому віддати реєстр","хто читає реєстр"}}},fp="13,309,21.468.0,21.418.1,26.186.0,33.157.0,36.191.0,24.192.0"}
P.entries["item:defias-tower-key"] = {n="Ключ від Вежі Дефіасу",s="Ключ від Вежі Дефіасу викрадають у потворних вартових, що стережуть Вежу Клавена у Вестфолі. Його носять мутовані трутні, які захищають це місце, і він — важливий доказ небезпечних справ Братства Дефіас, якого шукають агенти розвідки Стормвінда.",h="Ключ від Вежі Дефіасу викрадають у потворних вартових, що стережуть Вежу Клавена у Вестфолі.",kw={"ключ від вежі дефіасу","вежа клавена","si:7","матіас шоу","занзіл вигнанець","отрути"},ang={["class:Rogue"]="Здобути Ключ від Вежі Дефіасу — класичне випробування для розбійників, що працюють із SI:7: воно вимагає майстерно скрадатися, спритно обчищати кишені й розумітися на смертельних отрутах."},sec={{t="Трофей від потворної варти",b="Klaven's Tower along the Westfall coastline has long served as a stronghold for the Defias Brotherhood, but recent shipments out of Duskwood brought far more terrifying sentries to its perimeter. Among the guards are malformed Defias drones—undead, spike-ridden abominations. To pierce the defenses and prove the perimeter breached, SI:7 operatives stake out the grounds and mandate that field agents pick the pockets of these grotesque sentinels rather than engage them head-on. The key serves as clear evidence that an infiltrator penetrated the perimeter without sounding an alarm."},{t="Слід веде до Сутінколісся",b="Здобути цей ключ — перший крок до розкриття неприродної змови, що сягає далеко за межі звичайного розбою на дорогах. У вежі стоїть скриня з вантажем із Сутінколісся, а в ній — Щоденник Клавена Мортвейка. Коли щоденник потрапляє до Майстра Матіаса Шоу в Стормвінді, стає ясно, що Дефіас змовилися з Венчурною Компанією, щоб торгувати особливими отрутами тролів, які відкрив Занзіл Вигнанець. Ці суміші дають алхімікам змогу імітувати нежиття — от звідки взялися потворні почвари, що кашляють довкола вежі."}},faq={{q="Як здобути Ключ від Вежі Дефіасу?",a="Ключ не випадає з переможеного ворога. Агентові треба непомітно підкрастися й обчистити кишені одного зі спотворених трутнів Дефіас, що стережуть Вежу Клейвена у Вестфолі.",al={"де взяти ключ","як отримати ключ від вежі дефіасу","хто дропає ключ від вежі дефіасу"}},{q="Що відмикає Ключ від Вежі Дефіасу?",a="Насправді ключ не відмикає ні дверей вежі, ні Скрині Сутінколісся всередині. Це розвідувальний знак, якого вимагає Майстер Матіас Шоу, щоб пересвідчитися, що агент непомітно пройшов повз охорону.",al={"чи відчиняє скриню сутінколісся","які двері відчиняє ключ","що відмикає ключ дефіасу"}},{q="Хто такі спотворені трутні Дефіас, що стережуть вежу?",a="They are grotesque, spiked undead guards stationed around Klaven's Tower. Agent Kearnen does not know what made them and asks operatives to investigate the shipment they guard.",al={"хто тримає ключ","хто охороняє вежу","що таке шипастий зомбі"}},{q="Хто посилає агентів по цей ключ?",a="Агент Кірнен, розвідник SI:7, що стежить за околицями Вежі Клейвена, доручає польовим розбійникам здобути ключ і вміст Скрині Сутінколісся для Майстра Матіаса Шоу в Стормвінді.",al={"хто дає завдання","кому потрібен ключ"}}},fp="16,280,30.586.0,34.543.1,39.180.0,36.234.0,56.176.1,42.199.0"}
P.entries["item:deliah-s-ring"] = {n="Перстень Делії",s="Перстень Делії — прикраса з гравіюванням, знайдена в купі трупів, яку назбирали гнилошкірі гноли в Срібноліссі. Напис «Для Делії» веде похмурим слідом до жертви чуми, викраденої з братських могил Тірісфалю.",h="Перстень Делії — прикраса з гравіюванням, знайдена в купі трупів, яку назбирали гнилошкірі гноли в...",kw={"перстень делії","делія","гнилошкірі гноли","брілл","магістрат севрен","тірісфаль","острів фенріс"},ang={["race:Undead"]="Перстень показує холодну дійсність існування Відступників: смертні прив'язаності часто гниють разом із плоттю, хоча дехто ще чіпляється за пам'ять про тих, кого кохав за життя."},sec={{t="Пам'ятка в багнюці",b="Перстень знайшли на порізаній віспинами, порівняно свіжій руці трупа серед гнолівських курганів у Срібноліссі, і напис на ньому простий: «Для Делії». Знахідка показує, що місцеві гнилошкірі гноли не просто обдирають поля битв — вони грабують братські могили Галявин Тірісфалю й тягнуть людські тіла й тіла Відступників на південь, на Острів Фенріс, для власних мерзенних цілей."},{t="Ниточка до Брілла",b="Коли перстень приносять владі Відступників, Верховний Екзекутор Гадрек відсилає його до Брілла, де Магістрат Севрен веде записи про нещодавно померлих. Севрен підтверджує, що Делія жила в Бріллі, доки її не забрала чума, і там її поховали, перш ніж викрадачі тіл розкопали її рештки. Ниточка персня веде до тривалого горя тих, кого вона лишила, і перевіряє, чи може смертна відданість пережити перехід у нежиття."}},faq={{q="Де знайти Перстень Делії?",a="Перстень знаходять, обшукуючи кургани гнилошкірих гнолів на півночі Срібнолісся: він на руці жертви чуми, з якої зняли саван, серед награбованих мерців.",al={"де знайти перстень делії","місце персня делії","як отримати перстень делії"}},{q="Хто така Делія?",a="Делія — колишня мешканка Брілла, що померла від чуми. Її поховали в місцевій братській могилі, а потім гнилошкірі гноли викрали тіло й затягли в Срібнолісся.",al={"хто така делія","історія делії","делія з брилла"}},{q="Навіщо гнилошкірим гнолям її тіло?",a="Гнилошкірі гноли, що служать Погибелі, грабують братські могили в Галявинах Тірісфалю, збирають трупи й переправляють їх до своєї твердині на Острові Фенріс.",al={"чому гноли крадуть тіла","гнилошкірі крадуть трупи","що гноли роблять з трупами"}},{q="Що написано на персні?",a="Усередині обідка вигравіювано слова «Для Делії» — отже, це був особистий подарунок від коханого чи чоловіка ще до її смерті.",al={"гравіювання на персні","що написано на персні","перстень для делії"}}},fp="13,266,22.395.0,13.454.1,29.182.0,15.183.0,42.173.0,36.143.0"}
P.entries["item:delivery-to-mathias"] = {n="Посилка для Матіаса",s="Посилка для Матіаса — запечатаний пакунок, який Керін Сильвій у Ґолдширі довіряє здібним розбійникам. Передавши його Майстрові Матіасу Шоу, агент-початківець отримує доступ до внутрішньої кухні SI:7 у Стормвінді.",h="Посилка для Матіаса — запечатаний пакунок, який Керін Сильвій у Ґолдширі довіряє здібним розбійникам.",kw={"посилка для матіаса","майстер матіас шоу","керін сильвій","si:7","розбійник","старе місто"},ang={["class:Rogue"]="Цей пакунок — ваш обряд посвяти: перехід від дрібних бійок у завулках до таємного світу королівської розвідки під проводом Матіаса Шоу.",["faction:Alliance"]="Таємні депеші між місцевими розвідниками й столицею підтримують роботу потайного шпигунського апарату Стормвінда в боротьбі з внутрішньою підривною діяльністю."},sec={{t="Випробування гінця",b="Непосвяченому оку віднести простий пакунок із Корчми «Лев'яча Гордість» до Казарм Стормвінда здається буденною роботою посильного. Та для розбійників-початківців цей пакунок — проба для розвідки Стормвінда. Отриманий від місцевої наставниці Керін Сильвій, він дає новачкам — кишеньковим злодіям — нагоду познайомитися просто з Майстром Матіасом Шоу й перевіряє, чи вміють вони орієнтуватися в столиці, не привертати уваги й виконувати делікатні накази без зайвих питань."},{t="Брама до SI:7",b="Доставивши пакунок, агент потрапляє просто в серце штабу SI:7 у Старому Місті. Матіас Шоу використовує такі передачі, щоб відсіяти позерів від справжніх талантів. Тих, хто вручить пакунок не схибивши, чекають відповідальні польові завдання — передусім таємна розвідка й проникнення в контрабандні мережі Дефіас у Лісі Елвінн."}},faq={{q="Що в Посилці для Матіаса?",a="Посилка запечатана, і кур'єр не знає, що всередині. Але оскільки її передає польовий наставник Керін Сильвій головному розвідникові Матіасу Шоу, там, певно, донесення, оцінки учнів чи таємні відомості про місцеві загрози, як-от Братство Дефіас в Елвінні.",al={"що в пакеті","вміст посилки","вміст посилки для матіаса"}},{q="Хто надсилає цю посилку?",a="Посилку вручає Керін Сильвій — агент-розбійник і наставник, що мешкає нагорі в Корчмі «Лев'яча Гордість» у Ґолдширі.",al={"хто дав посилку","відправник посилки","посилка керина сильвіуса"}},{q="Де штаб Матіаса Шоу?",a="Матіас Шоу — на другому поверсі будівлі SI:7 у південно-східному куті Старого Міста, біля Казарми Стормвінда.",al={"де матіас шоу","куди віднести посилку","місце шоу"}},{q="Що стається, коли показати посилку Шоу?",a="Пересвідчившись у ваших здібностях, Шоу долучає вас до справжнього польового шпигунства. Він посилає вас проникнути на Пристань Джерода й викрасти розклад суден у портового наглядача Дефіас.",al={"наступне завдання після доставки","що робить шоу","після доставки матіасу"}}},fp="19,223,16.454.0,15.375.0,39.274.0,24.132.0,46.153.0,49.179.1"}
P.entries["item:deviate-hide"] = {n="Девіантна Шкіра",s="Девіантні шкури — мутовані шкури, здерті зі звірів, що живуть у Печерах Стогонів. Спотворені скверним сном архідруїда Наралекса, ці потойбічні шкури шукають друїди, які прагнуть обернути скверну Жахіття на міцні шкіряні вироби.",h="Девіантні шкури — мутовані шкури, здерті зі звірів, що живуть у Печерах Стогонів.",kw={"девіантна шкіра","печери стогонів","наралекс","налпак","смарагдове жахіття","шкірництво"},ang={["class:Druid"]="Для друїдів збирати девіантні шкури — гірке зіткнення з владою Смарагдового Жахіття над природою, хоча учні на кшталт Налпака намагаються повернути спотвореним матеріалам практичну користь для виживання."},sec={{t="Сплюндровані шкури Жахіття",b="Коли друїд із нічних ельфів Наралекс поринув у глибокий сон під Пустками, його сновидіння обернулося на Смарагдове Жахіття, що спотворило природу печер. Звірі в глибинах перетворилися на неприродних хижаків-девіантів із цупкими, мутованими шкурами. Хоч ці шкури від природи позначені злом, вони мають незвичну, гнучку стійкість, що робить їх напрочуд придатними для шкірництва. Налпак, що сидить високо над входом до печери, у скелі, схожій на череп, збирає ці шкури, щоб вивчити їхні властивості й пошити з них міцні дорожні торби."}},faq={{q="Чим девіантна шкіра відрізняється від звичайної?",a="Девіантні шкіри знімають з істот, спотворених Смарагдовим Жахіттям, що просочується зі сну Наралекса. Ця скверна змінює їхню плоть і дає дивну, неземну міцність і пружність, якої не мають шкури звичайних звірів.",al={"історія девіантної шкіри","чому девіантні шкури дивні","природа девіантної шкури"}},{q="Хто збирає ці шкури?",a="Налпак, учень Наралекса, що отаборився в печері-«очниці» над входом до Печер Стогонів, шукає ці шкури. Він вірить, що, попри лиху природу девіантних звірів, їхні шкури можна спокутувати й перетворити на корисні шкіряні вироби.",al={"хто хоче девіантні шкури","шкури налпака","кому потрібна девіантна шкіра"}},{q="Де знайти девіантні шкури?",a="Їх знімають із різних девіантних звірів, що никають Печерами Стогонів під Пустками, — рапторів, гадюк, кроколісків і жахоіклів.",al={"звідки падають девіантні шкури","як отримати девіантні шкури"}}},fp="12,267,30.569.0,56.225.0,30.260.0,30.158.0"}
P.entries["item:devlin-s-remains"] = {n="Останки Девліна",s="Останки Девліна — зібрані кістки Девліна Аґаманда, молодшого сина заможної родини, якій належали Млини Аґаманда. Безтямним рабом Погибелі він никав дорогами біля зруйнованого родового маєтку, доки його не здолали, щоб доставити його кістки мстивому вцілілому у Бріллі.",h="Останки Девліна — зібрані кістки Девліна Аґаманда, молодшого сина заможної родини, якій належали Млини...",kw={"останки девліна","девлін аґаманд","млини аґаманда","коулмен фартінґ","помста","брілл"},ang={["race:Undead"]="Для Відступників Аґаманди — стара привілейована знать Лордерону, чиї невдачі лишили простолюд гинути й повставати чудовиськами, тож наруга над останками Девліна — акт класової відплати."},sec={{t="Гірка спадщина",b="За життя Девлін Аґаманд стояв у тіні старшого брата Турмана. Де Турман був лагідний і високий, там Девліна пам'ятали тілесно кволим і злостиво гострим на язик. Коли Чума Нежиті прокотилася північчю Галявин Тірісфалю, родина Аґамандів не зуміла захистити ні свої землі, ні робітників. Девлін упав одним із перших і був піднятий ненажерливим гулем Погибелі, чиє шалене, безумне белькотіння переслідувало узбіччя дороги до Млинів Аґаманда."},{t="Помста на каміні",b="Коулмен Фартінґ, один із Відступників, що мешкає у Бріллі, плекає глибоку й невідступну образу на весь рід Аґамандів. Вважаючи їх прямо винними в тому, що вони підвели його сім'ю, коли прийшла чума, Фартінґ доручив мандрівникам упокоїти Девліна й зібрати його останки. Фартінґ хотів виставити кістки Девліна на своєму каміні, смакуючи знання, що його колишні господарі обернулися на порох і потрощені уламки під його п'ятою."}},faq={{q="Ким був Девлін Аґаманд за життя?",a="Девлін — молодший син родини Аґаманд, заможних землевласників, що збудували Млини Аґаманда на півночі Галявин Тірісфалю. На відміну від свого лагідного й широкоплечого брата Термана, Девлін був кволий, хворобливий і славився лихою вдачею та їдким, гострим язиком.",al={"хто такий девлін","історія девліна аґаманда","про девліна"}},{q="Звідки зібрали останки Девліна?",a="Їх забрали з трупа Девліна Аґаманда, яким керує Погибель, — трохи на південь від Млинів Аґаманда, при дорозі, що в'ється Галявинами Тірісфалю.",al={"де девлін","де знайти девліна","місце девліна аґаманда"}},{q="Навіщо Коулменові Фартінґу ці кістки?",a="Коулмен Фартінґ зневажає родину Аґаманд: він вважає, що вони покинули й підвели його та його рідних, коли спалахнула Чума. Він хоче виставити кістки Девліна на камінній полиці в Бріллі — як трофей помсти й утіхи.",al={"чому фартінґ хоче останки","мотив коулмена фартінґа","чому збирати кістки аґаманд"}},{q="Чи Девлін — Відступник?",a="Ні. Коли Девліна здолала Чума, його розум цілком поглинула Погибель. Він блукав околицями млинів як безвольний гуль-нежить і белькотів божевільні речі, доки його не знищили.",al={"чи девлін відступник","чи девлін був погибеллю"}}},fp="16,290,15.464.0,23.452.0,31.284.0,42.152.0,43.245.0,31.184.0"}
P.entries["item:dirt-caked-pendant"] = {n="Обліплений брудом амулет",s="Обліплений брудом амулет — особиста пам'ятка полоненого орка Доґрана. Його віддають чорнокнижникові-початківцю в Пустках, і він стає важливою емоційною приманкою, щоб в Оргріммарі прикликати й скорити сукуба.",h="Обліплений брудом амулет — особиста пам'ятка полоненого орка Доґрана.",kw={"амулет","доґран","занкаджа","сукуб","чорнокнижник","тіньова розколина"},ang={["class:Warlock"]="Для чорнокнижників-учнів амулет показує темне мистецтво: як використати смертну скорботу й відданість, щоб повелівати демонами з Викривленого Нижнього Світу.",["race:Orc"]="Амулет утілює гірко-солодкий вибір Доґрана: не бажаючи бути калікою-тягарем для клану й подруги, він пожертвував своєю пам'яткою, аби востаннє стати до бою як воїн."},sec={{t="Трагічна пам'ятка",b="Зламаний воїн Доґран беріг Обліплений брудом амулет під час своїх мук у Пустках: це знак його невисловленої любові до подруги, Занкаджі. Отруєний і покалічений без надії на одужання, Доґран віддав амулет, аби не повертатися до неї тягарем, і вирішив загинути в бою з тими, хто його полонив. Похмуру пам'ятку довірили чорнокнижникові, і той приніс її до Оргріммара, щоб чорнокнижники Тіньової Розколини обернули її важкий тягар розбитого серця й відданості на свою користь."},{t="Приманка для демона",b="У підземних глибинах Тіньової Розколини Ґан'рул Бладай бачить темну силу, вплетену в такі реліквії. Сукуб живиться смертною тугою, коханням і трагедією. Очистивши й відполірувавши амулет Доґрана до блиску, майстер-чорнокнижник перетворює символ відданої любові на нездоланну духовну приманку, що прикликає пожирача душ, якого потім треба скорити в ритуальному бою."}},faq={{q="Звідки береться Обліплений брудом амулет?",a="Амулет віддає Доґран — полонений орк-воїн у Пустках, — після того як ви дасте йому відвар Кен'зіґли, щоб привести його до тями.",al={"походження амулета","де взяти амулет","хто дає амулет"}},{q="Як амулет пов'язаний із Занкаджою?",a="Занкаджа — подруга Доґрана в Оргріммарі. Доґран вирішив віддати амулет і приховати від неї, що вижив, щоб їй не довелося доглядати каліку-воїна.",al={"хто така занкаджа","доґран і занкаджа","значення амулета"}},{q="Чому Ґан'рулу Бладаю потрібен саме цей амулет?",a="Сукубів вабить сильне смертне почуття — особливо кохання, розбите серце й відданість. Очищений амулет Доґрана стає потужним осередком, що притягує сукуба в коло виклику.",al={"навіщо потрібен амулет","принада для сукуби","амулет ґан'рула бладая"}},{q="Що стається, коли амулет доставлено в Оргріммар?",a="Ґан'рул Бладай очищає амулет і, скориставшись його принадою, починає обряд «Прив'язування»: сукуб з'являється в колі під Тіньовою Розколиною, і чорнокнижник має здолати й підкорити його.",al={"що далі з амулетом","що робити з амулетом"}}},fp="18,208,14.494.1,16.409.1,44.143.0,44.169.1,53.196.0,57.184.1"}
P.entries["item:disarming-colloid"] = {n="Знешкоджувальний Колоїд",s="Знешкоджувальний Колоїд — особливий хімічний засіб, створений, щоб приборкати нестійкість вибухового порошку сифоріуму. Його дає дворф Ешлан Стоунсмерк у Багнокраї, і він — ключовий стабілізатор у знешкоджувальній суміші, що має запобігти катастрофічному підриву Каменетесної Греблі.",h="Знешкоджувальний Колоїд — особливий хімічний засіб, створений, щоб приборкати нестійкість вибухового порошку...",kw={"знешкоджувальний колоїд","сифоріум","ешлан стоунсмерк","каменетесна гребля","темне залізо","багнокрай"},ang={["profession:Engineering"]="Інженери впізнають у сифоріумі досконалу вибухову сполуку неймовірної руйнівної сили, яку треба знешкоджувати точними хімічними протизасобами на кшталт цього колоїду, а не грубим механічним розміновуванням.",["race:Dwarf"]="Сифоріум, націлений на Каменетесну Греблю, — пряма загроза шедеврам дворфійської інженерії та безпеці Лох Модану нагорі."},sec={{t="Хімічний нейтралізатор",b="Коли Ешлан Стоунсмерк дослідив незвичний підривний порошок, відібраний у диверсантів Темного Заліза в Багнокраї, він одразу впізнав його за характерним запахом і дрібними срібними кристалами: сифоріум. Цілком сухий, сифоріум нешкідливий, але від зіткнення з вологою стає неймовірно руйнівним — а це смертельна загроза для просякнутої водою Каменетесної Греблі. Щоб спинити реакцію до вибуху, Стоунсмерк дав знешкоджувальний колоїд. Змішаний із трьома особливими місцевими реагентами — отрутою причаєнців, товченим кристалом Мо'ґрош і сльозою кроколіска, — цей колоїд надійно знешкоджує вибухові властивості сифоріуму."}},faq={{q="Для чого потрібен Знешкоджувальний Колоїд?",a="Це основний хімічний засіб, потрібний, щоб знешкодити вибуховий порошок сіфоріум. Змішаний з отрутою причаєного, розтертим кристалом Мо'ґрош і сльозою кроколіска, він гасить нестійку реакцію, яка інакше спричинила б нищівний вибух, щойно сіфоріум намокне.",al={"призначення колоїду","що робить знешкоджувальний колоїд","знешкоджувач сіфоріуму"}},{q="Хто створив чи дав цей колоїд?",a="Знешкоджувальний колоїд дає Ешлан Стоунсмерк — розвідник Альянсу в Багнокраї, що розкрив задум дворфів Темного Заліза підірвати Каменетесну Греблю.",al={"хто дає колоїд","колоїд ашлана"}},{q="Чому сіфоріум такий небезпечний у Багнокраї?",a="Сухий порошок сіфоріуму хімічно інертний, але від вологи стає вкрай вибуховим. Багнокрай просякнутий водою, а мета — сама Каменетесна Гребля, тож будь-який вологий сіфоріум загрожує величезними руйнуваннями.",al={"чому сіфоріум небезпечний","мокрий сіфоріум"}},{q="Кому треба доставити цей колоїд?",a="Ешлан Стоунсмерк велить негайно доправити колоїд і звістку про змову з сіфоріумом просто Головному Інженерові Гіндервіру на Каменетесну Греблю.",al={"кому віднести колоїд","здати колоїд"}}},fp="17,315,22.666.0,35.277.0,37.175.0,46.279.0,38.152.0"}
P.entries["item:disarming-mixture"] = {n="Знешкоджувальна Суміш",s="Знешкоджувальна Суміш — особливе хімічне зілля, яке готує Головний Інженер Гіндервір на Каменетесній Греблі. Створена, щоб нейтралізувати небезпечну сіфоріумну вибухівку, вона не дає диверсантам Темного Заліза зруйнувати велетенську дворфійську споруду, що стримує води Лох Модану.",h="Знешкоджувальна Суміш — особливе хімічне зілля, яке готує Головний Інженер Гіндервір на Каменетесній Греблі.",kw={"знешкоджувальна суміш","гіндервір","каменетесна гребля","темне залізо","вибухівка","ешлан стоунсмерк"},ang={["profession:Engineering"]="Знешкоджувальна Суміш — приклад практичної контрінженерії: швидка хімічна нейтралізація робить небезпечні сіфоріумні заряди нешкідливими, не спричиняючи вибуху.",["race:Dwarf"]="Каменетесна Гребля захищає навколишні долини й низовини, тож швидко застосувати цей нейтралізатор — справа дворфійської безпеки."},sec={{t="Хімічний нейтралізатор",b="Коли диверсанти Темного Заліза заклали під фундамент Каменетесної Греблі важкий сіфоріумний заряд, звичайні способи розмінування були надто ризиковані. Не маючи під рукою підмоги горян, Головний Інженер Гіндервір склав Знешкоджувальну Суміш зі складників, які назвав знавець вибухівки Ешлан Стоунсмерк, щоб швидко знешкодити підводний заряд. Коли розчин вливають просто в закладену порохову бочку, він нейтралізує активні речовини, і замість нищівного вибуху лишається нешкідливе шипуче місиво."}},faq={{q="Для чого потрібна Знешкоджувальна Суміш?",a="Суміш створено, щоб знешкодити велике барило вибухового сіфоріуму, яке повстанці Темного Заліза заклали під водою біля підніжжя Каменетесної Греблі.",al={"що робить знешкоджувальна суміш","використання знешкоджувальної суміші","призначення знешкоджувальної суміші"}},{q="Хто готує Знешкоджувальну Суміш?",a="Головний Інженер Гіндервір, дворф, що відповідає за обслуговування й оборону Каменетесної Греблі, змішує потрібні складники.",al={"хто робить знешкоджувальну суміш","хто дає знешкоджувальну суміш","суміш гіндервейра"}},{q="Навіщо потрібна суміш, а не просто знешкодити бомбу?",a="Сухий порошок сіфоріуму нешкідливий, але мокрий може вибухнути з величезною силою. Хімічна суміш знешкоджує реактивний порошок просто в барилі й усуває загрозу вибуху під водою біля греблі.",al={"чому не знешкодити звичайно","чому хімія на бомбі","навіщо знешкоджувальна суміш"}}},fp="17,297,22.527.0,39.157.0,34.163.0,67.230.0"}
P.entries["item:divined-scroll"] = {n="Сповіщений Сувій",s="Сповіщений Сувій — зачарований пергамент, яким нічні ельфи з Притулку Срібного Вітру викривають джерело збурених вод Ашенвалю. Спрямувавши залишкову магію з уцілілих наручів водяних елементалів, сувій розкриває, хто той свавільний чаклун, що їх викликає.",h="Сповіщений Сувій — зачарований пергамент, яким нічні ельфи з Притулку Срібного Вітру викривають джерело...",kw={"сповіщений сувій","водяні елементалі","озеро містраль","велене старстрайк","маг","ворожіння"},ang={["class:Mage"]="Сувій діє на основоположних засадах вистежування викликань: він показує, що стихійні зв'язувальні чари неминуче несуть незмивний магічний відбиток чарівника, який їх виковав.",["race:NightElf"]="Для вартових, які боронять Ашенваль, ворожильні знаряддя на кшталт цього сувою вкрай важливі, щоб вистежувати смертних забруднювачів, чиє таємне чаклунство загрожує священним водам лісу."},sec={{t="Слідами закликача",b="Отруєні води Озера Містраль давно непокоять вартових, що стережуть Ашенваль. Щоб з'ясувати, хто керує водяними елементалями, які заполонили озеро, Вартова Велене Старстрайк дає мандрівникам незаряджений сувій ворожіння. Якщо зібрати цілі наручі просто з убитих елементалів і використати їх як таємний реагент, приховані в металі зв'язувальні чари перетікають у пергамент. Сповіщений Сувій, що з цього постає, розкриває магічний відбиток свавільного чарівника, який стоїть за навалою."},{t="Викритий маг",b="Щойно сувій наповнюється силою, письмена на Сповіщеному Сувої прямо вказують Вартовій Велене на смертного винуватця: безрозсудного мага, що навмисно отруює чисті лісові озерця. Озброєні знанням, яке відкрив пергамент, вартові можуть готувати відплату й посилати розвідників вистежити закликача, що осквернює їхню священну дику природу."}},faq={{q="Для чого потрібен Сповіщений Сувій?",a="Сповіщений Сувій відкриває, хто саме з чаклунів викликає й прив'язує ворожих водяних елементалів в озерах Ашенвалю, — і Вартова Велене Старстрайк може вдарити просто по винуватцеві.",al={"що робить сповіщений сувій","призначення сповіщеного сувою","навіщо створювати сповіщений сувій"}},{q="Як створюють Сповіщений Сувій?",a="Для цього порожній Сувій Ворожіння, який дає Вартова Велене Старстрайк, застосовують до п'яти Неушкоджених Наручів Елементалів, зібраних із переможених водяних елементалів довкола Озера Містраль.",al={"як створити сповіщений сувій","створення сповіщеного сувою","як отримати сповіщений сувій"}},{q="Навіщо для ворожіння наручі елементалів?",a="Наручі — це фізичні пута, що тримають елементалів у світі смертних. Залишки чарів на них дають сувоєві потрібний магічний відбиток, за яким можна визначити чарівника, що викликав цих істот.",al={"чому цілі наручі","призначення наручів елементалів"}},{q="Кому принести Сповіщений Сувій?",a="Готовий Сповіщений Сувій слід віднести Вартовій Велене Старстрайк у Притулок Срібного Вітру при дорозі на півдні Ашенвалю.",al={"куди здати сповіщений сувій","кому потрібен сповіщений сувій"}}},fp="14,288,20.507.0,16.364.1,36.202.0,34.186.0,58.222.0,37.124.0"}
P.entries["item:divining-scroll"] = {n="Сувій Ворожіння",s="Сувій Ворожіння — зачарований пергамент, який видає Вартова Велене Старстрайк у Притулку Срібного Вітру. Його магія дає змогу простежити магічний відбиток протиприродних водяних елементалів, що заполонили Ашенваль, аж до їхнього творця.",h="Сувій Ворожіння — зачарований пергамент, який видає Вартова Велене Старстрайк у Притулку Срібного Вітру.",kw={"сувій ворожіння","велене старстрайк","притулок срібного вітру","водяні елементалі","ашенваль","маг"},ang={["class:Mage"]="Сувій показує класичну ворожильну магію, що вистежує відлуння таємних сил, і викриває, що такий самий знавець таємної магії зловживає викликанням елементалів у священних гаях калдореїв.",["race:NightElf"]="Для вартових, які оберігають Ашенваль, цей сувій — важливе знаряддя, щоб викривати чужинців, які оскверняють чисті води лісу протиприродною порчею."},sec={{t="Слідами протиприродних елементалів",b="Коли з чистих озер Ашенвалю почали підійматися зіпсовані водяні елементалі, вартові знали: це не природне явище. Вартова Велене Старстрайк здобула цей ворожильний сувій, щоб з'ясувати, хто винен. Пропустивши магію сувою крізь цілі наручі елементалів як фокусувальний реагент, користувач видобуває відбиток закликача, і чистий пергамент перетворюється на Сповіщений Сувій, що називає винуватця."}},faq={{q="Для чого потрібен Сувій Ворожіння?",a="Сувій має з'ясувати, хто створив зіпсованих водяних елементалів, що вдерлися в Ашенваль. Із неушкодженими наручами елементалів як осередком пергамент спрямовує магію ворожіння, зчитує ауру заклинача й записує, хто він.",al={"що робить сувій","призначення сувою ворожіння","навіщо сувій ворожіння"}},{q="Хто дає Сувій Ворожіння?",a="Сувій дає Вартова Велене Старстрайк дослідникам Альянсу в Притулку Срібного Вітру на півдні Ашенвалю, коли розслідує отруєння вод.",al={"хто дає сувій ворожіння","де взяти сувій","сувій велін старстрайк"}},{q="Навіщо потрібні неушкоджені наручі елементалів?",a="Більшість наручів у бою розлітається на друзки. Лише кілька вцілілих зберігають досить залишкових чарів прив'язування від свого викликача, щоб стати справжнім магічним осередком для ворожіння.",al={"чому наручі","цілі наручі елементалів","реагент для сувою"}},{q="Що стається після використання сувою?",a="Сувій, застосований до п'яти неушкоджених наручів, витрачається й стає Сповіщеним Сувоєм. Він відкриває, що маг-ренегат навмисно викликає зіпсованих елементалів в озера лісу.",al={"сповіщений сувій","після використання сувою","у що він перетворюється"}}},fp="15,245,28.456.0,37.231.0,33.165.0,40.205.0,38.207.1"}
P.entries["item:dogran-s-pendant"] = {n="Амулет Доґрана",s="Амулет Доґрана — глибоко особистий талісман пораненого орка Доґрана, пов'язаний із трагедією його розлуки з подругою, Занкаджею. У потаємних колах чорнокнижників Оргріммара сирий емоційний відгомін амулета стає каталізатором, щоб прикликати й скорити сукуба.",h="Амулет Доґрана — глибоко особистий талісман пораненого орка Доґрана, пов'язаний із трагедією його розлуки з...",kw={"амулет доґрана","занкаджа","сукуб","ніру файрблейд","ґан'рул бладай","тіньова розколина"},ang={["class:Warlock"]="Для чорнокнижників Орди Амулет Доґрана — головний талісман, яким вони доводять владу над Нижнім Світом і засвоюють ритуал прикликання сукуба.",["faction:Horde"]="Амулет — символ тихих особистих трагедій, що розгортаються в Пустках і Дуротарі й тісно пов'язані з прихованим ковеном чорнокнижників Оргріммара."},sec={{t="Провідник розбитого серця",b="Амулет Доґрана просякнутий особистим горем: він позначає трагічну долю орка, чию любов до Занкаджі затьмарили полон і каліцтво. Для чорнокнижників Тіньової Розколини такі сильні почуття — не просто рештки скорботи, а магічні провідники. Демони, як-от сукуб, жадібно живляться коханням, тугою й беззахисністю, тож амулет — ідеальна приманка, щоб виманити одного з них крізь Викривлений Нижній Світ у коло прикликання Ніру Файрблейда."},{t="Підкорення й пам'ять",b="Під наглядом Ґан'рула Бладая чорнокнижник-початківець за допомогою амулета прикликає демона, долає його в бою й доводить свою цілковиту владу над його спокусливими хитрощами. Коли ритуал завершено, талісман повертають Ґан'рулові, щоб той передав його Занкаджі, — як суворе нагадування: самовпевненість і зайві почуття швидко коштуватимуть чорнокнижникові душі."}},faq={{q="Для чого потрібен Амулет Доґрана?",a="Він слугує головним реагентом, щоб викликати сукуба в наметі Ніру Файрблейда в Тіньовій Розколині. Коли демона викликано й переможено, амулет треба повернути Ґан'рулу Бладаю.",al={"використання амулета","що робити з амулетом доґрана","завдання амулета доґрана"}},{q="Чому сукуб відгукується на амулет?",a="Сукуб живиться бажанням, коханням і пристрастю та маніпулює ними. Амулет пов'язаний із трагічним коханням Доґрана й Занкаджі, тож його почуттєва вага стає непереборною принадою аж крізь Нижній Світ.",al={"чому сукуба хоче амулет","чому амулет викликає демона","історія амулета"}},{q="Хто такий Доґран?",a="Доґран — орк, чий полон і рани розслідують чорнокнижники Орди через своїх знайомих, як-от Сліпого Казула й Кен'зіґлу. Він глибоко кохає Занкаджу, але не хоче обтяжувати її доглядом за калікою.",al={"хто такий доґран","історія доґрана"}},{q="Що стається з амулетом після обряду виклику?",a="Здолавши викликаного сукуба, чорнокнижник повертає амулет Ґан'рулу Бладаю, щоб той нарешті передав реліквію Занкаджі й поставив крапку в цій історії.",al={"кому дістається амулет","повернути амулет доґрана"}}},fp="16,298,23.477.0,27.383.1,34.196.0,43.209.0,15.226.0,55.150.0"}
P.entries["item:dolanaar-delivery"] = {n="Посилка для Доланаара",s="Посилка для Доланаара — пакунок зібраного зілля, відправлений із друїдських угідь Тінедолу до села Доланаар. Довірений молодим мандрівникам, що покидають затишну долину, він слугує простим дорученням, яке знайомить їх із Корчмарем Келдаміром далі дорогою.",h="Посилка для Доланаара — пакунок зібраного зілля, відправлений із друїдських угідь Тінедолу до села Доланаар.",kw={"посилка","доланаар","зілля","портанніус","корчмар келдамір","тінедол","корчма"},ang={["profession:Herbalism"]="Посилка показує сталий попит на рослини, зібрані довкола Алдрассила, для постачання віддалених поселень Тельдрассила.",["race:NightElf"]="Узяти пакунок — обряд посвяти для молодих калдореїв, що виходять з-під захисного віття Тінедолу в ширший світ."},sec={{t="Клунок із Тінедолу",b="Зібраний у тінистих гаях Алдрассила, цей пакунок містить свіже зілля для поселення Доланаар. Портанніус, затриманий поточними справами серед друїдів Тінедолу, покладається на молодих шукачів пригод, що прямують дорогою на південь, аби ті безпечно доправили клунок Корчмареві Келдаміру."},{t="Ласкаво просимо до вогнища",b="Доставка пакунка приводить мандрівника просто на поріг корчми Доланаара. Келдамір із вдячністю приймає товар і користається нагодою нагадати втомленим подорожнім про потребу відпочинку, душевного спокою й прихистку біля вогнища корчми, перш ніж вони заглибляться в Тельдрассил."}},faq={{q="Що в Посилці для Доланаара?",a="У посилці — добірка свіжих трав, зібраних у Тінедолі, для Корчмаря Келдаміра та відвідувачів корчми в Доланаарі.",al={"які трави всередині","вміст посилки для доланаара","що в пакеті"}},{q="Хто надсилає цю посилку?",a="Портанніус, ельф, що має справи з друїдами в Тінедолі, готує пакунок, але не має часу сам вирушити на південь.",al={"хто дає посилку","хто надіслав трави","посилка портанніуса"}},{q="Хто отримує посилку в Доланаарі?",a="Посилку приносять просто Корчмареві Келдаміру, який тримає спільну корчму в самому серці Доланаара.",al={"кому віднести трави","одержувач посилки доланаара","трави келдаміра"}},{q="Чому Портанніус не доставив посилку сам?",a="У Портанніуса нагальні, незавершені справи з друїдами довкола Алдрассила, тож він просить мандрівного шукача пригод, що прямує лісовою дорогою на південь.",al={"чому портанніус лишився","чому портанніус послав мене"}}},fp="17,266,24.310.0,21.305.0,37.144.0,24.144.0,37.110.0,52.171.0"}
P.entries["item:dragonmaw-war-banner"] = {n="Бойовий Прапор Драконячої Пащі",s="Бойові прапори Драконячої Пащі — похідні стяги, які носять орки цього клану, що окопалися в Багнокраї. Позначені символами клану, вони слугують доказом бою для дворфів-захисників Гавані Менетіл, які прагнуть приборкати дедалі більшу загрозу орків.",h="Бойові прапори Драконячої Пащі — похідні стяги, які носять орки цього клану, що окопалися в Багнокраї.",kw={"бойовий прапор драконячої пащі","драконяча паща","вождь нек'рош","капітан стаутфіст","гавань менетіл","орки"},ang={["faction:Alliance"]="Відбираючи прапори в Драконячої Пащі, ви послаблюєте давнього ворога Альянсу, перш ніж він відновить ту страшну силу, якою володів під час Другої війни.",["race:Dwarf"]="Для дворфів Каз Модану очистити болота від прапорів Драконячої Пащі конче потрібно, щоб торгові шляхи до Гавані Менетіл були вбезпечені від орківських загонів."},sec={{t="Знамена давньої загрози",b="Після Другої війни клан Драконячої Пащі розпався, утративши владу над поневоленими червоними драконами. Розлючені дракони обернулися проти своїх поневолювачів і вигнали вцілілих із Ґрім Батола на східні пагорби. Останнім часом уцілілі орки знову набираються сили під проводом Вождя Нек'роша й піднімають бойові прапори над таборами на північний схід від Гавані Менетіл. Ці грубі, грізні стяги уособлюють і їхню незламну непокору, і пряму загрозу болотяним поселенням."},{t="Доказ перемоги",b="Капітан Стаутфіст, що служить у Гавані Менетіл, доручає шукачам пригод з Альянсу вдарити по болотяних таборах і принести ці прапори. Здобуті в нападників, центуріонів і кістяних вартових, прапори підтверджують дворфійському гарнізонові, що табори Драконячої Пащі планомірно громлять, перш ніж клан зможе влаштувати злагоджені набіги."}},faq={{q="Навіщо Капітанові Стаутфісту ці прапори?",a="Капітанові Стаутфісту потрібні прапори як відчутний доказ того, що шукачі пригод напали на табір Драконячої Пащі на північний схід від Гавані Менетіл і прорідили їхні лави.",al={"навіщо збирати прапори","призначення бойових прапорів","чому стаутфіст хоче прапори"}},{q="Хто носить Бойові Прапори Драконячої Пащі?",a="Прапори носять різні бійці Драконячої Пащі в їхніх таборах у Багнокраї — грабіжники, болотяні бігуни, центуріони, майстри бою, вартові тіней, вартові кісток і сам Вождь Нек'рош.",al={"хто дропає прапор драконячої пащі","де взяти бойові прапори","які орки мають прапори"}},{q="Як орки Драконячої Пащі опинилися в Багнокраї?",a="Наприкінці Другої війни Драконяча Паща втратила владу над полоненими червоними драконами. Звільнені дракони люто полювали на колишніх господарів, і вцілілі орки мусили тікати зі своєї твердині Ґрім Батол і розпорошитися болотами й довколишніми горами.",al={"чому драконяча паща тут","історія драконячої пащі в багнокраї","лор драконячої пащі"}},{q="Хто тепер очолює клан Драконячої Пащі?",a="Клан очолює Вождь Нек'рош, син колишнього вождя Некроса. Нек'рош поклявся помститися червоним драконам, які повстали й убили його батька.",al={"лідер драконячої пащі","хто такий нек'рош","вождь нек'рош"}}},fp="20,264,29.519.0,17.360.0,46.180.0,38.217.0,43.268.0,33.172.0"}
P.entries["item:dried-seeds"] = {n="Сушене Насіння",s="Сушене насіння — мертві лушпайки, які тауренський друїд Тонга Рунтотем дає мандрівникам на Перехресті. Вони слугують дослідним засобом, щоб перевірити незвичну життєдайну силу, що вибулькує з розколин під водами Пусток.",h="Сушене насіння — мертві лушпайки, які тауренський друїд Тонга Рунтотем дає мандрівникам на Перехресті.",kw={"сушене насіння","тонга рунтотем","оази","розколини","друїди","пустки"},ang={["class:Druid"]="Друїди, що вивчають дивне буяння по всіх Пустках, упізнають у цьому мертвому насінні важливе знаряддя, щоб дослідити дикі, неприборкані сили, які виходять із землі.",["faction:Horde"]="Шукачі пригод Орди допомагають Тонзі Рунтотему розгадувати природні загадки, що змінюють сухі ґрунти Пусток."},sec={{t="Насіння й оаза",b="На побіжний погляд це зморщене насіння здається геть неплідним і мертвим. Та в руках Тонги Рунтотема воно — важливе знаряддя друїдських досліджень. Зацікавлений дивними підводними отворами, знайденими в Забутих ставках, Тонга прагне з'ясувати, чи є подібні розколини під Застояною Оазою на південному сході. Занурюючи це мертве насіння в бурхливу розколину, дослідник на власні очі бачить загадкові сили, що струменять оазами Пусток і мають дивовижну здатність пробуджувати життя там, де його вже не мало б бути."}},faq={{q="Для чого потрібне Сушене Насіння?",a="Сушеним Насінням перевіряють чарівні, життєдайні властивості булькотливого розлому глибоко в Застояні. Занурюючи мертве насіння у води розлому, ви з'ясовуєте, чи здатна дивна енергія під оазою оживити рослини.",al={"використання сушеного насіння","що робити із сушеним насінням","призначення сушеного насіння"}},{q="Хто дає Сушене Насіння?",a="Його дає шукачам пригод Тонга Рунтотем — таурен-друїд із Перехрестя в Пустках, що вивчає раптові неприродні спалахи буйної зелені в краї.",al={"хто дає сушене насіння","звідки сушене насіння"}},{q="Де розлом, біля якого його використати?",a="Розлом прихований під водою Застояни на південний схід від Перехрестя в Пустках.",al={"де садити сушене насіння","розлом застійного оазису","булькотливий розлом сушене насіння"}},{q="Що стається, коли насіння занурюють у розлом?",a="Тонга просить покласти мертве насіння в булькотливий розлом і поспостерігати. Те, як воно відгукнеться, і є наслідком його досліду — це з'ясується, коли розслідування триватиме далі.",al={"чи ростуть насінини","результат сушеного насіння"}}},fp="11,247,23.583.1,34.261.0,29.181.0,36.129.0,55.167.1"}
P.entries["item:durnan-s-scalding-mornbrew"] = {n="Гарячий Ранковий Узвар Дурнана",s="Гарячий Ранковий Узвар Дурнана — щойно налитий, обпікаюче гарячий дворфійський напій, призначений для Дурнана Фуркаттера в Долині Холодного Хребта. На морозному гірському повітрі питво швидко холоне, тож його треба чимдуж донести до Анвілмара, поки не вистигло.",h="Гарячий Ранковий Узвар Дурнана — щойно налитий, обпікаюче гарячий дворфійський напій, призначений для Дурнана...",kw={"ранковий узвар","дурнан фуркаттер","гарячий напій","анвілмар","долина холодного хребта","доставка","норі"},ang={["race:Dwarf"]="Для дворфа з Дун Мороґу мало образ гірших, ніж дати доброму елю чи ранковому узвару захолонути на гірському морозі."},sec={{t="Наввипередки з холодом",b="У пронизливому холоді Долини Холодного Хребта мало що зрівняється з кухлем свіжого ранкового узвару, поданого гарячим-гарячим. Коли кур'єр затримується, доставляючи порцію Ґреліну Вайтбірду, свіжий кухоль для Дурнана Фуркаттера в Анвілмарі ризикує вкритися кригою. Дурнан вимагає, щоб його узвар був саме обпікаючим, тож лишається лише кілька хвилин, аби пронести паруючий кухоль засніженою стежкою до гірської зали, поки він геть не вистиг."}},faq={{q="Для кого цей узвар?",a="Узвар призначено для Дурнана Фуркаттера — дворфа, що служить в Анвілмарі в Долині Холодного Хребта.",al={"кому узвар","отримувач узвару дурнана","куди узвар"}},{q="Чому доставити треба так швидко?",a="Крижане повітря Дун Мороґа швидко висмоктує тепло з відкритих кухлів. Дурнан замовив саме гарячий узвар, а прохолодний чи ледь теплий кухоль його аж ніяк не вдовольнить.",al={"чому ліміт часу","узвар холоне","чому поспішати з узваром"}},{q="Звідки починається доставка?",a="Напій передають біля табору Ґреліна Вайтбірда під Анвілмаром, коли кур'єр розуміє, що сам не встигне дістатися до зали з горном.",al={"звідки узвар","хто розливає узвар"}},{q="Що стається, коли Дурнан отримує кухоль?",a="Дурнан одразу робить перерву у своїх справах в Анвілмарі, щоб насолодитися парким напоєм, доки той ще гарячий.",al={"реакція дурнана","здати узвар"}}},fp="26,255,23.436.0,29.112.0,48.170.0,34.152.0,42.124.0"}
P.entries["item:durotar-tiger-fur"] = {n="Хутро Тигра з Дуротара",s="Хутро Тигра з Дуротара здобувають із лютих тигрів, що блукають тропічними Островами Відлуння біля південно-східного узбережжя Дуротару. Тролі Темного Списа значною мірою покладаються на ці шкури, щоб шити ковдри на холод, міцні намети й надійні обладунки, поки їхнє населення біженців невпинно зростає.",h="Хутро Тигра з Дуротара здобувають із лютих тигрів, що блукають тропічними Островами Відлуння біля...",kw={"хутро","тигр","дуротар","острови відлуння","сен'джин","темний спис","шкура"},ang={["class:Hunter"]="Вистежування тигрів Островів Відлуння повторює класичні мисливські обряди тролів і вимагає величезного терпіння й маскування, щоб заскочити цих скрадливих острівних хижаків.",["race:Troll"]="Для Темного Списа здобуття тигрячих шкур — подвійне нагадування: про щоденну боротьбу за виживання в Селі Сен'джин і про болючу втрату законної батьківщини на Островах Відлуння."},sec={{t="Життєво важливий ресурс для Темного Списа",b="У тісному поселенні Село Сен'джин ресурсів вічно бракує. Тролі Темного Списа зважують виживання свого народу проти крихкої екології нового дому, свідомо даючи місцевим тигрячим популяціям розростатися, доки зростання потреб не вимагатиме відстрілу. Густі, міцні шкури тигрів Дуротару ретельно вичиняють на щоденні речі для виживання — від простих захисних обладунків до теплих ковдр, що вкривають плем'я, коли змінюється пора року."},{t="Полювання на Островах Відлуння",b="Щоб здобути ці шкури, треба перетнути відкриту воду до Островів Відлуння — пишного архіпелагу на південь від Дуротару, який Темний Спис колись звав домом, доки відьмак Залазан не вигнав їх звідти. Окрім небезпеки від рабів Залазана, мисливці в густих заростях мають рахуватися з терплячою хижою вдачею самих тигрів. Досвідчені тролі-мисливці на кшталт Вел'ріна Фанга розповідають, як цілими днями нерухомо лежали в джунглях заради єдиного чистого пострілу."}},faq={{q="Де здобувають хутро тигрів із Дуротара?",a="Його збирають, полюючи на тигрів із Дуротара на Островах Відлуння — архіпелазі біля південно-східного узбережжя Дуротару.",al={"де падає хутро тигрів","місце хутра тигра з дуротара","як отримати хутро тигра"}},{q="Навіщо тролям із Села Сен'джин це хутро?",a="Вел'рін Фанг із Села Сен'джин збирає його, щоб забезпечити дедалі більше поселення Темного Спису ковдрами, наметами й захисними шкіряними обладунками, — аби плем'я не бідувало, коли зміниться пора року.",al={"навіщо збирати шкури тигрів","кому потрібне хутро тигра","практична здобич"}},{q="Чому тролі не винищують тигрів?",a="Темний Спис навмисно дає тиграм вільно плодитися й полює лише тоді, коли в громаді закінчуються запаси, а притулку чи одягу бракує для дедалі численнішого племені.",al={"збереження тигрів","чому тролі не винищують тигрів"}}},fp="17,283,34.484.0,22.492.0,38.139.0,53.203.0,41.206.0"}
P.entries["item:duskbat-wing"] = {n="Крило Сутінкового Кажана",s="Крило Сутінкового Кажана — сировина, здобута зі шкірястокрилих кажанів, що снують у мороці довкола Похоронного Подзвону. У злиденному поселенні Відступників ці шкірясті крила збирають, а місцеві кравці перешивають їх на міцну саморобну броню для щойно піднятих солдатів.",h="Крило Сутінкового Кажана — сировина, здобута зі шкірястокрилих кажанів, що снують у мороці довкола...",kw={"крило сутінкового кажана","сутінкові кажани","послушниця елрет","похоронний подзвін","броня","кравецтво"},ang={["profession:Tailoring"]="Послушниця Елрет показує грубе похідне кравецтво, потрібне в Тірісфалі: міцні крила кажанів правлять за замінник шкіри й тканини.",["race:Undead"]="Для щойно пробуджених Відступників збирання цих крил — одне з найперших завдань на виживання, щоб ви не розсипалися на шматки в перших сутичках."},sec={{t="Імпровізований захист у Похоронному Подзвоні",b="Коли нові мерці видряпуються з землі Похоронного Подзвону, вони виходять майже ні з чим, окрім лахміття й крихких кісток. В оточенні безтямних решток Погибелі й ворожої живності новоявлені Відступники мусять нашкребти будь-яке захисне спорядження, яке тільки знайдуть. Послушниця Елрет, якою опікується Жрець Тіні Сарвіс, збирає Крила Сутінкових Кажанів разом із вовчими лапами, щоб зшивати й зміцнювати одяг і броню для щойно піднятих воїнів, перш ніж їх пошлють битися в хащі."}},faq={{q="Для чого потрібні Крила Сутінкового Кажана?",a="У Похоронному Подзвоні Послушниця Елрет разом із лапами падальників використовує крила сутінкових кажанів як сировину, щоб шити, лагодити й зміцнювати обладунки та одяг для щойно пробуджених новобранців-Відступників.",al={"використання крила сутінкового кажана","навіщо крила сутінкового кажана","призначення крил сутінкового кажана"}},{q="Звідки беруться Крила Сутінкового Кажана?",a="Їх знімають із сутінкових кажанів і шолудивих сутінкових кажанів, що мешкають у гаях і на схилах довкола села Похоронний Подзвін у Галявинах Тірісфалю.",al={"де знайти крила сутінкового кажана","джерело крила сутінкового кажана","хто дропає крила сутінкового кажана"}},{q="Хто в Похоронному Подзвоні просить ці крила?",a="Їх просить зібрати Послушниця Елрет, яка доглядає поранених і шиє спорядження під наглядом Жерця Тіні Сарвіса в каплиці Похоронного Подзвону.",al={"кому потрібні крила","здати крило сутінкового кажана","хто дає завдання на крила"}},{q="Чому Відступники шиють обладунки з частин кажанів?",a="У Похоронного Подзвону майже немає ні шляхів постачання, ні звичного виробництва. Місцеві доглядачі мусять добувати цупкі шкури, хутро й шкірясті крила кажанів із тірісфальських хижаків, щоб пошити хоч найпростіший захисний одяг для новобранців, які йдуть у бій.",al={"чому крила кажанів для обладунків","шкіряні обладунки з кажанів відступників"}}},fp="12,287,35.494.0,32.176.0,33.149.0,39.159.0,48.251.0"}
P.entries["item:dusky-crab-cakes"] = {n="Сутінкові Крабові Котлети",s="Сутінкові Крабові Котлети — смачна страва, яку Шеф-кухар Ґруал у Даркширі готує, щоб угамувати нестерпний голод Тремтія. Ця місцева страва має пікантний смак, і зголоднілий Тремтій вважає її вишуканою.",h="Сутінкові Крабові Котлети — смачна страва, яку Шеф-кухар Ґруал у Даркширі готує, щоб угамувати нестерпний...",kw={"сутінкові крабові котлети","шеф-кухар ґруал","тремтій","даркшир","кулінарія","павуки"},ang={["profession:Cooking"]="Котлети Ґруала показують, як винахідливий кухар може приготувати пікантну місцеву страву з того, що є під рукою в Сутінколіссі."},sec={{t="Сумнівний делікатес",b="У похмурому Сутінколіссі свіжих харчів обмаль, і кухарям доводиться обходитися тим м'ясом, яке дає потемнілий ліс. Коли наляканого волоцюгу Тремтія скручує від голоду, Шеф-кухар Ґруал нашвидку готує партію своїх фірмових «крабових» котлет. Чужинцеві страва здасться звичайною котлеткою з морепродуктів, але таємний інгредієнт Ґруала куди менш апетитний: жилаві, слизькі ноги жахливих павуків Сутінколісся. Зголоднілий Тремтій умить змітає котлети, навіть не здогадуючись, що насправді їсть."}},faq={{q="З чого насправді зроблені Сутінкові Крабові Котлети?",a="Шеф-кухар Ґруал тримає рецепт своєї фірмової страви в таємниці. Що за таємний складник, з'ясовується, коли збирати для нього припаси в Сутінколіссі.",al={"склад сутінкових крабових котлет","що в сутінкових крабових котлетах","павуче м'ясо"}},{q="Хто їсть Сутінкові Крабові Котлети?",a="Котлети готують для Тремтія — неспокійного чоловіка, що ховається на Воронячому Пагорбі й скаржиться, що в нього страшенно бурчить у животі.",al={"кому котлети","для кого ці котлети","їжа тремтія"}},{q="Як Тремтій реагує на котлети?",a="Тремтій страшенно голодний і радо проковтує котлети, не розпитуючи про рецепт, — йому досить, що вони смачні й ситні.",al={"реакція тремтія","чи тремтію смакують котлети"}},{q="Хто готує Сутінкові Крабові Котлети?",a="Шеф-кухар Ґруал, місцевий кухар Таверни «Багряний Крук» у Даркширі, готує страву з припасів, які для нього зібрали.",al={"хто готує крабові котлети","кухар ґруал","кухар даркшира"}}},fp="16,208,23.544.1,43.137.0,30.128.0,36.119.0,31.121.0"}
P.entries["item:dust-devil-debris"] = {n="Уламки Пилового Демона",s="Уламки Пилового Демона — вихрястий пісок і стихійні рештки, які лишаються від агресивних духів повітря, що блукають Вестфолом. Маги цінують ці заряджені частинки як магічні реагенти: повітряна есенція допомагає зачаровувати пергамент і вплітати в сувої закляття для послань.",h="Уламки Пилового Демона — вихрястий пісок і стихійні рештки, які лишаються від агресивних духів повітря, що...",kw={"уламки пилового демона","пилові демони","вестфол","коллін маурен","елементалі","сувої"},ang={["class:Mage"]="Уламки Пилового Демона показують, як стихійні рештки можна спрямувати в практичні закляття для письма й зв'язку, поєднавши дикий хаос стихій із вишколеною таємною дисципліною."},sec={{t="Повітря, вплетене в пергамент",b="Сухі рівнини Вестфолу дедалі неспокійніші: їх терзають люті вихори, відомі як Пилові Демони. Коли таку живу бурю повалити, вона розсипається купою зарядженого пилу й піску — Уламками Пилового Демона. Це не просто бруд: рештки зберігають ледь відчутний слід стихійного вихору, що дав їм життя. Знавці таємної магії, як-от Коллін Маурен у Стормвінді, цінують такий матеріал для особливих чарів. Додавши пісок до зачарованого чорнила й пергаменту, чарівник може вплести в сувій повітряне закляття-послання й передавати вісті на далекі відстані по всьому королівству."}},faq={{q="Для чого потрібні Уламки Пилового Демона?",a="Коллін Маурен, чарівник із Кварталу магів Стормвінда, потребує цих стихійних решток, щоб виготовити особливий сувій для послань. Стихійна енергія, що лишилася в пилу, дає йому змогу накласти на папір тонкі чари зв'язку.",al={"використання уламків пилового демона","навіщо уламки пилового демона","призначення уламків"}},{q="Звідки беруться ці уламки?",a="Їх збирають з решток Пилових Демонів — ворожих повітряних елементалів, що блукають спустошеними полями й дорогами Вестфолу.",al={"де знайти уламки","дроп пилових демонів","уламки вестфолла"}},{q="Чим небезпечні Пилові Демони?",a="Це ворожі повітряні елементалі, що блукають Вестфолом. Коллін Маурен попереджає: щоб зібрати їхні уламки, доведеться зійтися з небезпечними істотами.",al={"чому елементалі у вестфоллі","походження пилових демонів вестфолла"}},{q="Хто такий Коллін Маурен?",a="Коллін Маурен — маг-людина з Кварталу магів у Стормвінді. Своїм знанням таємної магії він допомагає виготовляти зачаровані сувої й магічні складники для інших чародіїв і цікавих дослідників.",al={"коллін маурен","хто хоче уламки"}}},fp="17,275,23.592.0,35.248.0,33.125.0,30.136.0,21.207.0"}
P.entries["item:dwarven-tinder"] = {n="Дворфський Трут",s="Дворфський трут — особливо приготована горюча речовина, якою користуються сили Альянсу в Багнокраї. Його роздали диверсантам, яким доручили спалити облогові машини клану Драконячої Пащі, перш ніж їх кинуть проти Гавані Менетіл.",h="Дворфський трут — особливо приготована горюча речовина, якою користуються сили Альянсу в Багнокраї.",kw={"дворфський трут","драконяча паща","катапульти","вождь нек'рош","гавань менетіл","диверсія"},ang={["faction:Alliance"]="Поки за перевали Дун Алґазу точаться бої, спалити ворожі бойові машини, перш ніж вони дістануться Гавані Менетіл, конче потрібно, щоб головний болотяний порт Альянсу вистояв.",["race:Dwarf"]="Дворфійські інженери й розвідники знають ціну надійному кресалу — особливо у вічно мокрих, залитих дощами болотах Багнокраю."},sec={{t="Диверсія проти Драконячої Пащі",b="Коли розвідники Альянсу виявили, що Вождь Нек'рош збудував у таборі Драконячої Пащі важкі катапульти, над Гаванню Менетіл нависла неминуча криза. Відрізані запеклими боями в Дун Алґазі від підкріплень із півдня, захисники не витримали б тривалої облоги. Вихід був один — диверсія на випередження. Дворфський трут, який роздають добровольцям, що вирушають на землі орків, займається від однієї іскри й дає полум'я, досить жарке, щоб за лічені хвилини поглинути укріплені дерев'яні облогові машини."}},faq={{q="Для чого потрібен Дворфський Трут?",a="Дворфським Трутом підпалюють і знищують облогові катапульти, які клан Драконячої Пащі збудував у Багнокраї, щоб не допустити артилерійського удару по Гавані Менетіл.",al={"призначення дворфського трута","навіщо дворфський трут","що робить дворфський трут"}},{q="Чому катапульти палять, а не захоплюють?",a="Гарнізон Гавані Менетіл значно поступається числом ворогові й відрізаний від підкріплень з Айронфорджа через блокаду в Дун Алґазі. У захисників просто немає людей, щоб захопити чи вивезти важкі облогові машини з глибини ворожих земель Драконячої Пащі, тож знищення — єдиний можливий захист.",al={"чому знищити катапульти","чому не захопити облогові машини"}},{q="Хто приготував цей трут?",a="Трут дає дворфський гарнізон Гавані Менетіл — його приготовано саме для того, щоб швидко й надійно підпалювати під час диверсійних вилазок.",al={"хто приготував трут","звідки дворфський трут"}}},fp="14,245,24.517.0,32.161.0,49.289.0,25.158.0"}
P.entries["item:ear-of-balgaras"] = {n="Вухо Балґараса",s="Вухо Балґараса — похмурий доказ смерті Балґараса Мерзенного, чорнокнижника Темного Заліза, що очолив напад на Дун Модр. Здобуте з тіла боягузливого командира, воно дає горянам Айронфорджа, що боронять північ Багнокраю, змогу поставити крапку в цій історії.",h="Вухо Балґараса — похмурий доказ смерті Балґараса Мерзенного, чорнокнижника Темного Заліза, що очолив напад на...",kw={"вухо балґараса","балґарас мерзенний","дун модр","лонґбрейд похмурий","темне залізо","міст тандол"},ang={["class:Warlock"]="Балґарас орудував тінню й мистецтвом скверни з укриття, тож перемога над ним — це покарання збоченого чаклуна, що приніс загибель північній дорозі.",["race:Dwarf"]="Для дворфів Айронфорджа здобути це вухо — означає звести кривавий рахунок за родичів, вирізаних під час диверсії на Мосту Тандол."},sec={{t="Похмурий трофей",b="Дун Модр обернувся на руїни, коли загарбники з Темного Заліза підірвали Міст Тандол і вирізали місцевий дворфійський гарнізон. Ними на полі бою командував Балґарас Мерзенний — підступний чорнокнижник, що керував військами з тіні й уникав особистого бою. Для Лонґбрейда Похмурого, офіцера гірського короля, що стоїть табором біля зруйнованої застави, справедливість вимагала відчутного доказу загибелі призвідця. Відтяте вухо Балґараса — беззаперечне підтвердження того, що влада терору чорнокнижника на північному кордоні скінчилася."},{t="Справедливість для полеглих",b="Утрата Дун Модра коштувала Лонґбрейдові брата й десятків хоробрих вояків, що загинули, коли обвалився Західний міст. Принесене вухо чорнокнижника не відбудує зруйнований міст і не поверне полеглих, але воно розхитує рештки сил Темного Заліза, розкидані північчю Багнокраю. Без Балґараса, що ними керував, уцілілих нападників розвідникам Айронфорджа куди легше стримувати, доки з півдня не пришлють нового командира."}},faq={{q="Хто такий Балґарас Мерзенний?",a="Балґарас Мерзенний — дворф-чорнокнижник із Темного Заліза, що командував загоном, який напав на Дун Модр і зруйнував західну частину Мосту Тандол. Він славився боягузтвом: посилав хвилю за хвилею воїнів на смерть, а сам ховався від патрулів Альянсу.",al={"хто такий балґарас","історія балґараса","балґарас мерзенний"}},{q="Чому Лонґбрейді Похмурому потрібне саме його вухо?",a="Лонґбрейда Похмурий хотів незаперечного доказу, що невловимого чорнокнижника справді вбито. Відтяте вухо — класичний прикордонний трофей: воно засвідчує виконання угоди, і не треба тягти весь труп до дворфського табору.",al={"чому саме вухо","навіщо відрізати вухо","доказ для лонґбрейда"}},{q="Що стається з Темним Залізом після смерті Балґараса?",a="Утративши розважливого ватажка, уцілілі сили Темного Заліза в Дун Модрі втрачають згуртованість. Вони й далі никають руїнами, але Лонґбрейда вважає, що вони вже досить розпорошені, тож Альянс упорається з ними, перш ніж вороги Айронфорджа пришлють нового командира.",al={"що буде після смерті балґараса","темне залізо в дан модрі"}}},fp="15,257,13.544.0,22.468.0,26.262.0,54.246.0,53.265.0"}
P.entries["item:ebonlocke-s-response-to-solomon"] = {n="Відповідь Ебонлока Соломону",s="Відповідь Ебонлока Соломону — офіційний лист, написаний Лордом Елло Ебонлоком, мером Даркшира. Доставлений до Лейкшира, він навідріз відхиляє відчайдушне прохання Редріджу про військову допомогу Нічної Варти.",h="Відповідь Ебонлока Соломону — офіційний лист, написаний Лордом Елло Ебонлоком, мером Даркшира.",kw={"відповідь ебонлока соломону","елло ебонлок","магістрат соломон","лейкшир","даркшир","нічна варта"},ang={["faction:Alliance"]="Лист показує, як розвалюється саме серце Альянсу: Редрідж, Сутінколісся й Вестфол — усіх їх королівський двір Стормвінда пустив за течією."},sec={{t="Гірка відмова",b="Потерпаючи від набігів орків Блекрок, Магістрат Соломон із Лейкшира попросив підкріплення в Сутінколісся, бо Стормвінд знехтував його проханнями. Відповідь Лорда Елло Ебонлока їдка й непохитна. Ебонлок нагадує, що Нічна Варта існує лише тому, що Стормвінд покинув Даркшир напризволяще, коли ліс уперше охопила спотворювальна магія. Позбавити місто захисників заради допомоги Редріджу означало б лишити Сутінколісся беззахисним — і зло поглинуло б його ще до того, як ополченці дійшли б до узлісся."},{t="Прикордоння, що розсипається",b="Лист глибоко вражає Соломона. Армія Стормвінда пішла з Вестфолу, королівської варти немає в Даркширі — усе південне прикордоння королівства покинуте гнити. Соломон не відмахується від гніву Ебонлока, а бачить у ньому жахливу закономірність: раптова байдужість Корони до віддалених земель свідчить про зраду на найвищих щаблях влади в Стормвінді."}},faq={{q="Що таке Відповідь Ебонлока Соломону?",a="Це запечатаний лист Лорда Елло Ебонлока з Даркшира до Магістрата Соломона з Лейкширу. У ньому Ебонлок відмовляється послати Нічну Варту на захист Редріджу, пояснюючи, що Сутінколісся ледве стримує власні жахіття.",al={"лист ебонлока","відповідь ебонлока","лист до соломона"}},{q="Чому Даркшир не пошле допомогу Лейкширу?",a="У Даркширі немає власних королівських військ. Нічну Варту зібрали винятково з місцевих добровольців, бо Стормвінд покинув край напризволяще. Лорд Ебонлок попереджає: якщо його вартові підуть, Даркшир заполонять нежить і мерзенні потвори ще до того, як вони вийдуть із лісу.",al={"чому нічна варта не допоможе","чому даркшир відмовив","ебонлок відмовив соломону"}},{q="Як Магістрат Соломон сприймає лист?",a="Магістрат Соломон приголомшений і стривожений. Дізнавшись, що королівська варта покинула Даркшир — так само, як військо пішло з Вестфолу, — він переконується, що керівництво Стормвінда паралізоване якоюсь підступною грою чи зрадою.",al={"реакція соломона","що каже соломон"}},{q="Хто написав цей лист?",a="Лист написав Лорд Елло Ебонлок — змучений бургомістр Даркшира й голова Ради Даркшира, що відповідає за оборону міста.",al={"хто такий ебонлок","лорд ебонлок"}}},fp="31,225,16.500.0,22.425.1,40.249.0,43.286.0,48.223.1,22.153.0"}
P.entries["item:echeyakee-s-hide"] = {n="Шкіра Ечеякі",s="Шкіра Ечеякі — бліда шкура легендарного білого лева, знаного як Біла Імла, з Пусток. Таурени шанують цього звіра як втілення милосердя й смерті, а шкура — доказ майстерності мисливця для Серґри Даркторн на Перехресті.",h="Шкіра Ечеякі — бліда шкура легендарного білого лева, знаного як Біла Імла, з Пусток.",kw={"шкіра ечеякі","ечеякі","біла імла","білий лев","серґра даркторн","полювання"},ang={["class:Hunter"]="Здобути шкуру верховного хижака савани — один із перших обрядів посвяти для слідопитів Орди, що прагнуть опанувати тонкощі дикої природи.",["race:Tauren"]="Для тауренів полювання на Ечеякі — священне випробування милосердя й потайності: так шанують швидкий дух Білої Імли, а не прагнуть простої перемоги."},sec={{t="Трофей Білої Імли",b="Мовою таур-ае «Ечеякі» означає «Біла Імла». Хижак здобув це ім'я серед левів савани за свою потайну білу шерсть і за те, як швидко він повалював здобич, обриваючи її життя раніше, ніж її встигали охопити страх чи біль. Щоб здобути шкуру звіра, треба викликати невловиму кішку обрядовим рогом біля велетенських кісток кодо на північний схід від Перехрестя. Принести цю шкуру Серґрі Даркторн — означає не лише довести бойову вправність, а й ушанувати тихий, милосердний кінець хижака."}},faq={{q="Звідки береться Шкіра Ечеякі?",a="Шкіру здобувають, убивши Ечеякі — білого лева, що має лігво серед велетенських скелетів кодо на північний схід від Перехрестя в Пустках. Щоб його викликати, потрібен Ріг Ечеякі, який дає Серґра Даркторн.",al={"де взяти шкіру ечеякі","як отримати шкіру ечеякі","місце шкури ечеякі"}},{q="Кому потрібна Шкіра Ечеякі?",a="Серґра Даркторн, орчиха-мисливиця з Перехрестя, доручає молодим мисливцям Орди вистежити великого кота й принести його шкуру на доказ свого зв'язку з дикою природою.",al={"хто здає шкіру ечеякі","здати шкіру ечеякі","кому потрібна шкіра ечеякі"}},{q="Що означає ім'я Ечеякі?",a="Мовою тауренів «Ечеякі» означає «Білий Туман». Ім'я вшановує бліде хутро звіра та віру в те, що він сунув саваною, наче туман, і вбивав, не завдаючи тривалого жаху чи мук.",al={"переклад ечеякі","значення ечеякі","ім'я тауренів ечеякі"}}},fp="16,250,19.499.0,38.216.0,27.183.0,34.217.0"}
P.entries["item:egalin-s-grimoire"] = {n="Гримуар Еґаліна",s="Гримуар Еґаліна — цінний магічний фоліант, що описує основні обряди виклику блукача Порожнечі й керування ним. Написаний майстром-чорнокнижником, він служить важливим підручником у Храмі Проклятих в Андерсіті.",h="Гримуар Еґаліна — цінний магічний фоліант, що описує основні обряди виклику блукача Порожнечі й керування ним.",kw={"гримуар еґаліна","блукач порожнечі","чорнокнижник","карендін галґар","багряний хрестовий похід","галявини тірісфалю","храм проклятих"},ang={["class:Warlock"]="Гримуар Еґаліна містить точні прийоми, щоб вирвати блукача Порожнечі з Нижнього Світу й підкорити його своїй волі, — це важливий обряд посвяти для кожного чорнокнижника.",["race:Undead"]="Повернувши книгу, ви не даєте фанатикам Багряного Хрестового Походу втримати могутній магічний артефакт, викрадений просто в чорнокнижників Андерсіті."},sec={{t="Праця майстра",b="Цей гримуар, написаний майстром виклику Еґаліном, докладно описує тонкий і небезпечний процес — як вирвати створіння хаосу з Нижнього Світу. Еґалін славився серед чорнокнижників тим, як легко керував викликаними блукачами Порожнечі, і передав цей дар своїм учням, серед них і Карендінові Галґару. Без особливих формул і способів спрямування сили, записаних у книзі, непідготовленого заклинача може розірвати на шматки та сама істота, яку він кличе."},{t="Багряна крадіжка",b="Гримуар у чорнокнижників-Відступників викрав агент Багряного Хрестового Походу на ім'я Перрін і сховав його в скрині у вежі на заході Галявин Тірісфалю. Хоч фанатики й ненавидять темну магію, злодій, схоже, не розумів справжньої ваги книги: для нього це була лише конфіскована єретична здобич — доки гримуар не повернули учні-Відступники, що прагнуть опанувати Порожнечу."}},faq={{q="Хто такий Еґалін?",a="Еґалін — надзвичайно обдарований чорнокнижник і наставник Карендіна Галґара. Його пам'ятають як першого з них, хто викликав блукача Порожнечі, і як того, хто з цілковитою легкістю керував істотами хаосу.",al={"хто такий еґалін","історія еґаліна","хто написав гримуар"}},{q="Чим небезпечний Гримуар Еґаліна?",a="У книзі — закляття й способи спрямування сили, потрібні, щоб викликати блукача Порожнечі. Якщо чорнокнижник спробує провести обряд, не опанувавши як слід цих настанов, викликана сутність Порожнечі розірве його на шматки.",al={"що робить гримуар","книга пустоходців небезпека","чому небезпечний"}},{q="Як книга потрапила до Багряного Хрестового Походу?",a="Агент Багряного Хрестового Походу на ім'я Перрін зумів викрасти том у чорнокнижників-Відступників. Він замкнув його в скрині на сторожовій вежі Походу на заході Галявин Тірісфалю, схоже, навіть не здогадуючись про справжню магічну цінність книги.",al={"хто вкрав книгу","гримуар перрін","чому хрестоносці його мають"}},{q="Кому треба повернути цей гримуар?",a="Гримуар потрібен Карендіну Галґару, наставникові чорнокнижників у Храмі Проклятих під Андерсіті, щоб навчити новачків викликати й прив'язувати блукачів Порожнечі.",al={"кому віддати гримуар","хто хоче гримуар","книга карендіна гелґара"}}},fp="17,232,15.458.0,17.409.1,15.206.0,38.215.0,41.221.0,33.177.0"}
P.entries["item:electropeller"] = {n="Електропеллер",s="Електропеллер — особлива механічна деталь, яку сконструював гном-винахідник Візбанґ Кранктоґґл. Вона мала рухати вибухову качку-приманку, але цілий мішок цих пристроїв загубився в прісних річках Темного Узбережжя під час невдалої нічної вилазки.",h="Електропеллер — особлива механічна деталь, яку сконструював гном-винахідник Візбанґ Кранктоґґл.",kw={"електропеллер","візбанґ кранктоґґл","гноми","інженерія","темне узбережжя","качка-приманка"},ang={["profession:Engineering"]="Електропеллер — класична гномська вигадка: амбітна, моторизована й небезпечна; пристрій для вибухової качки-приманки опинився в річці, так і не пройшовши жодного справжнього випробування.",["race:Gnome"]="Візбанґ Кранктоґґл гідно продовжує гномську традицію поєднувати шалені технічні амбіції з неймовірними халепами — і радо просить рибалок, що проходять повз, урятувати плоди його нічних експериментів."},sec={{t="Пригоди на березі річки",b="Гномська інженерія вимагає точності, але її винахідники не завжди такі вже методичні. Візбанґ Кранктоґґл, ексцентричний гном, що працює в Обердайні, вигадав електропеллер як рушій для дослідної самохідної вибухової качки-приманки. Оглядаючи водойми Темного Узбережжя після кількох зайвих чарок, Кранктоґґл знепритомнів і прийшов до тями лише за кілька годин — з обсмаленим волоссям і порожньою торбою. Його електропеллери попадали в прісні течії й розсипалися річками та озерами Темного Узбережжя, звідки їх тепер виловлюють терплячі рибалки."}},faq={{q="Для чого потрібен електропеллер?",a="Електропеллери — моторні рушійні механізми, які сконструював Візбанґ Кранктоґґл. Він винайшов їх спеціально для експериментальної самохідної вибухової качки-приманки, над якою працював на Темному Узбережжі.",al={"призначення електропеллера","що робить електропеллер","навіщо качина принада"}},{q="Як ці деталі опинилися в річках Темного Узбережжя?",a="Візбанґ Кранктоґґл, трохи напідпитку, блукав уночі Темним Узбережжям у пошуках водойми для випробувань. Він знепритомнів і прокинувся вже в Обердайні з обсмаленим волоссям — а весь мішок деталей ненароком упустив у прісні потоки.",al={"чому у воді","як загубили електропеллери","помилка кранктоґла"}},{q="Де можна знайти електропеллери?",a="Вони дрейфують у прісних водоймах углибині Темного Узбережжя — зокрема в Річці Скельного Джерела та Річці Дикого Закруту, — і щасливі рибалки можуть витягти їх із води.",al={"де ловити електропеллери","місця електропеллерів","риболовля у кліффспрінг"}},{q="Кому треба повернути ці деталі?",a="Візбанґу Кранктоґґлу, гномові з Обердайна: йому потрібно дванадцять електропеллерів, щоб продовжити досліди з приманкою.",al={"кому потрібні електропеллери","хто такий кранктоґл","завдання гнома в обердайні"}}},fp="13,268,27.638.0,34.208.0,54.254.0,38.162.0,36.121.0"}
P.entries["item:elixir-of-pain"] = {n="Еліксир Болю",s="Еліксир Болю — експериментальне алхімічне вариво, яке варять аптекарі-Відступники в Таррен Міллі. Перегнана з крові, зібраної по всьому передгір'ю, суміш призначена для випробування біологічних засобів, що мають служити темнішим задумам Леді Сильвани.",h="Еліксир Болю — експериментальне алхімічне вариво, яке варять аптекарі-Відступники в Таррен Міллі.",kw={"еліксир болю","таррен мілл","аптекарі","стенлі","фермер рей","поля гілсбреду"},ang={["faction:Horde"]="Союзників Відступників часто кличуть допомагати в цих похмурих випробуваннях, і вони на власні очі бачать тривожні методи дослідників Таррен Мілла.",["race:Undead"]="Безсердечні польові випробування Королівського Аптекарського Товариства показують, що Відступники готові вдатися до будь-яких засобів, аби створити хімічну зброю проти живих."},sec={{t="Аптекарські досліди",b="Королівське Аптекарське Товариство невпинно шукає нових формул, щоб зміцнити становище Відступників проти їхніх смертних сусідів і Погибелі. Еліксир Болю — одна з таких спроб, змішана зі свіжозібраних складників із Передгір'я Гілсбреда. Зварене без жодної уваги до живих, це зілля доводить дієвість нестійких речовин, що мають допомогти Темній Леді."},{t="Польові випробування на Стенлі",b="Не бажаючи ризикувати цінними військовими силами чи передчасно викривати свою діяльність перед захисниками Гілсбреда, аптекарі шукають непомітного піддослідного. Еліксир згодовують Стенлі — на вигляд безневинному домашньому псові Фермера Рея з північного хутора на Полях Гілсбреду. Замість тихої смерті отруйне вариво жорстоко змутовує бідолашну тварину, перетворюючи її на розлюченого вовка-потвору."}},faq={{q="Для чого Еліксир Болю?",a="Еліксир Болю — експериментальне зілля, створене, щоб випробовувати живі складники для Королівського Аптекарського Товариства. Його творці сподіваються, що такі суміші врешті дадуть нищівні отрути на службу Леді Сильвані й забезпечать панування Відступників.",al={"навіщо еліксир болю","призначення еліксиру","що робить еліксир"}},{q="Хто такий Стенлі?",a="Стенлі — пес Фермера Рея з північного хутора на Полях Гілсбреду. Аптекарі-Відступники обирають його як нічого не підозрюваного піддослідного, щоб побачити, як щойно зварений еліксир діє на тіло.",al={"хто такий стенлі","фермер рей пес","пес стенлі"}},{q="Чому еліксир випробовують на Стенлі?",a="Аптекар Лайдон хоче перевірити щойно змішаний еліксир у польових умовах і посилає його песикові Фермера Рея, Стенлі, щоб подивитися, як тварина зреагує.",al={"що буде зі стенлі","чи помре стенлі","перетворення стенлі на вовка"}},{q="Де випробовують еліксир?",a="Випробування відбувається біля північного хутора на Полях Гілсбреду, на південний захід від Таррен Мілла. Стенлі зазвичай відпочиває біля ґанку будинку Фермера Рея.",al={"куди нести еліксир","місце стенлі","ферма фермера рея"}}},fp="14,273,26.416.0,24.395.1,42.247.0,15.223.0,36.141.1,27.178.0"}
P.entries["item:elixir-of-suffering"] = {n="Еліксир Страждання",s="Еліксир Страждання — алхімічне вариво, яке варить Аптекар Лайдон у Таррен Міллі. Створений за наказом Королівського Аптекарського Товариства, цей напій — експериментальний крок до заразної чуми, що має знищити і живих людей, і Погибель.",h="Еліксир Страждання — алхімічне вариво, яке варить Аптекар Лайдон у Таррен Міллі.",kw={"еліксир страждання","аптекар лайдон","таррен мілл","нова чума","умпі","королівське аптекарське товариство"},ang={["race:Undead"]="Королівське Аптекарське Товариство працює по всьому Лордерону, щоб створити зброю, яка забезпечить Відступникам незалежність і від Погибелі, і від живого людства, а отруйні досліди Лайдона в Таррен Міллі — важливий крок до цього."},sec={{t="Аптекарські досліди",b="У зруйнованому селищі Таррен Мілл Аптекар Лайдон невтомно змішує сирі складники, зібрані в довколишніх диких краях, в отруйні напої. Еліксир Страждання — ранній етап у виконанні головного доручення Королівського Аптекарського Товариства: створити нову чуму, що винищить і живих, і мертвих. Лайдон випробовує смертоносне вариво на своєму нещасному помічникові — ропусі на ім'я Умпі, — щоб переконатися в його дієвості."}},faq={{q="Для чого Еліксир Страждання?",a="Еліксир — експериментальне зілля, яке Аптекар Лайдон варить у межах досліджень Королівського Аптекарського Товариства. Ним перевіряють смертоносні складники для нової чуми Відступників — проти людей і Погибелі.",al={"навіщо еліксир страждання","що робить еліксир","призначення еліксиру страждання"}},{q="Хто такий Умпі?",a="Умпі — звичайнісінька жаба, яку тримає Аптекар Лайдон у Таррен Міллі. Хоч його жартома й називають помічником, насправді Умпі здебільшого слугує мимовільним піддослідним для щойно зварених алхімічних отрут.",al={"хто такий умпі","хто жаба","помічник лайдона"}},{q="Що стається, коли Умпі випиває еліксир?",a="Скуштувавши Еліксиру Страждання, бідолашна жаба востаннє квакає й майже миттєво гине від отрути — це доводить смертоносну дієвість рецепта Аптекаря Лайдона.",al={"чи вмре умпі","що буде з жабою"}}},fp="19,273,26.437.0,47.232.0,12.202.0,41.186.1"}
P.entries["item:elune-s-tear"] = {n="Сльоза Елуни",s="Сльоза Елуни — рідкісний сяйливий мінерал, який знаходять на центральному острові Озера Ірисів в Ашенвалі. Шануючи його як священне благословення Богині Місяця, травники й цілителі нічних ельфів шукають цей камінь за його могутню здатність очищати від магічної порчі та смертельних недуг.",h="Сльоза Елуни — рідкісний сяйливий мінерал, який знаходять на центральному острові Озера Ірисів в Ашенвалі.",kw={"сльоза елуни","озеро ірисів","релара вайтмун","орендил броудліф","зцілення","елуна"},ang={["class:Priest"]="Шанувальники Світла й Місяця бачать у камені вроджену силу очищати від тіні й гнилі — втілення цілющих див, які приписують Жрецтву Елуни.",["race:NightElf"]="Для нічних ельфів реліквії, що носять ім'я Елуни, — священні дари. Урятувати каменем невинну дитину — це вияв одвічного зв'язку між калдореями та цілющою благодаттю Матері-Місяця."},sec={{t="Священний очисний камінь",b="Сльоза Елуни, захована на невеликому острівці посеред Озера Ірисів на схід від Астранаару, — містичний камінь, у якому, як вірять, живе чистота самої Богині Місяця. Води довкола й сам острів часто відвідують місцеві водяні елементалі, яких вабить природна магія цього місця. Камінь славиться серед місцевих травників і цілителів нічних ельфів — як-от Орендила Броудліфа — як невідкладний засіб, здатний змити глибоко вкорінену порчу, коли звичайні лісові припарки безсилі."},{t="Відчайдушні ліки",b="Коли загадкова виснажлива хвороба спіткала юну нічну ельфійку Релару Вайтмун в Астранаарі, її батько Пелтурас перепробував усі звичайні ліки. За порадою аптекаря Орендила Пелтурас шукає Сльозу Елуни, щоб зварити з неї цілющий відвар. Камінь дає негайну надію в боротьбі з дивною недугою, проте вперта порча, що мучить Ашенваль, часто вимагає ще потужніших обрядів очищення."}},faq={{q="Що таке Сльоза Елуни?",a="Сльоза Елуни — рідкісний чарівний мінерал, що лежить на острівці Озера Ірисів в Ашенвалі. Нічні ельфи шанують її як священну реліквію, сповнену очисного дотику Елуни, і використовують передусім, щоб зцілювати неприродну скверну й люті хвороби.",al={"сльоза елуни","що це за камінь","що робить сльоза елуни"}},{q="Де знайти Сльозу Елуни?",a="Сльоза лежить на острові посеред Озера Ірисів, на схід від Астранаару в центрі Ашенвалю. Дістатися туди можна, звернувши з головного шляху на північ стежкою вздовж струмка.",al={"де сльоза елуни","місце каменю озера ірисів","знайти сльозу елуни"}},{q="Навіщо Пелтурасу Вайтмуну сльоза?",a="Пелтурас шукає сльозу, щоб урятувати хвору доньку, Релару. Звичайні трав'яні ліки не здатні спинити неприродну недугу, що підточує її тіло, тож аптекар Орендил радить: лише цілюща чистота каменя може очистити хворобу.",al={"чому пелтурас хоче її","ліки релари","кому потрібна сльоза елуни"}},{q="Що стереже камінь на Озері Ірисів?",a="На острові й у водах Озера Ірисів живуть водяні елементалі, що ревно бережуть свою територію: їх вабить чиста, зачарована течія довкола священного острова.",al={"вороги озера ірисів","що охороняє сльозу елуни"}}},fp="12,271,24.489.0,18.415.1,21.239.0,32.187.0,42.255.0,35.171.0"}
P.entries["item:embalming-ichor"] = {n="Бальзамувальний Іхор",s="Бальзамувальний Іхор — неприродна консервувальна рідина, добута з тіл гнолів Гнилошкірих на півночі Галявин Тірісфалю. Вона підтримує оживлене існування гнолів і привернула пильну увагу аптекарів Відступників, які прагнуть дослідити її властивості, щоб протистояти Погибелі.",h="Бальзамувальний Іхор — неприродна консервувальна рідина, добута з тіл гнолів Гнилошкірих на півночі Галявин...",kw={"бальзамувальний іхор","гноли гнилошкірі","лігво гаррена","магістрат севрен","аптекарі","брілл"},ang={["profession:Herbalism"]="Консервувальна рідина всередині Гнилошкірих демонструє темні алхімічні методи, що інтригують травників і хіміків, які вивчають реагенти чуми.",["race:Undead"]="Для Відступників позбавити Погибель свіжих трупів із братських могил життєво важливо: так вони захищають Тірісфаль і здобувають сировину для власного виживання."},sec={{t="Неприродне збереження",b="Гноли Гнилошкірі, що заполонили Лігво Гаррена й сусідні братські могили, — не звичайні дикі звірі, а гниючі законсервовані раби, яких Погибель посилає викопувати жертв чуми. Їхніми розкладеними жилами тече Бальзамувальний Іхор — мерзенна рідина, що штучно зберігає їхню плоть і дарує тривале нежиття. Для Магістрата Севрена у Бріллі здобуті флакони цього іхору слугують двом цілям: підтверджують знищення грабіжників могил і дають дослідникам Королівського Аптекарського Товариства свіжі зразки, щоб розтинати, вивчати й обертати на зброю проти прислужників, якими володіє Король-Ліч."}},faq={{q="Що таке Бальзамувальний Іхор?",a="Це алхімічна консервувальна речовина в оживлених тілах гнилошкірих гнолів у Галявинах Тірісфалю. Рідина підтримує їхню гнилу плоть і дає їм рухатися на службі Погибелі.",al={"бальзамувальний іхор","що таке іхор","рідина гнолів"}},{q="Хто хоче, щоб цей іхор зібрали?",a="Магістрат Севрен, що править містечком Брілл, велить поборникам-Відступникам добувати його з убитих гнилошкірих гнолів, щоб Королівське Аптекарське Товариство вивчило його хімічний склад.",al={"кому потрібен бальзамувальний іхор","іхор магістрата севрена","хто хоче іхор"}},{q="Чому гнилошкірі гноли розкопують могили?",a="Погибель використовує гнилошкірих гнолів, щоб викопувати тіла жертв чуми з братських могил на півночі, біля Лігва Гаррена, — так вона добуває сировину для поповнення своїх лав.",al={"чому гноли розкопують могили","грабіжники могил гноли","масові могили тирисфаль"}},{q="Що Відступники хочуть зробити з цією рідиною?",a="Аптекарі Андерсіті вивчають іхор, щоб розкрити його таємниці, сподіваючись створити протидію чи нові алхімічні формули проти Погибелі.",al={"що севрен робить з іхором","аптекарі вивчають іхор","використання бальзамувального іхору"}}},fp="15,287,22.601.0,24.199.0,31.181.0,46.176.0,47.155.0"}
P.entries["item:emerald-dreamcatcher"] = {n="Смарагдовий Ловець Снів",s="Смарагдовий Ловець Снів — священний амулет нічних ельфів, створений, щоб черпати тонку снагу зі Смарагдового Сну. Подарований Таллонкаю Свіфтруту друїдами Курганного Лігва Бан'етіл, він лишився в Селі Зоряного Вітерця, коли фурболги Вузлошкірів піддалися скверні й заполонили поселення.",h="Смарагдовий Ловець Снів — священний амулет нічних ельфів, створений, щоб черпати тонку снагу зі Смарагдового...",kw={"смарагдовий ловець снів","амулет","таллонкай свіфтрут","ґеролас талветрен","село зоряного вітерця","смарагдовий сон","фурболги"},ang={["class:Druid"]="Амулет — прямий зв'язок зі сплячими друїдами Курганного Лігва Бан'етіл, що показує, як їхнє єднання зі Смарагдовим Сном допомагає поселенням калдореїв унизу.",["race:NightElf"]="Повернення реліквії — маленька перемога над пошестю, що поглинає Село Зоряного Вітерця й навколишнє віття Тельдрассила."},sec={{t="Дарунок із Бан'етіла",b="Створений під опікою Ґероласа Талветрена, друїдського сторожа Курганного Лігва Бан'етіл, Смарагдовий Ловець Снів — зачарована реліквія, яку дарують лише небагатьом обраним. Він має витягати розлиті сили просто зі Смарагдового Сну, благословляючи носія удачею та захистом. Коли Село Зоряного Вітерця впало під натиском знавіснілих фурболгів Вузлошкірів, амулет лишився в шухляді комода — посеред ворожої, споганеної землі."}},faq={{q="Що робить Смарагдовий Ловець Снів?",a="За словами Таллонкая Свіфтрута, амулет черпає сиру енергію зі Смарагдового Сну й дає своєму власникові вдачу та життєву силу. Його вважають рідкісним знаком прихильності кенарійських друїдів.",al={"сили смарагдового ловця снів","навіщо ловець снів","історія ловця снів"}},{q="Хто зробив Смарагдовий Ловець Снів?",a="Його подарував Таллонкаю Ґеролас Талветрен — друїд-вартовий, що стереже сплячих друїдів кенарійського кола в Курганному Лігві Бан'етіл.",al={"хто зробив ловець снів","хто дав таллонкаї ловець снів"}},{q="Чому ловець снів лишився в Селі Зоряного Вітерця?",a="Таллонкай тримав амулет у своїй шафі в Селі Зоряного Вітерця. Коли місцевих фурболгів-Вузлошкірів поглинула скверна й вони стали жорстокими, поселення довелося покинути, і він не встиг його забрати.",al={"чому таллонкай його лишив","де загубили ловець снів"}},{q="Чому фурболги в Селі Зоряного Вітерця ворожі?",a="Плем'я Вузлошкірів по всьому Тельдрассилу стало жертвою темної скверни, що шириться й доводить їх до шаленої люті, тож нічні ельфи мусять тікати з віддалених поселень, як-от Зоряного Вітерця.",al={"чому впало село зоряного вітерця","фурболги села зоряного вітерця"}}},fp="20,300,21.470.0,38.204.0,34.143.0,59.219.0,51.201.0"}
P.entries["item:empty-blue-waterskin"] = {n="Порожній Синій Бурдюк",s="Порожній синій бурдюк — обрядова посудина, яку дають послушникам під час шаманських випробувань води. Його видає відлюдниця Брайн у Пустках, і послушник несе його на північ, у прадавні землі нічних ельфів, щоб набрати священну незатьмарену воду, потрібну для створення Тотема Води.",h="Порожній синій бурдюк — обрядова посудина, яку дають послушникам під час шаманських випробувань води.",kw={"порожній синій бурдюк","брайн","тотем води","руїни зоряного пилу","шаман","поклик води"},ang={["class:Shaman"]="Принести й наповнити цей бурдюк — важливий рубіж в опануванні духів води, що дає чисту рідину для створення вашого постійного Тотема Води.",["faction:Horde"]="Щоб дістати воду, доведеться вирушити в небезпечну мандрівку з Пусток на ворожі землі нічних ельфів на заході Ашенвалю."},sec={{t="Священна посудина",b="Щоб поєднатися з духом води, потрібен відчутний дотик до чистих, незайманих джерел по всьому Калімдору. Порожній синій бурдюк, який відлюдниця Брайн дає зі своєї хатини на пагорбі на півдні Пусток, — останнє й найнебезпечніше завдання зі збирання в початковому навчанні шамана. У ньому має опинитися чиста вода просто з відлюдного фонтана в глибині прадавніх Руїн Зоряного Пилу, що лежать на спірному прикордонні Ашенвалю."},{t="Лісовий фонтан",b="Щоб наповнити цю просту посудину, послушник мусить вийти за межі безпечних земель Орди в прадавні гаї, які стережуть дикі звірі й нічні ельфи. Щойно бурдюк занурюють у води зруйнованого святилища, він стає Наповненим Синім Бурдюком. Разом зі зразками з Пусток і Таррен Мілла його вміст дає Брайн змогу зварити напій, потрібний, щоб викликати й умилостивити стихійного духа води."}},faq={{q="Для чого потрібен Порожній Синій Бурдюк?",a="Це порожня посудина, потрібна в низці завдань «Поклик Води». Новачок має віднести її до священного фонтана в Руїнах Зоряного Пилу в Ашенвалі, наповнити й повернути Брайн, щоб та зварила напій чистої води.",al={"що робить порожній синій бурдюк","використання синього бурдюка","чому в мене порожній бурдюк"}},{q="Хто дає цей бурдюк?",a="Його дає Брайн — шаманка-аскетка й наставниця, що живе самітницею в хатині на півдні Пусток, на південь від Табору Тауражо, біля кордону з Рейзорфеном.",al={"хто дає синій бурдюк","де взяти синій бурдюк"}},{q="Де треба наповнити бурдюк?",a="Його треба наповнити біля центрального фонтана в Руїнах Зоряного Пилу на далекому південному заході Ашенвалю, трохи за Озером Містраль, біля гірського хребта Кам'яного Кігтя.",al={"де наповнити синій бурдюк","місце наповнення бурдюка","де його наповнити"}},{q="Навіщо Брайн вода з Ашенвалю?",a="Брайн хоче створити найчистішу фіалу води, яку тільки знав Калімдор. Незаймані священні джерела в руїнах нічних ельфів дають останній бездоганний складник, потрібний, щоб спілкуватися з духами води.",al={"чому вода з ашенвалю","чому вода руїн зоряного пилу"}}},fp="20,268,15.473.0,19.424.0,42.228.0,29.143.0,35.178.0,41.218.0"}
P.entries["item:empty-brown-waterskin"] = {n="Порожній Коричневий Бурдюк",s="Порожній коричневий бурдюк — стихійна посудина, яку Брайн дає під час шаманських випробувань у Пустках. Ним набирають воду в сусідній оазі, і це перше відчутне знаряддя, що вчить розуміти тендітну й спірну природу води в посушливому краї.",h="Порожній коричневий бурдюк — стихійна посудина, яку Брайн дає під час шаманських випробувань у Пустках.",kw={"порожній коричневий бурдюк","брайн","тотем води","оаза","шаман","поклик води"},ang={["class:Shaman"]="Цей бурдюк — обряд посвяти для шаманів Орди, що прагнуть здобути Тотем Води: він показує рівновагу між шануванням стихій і суворою боротьбою смертних за виживання."},sec={{t="Урок нестачі",b="На випалених сонцем рівнинах Пусток вода — значно більше, ніж ресурс: це саме життя й вічна іскра війни. Відлюдниця Брайн довіряє послушникові цей простий шкіряний бурдюк як перше випробування Поклику Води. Завдання здається скромним — спуститися з порожньою посудиною до водопою під її оселею й повернутися з повною. Та, набираючи воду з того самотнього озерця, носій одразу стикається з суворою правдою цієї землі: кожну краплю ревниво стережуть місцеві шипогриви, для яких оаза — безцінний скарб, і послушник мусить збагнути, як вода і підтримує життя, і штовхає смертних до насильства."}},faq={{q="Для чого потрібен Порожній Коричневий Бурдюк?",a="Це порожня посудина, яку Брайн дає новачкам-шаманам. У неї набирають воду з природного ставка просто під її хатиною в Пустках — так виходить наповнений бурдюк, потрібний, щоб приготувати стихійну сапту.",al={"призначення бурдюка","що робить коричневий бурдюк","використання порожнього коричневого бурдюка"}},{q="Хто дає цей бурдюк?",a="Брайн, мудра самітниця з півдня Пусток, дає посудину шаманам, що вирушають у стихійну прощу, щоб поспілкуватися з духами води.",al={"хто дає бурдюк","хто дає завдання на коричневий бурдюк","де взяти порожній бурдюк"}},{q="Чому шипогриви стережуть джерело?",a="Вода в Пустках — надзвичайна рідкість. Для шипогривів навіть маленький водопій — це величезне багатство й порятунок. Дощі тут рідко, тож вони з лютою жадібністю стережуть кожне джерело й нападають на кожного, хто наважиться з нього набрати.",al={"чому квілборги нападають","вода квілборгів","чому джерело охороняють"}},{q="Що стається, коли бурдюк наповнено?",a="Занурений в оазу під пагорбом Брайн, він стає Наповненим Коричневим Бурдюком. Повернувши його Брайн, ви даєте їй змогу перевірити, як ви розумієте рівновагу природи, перш ніж вона пошле вас світом по рідкісніші води.",al={"що робити після наповнення","здати бурдюк","здати наповнений коричневий бурдюк"}}},fp="21,255,20.652.0,43.227.0,28.186.0,48.245.0,37.219.0"}
P.entries["item:empty-cleansing-bowl"] = {n="Порожня Чаша Очищення",s="Порожня Чаша Очищення — обрядова посудина, яку Тундріс Віндвівер дає, щоб допомогти розслідувати порчу фурболгів Чорнолісся. Якщо наповнити її з місячного колодязя Обердайна й додати зразки їжі, вийде суміш, здатна на якийсь час зламати демонічну владу сатира.",h="Порожня Чаша Очищення — обрядова посудина, яку Тундріс Віндвівер дає, щоб допомогти розслідувати порчу...",kw={"порожня чаша очищення","тундріс віндвівер","фурболги чорнолісся","місячний колодязь","сатири","обердайн"},ang={["class:Druid"]="Розвіювати протиприродні недуги водою з місячного колодязя — це і є головне покликання друїда: лікувати поранену рівновагу природи на Темному Узбережжі.",["race:NightElf"]="Обряд очищення показує, що місячні колодязі Елуни здатні змити мерзенну демонічну скверну, — і дає надію, що давніх союзників нічних ельфів серед фурболгів колись удасться врятувати."},sec={{t="Посудина очищення",b="Порожню Чашу Очищення Тундріс Віндвівер з Обердайна довіряє шукачам пригод, щоб нести в ній священну воду з місцевого місячного колодязя. Нічні ельфи з'ясували, що північні фурболги Чорнолісся впали в демонічне божевілля, яке наслали сатири, що керують ними через зачаровані талісмани. Якщо набрати в чашу чистої місячної води й змішати її з горіхами, зерном і плодами, які зібрали фурболги, вийде благословенна страва, що ненадовго повертає враженим істотам розум і викриває сатира-наглядача, винного в усьому."}},faq={{q="Що робити з Порожньою Чашею Очищення?",a="Віднесіть чашу до місячного колодязя в Обердайні й занурте її в благословенні води, щоб отримати Наповнену Чашу Очищення. Потім вам треба зібрати зерно, горіхи й плоди в північному таборі фурболгів Блеквуд, щоб змішати їх із водою.",al={"використання порожньої чаші очищення","як використати чашу очищення","де наповнити чашу очищення"}},{q="Навіщо нічним ельфам ця чаша в боротьбі зі скверною фурболгів?",a="Фурболгів Блеквуд скувала темна магія талісманів сатирів. Тундріс Віндвівер наливає в чашу освячену суміш, що на якийсь час зцілює фурболгів від шалу й виманює їхнього прихованого господаря — сатира Ксабраксіса.",al={"навіщо чаша очищення","призначення чаші очищення"}},{q="Хто дає Порожню Чашу Очищення?",a="Тундріс Віндвівер, учений із нічних ельфів в Обердайні, дає вам чашу, коли доручає з'ясувати джерело скверни Блеквуд уздовж Річки Скельного Джерела.",al={"хто дає чашу очищення","хто дає завдання на чашу"}},{q="Що стається, коли суміш готова?",a="Готова суміш, поставлена біля багаття північного табору, очищає довколишніх фурболгів на досить довгий час, щоб накликати лють сатира Ксабраксіса, — і ви можете вбити його й забрати його Талісман Псування.",al={"багаття чаші очищення","куди поставити чашу очищення"}}},fp="20,285,24.560.0,43.236.0,70.240.1,38.176.0,42.211.1"}
P.entries["item:empty-cliffspring-falls-sampler"] = {n="Порожній Пробовідбірник Водоспаду Скельного Джерела",s="Порожній Пробовідбірник Водоспаду Скельного Джерела — особлива посудина, яку Коло Кенарія довіряє молодим друїдам із нічних ельфів. Нею набирають воду біля входу до печери на Річці Скельного Джерела на Темному Узбережжі, щоб розпізнати мерзенну отруту, яка вражає місцеву звірину.",h="Порожній Пробовідбірник Водоспаду Скельного Джерела — особлива посудина, яку Коло Кенарія довіряє молодим...",kw={"пробовідбірник","водоспад скельного джерела","дендрит старблейз","аланндаріан найтсонг","коло кенарія","зцілення від отрути"},ang={["class:Druid"]="Наповнити цей пробовідбірник біля печери, повної наг, — обряд посвяти для молодих друїдів, який веде просто до вміння «Зцілення від отрути».",["race:NightElf"]="Наги, що причаїлися біля чистих лісових вод Темного Узбережжя, оскверняють їх і загрожують і диким звірам, і поселенню Обердайн."},sec={{t="Розслідування отруєних вод",b="Водоспад Скельного Джерела — головне джерело прісної води на півночі Темного Узбережжя, тож будь-яке збурення в його верхів'ях смертельно небезпечне для місцевої природи. Коли місцеві олені почали гинути від підступної виснажливої отрути, Дендрит Старблейз із Кола Кенарія видав ці порожні пробовідбірники молодим друїдам, яких посилають із Місячного Гаю. Друїди мусять піднятися глибоко в скелі біля водоспаду, аж до входу в печеру, яку тепер заполонили ворожі наги, щоб набрати придатну пробу води."},{t="Рецепт ліків",b="Наповнена посудина містить каламуть, що виказує глибшу пошесть природи. Коли пробу приносять Аланндаріан Найтсонг в Обердайн, вона підтверджує, що мерзенні речовини отруюють підземні води. Вивчаючи домішки, ув'язнені в склі, Аланндаріан і друїди Кола Кенарія здобувають знання, потрібні, щоб створити протиотруту, і передають новачкові основи друїдських цілющих обрядів."}},faq={{q="Для чого цей пробовідбірник?",a="Це порожня посудина, яку дають друїдам, щоб набрати отруєної води біля входу до печери за Водоспадом Скельного Джерела на Темному Узбережжі. Проба допомагає кенарійським травникам з'ясувати природу отруєння місцевих тварин і вилікувати їх.",al={"використання пробовідбірника","навіщо пробовідбірник кліффспрінг","призначення порожнього пробовідбірника"}},{q="Де беруть пробу води?",a="Пробу треба зачерпнути просто біля входу до печери біля Водоспаду Скельного Джерела, високо на північно-східних пагорбах Темного Узбережжя. Біля входу живуть ворожі наги, тож набрати воду небезпечно.",al={"де наповнити пробовідбірник","місце пробовідбірника кліффспрінг","місце для проби"}},{q="Хто отримує наповнену посудину?",a="Наповнений пробовідбірник доставляють Аланндаріану Найтсонгу — цілителю з нічних ельфів і представникові кенарійців у прибережному поселенні Обердайн.",al={"хто отримує наповнений пробовідбірник","куди здати пробовідбірник","пробовідбірник аланндаріана"}},{q="Чому пробу беруть саме з Водоспаду Скельного Джерела, а не з інших річок?",a="Водоспад Скельного Джерела — головне джерело прісної води на півночі Темного Узбережжя. Дендрит Старблейз простежив хворобу, що вражає оленів краю, саме до цих верхів'їв, тож без проби води звідси ліків не створити.",al={"чому водоспад кліффспрінг","що труїть темне узбережжя","отрута кліффспрінг"}}},fp="31,274,32.508.0,19.415.1,36.228.0,32.204.0,34.154.0,63.236.0"}
P.entries["item:empty-dreadmist-peak-sampler"] = {n="Порожній Пробовідбірник Піка Лиховісного Туману",s="Порожній пробовідбірник Піка Жахливої Імли — особлива кенарійська посудина, яку довіряють друїдам Орди, щоб набрати отруєну воду на вершині Піка Жахливої Імли. Дослідження мерзенної рідини, зібраної в цей флакон, украй важливе, щоб розпізнати й вилікувати напасть, яка ширшає серед звірів на півночі Пусток.",h="Порожній пробовідбірник Піка Жахливої Імли — особлива кенарійська посудина, яку довіряють друїдам Орди, щоб...",kw={"порожній пробовідбірник","пік жахливої імли","дендрит старблейз","палаючий клинок","тонга рунтотем","друїди"},ang={["class:Druid"]="Здобути цей пробовідбірник — переломний крок в опануванні мистецтва зцілення від отрут, що випробовує відданість друїда справі розпізнавати й угамовувати страждання в дикій природі.",["faction:Horde"]="Друїди Орди несуть цей пробовідбірник, щоб допомогти Тонзі Рунтотему на Перехресті зупинити занепад природи, що загрожує північним рівнинам Пусток."},sec={{t="Слідами напасті",b="Коли мерзенна недуга почала косити газелей і розхитувати тендітну природу північних Пусток, друїд Дендрит Старблейз запідозрив, що осередок біди — озерця на вершині Піка Жахливої Імли, які впливають на погоду. Він послав послушників-друїдів із порожніми пробовідбірниками на гірські висоти, які тепер заполонили демонопоклонники з Палаючого Клинка, щоб набрати сиру воду просто з озерця на вершині."},{t="Вирішальний зразок",b="Із порожнім пробовідбірником, піднятим на скелі, друїди можуть здобути непідробний доказ мерзенних справ культу. Наповнену смердючу воду приносять Тонзі Рунтотему на Перехрестя, і її мерзенні складники стають основою, без якої не приготувати ліків і не захистити місцевих звірів."}},faq={{q="Для чого Порожній Пробовідбірник Піка Лиховісного Туману?",a="Це порожня посудина, якою друїди набирають пробу води з отруєного озерця на вершині Піка Жахливої Імли, щоб Тонга Рунтотем міг приготувати ліки для хворих тварин.",al={"що робить ця річ","використання пробовідбірника лиховісного туману","чому в мене цей пробовідбірник"}},{q="Куди треба віднести пробовідбірник?",a="Його треба піднести на саму вершину Піка Жахливої Імли, на північний захід від Перехрестя в Пустках, і занурити у високогірне озерце, де збирається вода.",al={"де наповнити пробовідбірник","місце пробовідбірника","як наповнити пробовідбірник"}},{q="Хто дає пробовідбірник?",a="Пробовідбірник дає Дендрит Старблейз, що діє від імені Кола Кенарія, перш ніж послати друїда до Тонги Рунтотема.",al={"хто дає пробовідбірник","хто почав це завдання"}},{q="Чому так важливо взяти пробу води на Піку Жахливої Імли?",a="Повітряні озерця Піка Жахливої Імли впливають на погоду й тумани всього краю. Вершину осквернив культ Палаючого Клинка, тож отруєна вода стікає рівнинами й труїть місцевих істот.",al={"чому пік жахливої імли","чому вода зіпсована"}}},fp="28,298,18.434.0,18.308.1,56.174.0,41.152.0,25.143.0,58.208.0"}
P.entries["item:empty-leaden-collection-phial"] = {n="Порожня Свинцева Колекційна Колба",s="Порожня Свинцева Колекційна Колба — захищена посудина, яку гноми-майстри створили, щоб збирати радіоактивні опади в руїнах Гномреґана. Виготовлена зі свинцю, щоб уберегти власника від смертельного зараження, вона потрібна шукачам пригод, які допомагають Оззі Тоґлвольту в Хараносі. Оззі сподівається, що вловлене сяйво допоможе створити ліки для їхніх уражених родичів — або хоча б надзвичайно міцний напій.",h="Порожня Свинцева Колекційна Колба — захищена посудина, яку гноми-майстри створили, щоб збирати радіоактивні...",kw={"свинцева колекційна колба","колба","оззі тоґлвольт","харанос","гномреґан","радіація","опади"},ang={["profession:Engineering"]="Свинцева колба — приклад простої гномської практичності: захист від радіації з важкого металу поєднаний із всмоктувальним пристроєм для безпечного збирання нестійких часточок із довкілля.",["race:Gnome"]="Спустошення Гномреґана лишається відкритою раною для гномів-вигнанців, тож кожна експериментальна спроба обернути назад отруйні опади для вас дуже особиста — хоч би яким диваком був дослідник."},sec={{t="Захищена посудина",b="Коли вентиляційні шахти Гномреґана затопили підземне місто отруйним випромінюванням, щоб винищити трогів, воно натомість спотворило вцілілих захисників, перетворивши їх на прокажених гномів, і опромінило звірів-загарбників. Прагнучи вивчити наслідки опадів і обернути їх назад, Оззі Тоґлвольт створив Порожню Свинцеву Колекційну Колбу. Зроблена з важкого свинцю, щоб захистити тих, хто її тримає, від навколишньої небезпеки, ця особлива колба втягує отруйне зелене сяйво, що лишається на тілах Опромінених Загарбників і Грабіжників, які нишпорять руїнами. Щойно її запечатають, вона стає Повною Свинцевою Колекційною Колбою із сирою, небезпечною речовиною, потрібною для експериментальних ліків."}},faq={{q="Для чого потрібна колба?",a="Колбою набирають і зберігають небезпечні радіоактивні опади з Опромінених Загарбників і Опромінених Грабіжників біля верхніх тунелів Гномреґана. Запечатані всередині опади перетворюють посудину на Повну Свинцеву Колекційну Колбу для досліджень.",al={"що робить колба","як використати свинцеву колбу","призначення колби"}},{q="Чому колба свинцева?",a="Радіоактивні опади в Гномреґані смертельні для незахищених живих істот: вони спричиняють тяжку променеву хворобу або перетворюють гномів на прокажених. Щільний свинець слугує захисним бар'єром і береже збирача від нестійкої світної отрути всередині.",al={"чому свинцева колба","чому свинцева"}},{q="Хто створив цей пристрій для збору?",a="Колбу дає гном-винахідник Оззі Тоґлвольт, що проводить свої хаотичні досліди в Хараносі в Дун Мороґу. Він вручає посудину шукачам пригод, які наважаться піти на отруйні околиці зруйнованого міста.",al={"хто зробив колбу","колба оззі тоґґлвольта","хто дав мені колбу"}},{q="Чого Оззі сподівається досягти із зібраними опадами?",a="Оззі та його товариш Раззл намагаються винайти ліки для гномів, яких катастрофа перетворила на прокажених. Як і з багатьма гномськими затіями, Оззі визнає, що експериментальна формула може виявитися й рецептом неймовірно міцного рому — а то й засобом від лисини.",al={"навіщо збирати опади","призначення ноґейну","що робить оззі"}}},fp="29,402,17.628.0,27.257.0,30.287.0,35.227.0,59.272.0"}
P.entries["item:empty-red-waterskin"] = {n="Порожній Червоний Бурдюк",s="Порожній червоний бурдюк — шкіряна посудина, яку довіряють молодим шаманам під час стихійних випробувань. Ним набирають свіжу, незатьмарену воду з несподіваного джерела — у враженому моровицею містечку Таррен Мілл.",h="Порожній червоний бурдюк — шкіряна посудина, яку довіряють молодим шаманам під час стихійних випробувань.",kw={"порожній червоний бурдюк","таррен мілл","брайн","криниця","тотем води","поклик води"},ang={["class:Shaman"]="Принести й наповнити цей бурдюк — основоположний крок до опанування Тотема Води й налаштування ваших чуттів на стійких духів води.",["race:Orc"]="Брайн порівнює чисту криницю в Таррен Міллі з Вождем Траллом — маяком непохитної сили й надії, що витримує величезні страждання."},sec={{t="Посудина для чистої води",b="Цей простий червоний бурдюк, який дає відлюдниця Брайн у Пустках, має важливе духовне призначення у випробуваннях Поклику Води. Послушникам доручають віднести його далеко за море, до Передгір'я Гілсбреда, і знайти містечко Таррен Мілл. Хоч містечко зайняли Відступники й воно просякнуте нежиттям, самотня криниця в його центрі й далі дає солодку, чисту джерельну воду. Наповнений червоний бурдюк зберігає важливий зразок життя, що вистояло посеред порчі, і Брайн змішує його у флакон найчистішої води для випробування послушника."}},faq={{q="Для чого потрібен Порожній Червоний Бурдюк?",a="Шамани в низці завдань «Поклик Води» набирають ним джерельну воду з колодязя в Таррен Міллі — так він стає Наповненим Червоним Бурдюком.",al={"використання червоного бурдюка","що робити з червоним бурдюком"}},{q="Хто дає цей бурдюк?",a="Брайн, орчиха-шаманка й самітниця, що живе на пагорбі на півдні Пусток, дає його новачкам-шаманам, які проходять стихійні випробування.",al={"хто дає червоний бурдюк","хто дає завдання на червоний бурдюк"}},{q="Чому воду беруть саме в Таррен Міллі?",a="Хоча Таррен Мілл перейшов під владу Відступників, центральний колодязь лишився цілком незіпсованим. Брайн бачить у цьому чистому джерелі могутній стихійний символ надії та життя, що вистояло на оскверненій землі.",al={"чому вода таррен мілла","колодязь таррен мілла"}},{q="Що стається, коли бурдюк наповнено?",a="Наповнений біля колодязя бурдюк треба повернути Брайн у Пустки. Вона змішує цю воду з іншими рідкісними пробами у фіалу найчистішої води, з якої Іслен Вотерсір створює Водяну Сапту.",al={"що далі з червоним бурдюком","здати наповнений червоний бурдюк"}}},fp="19,210,23.545.0,41.150.0,28.131.0,47.229.0,43.207.0"}
P.entries["item:empty-sampling-tube"] = {n="Порожня Пробовідбірна Трубка",s="Порожня Пробовідбірна Трубка — скляна пробірка, яку видає Тундріс Віндвівер в Обердайні. У неї мають набрати зіпсовану воду з Річки Скельного Джерела, щоб учені нічних ельфів могли дослідити порчу, що підступає до Темного Узбережжя.",h="Порожня Пробовідбірна Трубка — скляна пробірка, яку видає Тундріс Віндвівер в Обердайні.",kw={"пробовідбірна трубка","тундріс віндвівер","річка скельного джерела","сквернолісся","фурболги чорнолісся","край імли"},ang={["class:Druid"]="Пробовідбірна трубка — одна з перших спроб розпізнати демонічну скверну Сквернолісся, що просочується в чисті річки Темного Узбережжя й нівечить місцеву звірину.",["race:NightElf"]="Для нічних ельфів Обердайна перевірка Річки Скельного Джерела украй важлива, щоб отруйні стоки не загидили їхній прибережний прихисток біля Краю Імли."},sec={{t="Перевірка води",b="Поки нетрі Темного Узбережжя піддаються повзучій пошесті, природні водойми почали псуватися. Тундріс Віндвівер, дослідник, що працює в Обердайні, видає цю порожню скляну трубку, щоб зібрати на Річці Скельного Джерела відчутні докази. Набрана з озерця під першим водоспадом на північ від міста, проба дає змогу натуралістам нічних ельфів з'ясувати природу порчі, яку течія несе до Краю Імли."},{t="Пошук джерела",b="Хоча на берегах річки стоять табори ворожих фурболгів Чорнолісся, Віндвівер підозрює, що вони лише жертви й розносники, а не справжнє джерело гнилі. Наповнена трубка підтверджує: зараза стікає з отруєних висот Сквернолісся на сході. Зібрана проба стає основою для створення можливих ліків і підготовки рішучої відповіді на пошесть."}},faq={{q="Для чого потрібна Порожня Пробовідбірна Трубка?",a="Це запечатана скляна посудина, якою набирають пробу води з отруєної Річки Скельного Джерела на північ від Обердайна. Пробу приносять Тундрісу Віндвіверу, щоб він дослідив мерзенні речовини, які розходяться Темним Узбережжям.",al={"чому в мене трубка","що робить пробовідбірна трубка","призначення трубки"}},{q="Де треба взяти пробу води?",a="Трубку треба наповнити біля першого водоспаду на Річці Скельного Джерела, на північ від Обердайна під мостом, — саме там, де вода збирається, перш ніж стекти до Краю Імли.",al={"де наповнити трубку","місце річки кліффспрінг","місце проби"}},{q="Хто дав цю трубку?",a="Тундріс Віндвівер, нічний ельф-природознавець, що вивчає загрози довкіллю довкола Обердайна, довіряє трубку шукачам пригод, які наважаться вирушити в отруєні нетрі.",al={"хто дає трубку","хто дає завдання на трубку","тундріс віндвівер"}},{q="Що отруює Річку Скельного Джерела?",a="Місцеві фурболги Блеквуд живуть на берегах і лише погіршують бруд, але справжнє джерело скверни — зіпсований ліс Сквернолісся високо в горах на сході.",al={"чому річка зелена","що зіпсувало воду","скверна кліффспрінг"}}},fp="19,232,18.435.0,18.407.1,47.229.0,47.192.0,23.170.0,40.201.1"}
P.entries["item:empty-water-tube"] = {n="Порожня Трубка для Води",s="Порожня Трубка для Води — проста скляна посудина, яку видають в Обердайні, щоб набрати священної води з місячного колодязя. У ній благословенну рідину несуть до дивного червоного кристала на східних скелях Темного Узбережжя.",h="Порожня Трубка для Води — проста скляна посудина, яку видають в Обердайні, щоб набрати священної води з...",kw={"порожня трубка для води","місячний колодязь","червоний кристал","обердайн","сквернолісся","елуна"},ang={["class:Druid"]="Друїди глибоко шанують місячні колодязі й покладаються на їхні чисті води, щоб вивчати аномалії та очищати дивні збурення, які підступають зі спотворених земель на кшталт Сквернолісся.",["race:NightElf"]="Поводитися з освяченою водою місячного колодязя — священний обов'язок для калдореїв, які шанують місячні колодязі як святі водойми, благословенні богинею Елуною."},sec={{t="Посудина для благословенної води",b="Вартові й учені, що вивчають таємничий червоний кристал на східному кряжі Темного Узбережжя, потребують чистої місячної сутності, щоб перевірити його природу. Звичайне скло чи пляшки легко можуть осквернити освячену воду, тож цю запечатану пробірку довіряють саме дослідникам, що приходять до місячного колодязя в Обердайні. Наповнену, її несуть угору гірськими схилами, щоб побачити, як чужий мінерал відгукнеться на магію Елуни."},{t="Зазирнути в тінь Сквернолісся",b="Гори одразу на схід від Темного Узбережжя межують зі Скверноліссям — краєм, геть отруєним демонічною порчею. Захисники Обердайна підозрюють, що зловісний багряний моноліт біля скель має лиховісний зв'язок із тим понівеченим лісом. Обливаючи його ґратчасту будову водою з місячного колодязя, дослідники сподіваються, що священна вода відкриє внутрішню структуру кристала й не спричинить катастрофічного вивільнення сили, ув'язненої всередині."}},faq={{q="Для чого Порожня Трубка для Води?",a="Це порожня посудина, яку вам дають в Обердайні, щоб набрати води просто з місячного колодязя поселення. Ця вода потрібна, щоб дослідити дивний червоний кристал, знайдений на східних висотах Темного Узбережжя.",al={"призначення трубки для води","чому в мене трубка для води","що робити з трубкою для води"}},{q="Де наповнити трубку?",a="Її треба занурити в Місячний Колодязь в Обердайні. Наповнена, вона перетворюється на Пробірку з Водою Місячної Криниці.",al={"де наповнити трубку для води","де мені наповнити трубку","місце наповнення трубки"}},{q="Навіщо для кристала вода з місячного колодязя?",a="Вода з місячного колодязя несе могутню очисну магію Елуни. Учені вважають, що, якщо полити нею загадковий червоний кристал, вона прореагує з його поверхнею й підкаже, звідки він і з чого складається.",al={"навіщо вода місячного колодязя","що вода колодязя робить з кристалом","червоний кристал і місячний колодязь"}},{q="Чому мешканців Обердайна непокоїть кристал?",a="Кристал лежить біля високого хребта над Скверноліссям — лісом, який тяжко зіпсував Палаючий Легіон. Місцеві вартові бояться, що, коли кристал пов'язаний із тими отруєними нетрями, він може стати серйозною загрозою для Темного Узбережжя.",al={"чи кристал небезпечний","небезпека кристала на темному узбережжі","чому досліджувати червоний кристал"}}},fp="16,215,27.424.0,24.452.1,44.200.0,32.121.0,45.199.0,56.227.0"}
P.entries["item:enchanted-gaea-seeds"] = {n="Зачаровані Зерна Геї",s="Зачаровані Зерна Геї — особливо підготоване насіння, що має повернути життя спустошеним землям Калімдору. Наповнені друїдською магією й зібрані в Притулку Сонячної Скелі, їх садять просто в задушену попелом землю Обвугленої Долини, щоб протидіяти руйнуванню й знову розбудити природне зростання.",h="Зачаровані Зерна Геї — особливо підготоване насіння, що має повернути життя спустошеним землям Калімдору.",kw={"зачаровані зерна геї","таммра віндфілд","притулок сонячної скелі","обвуглена долина","відродження","друїди"},ang={["class:Druid"]="Насіння показує головний друїдський обов'язок — плекати коло відродження, повертаючи витривале життя в край, поглинутий руїною й пожежами.",["race:Tauren"]="Для шу'гало з Притулку Сонячної Скелі посадка зачарованого насіння — духовне служіння землі на честь Земної Матері й повернення пораненого краю."},sec={{t="Іскра в попелі",b="Зачаровані Зерна Геї втілюють друїдські зусилля Орди загоїти глибокі шрами, що лишилися на Горах Кам'яного Кігтя. Коли сирі Зерна Геї зібрано й обрядово зачаровано Таммрою Віндфілд у Притулку Сонячної Скелі, вони стають досить витривалими, щоб здолати всюдисуще зіпсуття й стихійну скверну. Посаджене в родючі земляні горбки, що досі вціліли під кіптявою Обвугленої Долини, насіння вкорінюється всупереч суворим умовам і дає нове життя місцині, де панують ворожі вогняні елементалі й гарпії-загарбниці."},{t="Обіцянка відродження",b="Мета цих посадок — не просте садівництво, а дієва спроба переломити хід боротьби за майбутнє Гір Кам'яного Кігтя. Магія, вплетена в лушпиння, дає насінню опиратися залишковому зіпсуттю й закріпитися місцевим рослинам. Коли рослинність відродиться, вона має заспокоїти розбурханих вогняних елементалів, витіснити диких гарпій і протидіяти нестримній вирубці, яку веде Венчурна Компанія своїми невпинними лісозаготівлями."}},faq={{q="Для чого потрібні Зачаровані Зерна Геї?",a="Їх садять у родючі горбки землі в Обвугленій Долині. З них проростають витривалі рослини, що опираються скверні довкілля й починають зцілювати землю, сплюндровану вогнем і війною.",al={"призначення зерен геї","що роблять зачаровані зерна геї","навіщо садити зерна геї"}},{q="Хто створив чи зачарував ці зерна?",a="Звичайні зерна Геї збирають у навколишній глушині й приносять Таммрі Віндфілд у Притулок Сонячної Скелі. Вона зачаровує їх, щоб вони вижили у ворожому, засипаному попелом ґрунті Обвугленої Долини.",al={"хто створив зерна","зерна таммри віндвіспер","як роблять зерна геї"}},{q="Чому їх треба садити саме в Обвугленій Долині?",a="Обвуглена Долина — осереддя руйнування природи в Горах Кам'яного Кігтя, де лютують розгнівані вогняні елементалі й гарпії. Посаджені просто в уцілілі горбки землі зерна несуть сюди життя, яке поступово вгамовує розбурханий край.",al={"де їх садити","чому обвугленої долини","садіння в обвугленій долині"}},{q="Що загрожує посадженим зернам?",a="Обвуглену Долину заполонили ворожі вогняні елементалі, народжені пожежею, агресивні гарпії Бладф'юрі, що гніздяться в руїнах, а неподалік підступає промислове нищення Венчурної Компанії.",al={"небезпеки обвугленої долини","що нищить землю"}}},fp="20,320,20.549.0,22.493.0,39.206.0,37.200.0,45.253.0,36.204.0"}
P.entries["item:enchanted-resonite-crystal"] = {n="Зачарований Кристал Резоніту",s="Зачарований Кристал Резоніту — алхімічно змінений мінерал, наповнений шаманською магією, яку вклав у нього Мор'роґал у Горах Кам'яного Кігтя. Його створено саме для того, щоб розбити резонітову оболонку, яка сковує сплячого давнього землянина на ім'я Ґоґґерок.",h="Зачарований Кристал Резоніту — алхімічно змінений мінерал, наповнений шаманською магією, яку вклав у нього...",kw={"зачарований кристал резоніту","мор'роґал","ґоґґерок","резоніт","шамани","гори кам'яного кігтя"},ang={["class:Shaman"]="Кристал показує, як стихійне втручання може розхитати навіть давню земну магію творінь титанів, що сковує живий камінь.",["faction:Horde"]="Рівновага Гір Кам'яного Кігтя хитка, і Мор'роґал покладається на поборників Орди, щоб знешкодити давні загрози, перш ніж вони наразять на небезпеку місцеві застави."},sec={{t="Руйнівник давнього каменю",b="Сирі кристали резоніту, зібрані в глибоких печерах Гір Кам'яного Кігтя, мають незвичні гармонійні й земні властивості. Розуміючи, яка небезпека дрімає в запечатаній підземній оболонці, шаман Мор'роґал змінив сирі мінерали своєю стихійною силою. Отриманий Зачарований Кристал Резоніту — точне знаряддя: коли ним ударити по укріпленій резонітовій оболонці, він руйнує її й силоміць будить велетенського землянина Ґоґґерока, поки той ще не оговтався від довгого сну."},{t="Загроза Ґоґґерока",b="Мор'роґал вважав, що давній землянин, якого ніхто не стримує, стане катастрофою для хиткої рівноваги Гір Кам'яного Кігтя й усього Калімдору. Розбиваючи оболонку зачарованим кристалом, Мор'роґал прагне розбудити створіння ослабленим, щоб мати вузьку шпарину часу знищити Ґоґґерока, перш ніж повернеться вся його стихійна міць."}},faq={{q="Для чого потрібен Зачарований Кристал Резоніту?",a="Ним розбивають резонітову оболонку глибоко в печерах Гір Кам'яного Кігтя, де аж кишить кобольдами, — і вивільняють сплячого землянина на ім'я Ґоґґерок.",al={"використання кристала резоніту","що робить кристал","розбити бочку резоніту"}},{q="Хто створив цей зачарований кристал?",a="Його створив шаман-таурен Мор'роґал, наповнивши сирі кристали резоніту своєю шаманською силою, щоб ослабити й виявити сплячу істоту всередині оболонки.",al={"хто зробив кристал","кристал мор'роґала","творець кристала резоніту"}},{q="Чому Ґоґґерока треба пробудити й знищити?",a="Мор'роґал боїться, що неперевершена міць прадавнього землянина, який вирветься на волю, загрожуватиме всьому Кам'яному Кігтю й Калімдору. Пробуджений кристалом, Ґоґґерок на якийсь час слабшає, і його можна здолати.",al={"чому вбити ґоґґерока","чи ґоґґерок небезпечний","загроза ґоґґерока"}},{q="Що робити з кристалом після перемоги над Ґоґґероком?",a="Вам треба повернути Зачарований Кристал Резоніту Мор'роґалові разом зі звісткою, що Ґоґґерока вбито.",al={"повернути кристал резоніту","здати зачарований кристал резоніту"}}},fp="26,245,24.511.0,22.360.1,48.158.0,35.158.0,44.223.0,59.117.0"}
P.entries["item:encrypted-memorandum"] = {n="Зашифрована Записка",s="Зашифрована Записка — закодоване послання, яке вручають розбійникам-новачкам, що починають шлях у Долині Холодного Хребта. Замасковане під офіційний лист, насправді це таємне запрошення від місцевого наставника розбійників, Солма Гарґріна, який закликає до єдності між пройдисвітами у вигнанні.",h="Зашифрована Записка — закодоване послання, яке вручають розбійникам-новачкам, що починають шлях у Долині...",kw={"зашифрована записка","розбійник","солм гарґрін","анвілмар","гноми","гномреґан","шифр"},ang={["class:Rogue"]="Цей закодований лист — ваш офіційний виклик у тіні Дун Мороґу, що зводить вас напряму з вашим місцевим наставником в Анвілмарі.",["race:Gnome"]="Живучи біженцями серед дворфів після падіння Гномреґану, гномські розбійники знаходять у цій записці тиху пропозицію солідарності й виживання."},sec={{t="Непомітний виклик",b="У людному дворфійському притулку Анвілмара розбійники мусять не впадати в око. Замість підходити до новобранців у всіх на виду, наставник Солм Гарґрін налагоджує зв'язок за допомогою Зашифрованої Записки. Закодований пергамент, замаскований під офіційну директиву від далекого начальства, дає новачкам-розбійникам знати, де шукати наставника, не привертаючи зайвої уваги місцевої варти чи підозріливих містян."},{t="Побратимство в Холодному Хребті",b="Під шифром ховається послання про практичне виживання. Гномреґан утрачено, переселені гноми тісняться поруч зі своїми союзниками-дворфами в засніжених поселеннях Дун Мороґу, і напруга жевріє біля самої поверхні. Солм використовує записку, щоб тихо згуртувати своїх учнів, нагадуючи: ті, хто займається їхнім ремеслом, мусять дбати одне про одного, коли через пошук цапів-відбувайлів та упередження їх ладні звинуватити в кожній зниклій дрібничці."}},faq={{q="Що таке Зашифрована Записка?",a="Це закодований пергамент, який отримують розбійники-початківці в Долині Холодного Хребта. Під виглядом офіційного розпорядження він велить їм шукати навчання в наставника розбійників.",al={"що таке зашифрована записка","предмет записка","записка розбійника"}},{q="Хто написав цю записку?",a="Її склав Солм Гарґрін, наставник розбійників в Анвілмарі, який замаскував її під офіційний наказ, щоб непомітно зібрати своїх побратимів-шахраїв.",al={"хто написав записку","хто надіслав зашифровану записку","автор записки"}},{q="Чому послання зашифроване?",a="Розбійники в Долині Холодного Хребта уникають зайвої уваги. Запрошення під виглядом звичайної канцелярської записки не дає місцевій владі й цікавим роззявам помітити таємне навчання.",al={"чому зашифроване","чому шифр","чому закодоване"}},{q="Чого хоче Солм Гарґрін?",a="Солм пропонує бойову науку, поради й взаємний захист і наголошує, що розбійники мусять триматися разом у людному Дун Мороґу, де в кожній пропажі першими звинувачують злодіїв.",al={"чого хоче солм","навіщо шукати солма","мета солма"}}},fp="20,279,18.422.0,20.439.1,33.159.0,26.156.0,29.198.0,28.187.0"}
P.entries["item:encrypted-parchment"] = {n="Зашифрований Пергамент",s="Зашифрований Пергамент — шифроване послання, яке вручають майбутнім оркам-розбійникам, що навчаються в Долині Випробувань. Передане Ґорнеком, воно непомітно спрямовує здібних новобранців у тінь Лігва, до таємного наставника Рваґа.",h="Зашифрований Пергамент — шифроване послання, яке вручають майбутнім оркам-розбійникам, що навчаються в Долині...",kw={"зашифрований пергамент","розбійник","рваґ","ґорнек","лігво","долина випробувань","розтрощена рука"},ang={["class:Rogue"]="Пергамент означає ваше посвячення в таємне підпілля Орди і вказує на наставників, пов'язаних із Розтрощеною Рукою.",["race:Orc"]="Хоч орча культура зазвичай цінує відкритий, чесний бій, це послання вітає тих, чий талант — у тихіших, смертоносніших мистецтвах виживання."},sec={{t="Поклик із тіні",b="Молоді орки, що прагнуть довести свою бойову вправність у Долині Випробувань, зазвичай б'ються просто неба, під сонцем. Та ті, хто виявляє хист до скрадання, обману й роботи клинком, привертають зовсім іншу увагу. Зашифрований Пергамент Ґорнек вручає здібним оркам-розбійникам, щойно ті випробують себе на місцевій звірині. Замість відкритого оголошення послання закодоване, щоб на поклик відгукнувся лише той, хто має око на хитрощі."},{t="Зв'язок із Розтрощеною Рукою",b="Розшифрувавши пергамент, новачок прямує вглиб печери, відомої як Лігво, повз пильні погляди інших наставників клану, щоб знайти Рваґа. Там новобранець дізнається, що виклик надіслано від імені Розтрощеної Руки — ордену, який діє в таємній мережі Орди. Відповівши на пергамент, розбійник робить перший крок у світ шпигунства, тіньового ремесла та стережених таємниць."}},faq={{q="Для чого Зашифрований Пергамент?",a="Це закодований виклик, що знайомить орків — розбійників-початківців — із їхнім наставником Рваґом, який чатує в Лігві в Долині Випробувань.",al={"що таке зашифрований пергамент","призначення пергаменту","навіщо зашифрований пергамент"}},{q="Хто надсилає цей пергамент?",a="Послання йде від наставника розбійників Рваґа, хоча вручає його вам Ґорнек, коли ви пройдете перші випробування в долині.",al={"хто написав пергамент","хто надіслав пергамент","хто дав мені пергамент"}},{q="Чому послання написане шифром?",a="Рваґ і його спільники з Розтрощеної Руки віддають перевагу таємності, а не відкритим заявам. Шифроване послання гарантує, що до їхніх прихованих лав приведуть лише того, хто годиться для тонкого шляху розбійника.",al={"чому зашифровано","чому шифр","таємне послання"}},{q="Яка організація стоїть за викликом?",a="Рваґ розповідає, що Розтрощена Рука попросила його пильнувати здібних новобранців. Вони навчають скрадання й шпигунства, щоб служити Орді з тіні.",al={"хто хоче мене навчати","розбійник розтрощеної руки","яка фракція надіслала це"}},{q="Чи можуть тролі-розбійники скористатися цим пергаментом?",a="Ні. Тролі-розбійники теж починають у Долині Випробувань, але їхній таємний виклик — це Зашифрована Табличка, а не цей пергамент.",al={"пергамент для тролів","чи й для тролів"}}},fp="19,237,26.478.0,26.406.0,47.146.0,31.142.0,37.203.0,40.169.0,36.151.0"}
P.entries["item:encrypted-rune"] = {n="Зашифрована Руна",s="Зашифрована Руна — закодоване послання-виклик, яке вручають перспективним новачкам-розбійникам у Долині Холодного Хребта. Передана потай, вона велить власникові розшифрувати її зміст і знайти наставника розбійників Солма Гарґріна в Анвілмарі.",h="Зашифрована Руна — закодоване послання-виклик, яке вручають перспективним новачкам-розбійникам у Долині...",kw={"зашифрована руна","розбійник","солм гарґрін","анвілмар","долина холодного хребта","шифр","скрадання"},ang={["class:Rogue"]="Ця руна — ваш перший офіційний контакт із мережею розбійників Дун Мороґу, що посвячує вас у мистецтво скрадання, швидких клинків і виживання.",["race:Dwarf"]="Передана в Долині Холодного Хребта, руна кличе ще одне дитя Айронфорджа опанувати тіні й боронити інтереси клану з-під поверхні."},sec={{t="Закодований виклик",b="У затишній засніженій улоговині Долини Холодного Хребта відкритий набір — не в стилі місцевих пройдисвітів і розвідників. Натомість послушникам, які виявляють хист до скрадання й хитрощів, непомітно підкидають Зашифровану Руну. Камінь, помічений ледь уловимими шифрами, несе непомітне запрошення від Солма Гарґріна, наставника розбійників, що квартирує в Анвілмарі. Це водночас і таємний іспит на знання злодійського жаргону, і вступ до тіньового ремесла, без якого не вижити в суворій пустці Дун Мороґу."},{t="Очі в тінях",b="Розшифрована руна приводить нових розбійників до Солма, який прагне зміцнити таємні лави долини посеред дедалі більшої місцевої напруги. Окрім основ володіння клинком і скрадання, Солм наголошує на пильності й побратимстві, нагадуючи новачкам: у цей час хиткого миру їхньому братству тим паче важливо триматися разом."}},faq={{q="Що таке Зашифрована Руна?",a="Це закодоване послання для розбійників-початківців у Долині Холодного Хребта: воно велить їм з'явитися до Солма Гарґріна в Анвілмарі на навчання.",al={"що за руна","призначення зашифрованої руни","що робить руна"}},{q="Хто надіслав Зашифровану Руну?",a="Послання йде від Солма Гарґріна, наставника розбійників в Анвілмарі, який так тихенько скликає новобранців, не привертаючи зайвої уваги.",al={"хто написав","хто дав","відправник руни"}},{q="Куди віднести руну?",a="Віднесіть розшифровані вказівки Солмові Гарґріну — він усередині Анвілмара в Долині Холодного Хребта.",al={"куди мені йти","кому віднести","де солм"}},{q="Чому послання зашифроване?",a="Розбійники покладаються на таємність, обман і приховане спілкування. Зашифрована руна гарантує, що на поклик відгукнеться лише майбутній розбійник, здатний прочитати шифр, а їхні методи лишаться поза чужими очима.",al={"чому шифр","чому закодовано","чому таємна руна"}}},fp="14,223,15.503.0,19.341.0,27.145.0,28.165.0,29.107.0,29.209.0"}
P.entries["item:encrypted-scroll"] = {n="Зашифрований Сувій",s="Зашифрований Сувій — непримітний пергамент, що його вручають багатонадійним щойно піднятим розбійникам у Похоронному Подзвоні. Скріплений печаткою Девіда Тріаса, він велить одержувачу з'явитися на офіційний вишкіл серед таємних оперативників Відступників.",h="Зашифрований Сувій — непримітний пергамент, що його вручають багатонадійним щойно піднятим розбійникам у...",kw={"зашифрований сувій","розбійник","девід тріас","похоронний подзвін","відступники","тіньові переслідувачі"},ang={["class:Rogue"]="Сувій знаменує початок вашого професійного навчання скритності, зламу замків і брудного бою під пильним оком розбійницького кадру Відступників.",["race:Undead"]="Для щойно піднятих у Похоронному Подзвоні цей виклик — рання нагода посісти осмислене місце в королівстві Сильвани, що тільки постає."},sec={{t="Таємний виклик",b="Коли щойно пробуджений із Відступників виявляє хист до скритності й хитрощів, непоміченим він лишається недовго. Зашифрований Сувій вручають у Похоронному Подзвоні, щойно розвідник доведе свою спроможність проти безтямної Погибелі, що блукає сусіднім цвинтарем. Скріплений особистою печаткою наставника розбійників Девіда Тріаса, сувій велить власникові розшукати його в місцевій корчмі. Це перший відбір: він скеровує оперативників-початківців до дисципліни, потрібної, щоб служити Темній Леді, а не змарнувати другий шанс на життя простими кишеньковими злодіями."},{t="Очі Тіньових Переслідувачів",b="Саме послання коротке: розбійникові належить вийти на зв'язок у Похоронному Подзвоні, перш ніж заглиблюватися в Галявини Тірісфалю. Тріас наглядає за перспективними талантами від імені Тіньових Переслідувачів — таємного крила Відступників. Щоб вижити в Лордероні, Відступники щедро покладаються на тихі клинки й хитрих розвідників: їхні вороги — Багряний Хрестовий Похід, уцілілі анклави Альянсу й недобитки Погибелі. Відгукнутися на цей шифрований виклик — перший крок до цієї таємної мережі."}},faq={{q="Для чого Зашифрований Сувій?",a="Зашифрований Сувій — вступний виклик для щойно піднятих розбійників-Відступників. Він велить їм з'явитися до Девіда Тріаса в корчмі Похоронного Подзвону, щоб почати навчання ремесла розбійника.",al={"що робить сувій","навіщо зашифрований сувій","призначення сувою"}},{q="Хто надсилає Зашифрований Сувій?",a="На сувої — особиста печатка Девіда Тріаса, місцевого наставника розбійників у Похоронному Подзвоні, який пильнує багатообіцяльних новобранців.",al={"хто написав сувій","відправник сувою","від кого сувій"}},{q="Хто такі Тіньові Скрадачі, про яких згадує Девід Тріас?",a="Тіньові Скрадачі — таємне угруповання розбійників, розвідників і вбивць-Відступників, що діє по всьому Лордерону. Тріас оцінює нові таланти, щоб визначити, хто гідний згодом вступити до їхніх лав.",al={"хто такі тіньові скрадачі","тіньові скрадачі відступники","орден тіньових скрадачів"}},{q="Куди віднести Зашифрований Сувій, прочитавши його?",a="Прочитавши сувій, віднесіть його просто Девідові Тріасу — він тиняється в корчмі Похоронного Подзвону.",al={"куди здати сувій","кому віднести сувій","здати сувій"}}},fp="16,243,16.574.0,26.501.0,44.197.0,31.145.0,53.200.0,54.114.0"}
P.entries["item:encrypted-sigil"] = {n="Зашифрований Сигіл",s="Зашифрований Сигіл — закодований знак, який вручають щойно пробудженим розбійникам — нічним ельфам у Тінедолі. Він несе приховані настанови від наставника Фрагуна Шейдвіспера й велить молодим виконавцям розпочати навчання посеред дедалі більших загроз Тельдрассилу.",h="Зашифрований Сигіл — закодований знак, який вручають щойно пробудженим розбійникам — нічним ельфам у Тінедолі.",kw={"зашифрований сигіл","розбійник","фрагун шейдвіспер","тінедол","алдрассил","тельдрассил","наставник"},ang={["class:Rogue"]="Сигіл — відправна точка шляху розбійника — нічного ельфа, що перевіряє вашу здатність розшифрувати настанови й зв'язатися зі своїм місцевим наставником.",["race:NightElf"]="Для калдореїв таємні виконавці дають життєво важливі відомості в крихку добу, коли прадавні лісові кордони зазнають нового натиску Орди."},sec={{t="Прихований виклик",b="У затишній улоговині Тінедолу з майбутніми розвідниками й лазутчиками нічних ельфів зв'язуються непомітно. Зашифрований Сигіл передає посвяченому просто в руки тихий посланець від імені Фрагуна Шейдвіспера. Ховаючи свій зміст так, як личить ремеслу, сигіл велить одержувачу з'явитися до Фрагуна біля Алдрассила. Для Шейдвіспера прочитати й доставити знак означає довести, що посвячений уміє виконувати ледь помітні вказівки й поводитися з таємними посланнями."},{t="Очі в тінях",b="Фрагун користається викликом, щоб наголосити на потребі в розбійниках у неспокійному світі. Поки між нічними ельфами й далекою Ордою тліє напруга, Шейдвіспер нагадує новобранцям: відкрита війна — не єдина небезпека для їхнього народу. Розбійники мають бути першими очима й незримими клинками калдореїв: збирати відомості по всьому Тельдрассилу й учитися бити, перш ніж загрози вкоріняться у вітті Світового Дерева."}},faq={{q="Для чого Зашифрований Сигіл?",a="Він слугує вступним викликом для нічних ельфів — розбійників-початківців. У ньому приховано вказівки, що велять власникові з'явитися до Фрагуна Шейдвіспера біля Алдрассила й почати справжнє навчання розбійника.",al={"що робить сигіл","навіщо зашифрований сигіл","чому в мене зашифрований сигіл"}},{q="Хто надсилає Зашифрований Сигіл?",a="Сигіл надсилає Фрагун Шейдвіспер, наставник розбійників у Тінедолі під гілками Алдрассила.",al={"хто написав цей сигіл","хто надіслав зашифрований сигіл","від кого сигіл"}},{q="Чого хоче Фрагун Шейдвіспер?",a="Фрагун хоче оцінити вашу готовність, наголосити на дедалі більших небезпеках для нічних ельфів — зокрема на можливих чварах, які сіє Орда, — і дати основи бойової науки.",al={"чому фраґун хоче мене","завдання фраґуна","чому говорити з фраґуном"}},{q="Куди віднести сигіл, прочитавши його?",a="Віднесіть його Фрагунові Шейдвісперу — він біля великих курганів і стежок довкола центрального дупла Алдрассила в Тінедолі.",al={"куди віднести зашифрований сигіл","місце фраґуна","де фраґун"}}},fp="15,259,16.498.0,19.443.0,43.205.0,30.126.0,43.195.0,45.141.0"}
P.entries["item:encrypted-tablet"] = {n="Зашифрована Табличка",s="Зашифрована Табличка — кодоване послання, яке отримують тролі-розбійники Темного Списа, що починають навчання в Долині Випробувань. Накреслене наставником розбійників Рваґом, воно кличе здібних злодюжок і розвідників до його посту в Лігві.",h="Зашифрована Табличка — кодоване послання, яке отримують тролі-розбійники Темного Списа, що починають навчання...",kw={"зашифрована табличка","розбійник","рваґ","лігво","темний спис","долина випробувань"},ang={["class:Rogue"]="Шифрована плитка означає ваше перше посвячення в офіційні лави розбійників Орди і вказує шлях до науки Рваґа в Лігві.",["race:Troll"]="Тролі Темного Списа, що навчаються в Дуроторі, отримують цю табличку як доказ, що їхня спритність і скрадливість привернули увагу наставників Долини."},sec={{t="Прихований поклик",b="Тролі-розбійники, що прибувають у Долину Випробувань, отримують Зашифровану Табличку як першу настанову. Накреслена шифрованими вказівками, плитка веде їх просто до Рваґа — орка-наставника, що мешкає в затінених печерах Лігва. Замість відкрито оголошувати справи гільдії, місцеві тіньові агенти вживають ці шифровані плитки, щоб перевірити кмітливість і непомітно взяти нові таланти під офіційну опіку."},{t="Очі Руки",b="Розшифрування таблички знайомить новобранців із ширшою тіньовою мережею Орди. Доповівши Рваґу, розвідники дізнаються, що за їхнім поступом стежать тіньові спілки на кшталт Розтрощеної Руки, які покладаються на наставників долини, аби майбутні злодюжки, шпигуни й убивці були достатньо гострі, щоб служити новій нації."}},faq={{q="Для чого потрібна Зашифрована Табличка?",a="Зашифрована Табличка — закодований виклик, що велить молодим тролям-розбійникам з'явитися до Рваґа, місцевого наставника розбійників у Лігві в Долині Випробувань.",al={"призначення таблички","що робить зашифрована табличка","чому в мене зашифрована табличка"}},{q="Хто написав послання на табличці?",a="Послання склав Рваґ — наставник розбійників у Долині Випробувань, що навчає злодіїв, кишенькових крадіїв і вбивць для Орди.",al={"хто надіслав зашифровану табличку","автор таблички","хто це написав"}},{q="Де знайти Рваґа?",a="Рваґ — глибоко в Лігві, системі печер уздовж північного хребта Долини Випробувань у Дуротарі.",al={"де рваґ","місце рваґа","знайти вчителя розбійників долини випробувань"}},{q="Що таке «Рука», про яку згадує Рваґ?",a="«Рука» — це Розтрощена Рука, таємний орден у мережі розбійників Орди. Рваґ звітує їм про готовність нових агентів, що виходять із Долини.",al={"яка рука","хто така рука","зв'язок із розтрощеною рукою"}}},fp="16,223,16.432.0,16.331.0,38.175.0,36.152.0,21.114.0,37.190.0"}
P.entries["item:essence-of-nightlash"] = {n="Сутність Найтлеша",s="Сутність Найтлаш — магічний залишок, зібраний після поразки баньші Найтлаш на Мертвих Полях. Для Верховного Екзекутора Гадрека це незаперечний доказ того, що сили Погибелі, які підтримували місцевих гнилошкірих гнолів, зламано.",h="Сутність Найтлаш — магічний залишок, зібраний після поразки баньші Найтлаш на Мертвих Полях.",kw={"сутність найтлаш","баньші","найтлаш","мертві поля","верховний екзекутор гадрек","гнилошкірі гноли","срібнолісся"},ang={["class:Mage"]="Чародії й учені часто досліджують рештки знищених баньші, щоб збагнути, як примарна нежить прив'язує некротичну магію до фізичного світу.",["race:Undead"]="Вояки-Відступники вважають знищення баньші на кшталт Найтлаш вкрай важливою справою: самі колись поневолені Погибеллю, вони бачать у знищенні посіпак Короля-Ліча основу того, щоб утвердити Лордерон для свого народу."},sec={{t="Баньші Мертвих Полів",b="На покинутому хуторі в північному Срібноліссі, відомому як Мертві Поля, під проводом Погибелі окопалися зграї гнилошкірих гнолів-нежиті. Перші напади Відступників раз у раз розбивалися не через диких гнолів, а через їхню примарну командирку — баньші Найтлаш. Закликаючи голосильні чари, вона зміцнювала лави гнолів і обертала на втечу загони з Гробниці. Коли її вбивають, її безтілесна подоба розсипається порохом, лишаючи кристалічну магічну сутність — знак того, що її знищено назавжди."},{t="Доказ поразки Погибелі",b="Баньші не лишають по собі тілесного трупа, тож Сутність Найтлаш — єдиний речовий доказ того, що злісного духа знищено. Верховному Екзекуторові Гадреку в Гробниці потрібна ця сутність, щоб пересвідчитися: місцевий плацдарм Погибелі впав, і Відступники можуть нарешті вбезпечити свої північні рубежі й придушити загрозу гнилошкірих."}},faq={{q="Що таке Сутність Найтлеша?",a="Це кристалізований пил, що лишається після перемоги над банші Погибелі Найтлаш. Духи не мають тіла, тож цей магічний залишок слугує доказом її загибелі.",al={"сутність найтлеша","пил найтлеша","що таке сутність найтлеша"}},{q="Хто така Найтлаш?",a="Найтлаш — банші на боці Погибелі, що очолює й підсилює гнилошкірих гнолів, які орудують на Мертвих Полях на півночі Срібнолісся.",al={"хто така найтлаш","історія найтлаш","банші найтлаш"}},{q="Кому потрібна ця сутність?",a="Верховний Екзекутор Гадрек у Гробниці просить поборників-Відступників принести її як доказ того, що банші, яка розбивала його передові загони, знешкоджено.",al={"кому потрібна сутність найтлеша","кому здати сутність","верховний виконавець гадрек"}},{q="Чому гноли діють разом із банші?",a="Гнилошкірі гноли на Мертвих Полях піддалися чумі нежиті й стали рабами Погибелі. Найтлаш прислали наглядати за ними й підтримувати їх магією проти патрулів Відступників.",al={"гноли та погибель","гнилошкірі й погибель","чому гноли з банші"}}},fp="20,256,30.536.0,23.370.0,33.178.0,17.148.0,23.155.0,42.203.0"}
P.entries["item:essential-artificial"] = {n="Штучний Мозок",s="Штучний Мозок — універсальна стандартизована механічна деталь, без якої не обійтися гномам-майстрам та інженерам. Під час панічної евакуації з Гномреґана цілі запаси цих деталей лишилися на складах, і тепер гноми, що намагаються відновити свої технологічні розробки у вигнанні в Айронфорджі, дуже їх шукають.",h="Штучний Мозок — універсальна стандартизована механічна деталь, без якої не обійтися гномам-майстрам та...",kw={"штучний мозок","деталі","гномреґан","клокморт спаннерспан","містечко майстрів","інженерія"},ang={["profession:Engineering"]="Інженери оцінять витонченість майже універсальної механічної деталі, створеної, щоб бездоганно вписуватися в найрізноманітніші машини й експериментальні конструкції.",["race:Gnome"]="Кожна деталь, врятована з опромінених коридорів Гномреґана, допомагає гномам-вигнанцям відновити свою технологічну першість, поки вони шукають притулку в Айронфорджі."},sec={{t="Стандартна винахідливість",b="До падіння Гномреґана Штучний Мозок був наріжним каменем щоденної гномської інженерії. Майстри описували його як майже універсальну деталь, і його вбудовували в незліченні пристрої, годинникові дива й важкі машини по всіх підземних залах. Стандартизованість робила його незамінним для ковалів і механіків, яким потрібні надійні взаємозамінні модульні частини."},{t="Порятунок із глибин",b="Коли вторгнення трогів і подальша радіаційна катастрофа змусили гномів до відчайдушної, панічної втечі, величезні запаси цих деталей покинули там, де вони лежали. Вони й досі зберігаються у важких паросилових роздавачах, відомих як штучні екстраполятори, розкиданих по глибших переходах Гномреґана. У Містечку Майстрів майстер Клокморт Спаннерспан наймає відважних шукачів пригод, щоб ті повернулися до заражених руїн і врятували ці деталі, аби дослідження й винаходи тривали."}},faq={{q="Що таке Штучний Мозок?",a="Це стандартна й надзвичайно універсальна механічна деталь, яку гномські ковалі й майстри широко використовують у своїх дослідах, машинах і пристроях.",al={"що таке штучний мозок","предмет штучний мозок","що це за деталь"}},{q="Чому їх залишили в Гномреґані?",a="Коли вдерлися троги, а місто затопило смертоносне випромінювання, гноми тікали в шаленому поспіху. У паніці евакуації запаси звичайних деталей просто лишилися в сховищах.",al={"чому їх лишили в гномереґані","чому покинуті"}},{q="Хто хоче повернути ці деталі?",a="Клокморт Спаннерспан, честолюбний гном-винахідник із Містечка Майстрів в Айронфорджі, шукає їх для своїх дослідів і технічних пошуків у вигнанні.",al={"хто хоче повернути штучні мізки","хто бере ці деталі","завдання клокморта спаннерспана"}},{q="Де їх знайти в руїнах?",a="Вони зберігаються у великих парових механічних контейнерах — штучних екстраполяторах, розставлених на глибших рівнях зараженого Гномреґана.",al={"де їх знайти","місце екстраполятора"}}},fp="20,302,24.407.0,23.522.0,32.152.0,40.212.0,37.173.0,38.166.0"}
P.entries["item:etched-note"] = {n="Гравірована Записка",s="Гравірована Записка — офіційний виклик, який вручають перспективним молодим мисливцям-тауренам, що відпочивають у Таборі Нарачі. Написане наставницею мисливців табору, Ланкою Фаршот, послання вітає новачка в традиціях полювання й кличе його на перший урок.",h="Гравірована Записка — офіційний виклик, який вручають перспективним молодим мисливцям-тауренам, що...",kw={"гравірована записка","мисливець","ланка фаршот","табір нарачі","таурени","шу'гало"},ang={["class:Hunter"]="Записка знаменує ваше офіційне посвячення в традицію мисливців і обіцяє уроки володіння далекобійною зброєю та спілкування зі звірами рівнин.",["race:Tauren"]="Несучи сподівання старійшин і свого роду, ви отримуєте цю записку як поклик опанувати хвилясті луки Малгору, перш ніж вирушати в далекі землі."},sec={{t="Поклик до полювання",b="Табір Нарачі — безпечне місце, де молодих шу'гало рано розпізнають за природними нахилами й родинним походженням. Гравіровану Записку приносить гонець від імені Ланки Фаршот, тутешньої наставниці мисливців. Вона називає мисливця серцем племені й водночас суворо нагадує: сирий інстинкт треба гартувати суворою наукою та глибокою шаною до дикої природи Малгору."},{t="Традиції шу'гало",b="Для тауренів полювання — значно більше, ніж практичний спосіб вижити: це шанована, священна дисципліна, вплетена в життя племені. Записка велить читачеві досконало вивчити кожен клапоть Плато Червоної Хмари й довколишніх рівнин. Подавши лист Ланці, учень робить перші офіційні кроки в науці зброї, розумінні звірів і виконанні обов'язку захищати й годувати племена."}},faq={{q="Для чого Гравірована Записка?",a="Вона слугує вступним викликом для тауренів — мисливців-початківців. Прочитавши записку, власник має з'явитися до Ланки Фаршота в Таборі Нарачі, щоб почати справжнє навчання стрільби й знання звірів.",al={"що робить гравірована записка","використання гравірованої записки","чому я отримав записку"}},{q="Хто написав цю записку?",a="Послання написав Ланка Фаршот, наставник мисливців у Таборі Нарачі. Він розсилає гінців по всьому плато, щоб знайти молодих мисливців, готових учитися.",al={"хто написав записку","хто надіслав гравіровану записку","автор записки"}},{q="Чому полювання таке важливе для тауренів?",a="Полювання — наріжний камінь виживання, духовності й племінних традицій тауренів. Вправні мисливці дають своєму народові їжу й матеріали, живуть у рівновазі з землею й шанують духів звірів, яких уполювали.",al={"історія тауренів-мисливців","чому таурени полюють","полювання в культурі тауренів"}},{q="Куди віднести цю записку?",a="Віднесіть записку просто Ланці Фаршоту — він стоїть біля навісу й тренувального майданчика в Таборі Нарачі на Плато Червоної Хмари.",al={"куди віднести записку","кому здати це","здати гравіровану записку"}}},fp="11,274,18.422.0,26.430.0,39.217.0,20.173.0,42.235.0,34.133.0"}
P.entries["item:etched-parchment"] = {n="Гравірований Пергамент",s="Гравірований Пергамент — письмовий виклик, який отримують мисливці-новачки, що навчаються в Долині Випробувань у Дуроторі. Переданий Ґорнеком, він спрямовує майбутніх слідопитів нетрів по науку до тролиці-наставниці Джен'шан.",h="Гравірований Пергамент — письмовий виклик, який отримують мисливці-новачки, що навчаються в Долині...",kw={"гравірований пергамент","мисливець","джен'шан","ґорнек","долина випробувань","дуротар"},ang={["class:Hunter"]="Це послання — найперший обряд переходу мисливця в Дуроторі, що офіційно зводить вас із Джен'шан для навчання вистежування, стрільби й виживання.",["faction:Horde"]="Кожен молодий воїн Орди має відточувати своє ремесло; для мисливців цей пергамент — перший крок до того, щоб годувати клан і стерегти кордони Дуротару."},sec={{t="Поклик на полювання",b="Молоді орки й тролі Темного Списа, що шукають своє місце в Орді, починають обряди в посушливому басейні Долини Випробувань. Поки вони випробовують себе на місцевій дрібноті, Ґорнек пильно наглядає за ними й скеровує новобранців до їхнього покликання. Тим, кому судилося володіти луком, рушницею та іклом, Ґорнек передає цей гравірований пергамент. Він несе пряме послання від Джен'шан — умілої наставниці мисливців, що шукає свіжих очей і твердих рук."},{t="Перший урок",b="Принести пергамент Джен'шан — означає по-справжньому почати мисливський вишкіл у Дуроторі. Джен'шан наголошує: йти дикою стежкою нелегко, і опанувати звірів пустелі потребує не меншої відданості, ніж маг віддає магії, а шаман — духам. Прочитати пергамент і відгукнутися на її поклик — означає долучити новачків до справжньої стрілецької майстерності й виживання в нетрях."}},faq={{q="Для чого Гравірований Пергамент?",a="Це вступний виклик, що веде щойно прибулих мисливців у Долині Випробувань до їхнього наставника, Джен'шана.",al={"використання гравірованого пергаменту","що робить гравірований пергамент"}},{q="Хто роздає цей пергамент?",a="Ґорнек, наглядач біля Лігва в Долині Випробувань, вручає записку молодим мисливцям, щойно вони прибувають.",al={"хто дає гравірований пергамент","видавець завдання на пергамент"}},{q="Хто написав Гравірований Пергамент?",a="Послання від Джен'шана — троля, наставника мисливців у Долині Випробувань, який охоче навчає нових стрільців.",al={"хто надіслав гравірований пергамент","автор пергаменту"}},{q="Де знайти Джен'шана?",a="Джен'шан — у Долині Випробувань у Дуротарі: він чекає біля тренувального майданчика, щоб навчати орків і тролів — мисливців-початківців.",al={"де джен'шан","знайти джен'шана"}}},fp="16,229,21.455.0,16.408.0,33.127.0,29.123.0,31.129.0,28.131.0"}
P.entries["item:etched-rune"] = {n="Гравірована Руна",s="Гравірована Руна — різьблена кам'яна табличка, яку вручають майбутнім дворфійським мисливцям у Долині Холодного Хребта. Це запрошення від наставника мисливців Торґаса Ґрімсона, що велить новачкам знайти його в Анвілмарі й розпочати офіційне навчання лісовому ремеслу.",h="Гравірована Руна — різьблена кам'яна табличка, яку вручають майбутнім дворфійським мисливцям у Долині...",kw={"гравірована руна","мисливець","торґас ґрімсон","анвілмар","долина холодного хребта","полювання","вистежування"},ang={["class:Hunter"]="Руна — ваш перший офіційний виклик до давнього ремесла дворфійського полювання, де головне — вистежування, повага до тварин-супутників і виживання в суворій пустці лише власним розумом.",["race:Dwarf"]="Різьблені камені й руни — традиційний дворфійський спосіб передавати ремісничі знання та нагальні вказівки, навіть загартованим мандрівникам серед снігів Долини Холодного Хребта."},sec={{t="Поклик дикої природи",b="Цю невелику кам'яну табличку з вирізьбленими дворфійськими рунами передають новачкам, які виявляють хист серед заметів Долини Холодного Хребта. Надіслана горянином і наставником мисливців Торґасом Ґрімсоном, руна закликає молодих слідопитів відкласти справи надворі й з'явитися до Анвілмара. Прочитання каменя — перший крок мисливця від простого виживання до глибшого розуміння ремесла дикої природи: навчитися шанувати звірів Дун Мороґу, вистежувати гірських хижаків, доглядати дальнобійну зброю й витримувати люту стихію."}},faq={{q="Для чого Гравірована Руна?",a="Руна — це виклик із настановою для дворфів-мисливців. Знаки на табличці велять власникові знайти Торґаса Ґрімсона в теплі Анвілмара, щоб отримати справжні настанови в мисливському ремеслі.",al={"що робить гравірована руна","використання гравірованої руни","чому в мене гравірована руна"}},{q="Хто написав чи надіслав Гравіровану Руну?",a="Руну надіслав Торґас Ґрімсон, місцевий наставник мисливців в Анвілмарі. Він передає ці різьблені камені новачкам-слідопитам у Долині Холодного Хребта, що виявляють хист до виживання в замерзлій глушині.",al={"хто надіслав гравіровану руну","хто дав мені руну","автор гравірованої руни"}},{q="Куди віднести Гравіровану Руну, прочитавши її?",a="Віднесіть руну до головної зали Анвілмара в Долині Холодного Хребта. Торґас Ґрімсон стоїть біля горна й тренувальних зал — він готовий навчити вас вистежування, догляду за зброєю й традицій дворфського полювання.",al={"куди віднести гравіровану руну","здати гравіровану руну","місце торґаса ґрімсона"}}},fp="11,262,16.564.0,39.231.0,34.225.0,52.230.0"}
P.entries["item:etched-sigil"] = {n="Гравірований Сигіл",s="Вирізьблений знак, який вручають майбутнім мисливцям — нічним ельфам, що пробуджуються в Тінедолі. Принесений лісовим гінцем, він несе виклик від наставниці мисливців Аянни Еверстрайд із великої гілки Алдрассила.",h="Вирізьблений знак, який вручають майбутнім мисливцям — нічним ельфам, що пробуджуються в Тінедолі.",kw={"гравірований сигіл","мисливець","аянна еверстрайд","тінедол","алдрассил","тельдрассил","лук"},ang={["class:Hunter"]="Цей вирізьблений талісман — самісінький початок шляху калдорейського мисливця до опанування лука й звичаїв звірів під проводом Аянни Еверстрайд.",["race:NightElf"]="Вручений у відлюдному шатрі Тінедолу, сигіл вшановує прадавні традиції нічноельфійських лісників, відданих захисту Тельдрассила."},sec={{t="Поклик дикого краю",b="Різьблений знаками полювання Гравірований Сигіл вручають щойно пробудженим мисливцям — нічним ельфам, щойно ті ступають у Тінедол. Знак слугує офіційним сповіщенням і вітанням від Аянни Еверстрайд, місцевої наставниці мисливців, що мешкає високо в порожнистому вітті Алдрассила. Велячи новачкові розшукати її, сигіл розпочинає довічну науку стрільби з лука, лісового вистежування й прадавнього нічноельфійського зв'язку між ловцем і звіром."}},faq={{q="Для чого Гравірований Сигіл?",a="Сигіл — прямий виклик, що велить нічному ельфові, мисливцеві-початківцю, знайти свою наставницю Аянну Еверстрайд нагорі в Алдрассилі в Тінедолі й почати навчання виживання, вистежування й стрільби з лука.",al={"що робить гравірований сигіл","використання гравірованого сигіла","чому в мене сигіл"}},{q="Хто надсилає Гравірований Сигіл?",a="Його виготовляє й надсилає Аянна Еверстрайд — наставниця мисливців, що опікується молодими лісовими слідопитами в Тінедолі.",al={"хто надіслав гравірований сигіл","звідки гравірований сигіл"}},{q="Куди віднести сигіл?",a="Його треба віднести на горішні яруси великого дерева Алдрассил у самому серці Тінедолу, де чекає Аянна Еверстрайд.",al={"куди віднести сигіл","кому віддати гравірований сигіл"}},{q="Чому мисливці нічних ельфів отримують сигіл, а не паперовий лист?",a="Традиції калдореїв віддають перевагу природному різьбленню й міцним знакам зі священними символами Елуни та дикої природи, а не звичайному пергаменту, — так виявляється зв'язок мисливця з лісом.",al={"чому сигіл, а не лист","з чого сигіл"}}},fp="12,209,20.452.0,40.206.0,27.129.0,32.137.0,68.195.0"}
P.entries["item:explosive-stick-of-gann"] = {n="Вибухова Шашка Ґанна",s="Вибухова шашка Ґанна — особливий підривний заряд, який Ґанн Стоунспайр склав за викраденими дворфійськими кресленнями. Її створили саме для того, щоб знищити дворфійську літальну машину в Бель Модані на півдні Пусток.",h="Вибухова шашка Ґанна — особливий підривний заряд, який Ґанн Стоунспайр склав за викраденими дворфійськими...",kw={"вибухова шашка ґанна","ґанн стоунспайр","бель модан","хазґорм","літальна машина","таурени"},ang={["profession:Engineering"]="Ця зброя показує іронію ситуації: прості викрадені креслення обертаються проти досконалої дворфійської машинерії.",["race:Tauren"]="Скориставшись цією зброєю, ви помститеся за вигнане плем'я Стоунспайр і завдасте удару шукачам, що перекопали священну землю Калімдору."},sec={{t="Зброя відплати",b="Коли дворфійський Шукач Хазґорм привів розкопки Айронфорджа на південь Калімдору, дворфи вигнали тауренів Стоунспайр із їхнього родового села й сплюндрували їхні священні землі, щоб звести фортецю-розкопки Бель Модан. Ведений жагою помсти й прагненням ушанувати вигнаних і полеглих родичів, Ґанн Стоунспайр здобув креслення Хазґорма, щоб обернути дворфійську інженерію проти загарбників. Вивчивши здобуті плани, Ґанн склав цей особливий заряд такої вибухової сили, що здатен розтрощити важкі машини."},{t="Ціль — небесна машина",b="Вибухову шашку виготовили для однієї-єдиної цілі: дворфійської літальної машини, що стоїть на спостережній вежі над місцем розкопок. Для Ґанна механічний літун — не просто повітряний транспорт чи зброя: це пихатий символ панування Альянсу над священною тауренською землею. Підрив заряду знищує одну з опор дворфійської застави й завдає важливого удару на честь утраченого племені Стоунспайр."}},faq={{q="Що таке Вибухова Шашка Ґанна?",a="Це вибуховий заряд, який виготовив таурен Ґанн Стоунспайр. За захопленими дворфськими кресленнями Ґанн зробив його, щоб зіпсувати машини шукачів, що захопили землі його предків.",al={"вибухова шашка ґанна","шашка ґанна","бомба ґанна"}},{q="Хто зробив цю вибухівку?",a="Її зібрав Ґанн Стоунспайр — таурен, що прагне помсти після того, як дворфи Айронфорджа в Бель Модані знищили село його племені й осквернили рідну землю на півдні Пусток.",al={"хто зробив цю вибухівку","хто такий ґанн","ґанн стоунспайр"}},{q="Що має підірвати ця вибухівка?",a="Вона призначена знищити дворфську літальну машину на оглядовій вежі над розкопом у Бель Модані. Знищений літак позбавляє розкопки розвідки й стає символічною помстою за плем'я Стоунспайр.",al={"що підірвати","ціль літальних машин","де використати"}},{q="Як таурен навчився робити дворфську вибухівку?",a="Ґанн зробив шашку за інженерними кресленнями, відібраними в Шукача Хазґорма, керівника дворфських розкопок у Бель Модані, — обернувши техніку загарбників проти них самих.",al={"як ґанн зробив вибухівку","креслення вибухівки","плани казгорма"}}},fp="23,238,23.527.0,25.454.1,36.203.0,24.190.0,42.238.0,50.194.0"}
P.entries["item:faded-shadowhide-pendant"] = {n="Збляклий Підвісок із Тіньошкіри",s="Потьмянілий талісман, який колись носили гноли Тіньової Шкури Редріджу; його зачарували, щоб передавати темні накази. На подив власника, підвісок несе ще й відкладене магічне послання від чарівника Теокрітуса.",h="Потьмянілий талісман, який колись носили гноли Тіньової Шкури Редріджу; його зачарували, щоб передавати темні...",kw={"збляклий підвісок","гноли Тіньової Шкури","теокрітус","морґант","вежа азори","редрідж"},ang={["class:Mage"]="Підвісок демонструє тонкощі магічного перехоплення: навіть грубі чи темні чари дисциплінований чарівник Кірін-Тору здатен розшифрувати й перехопити.",["faction:Alliance"]="Повернувши цей амулет, ви допомагаєте Вежі Азори послабити гнолів Тіньової Шкури, які загрожують спокою і Лісу Елвінн, і Лейкширу."},sec={{t="Перервана мережа",b="Гноли Тіньової Шкури, що блукають Горами Редріджу, підкоряються зловісному володареві на ім'я Морґант і узгоджують свої дії за допомогою зачарованих підвісків. Досліджуючи ці талісмани у своєму притулку у Вежі Азори, верховний маг Теокрітус створив експериментальне закляття, щоб прорватися на їхню магічну частоту. Хоч його чарівне послання проявилося лише за кілька тижнів, цей збляклий підвісок довів, що лінію зв'язку гнолів можна перехопити, — а отже, можна й підірвати владу їхнього темного володаря."},{t="Задум мага",b="Вивчивши збляклий підвісок власноруч, Теокрітус дізнається значно більше, ніж просто перехоплені розмови. Дослідивши, як чари витримали його втручання, маг сподівається вдосконалити своє чаклунство й перетворити його на зброю, здатну завдавати знесилювальних ударів через будь-який схожий амулет, що його носять у Редріджі. Доставити артефакт назад до Вежі Азори в Лісі Елвінн — перший і вирішальний крок до того, щоб зламати владу Морґанта над гнолами краю."}},faq={{q="Що таке Збляклий Підвісок із гноли Тіньової Шкури?",a="Це зачарований амулет, який носили гноли гноли Тіньової Шкури в Горах Редріджу, щоб отримувати накази від свого господаря, Морґанта. Саме цей підвісок змінило перехоплене закляття-послання, яке надіслав Верховний Маг Теокрітус.",al={"підвісок тіньової шкури","що це за підвісок","підвісок теокрітуса"}},{q="Чому з підвіска лунає голос?",a="Верховний Маг Теокрітус місяцями досліджував, як магічно пробити зв'язок між підвісками. Голос, який ви чуєте, — відлуння закляття, яке він надіслав кілька тижнів тому: це доводить, що його чари таки проникли в мережу гнолів.",al={"хто говорить","безтілесний голос","голос теокрітуса"}},{q="Хто такий Теокрітус?",a="Теокрітус — Верховний Маг, що живе у Вежі Азори на сході Лісу Елвінн. Свої магічні дослідження він присвячує стеженню за темними загрозами за кордоном, у Редріджі, — передусім за чаклуном-ренегатом Морґантом.",al={"історія теокрітуса","верховний маг теокрітус","маг вежі азори"}},{q="Хто такий Морґант?",a="Морґант — зловісний чаклун-ренегат, що орудує в Редріджі. Він має темну владу над місцевою зграєю гнолів гнолів Тіньової Шкури і передає їм накази через ці зачаровані підвіски.",al={"хто така морґант","особа морґанта","майстер гнолів"}},{q="Що Теокрітус хоче зробити з підвіском?",a="Теокрітус має намір вивчити чари підвіска у своїй лабораторії. Його кінцева мета — навчитися посилати мережею паралізувальні магічні удари, що миттю знешкоджуватимуть кожного гнола з таким підвіском.",al={"чого теокрітус хоче від підвіска","навіщо підвіски теокрітусу","підвіски як зброя"}}},fp="24,240,16.500.0,19.447.1,37.240.0,40.241.0,18.210.0,16.189.0,49.212.0"}
P.entries["item:fallen-moonstone"] = {n="Полеглий Місячний Камінь",s="Полеглий Місячний Камінь — сяйливий, наповнений магією камінь, який збирають у тихих водах Озера Впалого Неба в Ашенвалі. Сповнені священної місячної сили, ці камені мають могутню цілющу дію: вони відновлюють життєву силу й лікують тяжке виснаження.",h="Полеглий Місячний Камінь — сяйливий, наповнений магією камінь, який збирають у тихих водах Озера Впалого Неба...",kw={"полеглий місячний камінь","озеро впалого неба","оракул тінявої хащі","релара вайтмун","зцілення","елуна"},ang={["class:Priest"]="Послідовниці Сестринства Елуни вбачають у місячному сяйві цих каменів відчутний вияв цілющої благодаті.",["race:NightElf"]="Для калдореїв реліквії, пов'язані з сяйвом Елуни, — священні знаряддя збереження, що дарують божественне зцілення, коли смертна медицина безсила."},sec={{t="Дари нічного неба",b="Колись полеглі місячні камені збирали вдосталь на берегах і мілинах Озера Впалого Неба, на південний схід від Астранаару. Нічні ельфи дуже цінували їх за цілющу магію та місячне благословення й часто шукали, щоб допомогти одужанню, коли звичайні засоби не допомагали. Та збирати їх стало небезпечно, коли озеро заполонили зіпсовані лісовики Тінявої Хащі. Їхній ватажок, Оракул Тінявої Хащі, зносив кожен знайдений камінь на невеликий острівець посередині озера, відрізавши місцевих калдореїв від важливого джерела зцілення."},{t="Батько-рятівник",b="Коли юна Релара Вайтмун тяжко занедужала в Астранаарі, звичайне лікування збило їй жар, але дівчинка згасала й трималася за життя з останніх сил. Її батько, Пелтурас Вайтмун, зрозумів, що відновити її виснажені сили може лише зосереджена цілюща міць місячного каменю. Камінь, здобутий зі схованки Оракула Тінявої Хащі, дав ту іскру, що врятувала дитині життя."}},faq={{q="Що таке Полеглий Місячний Камінь?",a="Це рідкісний світний камінь з Озера Впалого Неба в Ашенвалі. Насичений місячною магією, він має потужну цілющу енергію, якою нічні ельфи повертають сили тяжко виснаженим.",al={"що таке полеглий місячний камінь","історія місячного каменю","місячний камінь ашенвейлу"}},{q="Де знайти Полеглі Місячні Камені?",a="Вони походять з Озера Впалого Неба на південний схід від Астранаару в Ашенвалі. Колись вони вільно лежали на дні озера, але ворожі деревні люди Тінявої Хащі позбирали їх і сховали на острові посеред озера.",al={"де знайти полеглі місячні камені","місце полеглого місячного каменю"}},{q="У кого місячні камені на Озері Впалого Неба?",a="Оракул Тінявої Хащі, ватажок зіпсованих деревних людей з Озера Впалого Неба, сховав полеглі місячні камені на острові посеред озера.",al={"у кого полеглий місячний камінь","оракул тіньового гаю місячний камінь"}},{q="Навіщо Пелтурасу Вайтмуну Полеглий Місячний Камінь?",a="Його юна донька Релара пережила виснажливу гарячку, але лишилася вкрай кволою й швидко згасає. Пелтурас зрозумів, що звичайний відпочинок не врятує їй життя, — потрібна вроджена магія місячного каменя, щоб повернути їй сили.",al={"донька пелтураса вайтмуна","навіщо місячний камінь","ліки релари"}}},fp="16,264,22.554.0,20.413.1,27.206.0,34.218.0,48.159.0,52.243.0"}
P.entries["item:fandral-s-message"] = {n="Послання Фандрала",s="Послання Фандрала — лист, написаний Архідруїдом Фандралом Стаґгелмом у Дарнасусі. Його доручають шукачеві пригод, щоб той переправив його через море до Древа Знань Ону на Темному Узбережжі.",h="Послання Фандрала — лист, написаний Архідруїдом Фандралом Стаґгелмом у Дарнасусі.",kw={"послання фандрала","фандрал стаґгелм","ону","древо знань","гай прадавніх","темне узбережжя","коло кенарія"},ang={["class:Druid"]="Листування між Ценаріонським Анклавом у Дарнасусі та Древами Знань на Темному Узбережжі показує, як різняться погляди: наполегливий натиск Фандрала Стаґгелма — і терпляча вірність традиціям старших друїдичних охоронців.",["race:NightElf"]="Доставка цієї депеші — один із перших кроків із вершини Тельдрассилу назад, до прадавніх лісів материкового Калімдору."},sec={{t="Депеша від Архідруїда",b="Цю запечатану депешу Архідруїд Фандрал Стаґгелм написав у Ценаріонському Анклаві. Це пряме листування між тимчасовим очільником друїдів нічних ельфів та Ону — шанованим Древом Знань, що живе в Гаю Прадавніх. Отримавши звістки про стан Галявини Оракула на Тельдрассилі, Стаґгелм не гає часу й одразу відряджає гінців на південь від Обердайна. Щоб доставити послання, мандрівникам доводиться перетнути води до Темного Узбережжя — так серце нового Світового Древа з'єднується зі старішим, похмурим материком."},{t="Два різні ритми",b="Що саме написано в посланні, знають лише Архідруїд та Ону, але сама доставка виявляє тонкий розкол у вдачі Кола Кенарія. Приймаючи лист, Ону зауважує, що Фандрал раз у раз виявляє дивне для друїда нетерпіння й квапить події, які, на думку прадавніх, мають розгортатися своїм плином. Для неквапливих деревних створінь Темного Узбережжя рвучка поквапливість Фандрала разюче контрастує з терплячою мудрістю, яку колись утілював Архідруїд Малфуріон Стормрейдж."}},faq={{q="Що таке Послання Фандрала?",a="Це офіційне письмове послання від Архідруїда Фандрала Стаґгелма до Ону — Древа Знань, що живе в Гаю Прадавніх на Темному Узбережжі.",al={"послання фандрала","предмет послання фандрала","лист верховного друїда"}},{q="Хто надсилає це послання й навіщо?",a="Архідруїд Фандрал Стаґгелм пише його в Дарнасусі. Отримавши звістки про Галявину Оракула на Тельдрассилі, він сповіщає Ону, який давно чекає новин із крони Світового Дерева.",al={"хто це написав","навіщо фандрал надіслав послання"}},{q="Куди слід віднести послання?",a="Послання треба принести Ону в Гай Прадавніх, що на Темному Узбережжі просто на південь від прибережного поселення Обердайн.",al={"хто отримує послання","куди доставити послання","призначення послання фандрала"}},{q="Що Ону думає про лист?",a="Отримавши його, Ону зауважує, що Фандрал, здається, вічно кудись поспішає. Прадавній каже, що природа рухається у своєму, відміряному їй ритмі, і роздумує, що шан'до Малфуріон Стормрейдж розумів цю істину куди краще за Фандрала.",al={"реакція ону","що каже ону"}}},fp="17,182,29.563.0,18.503.1,26.157.0,31.207.0,35.149.0,34.232.0"}
P.entries["item:fang-of-vagash"] = {n="Ікло Ваґаша",s="Ікло Ваґаша — величезний хижацький зуб, узятий у сумнозвісного звіра Ваґаша серед засніжених скель Дун Мороґу. Для місцевих тваринників це відчутний доказ того, що чудовисько, яке загрожувало їхнім цінним баранам, нарешті вбито.",h="Ікло Ваґаша — величезний хижацький зуб, узятий у сумнозвісного звіра Ваґаша серед засніжених скель Дун Мороґу.",kw={"ікло ваґаша","ваґаш","ранчо амберстілл","барани","хижак","дун мороґ","трофей"},ang={["class:Hunter"]="Вистежити такого верховного хижака, як Ваґаш, серед крижаних скель Дун Мороґу — рання перевірка вміння йти по сліду, виживати в дикій природі й убивати звірів.",["race:Dwarf"]="Ранчо Амберстілл постачає витривалих гірських баранів, без яких не обійтися ні дворфійським горянам, ні мандрівникам. Принести ікло Ваґаша — означає зберегти найцінніший верховий виводок Айронфорджа."},sec={{t="Трофей полювання",b="Високі скелі Дун Мороґу — домівка лютого холоду й лютих хижаків, та жоден не дошкуляв місцевим ранчо так, як Ваґаш. Цей дикий звір, що зачаївся на гребенях над Ранчо Амберстілл, часто спускається під покровом темряви, щоб різати цінних баранів. Війська Айронфорджа й так розтягнуті до краю, тож місцеві пастухи не можуть розраховувати на захист міської варти. Убити звіра й вирізати одне з його лютих ікол — незаперечний доказ того, що пасовиська знову в безпеці."}},faq={{q="Для чого потрібне Ікло Ваґаша?",a="Ікло приносять скотарям на Ранчо Амберстілл у Дун Мороґу як речовий доказ, що Ваґаша вбито. Натомість вдячні скотарі винагороджують мисливця, який уберіг їхній достаток.",al={"використання ікла ваґаша","що робити з іклом ваґаша","здати ікло ваґаша"}},{q="Хто такий Ваґаш?",a="Ваґаш — надзвичайно небезпечний звір, що має лігво на засніжених пагорбах просто над баранячими пасовищами в Дун Мороґу. Серед місцевих дворфів він здобув лиху славу, бо ночами нападає на отари.",al={"що таке ваґаш","де ваґаш","історія ваґаша"}},{q="Чому варта Айронфорджа не вбила Ваґаша?",a="Військ Айронфорджа й так ледве вистачає. Солдатів на сільські патрулі майже немає, тож скотарі мусять покладатися на мандрівних шукачів пригод, щоб упоратися з небезпечними хижаками.",al={"чому варта не допомагає","де армія айронфорджа","гірські стрільці й ваґаш"}}},fp="14,246,18.521.0,36.207.0,14.195.0,45.173.0"}
P.entries["item:fangore-s-paw"] = {n="Лапа Фанґора",s="Лапа Фанґора — відрубана лапа Лейтенанта Фанґора, одного з командирів гнолів Тіньової Шкури у Горах Редріджу. Для Магістрата Соломона в Лейкширі вона — моторошний доказ загибелі гнолівського ватажка. Нагороду за неї призначили, щоб покінчити із загрозою, яку цей воєвода становив для обложеного містечка.",h="Лапа Фанґора — відрубана лапа Лейтенанта Фанґора, одного з командирів гнолів Тіньової Шкури у Горах Редріджу.",kw={"лапа фанґора","лейтенант фанґор","гноли Тіньової Шкури","магістрат соломон","лейкшир","морґант"},ang={["faction:Alliance"]="Убивши Фанґора й принісши його лапу, ви даруєте неабияку полегкість обложеному Лейкширу, якому Стормвінд майже не допомагає військом."},sec={{t="Трофей полеглого ватажка",b="Лейтенант Фанґор — один із головних польових командирів гнолів Тіньової Шкури, що розповзаються Горами Редріджу. Служачи безпосередньо магові-ренегату Морґанту, Фанґор керує жорстокими нападами на торгові шляхи, віддалені ферми й укріплення довкола Озера Незрушного. Гноли-грабіжники не носять мундирів, печаток чи знамен, за якими можна було б підтвердити їхні втрати, тож міська влада покладається на похмурі речові докази. Магістрат Соломон окремо вимагав лапу Фанґора як незаперечний доказ його страти — щоб Лейкшир, оточений дедалі більшими небезпеками, міг хоч трохи легше зітхнути."}},faq={{q="Кому належить ця лапа?",a="Лапа належить Лейтенантові Фанґору — сумнозвісному ватажкові клану гнолів гнолів Тіньової Шкури, що заполонили Гори Редріджу. Він організовує набіги й водить загони за вказівками темного чарівника Морґанта.",al={"хто такий фанґор","чия це лапа","особа фанґора"}},{q="Навіщо Магістратові Соломону лапа?",a="Магістрат Соломон оголосив офіційний розшук, назвавши Фанґора мерзенним ворогом Стормвінда. Відтята лапа потрібна йому як незаперечний речовий доказ того, що лейтенанта гнолів Тіньової Шкури убито.",al={"навіщо збирати лапу фанґора","доказ нагороди соломона","доказ для магістрата"}},{q="На кого працює Лейтенант Фанґор?",a="Фанґор служить Морґантові — ренегатові, що опанував темну магію: той загрожує Лейкширу зі своєї вежі в східних горах і спрямовує гнолів проти королівства.",al={"господар фанґора","хто очолює фанґора","зв'язок із морґантом"}},{q="Де знайти Лейтенанта Фанґора?",a="Лейтенант Фанґор орудує в нетрях Гір Редріджу, серед ворожих таборів гнолів гнолів Тіньової Шкури.",al={"місце фанґора","де фанґор","знайти фанґора"}}},fp="13,321,28.647.0,28.209.0,41.207.0,38.171.0,34.119.0"}
P.entries["item:farren-s-report"] = {n="Звіт Фаррена",s="Звіт Фаррена — офіційне донесення, яке Лейтенант Фаррен Орінелль склав у Саутшорі про свої розслідування щодо місцевих наг. Фаррен використовує цей документ, щоб звернутися до свого колишнього наставника, Майора Семюелсона у Фортеці Стормвінда, сподіваючись домогтися переведення назад до столиці.",h="Звіт Фаррена — офіційне донесення, яке Лейтенант Фаррен Орінелль склав у Саутшорі про свої розслідування щодо...",kw={"звіт фаррена","фаррен орінелль","саутшор","майор семюелсон","наги","фортеця стормвінда"},ang={["faction:Alliance"]="Документ висвітлює бюрократичні хитрощі у війську Альянсу, де далекі пости в Гілсбреді стикаються з офіцерами, що вигадують, як дістати безпечнішу службу в Стормвінді.",["race:Human"]="Для людей Альянсу доставка звіту Фаррена простежує тривкий зв'язок між обложеним прихистком Саутшором і королівським двором у Фортеці Стормвінда."},sec={{t="Квиток із Саутшора",b="Служачи на неспокійному узбережжі Передгір'я Гілсбреда, Лейтенант Фаррен Орінелль утомився від місцевого начальства й далекого прикордоння. Доручивши шукачам пригод полювати на наг Кинджалоспинів, щоб зібрати докази їхньої загрози, Орінелль виклав свої висновки в офіційному звіті. Замість подати його своєму командирові, Магістратові Генрі Малебу, чи місцевому ветеранові Маршалові Редпату, Фаррен вирішив надіслати його просто Майорові Семюелсону, капітанові варти у Фортеці Стормвінда. Фаррен навчався під проводом Семюелсона й сподівався, що документ доведе його вправність і виправдає негайне переведення назад, до зручностей Стормвінда."}},faq={{q="Що таке Звіт Фаррена?",a="Це офіційне військове донесення, яке написав Лейтенант Фаррен Орінелль. У ньому підсумовано його дії проти наг Кинджалоспинних, що вдираються на пляжі Саутшора.",al={"звіт фаррена","що це за звіт","звіт орінель"}},{q="Чому Фаррен хоче доставити звіт до Стормвінда?",a="Фаррен хоче, щоб його перевели із Саутшора назад до Стормвінда. Він адресує звіт просто Майорові Семюелсону — своєму колишньому наставникові й капітанові варти Стормвінда, — сподіваючись на прихильне рішення про переведення.",al={"чому надсилати звіт до стормвінда","мета фаррена","чому семюелсон"}},{q="Чому Фаррен приховує звіт від Редпата?",a="Фаррен не хоче пильної уваги Маршала Редпата й місцевого командування: тим може не сподобатися, що офіцер використовує місцеву загрозу лише для того, щоб улаштувати собі переведення назад у безпечну столицю.",al={"чому ховати від редпата","таємниця старого редпата"}},{q="Як Майор Семюелсон сприймає звіт?",a="Майор Семюелсон хвалить колишнього учня за ініціативу в боротьбі з нагами Саутшора й обіцяє врахувати звіт, коли наступного місяця розглядатиме призначення вартових.",al={"реакція семюелсона","здати переведення"}}},fp="15,287,26.658.0,24.162.0,49.226.0,55.208.0,49.193.1"}
P.entries["item:fathom-core"] = {n="Глибинне Ядро",s="Глибинне Ядро — особлива реліквія, здобута із затопленого глибинного каменя в надрах Чорноглибинних Печер. Розшифроване, воно дає докладний літопис стихійної діяльності в навколишньому краї. Земляне Кільце шукає цей артефакт, щоб з'ясувати, які темні обряди проводить культ Молота Присмерку під Ашенвалем.",h="Глибинне Ядро — особлива реліквія, здобута із затопленого глибинного каменя в надрах Чорноглибинних Печер.",kw={"глибинне ядро","земляне кільце","молот присмерку","чорноглибинні печери","дже'ню санкреа","застава зорам'гар"},ang={["class:Shaman"]="Як артефакт, що літописить стихійні течії, Глибинне Ядро надзвичайно цікаве для Земляного Кільця: воно показує, як прадавні реліквії можуть викрити маніпуляції стихіями.",["faction:Horde"]="Здобуте ядро прямо допомагає Дже'ню Санкреа й зміцнює позиції Орди на Заставі Зорам'гар проти згубних задумів Молота Присмерку."},sec={{t="Стихійний літопис",b="Глибинне Ядро, що лежить у прадавньому глибинному камені, затопленому серед Руїн Місячної Святині, — це літопис стихійних явищ. Воно фіксує й зберігає зсуви, збурення й сплески стихій протягом часу. Для шаманів Земляного Кільця на Заставі Зорам'гар здобути ядро вкрай важливо, щоб зрозуміти, як сектанти Молота Присмерку маніпулюють стихіями краю у власних цілях."}},faq={{q="Що таке Глибинне Ядро?",a="Глибинне Ядро — магічний пристрій, що записує й переказує докладну історію всієї стихійної діяльності довкола себе. Його знаходять у прадавньому глибинному камені в Руїнах Місячної Святині.",al={"що робить глибинне ядро","історія глибинного ядра","що це таке"}},{q="Де знайти Глибинне Ядро?",a="Ядро лежить глибоко в печерних залах Чорноглибинних Печер на узбережжі Ашенвалю — всередині глибинного каменя під водами Руїн Місячної Святині.",al={"місце глибинного ядра","де знайти глибинне ядро","місце глибинного каменю"}},{q="Кому потрібне Глибинне Ядро й навіщо?",a="Ядро шукає Дже'ню Санкреа — шаман Земляного Кільця із Застави Зорам'гар. Вивчивши записи про зміни стихій, Дже'ню та його коло сподіваються розгадати підривні дії культу Молота Присмерку в руїнах і протидіяти їм.",al={"кому потрібне глибинне ядро","чому дже'неу хоче глибинне ядро","кільце землі й ядро"}},{q="Чому Молот Присмерку цікавиться Чорноглибинними Печерами?",a="Культисти засіли в затоплених руїнах, щоб підкорити й зіпсувати місцеві стихії, спрямувати їх на темні цілі й цілком заволодіти підземним храмом.",al={"молот присмерку чорноглибинні печери","культисти в чорноглибинних печерах"}}},fp="11,341,19.449.0,24.210.0,33.185.0,34.259.0,61.195.0"}
P.entries["item:feather-charm"] = {n="Талісман з Пера",s="Талісмани з Пера — грубі магічні дрібнички, які носять новачки тролів Морозогривів у засніжених низинах Долини Холодного Хребта. Хоч зроблені вони з простих матеріалів, у них живе природний чаклунський відгук, що привертає увагу місцевих наставників-чорнокнижників.",h="Талісмани з Пера — грубі магічні дрібнички, які носять новачки тролів Морозогривів у засніжених низинах...",kw={"талісман з пера","чорнокнижник","морозогриви","тролі","аламар грімм","біс","анвілмар"},ang={["class:Warlock"]="Для чорнокнижників-новачків у Дун Мороґу відібрати талісмани з пера в тролячих чаклунів — головне випробування дисципліни, перш ніж Аламар Грімм довірить їм ритуал призову біса.",["race:Gnome"]="Гномські чорнокнижники, що працюють з Анвілмара, вивчають ці примітивні тролячі фетиші, щоб розібрати сиру, невідшліфовану магію, яку спрямовують первісні чаклуни Морозогривів."},sec={{t="Тролячі дрібнички й темні студії",b="Тролі Морозогриви, що живуть у засніжених печерах на південний захід від Анвілмара, відомі здебільшого територіальною жорстокістю, але їхні новачки бавляться примітивним чаклунством. Талісмани з пера, які носять ці молоді тролі, таять слабку, але безпомильну магічну силу. В Анвілмарі наставник чорнокнижників Аламар Грімм вважає їх цікавим предметом для вивчення — несподівано для грубої тролячої роботи — і використовує як випробування для новачків-чорнокнижників, які прагнуть опанувати прив'язування свого першого біса."}},faq={{q="Хто носить ці талісмани з пера?",a="Їх носять новачки-Морозогриви, що ховаються в засніженій печері на південний захід від Анвілмара в Долині Холодного Хребта.",al={"звідки талісмани з пера","хто дропає талісман з пера","талісман новачка морозогривів"}},{q="Навіщо вони Аламарові Ґрімму?",a="Аламар Грімм вважає вроджену магію талісманів цікавою й вартою дослідження — що, як він зауважує, доволі несподівано для тролівської роботи. Він вимагає їх від майбутніх чорнокнижників, щоб перевірити їхню витривалість і магічний хист, перш ніж навчити викликати біса.",al={"навіщо аламару талісмани","аламар ґрімм талісмани з пера","що ґрімм з ними робить"}},{q="Чи вправні Морозогриви в магії?",a="Хоча плем'я Морозогривів здебільшого вважають грубим і ворожим, їхні новачки вміють творити найпростіші чари. Талісмани з пера зосереджують цю нехитру магію — тож навіть їхні недосвідчені заклиначі користуються таємною чи шаманською силою.",al={"чи морозогриви вправні в магії","магія новачків морозогривів"}},{q="Який вигляд мають талісмани?",a="Це прості обереги, сплетені з пір'я й мотузки: новачки-Морозогриви роблять їх як осередки для перших магічних вправ у холодних печерах Дун Мороґа.",al={"опис талісмана з пера","вигляд талісмана"}}},fp="13,252,31.492.0,33.119.0,32.277.0,43.250.0,29.161.0"}
P.entries["item:fel-cone"] = {n="Шишка Скверни",s="Шишки Скверни — споганені насінні коробочки, що падають із віття Тельдрассила; їх легко впізнати за отруйними зеленими випарами з лушпиння. Хоч вони огидні й отруєні темними силами, тутешні захисники — нічні ельфи знаходять їм хитре застосування проти поблизьких шахраїв.",h="Шишки Скверни — споганені насінні коробочки, що падають із віття Тельдрассила; їх легко впізнати за отруйними...",kw={"шишка скверни","скверна","зенн фаулгуф","сатир","сірал блейдліф","доланаар","тельдрассил","жаба"},ang={["class:Druid"]="Бачити, як здорові лісові насінні коробочки скисають на димучі рештки Скверни, — похмуре нагадування друїдам про крихку рівновагу, за яку борються по всьому Тельдрассилу.",["race:NightElf"]="Існування Шишок Скверни — тривожний знак хвороби глибоко в корінні Тельдрассила, доказ того, що навіть молоде зростання Світового Дерева не вбережене від демонічної скверни."},sec={{t="Пошесть у шатрі",b="Тельдрассил молодий, та скверна вже просочилася в його живу деревину. Шишки Скверни — видимий доказ цього підступного гниття: покручені опалі соснові шишки, що клубочаться огидним зеленим димом. Розкидані під віттям одразу на схід від Доланаара, ці коробочки просякнуті споганеною магією, яка викривлює природну рослинність і робить їх небезпечними для необережного дотику чи споживання."},{t="Гіркі ліки",b="Коли необачні мандрівники піддаються на хитрощі Зенна Фаулгуфа — сатира, що чигає на подорожніх і підбурює їх виконувати свою волю, — тутешні охоронці вимагають покути. Сірал Блейдліф і Вартові велять розкаяним шукачам пригод зібрати ці отруйні шишки й віддати їх Фаулгуфу під виглядом невинного наїдку. Зосереджена скверна в насінні спричиняє дивне перетворення й на якийсь час обертає огидного сатира на нешкідливу жабу."}},faq={{q="Що таке Шишка Скверни?",a="Шишка Скверни — зіпсована соснова шишка, що падає з гілок Тельдрассила. Отруєна неприродною магією, вона курить моторошним зеленим димом і містить нестійку перетворювальну енергію.",al={"що таке шишки скверни","історія шишки скверни","що це шишка скверни"}},{q="Де знайти Шишки Скверни?",a="Вони лежать на лісовій землі під деревами трохи на схід від Доланаара, в самому серці Тельдрассила.",al={"де шишки скверни","місце шишки скверни","як знайти шишки скверни"}},{q="Чому Рада Лісу хоче, щоб їх зібрали?",a="Якщо ви ненароком допомогли сатирові Зенну Фаулгуфу зашкодити створінням природи, Рада Лісу дає змогу спокутувати провину. Вона доручає зібрати Шишки Скверни й підступом змусити Зенна їх з'їсти — йому на науку.",al={"пошук спокути шишки","чому збирати шишки скверни","хто хоче шишки скверни"}},{q="Що стається, коли хтось з'їдає Шишку Скверни?",a="Рада Лісу хоче, щоб шишки провчили Зенна Фаулгуфа. Розраховують, що він прийме їх за безневинну закуску, а що саме вони зроблять, з'ясується, коли задум здійсниться.",al={"що робить шишка скверни","з'їсти шишку скверни","зенн фаулгуф жаба"}}},fp="8,264,20.376.0,17.455.1,19.191.0,29.114.0,55.219.0,42.192.1"}
P.entries["item:fel-moss"] = {n="Мох Скверни",s="Мох Скверни — споганена рослинна речовина, що розповзається лісами Тельдрассила. Він несе демонічні, руйнівні сили, його розносять ворожі ґрелли та ґреллята, і він становить підступну загрозу для звірини й корінних племен фурболгів Світового Дерева.",h="Мох Скверни — споганена рослинна речовина, що розповзається лісами Тельдрассила.",kw={"мох скверни","скверна","ґрелли","фурболги","вузлошкіри","тариндрелла","тінедол","тельдрассил"},ang={["class:Druid"]="Для друїдів Кола Кенарія Мох Скверни — тривожна пухлина, що розповзається Тельдрассилом, і доказ того, що новонароджене Світове Дерево глибоко вразливе до демонічної пошесті.",["race:NightElf"]="Нічні ельфи шанують Тельдрассил як нову батьківщину, тож присутність Моху Скверни — гнітюче знамення: мир лишається невловимим навіть на їхньому священному вітті."},sec={{t="Пошесть на Світовому Дереві",b="Тельдрассил посадили, щоб повернути нічним ельфам безсмертя й зцілити природний світ, та скверна вже прокралася в його незаймане віття. Мох Скверни — один із найпомітніших знаків цього занепаду. Він чіпляється до бісуватих ґреллів і ґреллят, що заполонили Тінедол, і мандрує разом із ними, випромінюючи неприродну, лиху магію. Захисники лісу, як-от дріада Тариндрелла, взялися збирати зразки, щоб виміряти, як глибоко це гниття проникло у священне лісове шатро."},{t="Насіння безумства",b="Небезпека Моху Скверни сягає далі простого лісового гниття: він має згубний вплив на розум живих створінь. Колись мирні фурболги з висот Тельдрассила піддалися його дотику, покинули свої споконвічні оселі й збилися у вороже плем'я Вузлошкірів. Доведені до безумства лихою силою моху під проводом ватажків на кшталт Урсала Гамаїла, ці уражені створіння виявляють дедалі більшу хворобу, що вкорінюється у великому дереві."}},faq={{q="Що таке Мох Скверни?",a="Мох Скверни — мерзенна, магічно зіпсована рослинність на Тельдрассилі. Сповнений лихої енергії, він чіпляється до заразних істот і поширює божевілля та тілесне зіпсуття довкола.",al={"історія моху скверни","що таке мох скверни","що робить мох скверни"}},{q="Звідки береться Мох Скверни?",a="На Тельдрассилі шукачі пригод знімають жмутки Моху Скверни з викривлених греллів і греллят, що блукають схилами довкола Тінедолу. Він породжений мерзенними силами зіпсуття, що пустили коріння в самому Світовому Дереві.",al={"де взяти мох скверни","дроп моху скверни","джерело моху скверни"}},{q="Як Мох Скверни діє на фурболгів?",a="Мох Скверни — каталізатор зіпсуття. Його лиха сила доводить фурболгів до жорстокого шалу й перетворює колись мирні племена Тельдрассила на агресивних і ворожих до чужинців Вузлошкірів.",al={"скверна фурболгів","чому ґнарлпайни шалені","ґнарлпайн мох скверни"}},{q="Хто намагається спинити поширення Моху Скверни?",a="Дріада Тариндрелла в Тінедолі просить молодих захисників зібрати зразки Моху Скверни з греллят, щоб підтвердити свої підозри щодо зіпсуття лісу. Стурбованих оборонців вона посилає далі — до друїдів, як-от Атрідаса Бермантла в Доланаарі.",al={"хто вивчає мох скверни","хто хоче мох скверни","завдання таріндрелли"}}},fp="8,264,24.512.0,16.473.1,17.211.0,30.222.0,38.207.0,45.242.0"}
P.entries["item:felix-s-box"] = {n="Скринька Фелікса",s="Скринька Фелікса — невеликий контейнер з особистими речами Фелікса Віндлболта, біженця, що втік після падіння Гномреґану. Загублену під час панічної евакуації до Дун Мороґу скриньку розграбували місцеві тролі Морозогриви й віднесли до своїх таборів на південний захід від Анвілмара.",h="Скринька Фелікса — невеликий контейнер з особистими речами Фелікса Віндлболта, біженця, що втік після падіння...",kw={"скринька фелікса","фелікс віндлболт","гномреґан","біженець","морозогриви","тролі","анвілмар"},ang={["profession:Engineering"]="Повернуті інструменти й контейнери — рятівна нитка для винахідника, і вони підкреслюють, яких злигоднів зазнають переселені гномські ремісники, розлучені зі своїм обладнанням.",["race:Gnome"]="Для гномів-шукачів пригод, що починають шлях у Долині Холодного Хребта, повернути особисті речі Фелікса — означає напряму полегшити долю побратима-вигнанця, який потерпає від гірких наслідків евакуації Гномреґану."},sec={{t="Загублена під час утечі з Гномреґану",b="Коли Гномреґан затопила радіація під час невдалої спроби вичистити трогів, Фелікс Віндлболт приєднався до панічного виходу гномів у Долину Холодного Хребта. У відчайдушній втечі від радіоактивних випарів Фелікс загубив свої найцінніші речі й ремісниче знаряддя на засніженій дорозі. Перш ніж він устиг їх повернути, тутешні тролі Морозогриви розграбували залишки край дороги й затягли його скриньку разом зі скринею та відром болтів до своїх грубих поселень на південний захід від Анвілмара."},{t="Біда біженця",b="Незвиклий до насильства й не пристосований до суворої пустки Дун Мороґу, Фелікс був змушений просити допомоги в подорожніх шукачів пригод в Анвілмарі, щоб повернути своє майно. Повернути Скриньку Фелікса — це не просто віддати скромний контейнер: це повернути дещицю звичного життя й заробітку переселеному ремісникові, який утратив усе в катастрофі, що поглинула його підземну батьківщину."}},faq={{q="Що таке Скринька Фелікса?",a="Це скринька з особистими речами Фелікса Віндлболта — гнома-майстра, що втік із Гномреґана після катастрофічного зараження міста.",al={"скринька фелікса","що це за скринька","історія скриньки фелікса"}},{q="Як скринька опинилася в тролів-Морозогривів?",a="Фелікс покинув своє спорядження, тікаючи від отруйних випарів, що валили з Гномреґана. Тролі-Морозогриви, що патрулюють пагорби на південний захід від Анвілмара, підібрали речі при дорозі й затягли до свого табору.",al={"чому в тролів скринька фелікса","хто вкрав скриньку фелікса","як її загубили"}},{q="Хто такий Фелікс Віндлболт?",a="Фелікс Віндлболт — гном-біженець, звичайний цивільний, що тепер живе в Анвілмарі. Падіння Гномреґана глибоко його вразило, і він лишився без найпотрібніших інструментів і особистих речей.",al={"фелікс віндлболт","хто такий фелікс"}},{q="Що ще втратив Фелікс?",a="Крім скриньки, тролі-Морозогриви пограбували Скриню Фелікса та його Відро Болтів і розтягли все це по своїх таборах на південний захід від Анвілмара.",al={"інші речі фелікса","майно фелікса","що ще загубив фелікс"}}},fp="11,281,34.514.0,20.412.0,20.154.0,49.210.0,25.174.0,32.150.0"}
P.entries["item:felix-s-bucket-of-bolts"] = {n="Відро Болтів Фелікса",s="Відро Болтів Фелікса — ємність із запасними деталями й інструментами, що належить Феліксу Віндлболту, гному-біженцю, який утік після падіння Гномреґану. Під час його втечі до Дун Мороґу відро вихопили місцеві тролі Морозогриви й затягли до своїх сусідніх таборів.",h="Відро Болтів Фелікса — ємність із запасними деталями й інструментами, що належить Феліксу Віндлболту...",kw={"відро болтів","фелікс віндлболт","гномреґан","інженерія","морозогриви","тролі","біженець"},ang={["profession:Engineering"]="Жоден майстер не працюватиме без базового кріплення, тож просте відро болтів стає цінним надбанням, коли починаєш усе спочатку серед снігів Дун Мороґу.",["race:Gnome"]="Кожне врятоване відро деталей — ще один крихітний шматочок Гномреґану, вирваний у руїни, що допомагає біженцям закріпитися в Долині Холодного Хребта."},sec={{t="Розкидане знаряддя біженця",b="Коли після катастрофи у війні з трогами Гномреґан затопила радіація, тисячі гномів утекли в крижані пустки Дун Мороґу з тим, що змогли винести. Фелікс Віндлболт зумів вибратися зі своїм найважливішим обладнанням, але в сум'ятті втечі до Анвілмара потрапив у засідку тролів Морозогривів, що мешкають у скелях на південний захід від містечка. Тролі розграбували його майно, зокрема й це відро, повне болтів і деталей, лишивши ремісника без матеріалів, конче потрібних, щоб працювати за фахом у вигнанні."}},faq={{q="Що таке Відро Болтів Фелікса?",a="Це важке відро з металевими болтами, кріпленнями й майстровим приладдям, що належить Феліксові Віндлболту — гномові-вигнанцеві, який знайшов прихисток в Анвілмарі.",al={"відро болтів","відро фелікса","відро болтів фелікса"}},{q="Хто вкрав відро?",a="Відро разом з іншими особистими речами Фелікса вкрали тролі-Морозогриви, коли він тікав від катастрофи в Гномреґані.",al={"хто взяв болти","тролі вкрали відро","у кого болти фелікса"}},{q="Куди тролі його забрали?",a="Тролі віднесли його до своїх таборів серед скель на південний захід від Анвілмара в Долині Холодного Хребта.",al={"де болти","місце відра","табір болтів фелікса"}},{q="Чому це відро таке важливе для Фелікса?",a="Гноми-біженці втекли з дому майже ні з чим. Для інженера чи майстра, як Фелікс, звичайні кріплення й деталі — необхідність, щоб вижити й відбудувати життя далеко від Гномреґана.",al={"чому фелікс хоче болти","важливість болтів фелікса віндлболта"}}},fp="23,265,27.541.0,32.156.0,21.131.0,29.103.0,38.199.0"}
P.entries["item:felix-s-chest"] = {n="Скриня Фелікса",s="Скриня Фелікса — контейнер з особистими речами, який вигнанець-гном Фелікс Віндлболт загубив під час утечі з Гномреґану. Її віднесли тролі Морозогриви, що никають біля Долини Холодного Хребта, і тепер вона стоїть покинута в одному з їхніх примітивних гірських таборів.",h="Скриня Фелікса — контейнер з особистими речами, який вигнанець-гном Фелікс Віндлболт загубив під час утечі з...",kw={"скриня фелікса","фелікс віндлболт","гномреґан","евакуація","морозогриви","тролі","анвілмар"},ang={["race:Gnome"]="Скриня — болісне нагадування про хаотичну евакуацію Гномреґану, коли гноми-втікачі втратили майже все через дику природу та мародерів-опортуністів."},sec={{t="Утрати біженця",b="Коли підземне техномісто Гномреґан упало під натиском трогів і отруйних радіоактивних опадів, тисячі гномів кинулися на засніжену поверхню Дун Мороґу з тим майном, що змогли понести. Фелікс Віндлболт зумів вибратися з опромінених руїн, але серед паніки евакуації тутешні тролі Морозогриви нишпорили по дорогах і наздоганяли розрізнених уцілілих. Фелікс утратив основне знаряддя й пожитки, а його міцну скриню затягли до грубих таборів, які тролі тримають у скелях на південний захід від Анвілмара."}},faq={{q="Що в Скрині Фелікса?",a="У скрині — особисті речі, які Фелікс Віндлболт зумів урятувати, тікаючи з Гномреґана. Він покинув їх, поспішаючи втекти від смертельного випромінювання. Тролям від них мало користі, але для Фелікса це вцілілі рештки колишнього життя.",al={"вміст скрині фелікса","що в скрині","здобич зі скрині фелікса"}},{q="Чому речі Фелікса в тролів-Морозогривів?",a="Тролі-Морозогриви раз у раз нападають на мандрівників і нишпорять Долиною Холодного Хребта. Коли розгублені гноми-біженці розбрелися Дун Мороґом, рятуючись зі зруйнованого міста, тролі підстерегли тих, хто відстав, і потягли кинуті речі й поклажу до своїх стоянок.",al={"чому в тролів скриня фелікса","хто вкрав скриню фелікса","тролі фелікс віндлболт"}},{q="Де знайти скриню?",a="Скриня на південний захід від Анвілмара в Долині Холодного Хребта — біля наметів поселення тролів-Морозогривів, разом з іншим награбованим добром.",al={"де скриня фелікса","місце скрині фелікса","знайти скриню фелікса"}}},fp="13,257,18.547.0,29.271.0,52.277.0,27.148.0"}
P.entries["item:felstalker-hoof"] = {n="Копито Переслідувача Скверни",s="Копито Переслідувача Скверни — речовий знак, здобутий із демонічних звірів, що кишать у Ковені Палаючого Клинка в Долині Випробувань у Дуроторі. Молоді шамани мають здобути ці копита як випробування готовності, перш ніж навчитися єднатися з духами стихії землі.",h="Копито Переслідувача Скверни — речовий знак, здобутий із демонічних звірів, що кишать у Ковені Палаючого...",kw={"копито","переслідувач скверни","шаман","ерткаллер","ковен","долина випробувань","тотем землі"},ang={["class:Shaman"]="Убивство демонів і збирання їхніх копит — ваш перший великий крок до єднання з духами землі, перевірка терпіння й упертої стійкості, потрібних, щоб володіти Тотемом Землі.",["faction:Horde"]="Присутність демонічних переслідувачів Скверни на тренувальних землях Дуротару — постійне нагадування про скверну Палаючого Клинка, що й досі тліє на землях Орди."},sec={{t="Випробування шамана",b="У випаленій сонцем Долині Випробувань наставник Канаґа Ерткаллер доручає шаманам-початківцям стати на герць із демонічною скверною, що загрожує Дуротару. Ковен Палаючого Клинка на півночі ховає мерзенних фамільярів і демонічних переслідувачів Скверни. Забрати копита цих бісів — не просто знищення шкідників, а суворе випробування витривалості, рішучості й духу. Лише приборкавши цих хаотичних звірів, майбутній шаман доводить, що гідний прийняти таємниці землі та приготувати обрядову сапту, потрібну для прямого єднання з духами стихій."}},faq={{q="Для чого потрібне Копито Переслідувача Скверни?",a="Два Копита Переслідувача Скверни приносять Канаґі Ерткаллер у Долині Випробувань. Вони доводять, що новачок-шаман має досить сили й духу, щоб почати спілкування зі стихією землі.",al={"що робить копито переслідувача скверни","предмет копито","навіщо збирати копита"}},{q="Звідки ці копита?",a="Їх зрізають із демонічних переслідувачів скверни в Ковені Палаючого Клинка та довкола нього, на півночі Долини Випробувань у Дуротарі.",al={"де взяти копито переслідувача скверни","місце копита","хто дропає копита"}},{q="Кому потрібні ці копита?",a="Їх просить Канаґа Ерткаллер, наставниця шаманів біля Лігва в Долині Випробувань, під час обряду «Поклик Землі».",al={"кому потрібні копита","хто хоче копита","завдання канаґи землеклич"}},{q="Чи може будь-який шукач пригод збирати ці копита?",a="Копита Переслідувача Скверни потрібні саме шаманам, що проходять стихійну посвяту. Воїни, чорнокнижники й розбійники мають у долині власні випробування, і ці копита їм ні до чого.",al={"чи може не шаман збирати копита","чи копито лише для шаманів"}}},fp="15,260,16.552.0,37.208.0,32.161.0,26.131.0,40.197.0"}
P.entries["item:fenwick-s-head"] = {n="Голова Фенвіка",s="Голова Фенвіка — моторошний доказ страти Фенвіка Татроса на березі Озера Лордамер. Її здобувають розбійники-Відступники, що виконують наказ, який надійшов від самого лорда Варіматраса.",h="Голова Фенвіка — моторошний доказ страти Фенвіка Татроса на березі Озера Лордамер.",kw={"голова фенвіка","фенвік татрос","озеро лордамер","меннет каркад","скрадачі смерті","варіматрас","розбійник"},ang={["class:Rogue"]="Здобути Голову Фенвіка — важливий рубіж для молодих розбійників-Відступників: він доводить, що на вас можна покластися як на скрадача смерті, і відкриває доступ до вищого навчання.",["race:Undead"]="Це полювання показує, як безжально Відступники придушують суперницькі угруповання нежиті, що змагаються за владу над Срібноліссям і берегами Озера Лордамер."},sec={{t="Замовлення з тіні",b="У Кварталі Розбійників Андерсіті Меннет Каркад діє за терміновими відомостями, що надійшли просто від жахолорда Варіматраса. Ворожий ватажок нежиті на ім'я Фенвік Татрос закріпився біля напівзогнилих причалів на березі Озера Лордамер у Срібноліссі. Щоб ця загроза не згуртувала ворожу нежить проти Відступників, Каркад посилає здібних скрадачів смерті знайти Татроса, убити його й відтяти голову як незаперечний доказ."},{t="Обряд посвяти",b="Принести Каркадові Голову Фенвіка — це не просто отримати винагороду за вбивство: це важливе випробування для агентів-скрадачів смерті. Відрубаний трофей засвідчує вправність розбійника в проникненні й убивстві та відчиняє двері до глибшого, особливого навчання тіньових мистецтв у майстрів-Відступників."}},faq={{q="Хто такий Фенвік Татрос?",a="Лорд Варіматрас назвав Фенвіка Татроса ватажком нежиті, що засів у Срібноліссі. Те, що він тримався біля напівзруйнованих доків на Озері Лордамер, робило його нагальною загрозою для інтересів Відступників у краї.",al={"хто такий фенвік","історія фенвіка татроса","хто був татрос"}},{q="Кому потрібна Голова Фенвіка?",a="Голову вимагає Меннет Каркад, наставник скрадачів смерті з Кварталу Розбійників в Андерсіті, — виконуючи нагальний наказ лорда Варіматраса.",al={"кому потрібна голова","кому віддати","меннет каркад"}},{q="Де знайти Фенвіка Татроса?",a="За відомостями розвідників-скрадачів смерті, Фенвік Татрос причаївся біля напівзруйнованих доків на березі Озера Лордамер у Срібноліссі.",al={"місце фенвіка татроса","де фенвік","знайти фенвіка"}},{q="Чому треба відтяти йому голову?",a="Меннетові Каркаду потрібен незаперечний речовий доказ, що загрозу остаточно знищено, — лише тоді він допустить агента до вищої науки тіні.",al={"навіщо брати голову","чому відтинати голову"}}},fp="14,205,27.472.0,17.334.0,24.229.0,25.171.0,33.158.0,29.160.0"}
P.entries["item:fey-dragon-scale"] = {n="Луска Чарівного Дракона",s="Луска Чарівного Дракона — мерехтлива лісова реліквія, здобута в невловних чарівних драконів, що живуть довкола Піку Кам'яного Кігтя. Її шукає знахар Темного Списа Джин'Зіл, використовуючи як екзотичний реагент в алхімічному зіллі, що глузує з природної магії нічних ельфів.",h="Луска Чарівного Дракона — мерехтлива лісова реліквія, здобута в невловних чарівних драконів, що живуть...",kw={"луска чарівного дракона","чарівні дракони","знахар джин'зіл","малака'джин","пік кам'яного кігтя","нічні ельфи"},ang={["faction:Horde"]="Допомагаючи Джин'Зілові, ви зміцнюєте позиції Орди в Горах Кам'яного Кігтя й б'єте просто по нічних ельфах, що окопалися вище на схилах.",["race:NightElf"]="Чарівні дракони — дорогі серцю супутники й охоронці лісу для калдореїв; бачити, як їхню луску здирають заради смертоносного глуму тролівського знахаря, — обурлива наруга над природою."},sec={{t="Рідкісний лісовий здобуток",b="Чарівні дракони — таємничі, невловні створіння, тісно пов'язані з дикими гаями Калімдору, надто з незайманими лісами довкола Піку Кам'яного Кігтя. Їхня луска має природний магічний полиск, що нагадує про глибокі ліси, які вони стережуть. Нічні ельфи шанують їх як нешкідливих лісових духів і союзників, а чужинці бачать у них дике джерело рідкісних магічних складників."},{t="Глумливе зілля",b="У поселенні Орди Малака'джин Знахар Джин'Зіл варить зловісну суміш, що пародіює священні традиції калдореїв. Поєднуючи луску чарівного дракона з деревною живицею, котячими вусами й десятками очей скакунів, Джин'Зіл варить те, що глузливо називає «лісовою магією». Замість лагідного благословення природи виходить смертельна отрута, що шириться повітрям і призначена для полонених нічних ельфів."}},faq={{q="Звідки ця луска?",a="Луску знімають із чарівних дракончиків, що пурхають гаями нагір'я довкола Піку Кам'яного Кігтя, — зокрема з невловимих хитрих чарівних драконів і Нал'ташзара.",al={"дроп луски чарівного дракона","де знайти луску чарівного дракона","хто дропає луску чарівного дракона"}},{q="Навіщо Знахареві Джин'Зілу луска чарівного дракона?",a="Знахар Джин'Зіл у Малака'джині просить луску разом з іншими лісовими реагентами, щоб зварити те, що він глузливо називає «лісовою магією», для своїх полонених нічних ельфів у клітках.",al={"чому джин'зіл хоче її","для чого луска","реагент лісової магії джин'зіла"}},{q="Що стається, коли Джин'Зіл доварює своє зілля?",a="Джин'Зіл збирається застосувати готове вариво до трьох полонених нічних ельфів. Яка доля спіткає в'язнів, стане відомо, коли він здійснить свій задум.",al={"що джин'зіл робить зі зіллям","результат магії джин'зіла","в'язні джин'зіла"}}},fp="16,269,21.382.0,20.441.1,32.169.0,54.170.0,44.141.1"}
P.entries["item:filled-amethyst-phial"] = {n="Наповнена Аметистова Фіала",s="Наповнена Аметистова Фіала містить священну воду з прадавнього місячного колодязя під віттям Дерева Оракула. Зібрана на прохання Корітраса Мунрейджа, ця очищена вода слугує друїдам Кола Кенарія для вивчення тривожного, недосконалого зростання Тельдрассила.",h="Наповнена Аметистова Фіала містить священну воду з прадавнього місячного колодязя під віттям Дерева Оракула.",kw={"наповнена аметистова фіала","місячний колодязь","дерево оракула","корітрас мунрейдж","фандрал стаґгелм","драконячі аспекти","тельдрассил","нордрассил"},ang={["class:Druid"]="Друїди Кола Кенарія шанують місячні колодязі як провідники природи й зоряної сили і вивчають уражений живий світ Тельдрассила за допомогою очищених посудин, як-от ця фіала.",["race:NightElf"]="Для калдореїв наповнити цю фіалу означає похмуро усвідомити: їхній славний новий дім відкинули Драконячі Аспекти, а втрачене безсмертя не повернулося."},sec={{t="Вода Дерева Оракула",b="Далеко на північному заході Тельдрассила лежить Галявина Оракула, де під великим Деревом Оракула спочиває найстаріший і наймогутніший із місячних колодязів острова. Якщо менші колодязі по всьому вітті служать щоденним потребам нічних ельфів, то води цього колодязя насичені чистою сутністю ласки Елуни. Друїди, яким доручено стежити за здоров'ям Світового Дерева, набирають і зберігають цю могутню рідину в особливих аметистових фіалах для досліджень і обрядового очищення."},{t="Недосконале відродження",b="Повернення цього зразка Корітрасу Мунрейджу має скорботну мету. Попри тріумф Архідруїда Фандрала Стаґгелма, який виростив Тельдрассил на заміну полеглому Нордрассилу, Драконячі Аспекти відмовилися його освятити. Без благословення Ноздорму, яке повернуло б нічним ельфам безсмертя, і Алекстрази, яке захистило б його життєву силу, зростання Тельдрассила лишається кволим і ураженим скверною. Зразки з галявини показують: навіть найсвященніші води острова не приховають повзучої недуги, що вкорінюється у Світовому Дереві."}},faq={{q="Звідки вода в цій фіалі?",a="Воду зачерпують просто з місячного колодязя в Галявині Оракула, на північному заході Тельдрассила, під могутнім корінням Дерева Оракула.",al={"де наповнити","місце місячного колодязя","колодязь дерева оракула"}},{q="Чим особливий місячний колодязь у Галявині Оракула?",a="Його шанують як перший і наймогутніший місячний колодязь, створений на Тельдрассилі: він зберігає зосереджену сутність сили Елуни, а пильнує його саме прадавнє Дерево Оракула.",al={"чому галявина оракула","важливість колодязя оракула"}},{q="Хто просить набрати цієї води?",a="Корітрас Мунрейдж, друїд нічних ельфів із Доланаара, доручає молодим шукачам пригод набрати воду в межах обрядів «Корони Землі».",al={"хто хоче фіалу","завдання корітраса"}},{q="Навіщо друїди перевіряють місячні колодязі Тельдрассила?",a="Тельдрассил виростили без благословення Аспектів драконів, тож він уразливий. Друїди беруть проби з місячних колодязів, щоб стежити за здоров'ям Світового Дерева, яке виявляє тривожні ознаки зіпсуття й чахлого росту.",al={"чому перевіряти воду","хвороба тельдрассила"}}},fp="21,266,24.487.0,16.525.1,45.161.0,44.178.0,34.153.0,50.224.0"}
P.entries["item:filled-blue-waterskin"] = {n="Наповнений Синій Бурдюк",s="Наповнений синій бурдюк містить чисту воду з фонтана в прадавніх Руїнах Зоряного Пилу в Ашенвалі. Шамани, що прагнуть єднання з духами води, набирають цей зразок як важливий реагент для свого випробування посвяти.",h="Наповнений синій бурдюк містить чисту воду з фонтана в прадавніх Руїнах Зоряного Пилу в Ашенвалі.",kw={"наповнений синій бурдюк","руїни зоряного пилу","брайн","шаман","поклик води","ашенваль"},ang={["class:Shaman"]="Здобути цю священну воду — вершина вашого шляху до опанування води: вона вимагає перетнути кордони ворожої сторони, щоб поєднатися з найчистішими джерелами природи.",["faction:Horde"]="Похід на північ у спірні ліси Ашенвалю — справжня небезпека для послушників Орди: він змушує вас вирушити на родові землі нічних ельфів, щоб завершити священні обряди."},sec={{t="Священне джерело Ашенвалю",b="Послушників, що проходять Поклик Води, посилають на північ через кордон із Пусток у густі ліси Ашенвалю. Під горами, що відділяють Ашенваль від Кам'яного Кігтя, за Озером Містраль, лежать Руїни Зоряного Пилу — відлюдне ельфійське святилище, яке стережуть люті лісові звірі. Посеред цього священного озера стоїть незайманий фонтан. Вода, набрана з його чаші в синій бурдюк, не знає ні порчі, ні посухи, і майстри-шамани цінують її для обрядового налаштування."},{t="Обряд злагоди",b="Вода в цій посудині — останній зразок, потрібний Брайн, відлюдниці й знавчині вод, що живе на південних болотах Пусток. Поєднана з водами інших, зовсім несхожих криниць і джерел, ця чиста сутність перетворюється на дар, досить потужний, щоб викликати й угамувати стихійних духів води й завершити випробування послушника."}},faq={{q="Де набирають воду для цього бурдюка?",a="Її зачерпують із невеликого фонтана посеред озера в Руїнах Зоряного Пилу, на південному заході Ашенвалю, трохи за Озером Містраль.",al={"де наповнити","фонтан руїн зоряного пилу","місце води"}},{q="Кому потрібна ця вода?",a="Брайн, досвідчена самітниця з півдня Пусток, доручає новачкам-шаманам принести цю воду в межах випробувань «Поклику Води».",al={"кому потрібна вода","хто хоче синій бурдюк","брайн вода"}},{q="Навіщо збирати цю пробу?",a="Це останній складник, потрібний Брайн, щоб зварити напій надзвичайно чистої води, — він дає майбутньому шаманові змогу спілкуватися з духами води й ушанувати їх.",al={"навіщо мені вона","для чого наповнений синій бурдюк"}},{q="Чи небезпечне місце, де набирають воду?",a="Так. У Руїнах Зоряного Пилу живуть ворожі істоти — місцеві елементалі та люті звірі, що боронять прадавню ельфійську галявину від непроханих гостей.",al={"небезпека руїн зоряного пилу","чи безпечний фонтан ашенвейлу"}}},fp="21,233,26.515.0,17.380.0,51.160.0,24.155.0,46.178.0,50.164.0"}
P.entries["item:filled-brown-waterskin"] = {n="Наповнений Коричневий Бурдюк",s="Наповнений коричневий бурдюк містить свіжу воду з рідкісного ставка біля хатини Брайн у Пустках. Його набирають майбутні шамани, і це перший основоположний крок до приготування сапти, потрібної для єднання з духами води.",h="Наповнений коричневий бурдюк містить свіжу воду з рідкісного ставка біля хатини Брайн у Пустках.",kw={"наповнений коричневий бурдюк","брайн","ставок","шаман","поклик води","пустки"},ang={["class:Shaman"]="Принести цю воду — перше практичне випробування від Брайн під час Поклику Води, яке вчить вас шанувати тендітну рівновагу й люті пристрасті довкола життєдайної вологи."},sec={{t="Життєдайна вода",b="На спраглих просторах Пусток поверхнева вода — і благословення, і поле бою. Ставок під хатиною Брайн дає дорогоцінну вологу, що вабить відчайдушних і ревних до своєї землі шипогривів, які живуть поблизу. Для послушника на шаманському шляху наповнити цей простий шкіряний бурдюк — не просто доручення по припаси, а урок стихій. Наблизившись до ставка й побачивши запеклу боротьбу за нього, новачок на власні очі бачить, як та сама речовина, що підтримує життя в пустелі, може штовхати смертних істот до насильства."}},faq={{q="Для чого потрібен Наповнений Коричневий Бурдюк?",a="Його приносять просто Брайн до її хатини на півдні Пусток. Із зібраної води вона починає готувати стихійну сапту — напій, що дає шаманам змогу бачити духів води й спілкуватися з ними.",al={"використання коричневого бурдюка","що таке наповнений коричневий бурдюк","що робити з наповненим бурдюком"}},{q="Звідки ця вода?",a="Її зачерпують із невеликого прісного ставка трохи нижче по схилу, під відлюдною хатиною Брайн, — оази, за яку люто змагаються місцеві шипогриви.",al={"де взяти воду","місце ставка","де водопій"}},{q="Чому шипогриви б'ються за це джерело?",a="У посушливих Пустках дощ — велика рідкість, тож будь-який ставок — це ціле багатство. Вода така дефіцитна, що шипогриви влаштовують бенкети, коли йде дощ, і боронять природні джерела від чужинців до останнього подиху.",al={"чому квілборги нападають","вода квілборгів","чому вода священна для квілборгів"}}},fp="22,235,21.593.0,44.210.0,32.153.0,49.211.0"}
P.entries["item:filled-cliffspring-falls-sampler"] = {n="Наповнений Пробовідбірник Скельноджерельних Водоспадів",s="Наповнений Пробовідбірник Скельноджерельних Водоспадів містить каламутну воду, набрану у верхів'ях біля Водоспаду Скельного Джерела на Темному Узбережжі. Зібраний на прохання Кола Кенарія, він — важливий доказ у пошуках того, що отруює місцевих оленів.",h="Наповнений Пробовідбірник Скельноджерельних Водоспадів містить каламутну воду, набрану у верхів'ях біля...",kw={"пробовідбірник","водоспад скельного джерела","дендрит старблейз","аланндаріан найтсонг","коло кенарія","наги"},ang={["class:Druid"]="Здобути й дослідити цю отруєну воду — важливе випробування для друїдів Альянсу, що закладає основу для опанування «Зцілення від отрути».",["race:NightElf"]="Для нічних ельфів Темного Узбережжя вберегти верхів'я Скельного Джерела украй важливо, щоб захистити природу довкола Обердайна від мерзенної чужинської порчі."},sec={{t="Отруєне джерело",b="Водоспад Скельного Джерела дає питну воду більшій частині Темного Узбережжя, спадаючи зі східних височин до моря. Та останнім часом звірі, що п'ють цю воду, — передусім місцеві олені — стали жертвами виснажливої, протиприродної хвороби. На прохання Дендрита Старблейза з Місячного Гаю новачки-друїди набирають цю пробу просто біля входу до печери, де засіли ворожі наги. У пробірці помітно смердюча рідина — доказ того, що головне джерело прісної води в краї отруєно."},{t="Шлях до ліків",b="Принесена Аланндаріан Найтсонг в Обердайн, мерзенна проба дає Колу Кенарія відчутний доказ, потрібний, щоб вивчити отруту. Аланндаріан не просто виливає її, а досліджує склад домішок. Розгадавши точні властивості цього мулу, друїди можуть приготувати цілющу мазь — важливий крок до обряду, що дає владу над отрутами."}},faq={{q="Що в Наповненому Пробовідбірнику Скельноджерельних Водоспадів?",a="У ньому отруєна вода, зачерпнута біля входу до печери поряд із Водоспадом Скельного Джерела на Темному Узбережжі. Вода помітно змінила колір і несе отруту, від якої хворіють місцеві олені.",al={"вміст пробовідбірника","яка вода у флаконі","що в пробі"}},{q="Хто просить цю пробу води?",a="Дендрит Старблейз із Кола Кенарія доручає молодим друїдам набрати пробу, а Аланндаріан Найтсонг в Обердайні отримує її, щоб дослідити отруту й створити ліки.",al={"хто хоче пробу води","кому віддати пробовідбірник","кому потрібен пробовідбірник"}},{q="Чому Водоспад Скельного Джерела такий важливий?",a="Водоспад Скельного Джерела — головне джерело питної води для Темного Узбережжя. Будь-яка скверна, що потрапляє у водоспад, розходиться місцевими водоймами й уражає всю дику природу.",al={"чому водоспад кліффспрінг","важливість водоспаду кліффспрінг"}},{q="Що каламутить воду?",a="Вода бере початок біля печери, яку нещодавно заполонили ворожі наги. Їхня поява збіглася з отруєнням верхів'їв, звідки неприродна хвороба шириться серед місцевих тварин.",al={"хто отруїв воду","чому водоспад отруєно","нага кліффспрінг"}}},fp="32,252,16.544.0,16.429.1,52.195.0,31.184.0,38.197.0,39.184.0"}
P.entries["item:filled-containment-coffer"] = {n="Наповнена Скриня Зберігання",s="Наповнена Скриня Зберігання — зачароване вмістилище, у яке заклиначі-Відступники ловлять непередбачуваних магічних істот. Виявивши й послабивши породження розлому в Апотекаріумі за допомогою Заклинання Прояву, маги замикають аномалії в цих укріплених скриньках для безпечного вивчення.",h="Наповнена Скриня Зберігання — зачароване вмістилище, у яке заклиначі-Відступники ловлять непередбачуваних...",kw={"наповнена скриня зберігання","заклинання прояву","анастасія гартвелл","алджернон","аптекаріум","породження розлому","маг"},ang={["class:Mage"]="Учні-Відступники працюють із цими скриньками на практичному уроці захисної магії: вони вчаться виявляти прихованих магічних істот і замикати нестійку магічну енергію в матеріальні обереги.",["race:Undead"]="Безпека Апотекаріуму для Відступників понад усе, тож розслідувати й стримати будь-який загадковий магічний прорив — нагальна справа всього міста."},sec={{t="Пастка для незримого",b="Коли в крамниці Алджернона в Апотекаріумі з'явилися незрозумілі магічні збурення, Анастасія Гартвелл, магиня Відступників, доручила знавцям магії впіймати винних істот. Оскільки істоти з розлому — це жива магічна енергія, що блукає непомітно, звичайні клітки марні. Тож заклиначі виявляють їх Заклинанням Прояву, перемагають у бою й захлопують довкола них ці особливо підготовлені скриньки зберігання. Запечатані скриньки захищають того, хто їх несе, від нестійких магічних відбоїв і зберігають зразки цілими для магічного розтину."},{t="Магічна криміналістика",b="Живі істоти з мани в Андерсіті — серйозна загроза. Запечатаних у скриньки бранців доправляють до Анастасії Гартвелл і вчених міста. Найбільше магів-Відступників турбує одне: чи ці вторгнення — природні розриви в магічній тканині Азероту, чи перші розвідувальні удари продуманого магічного наступу на королівство."}},faq={{q="Що в Наповненій Скрині Зберігання?",a="У кожній скрині — упіймане породження розлому, невидима істота з чистої магічної енергії, що з'явилася в алхімічній крамниці Алджернона в Апотекаріумі.",al={"що в скрині","вміст скриньки","істота в скриньці"}},{q="Як наповнити скриню зберігання?",a="Маг має прочитати Заклинання Прояву, щоб приховані істоти стали видимими, здолати їх у бою й відкрити порожню скриню, щоб піймати залишки енергії, доки ті не розвіялися.",al={"як наповнити скриню","як піймати розривну істоту","наповнення скриньки"}},{q="Кому в Андерсіті потрібні ці наповнені скрині?",a="Анастасія Гартвелл, відома наставниця магів у Магічному Кварталі Андерсіті, просить ці запечатані скрині, щоб розслідувати збурення, яке загрожує місту.",al={"хто бере скрині","видавець завдання на скриньку","скриня анастасії гартвелл"}},{q="Чому Відступники вивчають цих істот?",a="Ученим Андерсіті треба з'ясувати, чи аномалія — випадковий розрив у місцевому потоці магії, чи навмисний злагоджений напад ворожої магічної сили.",al={"чому вивчати розривних істот","причина андерсіту"}}},fp="25,294,19.619.0,16.414.0,43.164.0,35.186.0,44.166.0,46.173.0"}
P.entries["item:filled-crystal-phial"] = {n="Наповнена Кришталева Фіала",s="Наповнена Кришталева Фіала містить священну воду з місячного колодязя одразу на північ від Алдрассила в Тінедолі. Зібрана за настановою Тенарона Стормґріпа, ця вода знайомить новачка зі священною й мінливою силою, що струменить Тельдрассилом.",h="Наповнена Кришталева Фіала містить священну воду з місячного колодязя одразу на північ від Алдрассила в...",kw={"наповнена кришталева фіала","місячний колодязь","тенарон стормґріп","тінедол","алдрассил","колодязь вічності","гора гіджал"},ang={["class:Druid"]="Друїди глибоко шанують воду місячних колодязів і її оживлювальними силами доглядають споганену рослинність і підтримують великі дерева.",["race:NightElf"]="Кожен молодий калдорей, що починає навчання під Алдрассилом, наповнює цю фіалу, згадуючи жертву Гори Гіджал і свій священний обов'язок берегти природу."},sec={{t="Води місячного колодязя",b="Щоб підготувати молодих нічних ельфів до виходу в ширший світ, Тенарон Стормґріп посилає їх набрати води з місячного колодязя, що ховається в Тінедолі. У фіалі не проста джерельна вода: Місячний Колодязь наснажений залишковими силами, що сягають прадавнього Колодязя Вічності. Вартові шанують ці місця як благословенні святині Елуни, а друїди спрямовують їхні відновлювальні властивості на догляд за природою, та давнє таємне чаклунство лишається суворо забороненим. Набрати цієї води — перший крок до розуміння жертв Гори Гіджал і хисткої рівноваги, потрібної, щоб плекати Тельдрассил."}},faq={{q="Що в Наповненій Кришталевій Фіалі?",a="У фіалі — вода з місячного колодязя на північ від Алдрассила в Тінедолі. Ця вода несе рештки прадавнього Колодязя Вічності, благословенна світлом Елуни й плекана друїдами.",al={"яка вода у фіалі","вміст фіали","що в кристалевій фіалі"}},{q="Хто просить наповнити фіалу?",a="Тенарон Стормґріп, що перебуває на гілках Алдрассила, посилає молодих шукачів пригод набрати воду — це частина їхнього обряду посвяти й уроку історії.",al={"хто хоче фіалу","хто дає завдання кристалевої фіали","завдання тенарона стормґріпа"}},{q="Навіщо Тенаронові Стормґріпу ця вода?",a="Тенарон використовує це доручення як перший урок історії нічних ельфів після Третьої війни: розповідає молодим шукачам пригод про жертву Нордрассила, силу місячних колодязів і невпинну опіку над Тельдрассилом.",al={"навіщо наповнювати кристалеву фіалу","призначення корони землі"}},{q="Чи небезпечні ці води?",a="Води несуть могутню магію, що сягає коренями прадавнього Колодязя Вічності. Друїди й жриці безпечно користуються ними для благословень і зцілення, але легковажні магічні маніпуляції з такими водами в давнину спричинили катастрофу й досі суворо заборонені.",al={"чи місячний колодязь небезпечний","чи вода магічна"}}},fp="20,265,22.622.0,40.195.0,31.165.0,43.227.0,25.253.0"}
P.entries["item:filled-cursed-ooze-jar"] = {n="Глек, Наповнений Проклятою Слизотою",s="Глек, Наповнений Проклятою Слизотою, містить отруйні рештки проклятого слизуна, зібрані в зіпсованих лісах Сквернолісся. Його збирають для Ларіса Ґірдавдла — гнома-вченого в Айронфорджі, що прагне розкрити первісне походження слизунів Азероту.",h="Глек, Наповнений Проклятою Слизотою, містить отруйні рештки проклятого слизуна, зібрані в зіпсованих лісах...",kw={"глек, наповнений проклятою слизотою","проклятий слизун","ларіс ґірдавдл","сквернолісся","слиз","ліга дослідників","гномреґан"},ang={["faction:Alliance"]="Натурфілософи Альянсу в Айронфорджі пильно стежать за діями Відступників і зауважують, що Королівське Аптекарське Товариство теж виявляє зловісний інтерес до збору зразків слизу по всьому Азероту.",["race:Gnome"]="Одержимість Ларіса Ґірдавдла дослідженням слизу — глибоко особиста: він прагне принести честь гномам, що втратили домівку, й довести господарям-дворфам в Айронфорджі цінність їхнього розуму."},sec={{t="Цікавий зразок",b="Більшість шукачів пригод сахаються мерзенних калюж і їдких слизунів, що повзають Калімдором, але гном-дослідник Ларіс Ґірдавдл бачить у них біологічну загадку. Помітивши, що слизуни трапляються в найрізноманітніших місцях, і побачивши, як аптекарі Відступників старанно їх збирають, Ґірдавдл висунув суперечливу теорію: слиз може бути первісною виділиною, пов'язаною безпосередньо зі створенням Азероту. Щоб добути зразок, треба пройти зараженими лісами Сквернолісся, здолати проклятого слизуна й зачерпнути їдку речовину в порожній глек, доки та повністю не розчинилася."},{t="Наукові амбіції",b="Для Ґірдавдла ці смердючі зразки мають подвійну мету. Окрім пошуку природничих знань, він сподівається, що велике відкриття зміцнить його репутацію в Лізі Дослідників, якою керують дворфи. Після нищівного падіння Гномреґану чимало гномів-біженців в Айронфорджі відчувають сильний тиск: їм треба довести свою цінність господарям-дворфам, і Ґірдавдл вірить, що розкриття давніх таємниць слизу покаже всім: прийняти гномів не було помилкою."}},faq={{q="Звідки цей глек?",a="Його отримують, застосувавши Порожній Слоїк для Проклятого Слизу до решток переможеної Проклятої Слизоти в зіпсованих землях Сквернолісся.",al={"де взяти проклятий слиз","як отримати глек з проклятою слизотою","місце глека зі слизом"}},{q="Кому потрібні ці зразки слизу?",a="Ларіс Ґірдавдл, гном-дослідник із Зали Дослідників в Айронфорджі, просить їх, щоб просунути свої природознавчі дослідження.",al={"кому потрібні глеки зі слизом","завдання ларіса ґірдавдла","хто бере глек зі слизом"}},{q="Чому Ларіс Ґірдавдл вивчає слизи?",a="Він помітив, що слизами дуже цікавляться і природа, і Королівське Аптекарське Товариство. Ларіс припускає, що слизи можуть бути прадавніми виділеннями, пов'язаними з самим зародженням і розвитком життя на Азероті, але, щоб перевірити свої теорії, йому потрібні справжні зразки.",al={"чому вивчати слизи","теорія слизу ґірдавдла","чому слиз"}},{q="Чому гномові не байдужа Ліга Дослідників?",a="Після падіння Гномреґана гноми-біженці знайшли прихисток у дворфів в Айронфорджі. Ґірдавдл сподівається, що велике наукове відкриття в Лізі Дослідників доведе господарям, що прихистити гномів було правильним рішенням.",al={"чому ліга дослідників","гноми в айронфорджі"}}},fp="22,262,18.568.0,17.476.0,30.124.0,29.138.0,39.263.0,50.255.0"}
P.entries["item:filled-dreadmist-peak-sampler"] = {n="Наповнений Пробовідбірник Вершини Моторошного Туману",s="Наповнений пробовідбірник Піка Жахливої Імли — флакон із зіпсованою водою з високогірних озерець на вершині Піка Жахливої Імли на півночі Пусток. Його набирають молоді друїди Орди, і він дає Колу Кенарія відчутний доказ, потрібний для вивчення мерзенної недуги, що отруює звірів краю.",h="Наповнений пробовідбірник Піка Жахливої Імли — флакон із зіпсованою водою з високогірних озерець на вершині...",kw={"наповнений пробовідбірник","пік жахливої імли","палаючий клинок","тонга рунтотем","коло кенарія","друїди"},ang={["class:Druid"]="Здобути цей зразок — важливий обряд посвяти для друїдів Орди: він учить, як природні водні шляхи поширюють порчу, і готує до опанування цілющої магії.",["faction:Horde"]="Розслідування на Піку Жахливої Імли викриває загрозу культу Палаючого Клинка, що підступає в самому серці земель Орди в Пустках."},sec={{t="Отруєне джерело",b="Високі скелі Піка Жахливої Імли приховують природні озерця, чиї тумани здавна впливають на погоду й дощі на півночі Пусток. Коли демонопоклонники з Палаючого Клинка облаштували своє збіговисько на вершині, вода швидко зіпсувалася. Підозрюючи, що демонічні обряди отруїли випари, які живлять довколишню савану, друїди Кола Кенарія посилають послушників набрати зразок особливим пробовідбірником. Мерзенна рідина всередині підтверджує їхні найгірші побоювання: від неї тхне порчею, досить сильною, щоб занедужали стада, що блукають унизу."},{t="Зцілення савани",b="Brought to Tonga Runetotem at the Crossroads, the vile sample serves as the focal point for formulating an antidote. While the Burning Blade are suspected of tainting the water, analyzing its properties enables the Cenarion Circle to understand the poison's nature. By isolating the taint within this vial, druids develop the herbal remedies required to purge the affliction from dying gazelles and master their own natural power over poison."}},faq={{q="Де взяли цю пробу води?",a="Пробу набирають з озерця на самій вершині Піка Жахливої Імли — скелястої гори на північний захід від Перехрестя в Пустках.",al={"звідки взяти пробу","місце пробовідбірника","де наповнити пробовідбірник"}},{q="Чому вода на Піку Жахливої Імли отруєна?",a="The Burning Blade cult has taken over the heights of Dreadmist Peak to practice demon worship. Dendrite Starblaze suspects that the cult has tainted the summit's natural waters.",al={"чому вода отруєна","хто отруїв пік жахливої імли","вода палаючого клинка"}},{q="Кому потрібен наповнений пробовідбірник?",a="Його треба доставити на Перехрестя в Пустках, де кенарійський друїд Тонга Рунтотем розслідує раптову хворобу, що косить тварин краю.",al={"кому віднести пробовідбірник","пробовідбірник тонґи рунетотем","здати воду"}},{q="Як ця отруєна вода впливає на Пустки?",a="Високогірні озерця на Піку Жахливої Імли природно впливають на місцеву погоду й тумани. Коли вони отруєні, випари осідають над саваною на північ від головного шляху й спричиняють масову хворобу серед місцевих газелей.",al={"що робить вода","хворі газелі пустищ","дія жахливої імли"}},{q="Для чого пробовідбірник, коли його наповнено?",a="Тонга Рунтотем досліджує мерзенну рідину, щоб визначити точні властивості демонічної скверни, і з цим знанням готує цілющу мазь, якою друїди лікують хворих газелей.",al={"що тонґа з нею робить","ліки від отрути","дослідження отрути"}}},fp="29,312,16.536.0,18.442.1,36.157.0,43.177.0,29.169.0,48.225.0,51.192.0"}
P.entries["item:filled-etched-phial"] = {n="Наповнена Гравірована Фіала",s="Наповнена Гравірована Фіала — вишукана посудина дріад, наповнена освяченою водою, набраною просто з місячного колодязя нічних ельфів в Ашенвалі. Цю воду, по яку звертаються таурени з Тандер Блафа, сповнює рідкісна духовна сила, здатна загасити вічне полум'я, що оберігає священну реліквію кентаврів.",h="Наповнена Гравірована Фіала — вишукана посудина дріад, наповнена освяченою водою, набраною просто з місячного...",kw={"наповнена гравірована фіала","місячний колодязь","дріади","ашенваль","кентаври","кенарій","занген стоунгуф","рау кліффраннер"},ang={["race:NightElf"]="Нічні ельфи вважають крадіжку фіали дріад і черпання води з місячних колодязів агентами Орди непрощенним вторгненням до найсвятіших прихистків Ашенвалю.",["race:Tauren"]="Для тауренів здобути цю воду — розважливий удар по кентаврах Ґалак: спільну магію природи дітей Кенарія обернено проти їхніх давніх племінних ворогів."},sec={{t="Вода місячного колодязя й ремесло дріад",b="Щоб здобути цю фіалу, доведеться пробратися глибоко на землі нічних ельфів в Ашенвалі. Спершу порожню посудину треба забрати в дріад довкола Притулку Рейнвуд — їхні тендітні посудини створені для чистих цілющих настоїв. Потім фіалу наповнюють біля священного місячного колодязя на західному березі Річки Фалфаррен, і вона вбирає воду, сповнену небесної сили природи. Для нічних ельфів брати цю воду без дозволу — відверте блюзнірство, але таурени вважають це нагальною потребою, щоб упоратися із загрозою далі на півдні."},{t="Ключ до чаклунства кентаврів",b="Занген Стоунгуф і Рау Кліффраннер шукали саме цю воду через приховані міфічні узи, що пов'язують дріад і кентаврів. Обидва роди ведуть свій родовід від Кенарія, тож їхні магічні традиції глибоко переплетені й відгукуються одна одній. У Тисячі Голок клан Ґалак стереже прадавню реліквію, захищену незгасним вічним вогнем, що палає ще від часів появи народу кентаврів. Завдяки спільному первісному корінню освячена вода місячного колодязя у фіалі дріад — єдине, що здатне пробити й загасити це захисне полум'я."}},faq={{q="Що в Наповненій Гравірованій Фіалі?",a="У ній священна вода, набрана просто з місячного колодязя нічних ельфів в Ашенвалі, біля Річки Фалфаррен. Вода — в оздобленій скляній фіалі, яку забрали в дріад біля Притулку Рейнвуд.",al={"яка вода у фіалі","чим наповнена гравірована фіала"}},{q="Навіщо тауренам вода з місячного колодязя?",a="Рау Кліффраннерові потрібна освячена вода, щоб пробитися крізь вічне захисне полум'я, яке підтримують кентаври Ґалак у Тисячі Голок. Дріади й кентаври мають спільних предків через Кенарія, тож вода з місячного колодязя здатна розвіяти прадавній оберіг, що стереже їхню реліквію.",al={"чому таурени потребують місячний колодязь","навіщо раю вода колодязя"}},{q="Звідки береться порожня фіала?",a="Цю посудину носять Реготливі Сестри — дріади, що блукають лісами довкола Притулку Рейнвуд у центрі Ашенвалю.",al={"де знайти гравіровану фіалу","як отримати порожню фіалу"}},{q="Кому доставити Наповнену Гравіровану Фіалу?",a="Набравши води, фіалу спершу несуть Зангенові Стоунгуфу на Узвишшя Мисливців у Тандер Блафі, а той посилає вас віднести її Рау Кліффраннеру на Заставу Вільного Вітру в Тисячі Голок.",al={"кому віддати фіалу","здати фіалу"}}},fp="19,303,31.568.0,24.563.1,39.197.0,38.279.0,37.126.0,46.200.0"}
P.entries["item:filled-jade-phial"] = {n="Наповнена Нефритова Фіала",s="Наповнена Нефритова Фіала містить священну воду з місячного колодязя біля Села Зоряного Вітерця. Принесена назад до Доланаара, вона є частиною безперервного обряду поповнення центральних вод столиці, під час якого молоді нічні ельфи пізнають історію свого народу.",h="Наповнена Нефритова Фіала містить священну воду з місячного колодязя біля Села Зоряного Вітерця.",kw={"наповнена нефритова фіала","місячний колодязь","село зоряного вітерця","корітрас мунрейдж","доланаар","нордрассил","малфуріон стормрейдж"},ang={["class:Druid"]="Догляд за місячними колодязями прямо єднає друїдів із відновлювальною магією, що живить Дарнасус, і з безперервними зусиллями Кола Кенарія плекати молоде Світове Дерево.",["race:NightElf"]="Принесена вода зміцнює священний обов'язок молодого калдорея перед Тельдрассилом і передає важливу історію про втрату безсмертя після Гори Гіджал."},sec={{t="Води Зоряного Вітерця",b="Друїди Дарнасуса покладаються на священну воду місячних колодязів з усього віття Тельдрассила, щоб поповнювати свої центральні колодязі. Особливо виготовлені посудини, як-от нефритова фіала, яку Корітрас Мунрейдж у Доланаарі довіряє молодим шукачам пригод, настроєні безпечно вміщувати ці чисті води. Вирушивши на схід до місячного колодязя за Селом Зоряного Вітерця, посвячені набирають життєдайну воду й водночас доводять відданість догляду за Світовим Деревом."},{t="Урок історії",b="Повернути Наповнену Нефритову Фіалу до Доланаара — більше ніж просте доручення: кожна поповнена посудина відкриває новий розділ усної історії калдореїв. Прийнявши повну фіалу, Корітрас Мунрейдж розповідає про відчайдушну добу після Третьої війни — спалення Нордрассила, втрату безсмертя нічних ельфів, звільнення Зрадника й раптове зникнення Шан'до Малфуріона Стормрейджа у Смарагдовому Сні."}},faq={{q="Де наповнити Нефритову Фіалу?",a="Нефритову Фіалу наповнюють священною водою з місячного колодязя просто за Селом Зоряного Вітерця, на схід від Доланаара на Тельдрассилі.",al={"де наповнити нефритову фіалу","як отримати наповнену фіалу","колодязь зоряного вітерця"}},{q="Кому потрібна Наповнена Нефритова Фіала?",a="Корітрас Мунрейдж, старійшина нічних ельфів із поселення Доланаар, доручає мандрівникам принести воду в межах обрядових доручень «Корони Землі».",al={"кому потрібна фіала","предмет завдання корітраса"}},{q="Навіщо воду з місячних колодязів набирають у такі фіали?",a="Друїди Дарнасуса мають час від часу поповнювати свої головні місячні колодязі. Особливі посудини, як-от Нефритова Фіала, дають змогу безпечно переносити чисту воду з віддалених колодязів по всьому Тельдрассилу.",al={"навіщо збирати воду колодязів","для чого нефритова фіала"}},{q="Яку історію розповідає Корітрас, отримавши фіалу?",a="Отримавши наповнену фіалу, Корітрас Мунрейдж розповідає про похмурі наслідки Битви за Гору Гіджал: про втрату безсмертя нічними ельфами, звільнення Іллідана Стормрейджа й загадковий сон шан'до Малфуріона Стормрейджа.",al={"що розповідає корітрас","лор корони землі"}}},fp="17,256,20.463.0,19.435.0,31.151.0,35.166.0,54.214.0,55.249.0"}
P.entries["item:filled-pure-sample-jar"] = {n="Глек, Наповнений Чистим Зразком",s="Глек, Наповнений Чистим Зразком, містить незіпсований зразок первісного слизу, зібраний у віддаленій дикій глушині. Для гнома-вченого Ларіса Ґірдавдла в Айронфорджі це ключові вихідні дані: він вивчає, як зіпсованість довкілля змінює живу матерію.",h="Глек, Наповнений Чистим Зразком, містить незіпсований зразок первісного слизу, зібраний у віддаленій дикій...",kw={"глек, наповнений чистим зразком","ларіс ґірдавдл","кратер ун'ґоро","слиз","сквернолісся","зразок"},ang={["faction:Alliance"]="Дослідники Альянсу, що вирушають у суворі краї на кшталт Кратера Ун'Ґоро, привозять важливі природничі дані вченим, які безпечно працюють в Айронфорджі.",["race:Gnome"]="Гномські вчені дивляться на польову біологію крізь сувору призму досліду: порівняння забруднених слизунів Сквернолісся з чистими зразками з Ун'Ґоро — взірець звичайного наукового методу."},sec={{t="Пошуки незіпсованого слизу",b="Вивчаючи слизунів по всьому Азероту, гном-дослідник Ларіс Ґірдавдл виявив тривожне явище: ці безформні істоти вбирають і віддзеркалюють магічну й природну зіпсованість свого довкілля. Описавши заражених слизунів Сквернолісся, Ларіс дійшов висновку, що для розгадки природи гнилі потрібна контрольна група. У Глеку, Наповненому Чистим Зразком, — слиз, зібраний у незайманій, незараженій глушині, як-от у первісній природі Кратера Ун'Ґоро. Він дає вченим незмінений зразок для порівняння з хворими й зіпсованими різновидами."},{t="Первісна природа",b="Слизуни — надзвичайно мінливі організми, тож справді «чисті» зразки неможливо зібрати поблизу сучасної цивілізації, демонічних пошестей чи некромантських наслідків. Клейкі слизуни дикої улоговини Кратера Ун'Ґоро лишаються відносно відрізаними від зовнішньої скверни, тож стають ідеальним науковим еталоном для допитливих умів Айронфорджа."}},faq={{q="Кому потрібні ці чисті зразки?",a="Ларіс Ґірдавдл, гном-дослідник з Айронфорджа, шукає ці банки з чистими зразками, щоб продовжити вивчення слизів Азероту.",al={"завдання ларіса ґірдавдла","кому потрібні глеки з чистим зразком","хто хоче глеки"}},{q="Чому Ларісові потрібен чистий слиз, а не зіпсований?",a="Ларіс з'ясував, що слизи швидко пристосовуються й убирають властивості довкілля — як-от демонічну гниль Сквернолісся. Щоб зрозуміти, як далеко сягає це зіпсуття й як воно діє, йому потрібні незіпсовані зразки для наукового порівняння.",al={"чому чистий слиз","чому чистий зразок","мета вивчення слизу"}},{q="Де зібрати чисті зразки слизу?",a="Чисті зразки збирають із клейких слизів, що живуть у первісній глушині Кратера Ун'Ґоро, де рослини й тварини лишаються відрізаними від зовнішньої скверни.",al={"де знайти чистий слиз","місце глека з чистим зразком","де наповнити глеки"}},{q="Що стається, коли зразки доставлено в Айронфордж?",a="Ларіс проводить на зразках лабораторні досліди щодо пристосування й стійкості до довкілля та винагороджує шукачів пригод, які наважилися принести їх із небезпечних нетрів.",al={"нагорода від ларіса","що ларіс з ними робить"}}},fp="22,263,30.573.0,18.354.0,29.145.0,54.263.0,41.172.0,57.157.0"}
P.entries["item:filled-red-waterskin"] = {n="Наповнений Червоний Бурдюк",s="Наповнений червоний бурдюк містить чисту джерельну воду із сільської криниці в Таррен Міллі. Набрати цю чисту воду серед сплюндрованих руїн, які тримають Відступники, — важливе випробування для молодих шаманів, що прагнуть єднання з духами води.",h="Наповнений червоний бурдюк містить чисту джерельну воду із сільської криниці в Таррен Міллі.",kw={"наповнений червоний бурдюк","таррен мілл","криниця","брайн","шаман","поклик води"},ang={["class:Shaman"]="Ця вода перевіряє, чи здатен шаман знайти й ушанувати життєдайну рівновагу навіть у найзанедбаніших, найскорботніших куточках світу.",["faction:Horde"]="Відвідини Таррен Мілла приводять молодих звитяжців із Калімдору в саме серце боротьби Відступників проти сил Альянсу у Східних Королівствах."},sec={{t="Маяк у сплюндрованих землях",b="Навчаючи шаманів шляхів води, відлюдниця Брайн із Пусток посилає послушників у далеку мандрівку до Таррен Мілла в Передгір'ї Гілсбреда. Посеред тліну й мерців центральна криниця містечка дивом дає чисту, незатьмарену джерельну воду. Брайн бачить у цьому святому залишку в несвятій землі символ незламного духу й порівнює незіпсоване джерело з непохитною рішучістю Вождя Тралла, що вистояла попри тяжкі випробування. Набравши цей зразок, послушник доводить свою шану до чистоти води, хай яке вороже довкілля."}},faq={{q="Що в Наповненому Червоному Бурдюку?",a="У ньому чиста, незіпсована джерельна вода, набрана просто з громадського колодязя в центрі Таррен Мілла.",al={"яка вода всередині","вода таррен мілла","вміст червоного бурдюка"}},{q="Навіщо Брайн вода з Таррен Мілла?",a="Брайн вважає свіже джерело містечка дивовижним осередком чистоти, що вцілів серед тліну Відступників. Цей священний зразок потрібен їй як складник для сапти, яку п'ють шамани під час випробувань води.",al={"навіщо брайн вода таррен мілла","чому таррен мілл","призначення червоного бурдюка"}},{q="Як колодязь лишається чистим у місті нежиті?",a="Джерело живиться глибоко під землею, і чуми довкола його не торкнулися. Брайн зауважує, що Відступники в Таррен Міллі, може, навіть не помічають і не цінують чистоти цієї святині серед них.",al={"чому колодязь не зіпсований","чи отруєний колодязь таррен мілла","святий колодязь таррен мілла"}},{q="Як із цим завданням пов'язаний Тралл?",a="Брайн порівнює чистий колодязь у зруйнованому місті з Траллом, який пережив страшні страждання й неволю, але вийшов із них сильним і незіпсованим, щоб вести орків крізь темні часи.",al={"порівняння з траллом","чому згадують тралла"}}},fp="20,255,26.577.0,40.108.0,43.206.0,47.218.0,37.191.0"}
P.entries["item:filled-tainted-ooze-jar"] = {n="Глек, Наповнений Зіпсованою Слизотою",s="Глек, Наповнений Зіпсованою Слизотою, містить в'язкий зіпсований слиз, зачерпнутий просто з решток слизунів, що блукають зараженими лісами Сквернолісся. Ці зразки, надійно закорковані в особливих посудинах, везуть до Айронфорджа, щоб підкріпити сміливі теорії про походження життя в Азероті.",h="Глек, Наповнений Зіпсованою Слизотою, містить в'язкий зіпсований слиз, зачерпнутий просто з решток слизунів...",kw={"глек, наповнений зіпсованою слизотою","ларіс ґірдавдл","сквернолісся","слиз","королівське аптекарське товариство","ліга дослідників"},ang={["faction:Alliance"]="Розвідники Альянсу пильно стежать за Королівським Аптекарським Товариством Відступників: з'ясувати, навіщо Андерсіті збирає слиз на різних континентах, — одне з першочергових завдань розвідки.",["race:Gnome"]="Для гномів-біженців в Айронфорджі проривні наукові внески до Ліги Дослідників — спосіб довести свою цінність і віддячити дворфам за гостинність після трагедії Гномреґану."},sec={{t="Слиз зіпсованого лісу",b="Зіпсовані слизуни, що блукають північним Калімдором, несуть у собі глибоку, в'їдливу скверну Сквернолісся. Щоб їх зібрати, потрібні надійні банки від гномських дослідників. Більшість мандрівників узагалі обходять цих отруйних істот, але такі зразки — рідкісний матеріал для натурфілософії й біологічних досліджень далеко від уражених лісів."},{t="Велика теорія Ґірдавдла",b="Зразки збирають для Ларіса Ґірдавдла — честолюбного гнома-вченого з Ліги Дослідників в Айронфорджі. Ґірдавдла захоплює те, що слиз трапляється всюди, і він помітив, що Королівське Аптекарське Товариство Відступників теж жваво ним цікавиться. Наперекір поширеному науковому скепсису він припускає, що слиз і слизуни можуть бути первісними виділинами, пов'язаними із самим створенням Азероту. Збираючи ці зразки, він прагне утвердити своє становище серед дворфійських учених після трагічного падіння Гномреґану."}},faq={{q="Що в Глеку, Наповненому Зіпсованою Слизотою?",a="У ньому свіжий зразок, узятий з решток переможеного Оскверненого Слизу, що водиться в Скверноліссі, і запечатаний у гномській банці для зразків.",al={"що в глеку","вміст глека зіпсованого слизу","що таке зіпсований слиз"}},{q="Кому потрібні ці зразки слизу?",a="Ларіс Ґірдавдл, гном-дослідник, що працює з Лігою Дослідників у Залі Дослідників в Айронфорджі, просить їх, щоб просунути свої природознавчі дослідження.",al={"хто бере слиз","завдання ларіса ґірдавдла","кому потрібен зіпсований слиз"}},{q="Чому Ларіс Ґірдавдл вивчає слизи?",a="Ґірдавдл помітив, що Королівське Аптекарське Товариство збирає зразки слизу, і вирішив першим розгадати їхню природу. Він має незвичну теорію, що слизи — первісні виділення, пов'язані зі створенням Азероту, і сподівається зміцнити свою наукову славу в Айронфорджі.",al={"чому вивчати слизи","теорія слизу ґірдавдла","чому гному слиз"}},{q="Де збирають ці зразки?",a="Їх збирають у Скверноліссі: треба здолати Осквернений Слиз і застосувати до його решток порожню банку для зразків.",al={"де знайти зіпсований слиз","місце глека зіпсованого слизу","де наповнити глек"}}},fp="23,292,27.363.0,25.565.0,41.145.0,29.171.0,39.297.0,34.109.0"}
P.entries["item:filled-tourmaline-phial"] = {n="Наповнена Турмалінова Фіала",s="Наповнена Турмалінова Фіала містить зачаровану воду з місячного колодязя на межі Озерець Арлітрієну в південному Тельдрассилі. Зібрана на прохання Корітраса Мунрейджа, вода є частиною зусиль стежити за здоров'ям і рівновагою зростаючого Світового Дерева.",h="Наповнена Турмалінова Фіала містить зачаровану воду з місячного колодязя на межі Озерець Арлітрієну в...",kw={"наповнена турмалінова фіала","озерця арлітрієну","місячний колодязь","корітрас мунрейдж","фандрал стаґгелм","вузлошкіри","тельдрассил"},ang={["class:Druid"]="Для друїдів несення фіали прямо торкається суперечливого спадку Архідруїда Фандрала Стаґгелма, який наполіг на посадженні Тельдрассила за незрозумілої відсутності Шан'до Стормрейджа.",["race:NightElf"]="Води місячних колодязів — неодмінна духовна жила калдореїв, тож скверна в навколишніх гаях Вузлошкірів — глибоко тривожне знамення для їхнього нового дому."},sec={{t="Води Арлітрієну",b="Турмалінова Фіала призначена саме для води з місячного колодязя на південний схід від дороги до Дарнасуса, на берегах Озерець Арлітрієну. Набирати воду з цієї святині стало небезпечно через раптову лють фурболгів Вузлошкірів — мирних сусідів, що стрімко скотилися в несамовите безумство. Корітрас Мунрейдж доручає мандрівникам пройти ворожими гаями й здобути цю воду, щоб розпізнати скверну, яка дедалі глибше збурює землю."},{t="Коріння Тельдрассила",b="Повернення фіали до Доланаара спонукає Корітраса Мунрейджа замислитися над постанням віття вгорі. Після зникнення Шан'до Малфуріона Стормрейджа у Смарагдовому Сні Архідруїд Фандрал Стаґгелм згуртував Коло Древніх за морем, на Темному Узбережжі, щоб посадити Тельдрассил у надії повернути втрачене безсмертя. Вода в самоцвітній фіалі відбиває стан того священного досліду — задуму, нині затьмареного незрозумілою хворобою, що розповзається на звірів і фурболгів."}},faq={{q="Для чого потрібна Наповнена Турмалінова Фіала?",a="Це зачарована посудина з водою місячного колодязя, яку просить Корітрас Мунрейдж у Доланаарі. Він збирає воду з місячних колодязів по всьому Тельдрассилу, щоб вивчати поширення скверни й розповідати новоприбулим захисникам історію Світового Дерева.",al={"використання турмалінової фіали","призначення турмалінової фіали","навіщо наповнювати фіалу"}},{q="Де місячний колодязь для Турмалінової Фіали?",a="Колодязь — на південний схід від головної брами Дарнасуса, на березі Озерець Арлітрієну на південному заході Тельдрассила. За ці місця запекло б'ються розлючені фурболги-Вузлошкіри.",al={"де наповнити турмалінову фіалу","басейни арлітрієна колодязь","місце колодязя арлітрієна"}},{q="Чому фурболги біля місячного колодязя нападають?",a="Фурболги-Вузлошкіри, колись мирний ведмежий народ, що жив поруч із нічними ельфами, стали жертвою підступного зіпсуття, яке вражає Тельдрассил. Їхнє раптове падіння в безтямну жорстокість — одна з кількох ознак недуги молодого Світового Дерева.",al={"чому ґнарлпайни шалені","ворожість фурболгів арлітрієна","скажені ґнарлпайни"}},{q="Хто такий Корітрас Мунрейдж?",a="Корітрас Мунрейдж — учений і доглядач із нічних ельфів у Доланаарі. Він веде молодих шукачів пригод крізь обряд, відомий як «Корона Землі», і розповідає їм про історію нічних ельфів, насадження Тельдрассила й зникнення Малфуріона Стормрейджа.",al={"роль корітраса","корітрас доланаар"}}},fp="23,279,20.507.0,23.526.1,45.246.0,55.206.0,49.247.0,26.278.0"}
P.entries["item:filled-vessel"] = {n="Наповнена Посудина",s="Наповнена Посудина містить очищену воду з різних священних місячних колодязів Тельдрассила. Довірена посланцям Корітрасом Мунрейджем у Доланаарі, вона призначена Архідруїдові Фандралу Стаґгелму в Дарнасусі на допомогу в його вивченні недуг Світового Дерева.",h="Наповнена Посудина містить очищену воду з різних священних місячних колодязів Тельдрассила.",kw={"наповнена посудина","місячні колодязі","корітрас мунрейдж","фандрал стаґгелм","дарнасус","ценаріонський анклав","тельдрассил"},ang={["class:Druid"]="Для посвячених Кола Кенарія доставка цієї посудини — перше офіційне доручення до Архідруїда Фандрала Стаґгелма, що на власні очі показує крихкість живого світу Тельдрассила.",["race:NightElf"]="Води місячних колодязів усередині — священні жили нового дому калдореїв, у яких магія Елуни змішується з непевним зростанням неблагословенного Світового Дерева."},sec={{t="Злиття священних вод",b="Тельдрассил посадили без благословення Великих Аспектів, Алекстрази й Ноздорму, і його величезне віття лишилося вразливим до несподіваної скверни, дивних звірів і знавіснілих племен фурболгів. Щоб стежити за молодим віттям і очищати його, нічноельфійських послушників посилають збирати зразки води з місячних колодязів по всьому вітті. Корітрас Мунрейдж зливає зібрані фіали в одну Наповнену Посудину й відсилає її далі, до столиці. Суміш слугує важливим зразком життєвої сили Тельдрассила для Архідруїда Фандрала Стаґгелма, який невтомно працює в Ценаріонському Анклаві, шукаючи ліки від глибинних вад Великого Дерева."}},faq={{q="Що в Наповненій Посудині?",a="У посудині — вода з кількох місячних колодязів по всьому Тельдрассилу, яку Корітрас Мунрейдж у Доланаарі злив в одну посудину.",al={"вміст наповненої посудини","яка це вода","що в посудині"}},{q="Кому потрібна Наповнена Посудина?",a="Наповнену Посудину приносять Архідруїдові Фандралу Стаґгелму, що мешкає на вершині Ценаріонського Анклаву в Дарнасусі.",al={"кому віддати наповнену посудину","куди посудина","здати наповнену посудину"}},{q="Навіщо Фандралу Стаґгелму ці проби води?",a="Тельдрассил не має звичного благословення Аспектів драконів, тож його гілки потерпають від дивної скверни, агресивних звірів і збожеволілих фурболгів. Стаґгелм вивчає змішані води, щоб з'ясувати вади дерева й знайти ліки від його недуг.",al={"навіщо стаґгелму вода","призначення води місячного колодязя стаґгелма","навіщо збирати воду місячного колодязя"}},{q="Хто підготував посудину?",a="Корітрас Мунрейдж, нічний ельф із Доланаара, зливає в посудину фіали, зібрані молодими шукачами пригод, перш ніж відправити її до Дарнасуса.",al={"хто підготував посудину","хто дає наповнену посудину","наповнена посудина корітраса"}}},fp="13,265,29.675.0,33.159.0,28.121.0,51.256.0,24.155.0"}
P.entries["item:final-clue-to-sanders-treasure"] = {n="Остання Підказка до Скарбу Сандерса",s="«Остання Підказка до Скарбу Сандерса» — записка в плямах віскі, запхана в старий глек на узбережжі Вестфолу. У ній — завершальні вказівки, які залишив покійний пірат капітан Сандерс: вони ведуть шукачів просто у відкрите море, до його захованої здобичі.",h="«Остання Підказка до Скарбу Сандерса» — записка в плямах віскі, запхана в старий глек на узбережжі Вестфолу.",kw={"скарб сандерса","капітан сандерс","остання підказка","морська скриня","вестфол","пірат"},ang={["class:Rogue"]="Іти за просякнутою віскі загадкою мертвого пірата у відкрите море — класична робота для шахрая, яка доводить: на берегах Вестфолу є пожива й окрім кишень Дефіасу."},sec={{t="Прощальні слова моряка",b="Від цього заплямованого пергаменту тхне міцним трунком, і він завершує заплутаний паперовий слід капітана Сандерса через увесь Вестфол. Покійний буканьєр, відомий загадковими вказівками, розкиданими по всьому узбережжю, сховав останню записку глибоко в старому глеку з-під віскі. Вказівки грубі, але прості: від місця, де лежить пляшка, іти просто на захід у морські хвилі, долаючи холодний прибій, аж до самотньої скелі серед моря, де чекає його окута залізом морська скриня."}},faq={{q="Що каже остання підказка?",a="Хоча чорнило розпливлося, а від записки тхне віскі, вона велить стати від глека з віскі обличчям на захід, спуститися просто у прибережну воду й плисти на захід у море, аж до маленького острівця, де сховано скриню зі скарбом.",al={"що написано в підказці","текст підказки","вказівки сандерса"}},{q="Де знайшли цю підказку?",a="Підказку запхали в старий глек з-під віскі біля західного берега Вестфолу — це третій крок у низці підказок, які розкидав капітан Сандерс.",al={"де знайти останню підказку","місце старого глечика","місце підказки"}},{q="Хто такий капітан Сандерс?",a="Капітан Сандерс — морський капітан і пірат, чиї пожитки й мапи скарбів винесло на берег Вестфолу. Сам Сандерс загинув, але залишив по всьому краю низку прихованих записок і позначок, що ведуть до його піратського скарбу.",al={"хто такий капітан сандерс","історія пірата сандерса","хто сховав скарб"}},{q="Куди зрештою веде ця підказка?",a="Записка велить вам плисти на захід від берега Вестфолу до самотнього острова посеред океану, де стоїть іржава морська скриня капітана Сандерса з закопаною здобиччю.",al={"де скриня","острів сандерса","місце острова"}}},fp="31,281,24.502.0,29.258.0,26.168.0,24.264.0,37.165.0"}
P.entries["item:fine-crab-chunks"] = {n="Вишукані Шматочки Краба",s="Вишукані Шматочки Краба — добірне м'ясо прибережних ракоподібних, що блукають пляжами Темного Узбережжя. Їх високо цінують за те, що з ними можна приготувати будь-що, тож місцеві мешканці узбережжя й голодні рибалки шукають їх для безлічі страв із морепродуктів.",h="Вишукані Шматочки Краба — добірне м'ясо прибережних ракоподібних, що блукають пляжами Темного Узбережжя.",kw={"вишукані шматочки краба","ґуббер бламп","краби","кулінарія","темне узбережжя","обердайн"},ang={["faction:Alliance"]="Постачаючи харчі мешканцям пристані Обердайна, ви допомагаєте втримати крихку заставу Альянсу серед похмурих небезпек Темного Узбережжя.",["profession:Cooking"]="Кожен початківець-кухар на узбережжі оцінить енциклопедичну пристрасть Ґуббера Блампа до крабів — від супів і салатів до перцевих натирань і місцевих делікатесів на кшталт краба-сюрпризу по-айронфордзьки."},sec={{t="Дари моря",b="Імлисті, порізані скелями береги Темного Узбережжя кишать прудкими ракоподібними — передусім рифовими повзунами й оброслими припливними повзунами. Багато мандрівників вважають цих закутих у панцири прибережних нишпорок шкідниками чи небезпекою біля води, та заповзятливі гурмани ставлять їхнє м'ясо серед найкращих дарів узбережжя. Добірні шматки цих істот дають ніжне, соковите м'ясо, яке пасує майже до будь-якого способу приготування — від варіння й смаження на грилі до фритюру та ситних рагу."}},faq={{q="З яких істот добувають Вишукані Шматочки Краба?",a="Їх добувають із рифових повзунів і обліплених припливних повзунів, що снують скелястими пляжами й прибережними мілинами Темного Узбережжя.",al={"звідки падають шматочки краба","які краби дропають шматочки","джерело крабового м'яса"}},{q="Кому на Темному Узбережжі потрібні Вишукані Шматочки Краба?",a="Ґуббер Бламп, завзятий рибалка з пристані Обердайна, шукає ці добірні шматки. Великий поціновувач морепродуктів, він цінує їх за цілий набір крабових страв домашнього приготування.",al={"кому потрібні шматочки краба","хто бере шматочки краба","краб ґаббера бламп"}},{q="Чи можна приготувати з них справжні страви?",a="Ці сирі шматки — передусім припаси для Ґуббера Блампа, а не складник кулінарного рецепта. Але, за місцевою кухарською традицією, крабове м'ясо напрочуд універсальне: його можна запікати, смажити на грилі, варити, тушкувати, обсмажувати й додавати в салати чи рагу.",al={"чи можна їх приготувати","що приготувати з шматочків краба","рецепти з краба"}}},fp="16,281,16.516.0,38.136.0,40.202.0,40.296.0"}
P.entries["item:fine-moonstalker-pelt"] = {n="Вишукана Шкура Місячного Хижака",s="Вишукана Шкура Місячного Хижака — густе бездоганне хутро найдосвідченіших місячних скрадачів, що полюють на півдні Темного Узбережжя. Терентіс з Обердайна тче з цих цінних шкур зачарований плащ, який дає змогу шукачам непомітно прослизнути повз ворожих звірів лісу.",h="Вишукана Шкура Місячного Хижака — густе бездоганне хутро найдосвідченіших місячних скрадачів, що полюють на...",kw={"шкура місячного хижака","місячні скрадачі","терентіс","волкор","річка дикого закруту","темне узбережжя"},ang={["class:Hunter"]="Вистежуючи вожаків і матріархів біля Річки Дикого Закруту, мисливець перевіряє свою майстерність на одних із найлютіших хижаків прибережного Калімдору.",["race:NightElf"]="Нічні ельфи шанують священну лютість місячних скрадачів і беруть їхні шкури лише з крайньої потреби — щоб допомогти родичам у біді, як-от Волкорові."},sec={{t="Шкури ватажків зграї",b="Звичайні місячні скрадачі нишпорять усіма оповитими імлою лісами Темного Узбережжя, але лише старі вожаки й матріархи мають хутро достатньо густе й здорове, щоб із нього вийшла вишукана шкура. Ці могутні дикі коти займають угіддя вздовж Річки Дикого Закруту й далі на південь, до меж Ашенвалю, де полюють зі смертоносним терпінням."},{t="Плащ-омана",b="Здобуття цих шкур — не просто полювання за трофеєм. Терентіс просить п'ять цілих шкур, щоб пошити зачароване вбрання для мандрівників, які шукають зниклого нічного ельфа Волкора. Сплетені й скріплені магією природи, шкури стають плащем-невидимкою, що огортає власника ілюзією й приглушує його присутність для звірів Темного Узбережжя — доки він сам не нападає."}},faq={{q="З яких істот добувають Вишукану Шкуру Місячного Хижака?",a="Такі шкури дають лише дорослі ватажки зграй місячних хижаків — самці-батьки й матріархині. Молодші чи звичайні місячні хижаки не мають шкури потрібної якості.",al={"що дропає вишукану шкуру місячного хижака","де взяти шкуру місячного хижака","які коти мають шкури"}},{q="Де знайти дорослих місячних хижаків?",a="Ці грізні дикі коти живуть на півдні Темного Узбережжя — особливо біля берегів Річки Дикого Закруту й далі на південь, уздовж лісової дороги до Ашенвалю.",al={"де дорослі самці й самиці","місце дорослого місячного хижака","місце матріарха місячних хижаків"}},{q="Навіщо Терентісу ці шкури?",a="Терентіс шиє з п'яти шкур зачарований плащ. Чари плаща приховують рятівника від хижих звірів, поки той шукає зниклого слідопита Волкора.",al={"для чого шкури","навіщо збирати шкури місячних хижаків","завдання терентіса про шкури"}},{q="Чи робить готовий плащ цілком невидимим?",a="Плащ створює тонку природну ілюзію, що відлякує звірів, але вона крихка. Терентіс попереджає: якщо робити щось більше, ніж просто розмовляти з іншими, чари зруйнуються, і маскування розвіється.",al={"як працює плащ","обмеження ілюзії плаща","чи плащ скидає невидимість"}}},fp="21,275,25.348.0,20.387.1,45.191.0,43.172.0,36.192.0,54.197.0"}
P.entries["item:fire-tar"] = {n="Вогняна Смола",s="Вогняна Смола — летка речовина, яку збирають чаклуни-шипогриви Гостроманів по всіх східних Пустках. Для шаманів Орди це ключовий обрядовий складник Вогняної Сапти, що дарує духовне єднання зі стихією вогню.",h="Вогняна Смола — летка речовина, яку збирають чаклуни-шипогриви Гостроманів по всіх східних Пустках.",kw={"вогняна смола","шипогриви","гострогриви","шаман","вогняна сапта","вогняний тотем","телф джулам"},ang={["class:Shaman"]="Збирання Вогняної Смоли — важливий обряд переходу, що вчить вас шукати відгомін стихій у широкому світі, аби зварити Вогняну Сапту й заслужити свій Вогняний Тотем.",["faction:Horde"]="Щоб здобути Вогняну Смолу, молоді шукачі пригод Орди покидають Дуротар і переходять Річку Південної Люті в Пустки, де стикаються з агресивними племенами Гостроманів."},sec={{t="Вариво Гостроманів",b="Вогняна смола — алхімічна речовина, тісно споріднена з полум'ям, і носять її майже виключно чаклуни-шипогриви Гостроманів: геоманти, містики й тернові ткачі. Поки щетинисті племена Пусток уживають її для власної жорстокої магії та обрядів, шаманські наставники бачать у ній необхідний земний реагент, здатний перекинути міст між смертними чуттями й сирою люттю стихій."},{t="Шлях до Вогняного Тотема",b="Коли молодих орків і тролів-шаманів посилають до Телфа Джулама, що вмостився високо на скелях Дуротару, їм доручають викувати свій вогняний тотем. Для Вогняної Сапти Телф вимагає два ключові складники, пов'язані з жаром і полум'ям: мішечок реагентів, відібраний у культистів Палаючого Клинка, і вогняну смолу, здобуту в Гостроманів. Випивши готове вариво, шаман пронизує завісу й бачить духів полум'я, що чекають на нього на сусідніх вершинах."}},faq={{q="Для чого потрібна Вогняна Смола?",a="Вогняна Смола — необхідний обрядовий складник, який приносять шаманові-самітникові Телфу Джуламу в Дуротарі. Разом із реагентами Палаючого Клинка з неї варять Вогняну Сапту — зілля, що дає шаманові змогу бачити духів вогню й спілкуватися з ними, щоб заслужити тотем вогню.",al={"використання вогняної смоли","що робить вогняна смола","навіщо мені вогняна смола"}},{q="Хто носить Вогняну Смолу?",a="Її носять шипогриви-заклиначі з племені Гостроманів на сході Пусток — геоманти, містики, плетії терну й шукачі води Гостроманів.",al={"хто дропає вогняну смолу","істоти з вогняною смолою","де взяти вогняну смолу"}},{q="Навіщо шаманам складники, пов'язані з ворожими заклиначами?",a="Для сапти потрібні речові складники, глибоко просякнуті відповідною стихією. І заклиначі Гостроманів, і чорнокнижники Палаючого Клинка спрямовують сильний жар і руйнівне полум'я, тож їхні звичайні речі вже насичені вогняною сутністю, потрібною, щоб пробудити стихійний зір шамана.",al={"чому квілборги й смола","чому чорнокнижники й квілборги"}},{q="Де Телф Джулам варить Вогняну Сапту?",a="Телф Джулам живе на високій кручі над скелями Дуротару, біля стежки між Гострим Пагорбом і Пустками. Там він навчає новачків тримати рівновагу між руйнівною й творчою природою полум'я.",al={"де телф джулам","здати вогняну смолу"}}},fp="8,250,29.406.0,26.454.0,26.269.0,21.157.0,61.300.0,43.207.0"}
P.entries["item:fizzle-s-claw"] = {n="Кіготь Фіззла",s="Кіготь Фіззла — відрубана рука гобліна-чорнокнижника Фіззла Дарксторма. Здобутий у його таборі на Громовому Хребті, він слугує речовим доказом для командирів Орди в Гострому Пагорбі, що небезпечного змовника Палаючого Клинка вбито.",h="Кіготь Фіззла — відрубана рука гобліна-чорнокнижника Фіззла Дарксторма.",kw={"кіготь фіззла","дарксторм","гоблін","чорнокнижник","громовий хребет","палаючий клинок","соулскар"},ang={["class:Warlock"]="Фіззл Дарксторм уживав мистецтва Скверни на службі підривному Палаючому Клинку, обернувши свої темні таланти на пряме повстання проти Орди.",["faction:Horde"]="Піднести кіготь Фіззла в Гострому Пагорбі — означає підтвердити тривалу рішучість очистити Дуротар від тіньових культів, що загрожують крихкій безпеці молодої нації."},sec={{t="Похмурий трофей",b="Орґніл Соулскар, якому доручено викорінити тіньові культи, що загрожують батьківщині орків, визначив Фіззла Дарксторма як підбурювача, що ширить скверну на Громовому Хребті. Вимога принести кіготь Фіззла — не просто дикунство, а практична потреба: Орді потрібен беззаперечний доказ, коли знищено таємного чорнокнижника, що діяв під стягом Палаючого Клинка."},{t="Загроза на Громовому Хребті",b="Громовий Хребет і так був збурений заворушеннями стихій, тож присутність культиста Фіззла стала близькою небезпекою для довколишніх земель. Відрубавши кіготь гобліна й принісши його до Гострого Пагорба, розвідники Орди підтвердили: обряди чорнокнижника та його спроби закріпити Палаючий Клинок на цих землях зірвано."}},faq={{q="Кому належить цей кіготь?",a="Кіготь належав Фіззлу Дарксторму — підступному гоблінові-чорнокнижникові з тіньового культу Палаючого Клинка.",al={"хто такий фіззл","фіззл дарксторм","чий кіготь"}},{q="Навіщо Орґнілу Соулскару Кіготь Фіззла?",a="Орґнілу Соулскару потрібен безсумнівний доказ смерті Фіззла. Палаючий Клинок діє з тіні, тож кіготь гобліна-чорнокнижника засвідчує, що цю загрозу для Дуротару усунено назавжди.",al={"навіщо потрібен кіготь","кіготь орґніла соулскара","доказ смерті"}},{q="Де знайшли кіготь?",a="Його забирають у Фіззла Дарксторма в його таборі, захованому на Громовому Хребті — у каньйоні на північний захід від Гострого Пагорба в Дуротарі.",al={"місце фіззла","де фіззл","кіготь громового хребта"}},{q="Що Палаючий Клинок робить у Дуротарі?",a="Палаючий Клинок — зловісний культ, що прагне підточити нову батьківщину орків демонічною скверною, темним чаклунством і заворушеннями. Чорнокнижники на кшталт Фіззла засновують приховані табори, щоб сіяти хаос по всьому краю.",al={"палаючий клинок у дуротарі","чому культисти на громовому хребті"}}},fp="13,242,13.376.0,27.325.0,29.127.0,44.219.0,25.135.0,43.220.0"}
P.entries["item:flagongut-s-fossil"] = {n="Скам'янілість Флагонгата",s="Скам'янілість Флагонгата — давній зразок, знайдений на розкопках у Багнокраї. Довірена дворфській Лізі Дослідників, вона ховає таємниці, які археолог Флеґонґат хоче розгадати за допомогою загадкової реліквії — Каменя Релу.",h="Скам'янілість Флагонгата — давній зразок, знайдений на розкопках у Багнокраї.",kw={"скам'янілість флагонгата","флеґонґат","камінь релу","ліга дослідників","шукач велґар","багнокрай"},ang={["faction:Alliance"]="Рятуючи артефакти зі зруйнованих розкопок Велґара, ви не даєте диким звірам знищити цінну історію, а ворожим силам — розграбувати її серед боліт.",["race:Dwarf"]="Для дворфів-дослідників скам'янілості на кшталт Флеґонґатової — не просто дивина, а відчутний зв'язок із сивою давниною, яку Ліга Дослідників присягнула відкопати."},sec={{t="Розкопки й дослідження",b="Ця давня скам'янілість, викопана під час дворфських експедицій по всьому Каз Модану, — щось більше, ніж просто закам'янілий камінь. Археолог Флеґонґат вірить, що в ній приховані забуті сили, пов'язані з сивою давниною світу, — подібні до артефактів, знайдених за морем, на Темному Узбережжі. На час досліджень у краї скам'янілість зберігав шукач Велґар на своїх розкопках у південних пагорбах Багнокраю."},{t="Як відімкнути реліквію",b="Знайшовши Камінь Релу, Флеґонґат зрозумів, що це ключ, потрібний, аби розгадати таємниці скам'янілості. Та дорогою на нього напали плямисті раптори, і камінь загубився. Щоб нарешті розкрити зразок, Флеґонґатові потрібні шукачі пригод, які заберуть скам'янілість із розкопок Велґара й добудуть проковтнутий камінь у звірів Багнокраю."}},faq={{q="Що таке Скам'янілість Флагонгата?",a="Це прадавній археологічний зразок, знайдений у Багнокраї, який дворфська Ліга Дослідників зберігає для вивчення, щоб розкрити таємниці давнього минулого світу.",al={"що таке скам'янілість","історія скам'янілості флагонгата"}},{q="Де знайти скам'янілість?",a="Вона в печері на вершині Місця Розкопок Велґара, серед південних гір Багнокраю, і її стережуть раптори й слизи, що заполонили розкопки.",al={"місце скам'янілості","де скам'янілість флагонгата","печера скам'янілості велґара"}},{q="Навіщо Флагонгату її повернути?",a="Флагонгат вважає, що разом із Каменем Релу зможе розгадати приховані магічні таємниці скам'янілості й порівняти її природу зі схожими знахідками в Калімдорі.",al={"чому флагонгат її хоче","що флагонгат з нею зробить"}},{q="Як вона пов'язана з Темним Узбережжям?",a="Флагонгат бачить схожість між цим зразком із Багнокраю та скам'янілістю, яку знайшов Шукач Ремтревел за морем, на Темному Узбережжі, і вірить, що Камінь Релу може пробудити силу в обох реліквіях.",al={"зв'язок з темним узбережжям","скам'янілість ремтревела"}}},fp="18,255,20.430.0,19.371.1,27.168.0,28.168.0,36.172.0,33.197.0"}
P.entries["item:flatland-cougar-femur"] = {n="Стегнова Кістка Рівнинного Кугуара",s="Стегнова Кістка Рівнинного Кугуара — щільна стегнова кістка хижих кугуарів, що никають золотими травами Малгору. Вона є важливим складником традиційних народних ліків тауренів, якими борються зі смертельним отруйним зараженням.",h="Стегнова Кістка Рівнинного Кугуара — щільна стегнова кістка хижих кугуарів, що никають золотими травами...",kw={"стегнова кістка рівнинного кугуара","кугуар","маур рейнколлер","маззранаш","село бладгуф","малгор","ліки"},ang={["class:Hunter"]="Щоб вистежити рівнинних кугуарів серед хвилястих чагарів Малгору, потрібне гостре око — це випробування для молодого мисливця: чи зможе він чисто здолати такого ж хижака, як сам.",["race:Tauren"]="Для тауренів Малгору полювання на рівнинного кугуара — і перевірка пильності, і джерело цінних матеріалів для традиційних ліків рівнин."},sec={{t="Ліки від отруйного укусу",b="Рівнинний кугуар — один із найнебезпечніших місцевих мисливців Малгору: він зливається з сухими чагарями, аж поки не стрибне на необачну здобич. Мисливці часто беруть шкури й пазурі кугуарів для шкірництва й на трофеї, але їхні важкі кістки, повні кісткового мозку, мають і практичну цінність для місцевої медицини. Коли Маур Рейнколлер, шаман із Села Бладгуф, дістав отруйну рану від страхітливого рожевого довгоступа Маззранаша, він терміново попросив стегнову кістку кугуара разом із частинами інших місцевих звірів. Кістку товчуть або виварюють, щоб видобути її цілющі властивості, і готують протиотрутну припарку, здатну витягнути жар і мертвотну отруту з гнійної рани від укусу."}},faq={{q="Для чого потрібна Стегнова Кістка Рівнинного Кугуара?",a="Маур Рейнколлер у Селі Бладгуф варить із неї невідкладні ліки. Маура вкусив сумнозвісний довгоступ Маззранаш, і йому потрібні кістковий мозок і кістка, щоб приготувати протиотруту, перш ніж люта отрута звіра його вб'є.",al={"використання стегнової кістки кугуара","для чого ця кістка","завдання стегнова кістка"}},{q="Де здобути Стегнову Кістку Рівнинного Кугуара?",a="Її беруть із рівнинних кугуарів, що блукають центральними й південними рівнинами Малгору, — зазвичай вони никають схилами й високою травою довкола Села Бладгуф.",al={"де знайти стегнову кістку кугуара","місце кістки кугуара","які істоти її дропають"}},{q="Чому Маурові Рейнколлеру потрібна саме кістка кугуара?",a="Тауренські травники й шамани часто додають щільні кістки й кістковий мозок хижаків до традиційних мазей і настоянок. Вважають, що сила й витривалість найгрізніших хижаків Малгору дають цілющу основу, потрібну, щоб знешкодити сильну отруту.",al={"чому кістка кугуара","чому стегнова кістка"}},{q="Хто такий Маур Рейнколлер?",a="Маур Рейнколлер — таурен із Села Бладгуф. Блукаючи рівнинами, він натрапив на Маззранаша — легендарного довгоступа, з яким колись бився його дід, — і ледве втік із запаленим отруйним укусом у плече.",al={"маур рейнколлер","хто потребує кістку"}}},fp="21,232,28.686.0,43.246.0,44.189.0,58.283.0,23.232.0"}
P.entries["item:flatland-prowler-claw"] = {n="Кіготь Рівнинного Бродяги",s="Кіготь Рівнинного Бродяги беруть у небезпечних котячих хижаків, що скрадаються трав'янистими рівнинами Малгору. Для майбутніх мисливців збирання цих кігтів — традиційний обряд посвяти, що доводить старійшинам Тандер Блафу їхню кмітливість і бойову рішучість.",h="Кіготь Рівнинного Бродяги беруть у небезпечних котячих хижаків, що скрадаються трав'янистими рівнинами...",kw={"кіготь рівнинного бродяги","рівнинний бродяга","мисливець","скорн вайтклауд","мелор стоунгуф","тандер блаф","малгор"},ang={["class:Hunter"]="Полювання на потайних бродяг перевіряє, наскільки пильний мисливець у полі, тож ці кігті — символ заслуженої поваги серед стрільців, що збираються на Узвишші Мисливців у Тандер Блафі.",["race:Tauren"]="Для тауренів полювання — почесна духовна традиція, і подані кігті хитрого рівнинного хижака знаменують перші кроки посвяченого до служіння племені слідопитом."},sec={{t="Доказ мисливця",b="Рівнинні бродяги — одні з найхитріших і найтериторіальніших хижаків, що никають обвітреними рівнинами Малгору. Прудкі й вправні у засідках у високій траві, вони становлять справжню загрозу для подорожніх і гідне випробування для молодих мисливців. Збирати їхні гострі кігті — не просто справа виживання, а визнана традиція. Скорн Вайтклауд радить перспективним мандрівникам здобути ці трофеї й подати їх Мелору Стоунгуфу на Узвишші Мисливців у Тандер Блафі — на доказ того, що вони мають рішучість і польову майстерність, потрібні на шляху мисливця."}},faq={{q="Для чого потрібні Кігті Рівнинного Бродяги?",a="Вони наочно доводять вправність і відвагу. Молоді мисливці приносять чотири такі кігті Мелорові Стоунгуфу на Узвишшя Мисливців у Тандер Блафі, щоб довести, що готові ступити на шлях мисливця.",al={"використання кігтя бродяги","навіщо кігті бродяги","шлях мисливця кігті"}},{q="Хто просить їх зібрати?",a="Старий мисливець Скорн Вайтклауд посилає здібних слідопитів зібрати кігті нишпорок Малгору — як доказ, перш ніж ті з'являться до Мелора Стоунгуфа.",al={"хто хоче кігті бродяги","видавець завдання на кігті бродяги"}},{q="Чому полювання на рівнинних нишпорок вважають гідним?",a="Рівнинні Нишпорки — витривалі, скритні й хитрі хижаки малгорських рівнин. Вистежити й здолати таких пильних звірів — означає довести, що майбутній мисливець має терпіння й бойове чуття, яких вимагає тауренська традиція.",al={"чому рівнинні нишпорки","чи небезпечні бродяги"}}},fp="21,268,16.571.0,41.207.0,29.178.0,52.245.0"}
P.entries["item:foreman-s-blackjack"] = {n="Кийок Наглядача",s="Кийок Наглядача — важка, обмотана шкірою довбня, яку позичають новим новобранцям Орди в Долині Випробувань. Наглядачі передають її як буденне знаряддя дисципліни: будити заснулих пеонів і тримати виснажливий темп перших будов Дуротару.",h="Кийок Наглядача — важка, обмотана шкірою довбня, яку позичають новим новобранцям Орди в Долині Випробувань.",kw={"кийок","наглядач","тазз'ріл","пеони","робітники","долина випробувань","дуротар"},ang={["faction:Horde"]="Кийок показує невпинні практичні зусилля, потрібні, щоб приборкати Дуротар: заселення суворого краю вимагає від кожного робітника праці без перепочинку.",["race:Orc"]="Для молодих орків, що ступають у Долину Випробувань, кийок у руках — ранній урок ієрархії Орди: тих, кому бракує сили чи духу воїна, відводять до праці й тримають у покорі силою."},sec={{t="Знаряддя орчої праці",b="Щоб збудувати новий дім у суворій пустелі Дуротару, потрібні величезні запаси деревини, і ця праця цілком лягає на плечі пеонів Орди. У Долині Випробувань Наглядач Тазз'ріл покладається на Кийок Наглядача, щоб робочі бригади не спинялися. Ця майстерно обтяжена довбня не завдає смертельних ударів — вона дає струсливий побудильний сигнал робітникам, яких заскочили за дрімотою під тінистими деревами долини. Це суворе нагадування про життя пеона в новій Орді: виснажливе, невдячне й під залізною рукою."}},faq={{q="Для чого потрібен Кийок Наглядача?",a="Наглядачі дають кийок молодим шукачам пригод, щоб приборкувати сонних пеонів по всій Долині Випробувань. Удар по задрімалому пеонові миттю його будить і повертає до рубання й тягання дров.",al={"використання кийка","навіщо кийок","кийок для пеонів"}},{q="Кому належить цей кийок?",a="Він належить Наглядачеві Тазз'рілу, що керує роботами в Долині Випробувань і наглядає за заготівлею деревини для молодого поселення орків.",al={"хто дає кийок","чий кийок наглядача"}},{q="Чому пеони раз у раз засинають на роботі?",a="Пеони-орки працюють виснажливі зміни, заготовляючи дрова під пекучим сонцем Дуротару. Щойно вони знаходять тінь під рідкими деревами долини, втома бере своє — і вони самовільно дрімають.",al={"чому пеони сплять","ледачі пеони"}},{q="Чи можна залишити кийок собі після завдання?",a="Ні. Наглядач вимагає негайно повернути знаряддя, щойно ледарів приборкано, щоб воно завжди було під рукою в наступних наглядачів і норми виконувалися.",al={"залишити кийок","чи можна залишити кийок наглядача"}}},fp="19,261,22.544.0,41.211.0,24.159.0,48.220.0,50.174.0"}
P.entries["item:forged-steel-bars"] = {n="Зливки Кованої Сталі",s="Зливки кованої сталі — очищені металеві злитки, що належать орку-ковалеві Тун'ґріму Файрґейзу. Спритні шипогриви-Гостромани викрали їх під час нічного нальоту, і повернути їх — доказ рішучості воїна, що відбирає вкрадене в Пустках.",h="Зливки кованої сталі — очищені металеві злитки, що належать орку-ковалеві Тун'ґріму Файрґейзу.",kw={"зливки кованої сталі","тун'ґрім файрґейз","коваль","гостромани","шипогриви","ковальство"},ang={["class:Warrior"]="Повернувши викрадену сталь Тун'ґріма, воїн доводить, що вміє вистежити злодіїв і зійтися з небезпечними зграями шипогривів, — і отримує за це зброю, викувану на замовлення.",["profession:Blacksmithing"]="Очищені зливки показують, яка прірва лежить між грубим племінним металобрухтом і якісною сталлю, що її кують навчені ковалі Орди."},sec={{t="Викрадений метал",b="Зливки кованої сталі — високоякісна ковальська заготовка, що належить слабозорому орку-ковалеві Тун'ґріму Файрґейзу, який має табір на півночі Пусток. Скориставшись тим, що зір Тун'ґріма слабне, місцеві шипогриви-Гостромани відволікли коваля рохканням і хрюканням, поки злодії вислизнули із залізною скринею, повною злитків. Не тямлячи в обробці доброї сталі, шипогриви покинули нерозкриту скриню біля розбитого воза у своєму таборі на північному заході, тож зливки лишилися цілими й чекають воїнів, які прийдуть їх повернути."}},faq={{q="Кому належать ці зливки кованої сталі?",a="Вони належать Тун'ґріму Файрґейзу — орку-зброяреві й панцирникові, що живе в таборі на півночі Пусток.",al={"чиї зливки","сталь тун'ґріма","чия це сталь"}},{q="Навіщо шипогриви їх украли?",a="Шипогриви Гостроманів напали на табір Тун'ґріма просто заради грабунку. Знаючи, що коваль погано бачить, одні дражнили й відволікали його, поки інші тягли його залізну скриню.",al={"чому красти сталь","мотив квілборгів","крадіжка шипогривів"}},{q="Чи скористалися шипогриви сталлю?",a="Ні. Як і передбачав Тун'ґрім, Гостромани не мали ні знань, ні вміння, щоб обробити таку добірну сталь. Скриня так і лишилася зачиненою й покинутою біля зламаного воза в їхньому таборі.",al={"чи ковали квілборги","що зробили шипогриви зі сталлю"}},{q="Що Тун'ґрім дасть натомість?",a="За сміливість піти в табори шипогривів і повернути всі зливки Тун'ґрім винагороджує молодих воїнів викуваною зброєю.",al={"нагорода за кувану сталь","що я отримаю за сталь"}}},fp="17,244,12.557.0,33.107.0,32.214.0,31.198.0,45.129.0"}
P.entries["item:fragments-of-rok-alim"] = {n="Уламки Рок'Аліма",s="Уламки Рок'Аліма — розтрощені кам'яні рештки первісного елементаля землі, що блукає каньйонами Тисячі Голок. Принесені Дорнові Плейнстокеру до Вивітреного Закутка, вони стають незаперечним речовим доказом того, що воїн здолав прадавнє страхіття у двобої.",h="Уламки Рок'Аліма — розтрощені кам'яні рештки первісного елементаля землі, що блукає каньйонами Тисячі Голок.",kw={"уламки рок'аліма","рок'алім товкач","елементаль землі","дорн плейнстокер","випробування сили","тисяча голок"},ang={["class:Shaman"]="Рок'Алім — прадавній дух землі, прив'язаний до світу задовго до нинішніх шаманських угод, тож його незламна вдача — цікавий приклад первісної стихійної впертості.",["race:Tauren"]="Перемога над живучими рештками первісного минулого Азероту близька до тауренських традицій випробовувати гармонію, стійкість і власну силу в зіткненні з найгрізнішими небезпеками краю."},sec={{t="Рештки прадавньої сили",b="Більшість елементалів зникли з Азероту після того, як було ув'язнено Древніх Богів, але деякі мали досить первісної сили, щоб лишитися на поверхні без виклику смертною магією. Рок'Алім Товкач — один із таких уцілілих: він блукає рівнинами каньйону на південь від головного шляху. Місцеві кентаври знають його з громового гуркоту кам'яних кулаків, що трощать на порох кожного, кому забракне розуму стати йому на шляху. Повалений, цей живий залишок первісного світу розсипається на гострі шматки щільної ожилої скелі — трофей, гідний довести неперевершену фізичну міць."},{t="Випробування сили",b="Для таурена-відлюдника Дорна Плейнстокера ці уламки — вирішальна частина Випробування сили. Серед низки духовних і бойових обрядів, що відбуваються високо у Вивітреному Закутку, це випробування вимагає від посвячуваного зустрітися з істотою незламної грубої сили. Принісши побиті рештки Рок'Аліма, шукач пригод доводить, що має досить хоробрості й фізичної міці, аби вижити серед найсуворіших небезпек Калімдору."}},faq={{q="Що таке Уламки Рок'Аліма?",a="Це розбиті кам'яні рештки Рок'Аліма Товкача — прадавнього елементаля землі, що никає північно-західними каньйонами Тисячі Голок. Вони — доказ перемоги над елементалем.",al={"уламки рок'аліма","що таке уламки рок'аліма","камінь рок'аліма"}},{q="Кому потрібні ці кам'яні уламки?",a="Дорн Плейнстокер, таурен, що мешкає в Обвітреній Ніші високо на кручах каньйонів Тисячі Голок, просить уламки, щоб завершити «Тест Сили».",al={"кому віддати уламки рок'аліма","здати уламки","завдання дорна плейнстокера"}},{q="Чим особливий Рок'Алім?",a="На відміну від більшості нинішніх елементалів, яких мусять викликати смертні маги, Рок'Алім живе у світі ще з епохи Древніх Богів. Кентаври з каньйонів прозвали його Товкачем через гуркіт, з яким його кулаки трощать здобич.",al={"чим особливий рок'алім","історія рок'аліма","хто такий рок'алім молотильник"}},{q="Де знайти Рок'Аліма?",a="Рок'Алім блукає північно-західною улоговиною Тисячі Голок, на південь від головного шляху краю, між піщаниковими шпилями.",al={"місце рок'аліма","знайти рок'аліма","де з'являється рок'алім"}}},fp="21,278,28.570.0,18.449.0,35.188.0,32.176.0,28.253.0,24.131.0"}
P.entries["item:frostwolf-banner"] = {n="Прапор Морозного Вовка",s="Прапор Морозного Вовка — племінний стяг, захований глибоко в Печері Диколапів у Долині Альтерак. Новачків Орди посилають повернути його в межах давнього обряду посвяти, щоб пробудити в них бойовий дух і заслужити першу відзнаку клану.",h="Прапор Морозного Вовка — племінний стяг, захований глибоко в Печері Диколапів у Долині Альтерак.",kw={"прапор морозного вовка","клан морозного вовка","печера диколапів","долина альтерак","воєвода лаґґронд","гноли"},ang={["faction:Horde"]="Повернення цього прапора позначає офіційне бойове хрещення воїна й посвяту до легендарного клану Морозного Вовка під проводом Воєводи Лаґґронда.",["race:Orc"]="Для орків повернення втраченого кланового стягу з рук диких гнолів — шана спадщині Морозного Вогню та родовому корінню Тралла в Альтерацьких горах."},sec={{t="Обряд посвяти",b="Для воїнів Орди, що прибувають до Долини Альтерак, справжнє місце в клані Морозного Вовка починається з випробування витривалості. Воєвода Лаґґронд посилає новобранців на південь, у вогкі, ворожі ходи Печери Диколапів — лігва, що кишить гнолами, які люто боронять свою територію. Дістатися прапора, схованого в глибинах печери, і повернути його неушкодженим — означає довести свою мужність, показати, що бойова лють воїна пробудилася, і заслужити відзнаку новачка клану Морозного Вовка."}},faq={{q="Чому Прапор Морозного Вовка лежить у печері гнолів?",a="Воєвода Лаґґронд і клан навмисно перетворили схованку прапора в Печері Диколапів на посвятне випробування. Вилазка на землі гнолів змушує нових бійців струсити самовдоволення, зустрітися з небезпекою й пробудити бойовий дух.",al={"чому прапор у вайлдпо","гноли мають прапор","місце прапора морозного вовка"}},{q="Кому повернути Прапор Морозного Вовка?",a="Прапор треба повернути Воєводі Лаґґронду в Долині Альтерак. Коли новачок вручає його, воєвода офіційно приймає новачка до лав Морозного Вовка й дає відзнаку.",al={"кому віддати прапор морозного вовка","здати прапор","прапор лаґґронда"}},{q="Чому стяг має незвичний для Морозного Вовка вигляд?",a="Лаґґронд визнає його стягом кланового випробування, але знаки на ньому нагадують давніші племінні символи — зокрема ті, що належали першим кланам орків старої Орди.",al={"символ молота присмерку на прапорі","прапор виглядає неправильно","дизайн прапора морозного вовка"}}},fp="16,231,17.460.0,48.235.0,40.179.0,57.180.0"}
P.entries["item:full-leaden-collection-phial"] = {n="Повна Свинцева Колекційна Колба",s="Важка колба зі свинцевою оболонкою, наповнена радіоактивними опадами, зібраними з трогів, що кишать у Гномреґані. Винахідник Оззі Тоґлвольт попросив цей небезпечний зразок, сподіваючись створити ліки для опромінених прокажених гномів — або, може, зварити небезпечно міцний ром.",h="Важка колба зі свинцевою оболонкою, наповнена радіоактивними опадами, зібраними з трогів, що кишать у...",kw={"повна свинцева колекційна колба","колба","радіоактивні опади","оззі тоґлвольт","харанос","гномреґан"},ang={["profession:Engineering"]="Свинцевий корпус — стандартний гномський запобіжний захід під час роботи з нестійкими отруйними опадами для лабораторних випробувань.",["race:Gnome"]="Для гномів-вигнанців у Дун Мороґу цей отруйний зразок — похмуре нагадування про катастрофу, що отруїла їхній рідний дім, але й відчайдушна надія повернути спотворених родичів."},sec={{t="Отруйне вариво",b="Свинцева оболонка цієї колби конче потрібна, щоб захистити того, хто її несе, від нестійких зелених опадів, якими просякнутий Гномреґан. Опади з'явилися, коли радники Великого Тінкера Меккаторка затопили нижні коридори отруйним випромінюванням, щоб зупинити трогів-загарбників, — а катастрофа натомість спотворила і трогів, і вцілілих гномів, перетворивши їх на шалених опромінених потвор. Збираючи рідкі рештки просто з Опромінених Загарбників і Грабіжників, відважні шукачі пригод постачають майстрам-біженцям у Хараносі, як-от Оззі Тоґлвольту й Раззлу Спрайспрокету, сировину для дослідів із ліками."},{t="Ліки чи вариво",b="Поки Ґноарн одержимий думкою відвоювати місто, Оззі Тоґлвольт береться за проблему опадів із шаленим гномським експериментаторством. Оззі хоче застосувати рідину, зібрану в колбу, щоб лікувати полоненого прокаженого гнома, — і водночас сподівається, що суміш поверне йому втрачене волосся. У гномській лабораторній науці межа між чудодійною протиотрутою й украй вибуховим напоєм лишається небезпечно тонкою."}},faq={{q="Чому колба свинцева?",a="Свинцеве покриття не дає сильним радіоактивним опадам, зібраним із заражених трогів Гномреґана, отруїти чи вбити того, хто несе колбу назад до Хараноса.",al={"чому колба свинцева","чому свинець","призначення свинцевої колби"}},{q="Кому потрібна ця опромінена рідина?",a="Оззі Тоґлвольт, гном-дослідник із Хараноса, потребує опромінених опадів, щоб разом із Раззлом Спрайспрокетом шукати ліки для гномів, уражених проказою.",al={"кому потрібна колба","завдання оззі тоґґлвольта","хто бере ноґейн"}},{q="Звідки випромінювання в колбі?",a="Світний зелений осад добувають просто з Опромінених Загарбників і Опромінених Грабіжників — трогів, що никають отруєними коридорами, які ведуть до Гномреґана.",al={"як наповнити колбу","місце опромінених троґів","джерело зеленого сяйва"}},{q="Чи справді Оззі вилікує нею прокажених гномів?",a="Досліди Оззі хаотичні й непевні. Його суміш має вилікувати полоненого прокаженого гнома й повернути йому самому волосся, але гномська наука часто потребує повторних випробувань і кращих зразків, перш ніж дасть безпечний і сталий результат.",al={"чи ліки діють","результат ноґейну","чи вилікують прокажених гномів"}}},fp="28,287,12.609.0,18.425.1,30.174.0,32.172.0,48.163.0,50.235.0"}
P.entries["item:fungal-spores"] = {n="Грибні Спори",s="Грибні спори збирають з обтяжених ними грибів, що ростуть довкола дивних оаз Пусток. Сповнені загадкової життєвої сили цих вод, вони дуже цінні для дослідників Королівського Аптекарського Товариства, які шукають сильні реагенти для своїх хімічних зіль.",h="Грибні спори збирають з обтяжених ними грибів, що ростуть довкола дивних оаз Пусток.",kw={"грибні спори","королівське аптекарське товариство","аптекар гелбрім","оази","відступники","травництво"},ang={["profession:Herbalism"]="Травники й збирачі помітять разючі зміни в будові цих грибів, спричинені життєдайними, перетворювальними водами оаз Пусток.",["race:Undead"]="Королівське Аптекарське Товариство цінує унікальні місцеві реагенти для своїх досліджень, і мутовані гриби Калімдору — спокуслива заміна знівеченим порчею рослинам Лордерону."},sec={{t="Життєва сила оаз",b="На посушливих рівнинах Пусток смарагдові оази — як-от Забуті ставки, Оаза Буйних Вод і Застояна Оаза — пульсують незвичною життєвою силою. Вода тут не лише вгамовує спрагу: вона прискорює, змінює й наснажує рослини та звірів довкола. Гриби на вологих берегах розбухають і важчають від спор, що несуть цю зосереджену, нестійку силу росту. Для природознавців це дивина природи, а для Королівського Аптекарського Товариства — чудовий рослинний зразок, який чекає, щоб його обернули на зброю чи вдосконалили."},{t="Алхімія Відступників",b="Аптекарі, що служать далеко від дому, як-от Аптекар Гелбрім на Перехресті, безупинно збирають екзотичні місцеві реагенти, щоб відсилати їх до своїх лабораторій чи ділитися з далекими колегами, як-от Аптекаркою Замах у Тандер Блафі. Змінена будова спор робить їх особливо цінними для приготування сильних хімічних розчинів. Відступники цінують ці зразки саме тому, що їхні природні властивості вже змінили загадкові сили, які вирують під землею Калімдору."}},faq={{q="Де знайти ці спори?",a="Грибні Спори збирають із налитих спорами грибів, що ростуть на берегах великих оаз Пусток: Забутих ставків, Оази Буйних Вод і Застояни.",al={"місця спор","де знайти грибні спори","місця грибів"}},{q="Чому ними цікавляться Відступники?",a="Спори насичені зміненою, буйною життєвою енергією оаз. Аптекар Гелбрім варить із них сильні алхімічні суміші для Королівського Аптекарського Товариства та своєї колеги, Аптекарки Замах у Тандер Блафі.",al={"чому хелбрим хоче спори","використання спор аптекарями","для чого спори"}},{q="Чому гриби довкола оаз такі великі?",a="Води оаз Пусток мають незвичну життєву силу, що бадьорить і змінює довколишні рослини й тварин, — тож гриби на берегах набухають сильними зміненими спорами.",al={"чому гриби мутовані","вплив води оази","таємниця оази"}},{q="Хто просить зібрати спори?",a="Аптекар Гелбрім, алхімік-Відступник із Перехрестя в Пустках, доручає шукачам пригод зібрати спори для своїх досліджень.",al={"кому потрібні грибні спори","хто дає завдання на спори","аптекар хелбрим"}}},fp="13,268,21.570.0,16.495.0,29.168.0,40.228.0,52.197.0,24.146.0"}
P.entries["item:furen-s-instructions"] = {n="Настанови Фурена",s="Настанови Фурена — рукописний пергамент від майстра-броняра Фурена Лонґбірда в Стормвінді. У ньому докладно перелічено рідкісні й небезпечні реагенти, потрібні, щоб викувати загартовану вогнем кольчугу для перспективних воїнів Альянсу.",h="Настанови Фурена — рукописний пергамент від майстра-броняра Фурена Лонґбірда в Стормвінді.",kw={"настанови фурена","фурен лонґбірд","кольчуга","химери","рейзорфен краул","флогістон"},ang={["class:Warrior"]="Цей перелік — обряд посвяти для воїнів Альянсу, що переходять на важку кольчугу: він вимагає випробувань у боротьбі з лютими звірами й мерзенними шипогривами.",["profession:Blacksmithing"]="Екзотичний рецепт Фурена показує, як майстри-ковалі поєднують звірині реагенти й рідкісні алхімічні дистиляти, щоб гартувати обладунки понад звичайне кування."},sec={{t="Вимоги майстра",b="Фурен Лонґбірд не роздає видатних обладунків абияк. Уже перевіривши рішучість воїна простішими ковальськими завданнями, дворфійський майстер пропонує викувати надзвичайно міцну кольчугу — за умови, що шукач пригод сам добуде рідкісні складники. Щоб нічого не забути, Фурен дає цей докладний перелік і посилає підопічного через континенти в нелегкі пошуки."},{t="Екзотичні складники",b="Настанови описують небезпечну подорож і Східними Королівствами, і Калімдором. Щоб викувати загартовані кільця, потрібні десятки обпалених павучих іклів із вогких печер Багнокраю, роги вогнедишних химер зі скель Гір Кам'яного Кігтя й цінний гальванований ріг самого матріарха химер. Останній, алхімічний каталізатор — фіал непередбачуваного флогістону, що зберігається глибоко в твердині шипогривів Рейзорфен Краул."}},faq={{q="Що таке Настанови Фурена?",a="Це письмовий перелік, який коваль Фурен Лонґбірд у Стормвінді дає воїнам Альянсу. У ньому названо особливі екзотичні матеріали, потрібні, щоб викувати загартовану вогнем кольчугу.",al={"настанови фурена","що за настанови фурена","список фурена"}},{q="Хто такий Фурен Лонґбірд?",a="Фурен Лонґбірд — майстер-зброяр із дворфів у Дворфійському Кварталі Стормвінда. Він випробовує досвідчених воїнів і кує для них міцне захисне спорядження.",al={"хто такий фурен","фурен лонґбірд","фурен стормвінд"}},{q="Звідки беруться матеріали зі списку?",a="Список посилає воїнів світ за очі: обпалені павучі ікла добувають у павуків Багнокраю, обвуглені роги й гальванований ріг — у химер Гір Кам'яного Кігтя, а фіал флогістону треба відібрати в Рооґуґа в Рейзорфен Краул.",al={"де знайти предмети","місця матеріалів фурена","матеріали зі списку фурена"}},{q="Що Фурен кує з цих матеріалів?",a="Коли воїн повертає йому всі небезпечні реагенти й настанови, Фурен, удаючись до своїх ковальських таємниць, кує для нього особливий обладунок — загартовану вогнем кольчугу.",al={"яку броню кує фурен","нагорода кольчуга","нагорода від фурена"}}},fp="20,223,24.417.0,17.472.0,29.195.0,23.182.0,45.266.0,43.179.0"}
P.entries["item:furen-s-notes"] = {n="Нотатки Фурена",s="Нотатки Фурена — рукописні зошити з відкриттями в металургії й бронярстві, які зробив Фурен Лонґбірд у Стормвінді. Написані після того, як він викував міцне захисне спорядження для досвідчених воїнів, вони розходяться по всьому Альянсу, щоб удосконалити майстерність колег-ремісників.",h="Нотатки Фурена — рукописні зошити з відкриттями в металургії й бронярстві, які зробив Фурен Лонґбірд у...",kw={"нотатки фурена","фурен лонґбірд","бронярство","ґріманд елмор","матіель","дарнасус"},ang={["class:Warrior"]="Ці нотатки з'явилися саме завдяки вашим випробуванням заради обладунків у Стормвінді — це доказ практичних новинок, народжених потребами передової.",["profession:Blacksmithing"]="Ці зошити втілюють постійний обмін особливими знаннями бронярства між дворфійськими, ельфійськими й гномськими майстрами по всьому Альянсу."},sec={{t="Відкриття майстра",b="Завершивши виснажливе кування особливого спорядження для воїнів у Дворфійському Кварталі Стормвінда, Фурен Лонґбірд записує методи й прориви, яких дійшов дорогою. Дворфійська металургія постійно розвивається, і Фурен робить кілька копій цих трактатів, щоб колеги могли повторити його відкриття й розвинути їх. Записи фіксують практичні здобутки в гартуванні, зміцненні й формуванні обладунків, що мають витримувати смертельні удари в бою."},{t="Розіслані по всьому Альянсу",b="Фурен розсилає свої нотатки надійним знайомим у ремісничих колах Альянсу. Місцеві майстри на кшталт Ґріманда Елмора можуть хмикати, що їх повчає колега, якого вони нібито самі навчали, та знехтувати цінністю цих знань неможливо. Копії везуть навіть за Велике Море — до нічноельфійських майстрів, як-от Матіель на Терасі Воїна в Дарнасусі, — і спільна бойова потреба зближує різні давні традиції."}},faq={{q="Що в Нотатках Фурена?",a="У нотатках описано способи кування обладунків і металургійні відкриття, які Фурен Лонґбірд зробив, виготовляючи обладунки на замовлення для досвідчених воїнів.",al={"що в нотатках фурена","зміст нотаток фурена","вміст нотаток фурена"}},{q="Хто такий Фурен Лонґбірд?",a="Фурен Лонґбірд — дворф, майстер-зброяр із Дворфійського Кварталу Стормвінда, відомий тим, що наставляє молодих воїнів і кує особливе захисне спорядження.",al={"хто це написав","хто такий фурен","фурен лонґбірд"}},{q="Чому Ґріманд Елмор сердиться через нотатки?",a="Ґріманд Елмор — дуже гордий коваль зброї й обладунків, що запевняє, ніби сам навчив Фурена всього, що той знає. Він обурений натяком, що колишній учень може навчити його чогось нового, але все ж визнає: описані в нотатках способи варто спробувати.",al={"чому ґріманд сердиться","реакція ґріманда елмора","гордість ґріманда"}},{q="Хто отримує копії Нотаток Фурена?",a="Фурен розсилає копії своїх записів довіреним колегам по всьому Альянсу — зброярові Ґріманду Елмору в Стормвінді, ковалеві з нічних ельфів Матіелю в Дарнасусі та гномові-ковалю Клокморту Спаннерспану в Айронфорджі.",al={"хто отримує нотатки фурена","куди нотатки","віднести нотатки фурена"}},{q="Як Матіель сприймає нотатки?",a="На відміну від суворих ковалів Стормвінда, Матіель — нічний ельф-коваль із Тераси Воїна в Дарнасусі — щиро й захоплено приймає дворфські знахідки: для нього напрацювання Фурена — велике відкриття, і він за честь вважає застосувати їх у своїй роботі.",al={"реакція матіель","матіель дарнасус","що думає матіель"}}},fp="13,287,22.471.0,30.465.0,39.184.0,23.172.0,50.276.0,37.244.0,36.261.0"}
P.entries["item:furlbrow-s-deed"] = {n="Грамота Фурлброу",s="«Грамота Фурлброу» — документ, що засвідчує право власності фермера Теодора Фурлброу та його дружини Верни на землю у Вестфолі. Розбійники Дефіасу викрали його, щоб підробляти за ним земельні грамоти, і він уособлює хиткий стан чесних людей, вигнаних зі своїх домівок по всьому королівству.",h="«Грамота Фурлброу» — документ, що засвідчує право власності фермера Теодора Фурлброу та його дружини Верни на...",kw={"грамота фурлброу","теодор фурлброу","верна фурлброу","братство дефіас","вестфол","підробка"},ang={["faction:Alliance"]="Повернута грамота — невелика розрада для підданих, які втратили домівки й яких покинуло королівство, що не має досить війська.",["race:Human"]="Крадіжка звичайних грамот на власність показує, наскільки глибоко Братство Дефіас підірвало громадський лад у землях по сусідству зі Стормвіндом."},sec={{t="Вкрадена земля й підроблені грамоти",b="Цей папір, підписаний Теодором Фурлброу й скріплений підписом його дружини Верни, засвідчує право власності на їхню родинну ферму у Вестфолі. Коли Братство Дефіас заполонило край, розбійники силою вигнали подружжя й забрали документ із собою до Лісу Елвінн. Нашкрябані на звороті нотатки свідчать, що злодії збиралися використати офіційний пергамент як зразок, щоб підробляти грамоти на інші володіння. Позбавлені дому й засобів до життя, Фурлброу опинилися на дорозі — а коли їхній віз зламався, застрягли біля кордону."}},faq={{q="Чому Дефіас украли грамоту?",a="Записи на звороті пергаменту показують, що головорізи Дефіас хотіли вивчити справжню печатку й підписи, щоб підробляти власні грамоти й узаконити захоплені хутори по всьому Вестфолу.",al={"навіщо красти грамоту","чому бандити хотіли грамоту","призначення грамоти дефіас"}},{q="Кому належить ця грамота?",a="Грамота законно належить Фермерові Теодору Фурлброу та його дружині Верні — двом вестфолським хуторянам, яких розбійники цькували, доки не вигнали з ферми.",al={"чия грамота фурлброу","хто такий фурлброу","чия це грамота"}},{q="Де знайти Фурлброу?",a="Подружжя можна знайти одразу на в'їзді до Вестфолу, при головному шляху з Лісу Елвінн: вони застрягли біля свого зламаного воза.",al={"де фурлброу","місце фермера фурлброу","куди повернути грамоту"}},{q="Навіщо Фурлброу грамота, якщо вони втекли?",a="Фурлброу визнають, що у Вестфолі стало надто небезпечно для чесних людей, але законний доказ власності — їхня єдина надія колись повернути свою землю, якщо настане мир.",al={"навіщо їм грамота","чи фурлброу повернуться"}}},fp="15,297,29.547.0,34.216.0,29.160.0,33.133.0,60.195.0"}
P.entries["item:furlbrow-s-pocket-watch"] = {n="Кишеньковий Годинник Фурлброу",s="«Кишеньковий Годинник Фурлброу» — дорога серцю родинна реліквія Фермера Фурлброу з Вестфолу. Цей годинник подарував йому батько дружини, Верни, у день їхнього весілля, і його довелося покинути в поспіху, коли розбійники Дефіасу захопили їхню гарбузову ферму.",h="«Кишеньковий Годинник Фурлброу» — дорога серцю родинна реліквія Фермера Фурлброу з Вестфолу.",kw={"кишеньковий годинник фурлброу","фермер фурлброу","верна фурлброу","бенні блаанко","реліквія","вестфол"},ang={["faction:Alliance"]="Допомога родині Фурлброу повернути втрачену реліквію — гірке нагадування про те, що корона Стормвінда геть не змогла вберегти працьовитих фермерів Вестфолу від організованого розбою."},sec={{t="Пам'ятка серед руїн",b="Коли головорізи Дефіасу заполонили Гарбузове Поле Фурлброу, Фермер Фурлброу та його дружина Верна мусили посеред ночі покинути свій дім. У шаленому поспіху фермер залишив дорогий кишеньковий годинник — весільний подарунок від тестя. Реліквія так і лишилася в шафі захопленого фермерського будинку, який стережуть горлорізи на чолі з Бенні Блаанко. Для подружжя, що тепер ночує край дороги, повернути годинник — означає зберегти одну з небагатьох речей із колишнього життя, яких ще не занапастили розбійники."}},faq={{q="Чому кишеньковий годинник такий важливий для Фермера Фурлброу?",a="Годинник подарував Фермерові Фурлброу батько Верни в день їхнього весілля. Утративши через Братство Дефіас землю, дім і засоби до життя, подружжя має тільки цю дорогу серцю річ.",al={"чому годинник фермеру фурлброу важливий","важливість годинника фурлброу","хто дав фурлброу годинник"}},{q="Де зберігається кишеньковий годинник?",a="Годинник лишився в шафі на хуторі Фурлброу, серед гарбузових полів на захід від головного шляху, де зараз застрягло подружжя.",al={"де кишеньковий годинник","місце шафи фурлброу","як знайти годинник"}},{q="Хто стереже годинник?",a="Покинутий хутір захопило Братство Дефіас — зокрема бандит Бенні Блаанко та його спільники, що вештаються біля самої шафи.",al={"хто має годинник фурлброу","охоронець годинника вестфолл","бенні бланко годинник"}},{q="Чи Дефіас просто вкрали годинник?",a="Ні. Коли бандити напали на гарбузове поле, Фурлброу тікали в такій паніці, що фермер просто забув узяти годинник. Він так і лишився схований у шафі в спальні, коли хутір захопили.",al={"чи дефіас пограбували годинник","чи годинник вкрали"}}},fp="23,242,23.580.0,56.223.0,31.166.0,26.159.0,40.200.0"}
P.entries["item:gaea-seed"] = {n="Насінина Ґеї",s="Насінини Ґеї — витривалі зернята рослин, які знаходять на березі Озера Міркфаллон у Горах Кам'яного Кігтя. Тауренські шамани дорожать ними й наповнюють їх стихійним благословенням, щоб відроджувати краї, спустошені війною й промислом.",h="Насінини Ґеї — витривалі зернята рослин, які знаходять на березі Озера Міркфаллон у Горах Кам'яного Кігтя.",kw={"насінина ґеї","озеро міркфаллон","таммра віндфілд","притулок сонячної скелі","земна мати","шамани"},ang={["class:Shaman"]="Насіння — практичне відновлення землі: воно показує, як шаманські обряди й благословення Земної Матері можуть пришвидшити природне зростання в пошкодженому краї.",["race:Tauren"]="Для тауренів Притулку Сонячної Скелі вирощування Насінин Ґеї — священний обов'язок відновити рівновагу землі, порушену чужими війнами й вирубкою лісу."},sec={{t="Посудини відродження",b="Насінини Ґеї походять із Гір Кам'яного Кігтя: їх викидає на берег чи вони самі ростуть довкола Озера Міркфаллон. Скромні на вигляд — схожі на маленькі волокнисті кокосові горіхи, — вони мають природну витривалість. Поки промислове визискування й війни шрамують Гори Кам'яного Кігтя, шамани бачать у цьому насінні важливий провідник для зцілення пораненої землі."},{t="Благословення Земної Матері",b="У Притулку Сонячної Скелі тауренська шаманка Таммра Віндфілд збирає Насінини Ґеї, щоб протидіяти руйнуванню, яке шириться вершинами. Традиційними співами й стихійними обрядами шамани наповнюють ці дрімотні лушпинки благословенням Земної Матері. Це духовне наповнення різко пришвидшує їхнє природне зростання й перетворює прості зернята на витривалі паростки, здатні вкоренитися в спаленій, безплідній землі на кшталт Обвугленої Долини."}},faq={{q="Де знайти Насінини Ґеї?",a="Насінини Ґеї розкидані вздовж берега Озера Міркфаллон, у горах на північ від Притулку Сонячної Скелі в Кам'яному Кігті.",al={"місце насінини ґеї","де знайти насінини ґеї","як отримати насінину ґеї"}},{q="Для чого потрібні Насінини Ґеї?",a="Таммра Віндфілд збирає їх у Притулку Сонячної Скелі для стихійного благословення. Наповнені шаманською силою, насінини повертають рослинне життя спустошеним місцям, як-от Обвугленій Долині.",al={"призначення насінини ґеї","навіщо збирати насінини ґеї","що таммра робить з насінинами"}},{q="Навіщо шаманам наповнювати насінини силою?",a="Подекуди в Кам'яному Кігті землю тяжко виснажили вогонь, війна й вирубка. Сила Земної Матері, спрямована в насінини, прискорює їхнє проростання й робить їх досить міцними, щоб рости у ворожому, зруйнованому ґрунті.",al={"навіщо благословляти насінини","магія шаманів насінини ґеї"}},{q="Який вигляд мають Насінини Ґеї?",a="Вони лежать біля самої води довкола Озера Міркфаллон і схожі на невеликі коричневі круглі лушпайки чи кокосові горіхи на березі.",al={"вигляд насінини ґеї","як помітити насінини ґеї"}}},fp="9,234,18.363.0,28.435.1,27.137.0,29.204.0,39.235.0,29.128.0"}
P.entries["item:gaffer-jack"] = {n="Електромуфта",s="Електромуфта — спеціальна інженерна деталь для тонкого механічного налаштування, наприклад стінтлових кілочків. Ящик таких деталей недбало впустив у хвилі біля берегів Обердайна ексцентричний гном-винахідник Візбанґ Кранктоґґл, коли плив через море.",h="Електромуфта — спеціальна інженерна деталь для тонкого механічного налаштування, наприклад стінтлових...",kw={"електромуфта","візбанґ кранктоґґл","обердайн","гноми","інженерія","рибальство"},ang={["profession:Engineering"]="Колеги-майстри зрозуміють, як прикро втратити фірмові деталі на кшталт електромуфт, без яких не відкалібрувати делікатні механізми, як-от стінтлові кілочки.",["race:Gnome"]="Проміняти метушню Айронфорджа на тихе життя в Обердайні — незвичний вибір для гнома, але впустити з корабля цілий ящик потрібних деталей, перебравши з випивкою, — цілком у гномському дусі."},sec={{t="Загублені в морі",b="Шукаючи тиші й спокою далеко від гуркотливих кузень і галасливих таверн Айронфорджа, гном-майстер Візбанґ Кранктоґґл сів на корабель до Обердайна. Добряче хильнувши під час морської подорожі, Візбанґ примудрився впустити за борт цілий ящик електромуфт. Ці маленькі механічні кріплення пішли на дно в імлистих прибережних водах Темного Узбережжя, і гном лишився без важливих деталей, потрібних, щоб налаштувати стінтлові кілочки."},{t="Скарби з дна",b="Оскільки електромуфти розсипалися в прибої вздовж берега, вони іноді чіпляються за гачки терплячих рибалок, що закидають вудки в прибережні води Темного Узбережжя. Повернувши ці загублені деталі, Візбанґ може складати свої дивовижні пристрої, хоча виловлювати дрібне металеве начиння з відкритого моря — справа надзвичайного терпіння й чистого везіння."}},faq={{q="Для чого потрібна Електромуфта?",a="За словами гнома-майстра Візбанґа Кранктоґґла, електромуфти — необхідні інженерні деталі, без яких не налаштувати штинтлові кілочки в його експериментальних винаходах.",al={"призначення електромуфти","що робить електромуфта","використання електромуфти"}},{q="Як вони опинилися в морі біля Обердайна?",a="Візбанґ Кранктоґґл відплив зі Східних Королівств, шукаючи тиші й спокою подалі від Айронфорджа. Дорогою він добряче перебрав і ненароком упустив ящик з електромуфтами за борт, у води Темного Узбережжя.",al={"чому електромуфти у воді","хто загубив електромуфти","загублена електромуфта"}},{q="Хто хоче повернути Електромуфти?",a="Візбанґ Кранктоґґл, ексцентричний гном-винахідник, що зупинився в портовому містечку Обердайн, — йому треба повернути вісім штук, щоб і далі будувати свої дивні винаходи.",al={"кому потрібні електромуфти","здати електромуфту","хто бере електромуфти"}},{q="Де знайти Електромуфти?",a="Вони лежать на морському дні вздовж берегів Темного Узбережжя, де рибалки часом випадково чіпляють їх, ловлячи рибу в прибої.",al={"де взяти електромуфти","як знайти електромуфти","місце електромуфти"}}},fp="11,291,11.493.0,14.379.0,31.165.0,51.233.0,33.161.0,32.143.0"}
P.entries["item:gallywix-s-head"] = {n="Голова Ґаллівікса",s="Голова Ґаллівікса — моторошний трофей, відтятий у Великого Наглядача Пузіка Ґаллівікса, що порядкував на об'єкті Венчурної Компанії біля Багнистого Болота в Пустках. Це страхітливий доказ страти, якого вимагає Розтрощена Рука — таємна спілка розбійників з осідком в Оргріммарі.",h="Голова Ґаллівікса — моторошний трофей, відтятий у Великого Наглядача Пузіка Ґаллівікса, що порядкував на...",kw={"голова ґаллівікса","пузік ґаллівікс","венчурна компанія","розтрощена рука","шентул","багнисте болото"},ang={["class:Rogue"]="Голова Ґаллівікса доводить смертоносну вправність розбійника в таємному проникненні, потайливості й прицільних убивствах на службі Розтрощеній Руці.",["faction:Horde"]="Усуваючи таких ватажків Венчурної Компанії, як Ґаллівікс, Орда стримує грабіжницькі промислові вторгнення, що загрожують кордонам Пусток і Дуротару."},sec={{t="Похмурий доказ розправи",b="Великий Наглядач Пузік Ґаллівікс керував роботами з вежі Венчурної Компанії на північ від Багнистого Болота. У відповідь на промислову загрозу, що підступала дедалі ближче, і на небезпечні суміші, які там варили, Розтрощена Рука відрядила агентів, щоб ущент знищити цей об'єкт. Голова Пузіка Ґаллівікса — незаперечний доказ для Шентула в Оргріммарі, що наглядача страчено, і вона зміцнює становище розбійника в гільдії."},{t="Вилазка на Багнисте Болото",b="Разом із наказом здобути голову Ґаллівікса агент отримує доручення повернути вкрадену схованку зміненої мікстури Занзіла й винищити отруєну обслугу вежі. Убивши Ґаллівікса на його сідалі й принісши голову до Тіньової Розколини, агенти підтверджують, що отруйні досліди Венчурної Компанії в Пустках зірвано."}},faq={{q="Чия це голова?",a="Голова належить Великому Наглядачеві Пузіку Ґаллівіксу — гоблінові, що керує роботами Венчурної Компанії в Багнистому Болоті на півночі Пусток.",al={"хто такий ґаллівікс","пузік ґаллівікс","походження голови ґаллівікса"}},{q="Кому потрібна Голова Ґаллівікса?",a="Трофей несуть Шентулу — наставникові розбійників і агентові Розтрощеної Руки в Тіньовій Розколині під Оргріммаром.",al={"кому віддати голову","здати голову ґаллівікса","голова для шентула"}},{q="Чому Розтрощена Рука хоче його смерті?",a="Пузік Ґаллівікс керував небезпечними роботами Венчурної Компанії, де експериментували зі Зміненою Мікстурою Занзіла. Розтрощена Рука прирекла його на смерть, щоб знешкодити місцеву промислову загрозу й заволодіти сумішшю.",al={"чому розтрощена рука хоче його смерті","причина вбивства ґаллівікса"}},{q="Де знайти Пузіка Ґаллівікса?",a="Він на самій верхівці вежі Венчурної Компанії, трохи на північ від Багнистого Болота на півночі Пусток.",al={"де ґаллівікс","місце ґаллівікса","бос вежі мулистого болота"}}},fp="15,275,27.437.0,24.349.1,19.150.0,26.140.0,42.211.0,32.119.0"}
P.entries["item:galvanized-horn"] = {n="Гальванований Ріг",s="Гальванований Ріг — затверділий наріст, який здобувають у грізних матріархів химер, що бродять випаленими скелями Калімдору. Майстри-бронярі обох фракцій дуже його цінують: цей міцний трофей — основний матеріал для особливих обладунків воїна.",h="Гальванований Ріг — затверділий наріст, який здобувають у грізних матріархів химер, що бродять випаленими...",kw={"гальванований ріг","химери","обвуглена долина","гори кам'яного кігтя","фурен лонґбірд","орм стоунгуф"},ang={["class:Warrior"]="Убити матріарха й здобути її гальванований ріг — випробування витривалості й сили, яке доводить вашу звитягу майстрам-бронярам Стормвінда чи Тандер Блафа.",["profession:Blacksmithing"]="Ріг показує, як органічні матеріали, загартовані в надзвичайних умовах, можуть зрівнятися з обробленим металом чи навіть перевершити його в підсиленні обладунків."},sec={{t="Трофей Обвугленої Долини",b="Химери — люті двоголові звірі, але старі матріархи, що нишпорять Обвугленою Долиною в Горах Кам'яного Кігтя, мають роги, які попіл, полум'я й боротьба за виживання загартували до незвичайної твердості. Роги звичайних пташенят крихкі й почорнілі, а ріг матріарха має природну загартовану міцність, схожу на оброблений метал. Цей ріг прагнуть здобути і дворфійський броняр Фурен Лонґбірд у Стормвінді, і Орм Стоунгуф у Тандер Блафі: вони вимагають його як випробування бойової звитяги й незамінний складник для видатної кольчуги."}},faq={{q="Звідки береться Гальванований Ріг?",a="Його знімають з матріархинь химер, що живуть в Обвугленій Долині на південному заході Гір Кам'яного Кігтя.",al={"де взяти гальванований ріг","як отримати гальванований ріг","дроп гальванованого рогу"}},{q="Чому ковалям потрібен саме цей ріг?",a="Майстри-зброярі цінують ріг за природну щільність і жаростійкість і зміцнюють ним особливі кольчуги й латні обладунки.",al={"навіщо гальванований ріг","використання гальванованого рогу"}},{q="Хто приймає Гальванований Ріг?",a="Для воїнів Альянсу ріг вимагає Фурен Лонґбірд у Стормвінді, щоб викувати загартований вогнем обладунок. Для воїнів Орди його шукає Орм Стоунгуф у Тандер Блафі — як доказ сили, щоб виготовити шолом воїна.",al={"хто приймає гальванований ріг","кому потрібен гальванований ріг"}},{q="Чим він відрізняється від звичайного Обвугленого Рогу?",a="Звичайні обвуглені роги легко зібрати з менших, молодих химер. Гальванований ріг дає лише доросла матріархиня — він має значно щільнішу, загартовану будову, придатну для майстерної ковальської роботи.",al={"обвуглений ріг чи гальванований","чи відрізняється від обвугленого рогу"}}},fp="15,282,26.561.0,39.131.0,38.150.0,32.208.0,47.215.0"}
P.entries["item:gargantuan-tumor"] = {n="Велетенська Пухлина",s="Велетенська Пухлина — величезний хворобливий наріст, вирваний зі споганеного деревляника Похмуродуба в Тельдрассилі. Це кричущий доказ неприродної хвороби, що розповзається серед створінь Озера Ал'Амет.",h="Велетенська Пухлина — величезний хворобливий наріст, вирваний зі споганеного деревляника Похмуродуба в...",kw={"велетенська пухлина","похмуродуб","деревляник","озеро ал'амет","скверна","тельдрассил","наріст"},ang={["class:Druid"]="Для друїдів, що прагнуть плекати молоде віття Тельдрассила, потворна пухлина — тривожне нагадування: природа у вітті небезпечно вразлива до скверни.",["race:NightElf"]="Бачити шанованого старійшину-деревляника, перетвореного на безумне, уражене чудовисько, — підкреслення дедалі більших негараздів довкілля, що спіткали новий дім калдореїв."},sec={{t="Пошесть над озером",b="Біля південного берега Озера Ал'Амет печера прихищає Похмуродуба — колись шляхетного старійшину деревляників, що став жертвою мерзенної недуги. Створіння було помітно отруєне величезним наростом, який спотворив його поведінку й просочував скверну в навколишню звірину. Відтяти цю потворну пухлину вкрай важливо не лише щоб покласти край мученицькому шалу звіра, а й щоб тутешні дослідники змогли оглянути пошесть і зрозуміти, як така огидна недуга вкоренилася у вітті новопосталого Світового Дерева."}},faq={{q="Звідки береться Велетенська Пухлина?",a="Пухлину знімають із Похмуродуба — великого зіпсованого деревляника, що живе в печері на південному березі Озера Ал'Амет на Тельдрассилі.",al={"джерело пухлини","як отримати велетенську пухлину","дроп похмуродуба"}},{q="Чому на Похмуродубі росте пухлина?",a="Це зовнішня ознака дивного зіпсуття, яке отруює деревляників і тварин довкола Озера Ал'Амет. Колись Похмуродуб був шанованим ватажком свого роду, але цілком піддався цьому лютому наростові.",al={"чому у похмуродуба пухлина","хвороба деревників","скверна озера аль'амет"}},{q="Хто хоче дослідити цю пухлину?",a="Пухлина потрібна дослідникам краю, щоб вивчити дивну гниль, яка вражає місцевих деревляників, і зрозуміти, як вилікувати чи спинити цю моровицю.",al={"хто бере пухлину","здати велетенську пухлину","здати завдання похмуродуба"}}},fp="16,222,20.499.0,42.141.0,48.207.0,30.152.0"}
P.entries["item:garrick-s-head"] = {n="Голова Ґарріка",s="Голова Ґарріка — відтята голова Ґаррика Педфута, сумнозвісного горлоріза, що орудував біля виноградників Долини Нортширу. Вона слугує моторошним доказом смерті, потрібним, щоб отримати винагороду, оголошену владою Абатства Нортшира.",h="Голова Ґарріка — відтята голова Ґаррика Педфута, сумнозвісного горлоріза, що орудував біля виноградників...",kw={"голова ґарріка","ґаррик педфут","бандит","винагорода","нортшир","помічник віллем"},ang={["class:Rogue"]="Усунення Педфута показує тутешнім головорізам, що на недисципліноване бандитство неодмінно відповідять смертоносніші, фаховіші клинки.",["race:Human"]="Голова Педфута — один із перших рішучих ударів, яких молодий новобранець Стормвінда завдає беззаконню, що розповзається Лісом Елвінн."},sec={{t="Кінець бандита",b="Тижнями Ґаррик Педфут і його зграя головорізів тероризували тутешніх фермерів і крамарів по всій Долині Нортширу. Скориставшись тим, що оборона Королівства Стормвінд розтягнута до межі, Ґаррик засів у халупі біля нортширських виноградників, грабуючи проїжджих торговців. Поки тутешню варту скували кобольди, що насуваються, та бандити Дефіас, Помічник Віллем оголосив винагороду за голову Педфута, шукаючи заповзятливого шукача пригод, який усуне розбійника й надасть незаперечний доказ його загибелі."}},faq={{q="Хто такий Ґаррик Педфут?",a="Ґаррик Педфут — лиходій-головоріз, що тероризував фермерів, виноградарів і мандрівних торговців Долини Нортширу. Він облаштував невелику схованку з ватагою головорізів на схід від Абатства Нортшира, за річкою.",al={"хто такий ґаррик","історія ґаррика педфута","ким був педфут"}},{q="Навіщо для винагороди потрібна відтята голова?",a="Прикордонне правосуддя в Лісі Елвінн вимагає незаперечного доказу. Помічник Віллем і влада Нортширу хочуть мати речовий доказ смерті Ґаррика, перш ніж виплатити винагороду.",al={"навіщо його голова","доказ смерті","чому брати голову ґаррика"}},{q="Де ховався Ґаррик Педфут?",a="Педфут отаборився біля невеликої дерев'яної халупи на схід від Абатства Нортшира, за мостом через річку, неподалік нортширських виноградників.",al={"де ґаррик","місце халупи ґаррика","де знайти ґаррика педфута"}},{q="Хто платить винагороду за голову Ґаррика?",a="Помічник Віллем, що стоїть просто біля входу до Абатства Нортшира, оголосив винагороду й виплачує її, отримавши голову.",al={"хто хоче голову ґаррика","здати голову ґаррика","хто здав голову ґаррика"}}},fp="14,229,14.485.0,24.222.0,51.190.0,33.139.0,39.130.0"}
P.entries["item:gazlowe-s-ledger"] = {n="Гросбух Ґазлоу",s="Гросбух Ґазлоу — докладний облік товарів і запасів, який веде гоблінський бос Раджета. Це рахункова книга, за якою звіряють вантажі з Буті Бей із портовою декларацією.",h="Гросбух Ґазлоу — докладний облік товарів і запасів, який веде гоблінський бос Раджета.",kw={"гросбух ґазлоу","ґазлоу","раджет","діззівіг","флібустьєри південних морів","торгівля"},ang={["class:Rogue"]="Приватний торговий гросбух гоблінського боса дає цікаву змогу зазирнути в потоки контрабанди, цінного ввезення й піратства на узбережжі Пусток.",["faction:Horde"]="Раджет — нейтральний порт, відкритий для торгівлі з Ордою; допомагаючи Ґазлоу вистежувати викрадені вантажі, ви зберігаєте добрі стосунки з місцевою владою картелю Стімвідл."},sec={{t="Торгові записи Раджета",b="Щоб керувати таким жвавим торговим портом, як Раджет, потрібен ретельний облік. Ґазлоу веде цей особистий гросбух, щоб стежити за ввезеними скринями, вантажами на вивіз і запасами на складах. Коли довгоочікуваний вантаж із Буті Бей кудись зникає, Ґазлоу звіряє за книгою очікувані запаси з морськими записами, які веде на пристанях Начальник Пристані Діззівіг."},{t="Як розкрили крадіжку",b="Порівнявши записи гросбуха з портовими журналами Діззівіга, гобліни пересвідчуються, що вантаж так і не дійшов до портового складу. Розбіжність підтверджує підозри Ґазлоу: зниклі скрині не зійшли з води цілими, і все вказує просто на Флібустьєрів Південних морів, що діють на сусідньому Узбережжі Крамарів."}},faq={{q="Що таке Гросбух Ґазлоу?",a="Це особиста облікова книга Ґазлоу із записами про товари, які мають прибути й зберігаються в Раджеті. Коли вантажі не надходять, Ґазлоу посилає її на пристань, щоб звірити з портовими записами.",al={"гросбух ґазлоу","гросбух рятчета","книга обліку ґазлоу"}},{q="Хто має перевірити гросбух?",a="Начальник Пристані Діззівіг, що відає доками Раджета, звіряє гросбух зі своїми журналами перевезень, щоб з'ясувати, чи товар загубили, чи його взагалі не розвантажували.",al={"кому віднести гросбух","одержувач гросбуха","гросбух діззівіґа"}},{q="Якого вантажу бракує в гросбуху?",a="Ґазлоу чекав звичайної поставки товарів із Буті Бей. Діззівіг підозрює, що найбільше Ґазлоу хвилюється через зниклу пару чобіт від Дріззлека.",al={"чого бракує ґазлоу","зниклий вантаж"}},{q="Що стається після перевірки гросбуха?",a="Коли Діззівіг пересвідчується, що вантаж через доки не проходив, гросбух повертають Ґазлоу — схоже, вантаж перехопили в морі пірати-Флібустьєри Південного Моря.",al={"що буде з гросбухом","після перевірки діззівіґа"}}},fp="16,220,28.388.0,20.351.1,25.199.0,32.175.0,37.163.0,41.188.1"}
P.entries["item:gem-of-anacondra"] = {n="Самоцвіт Анакондри",s="Самоцвіт Анакондри — один із чотирьох самоцвітів сну, які мають спотворені змієві ватажки в Печерах Стогонів. Його носить Леді Анакондра, і він стає відчутним доказом її поразки й того, що поширення Жахіття над Пустками приборкано.",h="Самоцвіт Анакондри — один із чотирьох самоцвітів сну, які мають спотворені змієві ватажки в Печерах Стогонів.",kw={"самоцвіт анакондри","леді анакондра","друїди ікла","печери стогонів","нара вайлдмейн","смарагдове жахіття"},ang={["class:Druid"]="Для кенарійських друїдів здобути цей самоцвіт — скорботний обов'язок: повалити сестру, яка віддала свій розум і подобу на поталу спотворювальному Смарагдовому Жахіттю.",["race:Tauren"]="Здобутий самоцвіт прямо допомагає Нарі Вайлдмейн із Тандер Блафа, розвіюючи темні видіння, що отруюють сон шу'гало на Узвишші Старійшин."},sec={{t="Спотворений осередок",b="Коли Наралекс поринув у глибокий сон, щоб повернути воду й життя посушливим Пусткам, Смарагдове Жахіття вдерлося в його думки й спотворило найближчих учнів. Леді Анакондра та її спільники зреклися давніх звичаїв і стали Друїдами Ікла, обернувши благородну мету відродження на отруйне марення. Самоцвіт Анакондри — один із чотирьох самоцвітів сну, які носять ці змієподібні ватажки: він зосереджує їхній спотворений зв'язок зі Смарагдовим Сном і тримає жахіття в мережі печер."},{t="Очищення видіння",b="Нара Вайлдмейн і коло кенарійських друїдів у Тандер Блафі виявили, що їхній сон теж отруюють видіння й лиховісні обличчя ватажків Ікла. Здобути Самоцвіт Анакондри — разом із каменями Кобрана, Пайтаса й Серпентіса — потрібно, щоб підтвердити, що Леді Анакондру повалено, і зняти гнітюче жахіття з розуму тих, хто береже рівновагу Калімдору."}},faq={{q="Що таке Самоцвіт Анакондри?",a="Це самоцвіт сну, який носить Леді Анакондра — одна з чотирьох ватажків спотворених Друїдів Ікла, що засіли в Печерах Стогонів.",al={"що таке самоцвіт анакондри","самоцвіт анакондри","що робить самоцвіт анакондри"}},{q="Кому потрібен цей самоцвіт?",a="Нара Вайлдмейн, друїдка-таурен з Узвишшя Старійшин у Тандер Блафі, шукає його разом із трьома іншими самоцвітами сну, щоб звільнити свій розум від жахіть і захистити Пустки.",al={"кому потрібен самоцвіт анакондри","куди здати самоцвіт анакондри","здати самоцвіт анакондри"}},{q="Де знайти Самоцвіт Анакондри?",a="Самоцвіт носить Леді Анакондра, яка ховається в покручених підземних тунелях Печер Стогонів у центрі Пусток.",al={"де він падає","хто дропає самоцвіт анакондри","місце леді анакондри"}},{q="Чому самоцвіти сну такі важливі?",a="Чотири самоцвіти тримають зіпсовані ватажки Друїдів Ікла. Зібрані самоцвіти засвідчують, що проводирів знищено, а отже, їхня влада над зіпсуттям Смарагдового Сну в краї зламана.",al={"чому чотири самоцвіти","призначення самоцвітів сну","самоцвіти вожаків ікла"}}},fp="16,241,17.531.0,20.388.1,29.139.0,19.183.0,40.149.0,33.205.0"}
P.entries["item:gem-of-cobrahn"] = {n="Самоцвіт Кобрана",s="Самоцвіт Кобрана — самоцвіт сну, який носить Лорд Кобран, один зі спотворених ватажків Друїдів Ікла в Печерах Стогонів. Він водночас і осередок його спотвореної мрії, і речовий доказ, потрібний Нарі Вайлдмейн, щоб підтвердити його поразку.",h="Самоцвіт Кобрана — самоцвіт сну, який носить Лорд Кобран, один зі спотворених ватажків Друїдів Ікла в Печерах...",kw={"самоцвіт кобрана","лорд кобран","друїди ікла","печери стогонів","нара вайлдмейн","наралекс"},ang={["class:Druid"]="Для кенарійських друїдів повернення Самоцвіту Кобрана — трагічний, але неминучий кінець полеглого брата, який проміняв гармонію природи на Смарагдове Жахіття.",["race:Tauren"]="Друїди Тандер Блафа пильно стежать за Пустками; здобутий самоцвіт Кобрана прямо оберігає рівнини й мисливські угіддя від неприродної скверни."},sec={{t="Осередок спотворених снів",b="Коли друїд із нічних ельфів Наралекс увійшов у Смарагдовий Сон, щоб відродити безплідні рівнини Калімдору, його кошмар спотворив і Печери Стогонів, і його учнів. Серед них був Кобран, що зрікся мирних звичаїв Кола Кенарія й прийняв подобу змії. Лорд Кобран носить один із чотирьох самоцвітів сну, що тримають владу ватажків над підземними водами, і спрямовує крізь нього спотворені сни, які загрожують обернути Пустки на отруйне болото."},{t="Відновлення рівноваги",b="У Тандер Блафі друїдку-тауренку Нару Вайлдмейн мучать кошмари, які насилають свавільні Друїди Ікла. Щоб очистити підземні джерела й уберегти Калімдор від їхнього видіння, шукачі пригод мають спуститися в печери, убити Лорда Кобрана разом із трьома його спільниками й забрати їхні самоцвіти сну. Повернутий кенарійським друїдам самоцвіт Кобрана кладе край його спотворювальному впливу на сплячого Наралекса."}},faq={{q="Що таке Самоцвіт Кобрана?",a="Це самоцвіт сну, який тримає Лорд Кобран — занепалий друїд, що очолює Друїдів Ікла в Печерах Стогонів. Самоцвіт спрямовує його силу, спотворену жахіттям.",al={"самоцвіт кобрана","самоцвіт кобрана що це","що таке самоцвіт кобрана"}},{q="Кому потрібен Самоцвіт Кобрана?",a="Нара Вайлдмейн, друїдка-таурен з Узвишшя Старійшин у Тандер Блафі, просить цей самоцвіт разом із трьома іншими, щоб покласти край Друїдам Ікла.",al={"кому потрібен самоцвіт кобрана","здати самоцвіт кобрана","хто бере самоцвіт кобрана"}},{q="Скільки самоцвітів потрібно для завдання?",a="Потрібно чотири: Самоцвіт Кобрана, Самоцвіт Анакондри, Самоцвіт Пітаса й Самоцвіт Серпентіса — кожен тримає один із чотирьох зміїних ватажків у печерах.",al={"скільки самоцвітів сну","самоцвіти вожаків ікла","усі самоцвіти ікла"}},{q="Хто такий Лорд Кобран?",a="Лорд Кобран колись був учнем Архідруїда Наралекса. Коли видіння Наралекса обернулося жахіттям, Кобран та кілька інших друїдів прийняли подобу змія й утворили Друїдів Ікла.",al={"хто такий кобран","історія лорда кобрана","кобран"}}},fp="14,256,27.491.0,17.430.1,27.170.0,29.155.0,47.171.0,20.202.0"}
P.entries["item:gem-of-pythas"] = {n="Самоцвіт Пітаса",s="Цей самоцвіт сну — один із чотирьох спотворених самоцвітів, які носять ватажки Друїдів Ікла в Печерах Стогонів. Його тримає Лорд Пайтас, і камінь живить жахіття, що спотворює підземну оазу й загрожує Пусткам.",h="Цей самоцвіт сну — один із чотирьох спотворених самоцвітів, які носять ватажки Друїдів Ікла в Печерах...",kw={"самоцвіт пітаса","лорд пайтас","друїди ікла","печери стогонів","наралекс","смарагдове жахіття"},ang={["class:Druid"]="Для кенарійських друїдів здобути самоцвіт — скорботний обов'язок, адже він уособлює цілковите падіння найближчого кола Наралекса, що обернулося на змієподібних страховиськ.",["race:Tauren"]="Спотворені обряди в печерах загрожують тендітній рівновазі Пусток, тож повернути ці самоцвіти конче потрібно, щоб захистити батьківщину шаманів і друїдів."},sec={{t="Посудина Жахіття",b="Коли Наралекс увійшов у Смарагдовий Сон, щоб відродити посушливі Пустки, його благородне видіння обернулося на живе жахіття. Разом із ним упали і його найперші послідовники: вони назвалися Друїдами Ікла й прагнуть переробити світ на поверхні на отруйні джунглі. Лорд Пайтас носить цей резонансний камінь — один із чотирьох самоцвітів сну, що тримають скверну в печерах. Самоцвіт — провідник їхнього темного задуму й доказ для друїдів Тандер Блафа, що спотворений транс Пайтаса нарешті перервано."}},faq={{q="Для чого потрібен Самоцвіт Пітаса?",a="Самоцвіт приносять Нарі Вайлдмейн у Тандер Блаф разом із самоцвітами Кобрана, Анакондри й Серпентіса. Разом вони завершують завдання покласти край ватажкам-ренегатам Друїдів Ікла.",al={"використання самоцвіту пітаса","що робити з самоцвітом пітаса","завдання самоцвіту пітаса"}},{q="Хто носить цей самоцвіт?",a="Його тримає Лорд Пайтас — занепалий друїд із нічних ельфів, що засів глибоко в Печерах Стогонів у Пустках.",al={"хто дропає самоцвіт пітаса","місце пітаса","де взяти самоцвіт пітаса"}},{q="Навіщо друїдам Тандер Блафа цей самоцвіт?",a="Нару Вайлдмейн і кенарійських друїдів у Тандер Блафі переслідує скверна, що йде з Печер Стогонів. Зібрані самоцвіти доводять, що чотирьох збочених ватажків убито, — і жахіття вже не просочується далі в Пустки.",al={"чому нара хоче самоцвіти","нара вайлдмейн пітас"}},{q="Чи є інші такі самоцвіти?",a="Так. Лорд Пайтас — один із чотирьох ватажків. Інші — Леді Анакондра, Лорд Кобран і Лорд Серпентіс — теж мають кожен свій самоцвіт сну глибоко в печері.",al={"інші самоцвіти сну","самоцвіти ікла","самоцвіти голосних печер"}}},fp="13,235,25.518.0,35.209.0,21.111.0,48.259.0,35.159.0"}
P.entries["item:gem-of-serpentis"] = {n="Самоцвіт Серпентіса",s="Самоцвіт Серпентіса — самоцвіт сну, який носить Лорд Серпентіс, самопроголошений очільник Друїдів Ікла в Печерах Стогонів. Він — головний провідник спотвореного жахіття, що змінює мережу печер і загрожує Пусткам.",h="Самоцвіт Серпентіса — самоцвіт сну, який носить Лорд Серпентіс, самопроголошений очільник Друїдів Ікла в...",kw={"самоцвіт серпентіса","лорд серпентіс","друїди ікла","печери стогонів","нара вайлдмейн","самоцвіти сну"},ang={["class:Druid"]="Самоцвіти сну, які носять Серпентіс і його кліка, показують страшну небезпеку глибокого трансу єднання зі Сном без пильної духовної дисципліни.",["race:Tauren"]="Вирвавши цей самоцвіт із рук Серпентіса, ви допомагаєте звільнити шаманів і друїдів Тандер Блафа від темних видінь, що тривожать їхній сон по всьому Малгору."},sec={{t="Серце зміїного сну",b="Коли сон Наралекса в Печерах Стогонів скорився Смарагдовому Жахіттю, його найвідданіших послідовників спотворило на фанатичних Друїдів Ікла. На вершині цієї кліки стоїть Лорд Серпентіс. Як і троє його змієподібних поплічників, Серпентіс носить зачарований самоцвіт сну, що прив'язує їхню спільну волю до спотвореного видіння. Здобутий самоцвіт ламає владу Серпентіса над природою печер і б'є просто по проводу, що керує поширенням скверни Пустками."},{t="Доказ для Тандер Блафа",b="Друїди-таурени на Узвишші Старійшин у Тандер Блафі, а надто Нара Вайлдмейн, бачать яскраві кошмари через скверну, що причаїлася під саваною. Самоцвіт Серпентіса разом із самоцвітами Кобрана, Анакондри й Пайтаса — відчутний доказ того, що призвідці свавільного ордену впали, і хватка жахіття на Колі Кенарія в Малгорі слабшає."}},faq={{q="Звідки береться Самоцвіт Серпентіса?",a="Самоцвіт носить Лорд Серпентіс, ватажок Друїдів Ікла, що живе глибоко серед покручених водних протоків Печер Стогонів.",al={"хто дропає самоцвіт серпентіса","де взяти самоцвіт серпентіса","місце самоцвіту серпентіса"}},{q="Яке призначення самоцвіту?",a="Це один із чотирьох самоцвітів-осередків, крізь які ватажки Друїдів Ікла спрямовують жахіття, що спотворює підземну оазу. Нара Вайлдмейн у Тандер Блафі шукає його як доказ, що Лорда Серпентіса переможено.",al={"навіщо мені самоцвіт серпентіса","для чого самоцвіт серпентіса"}},{q="Кому потрібні всі чотири самоцвіти сну?",a="Нара Вайлдмейн, друїдка з Узвишшя Старійшин у Тандер Блафі, просить шукачів пригод принести їй самоцвіти Кобрана, Анакондри, Пітаса й Серпентіса, щоб розірвати владу жахіття над краєм.",al={"хто бере самоцвіти","здати самоцвіт серпентіса","здати вожаків ікла"}},{q="Ким був Лорд Серпентіс до того, як отримав цей самоцвіт?",a="Спершу він був учнем Наралекса й прийшов у печери, щоб повернути Пусткам буйне життя, але Смарагдове Жахіття перетворило його шляхетні прагнення на фанатичне бажання переробити світ на зміїну подобу.",al={"історія лорда серпентіса","хто такий серпентіс"}}},fp="16,246,29.518.0,23.375.1,42.145.0,31.226.0,30.199.0,48.227.0"}
P.entries["item:gerenzo-s-mechanical-arm"] = {n="Механічна Рука Ґерензо",s="Механічна Рука Ґерензо — прищеплений протез, знятий з інженера-відщепенця Ґерензо Ренчвісла в Горах Кам'яного Кігтя. Для гоблінських агентів, що прагнуть позбутися конкурентів, це безпомилковий доказ його загибелі.",h="Механічна Рука Ґерензо — прищеплений протез, знятий з інженера-відщепенця Ґерензо Ренчвісла в Горах Кам'яного...",kw={"механічна рука ґерензо","ґерензо ренчвісл","зіз фіззікс","озеро скельної заводі","гноми","гобліни","інженерія"},ang={["profession:Engineering"]="Рука показує протилежність двох інженерних традицій: гноми охоче жертвують власним тілом заради механічної точності, а гобліни воліють зовнішні прибудови й грубу вогневу міць.",["race:Gnome"]="Ґерензо — похмура крайність гномської винахідливості: він заніс механічну заміну далеко за межі звичайних медичних протезів, у моторошне самовдосконалення."},sec={{t="Химерний винахід",b="Ґерензо Ренчвісл довів самовдосконалення до потворної крайності, прищеплюючи дзижчливі шестерні й метал просто до свого кволого тіла. Гном-ренегат, що засів над Озером Скельної Заводі, замінив природні кінцівки мудрованою механікою. Коли гоблінський винахідник Зіз Фіззікс хоче позбутися Ґерензо, щоб вразити начальство, ця характерна механічна рука — єдиний трофей, досить особливий, щоб стати незаперечним доказом смерті інженера."},{t="Гномська філософія, гоблінська критика",b="Для гоблінського розуму відтяти цілком справну руку лише для того, щоб приладнати механічну заміну, — безглуздя. Зіз Фіззікс якось влучно зауважив, що справжній гоблінський інженер просто лишив би обидві живі руки й приладнав третю, механічну. Попри цей філософський розкол, відтята кінцівка задовольняє Спаттервалва й допомагає Зізові домогтися призначення в Ґаджетзан чи Андермайн."}},faq={{q="Звідки береться Механічна Рука Ґерензо?",a="Її забирають у Ґерензо Ренчвісла, що керує вирубкою й інженерними роботами високо над Озером Скельної Заводі, біля водяного колеса в Горах Кам'яного Кігтя.",al={"хто дропає руку ґерензо","місце руки ґерензо","де взяти механічну руку ґерензо"}},{q="Навіщо Зізу Фіззіксу ця рука?",a="Зізові потрібен безперечний доказ для свого начальника, Спаттервалва, що Ґерензо мертвий. Ґерензо сильно переробив власне тіло, тож його унікальний протез неможливо підробити чи сплутати з чиїмось іншим.",al={"чому зізу рука","здати руку","доказ смерті ґерензо"}},{q="Чому Ґерензо замінив собі руку?",a="За словами Зіза Фіззікса, плоть Ґерензо, схоже, гнила. З відчаю чи з одержимості гномськими експериментами Ґерензо приточував до себе механізми й замінював немічні кінцівки механічними.",al={"чому ґерензо кіборг","ґерензо гниле тіло","чому механічна рука"}}},fp="24,238,19.444.0,35.412.1,46.162.0,35.205.0,36.217.0"}
P.entries["item:ghost-hair-comb"] = {n="Гребінець з Примарного Волосся",s="Гребінець з Примарного Волосся — моторошний гребінець, у якому заплуталися примарні пасма духа Сліпої Мері. Надісланий привидові Мадам Євою, він стає знаряддям трагічного прозріння, а зібране з нього волосся згодом спрядуть у дивовижну нитку.",h="Гребінець з Примарного Волосся — моторошний гребінець, у якому заплуталися примарні пасма духа Сліпої Мері.",kw={"гребінець з примарного волосся","сліпа мері","мадам єва","даркшир","привид","кравецтво"},ang={["class:Priest"]="Болісна реакція Мері на гребінець відбиває земну марнославність і глибокі душевні муки, що не відпускають неспокійних мерців Сутінколісся.",["profession:Tailoring"]="Ефірні пасма з гребінця — незвичайна сировина для тканини: її не стригли з овець і не мотали з шовкопрядів, а спряли просто з примарної печалі."},sec={{t="Трагічна марнославність",b="Мадам Єва з Даркшира посилає гребінець духові Сліпої Мері, що живе в самотній напівзруйнованій хаті на околиці Сутінколісся. Побачивши гребінець, привид відсахується в жаху: Мері раптом усвідомлює гірку правду — вона вже не та вродлива жива жінка, якою була колись. У горі й розпачі вона відштовхує гребінець, і в ньому лишаються пасма її примарного волосся."},{t="Спрядене з печалі",b="Коли гребінець повертається до Мадам Єви в Даркшир, волосся між його зубцями слугує значно таємничішій меті. Єва збирає ці тонкі примарні волокна, щоб спрясти з них Нитку з Примарного Волосся — містичний матеріал, яким зшивають і скріплюють окультні витвори в похмурому краї Сутінколісся."}},faq={{q="Що таке Гребінець з Примарного Волосся?",a="Це гребінець, який Мадам Єва з Даркшира надсилає духові Сліпої Мері. Коли Мері ним скористається чи відкине, на ньому лишаються пасма її примарного волосся, і Єва пряде з них Нитку з Примарного Волосся.",al={"гребінець з примарного волосся","що це за гребінець","гребінець єви"}},{q="Чому Сліпа Мері кричить і відкидає гребінець?",a="Гребінець нагадує Сліпій Мері про втрачену смертну красу. Отримавши його, вона мусить побачити свою справжню природу — жахливу примарну потвору, а не ту вродливу жінку, якою пам'ятає себе за життя.",al={"чому сліпа мері кричить","реакція сліпої мері на гребінець","чому мері кинула гребінець"}},{q="Кому треба повернути гребінець?",a="Мадам Єва, місцева ворожка й сільська чарівниця з Даркшира, просить принести гребінець назад, щоб зібрати застрягле в ньому примарне волосся.",al={"кому віддати гребінець","хто хоче гребінець","куди нести гребінець"}},{q="Для чого примарне волосся?",a="Мадам Єва пряде з примарних пасом, зібраних із гребінця, Нитку з Примарного Волосся — незвичний реагент для окультних обрядів і ремесел у Сутінколіссі.",al={"для чого примарне волосся","що таке нитка примарного волосся","призначення нитки примарного волосся"}}},fp="15,247,15.431.0,16.300.1,28.194.0,47.202.0,28.167.0,32.157.0"}
P.entries["item:ghost-hair-thread"] = {n="Нитка з Примарного Волосся",s="Нитка з Примарного Волосся — рідкісний надприродний матеріал, який пряде Мадам Єва в Даркширі. Кажуть, вона наділена потужними окультними властивостями: скріплює духовні сили й навіть може вшити життя в неживі речі. Відлюдник Аберкромбі просить її нібито для того, щоб захистити свою напівзруйновану хижу від неспокійних привидів.",h="Нитка з Примарного Волосся — рідкісний надприродний матеріал, який пряде Мадам Єва в Даркширі.",kw={"нитка з примарного волосся","мадам єва","аберкромбі","даркшир","цвинтар воронячого пагорба","кравецтво"},ang={["class:Warlock"]="Здатність нитки скріплювати духовні сутності й наділяти неживу матерію життям нагадує темні мистецтва маніпуляції душами й прив'язування створінь.",["profession:Tailoring"]="Звичайні кравці працюють із вовною, шовком і магічною тканиною, а примарна нитка Мадам Єви доводить, що матерію можна спрясти просто з надприродних сутностей — і вона втримуватиме чари."},sec={{t="Спрядена зі світу духів",b="Нитка з Примарного Волосся, яку пряде ворожка Мадам Єва в Даркширі, — далеко не звичайне кравецьке приладдя. За словами Єви, примарна нитка має найрізноманітніші окультні властивості: від приборкання лихих духів до вшивання життєвої сили в неживі предмети. Ефірна природа робить її цінною для обрядів і оберегів у проклятому краї Сутінколісся."},{t="Оберіг Аберкромбі",b="Відлюдник Аберкромбі, що живе в благенькій хижі на північ від Цвинтаря Воронячого Пагорба, просить подорожніх принести йому нитку з Даркшира. Він запевняє, що конче мусить натягнути її на вікна й одвірок, щоб блукаюча нежить із цвинтаря не вдерлася до його дому. Та з огляду на дивну здатність нитки вшивати життя в неживу матерію, справжнє її призначення лишається тривожною загадкою."}},faq={{q="Що таке Нитка з Примарного Волосся?",a="Це магічний матеріал для ремесла, який пряде Мадам Єва в Даркширі. Він має особливі окультні властивості: ним можна прив'язувати духів або вшивати життя в неживі речі.",al={"примарне волосся","що таке нитка з примарного волосся","примарна нитка"}},{q="Навіщо Аберкромбі Нитка з Примарного Волосся?",a="Аберкромбі запевняє, що нитка потрібна йому, щоб обшити вікна й двері, — створити захисний бар'єр від неспокійних духів, що блукають надворі біля Цвинтаря Воронячого Пагорба.",al={"нитка аберкромбі","навіщо аберкромбі нитка","підопічний аберкромбі"}},{q="Хто робить нитку?",a="Нитку на прохання виготовляє Мадам Єва — місцева ворожка й провидиця з Даркшира.",al={"хто пряде нитку примарного волосся","нитка мадам єви"}},{q="Чи можна використати нитку в кравецтві?",a="Ні. Попри назву й чарівні властивості, це особливий предмет завдання, призначений лише для доставки Аберкромбі, і в звичайних рецептах ремесла його не використати.",al={"нитка примарного волосся кравецтво","чи можна крафтити з нитки"}}},fp="17,313,24.380.0,18.431.1,26.167.0,44.178.0,21.110.0,41.166.0"}
P.entries["item:ghoul-fang"] = {n="Ікло Гуля",s="Ікла Гуля — моторошні трофеї, здобуті з нежиті, що нишпорить зараженими гаями й цвинтарями Сутінколісся. У Даркширі віщунка Мадам Єва використовує їх як необхідні складники для захисних талісманів, що бережуть подорожніх від темряви, яка підступає.",h="Ікла Гуля — моторошні трофеї, здобуті з нежиті, що нишпорить зараженими гаями й цвинтарями Сутінколісся.",kw={"ікло гуля","гулі","мадам єва","тотем покари","даркшир","сутінколісся"},ang={["faction:Alliance"]="Для шукачів пригод з Альянсу, що допомагають обложеному Даркширу, ці ікла — спосіб обернути жахіття Сутінколісся на знаряддя виживання проти скверни, що підступає й так нагадує Погибель."},sec={{t="Трофеї неспокійних мерців",b="Похмурий ліс Сутінколісся кишить ненажерливою нежиттю — від трупоїдів, що чатують біля могил, до зотлілих мерців, які бродять лісом. Вирвати ікло в цих потвор — і моторошна робота, і доказ того, що мисливець вистояв проти ненажерливих мерців, які загрожують кордонам Даркшира."},{t="Окультні реагенти",b="Мадам Єва, ворожка й містикиня Даркшира, бачить жахливі знамення над кожним, хто наважиться ступити в Сутінколісся. Вона поєднує приховану некротичну силу іклів гулів із пальцями кістяків і павучою отрутою, щоб зачарувати Тотем Покари, — так темні сили лісу обертаються на захисний амулет від жорстокого нападу."}},faq={{q="Де знайти Ікла Гуля?",a="Їх збирають із різних гулів по всьому Сутінколіссі — розносників чуми, мозкоїдів, кістогризів, смердючих трупів, гнилих і плотоїдів, що никають цвинтарями й самотніми стежками.",al={"де падають ікла гуля","хто дропає ікла гуля","місце іклів гуля"}},{q="Кому потрібні Ікла Гуля?",a="Вони потрібні Мадам Єві, провидиці з Даркшира, для обряду, що створює захисний оберіг — Тотем Покари.",al={"кому потрібні ікла гуля","здати ікла гуля","завдання мадам єви"}},{q="Навіщо вони Мадам Єві?",a="Єва відчуває, що мандрівникам загрожує небезпека, і разом із пальцями скелетів та павучою отрутою зачаровує ікла в захисний тотем, що карає кожного, хто вдарить його власника.",al={"навіщо ікла гуля","матеріали тотема страждання","що мадам єва робить з іклами"}}},fp="10,263,29.285.0,15.364.0,31.211.0,22.140.0,30.175.0"}
P.entries["item:ghoul-rib"] = {n="Ребро Гуля",s="Ребра Гуля здобувають із нежиті, що нишпорить проклятими гаями й цвинтарями Сутінколісся. Відлюдник Аберкромбі запевняє, що вони потрібні йому як матеріал для потворного опудала, яке відганятиме трупоїдних страховиськ від його хижі.",h="Ребра Гуля здобувають із нежиті, що нишпорить проклятими гаями й цвинтарями Сутінколісся.",kw={"ребро гуля","гулі","аберкромбі","цвинтар воронячого пагорба","сутінколісся","нежить"},ang={["class:Paladin"]="Торкатися осквернених кісток неспокійних мерців гидко, але допомога самотньому відлюдникові проти ненажерливих потвор — це та сама справа захисту живих від жахіть Сутінколісся.",["class:Priest"]="Спотворене оживлення, що скріплює ці кістки, свідчить про глибоку тінь, яка лягла на Сутінколісся й обернула загиблих селян на ненажерливих трупоїдів."},sec={{t="Моторошний оберіг",b="Проклятий ліс Сутінколісся кишить лютою нежиттю, зокрема ненажерливими гулями — трупоїдами, кістогризами, мозкоїдами, гнилими мерцями й розносниками чуми. Аберкромбі, дивакуватий відлюдник, що живе сам-один у хижі на північ від Цвинтаря Воронячого Пагорба, просить перехожих принести ці міцні зотлілі кістки. Він каже, що живе поза захистом Нічної Варти Даркшира, тож беззахисний, а страхітлива фігура з ребер гулів, наче опудало на городі, відлякуватиме зграї мерців."},{t="Підозри довкола хижі",b="Збирати частини вбитої нежиті — звична справа для виживання у ворожих краях, але особливе захоплення Аберкромбі анатомією гулів викликає подив. Замість того щоб шукати прихистку за частоколом Даркшира чи покластися на освячені обереги, відлюдник наполягає на тому, щоб зміцнити свою відлюдну оселю сирими некромантськими нутрощами."}},faq={{q="Які істоти носять Ребра Гуля?",a="Їх можна добути з різних гулів по всьому Сутінколіссі — плотоїдів, кістогризів, мозкоїдів, гнилих і розносників чуми. Ці потвори никають старими цвинтарями, руїнами при дорогах і покинутими хуторами по всьому лісі.",al={"де падають ребра гуля","які гулі мають ребра","джерела ребер гуля"}},{q="Навіщо Аберкромбі ці кістки?",a="Аберкромбі каже, що живе надто далеко від Даркшира, щоб покладатися на захист Нічної Варти. Йому потрібні ребра, щоб змайструвати грубе опудало чи бовдура, яке відлякуватиме блукаючу нежить від його стін.",al={"навіщо аберкромбі ребра","призначення опудала гулів","що аберкромбі робить з ребрами"}},{q="Чи справді опудала відганяють гулів?",a="Нежить зазвичай не знає страху: нею керує безтямний голод або темний некромантський примус. Дивно думати, що безмозкі гулі тікатимуть від опудала з кісток, але Аберкромбі наполягає, що воно вбереже його дім.",al={"чи опудала відганяють гулів","чи опудала лякають нежить","чи гулі бояться опудал"}},{q="Де халупа Аберкромбі?",a="Аберкромбі живе в напіврозваленій халупі на заході Сутінколісся, трохи на північ від Цвинтаря Воронячого Пагорба.",al={"місце аберкромбі","де відлюдник","куди здати ребра гуля"}}},fp="9,237,15.545.0,27.334.1,32.255.0,38.206.0,40.237.0,37.95.0"}
P.entries["item:giant-crocolisk-skin"] = {n="Шкіра Велетенського Кроколіска",s="Шкіри велетенських кроколісків — цупкі шкури, здобуті з величезних плазунів, що живуть у болотах Багнокраю. Ремісники Гавані Менетіл високо цінують їх для шкірництва, але здобувати їх — небезпечна робота, яка скалічила вже не одного необачного мисливця.",h="Шкіри велетенських кроколісків — цупкі шкури, здобуті з величезних плазунів, що живуть у болотах Багнокраю.",kw={"шкіра велетенського кроколіска","кроколіски","джеймс галлоран","гавань менетіл","шкірництво","багнокрай"},ang={["class:Hunter"]="Вистежувати велетенських кроколісків уздовж туманного узбережжя — випробування для мисливця: чи вміє він полювати на водяних звірів і не дати затягти себе під болотяну воду."},sec={{t="Небезпечне ремесло",b="Болота й протоки Багнокраю — дім для величезних кроколісків, чиї шкури такі щільні, що не піддаються вогкій болотяній гнилі. У Гавані Менетіл майстри на кшталт Джеймса Галлорана покладаються на постійні поставки шкур, щоб шити міцні шкіряні вироби. Та щоб зняти шкуру з дорослого велетенського кроколіска, доводиться лізти в глибокі води й долати лютих болотяних хижаків, тож кожна здобута шкура дається нелегко."},{t="Нерозважливість учня",b="Спершу добувати ці цупкі шкури мав юний учень Галлорана. Не маючи бойової вправності, щоб повалити дорослих болотяних звірів, хлопець потрапив у засідку на північному узбережжі. Покалічений велетенськими кроколісками, він тепер лежить під опікою місцевої повитухи, і та каже, що він, може, ще й видужає. Через цей напад Галлоранові довелося найняти досвідчених шукачів пригод, щоб вистежити хижаків і здобути потрібні шкури."}},faq={{q="Для чого потрібні Шкіри Велетенського Кроколіска?",a="Їх скуповує Джеймс Галлоран, ремісник із Гавані Менетіл, що цінує грубі шкури за те, що з них виходять міцні шкіряні вироби, здатні витримати вогкий клімат боліт.",al={"використання шкір велетенського кроколіска","навіщо збирати шкіри велетенського кроколіска","навіщо шкури галлорану"}},{q="Де водяться кроколіски, з яких знімають ці шкури?",a="Велетенські кроколіски Багнокраю никають узбережжям і болотяними водами на північ від Гавані Менетіл, у мілинах за місцевими поселеннями мурлоків.",al={"де велетенські кроколіски","де знайти велетенських кроколісків","болота узбережжя кроколісків"}},{q="Що сталося з учнем Галлорана?",a="Галлоран послав свого учня на болота самого по шкури. На учня напали велетенські кроколіски й так його покалічили, що тепер він лежить під наглядом менетілської повитухи, — вона каже, що він, може, й виживе.",al={"учень поранений","учень галлорана","хто втратив ногу"}},{q="Чим ці шкури відрізняються від шкур молодих кроколісків?",a="Молоді кроколіски дають тонші, м'якші шкури. Дорослі велетенські кроколіски мають значно цупкіші й товщі шкури, але, щоб убити такого, потрібна неабияка бойова вправність.",al={"молоді й велетенські кроколіски шкіра","різниця шкіри кроколісків"}}},fp="20,242,17.419.0,22.411.1,40.181.0,56.149.0,39.226.0,52.163.0"}
P.entries["item:gloom-weed"] = {n="Похмура Трава",s="Похмура Трава — хирлява рослина, що росте на ураженому ґрунті Галявин Тірісфалю, здебільшого на полях між Похоронним Подзвоном і Бріллом. Найбільше вона відома як не та рослина, яку збирає Ґордо — незграбна почвара Відступників, що плутає її з алхімічним реагентом, травою-згубою.",h="Похмура Трава — хирлява рослина, що росте на ураженому ґрунті Галявин Тірісфалю, здебільшого на полях між...",kw={"похмура трава","ґордо","почвара","трава-згуба","брілл","похоронний подзвін","травництво"},ang={["profession:Herbalism"]="Навчені травники відчувають цю рослину за допомогою Пошуку трав, тож помітити її в тінистому підліску Тірісфалю значно легше.",["race:Undead"]="Для нових Відступників, що покидають Похоронний Подзвін, принести Похмуру Траву — швидкий урок про вади праці почвар і їдкий норов алхіміків Андерсіті."},sec={{t="Помилковий урожай",b="Проростаючи серед мороку й розкладу Галявин Тірісфалю, Похмура Трава буяє на перелогах на захід від Брілла — там, де на обрії видніє Хутір Соллідена. Попри зловісну назву, рослина доволі нешкідлива й позбавлена потужного алхімічного ефекту, який цінує Королівське Аптекарське Товариство. Своєю славою вона завдячує почварі Ґордо, що блукає дорогою й намагається висмикувати бур'яни своїми величезними незграбними руками. Хибно зрозумівши наказ господаря, Ґордо знай збирає Похмуру Траву й підбиває довірливих мандрівників носити її оберемками майстрові Голланду на цвинтар Брілла — на превелике роздратування аптекаря."}},faq={{q="Для чого потрібна Похмура Трава?",a="Для алхіміків-Відступників вона майже нічого не варта. Її збирають лише тому, що гидота Ґордо плутає її з травою загибелі, яку насправді просив його господар.",al={"використання похмурої трави","що робить похмура трава","кому потрібна похмура трава"}},{q="Де росте Похмура Трава?",a="Вона росте полями Галявин Тірісфалю між Бріллом і Похоронним Подзвоном — особливо вздовж дороги та на луках на схід від Хутора Соллідена.",al={"де знайти похмуру траву","місце похмурої трави","місця похмурої трави"}},{q="Хто такий Ґордо й чому він її збирає?",a="Ґордо — гидота, яку Майстер Голланд послав збирати реагенти. Його зшиті руки надто незграбні, а розум простий, тож він блукає дорогами, рве не ті рослини й благає перехожих допомогти.",al={"хто такий ґордо","чому ґордо збирає бур'ян","ґордо потвора"}},{q="Чого насправді хотів Майстер Голланд?",a="Майстрові Голланду потрібна трава загибелі для дослідів на цвинтарі Брілла. Отримавши Похмуру Траву, він глузує з помилки й посилає мандрівників зібрати те, що йому справді потрібно.",al={"майстер голланд бур'ян","що потрібно голланду","смертний бур'ян чи похмура трава"}}},fp="10,278,18.640.0,28.177.0,27.164.0,38.220.0,38.181.0"}
P.entries["item:glowing-ember"] = {n="Сяйливий Жар",s="Сяйливий Жар — тліюче стихійне осердя, здобуте з переможеного Малого Прояву Вогню на скелях Дуротару. Це важливий обрядовий реагент у випробуваннях шамана, яким розпалюють жаровню в Святилищі Вічного Полум'я.",h="Сяйливий Жар — тліюче стихійне осердя, здобуте з переможеного Малого Прояву Вогню на скелях Дуротару.",kw={"сяйливий жар","вогонь","прояв вогню","шаман","святилище","смолоскип","дуротар"},ang={["class:Shaman"]="Здобуття цього палаючого осердя — визначальний обряд переходу, що змушує посвячуваного випробувати свою рішучість проти живого вогню, перш ніж наказувати його тотему."},sec={{t="Осердя полум'я",b="Коли майбутній шаман випиває вогняну сапту і стає перед вогняними духами на хребті біля Телфа Джулама, він зустрічає Малий Прояв Вогню. Після перемоги над елементалем цей тліючий залишок — усе, що лишається від його тілесної форми. Жар, що досі пульсує сирим стихійним теплом, несе живу іскру вогню, потрібну, щоб пробудити священну жаровню в Святилищі Вічного Полум'я."},{t="Запалення смолоскипа",b="Покладений у холодну чашу гірської жаровні, Сяйливий Жар спалахує раптовим білим полум'ям. Живлячись рештками переможеного елементаля, жаровня дає посвячуваному запалити Смолоскип Сплячого Полум'я, замкнувши норовливу сутність вогню в посудину, яку можна знести з гори на доказ влади над стихіями."}},faq={{q="Звідки береться Сяйливий Жар?",a="Жар забирають з решток Малого Прояву Вогню — ворожого елементаля, що трапляється на вершині над Святилищем Вічного Полум'я в Дуротарі.",al={"як отримати сяйливий жар","дроп сяйливого жару","де взяти сяйливий жар"}},{q="Для чого потрібен жар?",a="Новачки кладуть жар у металеву жаровню Святилища Вічного Полум'я. Він дає сильне, ритмічне полум'я, від якого запалюють обрядовий Смолоскип Сплячого Полум'я.",al={"що робить сяйливий жар","використання сяйливого жару","жар у жаровні"}},{q="Чому шаманам, щоб здобути його, потрібна вогняна сапта?",a="Духи стихій на вершині гори живуть поза звичайним зором смертних. Випита вогняна сапта налаштовує чуття шамана на царство стихій і відкриває Малий Прояв Вогню, щоб йому можна було кинути виклик.",al={"чому потрібна сапта","не бачу вогняного елементаля","вогняна сапта жар"}},{q="Хто посилає шаманів по цей жар?",a="Самітник Телф Джулам, що живе серед скель Дуротару, варить вогняну сапту й веде новачків-шаманів через випробування — перемогу над духом полум'я.",al={"хто дає завдання","жар телфа джулама","видавець завдання поклик вогню"}}},fp="13,250,17.396.0,18.366.1,39.165.0,27.176.0,49.217.0,39.155.0"}
P.entries["item:glowing-fruit"] = {n="Сяйливий Плід",s="Сяйливий Плід — екзотичний світний зразок, що росте серед дивного листя на вітті Тельдрассила. Його неприродне сяйво й химерна взаємодія з ґрунтом Світового Дерева роблять його предметом нагального ботанічного вивчення для природознавців.",h="Сяйливий Плід — екзотичний світний зразок, що росте серед дивного листя на вітті Тельдрассила.",kw={"сяйливий плід","деналан","озеро ал'амет","ботаніка","тельдрассил","насіння","ґрунт"},ang={["class:Druid"]="Для друїдів, настроєних на крихку рівновагу Тельдрассила, чужа рослинність, що непередбачувано реагує на ґрунт, — можливе збурення для зростаючого Світового Дерева.",["profession:Herbalism"]="Травники одразу завважать: дивне світіння плоду вказує на екзотичну, потужну взаємодію між чужоземним насінням і зачарованим ґрунтом."},sec={{t="Цікавий зразок",b="Знайдений під незвичним листям на Тельдрассилі, цей великий круглий плід випромінює безпомильне світло. Ботанік Деналан біля Озера Ал'Амет упізнає в ньому чужинця для Світового Дерева й припускає, що його насіння прибуло з далеких земель за морем. Хай яке його походження, плід дивно реагує на багатий, зачарований ґрунт Тельдрассила і показує, наскільки молода світова гілка вразлива до чужої й непередбачуваної рослинності."}},faq={{q="Що таке Сяйливий Плід?",a="Це екзотичний круглий плід, що виріс під незвичайним листям на Тельдрассилі. Він випромінює неземне сяйво й, схоже, незвично прореагував із місцевим ґрунтом.",al={"сяйливий плід тельдрассил","що це за плід","дивний плід завдання"}},{q="Звідки взявся цей плід?",a="За словами природознавця Деналана, плід не з Тельдрассила. Він підозрює, що насіння занесло чи привезло з-за моря — можливо, зі Східних Королівств Азероту, — і воно пустило тут коріння.",al={"звідки плід","звідки насіння","чи він місцевий"}},{q="Хто хоче оглянути Сяйливий Плід?",a="Деналан, дослідник із нічних ельфів біля Озера Ал'Амет, вивчає гілки й живу природу Тельдрассила. Його надзвичайно цікавлять чужинські рослини, що прореагували із землею Світового Дерева.",al={"кому потрібен плід","куди нести сяйливий плід","плід денелана"}}},fp="13,250,18.441.0,26.168.0,31.228.0,39.200.0"}
P.entries["item:glowing-gem"] = {n="Сяйливий Самоцвіт",s="Сяйливий Самоцвіт — зачарований камінь, здобутий у таборах мурлоків на водах Ашенвалю. Колись його шукав загиблий розвідник Тероніс; камінь — важлива складова, без якої не відновити чарівний жезл, створений Дартолом.",h="Сяйливий Самоцвіт — зачарований камінь, здобутий у таборах мурлоків на водах Ашенвалю.",kw={"сяйливий самоцвіт","тероніс","жезл дартола","мурлоки","озеро ірисів","шаель'дрін"},ang={["class:Druid"]="Друїдів цікавлять дослідження Тероніса про порчу, що поширюється, і реліквія, яку він сподівався відновити.",["race:NightElf"]="Повернувши самоцвіт і завершивши справу Тероніса, ви допоможете вартовим ушанувати загиблого розвідника й захистити Ашенваль від порчі, що ширшає."},sec={{t="Загублена реліквія Дартола",b="Сяйливий Самоцвіт, знайдений у агресивних мурлоків, що живуть біля Озера Ірисів, сповнений прихованої магічної сили. Юний нічний ельф Тероніс вирушив з Астранаару на його пошуки, сподіваючись зібрати знаряддя, здатне відкинути порчу, що просочується лісами Ашенвалю. Тероніс передчасно загинув біля озера, але сам камінь уцілів серед прибережних мурлоків-збирачів."},{t="Відновлення жезла",b="Коли камінь знаходять разом зі щоденником Тероніса, ватажок вартових Рейн Вульфраннер просить віднести його на північний схід до Шаель'дрін — дріади, що чатує біля сусіднього місячного колодязя. Дріада володіє прадавнім знанням, потрібним, щоб поєднати Сяйливий Самоцвіт з іншими втраченими частинами жезла, створеного Дартолом, — і праця загиблого розвідника не пропаде марно."}},faq={{q="Звідки береться Сяйливий Самоцвіт?",a="Самоцвіт носять мурлоки, що никають берегами й мілинами довкола Озера Ірисів у центрі Ашенвалю.",al={"місце сяйливого самоцвіту","хто дропає сяйливий самоцвіт","де взяти сяйливий самоцвіт"}},{q="Чому Тероніс шукав цей самоцвіт?",a="Тероніс шукав способів очистити дедалі більшу скверну Ашенвалю. За його дослідженнями, саме цей самоцвіт — одна з головних частин, потрібних, щоб відновити чарівний жезл, який колись створив Дартол.",al={"завдання тероніса","чому тероніс хотів самоцвіт","призначення самоцвіту"}},{q="Кому віднести Сяйливий Самоцвіт?",a="Показавши камінь і щоденник Тероніса Рейн Вульфраннер в Астранаарі, віднесіть Сяйливий Самоцвіт на північний схід — дріаді Шаель'дрін до місячного колодязя на схід від Озера Ірисів.",al={"кому потрібен сяйливий самоцвіт","здати сяйливий самоцвіт","що робити із самоцвітом"}},{q="Що таке жезл Дартола?",a="Це чарівне знаряддя, яке створив Дартол. Його частини розкидано по всьому лісі, і, щоб відтворити жезл, потрібен Сяйливий Самоцвіт.",al={"що таке жезл дартола","жезл дартола","що зробив дартол"}}},fp="11,235,22.428.0,17.368.1,37.111.0,37.201.0,37.169.0,26.138.0"}
P.entries["item:glowing-soul-gem"] = {n="Сяйливий Самоцвіт Душі",s="Сяйливий Самоцвіт Душі — темний обрядовий артефакт, який носять посланці Культу Темного Берега на півночі Ашенвалю. Наповнений тіньовим чаклунством, камінь ув'язнює дух нічого не підозрюючої жертви, щоб живити зловісні справи культу.",h="Сяйливий Самоцвіт Душі — темний обрядовий артефакт, який носять посланці Культу Темного Берега на півночі...",kw={"сяйливий самоцвіт душі","культ темного берега","делґрен очищувач","пост маестри","руїни ордил'аран","ашенваль"},ang={["class:Priest"]="Жерці, дивлячись на самоцвіт душі, відчувають муку ув'язненого в ньому духа й розуміють, що артефакт треба негайно очистити, а душу — відпустити на спочинок.",["class:Warlock"]="Чорнокнижники як ніхто знають мистецтво ув'язнювати духів у каменях душі, тож у самоцвіті Темного Берега вони впізнають грубішу, некромантську похідну маніпуляцій душами."},sec={{t="Посудина темного чаклунства",b="На північний схід від Посту Маестри, у затінених Руїнах Ордил'Аран, члени Культу Темного Берега чаклують під пильним оком своїх тіньових господарів. Їхні посланці носять Сяйливі Самоцвіти Душі — зачаровані вмістища, що ловлять і мучать душі мертвих. Це не просто прикраси: камені служать провідниками магічної енергії й прив'язують поневолених духів, змушуючи їх служити темним цілям культу."},{t="Таємниці Ордил'Арана",b="Прагнучи підірвати вплив Темного Берега на півночі Калімдору, Делґрен Очищувач на Посту Маестри досліджує ці артефакти. Розгадавши чари, вплетені в Сяйливий Самоцвіт Душі, можна побачити не лише темні тайні формули, а й ув'язнену душу, що волає зсередини каменя, — і викрити зловісні досліди, які пов'язують культистів Ашенвалю з їхньою ріднею у Вежі Альталакса."}},faq={{q="Що таке Сяйливий Самоцвіт Душі?",a="Це зачарований камінь душ, яким користується Культ Темного Берега. Насичений тіньовою магією, він ув'язнює духів, щоб черпати їхню сутність і живити мерзенне чаклунство культу.",al={"що таке самоцвіт душі","самоцвіт душі темне узбережжя","історія сяйливого самоцвіту душі"}},{q="Звідки береться цей самоцвіт душі?",a="Його носять члени Культу Темного Берега — культисти, вбивці, вишибали й адепти, — що орудують у руїнах Ордил'Арана на півночі Ашенвалю.",al={"хто дропає самоцвіт душі","місце сяйливого самоцвіту душі","самоцвіт орділ'арана"}},{q="Кому потрібен цей самоцвіт і навіщо?",a="Самоцвіт шукає Делґрен Очищувач із Посту Маестри. Він вважає, що, розгадавши чари самоцвіту, з'ясує приховане джерело сили культу й дізнається, що той замислює.",al={"самоцвіт душі делґрена","чому делґрен хоче самоцвіт душі","самоцвіт душі маестра"}},{q="Що стається, коли самоцвіт розгадано?",a="Розплутані чари самоцвіту вивільняють ув'язненого в ньому привида — змучена душа здобуває свободу, а викривлені глибини обрядів Темного Берега виходять на світло.",al={"що всередині самоцвіту душі","привид у самоцвіті душі"}}},fp="16,239,24.434.0,25.404.1,29.174.0,35.182.0,32.192.0,45.167.1"}
P.entries["item:glutton-shackle"] = {n="Кайдани Ненажери",s="Кайдани Ненажери — зачаровані пута, які носять воргени Ненажери Мунрейджів у Срібноліссі. Виготовлені божевільним архімагом Аруґалом, ці обручі спрямовують магію, що підпирає його недолугі чари й підтримує його прокляті вовчі створіння.",h="Кайдани Ненажери — зачаровані пута, які носять воргени Ненажери Мунрейджів у Срібноліссі.",kw={"кайдани ненажери","ненажера мунрейджів","воргени","архімаг аруґал","далар донвівер","срібнолісся"},ang={["class:Mage"]="Маги оцінять уїдливу критику Далара Донвівера щодо недбалих прийомів Аруґала: підпирати фізичними зачарованими милицями прості чари перетворення й виклику — ознака посереднього чародійства.",["race:Undead"]="Агенти-Відступники вважають збирання цих кайданів важливим кроком до того, щоб знешкодити загрозу воргенів, яка підступає просто до меж Гробниці."},sec={{t="Милиця для слабких чарів",b="Для вишколених магів-Відступників дикі воргени, що заполонили Срібнолісся, — не просто люті потвори, а доказ грубого чарівного невігластва. Далар Донвівер, знаний чародій, що служить у Гробниці, не має до Архімага Аруґала нічого, крім зневаги, і вважає його нездарою, негідним Кірін-Тору. Донвівер з'ясував, що Аруґал покладався на зачаровані реліквії, щоб надолужити крихкість своїх чарів. Кайдани Ненажери, які носять важкі Ненажери Мунрейджів, що блукають північним Срібноліссям, правлять за магічні якорі, які зміцнюють прокляття, що тримає звірів."},{t="Паливо для протидії Відступників",b="Аруґал вплів сирі чари просто в ці важкі залізні обручі, тож вони зберігають залишкову магічну енергію навіть після загибелі своїх носіїв. Донвівер вимагає ці кайдани від агентів-Відступників, щоб дослідити їхню будову й викачати їхні магічні запаси. Аналізуючи грубі чари, вкладені в метал, Відступники сподіваються розгадати таємниці прокляття воргенів і влаштувати падіння приборкувача звірів, що окопався у Фортеці Шадовфенг."}},faq={{q="Що таке Кайдани Ненажери?",a="Кайдани Ненажери — зачаровані залізні пута, які носять воргени — Ненажери Мунрейджів у Срібноліссі. Їх створив Архімаг Аруґал: ці обручі магічно підсилюють своїх носіїв, щоб підперти його недосконалі чари.",al={"що таке кайдани ненажери","історія кайданів ненажери","кайдани воргенів"}},{q="Навіщо Далару Донвіверу Кайдани Ненажери?",a="Далару Донвіверу потрібні кайдани, щоб вивчити грубі чари Аруґала й висотати з них залишкову магічну енергію. Зрозумівши, якими предметами Аруґал утримував своїх звірів, Відступники зможуть краще протидіяти його магії.",al={"навіщо збирати кайдани","завдання далара донвівера","кайдани для склепу"}},{q="Хто робить ці кайдани?",a="Їх зачарував Архімаг Аруґал — колишній чарівник Даларана, що викликав воргенів на боротьбу з Погибеллю, а зрештою збожеволів і прив'язав свої створіння до власної волі магічними дрібничками.",al={"хто зробив кайдани","кайдани аруґала","звідки кайдани"}},{q="Де знайти істот, що носять ці кайдани?",a="Ненажери Мунрейджів блукають лісами й покинутими хуторами в центрі та на півночі Срібнолісся, часто ватагами разом з іншими зіпсованими воргенами Мунрейджів.",al={"де з'являються ненажери","ненажери мунрейдж","кайдани воргенів сільверпайну"}}},fp="15,238,25.593.0,33.466.1,26.221.0,48.227.0,25.198.0,53.166.0"}
P.entries["item:glyph-of-azora"] = {n="Гліф Азори",s="Гліф Азори — таємний пристрій стеження, створений чарівником Теокрітусом у Вежі Азори. Прив'язані до ясновидної сили Ока Азори, ці різьблені камені дають магові змогу зазирати крізь відстані й проникати в думки своїх ворогів.",h="Гліф Азори — таємний пристрій стеження, створений чарівником Теокрітусом у Вежі Азори.",kw={"гліф азори","теокрітус","вежа азори","морґант","ясновидіння","редрідж"},ang={["class:Mage"]="Гліф Азори показує практичне таємне ворожіння, розширюючи звичайне кришталеве ясновидіння до цілеспрямованої телепатії та передачі відчуттів на відстані.",["faction:Alliance"]="Гліфи дають важливі відомості про ворожі пересування в Редріджі: вони стежать за чаклуном-відступником Морґантом і гарнізоном орків Блекрок в Кам'яній Варті."},sec={{t="Очі за кордоном",b="Зі своєї вежі в Лісі Елвінн чарівник Теокрітус невтомно стежить за ворожими силами, що загрожують королівству. Його кришталева реліквія, Око Азори, дає змогу бачити на великі відстані, та їй бракує сили проникати глибше — у розум і задуми супротивників. Щоб подолати це обмеження, Теокрітус створює мініатюрні осередки, відомі як Гліфи Азори. Прикріплений до поверхні у віддаленому місці, гліф стає якорем для його магії: він дозволяє не лише читати наміри ворога, а й переносити голос на милі, щоб говорити просто з польовими агентами."},{t="Шпигунство в Редріджі",b="Теокрітус розміщує ці гліфи просто на ворожій території в Горах Редріджу. Перший кріплять до давньої статуї лева над Вежею Ілґалара — твердинею його суперника-відступника, темного чарівника Морґанта. Проникнувши в розум Морґанта, Теокрітус виявляє несподівану сварку між магом-ренегатом і орками Блекрок, що зайняли сусідню Фортецю Кам'яної Варти. Другий гліф несуть на висоту вцілілої сторожової вежі фортеці, сховавши в покинутому глечику з-під трунку, щоб з'ясувати, чому Морґант і загарбники ворогують."}},faq={{q="Для чого Гліф Азори?",a="Це магічний ретранслятор, який створив Теокрітус. Його Око Азори дає змогу бачити здалеку, а встановлений Гліф Азори стає точкою прив'язки: через нього Теокрітус може читати думки й майбутні задуми своїх супротивників, а також передавати свій голос далеким союзникам.",al={"що робить гліф азори","навіщо гліф азори","призначення гліфа азори"}},{q="Хто створив Гліф Азори?",a="Його створив Теокрітус — могутній маг, що живе у Вежі Азори на східній околиці Лісу Елвінн.",al={"хто створив гліф","творець гліфа азори","гліф теокрітуса"}},{q="Де встановлюють Гліфи Азори?",a="Один гліф закладають у підніжжя вивітреної статуї лева над Вежею Ілґалара. Другий таємно проносять на верхню сторожову вежу Фортеці Кам'яної Варти й ховають у порожньому глеку з-під трунку, щоб шпигувати за орками Блекрок.",al={"де поставити гліф","місця гліфів","куди йде гліф"}},{q="Чому Теокрітус шпигує за Вежею Ілґалара?",a="У Вежі Ілґалара засів Морґант — небезпечний чаклун-ренегат і запеклий суперник Теокрітуса. Теокрітус використовує гліф, щоб викрити задуми Морґанта, перш ніж той обрушить на край темну магію.",al={"чому шпигувати за морґантом","теокрітус ілґалар","ворожнеча з морґантом"}},{q="Як гліф дає Теокрітусові змогу говорити з людьми?",a="Гліф безпосередньо пов'язаний із магічною енергією Вежі Азори. Закріплений на поверхні, він відкриває двобічний канал, крізь який Теокрітус передає свій безтілесний голос просто з каменю.",al={"говіркий гліф","голос теокрітуса в гліфі","чи гліф може говорити"}}},fp="14,256,22.588.0,21.554.1,42.286.0,31.126.0,37.237.0,49.210.0,55.218.0"}
P.entries["item:glyphic-letter"] = {n="Гліфічний Лист",s="Гліфічний Лист — офіційне послання з таємним знаком Келдена Бремена, наставника магів в Абатстві Нортшира. Його вручають перспективним новачкам після перших послуг гарнізону, і він велить майбутнім магам піднятися нагору й зустрітися із суворою дійсністю вивчення таємної магії.",h="Гліфічний Лист — офіційне послання з таємним знаком Келдена Бремена, наставника магів в Абатстві Нортшира.",kw={"гліфічний лист","келден бремен","маг","абатство нортшира","таємна магія","наставник"},ang={["class:Mage"]="Це позначене послання знаменує ваше офіційне посвячення в таємні традиції Альянсу й кличе вас нагору навчатися в Келдена Бремена.",["race:Human"]="Абатство Нортшира за історію королівства прихистило багатьох учнів таємної магії, і цей виклик починає вашу службу магічним дисциплінам Стормвінда."},sec={{t="Виклик до таємної магії",b="Запечатаний особистим знаком наставника магів Келдена Бремена, Гліфічний Лист вручають учням-чарівникам, щойно вони доведуть свою дисципліну в Долині Нортширу. Лист — офіційне запрошення відійти від простих польових обов'язків і розпочати справжнє магічне навчання в абатстві. Бремен використовує цей виклик, щоб виміряти рішучість учня й пересвідчитися, що кожен, хто береться за таємну магію, цілком готовий зустріти небезпечні сили, невблаганну прискіпливість і тягар, який несе володіння сирою магічною силою."}},faq={{q="Що таке Гліфічний Лист?",a="Це виклик із настановою, який написав і запечатав Келден Бремен — місцевий наставник магів в Абатстві Нортшира. Лист велить молодим магам-людям знайти його в горішніх покоях абатства, щоб почати справжнє навчання магії.",al={"що це за лист","предмет гліфічний лист","лист келдена"}},{q="Хто надсилає Гліфічний Лист?",a="Лист запечатано знаком Келдена Бремена, наставника магів в Абатстві Нортшира. Його вручає командування гарнізону, коли учень доведе свою вправність у боротьбі з довколишньою звіриною.",al={"хто це написав","хто дав мені гліфічний лист","відправник листа"}},{q="Куди віднести Гліфічний Лист?",a="Віднесіть його в Абатство Нортшира. Увійдіть через головний вхід за Маршалом Макбрайдом, поверніть у лівий коридор, підніміться сходами й пошукайте задню кімнату, де Келден Бремен навчає магії.",al={"куди йти","де келден бремен","місце келдена"}},{q="Навіщо Келден кличе молодих магів?",a="Келден хоче перевірити вашу рішучість. Як він застерігає на перших уроках, шлях таємної магії викликає і страх, і повагу, бо кидає виклик могутнім силам, — і йому треба знати, що його учні мають досить волі, щоб витримати таку долю.",al={"чому келден хоче мене","чому вчитель магів","чого хоче келден"}}},fp="14,294,23.545.0,27.225.0,29.220.0,35.215.0,38.253.0"}
P.entries["item:glyphic-memorandum"] = {n="Гліфічний Меморандум",s="Гліфічний Меморандум — письмове повідомлення, яке вручають магам-новачкам, що прибувають до Долини Холодного Хребта. Написаний від імені наставника магів Марріка Нуррібіта, він скеровує заклиначів-початківців під дах, щоб розпочати офіційне навчання таємним мистецтвам.",h="Гліфічний Меморандум — письмове повідомлення, яке вручають магам-новачкам, що прибувають до Долини Холодного...",kw={"гліфічний меморандум","маг","маррік нуррібіт","анвілмар","долина холодного хребта","навчання","гноми"},ang={["class:Mage"]="Для магів-початківців, що мандрують Дун Мороґом, ця записка — офіційний початок учнівства в таємних мистецтвах під проводом Марріка Нуррібіта.",["race:Gnome"]="Гномам-магам, що починають шлях у вигнанні, наставник нагадує: зосередьтеся на навчанні й тримайтеся подалі від утраченої батьківщини — Гномреґану."},sec={{t="Виклик до Анвілмара",b="Заклиначі-новачки, що вирушають у лютий мороз Долини Холодного Хребта, отримують це коротке послання, впоравшись із першими дорученнями. Меморандум, складений місцевим наставником магів Марріком Нуррібітом, кличе молодих практиків у тепло Анвілмара. Замість суворої академічної догми настанови Марріка невимушені й прямі: вчіть закляття, відкладайте монети на навчання й корчемний ель та тримайтеся якнайдалі від опроміненої руїни Гномреґану."}},faq={{q="Що таке Гліфічний Меморандум?",a="Це коротке письмове запрошення для магів, що щойно прибули в Долину Холодного Хребта: воно велить знайти місцевого наставника магії в Анвілмарі.",al={"гліфічний меморандум","записка мага","що таке гліфічний меморандум"}},{q="Хто написав цей меморандум?",a="Записку надіслав Маррік Нуррібіт — гном, наставник магів у залах Анвілмара в Дун Мороґу.",al={"хто це написав","хто надіслав меморандум","автор записки"}},{q="Яку пораду дає наставник, коли отримує меморандум?",a="Отримавши записку, Маррік нагадує новачкові стримуватися, відкладати гроші на заклинання й корчемний ель і нізащо не потикатися в радіоактивні зали Гномреґана.",al={"порада маррика","що каже маррик"}}},fp="18,236,21.465.0,31.153.0,26.116.0,64.168.0"}
P.entries["item:glyphic-scroll"] = {n="Гліфічний Сувій",s="Гліфічний Сувій — виклик, що його вручають щойно піднятим магам Відступників у Похоронному Подзвоні. Скріплений печаткою Ізабелли, місцевої наставниці таємної магії, він кличе чародіїв-початківців до оскверненої церкви — відточувати своє ремесло в нежитті.",h="Гліфічний Сувій — виклик, що його вручають щойно піднятим магам Відступників у Похоронному Подзвоні.",kw={"гліфічний сувій","маг","ізабелла","похоронний подзвін","таємна магія","відступники"},ang={["class:Mage"]="Сувій — перший офіційний виклик, який одержує маг Відступників; він наголошує, що нежиття не звільняє чародія від згубної залежності від таємної магії.",["race:Undead"]="Для Відступників повернуте знання таємної магії — не просто наука: це неодмінна зброя, щоб відстояти свій суверенітет і проти Погибелі, і проти живих ворогів."},sec={{t="Виклик із церкви",b="Коли щойно пробуджений маг Відступників повертається з проріджування безтямної Погибелі на цвинтарі Похоронного Подзвону, на нього чекає це запечатане послання. Написаний під знаком Ізабелли, місцевої наставниці магів, сувій кличе одержувача до зруйнованого парафіяльного святилища. Для щойно піднятих магів це перше знайомство з дисципліною таємної магії під стягом Відступників — нагадування, що смерть, може, і звільнила їх від смертної слабкості, та згубні спокуси магічної сили лишаються такими ж невідступними, як і завжди."}},faq={{q="Що таке Гліфічний Сувій?",a="Це вступне послання для щойно піднятих магів-Відступників у Похоронному Подзвоні. На ньому особиста печатка наставниці магії Ізабелли, і він велить молодим чародіям з'явитися до неї в міську церкву, щоб почати навчання.",al={"що це за річ","використання гліфічного сувою","що робить сувій"}},{q="Хто надсилає Гліфічний Сувій?",a="Сувій доставляють від імені Ізабелли, наставниці магів у зруйнованій церкві Похоронного Подзвону. Вона кличе кожного щойно піднятого мерця, що має хист до таємної магії.",al={"хто це написав","хто дав мені це","відправник сувою"}},{q="Чому Ізабелла хоче навчати нових магів-Відступників?",a="Ізабелла шукає споріднені душі, що поділяють біль смерті й прагнення повернути собі вкрадену батьківщину та долю. Вона вчить їх здобути досить магічної сили, щоб знищити кожного, хто стане проти Відступників, але застерігає не піддатися магічній залежності й зіпсуттю.",al={"мотив ізабелли","чому навчати магів"}}},fp="14,233,25.552.0,27.247.0,29.195.0,51.285.0"}
P.entries["item:glyphic-tablet"] = {n="Гліфічна Табличка",s="Гліфічна Табличка — плитка з письменами, яку отримують тролі-маги Темного Списа, починаючи випробування в Дуроторі. Передана через наглядача Ґорнека, вона спрямовує чародіїв-початківців по науку до тролиці-наставниці магів Май'а.",h="Гліфічна Табличка — плитка з письменами, яку отримують тролі-маги Темного Списа, починаючи випробування в...",kw={"гліфічна табличка","маг","май'а","ґорнек","темний спис","долина випробувань","магія"},ang={["class:Mage"]="Табличка знаменує початок вашої магічної науки серед Темного Списа і несе нагадування від Май'а: згубна принадність магії — ваша найбільша небезпека.",["race:Troll"]="Як єдиний народ у Долині Випробувань, що практикує чародійство, маги Темного Списа отримують цю табличку, щоб почати свій особливий шлях поряд із традиційними шаманськими й воїнськими."},sec={{t="Перший поклик мага",b="У Долині Випробувань новим посвячуваним Темного Списа, що виявляють хист до таємної сили, вручають Гліфічну Табличку. Ґорнек передає її, поки молоді новобранці виконують перші доручення серед червоних каньйонів; табличка містить запрошення від Май'а — досвідченої тролиці-маги, що стоїть біля Лігва. Для Темного Списа, чиї магічні традиції далекі від учених академій людей чи високих ельфів, табличка — офіційний заклик до дисципліни. На зустрічі Май'а дає і магічну настанову, і суворе застереження: сира магія розбещує, обманює і значно небезпечніша для розуму чародія, ніж будь-який ворожий солдат."}},faq={{q="Для чого Гліфічна Табличка?",a="Це письмовий виклик, що велить новачкові — тролю-магові — з'явитися до Май'а, місцевої наставниці магів у Долині Випробувань, і почати справжнє навчання чарів.",al={"що робить гліфічна табличка","використання гліфічної таблички","чому в мене гліфічна табличка"}},{q="Хто надсилає Гліфічну Табличку?",a="Табличку написала наставниця магів Май'а, а молодим тролям-новобранцям її вручає Ґорнек у Долині Випробувань.",al={"хто написав гліфічну табличку","хто дав гліфічну табличку"}},{q="Чому тролів-магів застерігають щодо магії?",a="Май'а наголошує, що таємна магія за своєю природою розбещує. Вона попереджає, що магія живить пиху й змушує чародіїв вірити у власну непереможність, а невидимі небезпеки таємної магії куди смертоносніші за живих суперників.",al={"що каже май'а","чи небезпечна магія"}},{q="Чи можуть цю табличку отримати інші раси Орди?",a="У Долині Випробувань Гліфічну Табличку отримують лише тролі-маги, бо орки Дуротару не практикують таємної магії.",al={"чи орки можуть отримати гліфічну табличку","чи табличка лише для тролів"}}},fp="14,246,22.655.0,42.171.0,29.123.0,46.233.0,42.124.0"}
P.entries["item:glyphs-of-summoning"] = {n="Гліфи Прикликання",s="Гліфи Прикликання — ритуальні написи, якими користуються чорнокнижники-учні в Оргріммарі. Переписані з давньої Скрижалі Верги, вони дають змогу виманити блукача Порожнечі з Нижнього Світу в коло прикликання й прив'язати його до себе на службу.",h="Гліфи Прикликання — ритуальні написи, якими користуються чорнокнижники-учні в Оргріммарі.",kw={"гліфи прикликання","скрижаль верги","блукач порожнечі","чорнокнижник","ґан'рул бладай","тіньова розколина"},ang={["class:Warlock"]="Гліфи — важливий обряд посвяти для чорнокнижників Орди: саме ними вони доводять свою владу над Порожнечею й здобувають слугу — блукача Порожнечі."},sec={{t="Угода, укладена в тіні",b="У підземних глибинах Тіньової Розколини темні мистецтва вивчають далеко від цікавих очей вартових Вождя. Для чорнокнижника-початківця, що навчається в Ґан'рула Бладая, влада над блукачем Порожнечі — важливий крок у ремеслі. Гліфи Прикликання, засновані на таємних знаннях, викарбуваних на Скрижалі Верги, перекидають міст між Азеротом і Нижнім Світом. Викладені в колі прикликання в наметі Ніру Файрблейда, гліфи розривають поріг і втягують істоту Порожнечі у світ смертних. Ритуал вимагає, щоб чорнокнижник здолав прикликану сутність у бою, і лише тоді Ґан'рул відкриває останні способи її прив'язати."}},faq={{q="Для чого потрібні Гліфи Прикликання?",a="Гліфи — обрядові письмена для кола виклику в наметі Ніру Файрблейда в Оргріммарі. Активовані, вони викликають із Нижнього Світу ворожого блукача Порожнечі, якого чорнокнижник мусить приборкати, щоб опанувати мистецтво його виклику.",al={"що роблять гліфи прикликання","призначення гліфів прикликання","як використати гліфи прикликання"}},{q="Звідки беруться Гліфи Прикликання?",a="Їх дає наставник чорнокнижників Ґан'рул Бладай у Тіньовій Розколині — на основі знань, збережених на Скрижалі Верги.",al={"де взяти гліфи прикликання","хто дає гліфи прикликання"}},{q="Де проводять обряд виклику?",a="Обряд відбувається в наметі Ніру Файрблейда — по той бік печери в Тіньовій Розколині Оргріммара.",al={"де викликати пустоходця","коло виклику оргріммар","коло нееру файєрблейд"}},{q="Чому чорнокнижники мусять здолати викликану істоту?",a="Чорнокнижник не може безпечно керувати демоном чи істотою Порожнечі, не утвердивши над нею своєї влади. Перемога над викликаною сутністю доводить його рішучість і дає Ґан'рулу Бладаю змогу навчити, як прив'язувати таких істот до своєї волі.",al={"чому перемагати пустоходця","приборкати пустоходця"}}},fp="19,252,23.680.0,42.244.0,43.143.0,40.127.0,53.246.0"}
P.entries["item:gnoam-sprecklesprocket"] = {n="Ґноам Спрекльспрокет",s="Ґноам Спрекльспрокет — хитромудре джерело живлення, зняте з потрощувача Сніда глибоко в Мертвих Копальнях. Гномські інженери шукають цю деталь, щоб надати небаченої потужності особливим бурильним машинам і здійснити сміливий задум — повернути свою загиблу домівку, Гномреґан.",h="Ґноам Спрекльспрокет — хитромудре джерело живлення, зняте з потрощувача Сніда глибоко в Мертвих Копальнях.",kw={"ґноам спрекльспрокет","снід","мертві копальні","гномреґан","шоні тихий","бур"},ang={["profession:Engineering"]="Ця деталь — неушкоджене джерело живлення, здатне рухати машини, потрібні, щоб пробуритися крізь скелясті підземні кордони Гномреґана.",["race:Gnome"]="Кожна врятована деталь наближає гномів-вигнанців до того, щоб пробуритися у втрачену домівку й вигнати звідти трогів."},sec={{t="Безцінне джерело енергії",b="Found in a goblin shredder operated within the Defias stronghold, the Gnoam Sprecklesprocket represents an exceptional feat of compact mechanical energy. Operating deep in the lumbering machine piloted by the goblin taskmaster Sneed, this specialized core delivers enough sustained energy to drive heavy industrial logging and cutting blades. Its stability and potent output make it an invaluable piece of salvage amidst the subterranean tunnels of Westfall."},{t="Прорив до Гномреґана",b="У Стормвінді гномська винахідниця Шоні Тихий побачила в потрощувачі з Мертвих Копалень ключ до ширшого наступу. Гноми прагнуть відбити Гномреґан у полчищ трогів, що його захопили, але запечатані підземні підступи — грізна перешкода. Завдяки Спрекльспрокету Шоні сподівається живити важкі гіросвердломатичні екскаваціонатори, здатні пробуритися крізь суцільну скелю довкола втраченого техноміста й прокласти несподіваний підземний шлях для атаки."}},faq={{q="Що таке Ґноам Спрекльспрокет?",a="Це цілий і потужний механічний блок живлення, вийнятий із гоблінського потрощувача глибоко в Мертвих Копальнях. Його потужності досить, щоб рухати важке підземне бурове обладнання.",al={"спрекльспрокет","що це за деталь","що це за предмет"}},{q="Звідки береться Ґноам Спрекльспрокет?",a="Його дістають із Потрощувача Сніда — промислової лісорубної машини, якою керує гоблін-наглядач Снід на лісопилках Мертвих Копалень.",al={"хто дропає його","як отримати спрекльспрокет","дроп подрібнювача"}},{q="Навіщо він Шоні Тихому?",a="Шоні потрібна його енергія, щоб живити гіробуромагічні копачі. Ці машини мають пробити підземні скельні межі Гномреґана, щоб гноми, віддані Альянсу, могли піти в наступ на трогів.",al={"навіщо він шоні","предмет завдання шоні"}},{q="Ця деталь — гоблінська чи гномська техніка?",a="Її знімають із робочого гоблінського потрощувача в Мертвих Копальнях, а Шоні хоче застосувати це джерело живлення в гномських бурильних машинах. Хто спершу сконструював деталь, джерело не уточнює.",al={"чи це гоблінська техніка","гномська чи гоблінська штука"}}},fp="22,263,20.458.0,20.512.0,35.186.0,48.149.0,35.234.0,45.206.0"}
P.entries["item:gnoll-paw"] = {n="Лапа Гнола",s="Лапи гнолів — грубі трофеї, які здобувають із гнолів Річколапів, що блукають степами Вестфолу. Народне ополчення збирає їх як доказ того, що патруль успішно прорідив зграї, які загрожують місцевим фермам.",h="Лапи гнолів — грубі трофеї, які здобувають із гнолів Річколапів, що блукають степами Вестфолу.",kw={"лапа гнола","гноли річколапів","народне ополчення","капітан данувін","сентінел гілл","вестфол"},ang={["class:Hunter"]="Вистежувати агресивні зграї Річколапів відкритими рівнинами Вестфолу — для мисливців проста здобич і водночас допомога сільським заставам.",["faction:Alliance"]="Для героїв Альянсу виконувати замовлення Народного ополчення життєво важливо, щоб західна житниця Стормвінда не дісталася цілком диким зграям і організованим розбійникам."},sec={{t="Винагорода від ополчення",b="Королівське військо далеко, корона ніби не помічає лиха сільських поселень, тож оборона Вестфолу лягла на плечі звичайних людей і добровольців. Народне ополчення, що діє із Сентінел Гілла, безупинно бореться з розбійниками, здичавілими механоїдами й агресивними гнолами з головами гієн. Щоб приборкати гнолів, Капітан Данувін призначив винагороди, за які треба приносити речові докази вбитих звірів. Збирати відрубані лапи — похмура необхідність: так найманці справді прочісують чагарники, а не байдикують у тіні сторожової вежі."},{t="Злагоджена загроза",b="Гноли Річколапів у Вестфолі — не просто дикі звірі, що шукають поживи на рівнинах. Спостерігачі з ополчення помітили тривожні ознаки того, що ці гноли діють у тісній злагоді зі злодіями Дефіасу, які осіли довкола Мертвих Копалень. Тероризуючи віддалені ферми й полюючи на вози з припасами, зграї гнолів фактично прикривають розбійників від місцевого спротиву. Приборкуючи їх і приносячи їхні лапи, шукачі пригод допомагають тримати відкритими хиткі суходільні шляхи між Сентінел Гіллом і Лісом Елвінн."}},faq={{q="Навіщо Капітанові Данувіну Лапи Гнола?",a="Капітан Данувін приймає лапи як доказ успішного патрулювання вестфолських рівнин. Сил в ополчення обмаль, а корона не допомагає, тож винагороду платять лише тоді, коли новобранці приносять відчутний доказ убитих гнолів.",al={"навіщо збирати лапи","лапи гнолів данувіна","для чого лапи гнолів"}},{q="З яких гнолів випадають ці лапи?",a="Їх збирають із різних гнолів-Річколапів, що никають луками, пагорбами й покинутими хуторами по всьому Вестфолу.",al={"де взяти лапи гнолів","які гноли мають лапи","місце лап гнолів"}},{q="Чи діють гноли у Вестфолі самі?",a="Ні. Капітан Данувін та ополчення підозрюють, що гноли-Річколапи діють заодно з бандитами й злодіями з Мертвих Копалень, — і місцеві хутори страждають подвійно.",al={"чи гноли працюють з дефіас","зв'язок гнолів із мертвими копальнями","хто командує гнолами"}},{q="Чому Стормвінд не розбирається із загрозою гнолів?",a="Через внутрішні чвари й політичний параліч Стормвінд майже покинув Вестфол напризволяще. Оборона краю лягла майже цілком на плечі місцевих фермерів і Народного ополчення.",al={"чому немає армії стормвінда","де армія","чому ополчення б'ється з гнолами"}}},fp="9,240,21.582.0,20.523.0,41.240.0,29.133.0,40.206.0,50.206.0"}
P.entries["item:gnomeregan-gumdrop"] = {n="Мармеладка з Гномреґану",s="Мармеладка з Гномреґану — особливі сезонні ласощі, які на Переддень Усіх Святих роздають від імені гномів-вигнанців. Шукачі пригод приносять цю цукерку, щоб хворий хлопчик Джеспер зі стормвіндського сиротинця теж міг відсвяткувати.",h="Мармеладка з Гномреґану — особливі сезонні ласощі, які на Переддень Усіх Святих роздають від імені...",kw={"мармеладка з гномреґану","переддень усіх святих","джеспер","талваш дель кіссель","гноми","солодощі"},ang={["faction:Alliance"]="Щоб здобути ці ласощі, доведеться побувати в людських, дворфійських і гномських громадах — це показує тісні зв'язки між народами Альянсу під час сезонних свят.",["race:Gnome"]="Навіть не повернувши собі власного міста, гноми пишаються тим, що їхні фірмові ласощі є серед частувань великих столиць Альянсу на Переддень Усіх Святих."},sec={{t="Смак гномської винахідливості",b="На Переддень Усіх Святих корчмарі по всьому Альянсу роздають місцеві ласощі, але гноми-вигнанці з Гномреґану не мають власної корчми в повноцінній столиці. Натомість винахідливий гном Талваш Дель Кіссель, що живе в Кварталі містиків Айронфорджу, роздає Мармеладки з Гномреґану мандрівникам, які охоче підтримують його святкові витівки. Попри радіоактивну катастрофу, що вигнала його народ із підземного королівства, гноми з гордістю діляться своїми неповторними солодощами з усім Альянсом."},{t="Ласощі для Джеспера",b="Джеспер хворий і прикутий до стормвіндського сиротинця на Соборній Площі, тож не може сам мандрувати континентами й ходити по солодощі. Мармеладка з Гномреґану — один із чотирьох обов'язкових місцевих смаколиків, разом із частуваннями зі Стормвінда, Айронфорджу й Дарнасуса, які добросерді мандрівники збирають у столицях Альянсу, щоб принести свято до нього."}},faq={{q="Звідки береться Мармеладка з Гномреґану?",a="Її дає Талваш Дель Кіссель — гном-майстер із Кварталу містиків Айронфорджа, — коли ви покажете йому фокус під час свята Переддень Усіх Святих.",al={"хто дає мармеладку","як отримати мармеладку","місце мармеладки"}},{q="Чому цю цукерку не роздають у Гномреґані?",a="Гномреґан заполонили троги й отруїло випромінювання, тож уцілілі гноми мусили піти у вигнання. Багато з них, як-от Талваш Дель Кіссель, тепер живуть поруч із дворфами в Айронфорджі.",al={"чому айронфордж","чому талваш в айронфорджі"}},{q="Для чого ця цукерка?",a="Це одна з чотирьох святкових солодощів, потрібних для завдання на Переддень Усіх Святих для Джеспера — хворого хлопчика-сироти із сиротинця на Соборній Площі Стормвінда.",al={"що робить мармеладка","цукерка джеспера"}},{q="Які ще ласощі збирають разом із нею?",a="Джеспер просить також Нугу зі Стормвінда, М'ятний Льодяник із Залізокузні та Марципан із Дарнасуса — кожну солодкість здобувають у відповідній столиці Альянсу.",al={"інші ласощі","солодощі хелловін"}}},fp="18,229,28.515.0,18.378.0,42.160.0,46.170.0,28.153.0,45.137.0"}
P.entries["item:gnomish-tools"] = {n="Гномські Інструменти",s="Гномські Інструменти — хитромудре механічне знаряддя, підняте з потоплених бойових кораблів флоту Великого адмірала Дейліна Праудмура біля узбережжя Дуротару. Орда шукає ці врятовані пристрої, щоб вивчити інженерію Альянсу й обернути технологічну перевагу ворогів собі на користь.",h="Гномські Інструменти — хитромудре механічне знаряддя, підняте з потоплених бойових кораблів флоту Великого...",kw={"гномські інструменти","праудмур","флот","дріботливе узбережжя","ґар'ток","інженерія","дуротар"},ang={["faction:Horde"]="Повернення втраченого обладнання Альянсу дає Орді змогу вивчити ворожі конструкції, розібрати чужі механізми й захиститися від майбутніх морських вторгнень.",["profession:Engineering"]="Ці набори показують точне, хитромудре ремесло майстрів Альянсу і дають цінне розуміння годинникових механізмів та мініатюризації."},sec={{t="Потоплена здобич",b="Коли Великий адмірал Дейлін Праудмур привів сили Кул Тірасу та Альянсу до берегів Дуротару, його флот віз величезні запаси сучасного обладнання, зокрема вигадливе знаряддя, виготовлене гномськими союзниками. Після знищення флоту Праудмура вздовж Дріботливого Узбережжя, на схід від Фортеці Тіраґард, ці тонкі механічні набори пішли під воду. Нині водонепроникні скриньки з інструментами розкидані серед гнилих колод і вкритих черепашками корпусів на мілководді."},{t="Очі в Оргріммарі",b="Ґар'Ток, наглядач Гострого Пагорба, доручив розвідникам Орди дістати ці інструменти з водної могили флоту Праудмура. Орки визнають, що люди й гноми володіють передовою технічною майстерністю, надто в облогових машинах, кораблебудуванні та годинниковій механіці. Збираючи ці набори й відправляючи їх караваном до ремісників і вчених Оргріммара, Орда має намір розібрати пристрої Альянсу, навчитися протистояти його бойовим машинам і пристосувати чужі винаходи до власного виживання."}},faq={{q="Чому гномські інструменти лежать біля берегів Дуротару?",a="Їх везли на бойових кораблях флоту великого адмірала Дейліна Праудмура, коли Кул Тірас напав на Дуротар. Коли армаду Праудмура розбили й потопили біля Дріботливого Узбережжя на схід від Фортеці Тіраґард, корабельний вантаж осів на морському дні.",al={"чому гномські інструменти тут","походження гномських інструментів","як інструменти опинилися в дуротарі"}},{q="Навіщо ці інструменти Орді?",a="Ґар'Ток із Гострого Пагорба хоче, щоб їх підняли й відправили в Оргріммар. Орда визнає, що інженери Альянсу мають складні механічні знання, і, вивчаючи їхні інструменти, розуміє, як працюють ворожі машини та як зробити краще власне спорядження.",al={"навіщо ґар'ток хоче інструменти","використання гномських інструментів ордою","для чого інструменти"}},{q="Де знайти інструменти?",a="Вони лежать у скриньках з інструментами, розкиданих серед затонулих уламків і довкола них уздовж Дріботливого Узбережжя, трохи на схід від Фортеці Тіраґард у Дуротарі. Багато з них під водою чи на напівзатоплених розбитих корпусах.",al={"місце гномських інструментів","де знайти гномські інструменти","місця гномських скриньок"}}},fp="13,293,14.485.0,17.521.0,53.259.0,36.280.0,26.201.0"}
P.entries["item:gold-dust"] = {n="Золотий Пил",s="Золотий Пил — дрібні крупинки дорогоцінного металу, які просіюють і накопичують кобольди, що заполонили копальні Лісу Елвінн. Поки звичайні рудокопи шукають цілі жили руди, тутешні ділки платять добру монету кожному, хто готовий відібрати ці зібрані крупинки в шкідників.",h="Золотий Пил — дрібні крупинки дорогоцінного металу, які просіюють і накопичують кобольди, що заполонили...",kw={"золотий пил","кобольди","ремі двічі","ґолдшир","копальня","чорний ринок"},ang={["class:Rogue"]="Торгівля неочищеним, невідстежуваним пилом із такими тіньовими постатями, як Ремі «Двічі», — практичний урок того, як підпілля відмиває сире багатство подалі від очей магістратів Стормвінда.",["profession:Mining"]="Поки рудокопи шукають суцільні жили міді й олова з киркою та лотком, кобольдовий пил показує, що підземні ходи Елвінну ховають багатші поклади, ніж кажуть звичайні обстеження."},sec={{t="Кисет, повний крихт",b="Під землею Лісу Елвінн кобольди шкребуть підземні тунелі копалень Фарґодіп і Яшмової. Замість як слід очищати знайдену руду, щуроподібні створіння часто ховають грубий золотий пил просто в кишенях і кисетах. Ці дрібні блискучі крупинки — плід марудної підземної праці, яку поважні гірничі товариства легко не помічають, зате палко жадають тутешні рознощики й скупники краденого, що хочуть тихо нажитися, не сплачуючи офіційних плавильних мит."},{t="Чорний ринок Ґолдширу",b="У містечку Ґолдшир Ремі «Двічі» завзято випитує в подорожніх здобутий золотий пил. Заявляючи, що пропонує найкращу ціну в місті, Ремі від імені своїх неназваних спільників міняє монету й підозрілі жетони на кисети з сирим пилом. Використовуючи заповзятливих найманців, щоб вирвати золото просто з кобольдових лап, тіньові посередники тримають руки чистими й водночас здобувають невідстежуване багатство просто під носом у варти Стормвінда."}},faq={{q="Звідки береться Золотий Пил?",a="Золотий Пил носять кобольди по всьому Лісу Елвінн. Шахтарі, копачі, геоманти та їхній сумнозвісний ватажок Золотозуб збирають і ховають цей мерехтливий порох, прокопуючись крізь пагорби.",al={"як отримати золотий пил","дроп золотого пилу","де взяти золотий пил"}},{q="У яких копальнях найбільше кобольдів із Золотим Пилом?",a="І Копальню Фарґодіп на південь від Ґолдшира, і Яшмову копальню на північному сході заполонили кобольди з пилом.",al={"де копальні","найкраща копальня для золотого пилу","місця копалень"}},{q="Хто купує Золотий Пил у Лісі Елвінн?",a="Ремі «Двічі» — темний ділок, що крутиться біля Корчми «Лев'яча Гордість» у Ґолдширі, — охоче скуповує мішечки Золотого Пилу за гроші й знаки від своїх спільників.",al={"хто хоче золотий пил","золотий пил ремі","здати золотий пил"}},{q="Чому кобольди носять пил, а не зливки?",a="Кобольдам бракує і порядку, і знарядь, щоб як слід переплавляти метал. Коли вони дряпають скелю грубими кайлами, золотий пил осідає на їхніх речах і в маленьких мішечках, які вони носять як блискучі дрібнички.",al={"чому кобольди мають пил","золото кобольдів"}}},fp="9,268,22.524.0,24.472.1,31.204.0,53.146.0,36.183.0,44.222.0"}
P.entries["item:golm-fragment"] = {n="Уламок Голма",s="Уламок Голма — одна з чотирьох утрачених частин, відколотих від Каменя Ґоаза, прадавньої реліквії, знайденої на розкопі в Багнокраї. Здобутий шукачами пригод, що ухилялися від лютих рапторів, він допомагає дворфам-археологам скласти докупи загадкові написи титанів.",h="Уламок Голма — одна з чотирьох утрачених частин, відколотих від Каменя Ґоаза, прадавньої реліквії, знайденої...",kw={"уламок голма","камінь ґоаза","шукач велґар","ліга дослідників","титани","багнокрай"},ang={["faction:Alliance"]="Здобутий уламок допомагає Лізі Дослідників уберегти безцінні давні знання, перш ніж розкоп остаточно поглинуть раптори.",["race:Dwarf"]="Для дворфів складати докупи уламки Каменя Ґоаза — ключ до розгадки свого походження від титанів і прихованої історії, похованої в Каз Модані."},sec={{t="Частина Каменя Ґоаза",b="Знайдений на розкопі на півдні Багнокраю, Уламок Голма — частина величезної плити, відомої як Камінь Ґоаза. Шукач Велґар відкрив камінь незадовго до того, як раптори відтіснили Лігу Дослідників, але виявив, що напис обірвано в чотирьох найважливіших місцях. Коли розкоп заполонили, Уламок Голма лишився серед землі й перекинутих ящиків, схований у прадавній скриньці для реліквій, доки його не забрали відважні дослідники."},{t="Таємниці титанів",b="Поєднаний з уламками Адоса, Модра й Неру, Уламок Голма довершує загадковий текст титанів, що провіщає «божественний задум» і «приречене пророцтво». Склавши камінь, Велґар розшифровує рядки про прадавні сутності, скуті під землею, — це підтверджує, що розкоп ховає знання куди давніші й небезпечніші, ніж проста дворфійська спадщина."}},faq={{q="Для чого потрібен Уламок Голма?",a="Це один із чотирьох кам'яних уламків, потрібних Шукачеві Велґару на розкопках у Багнокраї, щоб відновити Камінь Ґоаза під час завдання «Відкриваючи минуле».",al={"призначення уламка голма","навіщо уламок голма","завдання уламка голма"}},{q="Де знайти Уламок Голма?",a="Він серед прадавніх реліквій і пухкої землі, розкиданих по розкопках на південних пагорбах Багнокраю, де аж кишить рапторами.",al={"місце уламка голма","знайти уламок голма","де уламок голма"}},{q="Що каже Камінь Ґоаза, коли його зібрано?",a="Перший переклад Велґара говорить про божественний задум і приречене пророцтво. Йому потрібні всі чотири уламки, щоб і далі розшифровувати неповні письмена титанів.",al={"переклад каменю ґоаза","що написано на табличці","переклад велґара"}},{q="Які ще уламки потрібні, щоб завершити камінь?",a="Окрім Голма, вам треба знайти уламки Адоса, Модр і Неру, щоб цілком скласти таблицю.",al={"інші уламки таблички","частини каменю ґоаза","чотири уламки"}}},fp="13,266,25.462.0,21.363.1,35.155.0,37.137.0,44.157.1,52.98.0"}
P.entries["item:gordon-s-crate"] = {n="Ящик Гордона",s="Ящик Гордона — важка партія зброї, спакована в Андерсіті для загонів Відступників у Срібноліссі. Цей вантаж треба доправити просто до віддаленого гарнізону в Склепі.",h="Ящик Гордона — важка партія зброї, спакована в Андерсіті для загонів Відступників у Срібноліссі.",kw={"ящик гордона","склеп","срібнолісся","майкл гарретт","карос разок","кажани","вартовий смерті подріґ"},ang={["faction:Horde"]="Ця доставка показує, як розростаються повітряні шляхи Відступників, що швидко переносять вантажі й гінців через спірний Лордерон.",["race:Undead"]="Кожна партія клинків і спорядження зі столиці зміцнює хиткі прикордонні рубежі Леді Сильвани в Срібноліссі."},sec={{t="Припаси для Срібнолісся",b="Щоб утримувати Срібнолісся, Відступникам потрібен сталий потік постачання з Андерсіті. У Ящику Гордона — зброя для захисників Вартового Смерті Подріґа в Склепі: щоб воргени, дикі звірі чи вцілілі люди, які чатують у лісах, не заскочили вартових застави зненацька."},{t="Шлях доглядача кажанів",b="Суходільні дороги зі столиці небезпечні й повільні, тож цінні вантажі доправляють доглядачі кажанів Андерсіті. Ящик передають Майклові Гарретту — майстрові кажанів, що чатує над торговим кварталом міста, — і той відправляє його на спині навченого кажана до сідала Кароса Разока в Склепі."}},faq={{q="Що в Ящику Гордона?",a="У ящику — зброя й найпотрібніші бойові припаси, виписані з Андерсіті, щоб підсилити Вартових Смерті, що несуть службу в Срібноліссі.",al={"вміст ящика гордона","що в ящику"}},{q="Хто має отримати Ящик Гордона?",a="Ящик отримує Вартовий Смерті Подріґ у Гробниці. Щоб його доставити, треба домовитися з приборкувачем кажанів Андерсіті Майклом Гарреттом про прямий переліт.",al={"хто отримує ящик гордона","куди ящик"}},{q="Чому ящик везуть кажаном, а не пішим кур'єром?",a="Срібнолісся досі небезпечне й спірне. Навчені кажани під наглядом приборкувачів, як-от Майкла Гарретта й Кароса Разока, забезпечують швидкий переліт повітрям, оминаючи ворожі загрози на земних шляхах.",al={"чому летіти ящик","ящик нетопиром"}},{q="Чому Майкл Гарретт вимагає, щоб ви спершу побували в Гробниці?",a="Кажани Відступників інстинктивно повертаються до столиці, але щоб безпечно дістатися віддалених застав, як-от Гробниці, мандрівник має спершу встановити зв'язок із місцевим приборкувачем, Каросом Разоком, — лише тоді кажани зможуть туди летіти.",al={"чому потрібен маршрут польоту","вимога польоту кажаном"}}},fp="14,240,23.322.0,23.309.0,30.150.0,42.163.0,65.209.0,66.220.0"}
P.entries["item:grape-manifest"] = {n="Опис Винограду",s="Опис Винограду — рукописна відомість, що обліковує врожай із виноградника Міллі Осворт у Долині Нортширу. Вона засвідчує повернення свіжих плодів після того, як тутешні розбійники захопили поля, і призначена для підвалів Абатства Нортшира.",h="Опис Винограду — рукописна відомість, що обліковує врожай із виноградника Міллі Осворт у Долині Нортширу.",kw={"опис винограду","міллі осворт","брат нілз","абатство нортшира","урожай","виноградник"},ang={["profession:Cooking"]="Для кухарів опис утілює тонку рівновагу між урожаєм полів і коморами абатства, показуючи, як місцеві інгредієнти живлять цілу чернечу громаду.",["race:Human"]="Документ висвітлює ранні труднощі серця Стормвінда, де навіть чернече життя й простий урожай потребують збройного захисту від мандрівних розбійників."},sec={{t="Запис про врожай",b="Абатство Нортшира здавна живиться з місцевого господарства, зокрема з пишних виноградників, які доглядають тутешні фермери на кшталт Міллі Осворт. Коли бандити Дефіас прийшли в долину й захопили врожай, запаси свіжих плодів і сировини для бродіння в абатстві опинилися під загрозою. Опис Винограду слугує офіційним підтвердженням, що ящики повернуто з полів. Він вказує кількість урятованого винограду, щоб інтенданти абатства могли звести свої запаси й підготувати бочки для бродіння."},{t="Келар абатства",b="Брат Нілз відповідає за харчі й напої Нортширу, маючи особливу слабкість до куштування абатського вина у високій тиші дзвіниці. Для нього отримати опис — не просто паперова робота: він гарантує, що ченці й гостьові новобранці не страждатимуть від спраги. Для побожних братів абатства кожен урятований кошик — водночас і господарська перемога, і тихе благословення Святого Світла."}},faq={{q="Що таке Опис Винограду?",a="Це опис, який склала Міллі Осворт, — облік урожаю, врятованого з її захопленого виноградника. У ньому записано, скільки свіжого винограду доставляють до Абатства Нортшира.",al={"що таке опис винограду","предмет опис винограду"}},{q="Хто отримує опис?",a="Його отримує Брат Нілз. Він відає запасами їжі й вина абатства, і його зазвичай можна знайти на дзвіниці Абатства Нортшира, де він дегустує вина.",al={"хто отримує опис винограду","кому віддати опис винограду","куди опис винограду"}},{q="Чому виноград опинився під загрозою?",a="Розбійники Дефіас налетіли на Долину Нортширу й вигнали Міллі Осворт із виноградника. Урожай опинився під загрозою, а абатство лишилося без свіжих плодів, доки не втрутилися новобранці.",al={"чому виноград урятувати","розбійники виноградника","що сталося з урожаєм міллі"}},{q="Що Брат Нілз робить із виноградом?",a="Брат Нілз поповнює ним харчові запаси абатства й робить свіже нортширське вино — для місцевого братства й для захисників, що приходять у гості.",al={"для чого виноград","вино абатства"}}},fp="14,243,23.519.0,20.436.0,27.185.0,26.154.0,30.192.0,43.166.0"}
P.entries["item:gray-bear-tongue"] = {n="Язик Сірого Ведмедя",s="Язик Сірого Ведмедя — сирий складник, який добувають із диких ведмедів, що блукають Передгір'ям Гілсбреда. Його шукає Королівське Аптекарське Товариство в Таррен Міллі як біологічну складову своїх експериментальних отрут.",h="Язик Сірого Ведмедя — сирий складник, який добувають із диких ведмедів, що блукають Передгір'ям Гілсбреда.",kw={"язик сірого ведмедя","сірі ведмеді","таррен мілл","аптекар лайдон","еліксир страждання","передгір'я гілсбреда"},ang={["race:Undead"]="Збирання органічних складників із місцевої живності безпосередньо допомагає Королівському Аптекарському Товариству створювати нові чуми проти живих."},sec={{t="Аптекарські дослідження в Гілсбреді",b="Неприборкані дикі краї довкола Таррен Мілла багаті на місцеву живність, зокрема кілька порід кремезних сірих ведмедів. Хоча хижаки постійно загрожують мандрівникам, Відступники бачать у них джерело сировини для алхімії. Аптекар Лайдон вивчає місцевих тварин, щоб виокремити дієві органічні речовини, і використовує щільні м'язові тканини й рідини з язиків сірих ведмедів як основу для смертоносних розчинів, як-от Еліксиру Страждання."}},faq={{q="Кому потрібні язики сірих ведмедів?",a="Аптекар Лайдон із застави Відступників Таррен Мілл у Передгір'ї Гілсбреда шукає ці язики, щоб варити експериментальні смертоносні засоби.",al={"кому потрібні язики ведмедів","аптекар лайдон язики","здати язики ведмедів"}},{q="Для чого Аптекареві ці язики?",a="Лайдон створює смертоносне вариво — Еліксир Страждання, що має допомогти накликати чуму на живих людей Гілсбреда. Язики — один із головних органічних складників разом з іхором повзунів.",al={"навіщо лайдону язики","призначення язиків ведмедів","інгредієнти еліксиру страждання"}},{q="З яких істот випадають ці язики?",a="Їх можна добути з будь-яких сірих ведмедів, що блукають Передгір'ям Гілсбреда, — звичайних, старих, лютих сірих ведмедів і сумнозвісного звіра Великого Самраса.",al={"де падають язики ведмедів","які ведмеді мають язики","ведмеді гілсбреду"}}},fp="16,229,32.479.0,28.151.0,47.220.0,35.192.0"}
P.entries["item:gregor-s-remains"] = {n="Рештки Грегора",s="Рештки Грегора — кістки, здобуті з поневоленого Погибеллю Ґреґора Аґаманда. Колись він належав до найзаможнішої династії Галявин Тірісфалю, а тепер його останків прагне колишній робітник млина, що жадає звести давній рахунок з-за могили.",h="Рештки Грегора — кістки, здобуті з поневоленого Погибеллю Ґреґора Аґаманда.",kw={"рештки грегора","ґреґор аґаманд","млини аґаманда","коулмен фартінґ","помста","погибель"},ang={["faction:Horde"]="Очищення Млинів Аґаманда — прямий удар по недобитках Погибелі, що загрожують безпеці Галявин Тірісфалю.",["race:Undead"]="Трагедія Аґамандів віддзеркалює долю багатьох Відступників: простий люд, зраджений гордістю знаті й покинутий на жахіття Чуми."},sec={{t="Спадщина руїни",b="До Третьої війни родина Аґамандів мала величезне багатство й широкі землі на півночі Галявин Тірісфалю. Коли Погибель вторглася до Лордерону, патріархи обрали гордість замість утечі: укріпили родинні млини й переконали вірних робітників стати на відчайдушну оборону проти нежиті. Оборона провалилася цілковито. Маєток захопили, а тих, хто вистояв на місці, вирізали й підняли в нежитті. Ґреґор Аґаманд став ще одним безтямним рабом, яким володіє Король-Ліч, і тепер никає тими самими млинами, якими колись правила його родина."},{t="Ціна помсти",b="Для вцілілих, що вирвалися з лабет Короля-Ліча й приєдналися до Відступників, пам'ять про ту фатальну оборону лишається гіркою раною. Коулмен Фартінґ, колишній робітник млина, що тепер перебуває у Бріллі, звинувачує пиху Аґамандів у тому, що його душа ув'язнена у вічному гнитті. Зібрати рештки Ґреґора означає для Фартінґа міру особистої відплати — закрити розділ про господаря, який повів свій дім просто в прокляття."}},faq={{q="Хто такий Ґреґор Аґаманд?",a="Ґреґор Аґаманд — помітний член роду Аґамандів, найзаможнішої родини землевласників у Галявинах Тірісфалю до Третьої війни. Коли прийшла чума нежиття, він із родиною вирішив укріпити маєток, а не тікати, — і всіх, хто був усередині, вирізали й підняли з мертвих.",al={"історія ґреґора","хто такий ґреґор","ґреґор аґаманд"}},{q="Навіщо Коулменові Фартінґу Рештки Грегора?",a="За життя Коулмен Фартінґ працював на млинах Аґамандів. Він глибоко зненавидів родину за те, що вона вмовила робітників лишитися й битися з Погибеллю, — ця помилка прирекла їх усіх на нежиття. Рештки Ґреґора, принесені йому, — довгоочікувана помста.",al={"чому коулмен хоче рештки","образа коулмена фартінґа","навіщо збирати кістки ґреґора"}},{q="Де знайти Рештки Грегора?",a="Рештки забирають із піднятого з мертвих Ґреґора Аґаманда на Млинах Аґаманда, що на північних пагорбах Галявин Тірісфалю.",al={"де знайти ґреґора","місце ґреґора","млини аґаманда ґреґор"}},{q="Чи Аґаманди — Відступники?",a="Ні. На відміну від Відступників, які вирвалися на волю під проводом королеви Сильвани, Ґреґор Аґаманд і його рідня лишаються безвольними слугами, скутими волею Погибелі.",al={"чи ґреґор відступник","чи аґаманди погибель","хто керує ґреґором"}}},fp="16,246,16.557.0,22.424.0,23.299.0,48.276.0,33.135.0,38.148.0"}
P.entries["item:grelin-s-report"] = {n="Звіт Греліна",s="Звіт Греліна — депеша, яку Ґрелін Вайтбірд склав про становище з тролями Морозогривами в Долині Холодного Хребта. Довірена шукачеві пригод, а не недосвідченому учневі, вона є офіційною ланкою між розвідниками, що стережуть Анвілмар, і Сеніром Вайтбірдим, який служить у Хараносі.",h="Звіт Греліна — депеша, яку Ґрелін Вайтбірд склав про становище з тролями Морозогривами в Долині Холодного...",kw={"звіт греліна","ґрелін вайтбірд","сенір вайтбірдий","депеша","морозогриви","горянин талос","харанос","перевал холодного кряжа"},ang={["race:Dwarf"]="Пронести цей звіт — для дворфа перехід від безпечних навчальних угідь Холодного Хребта до оборони серця Дун Мороґу й служби Айронфорджу.",["race:Gnome"]="Доставити послання Ґреліна — нагода для гномів-біженців довести свою вартість дворфійським горянам, долаючи спільні гірські перевали Дун Мороґу."},sec={{t="Депеша повз трогів",b="Написаний після спостережень за тролями Морозогривами в Долині Холодного Хребта, Звіт Греліна робить висновок: великої загрози вони не становлять, і з ними впораються горяни, що вже стоять там, та найманці, яким заплатять із коштів Сенату. Замість довіряти такі важливі відомості своєму незграбному учневі, Ґрелін залучає здібного мандрівника, щоб той проніс документ крізь кишачий трогами Перевал Холодного Кряжа. Папір править за офіційну перепустку крізь заслін Горянина Талоса, доводячи, що власник прямує в нагальній справі на широкі засніжені простори Дун Мороґу."},{t="Переполох у Хараносі",b="Доставлений Сеніру Вайтбірдому до Ґуральні Тандербрю в Хараносі, звіт містить важливі польові відомості, призначені для Айронфорджа. Сенір з веселою покорою зауважує, що брат щедро розкидався по тексту іменем Короля Маґні Бронзбірда. Ґрелін посилається на дозвіл Короля на свої дії, і Сенір очікує, що таке звернення до королівської влади збурить декого в Сенаті Айронфорджа."}},faq={{q="Для чого Звіт Греліна?",a="У звіті — оцінка тролів-Морозогривів із Долини Холодного Хребта, яку Ґрелін Вайтбірд надсилає своєму братові Сеніру в Харанос. Він запевняє керівництво за межами долини, що тролі не становлять великої загрози й з ними впораються місцеві горяни та найманці, яких оплачує Сенат.",al={"що таке звіт греліна","навіщо надсилати звіт","призначення звіту греліна"}},{q="Чому Ґрелін не може доставити його сам?",a="Ґрелін лишається в Долині Холодного Хребта, стежачи за тролями. Спершу він думав послати учня, але небезпечна дорога тунелем, де аж кишить трогами, змусила його довірити важливі папери загартованому в боях шукачеві пригод.",al={"чому не доставити самому","чому довірити шукачу пригод"}},{q="Чому Горянин Талос пропускає вас зі звітом?",a="Горянин Талос стереже тунель із Долини Холодного Хребта, щоб уберегти мирних мешканців від лютих трогів. Звіт Греліна доводить, що ви в нагальній справі оборони дворфів, — і Талос вас пропускає.",al={"чому талос мене пропускає","блокада тунелю","прохід холодного хребта троґи"}},{q="Чому звіт дратує Сенат Айронфорджа?",a="Сенір Вайтбірдий зауважує, що Ґрелін раз у раз згадує в документі ім'я Короля Маґні. Такі спроби оминути звичні дипломатичні тонкощі й привернути увагу короля часто гнівлять урядовців Сенату Айронфорджа — хоч брати й погоджуються, що політиків пора струсонути.",al={"чому сенат сердиться","наїжачені пір'я","реакція сеніра"}}},fp="15,291,26.564.0,29.414.0,39.279.0,36.253.0,57.230.0,50.280.0"}
P.entries["item:grelin-whitebeard-s-journal"] = {n="Щоденник Греліна Вайтбірда",s="Щоденник Греліна Вайтбірда — особистий польовий записник, який дворф-розвідник Ґрелін Вайтбірд вів у Долині Холодного Хребта. Щоденник із важливими нотатками про діяльність місцевих тролів Морозогривів викрав вождь Ґрік'нір Холодний і затягнув до тролячої печери в Долині Холодного Хребта.",h="Щоденник Греліна Вайтбірда — особистий польовий записник, який дворф-розвідник Ґрелін Вайтбірд вів у Долині...",kw={"щоденник","ґрелін вайтбірд","ґрік'нір холодний","тролі","морозогриви","троляча печера","долина холодного хребта"},ang={["race:Dwarf"]="Повернути цей щоденник — означає вберегти важливі дворфійські відомості про загрозу Морозогривів, що підступає до самих воріт навчальних угідь Айронфорджа."},sec={{t="Записник розвідника",b="Спостерігаючи за агресивними пересуваннями тролів Морозогривів біля Долини Холодного Хребта, Ґрелін Вайтбірд старанно занотовував свої висновки в цьому записнику в шкіряній палітурці. У ньому — сирі польові спостереження про силу, устрій і рівень загрози від тутешніх зимових тролів. Але під час сутички чи засідки щоденник вихопив Ґрік'нір Холодний — троль-ватажок із рясним розписом на тілі, — і Ґреліну довелося залучити подорожніх шукачів пригод, щоб ті спустилися до тролячої печери й відбили записник, перш ніж він зможе завершити звіт."},{t="Депеша для Сеніра",b="Коли щоденник вирвано з лап Ґрік'ніра, нотатки в цьому пошарпаному записнику дають Ґреліну достатньо впевненості, щоб визнати тролячу загрозу в Долині Холодного Хребта тимчасово стриманою. Спираючись на повернуті записи, Ґрелін завершує письмову депешу про повстання Морозогривів, яку відтак запечатують і довіряють кур'єрам, що прямують до його брата Сеніра Вайтбірдого, який служить далі в Дун Мороґу."}},faq={{q="Хто вкрав щоденник Ґреліна Вайтбірда?",a="Щоденник забрав Ґрік'нір Холодний — помітний, увесь у розписах тролівський громило з Морозогривів, що живе глибоко в печері тролів у Долині Холодного Хребта.",al={"хто вкрав щоденник","у кого щоденник греліна","злодій щоденника греліна"}},{q="Що написано в щоденнику?",a="У щоденнику — розвідувальні нотатки Ґреліна Вайтбірда про місцевих тролів-Морозогривів, міру їхньої загрози й безпеку в Долині Холодного Хребта.",al={"що в щоденнику","зміст щоденника","нотатки греліна вайтбірда"}},{q="Що стається, коли щоденник повернуто?",a="Отримавши записник назад, Ґрелін за своїми нотатками пише остаточне донесення про тролів і просить шукача пригод доставити його братові, Сенірові Вайтбірдому.",al={"що ґрелін робить з щоденником","після викраденого щоденника"}},{q="Чому цей щоденник такий важливий для Ґреліна?",a="Без записника Ґрелін не складе точного розвідувального звіту про заколот Морозогривів для дворфської влади й свого брата Сеніра, і оборона Долини Холодного Хребта лишиться під питанням.",al={"чому ґрелін хоче його назад","важливість щоденника"}}},fp="27,291,16.571.0,17.417.1,38.153.0,31.175.0,44.195.1,43.195.0"}
P.entries["item:grell-earring"] = {n="Сережка Грелла",s="Сережки Грелла — грубі брязкальця, які підбирають і носять дикі істоти, що заполонили руїни Башал'Арана. На перший погляд нічим не примітні, вони побували поряд із давніми реліквіями, тож чутливі духи можуть простежити за ними залишки магічних печатей, що тримають їх у муках.",h="Сережки Грелла — грубі брязкальця, які підбирають і носять дикі істоти, що заполонили руїни Башал'Арана.",kw={"сережка грелла","грелли","астеріон","башал'аран","печать","темне узбережжя"},ang={["class:Mage"]="Сережки показують, як неживий метал може з часом пасивно вбирати й зберігати магічний відбиток давніх захисних печатей.",["race:NightElf"]="Бачити, як священні ельфійські руїни заполонили злодійкуваті феї в підібраних латунних цяцьках, — гірке нагадування, як низько впали колись величні маєтки давнього Калімдору."},sec={{t="Сліди в латуні",b="Дикі грелли й мерзенні феї, що ховаються серед обваленого мармуру Башал'Арана, збирають усілякі дрібнички й часто роблять сережки з уламків, які знаходять у руїнах. Для більшості смертних це нікчемне сміття. Але для Астеріона — давнього нічного ельфа, прикутого до руїн у подобі змученого привида, — вони стають чимось на кшталт лози лозошукача. Пильно вивчаючи відлуння магії, яке вбрали ці сережки, Астеріон намагається знайти давню печать, що тримає в неволі його примарну подобу."}},faq={{q="Звідки беруться Сережки Грелла?",a="Їх збирають із тіл диких греллів і мерзенних фей, що живуть у зруйнованому поселенні нічних ельфів Башал'Аран на Темному Узбережжі.",al={"де падають сережки грелла","де взяти сережки грелла","хто дропає сережки грелла"}},{q="Навіщо Астеріону ці сережки?",a="Астеріон — прадавній дух, якого могутня магія тримає в полоні в руїнах Башал'Аран. Він використовує сережки як магічні провідники, щоб відчути сліди печатки, яка століттями сковує його душу.",al={"навіщо астеріону сережки","чому збирати сережки грелла","призначення сережки грелла"}},{q="Як сережки допомагають Астеріону шукати печатку?",a="Астеріон сподівається накласти на сережки чари, щоб вистежити магічну печатку, яка тримає його примарну подобу в полоні в руїнах Башал'Аран.",al={"чи магічні сережки","чи грелли знають магію"}},{q="Чи знаходить Астеріон у сережках те, що шукає?",a="Самої печатки в сережках немає, але, оглянувши їх, він з'ясовує, що ці істоти нещодавно мали з нею справу, — і пошуки ведуть далі в навколишні руїни.",al={"чи спрацювали сережки","місце печатки астеріона"}}},fp="13,264,19.508.0,34.141.0,38.190.0,54.131.0,51.182.0"}
P.entries["item:grenka-s-claw"] = {n="Кіготь Гренки",s="Кіготь Гренки — трофей, здобутий у грізної гарпії Ґренки Бладскріч у глибинах Лігва Диких Пер. Вручений Дорнові Плейнстокеру у Вивітреному Закутку, він незаперечно доводить, що молодий шукач пригод витримав виснажливе фізичне випробування на висотах каньйону.",h="Кіготь Гренки — трофей, здобутий у грізної гарпії Ґренки Бладскріч у глибинах Лігва Диких Пер.",kw={"кіготь гренки","ґренка бладскріч","гарпії","лігво диких пер","дорн плейнстокер","випробування"},ang={["faction:Horde"]="Зачистка глибин Лігва Диких Пер і смерть Ґренки Бладскріч притуплюють загрозу гарпій, які раз у раз нападають на мандрівників довкола Застави Вільного Вітру.",["race:Tauren"]="Старійшина Дорн Плейнстокер вважає своїм священним обов'язком загартувати молодих героїв Орди мудрістю й стійкістю тауренських обрядів, перш ніж вони вийдуть у ширший і суворіший світ."},sec={{t="Трофей витривалості",b="У звивистих печерах Лігва Диких Пер, на захід від Застави Вільного Вітру, гарпії ховають запаси їжі й люто боронять свою територію від чужинців. Щоб випробувати фізичну витривалість молодих героїв, Дорн Плейнстокер доручає їм вдертися в глибокі гніздовища й знищити харчові запаси зграї. Така зухвала провокація неминуче накликає лють Ґренки Бладскріч. Відтятий і принесений її хижий кіготь доводить, що воїн здатен витримати хвилю за хвилею розлючених гарпій і вистояти перед шаленим натиском їхньої матріархи."}},faq={{q="Для чого потрібен Кіготь Гренки?",a="Кіготь — доказ перемоги для Дорна Плейнстокера, старійшини-таурена з Обвітреної Ніші в Тисячі Голок. Віддавши йому кіготь, ви завершуєте «Тест Витривалості» й доводите, що маєте досить тілесної стійкості, щоб вистояти в тривалому бою.",al={"використання кігтя гренки","навіщо мені кіготь гренки","завдання кігтя гренки"}},{q="Хто така Ґренка Бладскріч?",a="Ґренка Бладскріч — могутня гарпія, що гніздиться в Лігві Диких Пер у Каньйоні Вереску на південних кручах Тисячі Голок. Вона з'являється лише тоді, коли чужинці загрожують зграї, нищачи її запаси їжі.",al={"хто така ґренка","історія ґренки бладскріч","що таке ґренка"}},{q="Куди віднести кіготь, коли його здобуто?",a="Принесіть кіготь Дорнові Плейнстокеру в Обвітрену Нішу серед круч Тисячі Голок. Він прийме трофей і засвідчить, що ваше випробування витривалості успішне.",al={"куди здати кіготь гренки","кому потрібен кіготь гренки"}},{q="Чому Дорн Плейнстокер вимагає саме цей трофей?",a="Дорн Плейнстокер проводить молодих мандрівників крізь суворі випробування, щоб переконатися, що вони готові розумом, духом і тілом до більших небезпек. Убивши Ґренку й забравши її кіготь, воїн доводить, що витримає і напад зграї, і прямий удар смертоносної ватажки.",al={"чому дорн хоче кіготь","призначення кігтя"}}},fp="13,294,21.537.0,31.263.0,27.249.0,42.191.0,55.290.0"}
P.entries["item:grimtotem-satchel"] = {n="Сумка Ґрімтотемів",s="Сумка Ґрімтотемів — шкіряна торба, яку стискав полеглий таурен Маур Ґрімтотем глибоко в Проваллі Лютого Вогню. Навіть коли троги здолали його в підземній печері під Оргріммаром, Маур закривав цю торбу до останнього подиху. Якщо знайти її й повернути до Тандер Блафа, з'ясується, що Стара Відьма Маґата Ґрімтотем дуже цікавилася тим, що ніс її родич із клану.",h="Сумка Ґрімтотемів — шкіряна торба, яку стискав полеглий таурен Маур Ґрімтотем глибоко в Проваллі Лютого Вогню.",kw={"сумка ґрімтотемів","маур ґрімтотем","маґата ґрімтотем","провалля лютого вогню","тандер блаф","таурени","троги"},ang={["faction:Horde"]="Мертвий гонець Ґрімтотемів глибоко в тунелях під столицею Тралла показує, що небезпеки Провалля Лютого Вогню далеко не зводяться до звичайної навали звірів.",["race:Tauren"]="Ґрімтотем, що діяв глибоко під Оргріммаром і звітував Маґаті на Узвишші Старійшин, — яскравий знак тонких і тривожних політичних ігор Ґрімтотемів усередині об'єднаних племен тауренів."},sec={{t="Мертва хватка",b="Цю просту торбу знайшли під понівеченим тілом Маура Ґрімтотема в глибинах Провалля Лютого Вогню — він стискав її, мов лещатами. Оточений лютими трогами, що зрештою його вбили, Маур відчайдушно боронив її вміст. Така рішучість — берегти торбу понад власне життя — свідчить, що в ній щось значно важливіше, ніж звичайні харчі в дорогу чи припаси."},{t="Інтерес Старої Відьми",b="Коли торбу приносять Рагауро на Узвишші Старійшин у Тандер Блафі, відкривається більша таємниця. Рагауро приймає торбу від імені Маґати Ґрімтотем — матріархині клану Ґрімтотем. Маур служив Маґаті, і до неї дійшла чутка, що перед смертю він знайшов щось дивне в печерах під Оргріммаром; Маґата навмисно призначила винагороду за цілу торбу, а це свідчить, що верхівка Ґрімтотемів мала навмисні, таємні інтереси в Проваллі, яке заполонили троги."}},faq={{q="Де знайти Сумку Ґрімтотемів?",a="Сумку знаходять глибоко в Проваллі Лютого Вогню — вулканічній печері під Оргріммаром. Вона під тілом Маура Ґрімтотема, затиснута в його руках там, де він поліг від трогів.",al={"місце сумки","де сумка","як знайти сумку"}},{q="Кому належить сумка?",a="Вона належала Мауру Ґрімтотему з клану Ґрімтотемів, що спустився в Провалля Лютого Вогню. Навіть мертвий, він міцно обіймав сумку, захищаючи її вміст від трогів.",al={"чия сумка","власник сумки маура"}},{q="Хто хоче повернути сумку?",a="Сумку доставляють Рагауро на Узвишшя Старійшин у Тандер Блафі. Рагауро приймає її з прямого наказу Маґати Ґрімтотем, яка призначила винагороду тому, хто поверне речі її загиблого родича.",al={"кому віддати сумку","хто здає сумку","хто хоче сумку ґрімтотемів"}},{q="Навіщо Ґрімтотем носив це під Оргріммаром?",a="Маур Ґрімтотем служив Маґаті Ґрімтотем, яка зацікавилася Проваллям Лютого Вогню. Він спустився в провалля поговорити з трогами й знайшов там щось дивне, але так і не вибрався, щоб показати їй, що саме.",al={"чому маур був у вогняній безодні","що ґрімтотем робив в оргріммарі"}},{q="Що в сумці?",a="Що саме всередині, лишається таємницею: сумку запечатаною передають просто Рагауро в Тандер Блафі. Маґата сподівається знайти в ній сліди того дивного, що Маур відшукав у проваллі.",al={"вміст сумки","що в сумці"}}},fp="17,385,12.406.0,26.490.1,37.200.0,31.211.0,31.217.0,50.222.0,27.180.0"}
P.entries["item:grizzled-bear-heart"] = {n="Серце Сивого Ведмедя",s="Серце Сивого Ведмедя — біологічний реагент, який добувають із кремезних ведмедів Срібнолісся. Це важливий складник похмурих досліджень Королівського Аптекарського Товариства над Новою Чумою.",h="Серце Сивого Ведмедя — біологічний реагент, який добувають із кремезних ведмедів Срібнолісся.",kw={"серце сивого ведмедя","нова чума","аптекар ренферрел","головний аптекар фаранелл","старий лещатощелеп","срібнолісся","ведмеді"},ang={["class:Hunter"]="Велетенські ведмеді Срібнолісся — небезпечна здобич, і вистежувати таких звірів, як Старий Лещатощелеп, заради біологічних зразків — це перевірка вашого терпіння й уміння вправно розібрати тушу.",["race:Undead"]="Для Відступників ці органи — пряма допомога Головному Аптекареві Фаранеллу у створенні найдосконалішої зброї і проти Погибелі Артаса, і проти живих смертних, що загрожують Лордерону."},sec={{t="Реагент для Нової Чуми",b="Королівське Аптекарське Товариство невтомно працює над штучною заразою, здатною винищити і Погибель, і живих людей. У лісах Срібнолісся Аптекар Ренферрел з'ясував, що особлива отрута з серця сивого ведмедя в поєднанні з павучою сукровицею дає надзвичайно смертоносну суміш. Гінці й вірні Відступники вистежують лютих сивих ведмедів, велетенських сивих ведмедів і горезвісного звіра на ім'я Старий Лещатощелеп, щоб вирізати ці органи й доправити їх просто Головному Аптекареві Фаранеллу глибоко в Апотекаріумі Андерсіті."}},faq={{q="Для чого потрібне Серце Сивого Ведмедя?",a="Серця сивих ведмедів добувають як експериментальні реагенти для Королівського Аптекарського Товариства. Аптекар Ренферрел з'ясував, що отрути з цих сердець можна перегнати на смертоносний еліксир, — це частина зусиль Відступників створити Нову Чуму.",al={"що робить серце ведмедя","завдання серце ведмедя","рецепт смерті реагенти"}},{q="Кому потрібні ці ведмежі серця?",a="Аптекар Ренферрел у Срібноліссі посилає мандрівників зібрати серця разом із Метушливою Кров'ю й доставити їх просто Головному Аптекареві Фаранеллу в Апотекаріум Андерсіті.",al={"кому потрібне серце ведмедя","фараннел серце ведмедя","кому віддати серце ведмедя"}},{q="Звідки беруться Серця Сивого Ведмедя?",a="Їх вирізають із різних сивих ведмедів, що блукають Срібноліссям, — лютих і велетенських сивих ведмедів і грізного бродячого звіра Старого Лещатощелепа.",al={"де знайти ведмежі серця","які ведмеді дропають серце","місце серця ведмедя"}},{q="Навіщо Королівському Аптекарському Товариству природні звірині отрути?",a="Товариство шукає сильні живі складники, здатні отруїти й знищити як живу плоть, так і тіла нежиті. Особливі хімічні властивості серцевої тканини міцних ведмедів Срібнолісся дають ідеальну реактивну основу в суміші з лютою павучою кров'ю.",al={"чому аптекарі використовують ведмежу отруту","навіщо серця тварин для чуми"}}},fp="19,204,28.603.0,39.256.0,28.196.0,40.178.0,65.281.0"}
P.entries["item:grizzled-scalp"] = {n="Сивий Скальп",s="Сивий Скальп — густа хутряна шкура сивих будякових ведмедів, що блукають південними лісами Темного Узбережжя. Трофей начебто дивний, але цих шкур шукає ексцентричний гном-майстер Візбанґ Кранктоґґл, щоб постачати свої заховані в нетрях механізми.",h="Сивий Скальп — густа хутряна шкура сивих будякових ведмедів, що блукають південними лісами Темного Узбережжя.",kw={"сивий скальп","будякові ведмеді","візбанґ кранктоґґл","дзижчалка","пиво","темне узбережжя"},ang={["profession:Engineering"]="Мережа дзижчалок показує гномський хист маскувати автоматичні пивоварні під польові пристрої зв'язку.",["race:NightElf"]="Нічні ельфи бережуть звірів Темного Узбережжя й неприхильно дивляться і на безглузде браконьєрство, і на потаємні гномські самогонні апарати, що захаращують їхні ліси."},sec={{t="Дивне бродіння",b="Мандрівники, що полюють уздовж дороги на південь від Обердайна, натрапляють на старих сивих будякових ведмедів, відомих своїм грубим, густим хутром. Обдирати небезпечних хижаків для лісових мисливців — звична справа, та коли чотири скальпи приносять до Дзижчалки 525, з'ясовується куди менш шляхетна мета. Пристрою не потрібне ведмеже хутро ні для ремонту, ні для наукового аналізу. Насправді гном Візбанґ Кранктоґґл використовує розкидані Темним Узбережжям потаємні дзижчалки як підпільні винокурні. Місцеві нічні ельфи косо дивляться на незаконне пивоваріння у своїх поселеннях, тож Візбанґ покладається на довірливих шукачів пригод, які збирають ведмежі скальпи та інші химерні інгредієнти для його улюбленого «будякового ведмежого пива»."}},faq={{q="Де знайти Сиві Скальпи?",a="Сиві Скальпи здобувають із сивих будякових ведмедів та їхньої матріархині, Матері Лігва, у лісах на південь від Обердайна вздовж головної стежки Темного Узбережжя.",al={"місце сивого скальпа","хто дропає сиві скальпи","скальп ведмедя будяка"}},{q="Для чого потрібні Сиві Скальпи?",a="Їх кладуть у Дзижчальну Скриньку 525 — автоматичний механічний пристрій, захований у кущах при дорозі далеко на південь від Обердайна.",al={"використання сивого скальпа","що робити із сивими скальпами"}},{q="Навіщо Дзижчальній Скриньці 525 ведмежі скальпи?",a="Візбанґ Кранктоґґл потай використовує мережу своїх скриньок, щоб гнати підпільну випивку подалі від пильних очей нічних ельфів. Сиві скальпи — складник його саморобного пива з будякових ведмедів.",al={"навіщо візбанґу скальпи","призначення дзижчальної скриньки 525"}},{q="Чому Візбанґ ховає своє пивоваріння в нетрях Темного Узбережжя?",a="Нічним ельфам в Обердайні не до вподоби галаслива незаконна торгівля трунком у їхніх священних гаях. Візбанґ сховав свої пристрої в чагарниках при глухих дорогах, щоб його самогонна справа йшла непоміченою.",al={"чому візбанґ ховає скриньку","випивка візбанґа темне узбережжя"}}},fp="14,268,23.726.1,33.162.0,34.133.0,38.194.1,60.237.1"}
P.entries["item:gryshka-s-letter"] = {n="Лист Ґришки",s="Лист Ґришки — особиста подяка від Корчмарки Гришки з Оргріммара, адресована різникові Заргу на Перехресті. Написаний після того, як вона отримала партію свіжого м'яса, лист водночас висловлює вдячність і стає приводом навчити молодих гінців Орди користуватися мережею перельотів на вітрокрилах.",h="Лист Ґришки — особиста подяка від Корчмарки Гришки з Оргріммара, адресована різникові Заргу на Перехресті.",kw={"лист ґришки","корчмарка гришка","зарг","перехрестя","дорас","вітрокрил","перельоти"},ang={["faction:Horde"]="Доставка Листа Ґришки — обряд посвяти для молодих шукачів пригод Орди: їхнє перше знайомство з мережею майстрів перельотів на вивернах, що пов'язує Дуротар і Пустки."},sec={{t="Вдячна корчмарка",b="Коли Зарг надсилає з посушливих просторів Пусток до головної таверни Оргріммара в'язку приготованих стейків, Корчмарка Гришка пише йому у відповідь цю записку. Окрім задоволення різниковою роботою, лист виказує щиру — хоч і грубувату — прихильність до Зарга: Гришка пригадує кумедні пригоди, як-от той раз, коли він відтяв собі палець, розбираючи м'ясо. Наостанок вона з ніжною усмішкою зауважує, що він гарний навіть тоді, коли забризканий кров'ю від своєї роботи."},{t="Гонець на шляхах перельотів",b="Лист Ґришки дає мандрівникам практичний урок логістики Орди. Щоб доставити пергамент на Перехрестя, шукачам пригод велять звернутися до Дораса, господаря вітрокрилів, чиє сідало — на верхньому плато Оргріммара. Переконавшись, що мандрівник уже відмітився в Деврака на Перехресті, Дорас знайомить новачків-гінців зі шляхами перельотів на вивернах, що пов'язують поселення Дуротару й Пусток."}},faq={{q="Хто написав Лист Ґришки?",a="Лист написала Корчмарка Гришка, що тримає гамірну таверну в Долині Сили в Оргріммарі, отримавши поставку свіжого м'яса.",al={"хто написав лист","автор листа ґришки","відправник"}},{q="Кому призначено лист?",a="Лист адресовано Заргові — різникові з Перехрестя в Пустках, що постачав Гришці м'ясо.",al={"адресат","кому лист ґришки","куди лист"}},{q="Що написано в листі?",a="Гришка дякує різникові за добірне м'ясо, грайливо згадує випадок, коли він на роботі втратив палець, і жартує, що він чарівний навіть тоді, коли стікає кров'ю.",al={"текст листа","що каже ґришка","зміст листа"}},{q="Чому лист треба показати Дорасу?",a="Дорас — майстер вітрокрилів Оргріммара. Гришка посилає вас до нього, щоб замовити переліт на виверні назад до Перехрестя, — так ви дізнаєтеся, як працюють повітряні шляхи Орди.",al={"чому показати дорасу","дорас майстер вітрокрилів","майстер польотів оргріммар"}}},fp="16,325,20.483.0,30.447.0,27.149.0,31.118.0,34.181.0,38.174.0"}
P.entries["item:gunther-s-spellbook"] = {n="Книга Заклять Ґюнтера",s="Книга Заклять Ґюнтера — особистий том таємної магії, що належить Ґунтерові Арканусу, колишньому чарівникові Кірін-Тору, який мешкає на Галявинах Тірісфалю. Наділена чарами Бетора Айсшарда, книга слугує Ґунтерові доказом, що іншим магам також вдалося вирватися з-під влади Короля-Ліча.",h="Книга Заклять Ґюнтера — особистий том таємної магії, що належить Ґунтерові Арканусу, колишньому чарівникові...",kw={"книга заклять ґюнтера","ґунтер арканус","бетор айсшард","кірін-тор","даларан","маг"},ang={["class:Mage"]="Для тих, хто практикує таємну магію, том уособлює спільне даларанське коріння, що пов'язує нинішній магічний провід Відступників з бунтівними чародіями в глушині.",["race:Undead"]="Зачарована книга підкреслює невпинні зусилля Відступників залучати могутню незалежну нежить, що сама вирвалася з-під влади Короля-Ліча."},sec={{t="Знак давнього братства",b="До Третьої війни Ґунтер Арканус вивчав таємні мистецтва в Даларані разом із Бетором Айсшардом і Тулом Рейвенкловом як члени Кірін-Тору. Коли Чума Нежиті прокотилася Лордероном, Ґунтер загинув і був піднятий у нежитті, та зрештою зумів вирвати свій розум з-під влади Погибелі. Вважаючи себе самотнім і невпинно переслідуваним агентами, яких шле Король-Ліч, він лишався глибоко ворожим до чужинців. Коли том здобули, Бетор Айсшард наклав на його сторінки таємні чари — свідомий магічний підпис, що дає Ґунтерові змогу розпізнати присутність Бетора й зрозуміти: він не єдиний маг, який має вільну волю."}},faq={{q="Чия це книга заклять?",a="Вона належить Ґунтерові Арканусу — могутньому магові-нежиті, що живе на відлюдному острові посеред Озера Світлої Води в Галявинах Тірісфалю.",al={"чия книга","власник книги ґунтера","власник книги заклять"}},{q="Чому Бетор зачарував книгу заклять?",a="Бетор наклав на том власні чари як незаперечний доказ того, що він живий у Лордероні й вільний від влади Короля-Ліча, — сподіваючись переконати Ґунтера приєднатися до Відступників.",al={"чому зачарувати книгу","закляття бетора на книзі","магія книги"}},{q="Чому Ґунтер стає підозріливим, коли йому повертають книгу?",a="Ґунтер вважає, що кожен, хто наближається до його сховку, — агент Погибелі, посланий знову його поневолити, і спершу думає, що шукач пригод і є тим злодієм, що вкрав його том.",al={"чому ґунтер злий","ґунтер сердитий","ґунтер ворожий"}},{q="Звідки Ґунтер і Бетор знають одне одного?",a="Колись давно Ґунтер, Бетор Айсшард і Тул Рейвенклов були друзями й разом вивчали магію як учні Кірін-Тору в місті Даларан, доки їх не забрала Чума.",al={"минуле бетора й ґунтера","зв'язок з кірін-тор","друзі з даларана"}}},fp="19,288,22.651.1,24.124.0,37.199.0,52.175.0,43.167.0"}
